    private record ClassicWorldDetectionContext(
            int hiddenReveals, int trapActivations, int trapEffects) {}

    private ClassicWorldDetectionContext applyClassicWorldDetectionContext(
            int mapId, int instanceId, int casterX, int casterY,
            String reason) throws IOException {
        List<ClassicWorldMonsterPopulation.Reveal> reveals =
                hub.revealClassicWorldSinkMonsters(
                        mapId, instanceId, casterX, casterY, playerObjectId());
        List<ClientSession> mapMembers = hub.classicWorldMembers(
                mapId, instanceId);
        for (ClassicWorldMonsterPopulation.Reveal reveal : reveals) {
            for (ClientSession member : mapMembers) {
                member.serverClassicWorldMonsterRevealed(reveal, reason);
            }
        }

        ClassicWorldTrapPopulation.Detection traps =
                hub.detectClassicWorldTraps(
                        mapId, instanceId, casterX, casterY,
                        System.nanoTime());
        for (ClassicWorldTrapPopulation.Snapshot trap : traps.effects()) {
            byte[] effect = Protocol.effectLocation(
                    trap.x(), trap.y(), trap.gfxId());
            for (ClientSession member : mapMembers) {
                if (member.phase != Phase.WORLD
                        || member.classicWorldMapId != mapId
                        || member.classicWorldInstanceId != instanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                trap.x(), trap.y())) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT_LOC WorldTrap spawn=" + trap.spawnId()
                                + " slot=" + trap.spawnNumber()
                                + " trap=" + trap.trapId()
                                + " gfx=" + trap.gfxId()
                                + " reason=" + reason);
            }
        }
        return new ClassicWorldDetectionContext(
                reveals.size(), traps.activated().size(),
                traps.effects().size());
    }

