    private record MindBreakTargetMpDebit(
            int requested, int before, int after,
            boolean debited, String kind) {
        MindBreakTargetMpDebit {
            if (requested < 5 || requested > 50 || before < 0 || after < 0
                    || after > before || kind == null || kind.isBlank()
                    || debited != (before > requested
                        && before - after == requested)
                    || !debited && before != after) {
                throw new IllegalArgumentException(
                        "invalid Mind Break target MP debit");
            }
        }

        static MindBreakTargetMpDebit unavailable(
                int requested, String kind) {
            return new MindBreakTargetMpDebit(
                    requested, 0, 0, false, kind);
        }
    }
