    private void applyClassicWorldWaterDragonSaellBlessing(
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        long now = System.nanoTime();
        if (classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) > 5
                || waterDragonBlessingActive(now)) return;
        // Npc_Saell first removes the two mutually-exclusive dragon-world
        // blessings, then ADLV80_2 installs quest117's exact modifiers.
        storySkillEffectDeadlines.remove(4009);
        storySkillEffectDeadlines.remove(4018);
        long duration = ClassicWorldWaterDragonCatalog.WORLD_BLESSING_SECONDS
                * 1_000_000_000L;
        storySkillEffectDeadlines.put(
                ClassicWorldWaterDragonCatalog.WORLD_BLESSING_SKILL_ID,
                now > Long.MAX_VALUE - duration ? Long.MAX_VALUE : now + duration);
        byte[] effect = Protocol.effectObject(
                playerObjectId(),
                ClassicWorldWaterDragonCatalog.WORLD_BLESSING_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT Water-Dragon-Saell target=" + playerObjectId()
                                + " skill=" + ClassicWorldWaterDragonCatalog
                                        .WORLD_BLESSING_SKILL_ID
                                + " duration=" + ClassicWorldWaterDragonCatalog
                                        .WORLD_BLESSING_SECONDS);
            }
        }
        rebuildMaximumVitals(now);
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(playerHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT Water-Dragon-Saell=" + playerHp
                        + "/" + playerMaxHp);
        broadcastOwnHitRatio("Water-Dragon-Saell-max-hp");
        sendEncrypted(Protocol.manaPoint(playerMp, playerMaxMp),
                "S_MANA_POINT Water-Dragon-Saell=" + playerMp
                        + "/" + playerMaxMp);
        sendEncrypted(ownCharacterAttrDef(),
                "S_AC Water-Dragon-Saell=" + battleArmorClass());
        sendNativeBattleStatus(now, "Water-Dragon-Saell");
    }

    private void handleClassicWorldWaterDragonGateAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        boolean context = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && classicNpcDistance(new ArenaMapCatalog.Point(
                        npc.x(), npc.y())) <= 5
                && pendingPortal == null && !hub.hasPrivateShop(this);
        if (!context) return;
        if (request.action().equalsIgnoreCase("1")) {
            rentClassicWorldWaterDragonPass(npc);
            return;
        }
        if (!request.action().equalsIgnoreCase("0")) return;

        long now = System.nanoTime();
        Set<Long> passObjects = inventory.items().stream()
                .filter(item -> item.definition().catalogId()
                        == ClassicWorldWaterDragonCatalog.PASS_ITEM_ID)
                .map(RuntimeInventory.Item::objectId)
                .collect(java.util.stream.Collectors.toSet());
        GameHub.WaterDragonPass pass =
                hub.classicWorldWaterDragonPass(
                        selectedClassicServerName, passObjects, now);
        boolean cooldown = activeStorySkillEffect(
                ClassicWorldWaterDragonCatalog.WATER_DRAGON_BLOOD_SKILL_ID,
                now);
        ClassicWorldWaterDragonInstances.Admission admission =
                hub.admitClassicWorldWaterDragon(
                        this, pass == null ? -1 : pass.showId(),
                        pass != null, cooldown, now);
        if (!admission.admitted()) {
            if (admission.status()
                    == ClassicWorldWaterDragonInstances.AdmissionStatus.REENTRY_DENIED) {
                long penalty = ClassicWorldWaterDragonCatalog
                        .REENTRY_PENALTY_SECONDS * 1_000_000_000L;
                state.saveWaterDragonBlood(
                        stateCharacter(), ClassicWorldWaterDragonCatalog
                                .REENTRY_PENALTY_SECONDS);
                storySkillEffectDeadlines.put(
                        ClassicWorldWaterDragonCatalog.WATER_DRAGON_BLOOD_SKILL_ID,
                        now > Long.MAX_VALUE - penalty
                                ? Long.MAX_VALUE : now + penalty);
                sendEncrypted(Protocol.effectObject(
                                playerObjectId(),
                                ClassicWorldWaterDragonCatalog.COMPLETION_GFX),
                        "S_EFFECT Water-Dragon-reentry-penalty skill="
                                + ClassicWorldWaterDragonCatalog
                                        .WATER_DRAGON_BLOOD_SKILL_ID);
                sendEncrypted(Protocol.systemMessage(
                                9, "逃離副本後無法再進入"),
                        "S_SYSTEM_MESSAGE Water-Dragon-reentry-denied");
            } else if (admission.status()
                    == ClassicWorldWaterDragonInstances.AdmissionStatus.LEVEL_TOO_LOW) {
                sendEncrypted(Protocol.systemMessage(
                                9, "等級未滿60級，無法進入"),
                        "S_SYSTEM_MESSAGE Water-Dragon-level");
            } else if (admission.status()
                    == ClassicWorldWaterDragonInstances.AdmissionStatus.COOLDOWN_ACTIVE) {
                sendEncrypted(Protocol.messageCode(1626),
                        "S_MESSAGE_CODE Water-Dragon-cooldown=1626");
            } else if (admission.status()
                    == ClassicWorldWaterDragonInstances.AdmissionStatus.CAPACITY_REACHED) {
                sendEncrypted(Protocol.systemMessage(
                                9, "已達進入人數上限，無法進入"),
                        "S_SYSTEM_MESSAGE Water-Dragon-capacity");
            } else {
                sendEncrypted(Protocol.systemMessage(
                                9, "身上必須要有龍門憑證才可以進入。"),
                        "S_SYSTEM_MESSAGE Water-Dragon-credential");
            }
            return;
        }

        ClassicWorldWaterDragonCatalog.Location entry =
                ClassicWorldWaterDragonCatalog.ENTRY;
        if (!ClassicWorldMapCatalog.forMap(entry.mapId())
                .standingPassable(entry.x(), entry.y())) {
            hub.rollbackClassicWorldWaterDragonAdmission(this, admission);
            throw new IOException("Water Dragon entry is not passable");
        }
        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                entry.mapId(), entry.x(), entry.y(), true);
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, entry.heading(), 0,
                "Water-Dragon-entry-show-" + admission.showId(),
                admission.showId());
        pendingPortal = destination;
        pendingPortalReady = true;
        sendEncrypted(Protocol.portal(
                        destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL Water-Dragon-entry show=" + admission.showId()
                        + " destination=" + destination.mapId() + ":"
                        + destination.x() + "," + destination.y());
    }

    private void rentClassicWorldWaterDragonPass(
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        long nowEpochSeconds = state.currentEpochSeconds();
        long nowEpochMillis = Math.multiplyExact(nowEpochSeconds, 1_000L);
        Set<Long> stalePassObjectIds = inventory.items().stream()
                .filter(item -> item.definition().catalogId()
                        == ClassicWorldWaterDragonCatalog.PASS_ITEM_ID)
                .filter(item -> item.expiresAtEpochMillis() <= nowEpochMillis)
                .map(RuntimeInventory.Item::objectId)
                .collect(java.util.stream.Collectors.toCollection(
                        LinkedHashSet::new));
        boolean activePass = inventory.items().stream()
                .anyMatch(item -> item.definition().catalogId()
                        == ClassicWorldWaterDragonCatalog.PASS_ITEM_ID
                        && item.expiresAtEpochMillis() > nowEpochMillis);
        if (activePass) {
            sendEncrypted(Protocol.hypertext(
                            npc.objectId(), "y_n_dragon6", "", List.of()),
                    "S_HYPERTEXT Water-Dragon-pass already-rented");
            return;
        }
        if (hub.classicWorldWaterDragonRentedRooms(
                    selectedClassicServerName, System.nanoTime())
                >= ClassicWorldWaterDragonCatalog.ROOM_COUNT) {
            sendEncrypted(Protocol.hypertext(
                            npc.objectId(), "y_n_dragon3", "", List.of()),
                    "S_HYPERTEXT Water-Dragon-pass rooms-full");
            return;
        }
        long price = Math.multiplyExact(
                (long) ClassicWorldWaterDragonCatalog.PASS_PRICE,
                ClassicWorldWaterDragonCatalog.PASS_RENTAL_COUNT);
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.withoutObjects(stalePassObjectIds);
        InventoryCatalog.Definition passDefinition = InventoryCatalog.require(
                ClassicWorldWaterDragonCatalog.PASS_ITEM_ID);
        if (!next.removeCatalog(
                ClassicWorldWaterDragonCatalog.ADENA_ITEM_ID, price)) {
            sendEncrypted(Protocol.hypertext(
                            npc.objectId(), "y_n_dragon5", "", List.of()),
                    "S_HYPERTEXT Water-Dragon-pass insufficient-adena");
            return;
        }
        long expiresAtEpochSeconds = Math.addExact(nowEpochSeconds,
                ClassicWorldWaterDragonCatalog.PASS_RENTAL_SECONDS);
        long expiresAtEpochMillis = Math.multiplyExact(
                expiresAtEpochSeconds, 1_000L);
        RuntimeInventory.PersistentItem passState =
                new RuntimeInventory.PersistentItem(
                        0, ClassicWorldWaterDragonCatalog.PASS_RENTAL_COUNT,
                        0, 0, passDefinition.identified(), passDefinition.blessing(),
                        false, false, false, null,
                        passDefinition.initialChargeCount(),
                        expiresAtEpochMillis, false, false);
        if (!permitsInventoryAddition(next, passDefinition,
                    ClassicWorldWaterDragonCatalog.PASS_RENTAL_COUNT)) {
            return;
        }
        long passObjectId = next.addDistinctState(passDefinition, passState);
        if (passObjectId == 0) return;
        RuntimeInventory.Item passItem = next.item(passObjectId);
        if (passItem == null) {
            throw new IOException("Water Dragon pass allocation vanished");
        }
        GameHub.WaterDragonPass pass = hub.rentClassicWorldWaterDragonPass(
                selectedClassicServerName, this, passItem.objectId(),
                System.nanoTime());
        if (pass == null) return;
        GameStateStore.WaterDragonPassState durablePass =
                new GameStateStore.WaterDragonPassState(
                        selectedClassicServerName, pass.itemObjectId(), pass.showId(),
                        pass.roomNumber(), pass.renterIdentity(),
                        expiresAtEpochSeconds);
        boolean sqlAuthoritative = sqlPrivateInventorySnapshot.authoritative();
        if (sqlAuthoritative) {
            try {
                persistSqlWorldInventory(next,
                        new RepositoryWaterDragonPassChange(durablePass));
            } catch (IOException | RuntimeException failure) {
                hub.cancelClassicWorldWaterDragonPass(
                        selectedClassicServerName, passItem.objectId());
                throw failure;
            }
        }
        try {
            state.saveEconomyStateAndWaterDragonPass(
                    selectedClassicServerName, stateCharacter(), shopPoints,
                    next.catalogCounts(), next.catalogItemStates(),
                    pass.itemObjectId(), pass.showId(), pass.roomNumber(),
                    pass.renterIdentity(), expiresAtEpochSeconds);
        } catch (IOException | RuntimeException failure) {
            if (!sqlAuthoritative) {
                hub.cancelClassicWorldWaterDragonPass(
                        selectedClassicServerName, passItem.objectId());
                throw failure;
            }
            System.err.println("[LiTo] Water Dragon sidecar mirror failed after SQL "
                    + "commit source=" + selectedClassicServerName + " player="
                    + playerName() + " error=" + failure.getMessage());
        }
        inventory = next;
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.messageCode(
                        143, npc.nameId(), passItem.nativeViewName()),
                "S_MESSAGE_CODE Water-Dragon-pass=143 room="
                        + pass.roomNumber() + " show=" + pass.showId()
                        + " count=" + passItem.quantity());
        sendEncrypted(Protocol.hypertext(
                        npc.objectId(), "y_n_dragon2", "", List.of()),
                "S_HYPERTEXT Water-Dragon-pass rented room="
                        + pass.roomNumber());
    }

    private RepositoryHouseTaxQuote classicWorldHouseTaxQuote(
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null || npc == null || !npc.housekeeper()) {
            return new RepositoryHouseTaxQuote(
                    RepositoryHouseTaxQuoteStatus.NOT_FOUND,
                    null, npc == null ? 0 : npc.npcId(), 0, "", "");
        }
        try {
            RepositoryHouseTaxQuote quote = selectedSourceAccounts()
                    .houseTaxQuote(character.objectId(), npc.npcId());
            if (quote.status() == RepositoryHouseTaxQuoteStatus.UNAVAILABLE
                    && "lito_mysql".equals(config.databaseMode())) {
                throw new IOException(
                        "selected LiTo house-tax quote is unavailable");
            }
            return quote;
        } catch (IOException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IOException("cannot read selected-source house tax", failure);
        }
    }

    private void openClassicWorldHousekeeper(
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        if (classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) > 5) {
            return;
        }
        RepositoryHouseTaxQuote quote = classicWorldHouseTaxQuote(npc);
        String html;
        List<String> arguments;
        switch (quote.status()) {
            case MEMBER -> {
                html = npc.initialHtml(characterLawful());
                arguments = List.of();
            }
            case OCCUPIED -> {
                html = "agname";
                arguments = List.of(
                        quote.ownerClanName(), quote.ownerLeaderName(),
                        quote.house().name());
            }
            case VACANT -> {
                html = "agnoname";
                arguments = List.of(quote.house().name());
            }
            default -> {
                System.out.println("[LiTo] C_DIALOG housekeeper refused source="
                        + selectedClassicServerName + " npc=" + npc.npcId()
                        + " status=" + quote.status());
                return;
            }
        }
        if (html == null || html.isBlank()) {
            throw new IOException("retained housekeeper has no initial HTML");
        }
        sendEncrypted(Protocol.hypertext(npc.objectId(), html, "", arguments),
                "S_HYPERTEXT housekeeper=" + npc.npcId() + " html=" + html
                        + " status=" + quote.status());
    }

    private void handleClassicWorldHousekeeperAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        boolean context = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && classicNpcDistance(new ArenaMapCatalog.Point(
                        npc.x(), npc.y())) <= 5
                && pendingPortal == null && !hub.hasPrivateShop(this);
        if (!context) {
            System.out.println("[LiTo] C_HACTION housekeeper rejected context npc="
                    + npc.npcId() + " action=" + request.action());
            return;
        }
        if (request.action().equalsIgnoreCase("pay")) {
            RepositoryHouseTaxQuote quote = classicWorldHouseTaxQuote(npc);
            if (!quote.member()) return;
            ZonedDateTime deadline = Instant.ofEpochSecond(
                    quote.house().taxDeadlineEpochSeconds())
                    .atZone(CLASSIC_BOARD_ZONE);
            sendEncrypted(Protocol.hypertext(
                            npc.objectId(), "agpay", "",
                            List.of(npc.nameId(),
                                    Integer.toString(HOUSE_TAX_ADENA),
                                    Integer.toString(deadline.getMonthValue()),
                                    Integer.toString(deadline.getDayOfMonth()),
                                    Integer.toString(deadline.getHour()))),
                    "S_HYPERTEXT house-tax quote npc=" + npc.npcId()
                            + " house=" + quote.house().houseId()
                            + " deadline="
                            + quote.house().taxDeadlineEpochSeconds());
            return;
        }
        if (!request.action().equalsIgnoreCase("payfee")) {
            System.out.println("[LiTo] C_HACTION housekeeper deferred npc="
                    + npc.npcId() + " action=" + request.action());
            return;
        }
        payClassicWorldHouseTax(npc);
    }

    private void payClassicWorldHouseTax(
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        RepositoryHouseTaxQuote expected = classicWorldHouseTaxQuote(npc);
        if (!expected.member()) return;
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        if (!next.removeCatalog(InventoryCatalog.ADENA, HOUSE_TAX_ADENA)) {
            sendEncrypted(Protocol.messageCode(189),
                    "S_MESSAGE_CODE house-tax-insufficient-adena=189 required="
                            + HOUSE_TAX_ADENA);
            return;
        }
        CharacterSummary character = selectedCharacterSummary();
        if (character == null) return;
        try {
            Map<Long, Long> localToSource = state.sourceInventoryBindings(
                    stateCharacter()).stream().collect(
                            java.util.stream.Collectors.toMap(
                                    GameStateStore.SourceInventoryBinding::localObjectId,
                                    GameStateStore.SourceInventoryBinding::sourceObjectId,
                                    (left, right) -> left, LinkedHashMap::new));
            RepositoryHouseTaxPayment payment = selectedSourceAccounts()
                    .persistHouseTaxPayment(
                            character.objectId(), expected,
                            Instant.now().getEpochSecond(),
                            HOUSE_TAX_INTERVAL_DAYS, HOUSE_TAX_ADENA,
                            previous, next, localToSource);
            if (!payment.paid()) {
                System.out.println("[LiTo] SQL house-tax payment refused source="
                        + selectedClassicServerName + " npc=" + npc.npcId()
                        + " house=" + expected.house().houseId()
                        + " status=" + payment.status());
                return;
            }
            inventory = next;
            // SQL is authoritative; this remains a restart/debug economy mirror.
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
            sendInventoryDelta(previous, inventory);
            sendEncrypted(Protocol.closeHypertext(npc.objectId()),
                    "S_HYPERTEXT_CLOSE house-tax paid npc=" + npc.npcId()
                            + " house=" + payment.quote().house().houseId()
                            + " deadline="
                            + payment.quote().house().taxDeadlineEpochSeconds());
        } catch (IOException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IOException("cannot pay selected-source house tax", failure);
        }
    }

    /** Exact retained C_NPCAction room/hall/return/enter dispatcher. */
    private void handleClassicWorldHotelAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        boolean context = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) <= 5
                && pendingPortal == null && !hub.hasPrivateShop(this);
        if (!context) {
            System.out.println("[LiTo] C_HACTION hotel rejected npc=" + npc.npcId()
                    + " action=" + request.action() + " result=context");
            return;
        }
        String action = request.action().toLowerCase(Locale.ROOT);
        switch (action) {
            case ClassicWorldHotelCatalog.ROOM_ACTION ->
                    openClassicWorldHotelRental(npc, false);
            case ClassicWorldHotelCatalog.HALL_ACTION -> {
                if (selectedCharacterType()
                        != ClassicWorldHotelCatalog.CROWN_CHARACTER_TYPE) {
                    sendHotelHypertext(npc,
                            ClassicWorldHotelCatalog.HALL_CROWN_ONLY_HTML,
                            List.of(), "hall-crown-only");
                } else {
                    openClassicWorldHotelRental(npc, true);
                }
            }
            case ClassicWorldHotelCatalog.RETURN_ACTION ->
                    returnClassicWorldHotelKeys(npc);
            case ClassicWorldHotelCatalog.ENTER_ACTION ->
                    enterClassicWorldHotel(npc);
            default -> System.out.println("[LiTo] C_HACTION hotel deferred npc="
                    + npc.npcId() + " action=" + request.action());
        }
    }

    private void openClassicWorldHotelRental(
            ClassicWorldNpcCatalog.StaticNpc npc, boolean meetingHall)
            throws IOException {
        Set<Long> keyObjects = hotelInventoryObjectIds();
        GameStateStore.HotelOccupancy occupancy = hotelOccupancy(
                npc.npcId(), sourceCharacterIdentity());
        GameStateStore.HotelLeaseState blockingLease = occupancy.renterLease();
        if (blockingLease == null && !keyObjects.isEmpty()) {
            blockingLease = activeHotelLeaseForAnyInn(keyObjects);
        }
        if (occupancy.renterLease() != null || !keyObjects.isEmpty()) {
            sendHotelHypertext(npc,
                    blockingLease != null && blockingLease.meetingHall()
                            ? ClassicWorldHotelCatalog.ALREADY_HALL_HTML
                            : ClassicWorldHotelCatalog.ALREADY_ROOM_HTML,
                    List.of(), "already-rented");
            return;
        }
        if (!meetingHall && occupancy.activeRooms()
                >= ClassicWorldHotelCatalog.ROOM_CAPACITY) {
            sendHotelHypertext(npc, ClassicWorldHotelCatalog.ROOMS_FULL_HTML,
                    List.of(), "rooms-full");
            return;
        }
        if (meetingHall && occupancy.activeHalls()
                >= ClassicWorldHotelCatalog.HALL_CAPACITY) {
            sendHotelHypertext(npc, ClassicWorldHotelCatalog.HALLS_FULL_HTML,
                    List.of(), "halls-full");
            return;
        }
        if (occupancy.firstFreeSlot() < 0) {
            sendHotelHypertext(npc, meetingHall
                            ? ClassicWorldHotelCatalog.HALLS_FULL_HTML
                            : ClassicWorldHotelCatalog.ROOMS_FULL_HTML,
                    List.of(), "lease-pool-full");
            return;
        }

        int maximum = ClassicWorldHotelCatalog.maximumKeys(meetingHall);
        int mode = 0;
        String callback = "";
        pendingHotelRental = new PendingHotelRental(
                npc.objectId(), classicWorldMapId, npc.npcId(), meetingHall,
                maximum, mode, callback,
                System.nanoTime() + HOTEL_RENTAL_CONTEXT_TIMEOUT_NANOS);
        sendEncrypted(Protocol.hypertextInput(
                        npc.objectId(), ClassicWorldHotelCatalog.PRICE_PER_KEY,
                        1, 1, maximum, mode,
                        ClassicWorldHotelCatalog.inputHtml(meetingHall), "", callback,
                        List.of(npc.nameId(), Integer.toString(
                                ClassicWorldHotelCatalog.PRICE_PER_KEY))),
                "S_HYPERTEXT_INPUT hotel npc=" + npc.npcId()
                        + " hall=" + meetingHall + " price="
                        + ClassicWorldHotelCatalog.PRICE_PER_KEY
                        + " minimum=1 maximum=" + maximum);
    }

    private void performClassicWorldHotelRental(
            PendingHotelRental pending, int amount,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        Set<Long> existingKeys = hotelInventoryObjectIds();
        if (!existingKeys.isEmpty()) {
            GameStateStore.HotelLeaseState blocking =
                    activeHotelLeaseForAnyInn(existingKeys);
            sendHotelHypertext(npc,
                    blocking != null && blocking.meetingHall()
                            ? ClassicWorldHotelCatalog.ALREADY_HALL_HTML
                            : ClassicWorldHotelCatalog.ALREADY_ROOM_HTML,
                    List.of(), "rental-race-existing-key");
            return;
        }
        long price = Math.multiplyExact(
                (long) ClassicWorldHotelCatalog.PRICE_PER_KEY, amount);
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        if (!next.removeCatalog(ClassicWorldHotelCatalog.ADENA_ITEM_ID, price)) {
            sendHotelHypertext(npc, ClassicWorldHotelCatalog.INSUFFICIENT_ADENA_HTML,
                    List.of(npc.nameId()), "insufficient-adena");
            return;
        }
        InventoryCatalog.Definition keyDefinition = InventoryCatalog.require(
                ClassicWorldHotelCatalog.KEY_ITEM_ID);
        if (!permitsInventoryAddition(next, keyDefinition, amount)) {
            sendInventoryWeightOver("hotel-rental");
            return;
        }
        long keyExpiryMillis = Math.multiplyExact(
                Math.addExact(Instant.now().getEpochSecond(),
                        ClassicWorldHotelCatalog.LEASE_SECONDS), 1_000L);
        for (int index = 0; index < amount; index++) {
            RuntimeInventory.PersistentItem keyState = new RuntimeInventory.PersistentItem(
                    0, 1, 0, 0, keyDefinition.identified(), keyDefinition.blessing(),
                    false, false, false, null, keyDefinition.initialChargeCount(),
                    keyExpiryMillis, false, false);
            if (next.addDistinctState(keyDefinition, keyState) == 0) {
                sendInventoryCapacityOver("hotel-rental");
                return;
            }
        }
        List<RuntimeInventory.Item> keyItems = next.items().stream()
                .filter(item -> item.definition().catalogId()
                        == ClassicWorldHotelCatalog.KEY_ITEM_ID)
                .toList();
        List<Long> keyObjectIds = keyItems.stream()
                .map(RuntimeInventory.Item::objectId).toList();
        if (keyObjectIds.size() != amount) {
            throw new IOException("hotel key allocation count changed");
        }
        GameStateStore.HotelRentMutation mutation =
                state.saveEconomyStateAndHotelLease(
                        stateCharacter(), shopPoints,
                        next.catalogCounts(), next.catalogItemStates(),
                        pending.npcId(), pending.meetingHall(),
                        sourceCharacterIdentity(), keyObjectIds,
                        sqlPrivateInventorySnapshot.authoritative()
                                ? lease -> persistSqlWorldInventory(next,
                                        RepositoryHotelChange.rent(
                                                lease, keyObjectIds))
                                : null);
        if (!mutation.rented()) {
            String html = switch (mutation.status()) {
                case ALREADY_RENTED -> mutation.lease() != null
                        && mutation.lease().meetingHall()
                        ? ClassicWorldHotelCatalog.ALREADY_HALL_HTML
                        : ClassicWorldHotelCatalog.ALREADY_ROOM_HTML;
                case HALLS_FULL -> ClassicWorldHotelCatalog.HALLS_FULL_HTML;
                case ROOMS_FULL -> ClassicWorldHotelCatalog.ROOMS_FULL_HTML;
                case NO_FREE_SLOT -> pending.meetingHall()
                        ? ClassicWorldHotelCatalog.HALLS_FULL_HTML
                        : ClassicWorldHotelCatalog.ROOMS_FULL_HTML;
                case RENTED -> throw new IllegalStateException(
                        "rented hotel mutation was rejected");
            };
            sendHotelHypertext(npc, html, List.of(),
                    "rental-race-" + mutation.status());
            return;
        }

        inventory = next;
        sendInventoryDelta(previous, inventory);
        String keyName = keyItems.get(0).nativeViewName()
                + (amount > 1 ? " (" + amount + ")" : "");
        sendEncrypted(Protocol.messageCode(143, npc.nameId(), keyName),
                "S_MESSAGE_CODE hotel-key=143 npc=" + npc.npcId()
                        + " room=" + mutation.lease().roomNumber()
                        + " show=" + mutation.lease().showId()
                        + " hall=" + mutation.lease().meetingHall()
                        + " count=" + amount);
        sendHotelHypertext(npc, ClassicWorldHotelCatalog.RENTED_HTML,
                List.of(npc.nameId()), "rented");
    }

    private void returnClassicWorldHotelKeys(
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        GameStateStore.HotelReturnQuote quote = hotelReturnQuote(
                npc.npcId(), sourceCharacterIdentity(),
                hotelInventoryObjectIds());
        if (!quote.present()) return;
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.withoutObjects(
                quote.returnedKeyObjectIds());
        if (quote.refund() > 0 && !next.add(
                InventoryCatalog.require(ClassicWorldHotelCatalog.ADENA_ITEM_ID),
                quote.refund())) {
            sendInventoryCapacityOver("hotel-return");
            return;
        }
        state.saveEconomyStateAndHotelReturn(
                stateCharacter(), shopPoints,
                next.catalogCounts(), next.catalogItemStates(), quote,
                sqlPrivateInventorySnapshot.authoritative()
                        ? currentQuote -> persistSqlWorldInventory(next,
                                RepositoryHotelChange.returning(currentQuote))
                        : null);
        inventory = next;
        sendInventoryDelta(previous, inventory);
        sendHotelHypertext(npc, ClassicWorldHotelCatalog.RETURNED_HTML,
                List.of(npc.nameId(), Integer.toString(quote.refund())),
                "returned keys=" + quote.returnedKeyObjectIds().size()
                        + " lease=" + quote.releasesLease()
                        + " refund=" + quote.refund());
    }

    private void enterClassicWorldHotel(
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        GameStateStore.HotelLeaseState lease = activeHotelLeaseForInventory(
                npc.npcId(), hotelInventoryObjectIds());
        if (lease == null) return;
        ClassicWorldHotelCatalog.Inn inn =
                ClassicWorldHotelCatalog.forNpc(npc.npcId());
        ClassicWorldHotelCatalog.Location entry =
                inn.destination(lease.meetingHall());
        if (!ClassicWorldMapCatalog.forMap(entry.mapId())
                .standingPassable(entry.x(), entry.y())) {
            throw new IOException("hotel entry is not passable");
        }
        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                entry.mapId(), entry.x(), entry.y(), true);
        clearPendingClassicList();
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, entry.heading(), 0,
                "hotel-entry-npc-" + npc.npcId() + "-show-" + lease.showId(),
                lease.showId());
        pendingPortal = destination;
        pendingPortalReady = true;
        sendEncrypted(Protocol.portal(
                        destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL hotel-entry npc=" + npc.npcId()
                        + " hall=" + lease.meetingHall()
                        + " show=" + lease.showId()
                        + " destination=" + destination.mapId() + ":"
                        + destination.x() + "," + destination.y());
    }

    private Set<Long> hotelInventoryObjectIds() {
        LinkedHashSet<Long> result = new LinkedHashSet<>();
        for (RuntimeInventory.Item item : inventory.items()) {
            if (item.definition().catalogId()
                    == ClassicWorldHotelCatalog.KEY_ITEM_ID) {
                result.add(item.objectId());
            }
        }
        return Set.copyOf(result);
    }

    private GameStateStore.HotelLeaseState activeHotelLeaseForAnyInn(
            Set<Long> keyObjectIds) throws IOException {
        for (ClassicWorldHotelCatalog.Inn inn : ClassicWorldHotelCatalog.inns()) {
            GameStateStore.HotelLeaseState lease =
                    activeHotelLeaseForInventory(inn.npcId(), keyObjectIds);
            if (lease != null) return lease;
        }
        return null;
    }

    private GameStateStore.HotelOccupancy hotelOccupancy(
            int npcId, String renterIdentity) throws IOException {
        RepositoryHotelSnapshot sql = sqlHotelState();
        return sql == null
                ? state.hotelOccupancy(npcId, renterIdentity)
                : sql.occupancy(npcId, renterIdentity);
    }

    private GameStateStore.HotelLeaseState activeHotelLeaseForInventory(
            int npcId, Set<Long> objectIds) throws IOException {
        RepositoryHotelSnapshot sql = sqlHotelState();
        return sql == null
                ? state.activeHotelLeaseForInventory(npcId, objectIds)
                : sql.activeLeaseForKeys(npcId, objectIds);
    }

    private GameStateStore.HotelReturnQuote hotelReturnQuote(
            int npcId, String renterIdentity, Set<Long> objectIds)
            throws IOException {
        RepositoryHotelSnapshot sql = sqlHotelState();
        return sql == null
                ? state.hotelReturnQuote(npcId, renterIdentity, objectIds)
                : sql.returnQuote(npcId, renterIdentity, objectIds);
    }

    private RepositoryHotelSnapshot sqlHotelState() throws IOException {
        if (!sqlPrivateInventorySnapshot.authoritative()) return null;
        try {
            RepositoryHotelSnapshot snapshot = selectedSourceAccounts().hotelState();
            if (!snapshot.authoritative()) {
                throw new IOException("selected SQL source has no hotel authority");
            }
            return snapshot;
        } catch (IOException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IOException("cannot load selected-source hotel state", failure);
        }
    }

