    private void handleCastleStewardAction(
            Protocol.HypertextActionRequest request) throws IOException {
        ArenaMapCatalog.Point npc = castleStewardNpcPoint();
        if (request.kind() != Protocol.HypertextActionKind.GENERIC
                || npc == null || classicNpcDistance(npc) > 5
                || !request.parameter().isEmpty()) {
            pendingCastleAdmin = null;
            pendingMercenaryAdmin = null;
            pendingCastleSecurity = null;
            System.out.println("[LiTo] C_HACTION rejected castle-steward context action="
                    + request.action());
            return;
        }
        if (request.action().equalsIgnoreCase("tax")) {
            pendingMercenaryAdmin = null;
            pendingCastleSecurity = null;
            armCastleAdmin(CastleAdminAction.TAX);
        } else if (request.action().equalsIgnoreCase("withdrawal")) {
            pendingMercenaryAdmin = null;
            pendingCastleSecurity = null;
            armCastleAdmin(CastleAdminAction.WITHDRAW);
        } else if (request.action().equalsIgnoreCase("cdeposit")) {
            pendingMercenaryAdmin = null;
            pendingCastleSecurity = null;
            armCastleAdmin(CastleAdminAction.DEPOSIT);
        } else if (request.action().equalsIgnoreCase("employ")) {
            pendingCastleAdmin = null;
            pendingCastleSecurity = null;
            openMercenarySelection();
        } else if (request.action().equalsIgnoreCase("arrange")) {
            pendingCastleAdmin = null;
            pendingCastleSecurity = null;
            openMercenaryArrangement();
        } else if (request.action().equalsIgnoreCase("archer")) {
            pendingCastleAdmin = null;
            pendingCastleSecurity = null;
            openArcherArrangement();
        } else if (request.action().equalsIgnoreCase("inex")) {
            pendingCastleAdmin = null;
            pendingMercenaryAdmin = null;
            pendingCastleSecurity = null;
            CastleSummary castle = castleOwnerAuthority("inex");
            if (castle != null) {
                GameStateStore.CastleState snapshot = state.castle(
                        selectedClassicServerName, castle);
                sendEncrypted(Protocol.messageCode(309, castle.castleName(),
                                Long.toString(snapshot.publicMoney())),
                        "S_MESSAGE_CODE castle-information=309 castle="
                                + castle.castleId() + " public-money="
                                + snapshot.publicMoney());
            }
        } else if (request.action().equalsIgnoreCase(
                ClassicWorldWindawoodCastleCatalog.CASTLE_GATE_ACTION)
                && classicCastleSceneId() != ClassicWorldAdenToiCatalog.CASTLE_ID) {
            pendingCastleAdmin = null;
            pendingMercenaryAdmin = null;
            pendingCastleSecurity = null;
            CastleSummary castle = castleOwnerAuthority("castlegate");
            if (castle != null) {
                if (hub.classicCastleWarActive(
                        selectedClassicServerName, castle.castleId())) {
                    sendEncrypted(Protocol.messageCode(991),
                            "S_MESSAGE_CODE castle-gate-repair-cancelled-war=991 castle="
                                    + castle.castleId());
                    return;
                }
                int repaired = hub.repairClassicCastleDoors(castle.castleId());
                if (castle.castleId() == ClassicWorldDwarfCastleCatalog.CASTLE_ID) {
                    broadcastDwarfCastleDoors(
                            hub.dwarfCastleDoors(), "steward-repair");
                }
                if (castle.castleId() == ClassicWorldHeineCatalog.CASTLE_ID) {
                    broadcastHeineCastleDoors(
                            hub.heineCastleDoors(), "steward-repair");
                }
                sendEncrypted(Protocol.messageCode(990),
                        "S_MESSAGE_CODE castle-gates-repaired=990 count=" + repaired);
            }
        } else if ((classicCastleSceneId()
                    == ClassicWorldWindawoodCastleCatalog.CASTLE_ID
                    && ClassicWorldWindawoodCastleCatalog.isTextOnlyGateAction(
                            request.action()))
                || (classicCastleSceneId() == ClassicWorldKentCastleCatalog.CASTLE_ID
                    && ClassicWorldKentCastleCatalog.isTextOnlyGateAction(
                            request.action()))
                || (classicCastleSceneId() == ClassicWorldDwarfCastleCatalog.CASTLE_ID
                    && ClassicWorldDwarfCastleCatalog.isTextOnlyGateAction(
                            request.action()))
                || (classicCastleSceneId() == ClassicWorldAdenToiCatalog.CASTLE_ID
                    && ClassicWorldAdenToiCatalog.isTextOnlyGateAction(
                            request.action()))
                || (classicCastleSceneId() == ClassicWorldHeineCatalog.CASTLE_ID
                    && ClassicWorldHeineCatalog.isTextOnlyStewardAction(
                            request.action()))) {
            pendingCastleAdmin = null;
            pendingMercenaryAdmin = null;
            pendingCastleSecurity = null;
            System.out.println("[LiTo] C_HACTION castle-steward rejected "
                    + "resource-declared-unreachable action=" + request.action()
                    + " reachable="
                    + ClassicWorldWindawoodCastleCatalog.CASTLE_GATE_ACTION);
        } else {
            pendingCastleAdmin = null;
            pendingMercenaryAdmin = null;
            pendingCastleSecurity = null;
            System.out.println("[LiTo] C_HACTION castle-steward action="
                    + request.action() + " not-yet-mapped");
        }
    }

    private void handleClassicCastleEquipmentEnchant(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        boolean weaponService = isClassicCastleWeaponEnchanter(npc);
        String expectedAction = weaponService
                ? ClassicWorldGiranCastleCatalog.WEAPON_ENCHANT_ACTION
                : ClassicWorldGiranCastleCatalog.ARMOR_ENCHANT_ACTION;
        boolean accepted = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.action().equalsIgnoreCase(expectedAction)
                && request.parameter().isEmpty()
                && classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) <= 5
                && phase == Phase.WORLD
                && (classicWorldMapId == ClassicWorldGiranCastleCatalog.INTERIOR_MAP_ID
                    || classicWorldMapId
                        == ClassicWorldWindawoodCastleCatalog.INTERIOR_MAP_ID
                    || classicWorldMapId
                        == ClassicWorldKentCastleCatalog.INTERIOR_MAP_ID
                    || classicWorldMapId == ClassicWorldDwarfCastleCatalog.MAP_ID
                    || classicWorldMapId
                        == ClassicWorldAdenToiCatalog.ADEN_INTERIOR_MAP_ID
                    || classicWorldMapId == ClassicWorldHeineCatalog.INTERIOR_MAP_ID)
                && !observer && playerHp > 0;
        if (!accepted) {
            System.out.println("[LiTo] C_HACTION classic-castle equipment enchant rejected spawn="
                    + npc.spawnId() + " action=" + request.action());
            return;
        }

        RuntimeInventory.Item item = weaponService
                ? inventory.equippedWeaponItem() : inventory.equippedSourceArmor(2);
        if (item == null) {
            sendEncrypted(Protocol.messageCode(79),
                    "S_MESSAGE_CODE classic-castle-equipment-enchant-no-item=79 service="
                            + expectedAction);
            sendEncrypted(Protocol.closeHypertext(npc.objectId()),
                    "S_HYPERTEXT_CLOSE classic-castle-equipment-enchant service="
                            + expectedAction);
            return;
        }

        long nowNanos = System.nanoTime();
        int replacedSkill;
        int replacedCharacterWeaponSkill = 0;
        int actionId;
        int effectGfx;
        if (weaponService) {
            replacedCharacterWeaponSkill =
                    weaponBuffStatus.cancelMagicEffects().skillId();
            replacedSkill = itemWeaponEnchantStatus.activate(
                    nowNanos,
                    ClassicWorldGiranCastleCatalog.ENCHANT_WEAPON_DURATION_SECONDS,
                    ClassicWorldGiranCastleCatalog.ENCHANT_WEAPON_SKILL_ID,
                    item.objectId(), item.nativeLogName(),
                    ClassicWorldGiranCastleCatalog.ENCHANT_WEAPON_DAMAGE,
                    ClassicWorldGiranCastleCatalog.ENCHANT_WEAPON_DAMAGE);
            actionId = ClassicWorldGiranCastleCatalog.ENCHANT_WEAPON_ACTION_ID;
            effectGfx = ClassicWorldGiranCastleCatalog.ENCHANT_WEAPON_EFFECT_GFX;
        } else {
            replacedSkill = itemArmorEnchantStatus.activate(
                    nowNanos,
                    ClassicWorldGiranCastleCatalog.ENCHANT_ARMOR_DURATION_SECONDS,
                    ClassicWorldGiranCastleCatalog.ENCHANT_ARMOR_SKILL_ID,
                    item.objectId(), item.nativeLogName(),
                    ClassicWorldGiranCastleCatalog.ENCHANT_ARMOR_CLASS);
            actionId = ClassicWorldGiranCastleCatalog.ENCHANT_ARMOR_ACTION_ID;
            effectGfx = ClassicWorldGiranCastleCatalog.ENCHANT_ARMOR_EFFECT_GFX;
        }

        sendEncrypted(Protocol.messageCode(
                        161, item.nativeLogName(), "$245", "$247"),
                "S_MESSAGE_CODE classic-castle-equipment-enchant-success=161 item="
                        + item.objectId() + " service=" + expectedAction);
        sendEncrypted(Protocol.closeHypertext(npc.objectId()),
                "S_HYPERTEXT_CLOSE classic-castle-equipment-enchant service="
                        + expectedAction);
        byte[] action = Protocol.objectAction(playerObjectId(), actionId);
        byte[] effect = Protocol.effectObject(playerObjectId(), effectGfx);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, positionX, positionY)) {
                continue;
            }
            member.sendEncrypted(action,
                    "S_ACTION classic-castle-equipment-enchant caster=" + playerObjectId()
                            + " action=" + actionId);
            member.sendEncrypted(effect,
                    "S_EFFECT classic-castle-equipment-enchant target=" + playerObjectId()
                            + " gfx=" + effectGfx);
        }
        if (!weaponService) {
            sendEncrypted(ownCharacterAttrDef(),
                    "S_AC classic-castle-armor-enchant current=" + battleArmorClass());
        }
        System.out.println("[LiTo] classic-castle equipment enchant accepted player="
                + playerName() + " service=" + expectedAction + " item="
                + item.objectId() + " replaced-skill=" + replacedSkill
                + " replaced-character-weapon-skill="
                + replacedCharacterWeaponSkill
                + " duration=1800 cancellation-immune=true");
    }

    private void hypertextAction(byte[] payload) throws IOException {
        Protocol.HypertextActionRequest request = Protocol.hypertextActionRequest(payload);
        PendingShapeChange shapeChange = pendingShapeChange;
        if ((phase == Phase.BATTLE || phase == Phase.WORLD)
                && shapeChange != null
                && request.worldObjectId() == playerObjectId()) {
            if (observer || playerHp <= 0 || rejectWhileParalyzed("C_HACTION")) {
                synchronized (this) {
                    if (pendingShapeChange == shapeChange) {
                        pendingShapeChange = null;
                    }
                }
                return;
            }
            handleShapeChangeAction(request, shapeChange);
            return;
        }
        if ((phase == Phase.BATTLE || phase == Phase.WORLD)
                && request.worldObjectId() == playerObjectId()
                && pendingRewardUi != null) {
            handlePendingRewardAction(request);
            return;
        }
        if (phase == Phase.WORLD) {
            // Dynamic classic-world NPCs do not live in the static spawn
            // catalog.  Route them through the same C_NPCAction domain as
            // their C_DIALOG response; otherwise a valid trebuchet or Roi
            // follower action is incorrectly treated as an owned companion.
            boolean npcDomain = ClassicWorldNpcCatalog.npc(
                    classicWorldMapId, request.worldObjectId()) != null
                    || hub.classicCastleWarObject(
                            selectedClassicServerName, classicWorldMapId,
                            request.worldObjectId()) != null
                    || hub.classicWorldRoiFollowers().find(
                            request.worldObjectId()) != null;
            if (npcDomain) {
                handleClassicWorldNpcAction(request);
            } else {
                handleClassicWorldCompanionAction(request);
            }
            return;
        }
        if (phase != Phase.BATTLE) {
            pendingShapeChange = null;
            System.out.println("[LiTo] C_HACTION rejected invalid-phase=" + phase
                    + " action=" + request.action());
            return;
        }
        if (observer || playerHp <= 0 || rejectWhileParalyzed("C_HACTION")) {
            pendingShapeChange = null;
            return;
        }
        pendingHouseAuctionBid = null;

        if (rentalTownRoomState) {
            handleRentalTownHypertextAction(request);
            return;
        }

        if (request.worldObjectId() == classicMerchantNpcObjectId()) {
            ArenaMapCatalog.Point npc = classicMerchantNpcPoint();
            if (npc == null || classicNpcDistance(npc) > 5) {
                clearPendingClassicList();
                System.out.println("[LiTo] C_HACTION rejected classic-merchant-distance action="
                        + request.action());
                return;
            }
            if (request.action().equalsIgnoreCase("buy")) {
                sendClassicBuyList();
            } else if (request.action().equalsIgnoreCase("sell")) {
                sendClassicSellList();
            } else {
                clearPendingClassicList();
                System.out.println("[LiTo] C_HACTION rejected classic-merchant action="
                        + request.action());
            }
            return;
        }

        if (request.worldObjectId() == warehouseNpcObjectId()) {
            ArenaMapCatalog.Point npc = warehouseNpcPoint();
            if (npc == null || classicNpcDistance(npc) > 5) {
                clearPendingClassicList();
                System.out.println("[LiTo] C_HACTION rejected warehouse-distance action="
                        + request.action());
                return;
            }
            if (request.action().equalsIgnoreCase("retrieve")) {
                requestWarehouseRetrieve(1, 3, request.worldObjectId());
            } else if (request.action().equalsIgnoreCase("retrieve-pledge")) {
                requestWarehouseRetrieve(2, 5, request.worldObjectId());
            } else if (request.action().equalsIgnoreCase("retrieve-elven")) {
                requestWarehouseRetrieve(1, 9, request.worldObjectId());
            } else {
                clearPendingClassicList();
                pendingWarehousePassword = null;
                System.out.println("[LiTo] C_HACTION warehouse action=" + request.action()
                        + " not-yet-mapped");
            }
            return;
        }

        if (request.worldObjectId() == houseAuctionBoardObjectId()) {
            ArenaMapCatalog.Point board = houseAuctionBoardPoint();
            if (board == null || classicNpcDistance(board) > 5) {
                pendingHouseAuctionBid = null;
                System.out.println("[LiTo] C_HACTION rejected house-auction-distance action="
                        + request.action());
                return;
            }
            long houseId = houseAuctionHouseId(request.parameter());
            GameStateStore.HouseAuction auction = houseAuction(houseId);
            if (auction == null) {
                pendingHouseAuctionBid = null;
                System.out.println("[LiTo] C_HACTION rejected house-auction-row action="
                        + request.action() + " parameter=" + request.parameter());
                return;
            }
            if (request.action().equalsIgnoreCase("select")) {
                pendingHouseAuctionBid = null;
                sendHouseAuctionDetail(auction);
            } else if (request.action().equalsIgnoreCase("map")) {
                pendingHouseAuctionBid = null;
                sendEncrypted(Protocol.agitMap(request.worldObjectId(), houseId),
                        "S_AGIT_MAP board=" + request.worldObjectId()
                                + " house=" + houseId);
            } else if (request.action().equalsIgnoreCase("apply")) {
                openHouseAuctionBid(auction);
            } else {
                pendingHouseAuctionBid = null;
                System.out.println("[LiTo] C_HACTION rejected house-auction-action="
                        + request.action());
            }
            return;
        }

        if (request.worldObjectId() == mercenaryCommanderNpcObjectId()) {
            ArenaMapCatalog.Point npc = mercenaryCommanderNpcPoint();
            if (npc == null || classicNpcDistance(npc) > 5
                    || !request.parameter().isEmpty()
                    || !request.action().equalsIgnoreCase("demand")) {
                System.out.println("[LiTo] C_HACTION rejected mercenary-commander action="
                        + request.action() + " player=" + playerName());
                return;
            }
            demandMercenaries(request.worldObjectId());
            return;
        }

        if (request.worldObjectId() == castleStewardNpcObjectId()) {
            handleCastleStewardAction(request);
            return;
        }

        BattleCompanion owned = ownedCompanion(request.worldObjectId());
        if (owned == null) {
            boolean belongsToPeer = peerOwnsCompanion(request.worldObjectId());
            System.out.println("[LiTo] C_HACTION rejected object=" + request.worldObjectId()
                    + " action=" + request.action() + " result="
                    + (belongsToPeer ? "companion-not-owned" : "target-domain-unavailable"));
            return;
        }
        BattleCompanion.Snapshot companion = owned.snapshot();

        BattleCompanion.CommandResult result = owned.apply(request.action());
        if (result == BattleCompanion.CommandResult.TARGET_SELECTION_PENDING) {
            int mode = 0;
            pendingSlaveTarget = new PendingSlaveTarget(companion.objectId(), mode,
                    currentRoomId, System.nanoTime() + SLAVE_TARGET_TIMEOUT_NANOS);
            sendEncrypted(Protocol.slaveControl(companion.objectId(), mode),
                    "S_SLAVE_CONTROL companion=" + companion.objectId()
                            + " mode=" + mode + " expires-seconds=15");
        } else {
            pendingSlaveTarget = null;
        }
        if (result == BattleCompanion.CommandResult.RENAME_PENDING) {
            // LiTo has one generic S_ASK callback. A newer rename prompt
            // supersedes unopened trade/clan prompts owned by this client.
            hub.cancelPendingPlayerTradePrompt(this);
            clearPendingAskCallbacks();
            pendingPetRename = new PendingPetRename(companion.objectId(), currentRoomId,
                    System.nanoTime() + PET_RENAME_TIMEOUT_NANOS);
            sendEncrypted(Protocol.petRenameAsk(),
                    "S_ASK question=325 companion=" + companion.objectId()
                            + " expires-seconds=30");
        } else {
            pendingPetRename = null;
        }
        if (result == BattleCompanion.CommandResult.COLLECTION_REQUESTED) {
            transferCompanionItems(owned);
        }
        if (result == BattleCompanion.CommandResult.DISMISSED) {
            byte[] removed = new Protocol.Writer().c(Protocol.S_REMOVE_OBJECT)
                    .d(companion.objectId()).bytes();
            for (ClientSession member : hub.battleRecipients(
                    currentRoomId, hub.forceOf(currentRoomId, this))) {
                member.sendEncrypted(removed,
                        "S_REMOVE_OBJECT companion=" + companion.objectId()
                                + " owner=" + playerName() + " reason=dismiss");
            }
        }
        System.out.println("[LiTo] C_HACTION object=" + request.worldObjectId()
                + " action=" + request.action() + " parameter=" + request.parameter()
                + " kind=" + request.kind() + " result=" + result);
    }

    private void handleClassicWorldCompanionAction(
            Protocol.HypertextActionRequest request) throws IOException {
        if (observer || playerHp <= 0
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)
                || rejectWhileParalyzed("C_HACTION")) return;
        BattleCompanion owned = ownedCompanion(request.worldObjectId());
        BattleCompanion.Snapshot companion = owned == null ? null : owned.snapshot();
        if (companion == null || !companion.active()
                || !companion.kind().classicWorldEligible()
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, companion.x(), companion.y())) {
            pendingSlaveTarget = null;
            pendingPetRename = null;
            System.out.println("[LiTo] C_HACTION classic-world rejected object="
                    + request.worldObjectId() + " action=" + request.action()
                    + " result=unowned-inactive-or-out-of-screen");
            return;
        }

        boolean liberatedPet = companion.kind() == BattleCompanion.Kind.PET
                && request.kind() == Protocol.HypertextActionKind.DISMISS;
        BattleCompanion.CommandResult result;
        if (liberatedPet) {
            result = liberateClassicWorldPet(owned, companion)
                    ? BattleCompanion.CommandResult.DISMISSED
                    : BattleCompanion.CommandResult.REJECTED;
        } else {
            result = owned.apply(request.action());
        }
        long context = controlledCompanionContext();
        if (result == BattleCompanion.CommandResult.TARGET_SELECTION_PENDING) {
            pendingSlaveTarget = new PendingSlaveTarget(
                    companion.objectId(), 0, context,
                    System.nanoTime() + SLAVE_TARGET_TIMEOUT_NANOS);
            sendEncrypted(Protocol.slaveControl(companion.objectId(), 0),
                    "S_SLAVE_CONTROL classic-world companion="
                            + companion.objectId() + " mode=0 expires-seconds=15");
        } else {
            pendingSlaveTarget = null;
        }
        if (result == BattleCompanion.CommandResult.RENAME_PENDING) {
            hub.cancelPendingPlayerTradePrompt(this);
            clearPendingAskCallbacks();
            pendingPetRename = new PendingPetRename(
                    companion.objectId(), context,
                    System.nanoTime() + PET_RENAME_TIMEOUT_NANOS);
            sendEncrypted(Protocol.petRenameAsk(),
                    "S_ASK question=325 classic-world companion="
                            + companion.objectId() + " expires-seconds=30");
        } else {
            pendingPetRename = null;
        }
        if (result == BattleCompanion.CommandResult.COLLECTION_REQUESTED) {
            transferCompanionItems(owned);
        }
        if (result == BattleCompanion.CommandResult.DISMISSED && !liberatedPet) {
            removeClassicWorldCompanion(owned, companion, "dismiss", true);
        }
        System.out.println("[LiTo] C_HACTION classic-world object="
                + request.worldObjectId() + " action=" + request.action()
                + " parameter=" + request.parameter() + " kind="
                + request.kind() + " result=" + result);
    }

    private void handleClassicWorldNpcAction(
            Protocol.HypertextActionRequest request) throws IOException {
        pendingClassicCraft = null;
        pendingHotelRental = null;
        if (observer || playerHp <= 0
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)
                || rejectWhileParalyzed("C_HACTION")) return;
        ClassicWorldCastleWarField.WarObject castleObjective =
                hub.classicCastleWarObject(
                        selectedClassicServerName, classicWorldMapId,
                        request.worldObjectId());
        if (castleObjective != null
                && castleObjective.kind()
                    == ClassicWorldCastleWarField.Kind.TREBUCHET) {
            handleClassicCastleTrebuchetAction(request, castleObjective);
            return;
        }
        if (castleObjective != null
                && (castleObjective.kind()
                        == ClassicWorldCastleWarField.Kind.TOWER
                    || castleObjective.kind()
                        == ClassicWorldCastleWarField.Kind.CROWN)) {
            // C_NPCAction sets L1PcInstance.tempID before dispatching any
            // L1NpcInstance.  Preserve that context for C_WAR target " ".
            lastClassicNpcActionObjectId = castleObjective.objectId();
            System.out.println("[LiTo] C_HACTION castle objective temp-id player="
                    + playerName() + " object=" + castleObjective.objectId()
                    + " castle=" + castleObjective.castleId()
                    + " kind=" + castleObjective.kind());
            return;
        }
        ClassicWorldRescueFollowers.Snapshot rescueFollower =
                hub.classicWorldRescueFollowers().find(request.worldObjectId());
        if (rescueFollower != null) {
            handleClassicWorldRescueFollowerAction(request, rescueFollower);
            return;
        }
        ClassicWorldDspyEscorts.Snapshot dspyFollower =
                hub.classicWorldDspyEscorts().find(request.worldObjectId());
        if (dspyFollower != null) {
            handleClassicWorldDspyFollowerAction(request, dspyFollower);
            return;
        }
        ClassicWorldRoiFollowers.Snapshot roiFollower =
                hub.classicWorldRoiFollowers().find(request.worldObjectId());
        if (roiFollower != null) {
            handleClassicWorldRoiFollowerAction(request, roiFollower);
            return;
        }
        ClassicWorldNpcCatalog.StaticNpc npc = ClassicWorldNpcCatalog.npc(
                classicWorldMapId, request.worldObjectId());
        if (npc == null || !BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, npc.x(), npc.y())) {
            System.out.println("[LiTo] C_HACTION classic-world NPC rejected object="
                    + request.worldObjectId() + " action=" + request.action()
                    + " result=unknown-or-out-of-screen");
            return;
        }
        if (isClassicCastleSteward(npc)) {
            handleCastleStewardAction(request);
            return;
        }
        if (ClassicWorldDwarfCastleCatalog.isGuard(npc)) {
            handleDwarfCastleGuardAction(request, npc);
            return;
        }
        if (ClassicWorldDwarfCastleCatalog.isCommander(npc)) {
            handleDwarfCastleCommanderAction(request, npc);
            return;
        }
        if (ClassicWorldAdenToiCatalog.isGatekeeper(npc)) {
            handleAdenCastleGatekeeperAction(request, npc);
            return;
        }
        if (ClassicWorldAdenToiCatalog.isCommander(npc)) {
            handleAdenCastleCommanderAction(request, npc);
            return;
        }
        if (ClassicWorldHeineCatalog.isGatekeeper(npc)) {
            handleHeineCastleGatekeeperAction(request, npc);
            return;
        }
        if (ClassicWorldHeineCatalog.isGuard(npc)) {
            handleHeineCastleGuardAction(request, npc);
            return;
        }
        if (ClassicWorldHotelCatalog.isInnkeeper(npc)) {
            handleClassicWorldHotelAction(request, npc);
            return;
        }
        if (npc.housekeeper()) {
            handleClassicWorldHousekeeperAction(request, npc);
            return;
        }
        if (isClassicCastleWeaponEnchanter(npc)
                || isClassicCastleArmorEnchanter(npc)) {
            handleClassicCastleEquipmentEnchant(request, npc);
            return;
        }
        if (isClassicWorldWaterDragonGate(npc)) {
            handleClassicWorldWaterDragonGateAction(request, npc);
            return;
        }
        String homeTownLinkedHtml =
                ClassicWorldBehemothSilveriaCatalog.linkedTeleportHtml(
                        npc, request.action());
        if (homeTownLinkedHtml != null) {
            boolean accepted = request.kind() == Protocol.HypertextActionKind.GENERIC
                    && request.parameter().isEmpty()
                    && classicNpcDistance(new ArenaMapCatalog.Point(
                            npc.x(), npc.y())) <= 5;
            if (accepted) {
                sendEncrypted(Protocol.hypertext(
                                npc.objectId(), homeTownLinkedHtml, "", List.of()),
                        "S_HYPERTEXT home-town teleporter npc=" + npc.npcId()
                                + " html=" + homeTownLinkedHtml);
            }
            return;
        }
        if (handleClassicWorldDesireCaveAction(request, npc)) return;
        ClassicWorldTeleportCatalog.Route route = ClassicWorldTeleportCatalog.route(
                classicWorldMapId, request.worldObjectId(), request.action());
        String followUpHtml = ClassicWorldTeleportCatalog.followUpHtml(
                classicWorldMapId, request.worldObjectId(), request.action());
        if (handleIvoryTowerElfAttributeAction(request, npc)) return;
        if (handleDemonTempleDeferredAction(request, npc)) return;
        if (handleClassicWorldCkewCompletionAction(request, npc)) return;
        if (handleClassicWorldStoryAction(request, npc)) return;
        if (handleClassicWorldKamylaAction(request, npc)) return;
        if (handleClassicWorldShipGraveAction(request, npc)) return;
        if (handleDiadradLinkedHtml(request, npc)) return;
        if (handleSilentCavernFullHeal(request, npc)) return;
        if (handleIvoryTowerPriceAction(request, npc)) return;
        if (npc.fixedWarehouse()) {
            if (battleLevel() < 5 || classicNpcDistance(
                    new ArenaMapCatalog.Point(npc.x(), npc.y())) > 5) {
                clearPendingClassicList();
                pendingWarehousePassword = null;
                sendEncrypted(Protocol.messageCode(166),
                        "S_MESSAGE_CODE classic-world-warehouse-level-or-distance=166");
                return;
            }
            if (request.action().equalsIgnoreCase("retrieve")) {
                requestWarehouseRetrieve(1, 3, npc.objectId());
            } else if (request.action().equalsIgnoreCase("retrieve-pledge")) {
                requestWarehouseRetrieve(2, 5, npc.objectId());
            } else if (request.action().equalsIgnoreCase("retrieve-elven")) {
                requestWarehouseRetrieve(1, 9, npc.objectId());
            } else if (!request.action().equalsIgnoreCase("setwarepass")) {
                clearPendingClassicList();
                pendingWarehousePassword = null;
                System.out.println("[LiTo] C_HACTION classic-world warehouse deferred spawn="
                        + npc.spawnId() + " action=" + request.action());
            }
            return;
        }
        ClassicWorldMerchantCatalog.Merchant merchant =
                ClassicWorldMerchantCatalog.find(npc);
        if (npc.fixedMerchant() || merchant != null) {
            // Some retained teleporters (notably NPC70853) are implemented as
            // L1Merchant. Only a catalogued shop owns the buy-list capability;
            // unrelated fixed merchants continue to the dispatcher below.
            if (merchant != null) {
                boolean buy = request.kind() == Protocol.HypertextActionKind.GENERIC
                    && request.action().equalsIgnoreCase(merchant.buyAction())
                    && request.parameter().isEmpty()
                    && classicNpcDistance(new ArenaMapCatalog.Point(
                            npc.x(), npc.y())) <= merchant.maximumDistance();
                boolean emptySell = request.kind()
                        == Protocol.HypertextActionKind.GENERIC
                    && request.action().equalsIgnoreCase(
                            ClassicWorldMerchantCatalog.IVORY_TOWER_SELL_ACTION)
                    && request.parameter().isEmpty()
                    && ClassicWorldMerchantCatalog.supportsEmptySell(merchant)
                    && classicNpcDistance(new ArenaMapCatalog.Point(
                            npc.x(), npc.y())) <= merchant.maximumDistance();
                if (!buy && !emptySell) {
                    clearPendingClassicList();
                    System.out.println("[LiTo] C_HACTION classic-world merchant rejected spawn="
                            + npc.spawnId() + " action=" + request.action()
                            + " result=unsupported-action-or-distance");
                    return;
                }
                if (buy) sendClassicWorldBuyList(merchant);
                else sendClassicWorldEmptySellList(npc);
                return;
            }
        }
        if (ClassicWorldKentCastleCatalog.isNiki(npc)) {
            boolean accepted = request.kind() == Protocol.HypertextActionKind.GENERIC
                    && request.action().equalsIgnoreCase(
                            ClassicWorldKentCastleCatalog.NIKI_SELL_ACTION)
                    && request.parameter().isEmpty()
                    && classicNpcDistance(new ArenaMapCatalog.Point(
                            npc.x(), npc.y())) <= 5;
            if (!accepted) {
                clearPendingClassicList();
                System.out.println("[LiTo] C_HACTION Kent Niki rejected action="
                        + request.action());
                return;
            }
            sendClassicWorldEmptySellList(npc);
            return;
        }
        ClassicWorldCraftCatalog.Recipe craft = ClassicWorldCraftCatalog.find(
                classicWorldMapId, npc.npcId(), request.action());
        if (craft != null) {
            boolean accepted = request.kind() == Protocol.HypertextActionKind.GENERIC
                    && request.parameter().isEmpty()
                    && ClassicWorldCraftCatalog.matchesSource(npc, craft)
                    && battleLevel() >= craft.minimumLevel()
                    && classicNpcDistance(new ArenaMapCatalog.Point(
                            npc.x(), npc.y())) <= 5
                    && pendingPortal == null && !hub.hasPrivateShop(this);
            if (!accepted) {
                System.out.println("[LiTo] C_HACTION classic-world craft rejected spawn="
                        + npc.spawnId() + " recipe=" + craft.id()
                        + " result=source-level-or-state");
                return;
            }
            int maximum = ClassicWorldCraftCatalog.maximumAmount(inventory, craft);
            if (craft.amountInputable() && maximum > 1) {
                int mode = 0;
                pendingClassicCraft = new PendingClassicCraft(
                        npc.objectId(), classicWorldMapId, craft.id(), maximum,
                        mode, craft.action(), System.nanoTime()
                                + CLASSIC_CRAFT_CONTEXT_TIMEOUT_NANOS);
                sendEncrypted(Protocol.hypertextInput(
                                npc.objectId(), 0, 0, 0, maximum, mode,
                                "request", "", craft.action(), List.of()),
                        "S_HYPERTEXT_INPUT classic-world-craft recipe=" + craft.id()
                                + " action=" + craft.action()
                                + " maximum=" + maximum);
                return;
            }
            performClassicWorldCraft(craft, 1);
            return;
        }
        if (followUpHtml != null
                && request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()) {
            sendEncrypted(Protocol.hypertext(
                            npc.objectId(), followUpHtml, "",
                            ClassicWorldTeleportCatalog.followUpArguments(
                                    classicWorldMapId, request.worldObjectId(),
                                    request.action())),
                    "S_HYPERTEXT classic-world NPC follow-up spawn=" + npc.spawnId()
                            + " npc=" + npc.npcId() + " html=" + followUpHtml);
            System.out.println("[LiTo] C_HACTION classic-world NPC follow-up accepted"
                    + " map=" + classicWorldMapId + " spawn=" + npc.spawnId()
                    + " npc=" + npc.npcId() + " action=" + request.action()
                    + " html=" + followUpHtml);
            return;
        }
        if (route == null || request.kind() != Protocol.HypertextActionKind.GENERIC) {
            if (ClassicWorldSilentCavernCatalog.isTextOnlyTeleportAction(
                    npc, request.action())) {
                System.out.println("[LiTo] C_HACTION Silent-Cavern teleporter rejected"
                        + " Text.pak/DB mismatch action=" + request.action()
                        + " retained-routes=6 destination=unresolved");
                return;
            }
            if (ClassicWorldDwarfCastleCatalog.isTextOnlyTeleportAction(
                    request.action())) {
                System.out.println("[LiTo] C_HACTION Dwarf teleporter rejected Text.pak/DB"
                        + " mismatch action=" + request.action() + " retained="
                        + ClassicWorldDwarfCastleCatalog.DATABASE_CRYSTAL_ACTION);
                return;
            }
            System.out.println("[LiTo] C_HACTION classic-world NPC deferred spawn="
                    + npc.spawnId() + " npc=" + npc.npcId()
                    + " action=" + request.action());
            return;
        }
        if (npc.spawnId() != route.sourceSpawnId()
                || npc.npcId() != route.sourceNpcId()
                || npc.x() != route.sourceX() || npc.y() != route.sourceY()
                || battleLevel() < route.minimumLevel()
                || battleLevel() > route.maximumLevel()
                || pendingPortal != null || hub.hasPrivateShop(this)) {
            System.out.println("[LiTo] C_HACTION classic-world teleport rejected spawn="
                    + npc.spawnId() + " route=" + route.routeId()
                    + " result=source-level-or-state");
            return;
        }
        ClassicWorldMapCatalog.ClassicMap destinationMap =
                ClassicWorldMapCatalog.forMap(route.destinationMapId());
        if (!destinationMap.standingPassable(
                route.destinationX(), route.destinationY())) {
            throw new IOException("classic NPC teleport destination is not passable");
        }

        if (route.priceAmount() > 0) {
            RuntimeInventory previous = inventory;
            RuntimeInventory next = inventory.copy();
            if (!next.removeCatalog(route.priceItemId(), route.priceAmount())) {
                long available = inventory.catalogCounts().getOrDefault(
                        route.priceItemId(), 0);
                long shortage = Math.max(1L, route.priceAmount() - available);
                sendEncrypted(Protocol.messageCode(
                                337, "$4 (" + shortage + ")"),
                        "S_MESSAGE_CODE classic-world-teleport-insufficient=337"
                                + " item=" + route.priceItemId()
                                + " shortage=" + shortage);
                return;
            }
            state.saveEconomyState(stateCharacter(), shopPoints,
                    next.catalogCounts(), next.catalogItemStates());
            inventory = next;
            sendInventoryDelta(previous, inventory);
        }

        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                route.destinationMapId(), route.destinationX(),
                route.destinationY(), true);
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, route.heading(), 0,
                "NPC-teleport-route-" + route.routeId());
        pendingPortal = destination;
        pendingPortalReady = true;

        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT classic-world-NPC-teleport target="
                                + playerObjectId() + " gfx="
                                + ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
            }
        }
        sendEncrypted(Protocol.portal(destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL classic-world-NPC route=" + route.routeId()
                        + " map=" + destination.mapId() + " x=" + destination.x()
                        + " y=" + destination.y());
        System.out.println("[LiTo] C_HACTION classic-world teleport accepted player="
                + playerName() + " source=" + classicWorldMapId + ":"
                + npc.x() + "," + npc.y() + " npc=" + npc.npcId()
                + " route=" + route.routeId() + " action=" + route.action()
                + " price=" + route.priceAmount() + " destination="
                + destination.mapId() + ":" + destination.x() + ","
                + destination.y() + " result=awaiting-C_GOTO_PORTAL");
    }

    private void handleClassicCastleTrebuchetAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldCastleWarField.WarObject trebuchet) throws IOException {
        if (request.kind() != Protocol.HypertextActionKind.GENERIC
                || !request.parameter().isEmpty()
                || trebuchet.currentHp() <= 0
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, trebuchet.x(), trebuchet.y())) {
            System.out.println("[LiTo] C_HACTION castle trebuchet rejected object="
                    + request.worldObjectId() + " action=" + request.action()
                    + " result=layout-dead-or-distance");
            return;
        }
        long now = System.nanoTime();
        long available = trebuchet.npcId()
                == ClassicWorldCastleWarField.ATTACK_TREBUCHET_NPC_ID
                ? attackTrebuchetAvailableNanos : defenceTrebuchetAvailableNanos;
        if (now - available < 0) {
            sendEncrypted(Protocol.messageCode(3680),
                    "S_MESSAGE_CODE castle-trebuchet-cooldown=3680 object="
                            + trebuchet.objectId());
            return;
        }
        if (inventory.catalogCounts().getOrDefault(
                (long) ClassicWorldTrebuchetCatalog.NORMAL_SHELL_ITEM_ID, 0) < 1) {
            sendEncrypted(Protocol.questHelpMessage(
                            ClassicWorldTrebuchetCatalog.CLIENT_NO_AMMO_MESSAGE,
                            positionX, positionY),
                    "S_SAY_CODE castle-trebuchet-missing-normal-shell object="
                            + trebuchet.objectId());
            return;
        }
        ClassicWorldTrebuchetCatalog.Shot shot =
                ClassicWorldTrebuchetCatalog.resolve(
                        trebuchet.npcId(), request.action(),
                        bound -> ThreadLocalRandom.current().nextInt(bound));
        if (shot == null) {
            System.out.println("[LiTo] C_HACTION castle trebuchet deferred object="
                    + request.worldObjectId() + " npc=" + trebuchet.npcId()
                    + " action=" + request.action());
            return;
        }

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        boolean consumed = next.removeCatalog(shot.consumedItemId(), 1);
        if (shot.consumedItemId() == ClassicWorldTrebuchetCatalog.NORMAL_SHELL_ITEM_ID
                && !consumed) {
            throw new IOException("validated normal trebuchet shell vanished");
        }
        // The retained source deliberately ignores consumeItem(46282)'s result.
        // The selected database has no 46282 template, so preserve that exact
        // dangling-data behavior instead of fabricating a client/server item.
        if (consumed) {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    next.catalogCounts(), next.catalogItemStates());
            inventory = next;
            sendInventoryDelta(previous, inventory);
        }
        long nextUse = Math.addExact(now,
                java.util.concurrent.TimeUnit.SECONDS.toNanos(
                        ClassicWorldTrebuchetCatalog.COOLDOWN_SECONDS));
        if (trebuchet.npcId()
                == ClassicWorldCastleWarField.ATTACK_TREBUCHET_NPC_ID) {
            attackTrebuchetAvailableNanos = nextUse;
        } else {
            defenceTrebuchetAvailableNanos = nextUse;
        }
        publishClassicCastleTrebuchetShot(trebuchet, shot);
        System.out.println("[LiTo] C_HACTION castle trebuchet accepted player="
                + playerName() + " object=" + trebuchet.objectId()
                + " npc=" + trebuchet.npcId() + " action=" + shot.action()
                + " target=" + shot.x() + "," + shot.y()
                + " damage=" + (shot.damaging()
                    ? ClassicWorldTrebuchetCatalog.DAMAGE : 0)
                + " consumed-item=" + shot.consumedItemId()
                + " consumed=" + consumed);
    }

    private void publishClassicCastleTrebuchetShot(
            ClassicWorldCastleWarField.WarObject trebuchet,
            ClassicWorldTrebuchetCatalog.Shot shot) throws IOException {
        List<ClientSession> members = classicWorldMembers(trebuchet.mapId());
        for (ClientSession target : members) {
            if (ClassicWorldCastleWarField.castleIdAt(
                    target.classicWorldMapId, target.positionX, target.positionY) == 0) {
                continue;
            }
            target.sendEncrypted(Protocol.effectLocation(
                            shot.x(), shot.y(), shot.effectGfx()),
                    "S_EFFECT_LOC castle-trebuchet=" + trebuchet.objectId()
                            + " target=" + shot.x() + "," + shot.y()
                            + " gfx=" + shot.effectGfx());
            target.sendEncrypted(Protocol.objectAction(trebuchet.objectId(), 1),
                    "S_ACTION castle-trebuchet=" + trebuchet.objectId()
                            + " action=1");
            if (!shot.impacts(target.positionX, target.positionY)) continue;
            if (shot.damaging()) {
                // Retained Shells calls receiveDamage(npc, 300, 2).  Use the
                // WORLD monster/NPC path so damage is not discarded by the
                // Tournament-only BATTLE gate and death retains the firing
                // trebuchet's object id as its source.
                target.takeClassicWorldMonsterDamage(
                        ClassicWorldTrebuchetCatalog.DAMAGE,
                        trebuchet.objectId());
                byte[] damageAction = Protocol.objectAction(
                        target.playerObjectId(), BattleActionCodes.DAMAGE);
                for (ClientSession viewer : members) {
                    if (BattleSpellCatalog.isInNativeScreen(
                            viewer.positionX, viewer.positionY,
                            target.positionX, target.positionY)) {
                        viewer.sendEncrypted(damageAction,
                                "S_ACTION castle-trebuchet-victim="
                                        + target.playerObjectId() + " action="
                                        + BattleActionCodes.DAMAGE);
                    }
                }
            } else {
                byte[] silenceEffect = Protocol.effectObject(
                        target.playerObjectId(),
                        ClassicWorldTrebuchetCatalog.SILENCE_EFFECT_GFX);
                for (ClientSession viewer : members) {
                    if (BattleSpellCatalog.isInNativeScreen(
                            viewer.positionX, viewer.positionY,
                            target.positionX, target.positionY)) {
                        viewer.sendEncrypted(silenceEffect,
                                "S_EFFECT castle-trebuchet-silence-visual target="
                                        + target.playerObjectId() + " gfx="
                                        + ClassicWorldTrebuchetCatalog.SILENCE_EFFECT_GFX);
                    }
                }
            }
        }
    }

    /** Exact retained Desire Cave C_NPCAction family (NPC80058..80074). */
    private boolean handleClassicWorldDesireCaveAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        if (!ClassicWorldDesireCaveCatalog.isDialogueNpc(npc)) return false;
        boolean admitted = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) <= 5
                && pendingPortal == null && !hub.hasPrivateShop(this);
        if (!admitted) {
            System.out.println("[LiTo] C_HACTION Desire-Cave rejected npc="
                    + npc.npcId() + " action=" + request.action()
                    + " result=kind-parameter-distance-or-state");
            return true;
        }
        String action = request.action().toLowerCase(Locale.ROOT);
        GameStateStore.StoryQuestState questState =
                state.storyQuests(stateCharacter());
        Map<Integer, Integer> quests = questState.effective();
        GameStateStore.FactionKarmaBalance karma =
                state.factionKarma(stateCharacter());

        // The desert and spy teleports are hash-locked generic route rows.
        // Admit only the actions visible in the retained dynamic page, then
        // let the common route executor preserve C_GOTO_PORTAL semantics.
        if (npc.npcId() == 80058) {
            boolean accepted = action.equals("a") && battleLevel() >= 45
                    || action.equals("b") && battleLevel() >= 45
                    && battleLevel() <= 51;
            return !accepted;
        }
        if (npc.npcId() == 80065) {
            return !(action.equals("4") && karma.level() >= 3);
        }

        ClassicWorldDesireCaveActionCatalog.Door door =
                ClassicWorldDesireCaveActionCatalog.door(npc.npcId());
        if (door != null) {
            handleClassicWorldDesireCaveDoorAction(request, npc, door, quests, karma);
            return true;
        }
        switch (npc.npcId()) {
            case 80063 -> handleClassicWorldDesireInnerDoor(
                    request, npc, quests, karma);
            case 80064 -> handleClassicWorldBarlogSteward(
                    request, npc, quests, karma);
            case 80066 -> handleClassicWorldDesireBetrayal(
                    request, npc, quests, karma);
            case 80067 -> handleClassicWorldDesireSpy(
                    request, npc, quests, karma);
            case 80071 -> handleClassicWorldBarlogEarring(
                    request, npc, quests, karma);
            case 80072 -> handleClassicWorldBarlogSmith(
                    request, npc, quests, karma);
            case 80073 -> handleClassicWorldBarlogTactician(request, npc);
            case 80074 -> handleClassicWorldDesireKarmaManager(
                    request, npc, quests, karma);
            default -> System.out.println("[LiTo] C_HACTION Desire-Cave text-only npc="
                    + npc.npcId() + " action=" + request.action());
        }
        return true;
    }

    private boolean createClassicWorldDesireCaveRulerIfEligible(
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        ClassicWorldDesireCaveActionCatalog.Door door =
                ClassicWorldDesireCaveActionCatalog.door(npc.npcId());
        if (door == null || state.factionKarma(stateCharacter()).level() > 0) return false;
        Map<Long, Integer> counts = inventory.catalogCounts();
        if (counts.getOrDefault(40921L, 0) > 0
                || counts.getOrDefault(door.rulerId(), 0) > 0
                || counts.getOrDefault(door.protectionId(), 0) <= 0) return false;
        for (ClassicWorldDesireCaveActionCatalog.Door other
                : ClassicWorldDesireCaveActionCatalog.DOORS.values()) {
            if (other.npcId() != door.npcId()
                    && counts.getOrDefault(other.protectionId(), 0) > 0) return false;
        }
        int seals = ClassicWorldDesireCaveCatalog.necessarySealCount(counts);
        if (counts.getOrDefault(door.sealId(), 0) < seals) return false;

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        if (!next.removeCatalog(door.protectionId(), 1)
                || !next.removeCatalog(door.sealId(), seals)) {
            throw new IOException("validated Desire Cave ruler materials vanished");
        }
        InventoryCatalog.Definition ruler = InventoryCatalog.find(door.rulerId());
        if (ruler == null || !next.add(ruler, 1)) {
            throw new IOException("Desire Cave ruler definition/capacity unavailable");
        }
        saveClassicWorldDesireCaveMutation(previous, next,
                state.storyQuests(stateCharacter()).effective(),
                state.factionKarma(stateCharacter()).value());
        sendEncrypted(Protocol.messageCode(143, npc.nameId(), ruler.name()),
                "S_MESSAGE_CODE Desire-Cave-ruler=143 npc=" + npc.npcId()
                        + " item=" + ruler.catalogId() + " seals=" + seals);
        return true;
    }

    private void handleClassicWorldDesireCaveDoorAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc,
            ClassicWorldDesireCaveActionCatalog.Door door,
            Map<Integer, Integer> quests,
            GameStateStore.FactionKarmaBalance karma) throws IOException {
        String action = request.action().toLowerCase(Locale.ROOT);
        if (action.equals("a")) {
            beginClassicWorldDesireCavePortal(npc, action,
                    door.destinationMapId(), door.destinationX(),
                    door.destinationY(), door.destinationHeading());
            return;
        }
        if (action.equals("c")) {
            sendClassicWorldDesireCaveHtml(npc, "wpass07");
            return;
        }
        if (action.equals("e")) {
            closeClassicWorldDesireCaveHtml(npc, action);
            return;
        }
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        InventoryCatalog.Definition reward = null;
        if (action.equals("b")) {
            reward = InventoryCatalog.find(door.protectionId());
            if (reward == null || !next.add(reward, 1)) {
                sendEncrypted(Protocol.messageCode(263),
                        "S_MESSAGE_CODE Desire-Cave-door-capacity=263");
                return;
            }
        } else if (action.equals("d")) {
            removeAllCatalog(next, door.sealId());
        } else if (action.equals("f")) {
            removeUpToCatalog(next, door.protectionId(), 1);
            removeAllCatalog(next, door.sealId());
        } else {
            System.out.println("[LiTo] C_HACTION Desire-Cave door unsupported npc="
                    + npc.npcId() + " action=" + request.action());
            return;
        }
        saveClassicWorldDesireCaveMutation(
                previous, next, quests, karma.value());
        if (reward != null) {
            sendEncrypted(Protocol.messageCode(143, npc.nameId(), reward.name()),
                    "S_MESSAGE_CODE Desire-Cave-protection=143 npc="
                            + npc.npcId() + " item=" + reward.catalogId());
        }
        closeClassicWorldDesireCaveHtml(npc, action);
    }

    private void handleClassicWorldDesireInnerDoor(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc,
            Map<Integer, Integer> quests,
            GameStateStore.FactionKarmaBalance karma) throws IOException {
        if (!request.action().equalsIgnoreCase("a")) return;
        if (inventory.catalogCounts().getOrDefault(40921L, 0) > 0) {
            beginClassicWorldDesireCavePortal(npc, request.action(),
                    603, 32674, 32832, 2);
        } else {
            sendClassicWorldDesireCaveHtml(npc, "gpass02");
        }
    }

    private void handleClassicWorldBarlogSteward(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc,
            Map<Integer, Integer> quests,
            GameStateStore.FactionKarmaBalance karma) throws IOException {
        String action = request.action().toLowerCase(Locale.ROOT);
        if (action.equals("1")) {
            sendClassicWorldDesireCaveHtml(npc, "meet005");
            return;
        }
        if (action.equals("2")) {
            sendClassicWorldDesireCaveHtml(npc,
                    inventory.catalogCounts().getOrDefault(40678L, 0) > 0
                            ? "meet006" : "meet010");
            return;
        }
        if (action.equals("d")) {
            boolean ownsElementItem = false;
            for (long itemId = 40909; itemId <= 40921; itemId++) {
                if (inventory.catalogCounts().getOrDefault(itemId, 0) > 0) {
                    ownsElementItem = true;
                    break;
                }
            }
            if (ownsElementItem) closeClassicWorldDesireCaveHtml(npc, action);
            else beginClassicWorldDesireCavePortal(
                    npc, action, 602, 32674, 32832, 2);
            return;
        }
        int amount = switch (action) {
            case "a" -> 1; case "b" -> 10; case "c" -> 100; default -> 0;
        };
        if (amount == 0) return;
        if (inventory.catalogCounts().getOrDefault(40678L, 0) < amount) {
            sendClassicWorldDesireCaveHtml(npc, "meet004");
            return;
        }
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        if (!next.removeCatalog(40678, amount)) {
            throw new IOException("validated soul-crystal fragments vanished");
        }
        int nextKarma = clampDesireCaveKarma(
                (long) karma.value() + amount * 100L);
        saveClassicWorldDesireCaveMutation(previous, next, quests, nextKarma);
        sendEncrypted(Protocol.messageCode(1078),
                "S_MESSAGE_CODE Desire-Cave-karma-offering=1078 amount=" + amount);
        sendClassicWorldDesireCaveHtml(npc, switch (action) {
            case "a" -> "meet007"; case "b" -> "meet008";
            default -> "meet009";
        });
    }

    private void handleClassicWorldDesireBetrayal(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc,
            Map<Integer, Integer> quests,
            GameStateStore.FactionKarmaBalance karma) throws IOException {
        if (!request.action().equals("1") || karma.value() < 10_000_000) return;
        saveClassicWorldDesireCaveMutation(
                inventory, inventory, quests, -1_000_000);
        sendEncrypted(Protocol.messageCode(1079),
                "S_MESSAGE_CODE Desire-Cave-betrayal=1079");
        sendClassicWorldDesireCaveHtml(npc, "betray03");
    }

    private void handleClassicWorldDesireSpy(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc,
            Map<Integer, Integer> quests,
            GameStateStore.FactionKarmaBalance karma) throws IOException {
        String action = request.action().toLowerCase(Locale.ROOT);
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        Map<Integer, Integer> nextQuests = new LinkedHashMap<>(quests);
        int nextKarma = karma.value();
        List<InventoryCatalog.Definition> rewards = new ArrayList<>();
        boolean activateMorph = false;

        if (action.equals("n")) {
            activateMorph = next.catalogCounts().getOrDefault(
                    InventoryCatalog.ADENA, 0) >=
                    ClassicWorldDesireCaveActionCatalog.DESIRE_SPY_MORPH_ADENA;
            if (activateMorph && !next.removeCatalog(
                    InventoryCatalog.ADENA,
                    ClassicWorldDesireCaveActionCatalog.DESIRE_SPY_MORPH_ADENA)) {
                throw new IOException("validated Desire spy morph adena vanished");
            }
            for (long itemId : new long[] {41132, 41133, 41134}) {
                InventoryCatalog.Definition reward = InventoryCatalog.find(itemId);
                if (reward == null || !next.add(reward, 1)) {
                    sendEncrypted(Protocol.messageCode(263),
                            "S_MESSAGE_CODE Desire-spy-capacity=263 item=" + itemId);
                    return;
                }
                rewards.add(reward);
            }
            nextQuests.put(ClassicWorldDesireCaveActionCatalog.QUEST_DESIRE, 1);
        } else if (action.equals("d")) {
            removeUpToCatalog(next, 41130, 1);
            removeUpToCatalog(next, 41131, 1);
        } else if (action.equals("k")) {
            for (long itemId = 41132; itemId <= 41138; itemId++) {
                removeUpToCatalog(next, itemId, 1);
            }
            nextQuests.put(ClassicWorldDesireCaveActionCatalog.QUEST_DESIRE, 0);
        } else if (action.equals("e")) {
            int step = quests.getOrDefault(
                    ClassicWorldDesireCaveActionCatalog.QUEST_DESIRE, 0);
            if (step == ClassicWorldDesireCaveActionCatalog.QUEST_END
                    || karma.level() >= 1) {
                closeClassicWorldDesireCaveHtml(npc, action);
                return;
            }
            if (next.catalogCounts().getOrDefault(41138L, 0) <= 0) {
                sendClassicWorldDesireCaveHtml(npc, "minicod04");
                return;
            }
            removeUpToCatalog(next, 41130, 1);
            removeUpToCatalog(next, 41131, 1);
            if (!next.removeCatalog(41138, 1)) {
                throw new IOException("validated Kahel essence vanished");
            }
            nextKarma = clampDesireCaveKarma((long) karma.value() + 1_600);
            nextQuests.put(ClassicWorldDesireCaveActionCatalog.QUEST_DESIRE,
                    ClassicWorldDesireCaveActionCatalog.QUEST_END);
        } else if (action.equals("g")) {
            InventoryCatalog.Definition reward = InventoryCatalog.find(41130);
            if (reward == null || !next.add(reward, 1)) {
                sendEncrypted(Protocol.messageCode(263),
                        "S_MESSAGE_CODE Desire-spy-capacity=263 item=41130");
                return;
            }
            rewards.add(reward);
        } else {
            return;
        }

        saveClassicWorldDesireCaveMutation(
                previous, next, Map.copyOf(nextQuests), nextKarma);
        if (action.equals("n") && !activateMorph) {
            sendEncrypted(Protocol.messageCode(337, "$4"),
                    "S_MESSAGE_CODE Desire-spy-morph-adena=337 shortage=100");
        }
        if (activateMorph) activateClassicWorldDesireSpyMorph();
        for (InventoryCatalog.Definition reward : rewards) {
            sendEncrypted(Protocol.messageCode(143, npc.nameId(), reward.name()),
                    "S_MESSAGE_CODE Desire-spy-reward=143 item="
                            + reward.catalogId());
        }
        if (action.equals("d")) sendClassicWorldDesireCaveHtml(npc, "minicod09");
        else closeClassicWorldDesireCaveHtml(npc, action);
    }

    private void handleClassicWorldBarlogEarring(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc,
            Map<Integer, Integer> quests,
            GameStateStore.FactionKarmaBalance karma) throws IOException {
        long targetId = ClassicWorldDesireCaveActionCatalog.earringForAction(
                request.action());
        int targetLevel = ClassicWorldDesireCaveActionCatalog.earringLevel(targetId);
        if (targetLevel == 0 || targetLevel != karma.level()
                || inventory.catalogCounts().getOrDefault(targetId, 0) > 0) return;
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        InventoryCatalog.Definition reward = InventoryCatalog.find(targetId);
        if (reward == null || !next.add(reward, 1)) {
            sendEncrypted(Protocol.messageCode(263),
                    "S_MESSAGE_CODE Desire-earring-capacity=263 item=" + targetId);
            return;
        }
        for (long itemId = 21020; itemId < targetId; itemId++) {
            removeUpToCatalog(next, itemId, 1);
        }
        saveClassicWorldDesireCaveMutation(previous, next, quests, karma.value());
        sendEncrypted(Protocol.messageCode(143, npc.nameId(), reward.name()),
                "S_MESSAGE_CODE Desire-earring=143 item=" + targetId);
        closeClassicWorldDesireCaveHtml(npc, request.action());
    }

    private void handleClassicWorldBarlogSmith(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc,
            Map<Integer, Integer> quests,
            GameStateStore.FactionKarmaBalance karma) throws IOException {
        String selection = ClassicWorldDesireCaveActionCatalog.smithSelectionHtml(
                request.action());
        if (selection != null) {
            sendClassicWorldDesireCaveHtml(npc, selection);
            return;
        }
        if (request.action().equals("6")) {
            closeClassicWorldDesireCaveHtml(npc, request.action());
            return;
        }
        ClassicWorldDesireCaveActionCatalog.Craft craft =
                ClassicWorldDesireCaveActionCatalog.craft(request.action());
        if (craft == null || karma.level() < craft.minimumKarmaLevel()) return;
        for (ClassicWorldDesireCaveActionCatalog.ItemAmount material
                : craft.materials()) {
            if (inventory.catalogCounts().getOrDefault(material.itemId(), 0)
                    < material.count()) {
                sendClassicWorldDesireCaveHtml(npc, craft.failureHtml());
                return;
            }
        }
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        for (ClassicWorldDesireCaveActionCatalog.ItemAmount material
                : craft.materials()) {
            if (!next.removeCatalog(material.itemId(), material.count())) {
                throw new IOException("validated Barlog smith material vanished");
            }
        }
        InventoryCatalog.Definition result = InventoryCatalog.find(craft.resultItemId());
        if (result == null || !next.add(result, 1)) {
            sendEncrypted(Protocol.messageCode(263),
                    "S_MESSAGE_CODE Barlog-smith-capacity=263 item="
                            + craft.resultItemId());
            return;
        }
        saveClassicWorldDesireCaveMutation(previous, next, quests, karma.value());
        closeClassicWorldDesireCaveHtml(npc, request.action());
    }

    private void handleClassicWorldBarlogTactician(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        if (!request.action().equalsIgnoreCase("a")) return;
        storySkillEffectDeadlines.remove(
                ClassicWorldDesireCaveActionCatalog.DE_LV30);
        storySkillEffectDeadlines.remove(
                ClassicWorldDesireCaveActionCatalog.CKEW_LV50);
        long now = System.nanoTime();
        if (activeStorySkillEffect(
                ClassicWorldDesireCaveActionCatalog.STATUS_CURSE_BARLOG, now)) {
            sendEncrypted(Protocol.messageCode(79),
                    "S_MESSAGE_CODE Barlog-tactician-opposed-curse=79");
            return;
        }
        storySkillEffectDeadlines.put(
                ClassicWorldDesireCaveActionCatalog.STATUS_CURSE_YAHEE,
                now + ClassicWorldDesireCaveActionCatalog.YAHEE_CURSE_SECONDS
                        * 1_000_000_000L);
        byte[] effect = Protocol.effectObject(playerObjectId(),
                ClassicWorldDesireCaveActionCatalog.YAHEE_CURSE_EFFECT_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT Desire-Cave-curse target=" + playerObjectId()
                                + " gfx="
                                + ClassicWorldDesireCaveActionCatalog
                                        .YAHEE_CURSE_EFFECT_GFX);
            }
        }
        sendEncrypted(Protocol.messageCode(1127),
                "S_MESSAGE_CODE Desire-Cave-curse=1127");
    }

    private void handleClassicWorldDesireKarmaManager(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc,
            Map<Integer, Integer> quests,
            GameStateStore.FactionKarmaBalance karma) throws IOException {
        int amount = ClassicWorldDesireCaveActionCatalog.soulCrystalCount(
                request.action());
        int cost = ClassicWorldDesireCaveActionCatalog.soulCrystalKarmaCost(
                request.action());
        if (amount == 0 || karma.value() < 10_000_000) return;
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        InventoryCatalog.Definition reward = InventoryCatalog.find(40678);
        if (reward == null || !next.add(reward, amount)) {
            sendEncrypted(Protocol.messageCode(263),
                    "S_MESSAGE_CODE Desire-karma-manager-capacity=263");
            return;
        }
        int nextKarma = clampDesireCaveKarma((long) karma.value() - cost);
        saveClassicWorldDesireCaveMutation(previous, next, quests, nextKarma);
        sendEncrypted(Protocol.messageCode(143, npc.nameId(), reward.name()),
                "S_MESSAGE_CODE Desire-karma-manager-reward=143 item=40678 amount="
                        + amount);
        sendEncrypted(Protocol.messageCode(1080),
                "S_MESSAGE_CODE Desire-karma-manager=1080 cost=" + cost);
        closeClassicWorldDesireCaveHtml(npc, request.action());
    }

    private void saveClassicWorldDesireCaveMutation(
            RuntimeInventory previous, RuntimeInventory next,
            Map<Integer, Integer> quests, int karma) throws IOException {
        state.saveDesireCaveState(stateCharacter(), shopPoints,
                next.catalogCounts(), next.catalogItemStates(), quests, karma);
        inventory = next;
        if (previous != next || !previous.catalogCounts().equals(next.catalogCounts())
                || !previous.catalogItemStates().equals(next.catalogItemStates())) {
            sendInventoryDelta(previous, inventory);
        }
    }

    private static int clampDesireCaveKarma(long value) {
        return (int) Math.max(-15_500_000L, Math.min(15_500_000L, value));
    }

    private static void removeUpToCatalog(
            RuntimeInventory target, long itemId, int maximum) {
        int available = target.catalogCounts().getOrDefault(itemId, 0);
        int amount = Math.min(available, maximum);
        if (amount > 0 && !target.removeCatalog(itemId, amount)) {
            throw new IllegalStateException("validated Desire Cave removal failed");
        }
    }

    private static void removeAllCatalog(RuntimeInventory target, long itemId) {
        int available = target.catalogCounts().getOrDefault(itemId, 0);
        if (available > 0 && !target.removeCatalog(itemId, available)) {
            throw new IllegalStateException("validated Desire Cave removal failed");
        }
    }

