    private void beginClassicWorldDesireCavePortal(
            ClassicWorldNpcCatalog.StaticNpc npc, String action,
            int mapId, int x, int y, int heading) throws IOException {
        ClassicWorldMapCatalog.ClassicMap map = ClassicWorldMapCatalog.forMap(mapId);
        if (!map.standingPassable(x, y)) {
            throw new IOException("Desire Cave NPC teleport destination is not passable");
        }
        Protocol.PortalDestination destination =
                new Protocol.PortalDestination(mapId, x, y, true);
        clearPendingClassicList();
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, heading, 0,
                "Desire-Cave-NPC-" + npc.npcId() + "-action-" + action);
        pendingPortal = destination;
        pendingPortalReady = true;
        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT Desire-Cave-NPC-teleport target="
                                + playerObjectId() + " gfx="
                                + ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
            }
        }
        sendEncrypted(Protocol.portal(mapId, x, y),
                "S_PORTAL Desire-Cave npc=" + npc.npcId() + " action=" + action
                        + " map=" + mapId + " x=" + x + " y=" + y);
    }

    private void activateClassicWorldDesireSpyMorph() throws IOException {
        polymorphStatus.clear();
        desireQuestPolymorphGfx =
                ClassicWorldDesireCaveActionCatalog.DESIRE_SPY_GFX;
        desireQuestPolymorphDeadlineNanos = System.nanoTime()
                + ClassicWorldDesireCaveActionCatalog.DESIRE_SPY_MORPH_SECONDS
                        * 1_000_000_000L;
        int walkAction = BattleAnimationCatalog.get().resolveEquippedWalkAction(
                desireQuestPolymorphGfx, currentWeaponWalkAction());
        byte[] appearance = Protocol.polymorph(
                playerObjectId(), desireQuestPolymorphGfx, walkAction);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(appearance,
                        "S_POLYMORPH Desire-spy target=" + playerObjectId()
                                + " gfx=" + desireQuestPolymorphGfx
                                + " walk-action=" + walkAction);
            }
        }
    }

    private void handleDwarfCastleCommanderAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        boolean accepted = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.action().equalsIgnoreCase(
                        ClassicWorldDwarfCastleCatalog.COMMANDER_DEMAND_ACTION)
                && request.parameter().isEmpty()
                && classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) <= 5;
        if (!accepted) {
            System.out.println("[LiTo] C_HACTION Dwarf commander rejected action="
                    + request.action());
            return;
        }
        GameStateStore.MercenaryAssignment assignment =
                state.mercenaryAssignment(stateCharacter());
        // The preserved castle_soldier catalog has no castle-6 row, so the
        // native commander cannot materialize a proved mercenary template.
        sendEncrypted(Protocol.hypertext(npc.objectId(),
                        ClassicWorldDwarfCastleCatalog.COMMANDER_EMPTY_HTML,
                        "", List.of()),
                "S_HYPERTEXT Dwarf-commander html="
                        + ClassicWorldDwarfCastleCatalog.COMMANDER_EMPTY_HTML
                        + " assigned=" + assignment.mercenaries().total()
                        + " proved-catalog=false");
    }

