    private void handleAdenCastleGatekeeperAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        boolean open = request.action().equalsIgnoreCase(
                ClassicWorldAdenToiCatalog.OPEN_INNER_GATE_ACTION);
        boolean close = request.action().equalsIgnoreCase(
                ClassicWorldAdenToiCatalog.CLOSE_INNER_GATE_ACTION);
        CastleSummary castle = selectedLegacyCastle();
        boolean member = castle != null
                && castle.castleId() == ClassicWorldAdenToiCatalog.CASTLE_ID;
        boolean accepted = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty() && (open || close) && member
                && classicWorldMapId == ClassicWorldMapCatalog.WORLD_TREE_MAP_ID
                && classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) <= 5;
        if (!accepted) {
            System.out.println("[LiTo] C_HACTION Aden gatekeeper rejected action="
                    + request.action() + " member=" + member);
            return;
        }
        boolean isNowWar = hub.classicCastleWarActive(
                selectedClassicServerName, ClassicWorldAdenToiCatalog.CASTLE_ID);
        if (ClassicWorldCastleGateRules.blocksKeeperToggle(
                ClassicWorldAdenToiCatalog.CASTLE_ID, npc.npcId(), isNowWar)) {
            sendEncrypted(Protocol.closeHypertext(npc.objectId()),
                    "S_HYPERTEXT_CLOSE Aden-gatekeeper war-blocked=" + npc.npcId());
            System.out.println("[LiTo] C_HACTION Aden gatekeeper war-blocked keeper="
                    + npc.npcId());
            return;
        }
        List<ClassicWorldAdenCastleDoorState.Snapshot> changed =
                hub.setAdenCastleDoorsOpen(npc.npcId(), open);
        if (changed.isEmpty()) {
            throw new IOException("Aden gatekeeper has no selected-source door");
        }
        broadcastAdenCastleDoors(changed, open ? "gatekeeper-open" : "gatekeeper-close");
        sendEncrypted(Protocol.closeHypertext(npc.objectId()),
                "S_HYPERTEXT_CLOSE Aden-gatekeeper=" + npc.npcId());
    }

