    private void handleHeineCastleGuardAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        boolean accepted = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && request.action().equalsIgnoreCase(
                        ClassicWorldHeineCatalog.ASK_WAR_TIME_ACTION)
                && classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) <= 5;
        if (!accepted) {
            // The source declarewar branch is client-special and requires the
            // native clan-war prompt packet; do not fake it as a generic action.
            System.out.println("[LiTo] C_HACTION Heine guard deferred action="
                    + request.action());
            return;
        }
        CastleSummary castle = selectedCastleById(ClassicWorldHeineCatalog.CASTLE_ID);
        long sourceWarTime = castle == null ? 0 : castle.warTimeMillis();
        long currentWarTime = castle == null ? 0
                : hub.classicCastleWarStartMillis(
                        selectedClassicServerName, castle.castleId(), sourceWarTime);
        ZonedDateTime war = Instant.ofEpochMilli(currentWarTime)
                .atZone(ZoneId.of("Asia/Taipei"));
        List<String> arguments = List.of("", Integer.toString(war.getYear()),
                Integer.toString(war.getMonthValue()),
                Integer.toString(war.getDayOfMonth()),
                Integer.toString(war.getHour()), Integer.toString(war.getMinute()));
        sendEncrypted(Protocol.hypertext(npc.objectId(), "heguard7", "", arguments),
                "S_HYPERTEXT Heine-guard html=heguard7 war=" + war);
    }

