    private void sendQuestMonsters(String reason) throws IOException {
        for (BattleQuestEncounter.Snapshot monster : hub.visibleQuestMonsters(
                currentRoomId, this)) {
            sendEncrypted(Protocol.questMonster(monster),
                    "S_PUT_OBJECT quest-monster=" + monster.objectId()
                            + " force=" + monster.force()
                            + " room=" + monster.roomNumber()
                            + " npc=" + monster.npcId()
                            + " gfx=" + monster.gfx()
                            + " hp=" + monster.hp() + "/" + monster.maxHp()
                            + " x=" + monster.x() + " y=" + monster.y()
                            + " reason=" + reason);
            long nowNanos = System.nanoTime();
            if (hub.questMonsterFreezeActive(
                        currentRoomId, monster.objectId(), nowNanos)
                    || hub.questMonsterEarthBindActive(
                        currentRoomId, monster.objectId(), nowNanos)
                    || hub.questMonsterParalysisActive(
                        currentRoomId, monster.objectId(), nowNanos)) {
                sendEncrypted(Protocol.poison(monster.objectId(), 2),
                        "S_POISON quest-monster=" + monster.objectId()
                                + " type=2 reason=" + reason);
            }
            if (hub.questMonsterSlowActive(
                    currentRoomId, monster.objectId(), nowNanos)) {
                sendEncrypted(Protocol.speed(
                                monster.objectId(), Protocol.SpeedMode.SLOW, 0),
                        "S_SPEED quest-monster=" + monster.objectId()
                                + " type=" + BattleTimedStatus.SLOW
                                + " duration=0 reason=" + reason);
            } else if (hub.questMonsterHasteActive(
                    currentRoomId, monster.objectId(), nowNanos)) {
                sendEncrypted(Protocol.speed(
                                monster.objectId(), Protocol.SpeedMode.HASTE, 0),
                        "S_SPEED quest-monster=" + monster.objectId()
                                + " type=" + BattleTimedStatus.HASTE
                                + " duration=0 reason=" + reason);
            }
        }
    }

