    private void sendRepairNpc(String reason) throws IOException {
        ArenaMapCatalog.Point npc = repairNpcPoint();
        if (npc == null) return;
        int walkAction = BattleAnimationCatalog.get().requireWalkAction(
                REPAIR_NPC_GFX, BattleActionCodes.WALK);
        sendEncrypted(Protocol.battleActor(repairNpcObjectId(), npc.x(), npc.y(),
                        REPAIR_NPC_GFX, walkAction, 0, BattleTimedStatus.NORMAL,
                        REPAIR_NPC_NAME, "", 0, 0, "", 100, 1),
                "S_PUT_OBJECT passive-repair-npc=" + repairNpcObjectId()
                        + " gfx=" + REPAIR_NPC_GFX + " walk-action=" + walkAction);
        if (!config.repairNpcAppearanceSpeech().isEmpty()) {
            String speech = REPAIR_NPC_NAME + ": " + config.repairNpcAppearanceSpeech();
            sendEncrypted(Protocol.sayCode(
                            0, repairNpcObjectId(), speech, npc.x(), npc.y()),
                    "S_SAY_CODE repair-npc-appearance object=" + repairNpcObjectId()
                            + " x=" + npc.x() + " y=" + npc.y()
                            + " reason=" + reason);
        }
        System.out.println("[LiTo] repair NPC rebuilt object=" + repairNpcObjectId()
                + " gfx=" + REPAIR_NPC_GFX + " x=" + npc.x() + " y=" + npc.y()
                + " reason=" + reason);
    }

