    private long activeInteractionContext() {
        if (phase == Phase.WORLD && ClassicWorldMapCatalog.supports(classicWorldMapId)) {
            return -((long) classicWorldMapId + 1L);
        }
        if (phase == Phase.BATTLE) return currentRoomId;
        return 0;
    }

    private ArenaMapCatalog.Point activeWarehouseNpcPoint(long objectId) {
        if (phase == Phase.BATTLE && objectId == warehouseNpcObjectId()) {
            return warehouseNpcPoint();
        }
        if (phase != Phase.WORLD
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) return null;
        ClassicWorldNpcCatalog.StaticNpc npc =
                ClassicWorldNpcCatalog.fixedWarehouse(classicWorldMapId, objectId);
        return npc == null ? null : new ArenaMapCatalog.Point(npc.x(), npc.y());
    }

    private ArenaMapCatalog.Point nearestActiveWarehouseNpcPoint() {
        if (phase == Phase.BATTLE) return warehouseNpcPoint();
        if (phase != Phase.WORLD
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) return null;
        ArenaMapCatalog.Point nearest = null;
        int nearestDistance = Integer.MAX_VALUE;
        for (ClassicWorldNpcCatalog.StaticNpc npc
                : ClassicWorldNpcCatalog.fixedWarehouses(classicWorldMapId)) {
            ArenaMapCatalog.Point point = new ArenaMapCatalog.Point(npc.x(), npc.y());
            int distance = classicNpcDistance(point);
            if (distance < nearestDistance) {
                nearest = point;
                nearestDistance = distance;
            }
        }
        return nearest;
    }

    private void sendCastleStewardNpc(String reason) throws IOException {
        ArenaMapCatalog.Point npc = castleStewardNpcPoint();
        if (npc == null) return;
        CastleSummary castle = selectedLegacyCastle();
        CastleStewardProfile profile = castleStewardProfile(
                castle == null ? 5 : castle.castleId());
        int walkAction = BattleAnimationCatalog.get().requireWalkAction(
                profile.gfx(), BattleActionCodes.WALK);
        sendEncrypted(Protocol.battleActor(castleStewardNpcObjectId(), npc.x(), npc.y(),
                        profile.gfx(), walkAction, 0, BattleTimedStatus.NORMAL,
                        profile.name(), "", 0, 0, "", 100, 1),
                "S_PUT_OBJECT passive-castle-steward=" + castleStewardNpcObjectId()
                        + " castle=" + (castle == null ? 0 : castle.castleId())
                        + " gfx=" + profile.gfx() + " walk-action=" + walkAction
                        + " reason=" + reason);
    }

