    private void broadcastGroundItem(BattleGroundItems.Item item, String reason)
            throws IOException {
        byte[] packet = Protocol.groundItem(
                item.objectId(), item.x(), item.y(), item.definition().groundGfx(),
                item.quantity(), item.displayName());
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, item.x(), item.y())) continue;
            member.sendEncrypted(packet,
                    "S_PUT_OBJECT ground-item=" + item.objectId()
                            + " catalog=" + item.definition().catalogId()
                            + " quantity=" + item.quantity() + " reason=" + reason);
        }
    }

    private void broadcastGroundTake(GameHub.GroundTake take, String reason)
            throws IOException {
        if (take.remaining() == null) {
            byte[] removed = Protocol.removeObject(take.taken().objectId());
            for (ClientSession member : hub.roomMembers(currentRoomId)) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY,
                        take.taken().x(), take.taken().y())) continue;
                member.sendEncrypted(removed,
                        "S_REMOVE_OBJECT ground-item=" + take.taken().objectId()
                                + " reason=" + reason);
            }
            return;
        }
        broadcastGroundItem(take.remaining(), reason + "-remaining");
    }

    private void sendClassicWorldGroundItems(String reason) throws IOException {
        for (ClassicWorldGroundItems.Item item : hub.classicWorldGroundItemsInScreen(
                classicWorldMapId, classicWorldInstanceId, positionX, positionY)) {
            sendClassicWorldGroundItem(item, reason);
        }
    }

    private void sendClassicWorldGroundItem(
            ClassicWorldGroundItems.Item item, String reason) throws IOException {
        sendEncrypted(Protocol.groundItem(
                        item.objectId(), item.x(), item.y(), item.definition().groundGfx(),
                        item.quantity(), item.displayName()),
                "S_PUT_OBJECT ground-item=" + item.objectId()
                        + " catalog=" + item.definition().catalogId()
                        + " quantity=" + item.quantity()
                        + " source-npc=" + item.sourceNpcId() + " reason=" + reason);
    }

    private void broadcastClassicWorldGroundItem(
            ClassicWorldGroundItems.Item item, String reason) throws IOException {
        if (item == null) return;
        for (ClientSession member : hub.classicWorldMembers(
                item.mapId(), item.instanceId())) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, item.x(), item.y())) continue;
            member.sendClassicWorldGroundItem(item, reason);
        }
    }

    private void broadcastClassicWorldGroundTake(
            GameHub.ClassicGroundTake take, String reason) throws IOException {
        if (take == null) return;
        ClassicWorldGroundItems.Item item = take.taken();
        if (take.remaining() != null) {
            broadcastClassicWorldGroundItem(take.remaining(), reason + "-remaining");
            return;
        }
        byte[] removed = Protocol.removeObject(item.objectId());
        for (ClientSession member : hub.classicWorldMembers(
                item.mapId(), item.instanceId())) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, item.x(), item.y())) continue;
            member.sendEncrypted(removed,
                    "S_REMOVE_OBJECT ground-item=" + item.objectId()
                            + " source-npc=" + item.sourceNpcId() + " reason=" + reason);
        }
    }

    /**
     * Native pet getitem/collect(false): return carried items to the owner and
     * place only inventory overflow at the companion's current coordinates.
     */
    private void transferCompanionItems(BattleCompanion owned) throws IOException {
        if (phase == Phase.WORLD) {
            transferClassicWorldCompanionItems(owned, true);
            return;
        }
        record Overflow(RuntimeInventory.Item carried, BattleGroundItems.Item ground) {}
        BattleCompanion.Snapshot companion = owned.snapshot();
        if (!companion.active()) return;
        List<RuntimeInventory.Item> carried = owned.carriedItems();
        if (carried.isEmpty()) {
            System.out.println("[LiTo] companion getitem owner=" + playerName()
                    + " transferred=0 dropped=0 retained=0");
            return;
        }

        RuntimeInventory next = inventory.copy();
        List<RuntimeInventory.Item> transferred = new ArrayList<>();
        List<Overflow> overflow = new ArrayList<>();
        for (RuntimeInventory.Item item : carried) {
            RuntimeInventory admitted = next.copy();
            boolean capacity = admitted.add(item, item.quantity());
            boolean weight = capacity
                    && permitsInventoryAddition(next, item.definition(), item.quantity());
            if (capacity && weight) {
                next = admitted;
                transferred.add(item);
                continue;
            }
            if (!capacity) sendInventoryCapacityOver("companion-collect");
            else sendInventoryWeightOver("companion-collect");
            BattleGroundItems.Item ground = hub.putGroundItem(
                    currentRoomId, this, item, item.quantity(),
                    companion.x(), companion.y());
            if (ground != null) overflow.add(new Overflow(item, ground));
        }

        for (RuntimeInventory.Item item : transferred) {
            if (!owned.removeCarriedItem(item.objectId(), item.quantity())) {
                throw new IllegalStateException("staged companion transfer could not commit");
            }
        }
        for (Overflow entry : overflow) {
            RuntimeInventory.Item item = entry.carried();
            if (!owned.removeCarriedItem(item.objectId(), item.quantity())) {
                throw new IllegalStateException("staged companion overflow could not commit");
            }
        }

        RuntimeInventory previous = inventory;
        inventory = next;
        sendInventoryDelta(previous, inventory);
        for (Overflow entry : overflow) {
            broadcastGroundItem(entry.ground(), "companion-getitem-overflow");
        }
        if (!transferred.isEmpty()) {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        }
        System.out.println("[LiTo] companion getitem owner=" + playerName()
                + " transferred=" + transferred.size() + " dropped=" + overflow.size()
                + " retained=" + owned.carriedItems().size());
    }

    /** Native companion collect: inventory first, classic-map ground on overflow. */
    private void transferClassicWorldCompanionItems(
            BattleCompanion owned, boolean notifyOwner) throws IOException {
        record Overflow(RuntimeInventory.Item carried, ClassicWorldGroundItems.Item ground) {}
        BattleCompanion.Snapshot companion = owned.snapshot();
        if (!companion.active() || !companion.kind().classicWorldEligible()
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) return;
        List<RuntimeInventory.Item> carried = owned.carriedItems();
        if (carried.isEmpty()) return;

        RuntimeInventory next = inventory.copy();
        List<RuntimeInventory.Item> transferred = new ArrayList<>();
        List<Overflow> overflow = new ArrayList<>();
        for (RuntimeInventory.Item item : carried) {
            RuntimeInventory admitted = next.copy();
            boolean capacity = admitted.add(item, item.quantity());
            boolean weight = capacity
                    && permitsInventoryAddition(next, item.definition(), item.quantity());
            if (capacity && weight) {
                next = admitted;
                transferred.add(item);
                continue;
            }
            if (notifyOwner) {
                if (!capacity) sendInventoryCapacityOver("classic-world-pet-collect");
                else sendInventoryWeightOver("classic-world-pet-collect");
            }
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    classicWorldMapId, classicWorldInstanceId, item, item.quantity(),
                    companion.x(), companion.y(), companion.npcId());
            if (ground == null) {
                throw new IllegalStateException(
                        "validated classic WORLD companion overflow was rejected");
            }
            overflow.add(new Overflow(item, ground));
        }

        for (RuntimeInventory.Item item : transferred) {
            if (!owned.removeCarriedItem(item.objectId(), item.quantity())) {
                throw new IllegalStateException("staged classic WORLD companion transfer could not commit");
            }
        }
        for (Overflow entry : overflow) {
            RuntimeInventory.Item item = entry.carried();
            if (!owned.removeCarriedItem(item.objectId(), item.quantity())) {
                throw new IllegalStateException("staged classic WORLD companion overflow could not commit");
            }
        }

        RuntimeInventory previous = inventory;
        inventory = next;
        if (!transferred.isEmpty()) {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
            if (notifyOwner) sendInventoryDelta(previous, inventory);
        }
        for (Overflow entry : overflow) {
            broadcastClassicWorldGroundItem(entry.ground(),
                    "classic-world-pet-collect-overflow");
        }
        System.out.println("[LiTo] classic-world companion collect owner=" + playerName()
                + " companion=" + companion.objectId() + " transferred=" + transferred.size()
                + " dropped=" + overflow.size() + " retained="
                + owned.carriedItems().size() + " disconnect=" + !notifyOwner);
    }

    private void collectClassicWorldPetsOnDisconnect() throws IOException {
        List<BattleCompanion> pets;
        synchronized (tamedCompanions) {
            pets = tamedCompanions.stream()
                    .filter(companion -> companion.snapshot().kind()
                            == BattleCompanion.Kind.PET)
                    .toList();
        }
        for (BattleCompanion pet : pets) {
            transferClassicWorldCompanionItems(pet, false);
            GameStateStore.PetState durable = pet.durablePetState();
            if (durable != null) state.savePet(durable);
        }
    }

