    private void broadcastClassicWorldRescueStaticClaim(
            ClassicWorldNpcCatalog.StaticNpc source,
            ClassicWorldRescueFollowers.Snapshot claimed) throws IOException {
        for (ClientSession member : classicWorldMembers(source.mapId())) {
            boolean seesSource = BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, source.x(), source.y());
            if (seesSource) {
                member.sendEncrypted(Protocol.removeObject(source.objectId()),
                        "S_REMOVE_OBJECT rescue-static=" + source.objectId()
                                + " npc=" + source.npcId()
                                + " reason=follower-claim");
            }
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, claimed.x(), claimed.y())) {
                member.sendClassicWorldRescueFollower(claimed, "static-claim");
            }
            if (seesSource) {
                member.sendClassicWorldStaticNpc(source, "zero-delay-respawn");
            }
        }
    }

    private void broadcastClassicWorldRescueReplacement(
            ClassicWorldRescueFollowers.Snapshot before,
            ClassicWorldRescueFollowers.Snapshot after,
            String reason) throws IOException {
        for (ClientSession member : classicWorldMembers(
                ClassicWorldRescueFollowers.MAP_ID)) {
            if (before != null && BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, before.x(), before.y())) {
                member.sendEncrypted(Protocol.removeObject(before.objectId()),
                        "S_REMOVE_OBJECT rescue-follower=" + before.objectId()
                                + " kind=" + before.definition().kind()
                                + " reason=" + reason);
            }
            if (after != null && BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, after.x(), after.y())) {
                member.sendClassicWorldRescueFollower(after, reason);
            }
        }
    }

