    boolean classicWorldMonsterRetainedTargetEligible(int mapId) {
        return phase == Phase.WORLD && !observer && playerHp > 0
                && classicWorldMapId == mapId;
    }

    ClassicWorldMonsterAggressionCatalog.PlayerDisposition
            classicWorldMonsterDisposition(
                    ClassicWorldMonsterAggressionCatalog.Profile monster) {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null) return null;
        long nowNanos = System.nanoTime();
        BattlePolymorphCatalog.Form shape = polymorphStatus.active(nowNanos);
        return new ClassicWorldMonsterAggressionCatalog.PlayerDisposition(
                character.type(), baseBattleGfx(), battleGfx(), shape != null,
                invisible, nativeLawful(characterLawful()),
                state.factionKarma(stateCharacter()).level(),
                monster != null && monster.orcFamily()
                        && classicWorldOrcCastleOwner(character, nowNanos));
    }

    private boolean classicWorldOrcCastleOwner(
            CharacterSummary character, long nowNanos) {
        String clanName = character.clanName() == null ? "" : character.clanName().trim();
        if (clanName.isEmpty()) return false;
        String cacheKey = selectedClassicServerName + "\u0000" + clanName;
        if (cacheKey.equals(classicWorldOrcCastleCacheKey)
                && nowNanos < classicWorldOrcCastleCacheUntilNanos) {
            return classicWorldOrcCastleOwner;
        }
        boolean owner = false;
        try {
            CastleSummary orcCastle = effectiveClassicCastleById(2);
            owner = orcCastle != null
                    && orcCastle.clanName().equalsIgnoreCase(clanName);
        } catch (Exception error) {
            System.out.println("[LiTo] Orc-castle monster disposition lookup failed clan="
                    + clanName + ": " + error.getMessage());
        }
        classicWorldOrcCastleOwner = owner;
        classicWorldOrcCastleCacheKey = cacheKey;
        classicWorldOrcCastleCacheUntilNanos = nowNanos + 5_000_000_000L;
        return owner;
    }

    /** NPC60520 has selected-source agrocoi=1 and may acquire invisible PCs. */
    boolean classicWorldMonsterGuardAiEligible(int mapId) {
        return phase == Phase.WORLD && !observer && playerHp > 0
                && classicWorldMapId == mapId;
    }

    ClassicWorldGuardianCatalog.TargetDisposition classicWorldGuardianDisposition() {
        long nowEpochSeconds = state.currentEpochSeconds();
        boolean wanted = lastPkForElfEpochSeconds > 0
                && nowEpochSeconds >= lastPkForElfEpochSeconds
                && nowEpochSeconds - lastPkForElfEpochSeconds
                    <= ClassicWorldGuardianCatalog.WANTED_SECONDS;
        return ClassicWorldGuardianCatalog.disposition(isElfCharacter(), wanted);
    }

    boolean classicWorldGuardWanted() {
        return ClassicWorldGuardCatalog.wanted(
                lastPkEpochSeconds, state.currentEpochSeconds());
    }

    void serverClassicWorldGuardianWarning(
            ClassicWorldMonsterPopulation.Snapshot guardian,
            ClassicWorldGuardianCatalog.TargetDisposition disposition)
            throws IOException {
        if (!ClassicWorldGuardianCatalog.isGuardian(guardian)
                || disposition == null
                || disposition == ClassicWorldGuardianCatalog.TargetDisposition.NONE
                || phase != Phase.WORLD
                || guardian.mapId() != classicWorldMapId) return;
        boolean shout = disposition
                == ClassicWorldGuardianCatalog.TargetDisposition.INTRUDER;
        String text = shout
                ? "<" + guardian.template().nameId() + "> $"
                    + ClassicWorldGuardianCatalog.INTRUDER_MESSAGE
                : guardian.template().nameId() + ": $"
                    + ClassicWorldGuardianCatalog.ELF_MURDERER_MESSAGE;
        byte[] packet = Protocol.sayCode(shout ? 2 : 0,
                guardian.objectId(), text, guardian.x(), guardian.y());
        for (ClientSession member : classicWorldMembers(guardian.mapId())) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            guardian.x(), guardian.y())) continue;
            member.sendEncrypted(packet,
                    "S_SAY_CODE L1Guardian=" + guardian.objectId()
                            + " type=" + (shout ? 2 : 0)
                            + " disposition=" + disposition);
        }
    }

    /** L1Bow checkTg includes every visible PC, including corpses and invisibility. */
    boolean classicWorldBowTargetEligible(int mapId) {
        return phase == Phase.WORLD && classicWorldMapId == mapId;
    }

    void serverClassicWorldBowPlayerDamage(
            ClassicWorldNpcCatalog.StaticNpc bow) throws IOException {
        if (!ClassicWorldBowCatalog.isBow(bow)
                || !classicWorldBowTargetEligible(bow.mapId())
                || playerHp <= 0) return;
        double damage = ClassicWorldBowCatalog.DAMAGE;
        RuntimeInventory.Item weapon = inventory.equippedWeaponItem();
        if (weapon != null) {
            long catalogId = weapon.definition().catalogId();
            // Retained L1PcInstance applies the two self-damage axes before
            // Illusion Avatar and casts the completed double only once.
            if (catalogId == 145 || catalogId == 149) damage *= 1.5D;
        }
        takeClassicWorldDirectDamage(damage, bow.objectId());
    }

    void serverClassicWorldBowCompanionDamage(
            ClassicWorldNpcCatalog.StaticNpc bow,
            BattleCompanion.Snapshot companion) throws IOException {
        if (!ClassicWorldBowCatalog.isBow(bow) || companion == null
                || phase != Phase.WORLD || classicWorldMapId != bow.mapId()) return;
        BattleCompanion controlled = ownedCompanion(companion.objectId());
        if (controlled == null) return;
        applyClassicWorldMonsterCompanionDamage(
                controlled, companion, ClassicWorldBowCatalog.DAMAGE,
                bow.objectId(), "bow-aperture-death");
    }

    void serverClassicWorldBowProjectile(
            ClassicWorldNpcCatalog.StaticNpc bow, long targetObjectId,
            int targetX, int targetY) throws IOException {
        if (!ClassicWorldBowCatalog.isBow(bow)
                || phase != Phase.WORLD || classicWorldMapId != bow.mapId()
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, bow.x(), bow.y())) return;
        sendEncrypted(Protocol.classicWorldBowAttack(
                        bow.objectId(), targetObjectId, bow.heading(),
                        bow.x(), bow.y(), targetX, targetY),
                "S_ATTACK classic-world-bow=" + bow.objectId()
                        + " spawn=" + bow.spawnId() + " npc=" + bow.npcId()
                        + " target=" + targetObjectId + " damage="
                        + ClassicWorldBowCatalog.DAMAGE + " projectile-gfx="
                        + ClassicWorldBowCatalog.PROJECTILE_GFX + " source="
                        + bow.x() + "," + bow.y() + " endpoint="
                        + targetX + "," + targetY);
    }

    boolean classicWorldClanOwnsCastle(int castleId) {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null || character.clanName() == null
                || character.clanName().isBlank()) return false;
        try {
            CastleSummary castle = effectiveClassicCastleById(castleId);
            return castle != null && castle.clanName() != null
                    && castle.clanName().equalsIgnoreCase(character.clanName());
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] classic-world castle ownership lookup failed"
                    + " player=" + playerName() + " castle=" + castleId
                    + " reason=" + sourceFailure.getMessage());
            return false;
        }
    }

    private int classicWorldMonsterPanicAdjustedAbility(
            ClassicWorldMonsterPopulation.Snapshot actor,
            int sourceAbility, long nowNanos) {
        int modifier = hub.classicWorldMonsterPanicAbilityScoreModifier(
                actor.mapId(), classicWorldInstanceId,
                actor.objectId(), nowNanos);
        return Math.max(1, Math.min(254,
                Math.addExact(sourceAbility, modifier)));
    }

    private int timeAttackActorPanicAdjustedAbility(
            long roomId, BattleTimeAttackEncounter.Snapshot actor,
            int sourceAbility, long nowNanos) {
        int modifier = hub.timeAttackActorPanicAbilityScoreModifier(
                roomId, actor.objectId(), nowNanos);
        return Math.max(1, Math.min(254,
                Math.addExact(sourceAbility, modifier)));
    }

    void serverClassicWorldMonsterMoved(
            ClassicWorldMonsterPopulation.Movement movement) throws IOException {
        if (movement == null || phase != Phase.WORLD
                || classicWorldMapId != movement.after().mapId()) return;
        ClassicWorldMonsterPopulation.Snapshot before = movement.before();
        ClassicWorldMonsterPopulation.Snapshot after = movement.after();
        boolean sawBefore = BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, before.x(), before.y());
        boolean seesAfter = BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, after.x(), after.y());
        if (sawBefore && !seesAfter) {
            sendEncrypted(Protocol.removeObject(after.objectId()),
                    "S_REMOVE_OBJECT classic-world-monster=" + after.objectId()
                            + " reason=ai-screen-exit");
        } else if (!sawBefore && seesAfter) {
            sendClassicWorldMonster(after, "ai-screen-enter");
        } else if (seesAfter) {
            sendEncrypted(new Protocol.Writer().c(Protocol.S_MOVE_OBJECT)
                            .d(after.objectId()).h(before.x()).h(before.y())
                            .c(after.heading()).bytes(),
                    "S_MOVE_OBJECT classic-world-monster=" + after.objectId()
                            + " source=" + before.x() + "," + before.y()
                            + " destination=" + after.x() + "," + after.y()
                            + " heading=" + after.heading());
        }
        if (movement.teleportedHome()) {
            serverClassicWorldMonsterHomeTeleport(
                    movement.after(), movement.settled(),
                    "movement-distance");
        }
    }

    void serverClassicWorldMonsterIdleMovement(
            ClassicWorldMonsterPopulation.IdleMovement movement)
            throws IOException {
        if (movement == null) return;
        serverClassicWorldMonsterMoved(
                new ClassicWorldMonsterPopulation.Movement(
                        movement.before(), movement.moved()));
        if (!movement.teleportedHome() || phase != Phase.WORLD
                || classicWorldMapId != movement.after().mapId()) return;
        serverClassicWorldMonsterHomeTeleport(
                movement.moved(), movement.after(), "movement-distance");
    }

    void serverClassicWorldMonsterPickedItem(
            ClassicWorldMonsterPopulation.ItemPickup pickup,
            ClassicWorldGroundItems.Item item) throws IOException {
        if (pickup == null || item == null || phase != Phase.WORLD
                || classicWorldMapId != item.mapId()
                || classicWorldInstanceId != item.instanceId()
                || pickup.itemObjectId() != item.objectId()
                || pickup.actor().objectId() == item.objectId()
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, item.x(), item.y())) {
            return;
        }
        sendEncrypted(Protocol.removeObject(item.objectId()),
                "S_REMOVE_OBJECT ground-item=" + item.objectId()
                        + " reason=monster-pickup monster="
                        + pickup.actor().objectId() + " npc="
                        + pickup.actor().npcId() + " catalog="
                        + pickup.catalogId() + " quantity="
                        + pickup.quantity() + " destination="
                        + pickup.destinationObjectId() + " refinements="
                        + pickup.refinements().size() + " digest="
                        + pickup.digestSeconds());
    }

    void serverClassicWorldMonsterUsedItem(
            ClassicWorldMonsterPopulation.ItemUse use) throws IOException {
        if (use == null || phase != Phase.WORLD
                || classicWorldMapId != use.before().mapId()
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY,
                        use.before().x(), use.before().y())) {
            return;
        }
        if (use.kind() == ClassicWorldMonsterPopulation.ItemUseKind.HASTE) {
            // Retained useHastePotion broadcasts S_SkillHaste before gfx191.
            sendEncrypted(Protocol.speed(
                            use.before().objectId(),
                            Protocol.SpeedMode.HASTE,
                            use.durationSeconds()),
                    "S_SPEED classic-world-monster=" + use.before().objectId()
                            + " type=" + BattleTimedStatus.HASTE
                            + " duration=" + use.durationSeconds()
                            + " reason=monster-item catalog=" + use.catalogId());
        }
        sendEncrypted(Protocol.effectObject(
                        use.before().objectId(), use.effectGfx()),
                "S_EFFECT classic-world-monster=" + use.before().objectId()
                        + " gfx=" + use.effectGfx()
                        + " reason=monster-item kind=" + use.kind()
                        + " catalog=" + use.catalogId()
                        + " hp-delta=" + use.appliedHpDelta());
    }

    void serverClassicWorldMonsterHomeReset(
            ClassicWorldMonsterPopulation.HomeReset reset) throws IOException {
        if (reset == null || phase != Phase.WORLD
                || classicWorldMapId != reset.after().mapId()) return;
        serverClassicWorldMonsterHomeTeleport(
                reset.before(), reset.after(), "no-visible-player");
    }

    void serverClassicWorldMonsterNearTeleport(
            ClassicWorldMonsterPopulation.NearTeleport teleport)
            throws IOException {
        if (teleport == null || phase != Phase.WORLD
                || classicWorldMapId != teleport.after().mapId()) return;
        ClassicWorldMonsterPopulation.Snapshot before = teleport.before();
        ClassicWorldMonsterPopulation.Snapshot after = teleport.after();
        boolean sawBefore = BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, before.x(), before.y());
        boolean seesAfter = BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, after.x(), after.y());
        String reason = teleport.kind() ==
                ClassicWorldMonsterPopulation.NearTeleportKind.FIRST_FOUND
                        ? "first-found" : "random-pursuit";
        if (sawBefore) {
            // Retained teleportInternal first broadcasts gfx169, then removes
            // the previous known object before normal recognition rebuilds it.
            sendEncrypted(Protocol.effectObject(before.objectId(), 169),
                    "S_EFFECT classic-world-monster-near=" + before.objectId()
                            + " gfx=169 reason=" + reason);
            sendEncrypted(Protocol.removeObject(before.objectId()),
                    "S_REMOVE_OBJECT classic-world-monster-near="
                            + before.objectId() + " reason=" + reason);
        }
        if (seesAfter) {
            sendClassicWorldMonster(after,
                    "monster-near-teleport-" + reason);
        }
    }

    private void serverClassicWorldMonsterHomeTeleport(
            ClassicWorldMonsterPopulation.Snapshot before,
            ClassicWorldMonsterPopulation.Snapshot after,
            String reason) throws IOException {
        boolean sawBefore = BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, before.x(), before.y());
        boolean seesAfter = BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, after.x(), after.y());
        if (sawBefore) {
            sendEncrypted(Protocol.effectObject(before.objectId(), 169),
                    "S_EFFECT classic-world-monster-home=" + before.objectId()
                            + " gfx=169 reason=" + reason);
            sendEncrypted(Protocol.removeObject(before.objectId()),
                    "S_REMOVE_OBJECT classic-world-monster-home="
                            + before.objectId() + " reason=" + reason);
        }
        if (seesAfter) {
            sendClassicWorldMonster(after,
                    "monster-home-teleport-" + reason);
        }
    }

    void serverClassicWorldGuardHomecoming(
            ClassicWorldMonsterPopulation.GuardHomecoming homecoming)
            throws IOException {
        if (homecoming == null || phase != Phase.WORLD
                || classicWorldMapId != homecoming.after().mapId()) return;
        if (!homecoming.teleported()) {
            serverClassicWorldMonsterMoved(
                    new ClassicWorldMonsterPopulation.Movement(
                            homecoming.before(), homecoming.after()));
            return;
        }
        ClassicWorldMonsterPopulation.Snapshot before = homecoming.before();
        ClassicWorldMonsterPopulation.Snapshot after = homecoming.after();
        boolean sawBefore = BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, before.x(), before.y());
        boolean seesAfter = BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, after.x(), after.y());
        if (sawBefore) {
            sendEncrypted(Protocol.effectObject(before.objectId(), 169),
                    "S_EFFECT L1Guard home-teleport=" + before.objectId()
                            + " gfx=169");
            sendEncrypted(Protocol.removeObject(before.objectId()),
                    "S_REMOVE_OBJECT L1Guard home-teleport="
                            + before.objectId());
        }
        if (seesAfter) {
            sendClassicWorldMonster(after, "L1Guard-home-teleport");
        }
    }

    void serverClassicWorldMonsterAttack(
            ClassicWorldMonsterPopulation.Attack attack) throws IOException {
        if (attack == null || attack.targetObjectId() != playerObjectId()) return;
        ClassicWorldMonsterPopulation.Snapshot actor = attack.attacker();
        boolean monsterGuard = actor.npcId() == ClassicWorldMonsterGuardCatalog.NPC_ID
                && ClassicWorldMonsterGuardCatalog.target(
                        actor.mapId(), actor.objectId()) != null;
        boolean eligible = monsterGuard
                ? classicWorldMonsterGuardAiEligible(actor.mapId())
                : classicWorldMonsterRetainedTargetEligible(actor.mapId());
        ClassicWorldMapCatalog.ClassicMap actorMap =
                ClassicWorldMapCatalog.forMap(actor.mapId());
        boolean attackPosition = monsterGuard
                ? ClassicWorldMonsterGuardCatalog.attackPosition(
                        actorMap, actor.x(), actor.y(), positionX, positionY,
                        actor.template().attackRange())
                : actorMap.attackPosition(
                        actor.x(), actor.y(), positionX, positionY,
                        actor.template().attackRange());
        if (!eligible || attack.targetX() != positionX
                || attack.targetY() != positionY || !attackPosition) return;

        long attackNowNanos = System.nanoTime();
        int actorStrength = classicWorldMonsterPanicAdjustedAbility(
                actor, actor.template().strength(), attackNowNanos);
        int distance = Math.max(Math.abs(actor.x() - positionX),
                Math.abs(actor.y() - positionY));
        int d20 = config.uncannyDodgeHitFixtureD20() > 0
                ? config.uncannyDodgeHitFixtureD20()
                : ThreadLocalRandom.current().nextInt(1, 21);
        int targetArmorClass = battleArmorClass();
        int negativeAcRoll = targetArmorClass < 0
                ? ThreadLocalRandom.current().nextInt(1,
                    BattleNpcPhysicalAttack.negativeAcRollMaximum(
                            targetArmorClass) + 1)
                : 0;
        int dodgeModifier = effectivePhysicalDodge(attackNowNanos);
        int dodgeDown = effectivePhysicalDodgeDown(attackNowNanos);
        int hitChance = BattleNpcPhysicalAttack.hitChance(
                actor.template().level(), 0, targetArmorClass,
                dodgeModifier, dodgeDown, d20, negativeAcRoll);
        int d100 = config.uncannyDodgeHitFixtureD100() > 0
                ? config.uncannyDodgeHitFixtureD100()
                : ThreadLocalRandom.current().nextInt(1, 101);
        boolean hit = !config.battlePhysicalHitEnabled()
                || BattleNpcPhysicalAttack.hits(hitChance, d100);
        boolean rangedEvasionChecked = false;
        int rangedEvasionRate = 0;
        int rangedEvasionRoll = 0;
        if (hit && config.battlePhysicalHitEnabled()
                && actor.template().ranged() >= 10 && distance >= 2
                && hitChance > d100) {
            rangedEvasionChecked = true;
            rangedEvasionRate = effectiveRangedEvasionRate(attackNowNanos);
            rangedEvasionRoll = config.rangedEvasionFixtureD100() > 0
                    ? config.rangedEvasionFixtureD100()
                    : ThreadLocalRandom.current().nextInt(1, 101);
            hit = BattleRangedEvasion.hitsAfterEvasion(
                    rangedEvasionRate, rangedEvasionRoll);
        }

        boolean physicalHit = hit
                && !timedStatus.freezeActive(attackNowNanos)
                && !timedStatus.absoluteBarrierActive(attackNowNanos)
                && !timedStatus.earthBindActive(attackNowNanos);
        if (!physicalHit) hit = false;

        boolean shortDistance = !(distance > 1
                && actor.template().bowActionId() > 0);
        BattleCounterBarrier.Decision counterBarrier =
                BattleCounterBarrier.Decision.inactive();
        if (hit && shortDistance) {
            counterBarrier = counterBarrierDecision(
                    actor.template().level(), actor.template().magicResistance(),
                    actor.template().boss(), counterBarrierRoll(), attackNowNanos);
            if (counterBarrier.triggered()) {
                commitClassicWorldMonsterCounterBarrier(actor, counterBarrier);
                return;
            }
        }

        int rawDamage = 0;
        int sourceDamageBeforeWeaponBreak = 0;
        int weaponBreakStacks = hub.classicWorldMonsterWeaponBreakStacks(
                actor.mapId(), classicWorldInstanceId, actor.objectId());
        int acReduction = 0;
        int appliedDamage = 0;
        if (hit) {
            int levelRoll = ThreadLocalRandom.current().nextInt(
                    actor.template().level());
            int criticalRoll = ThreadLocalRandom.current().nextInt(100);
            int strengthDamage = requiredPhysicalGrowthStats().damage(
                    false, actorStrength);
            boolean undeadNight = switch (actor.template().undead()) {
                case 1, 3, 4 -> ClassicWorldNpcDamage.retainedNight(
                        System.currentTimeMillis());
                default -> false;
            };
            sourceDamageBeforeWeaponBreak = ClassicWorldNpcDamage.sourceDamage(
                    actor.template().level(), actorStrength,
                    strengthDamage, levelRoll, criticalRoll,
                    undeadNight, actor.template().boss());
            rawDamage = BattleWeaponBreak.damageAfterStacks(
                    sourceDamageBeforeWeaponBreak, weaponBreakStacks);
            int armBreakerModifier = shortDistance
                    ? hub.classicWorldMonsterArmBreakerMeleeDamageModifier(
                            actor.mapId(), classicWorldInstanceId,
                            actor.objectId(), attackNowNanos) : 0;
            rawDamage = Math.max(0,
                    Math.addExact(rawDamage, armBreakerModifier));
            CharacterSummary character = selectedCharacterSummary();
            int type = character == null ? 0 : character.type();
            int acMaximum = BattlePhysicalDefense.playerAcMaximum(
                    type, targetArmorClass);
            int acRoll = acMaximum == 0 ? 0
                    : ThreadLocalRandom.current().nextInt(acMaximum);
            acReduction = acMaximum == 0 ? 0
                    : acRoll + Math.max(1, acMaximum >> 3);
            appliedDamage = combatPhysicalDamageAfterArmorAndCooking(
                    Math.max(0, rawDamage - acReduction),
                    "classic-world-monster-" + actor.npcId());
            appliedDamage = BattleStrikerGale.damageAfterStatus(
                    appliedDamage,
                    timedStatus.strikerGaleActive(attackNowNanos),
                    BattleStrikerGale.npcAttackEligible(
                            distance, actor.template().bowActionId()));
            appliedDamage = earthBindProtectedCombatDamage(
                    appliedDamage, "classic-world-monster-" + actor.npcId());
        }

        if (physicalHit) {
            applyClassicWorldMonsterPoison(actor, attackNowNanos);
        }

        long projectileSequence = attack.projectile()
                ? ATTACK_SPELL_SEQUENCE.getAndIncrement() : 0;
        byte[] packet = attack.projectile()
                ? Protocol.rangedPhysicalAttack(
                        actor.template().projectileAttackAction(), actor.objectId(),
                        playerObjectId(), Math.min(0xFF, appliedDamage), actor.heading(),
                        projectileSequence, actor.template().bowActionId(),
                        actor.x(), actor.y(), positionX, positionY)
                : new Protocol.Writer().c(Protocol.S_ATTACK)
                        .c(BattleActionCodes.ATTACK).d(actor.objectId())
                        .d(playerObjectId()).c(Math.min(0xFF, appliedDamage))
                        .c(actor.heading()).d(0).bytes();
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, actor.x(), actor.y())
                    && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) continue;
            member.sendEncrypted(packet,
                    "S_ATTACK classic-world-monster=" + actor.objectId()
                            + " npc=" + actor.npcId() + " target=" + playerObjectId()
                            + " damage=" + appliedDamage + " raw=" + rawDamage
                            + " source-before-weapon-break="
                            + sourceDamageBeforeWeaponBreak
                            + " weapon-break-stacks=" + weaponBreakStacks
                            + " ac-reduction=" + acReduction + " hit=" + hit
                            + " physical-hit=" + physicalHit
                            + " hit-chance=" + hitChance + " d20=" + d20
                            + " d100=" + d100 + " dodge=" + dodgeModifier
                            + " projectile=" + attack.projectile()
                            + " projectile-gfx=" + actor.template().bowActionId()
                            + " projectile-sequence=" + projectileSequence
                            + " ranged-er-checked=" + rangedEvasionChecked
                            + " ranged-er=" + rangedEvasionRate
                            + " ranged-er-roll=" + rangedEvasionRoll);
        }
        if (appliedDamage > 0) {
            BattleJoyOfPainStatus.Lease joyLease =
                    hub.captureClassicWorldMonsterJoyOfPain(
                            classicWorldMapId, classicWorldInstanceId,
                            actor.objectId(), System.nanoTime());
            int joyDamage = joyLease == null ? 0
                    : currentJoyOfPainFeedbackDamage();
            takeClassicWorldMonsterDamage(appliedDamage, actor.objectId());
            tryMortalBodyClassicWorldMonsterReflection(
                    actor, "classic-world-monster-physical");
            applyJoyOfPainClassicWorldMonsterFeedback(
                    actor, joyLease, joyDamage,
                    "classic-world-monster-physical");
        }
    }

    private void commitClassicWorldMonsterCounterBarrier(
            ClassicWorldMonsterPopulation.Snapshot actor,
            BattleCounterBarrier.Decision decision) throws IOException {
        BattleSpellCatalog.CounterBarrierSpell spell =
                BattleSpellCatalog.counterBarrierSpell(
                        BattleSpellCatalog.COUNTER_BARRIER);
        byte[] effect = Protocol.effectObject(
                playerObjectId(), spell.triggerEffectGfx());
        byte[] reaction = Protocol.objectAction(
                actor.objectId(), BattleActionCodes.DAMAGE);
        String evidence = " defender=" + playerObjectId()
                + " attacker=" + actor.objectId()
                + " npc=" + actor.npcId()
                + " probability=" + decision.probability()
                + " roll=" + decision.roll()
                + " gfx=" + spell.triggerEffectGfx()
                + " action=" + BattleActionCodes.DAMAGE
                + " source-damage=" + decision.sourceDamage()
                + " original-attack-suppressed=true"
                + " recursive-reflection-suppressed=true";
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || (!BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            actor.x(), actor.y())
                        && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY))) continue;
            member.sendEncrypted(effect,
                    "S_EFFECT classic-world-monster Counter-Barrier" + evidence);
            member.sendEncrypted(reaction,
                    "S_ACTION classic-world-monster Counter-Barrier" + evidence);
        }

        ClassicWorldMonsterPopulation.Hit transition =
                hub.damageClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        actor.objectId(), playerObjectId(), decision.sourceDamage());
        if (transition == null) return;
        hub.provokeClassicWorldMonster(
                classicWorldMapId, classicWorldInstanceId,
                actor.objectId(), playerObjectId());
        for (BattleCompanion.Snapshot companion : classicWorldCompanionSnapshots()) {
            BattleCompanion controlled = ownedCompanion(companion.objectId());
            if (controlled != null) controlled.selectMasterTarget(actor.objectId());
        }
        ClassicWorldMonsterPopulation.Snapshot after = transition.after();
        byte[] ratio = Protocol.hitRatio(
                after.objectId(), after.currentHp(), after.maximumHp());
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            after.x(), after.y())) continue;
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO classic-world-monster=" + after.objectId()
                            + " hp=" + after.currentHp() + "/" + after.maximumHp()
                            + " source=counter-barrier");
            if (transition.diedNow()) {
                member.sendEncrypted(Protocol.objectAction(
                                after.objectId(), BattleActionCodes.DIE),
                        "S_ACTION classic-world-monster=" + after.objectId()
                                + " action=" + BattleActionCodes.DIE
                                + " source=counter-barrier");
            }
        }
        System.out.println("[LiTo] classic-world monster Counter Barrier triggered"
                + " defender=" + playerName() + evidence
                + " applied-damage=" + transition.appliedDamage()
                + " hp=" + after.currentHp() + "/" + after.maximumHp()
                + " died=" + transition.diedNow());
        if (transition.diedNow()) {
            handleClassicWorldWaterDragonDeath(after, transition.contributions());
            distributeClassicWorldMonsterRewards(after, transition.contributions());
            hub.scheduleClassicWorldMonsterLifecycle(
                    classicWorldInstanceId, after);
        }
    }

    private void tryMortalBodyClassicWorldMonsterReflection(
            ClassicWorldMonsterPopulation.Snapshot actor, String source)
            throws IOException {
        if (actor == null || phase != Phase.WORLD) return;
        ClassicWorldMonsterPopulation.Snapshot current =
                hub.classicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        actor.objectId());
        if (current == null || current.currentHp() <= 0) return;
        BattleSpellCatalog.MortalBodySpell spell =
                BattleSpellCatalog.mortalBodySpell(BattleSpellCatalog.MORTAL_BODY);
        BattleMortalBody.Decision decision = BattleMortalBody.decide(
                spell,
                abilityStatus.mortalBody(System.nanoTime()).remainingSeconds() != 0,
                battleLevel(), actor.template().level(),
                actor.template().boss(), mortalBodyRoll(), false,
                0, 0, 0, 0);
        if (!decision.triggered()) {
            if (decision.active()) {
                System.out.println("[LiTo] Mortal Body roll defender="
                        + playerName() + " npc-attacker=" + actor.objectId()
                        + " probability=" + decision.probability()
                        + " roll=" + decision.roll() + " triggered=false"
                        + " boss=" + actor.template().boss()
                        + " source=" + source);
            }
            return;
        }

        boolean sendReaction = BattleHitReactionSuppressCatalog
                .shouldSendDamageAction(actor.gfxId());
        if (sendReaction) {
            byte[] reaction = Protocol.objectAction(
                    actor.objectId(), BattleActionCodes.DAMAGE);
            for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                actor.x(), actor.y())
                            && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                positionX, positionY)) continue;
                member.sendEncrypted(reaction,
                        "S_ACTION classic-world-monster Mortal-Body attacker="
                                + actor.objectId() + " defender="
                                + playerObjectId() + " action="
                                + BattleActionCodes.DAMAGE + " source=" + source);
            }
        }
        ClassicWorldMonsterPopulation.Hit transition =
                hub.damageClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        actor.objectId(), playerObjectId(),
                        decision.reflectedDamage());
        if (transition == null) return;
        ClassicWorldMonsterPopulation.Snapshot after = transition.after();
        byte[] ratio = Protocol.hitRatio(
                after.objectId(), after.currentHp(), after.maximumHp());
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            after.x(), after.y())) continue;
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO classic-world-monster=" + after.objectId()
                            + " hp=" + after.currentHp() + "/"
                            + after.maximumHp() + " source=mortal-body");
            if (transition.diedNow()) {
                member.sendEncrypted(Protocol.objectAction(
                                after.objectId(), BattleActionCodes.DIE),
                        "S_ACTION classic-world-monster=" + after.objectId()
                                + " action=" + BattleActionCodes.DIE
                                + " source=mortal-body");
            }
        }
        System.out.println("[LiTo] Mortal Body triggered defender="
                + playerName() + " npc-attacker=" + actor.objectId()
                + " npc=" + actor.npcId()
                + " probability=" + decision.probability()
                + " roll=" + decision.roll()
                + " reflected-damage=" + transition.appliedDamage()
                + " hp=" + after.currentHp() + "/" + after.maximumHp()
                + " died=" + transition.diedNow()
                + " source=" + source
                + " boss-immune=false trigger-effect-gfx=none"
                + " damage-action-sent=" + sendReaction
                + " recursive-feedback-suppressed=true");
        if (transition.diedNow()) {
            handleClassicWorldWaterDragonDeath(after, transition.contributions());
            distributeClassicWorldMonsterRewards(after, transition.contributions());
            hub.scheduleClassicWorldMonsterLifecycle(
                    classicWorldInstanceId, after);
        }
    }

    private void applyJoyOfPainClassicWorldMonsterFeedback(
            ClassicWorldMonsterPopulation.Snapshot actor,
            BattleJoyOfPainStatus.Lease lease, int feedbackDamage,
            String source) throws IOException {
        if (actor == null || lease == null || phase != Phase.WORLD
                || !hub.consumeClassicWorldMonsterJoyOfPain(
                    classicWorldMapId, classicWorldInstanceId,
                    actor.objectId(), lease)) return;
        ClassicWorldMonsterPopulation.Snapshot current =
                hub.classicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        actor.objectId());
        if (feedbackDamage <= 0 || current == null
                || current.currentHp() <= 0) return;
        boolean sendReaction = BattleHitReactionSuppressCatalog
                .shouldSendDamageAction(actor.gfxId());
        if (sendReaction) {
            byte[] reaction = Protocol.objectAction(
                    actor.objectId(), BattleActionCodes.DAMAGE);
            for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            actor.x(), actor.y())
                            && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                positionX, positionY)) continue;
                member.sendEncrypted(reaction,
                        "S_ACTION classic-world-monster Joy-of-Pain attacker="
                                + actor.objectId() + " defender="
                                + playerObjectId() + " action="
                                + BattleActionCodes.DAMAGE + " source=" + source);
            }
        }
        ClassicWorldMonsterPopulation.Hit transition =
                hub.damageClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        actor.objectId(), playerObjectId(), feedbackDamage);
        if (transition == null) return;
        ClassicWorldMonsterPopulation.Snapshot after = transition.after();
        byte[] ratio = Protocol.hitRatio(
                after.objectId(), after.currentHp(), after.maximumHp());
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY,
                        after.x(), after.y())) continue;
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO classic-world-monster=" + after.objectId()
                            + " hp=" + after.currentHp() + "/"
                            + after.maximumHp() + " source=joy-of-pain");
            if (transition.diedNow()) {
                member.sendEncrypted(Protocol.objectAction(
                                after.objectId(), BattleActionCodes.DIE),
                        "S_ACTION classic-world-monster=" + after.objectId()
                                + " action=" + BattleActionCodes.DIE
                                + " source=joy-of-pain");
            }
        }
        System.out.println("[LiTo] Joy of Pain triggered world-monster="
                + actor.objectId() + " defender=" + playerName()
                + " feedback-damage=" + transition.appliedDamage()
                + " hp=" + after.currentHp() + "/" + after.maximumHp()
                + " died=" + transition.diedNow() + " source=" + source
                + " lease-consumed=true");
        if (transition.diedNow()) {
            handleClassicWorldWaterDragonDeath(after, transition.contributions());
            distributeClassicWorldMonsterRewards(after, transition.contributions());
            hub.scheduleClassicWorldMonsterLifecycle(
                    classicWorldInstanceId, after);
        }
    }

    private void applyClassicWorldMonsterPoison(
            ClassicWorldMonsterPopulation.Snapshot actor,
            long nowNanos) throws IOException {
        applyClassicWorldNpcPoison(
                actor.objectId(), actor.npcId(), actor.template().poisonAttack(),
                actor.template().paralysisAttack(), nowNanos,
                "classic-world-monster");
    }

    /** Retained L1AttackNpc poison_atk branch for PET/SUMMON/TAMED targets. */
    private void applyClassicWorldMonsterPoisonToCompanion(
            ClassicWorldMonsterPopulation.Snapshot actor,
            BattleCompanion controlled, BattleCompanion.Snapshot companion,
            long nowNanos) throws IOException {
        if (actor == null || controlled == null || companion == null
                || actor.template().poisonAttack() == 0
                || !companion.active() || companion.hp() <= 0
                || !companion.kind().classicWorldEligible()) return;
        int configuredRoll = config.classicWorldMonsterPoisonFixtureRoll();
        int oneBasedRoll = configuredRoll == 0
                ? ThreadLocalRandom.current().nextInt(1, 101) : configuredRoll;
        ClassicWorldMonsterPoisonAttack.Kind kind =
                ClassicWorldMonsterPoisonAttack.resolve(
                        actor.template().poisonAttack(), oneBasedRoll);
        BattleCompanion.NpcPoisonInstallation installation =
                controlled.activateNpcPoison(
                        kind, actor.objectId(), nowNanos);
        if (installation.applied()) {
            byte[] poison = Protocol.poison(companion.objectId(), 1);
            for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                companion.x(), companion.y())) continue;
                member.sendEncrypted(poison,
                        "S_POISON classic-world-companion="
                                + companion.objectId() + " type=1 reason=monster-"
                                + kind.name().toLowerCase(Locale.ROOT));
            }
        }
        System.out.println("[LiTo] classic-world monster poison companion npc="
                + actor.npcId() + " object=" + actor.objectId()
                + " target=" + companion.objectId() + " target-kind="
                + companion.kind() + " poison-atk="
                + actor.template().poisonAttack() + " paralysis-atk="
                + actor.template().paralysisAttack() + " roll=" + oneBasedRoll
                + " kind=" + kind + " native-damage-target="
                + installation.nativeDamageTarget() + " existing-poison="
                + installation.existingPoison() + " applied="
                + installation.applied()
                + " player-only-message=omitted"
                + " retained-paralysis-atk-handler=absent");
    }

    /** Shared retained L1AttackNpc poison_atk branch for monsters/pets/summons. */
    private void applyClassicWorldNpcPoison(
            long attackerObjectId, int attackerNpcId,
            int poisonAttack, int paralysisAttack,
            long nowNanos, String source) throws IOException {
        if (poisonAttack == 0 || playerHp <= 0) return;
        int configuredRoll = config.classicWorldMonsterPoisonFixtureRoll();
        int oneBasedRoll = configuredRoll == 0
                ? ThreadLocalRandom.current().nextInt(1, 101) : configuredRoll;
        ClassicWorldMonsterPoisonAttack.Kind kind =
                ClassicWorldMonsterPoisonAttack.resolve(
                        poisonAttack, oneBasedRoll);
        boolean poisonResistance = dragonEyeStatus.snapshot(nowNanos)
                .poisonResistance() > 0
                || !timedStatus.acceptsPoison(nowNanos, switch (kind) {
                    case DAMAGE -> BattleTimedStatus.PoisonKind.DAMAGE;
                    case SILENCE -> BattleTimedStatus.PoisonKind.SILENCE;
                    case PARALYSIS -> BattleTimedStatus.PoisonKind.PARALYSIS;
                    case NONE -> BattleTimedStatus.PoisonKind.DAMAGE;
                });
        boolean existingPoison = timedStatus.poisonActive(nowNanos)
                || timedStatus.poisonSilenceActive()
                || (classicWorldPoisonKind
                    == ClassicWorldMonsterPoisonAttack.Kind.PARALYSIS
                    && timedStatus.paralysisVisualActive(nowNanos));
        boolean applied = false;
        if (kind != ClassicWorldMonsterPoisonAttack.Kind.NONE
                && !poisonResistance && !existingPoison) {
            applied = switch (kind) {
                case DAMAGE -> timedStatus.activatePoison(
                        nowNanos,
                        ClassicWorldMonsterPoisonAttack.DAMAGE_DURATION_SECONDS,
                        ClassicWorldMonsterPoisonAttack.DAMAGE_TICK_MILLIS);
                case SILENCE -> timedStatus.activatePoisonSilence(nowNanos);
                case PARALYSIS -> timedStatus.activateParalysis(
                        nowNanos,
                        ClassicWorldMonsterPoisonAttack.PARALYSIS_WARNING_MILLIS,
                        ClassicWorldMonsterPoisonAttack.PARALYSIS_DURATION_MILLIS);
                case NONE -> false;
            };
        }
        if (applied) {
            classicWorldPoisonAttackerObjectId = attackerObjectId;
            classicWorldPoisonKind = kind;
            if (kind == ClassicWorldMonsterPoisonAttack.Kind.SILENCE) {
                sendEncrypted(Protocol.messageCode(310),
                        "S_MESSAGE_CODE " + source + "-silence-poison=310 npc="
                                + attackerNpcId);
            } else if (kind == ClassicWorldMonsterPoisonAttack.Kind.PARALYSIS) {
                sendEncrypted(Protocol.messageCode(212),
                        "S_MESSAGE_CODE " + source
                                + "-paralysis-poison-warning=212 npc="
                                + attackerNpcId);
            }
            broadcastPoisonState(1, source + "-poison-"
                    + kind.name().toLowerCase(Locale.ROOT));
        }
        System.out.println("[LiTo] " + source + " poison npc="
                + attackerNpcId + " object=" + attackerObjectId
                + " poison-atk=" + poisonAttack
                + " paralysis-atk=" + paralysisAttack
                + " roll=" + oneBasedRoll + " kind=" + kind
                + " poison-resistance=" + poisonResistance
                + " existing-poison=" + existingPoison
                + " applied=" + applied
                + " retained-paralysis-atk-handler=absent");
    }

    /** Retained L1AttackNpc poison_atk branch when a companion hits an NPC. */
    private void applyClassicWorldCompanionPoisonToMonster(
            BattleCompanion controlled, BattleCompanion.Snapshot companion,
            ClassicWorldMonsterPopulation.Snapshot target,
            long nowNanos) throws IOException {
        int poisonAttack = controlled.poisonAttack();
        if (poisonAttack == 0 || target == null || !target.alive()) return;
        int configuredRoll = config.classicWorldMonsterPoisonFixtureRoll();
        int oneBasedRoll = configuredRoll == 0
                ? ThreadLocalRandom.current().nextInt(1, 101) : configuredRoll;
        ClassicWorldMonsterPoisonAttack.Kind kind =
                ClassicWorldMonsterPoisonAttack.resolve(
                        poisonAttack, oneBasedRoll);
        ClassicWorldMonsterPopulation.ContributorKind contributorKind =
                companion.kind().earnsExperience()
                        ? ClassicWorldMonsterPopulation.ContributorKind.PET
                        : ClassicWorldMonsterPopulation.ContributorKind.SUMMON;
        ClassicWorldMonsterPopulation.NpcPoison result =
                hub.poisonClassicWorldMonsterFromNpc(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), contributorKind,
                        companion.objectId(), playerObjectId(), kind, nowNanos);
        boolean applied = result != null && result.applied();
        if (applied) {
            int palette = hub.classicWorldMonsterPoisonPalette(
                    classicWorldMapId, classicWorldInstanceId,
                    target.objectId(), nowNanos);
            byte[] poison = Protocol.poison(target.objectId(), palette);
            for (ClientSession member
                    : classicWorldMembers(classicWorldMapId)) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.x(), target.y())) continue;
                member.sendEncrypted(poison,
                        "S_POISON classic-world-monster=" + target.objectId()
                                + " type=" + palette
                                + " reason=companion-poison-"
                                + kind.name().toLowerCase(Locale.ROOT));
            }
        }
        System.out.println("[LiTo] classic-world companion poison NPC owner="
                + playerName() + " companion=" + companion.objectId()
                + " npc=" + companion.npcId() + " target=" + target.objectId()
                + " target-npc=" + target.npcId() + " poison-atk="
                + poisonAttack + " paralysis-atk="
                + controlled.paralysisAttack() + " roll=" + oneBasedRoll
                + " kind=" + kind + " existing-poison="
                + (result != null && result.existingPoison())
                + " applied=" + applied
                + " retained-paralysis-atk-handler=absent");
    }

    void serverClassicWorldMonsterMagicAttack(
            ClassicWorldMonsterPopulation.MagicAttack attack) throws IOException {
        if (attack == null || phase != Phase.WORLD
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) return;
        ClassicWorldMonsterPopulation.Snapshot actor = attack.attacker();
        if (actor.mapId() != classicWorldMapId) return;
        if (attack.targetObjectId() == playerObjectId()
                && !classicWorldMonsterRetainedTargetEligible(actor.mapId())) return;

        ClassicWorldMonsterMagicTarget primary =
                classicWorldMonsterMagicTarget(attack.targetObjectId());
        if (primary == null || primary.x() != attack.targetX()
                || primary.y() != attack.targetY()) {
            return;
        }

        ClassicWorldMonsterMagicSkillCatalog.Definition skill = attack.skill();
        List<ClassicWorldMonsterMagicTarget> targets;
        if (skill.targeting()
                == ClassicWorldMonsterMagicSkillCatalog.Targeting.DIRECTIONAL) {
            targets = List.of(primary);
        } else {
            int centerX = skill.targeting()
                    == ClassicWorldMonsterMagicSkillCatalog.Targeting.CASTER_CENTERED
                            ? actor.x() : primary.x();
            int centerY = skill.targeting()
                    == ClassicWorldMonsterMagicSkillCatalog.Targeting.CASTER_CENTERED
                            ? actor.y() : primary.y();
            targets = classicWorldMonsterMagicAreaTargets(
                    actor, centerX, centerY, skill.areaRadius());
        }

        List<ClassicWorldMonsterMagicHit> hits = new ArrayList<>();
        List<ClientSession> members = classicWorldMembers(classicWorldMapId);
        long damageNowNanos = System.nanoTime();
        int actorIntelligence = classicWorldMonsterPanicAdjustedAbility(
                actor, actor.template().intelligence(), damageNowNanos);
        SourceNpcPhysicalStats mirrorSourceStats = null;
        try {
            mirrorSourceStats = selectedSourceAccounts()
                    .npcPhysicalStats(actor.npcId());
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] classic-world Counter Mirror source"
                    + " lookup failed npc=" + actor.npcId() + " reason="
                    + sourceFailure.getMessage());
        }
        boolean mirrorEligible = counterMirrorNpcEligible(
                actor.npcId(), mirrorSourceStats);
        Map<Long, BattleEraseMagicStatus.Lease> eraseMagicLeases =
                new LinkedHashMap<>();
        for (ClassicWorldMonsterMagicTarget target : targets) {
            if (!target.isCompanion()
                    && target.owner().timedStatus.consumeCounterMagic(
                            damageNowNanos)) {
                target.owner().publishCounterMagicConsumption(
                        target.owner(), skill.skillId());
                hits.add(new ClassicWorldMonsterMagicHit(
                        target, 0, 0, 0, 0, 0));
                continue;
            }
            BattleEraseMagicStatus.Lease eraseMagicLease = target.isCompanion()
                    ? BattleEraseMagicStatus.Lease.none()
                    : target.owner().eraseMagicStatus.capture(damageNowNanos);
            int configuredDie = config.classicWorldMonsterMagicFixtureDieRoll();
            int sourceDamage = ClassicWorldMonsterMagicDamage.rollSourceDamage(
                    skill, sides -> configuredDie > 0
                            ? configuredDie
                            : ThreadLocalRandom.current().nextInt(1, sides + 1));
            if (target.isCompanion()) {
                SourceNpcPhysicalStats targetStats;
                try {
                    targetStats = target.owner().selectedSourceAccounts()
                            .npcPhysicalStats(target.companion().npcId());
                } catch (Exception sourceFailure) {
                    System.out.println("[LiTo] classic-world companion magic defense"
                            + " source lookup failed owner=" + target.owner().playerName()
                            + " npc=" + target.companion().npcId()
                            + " reason=" + sourceFailure.getMessage());
                    continue;
                }
                int elementalResistance =
                        ClassicWorldMonsterMagicDamage.companionElementalResistance(
                                targetStats.weakAttribute(), skill.attribute());
                int afterElement =
                        ClassicWorldMonsterMagicDamage.afterElementAndLeverage(
                                sourceDamage, actorIntelligence,
                                elementalResistance, skill.effectiveLeverage());
                int damage = ClassicWorldMonsterMagicDamage.afterArmorAndResistance(
                        afterElement, 0, targetStats.magicResistance(),
                        actorIntelligence);
                hits.add(new ClassicWorldMonsterMagicHit(
                        target, sourceDamage, elementalResistance, 0,
                        targetStats.magicResistance(), damage));
                continue;
            }

            int elementalResistance = target.owner()
                    .effectiveSpellElementalResistance(skill.attribute());
            int afterElement = ClassicWorldMonsterMagicDamage.afterElementAndLeverage(
                    sourceDamage, actorIntelligence,
                    elementalResistance, skill.effectiveLeverage());
            int armorReductionBase = target.owner()
                    .effectiveArmorMagicReductionBase();
            int armorReductionOffset = armorReductionBase <= 10 ? 0
                    : ThreadLocalRandom.current().nextInt(armorReductionBase - 10);
            int armorReduction = BattleMagicResistance.armorDamageReduction(
                    armorReductionBase, armorReductionOffset);
            BattleAbilityStatus.ReductionArmor reductionArmor =
                    target.owner().abilityStatus.reductionArmor(damageNowNanos);
            if (reductionArmor.remainingSeconds() != 0) {
                armorReduction = Math.addExact(armorReduction,
                        BattleSpellCatalog.reductionArmorSpell(
                                BattleSpellCatalog.REDUCTION_ARMOR).reduction(
                                        target.owner().battleLevel(), false));
            }
            int targetMagicResistance = target.owner()
                    .effectiveBaseMagicResistance();
            int damage = ClassicWorldMonsterMagicDamage.afterArmorAndResistance(
                    afterElement, armorReduction, targetMagicResistance,
                    actorIntelligence);
            damage = target.owner().combatDamageAfterCookingWithoutReductionArmor(
                    damage, "classic-world-monster-magic-" + skill.skillId());
            damage = target.owner().earthBindProtectedCombatDamage(
                    damage, "classic-world-monster-magic-" + skill.skillId());
            BattleCounterMirrorStatus.Decision mirror =
                    target.owner().counterMirrorDecision(
                            damage, mirrorEligible,
                            ThreadLocalRandom.current().nextInt(100),
                            damageNowNanos);
            if (mirror.triggered()) {
                target.owner().publishNpcCounterMirrorTrigger(
                        actor.objectId(), actor.x(), actor.y(), mirror,
                        members, "classic-world-monster-magic-"
                                + skill.skillId());
                ClassicWorldMonsterPopulation.Hit transition =
                        hub.damageClassicWorldMonster(
                                classicWorldMapId, classicWorldInstanceId,
                                actor.objectId(), target.owner().playerObjectId(),
                                mirror.reflectedDamage());
                if (transition != null) {
                    target.owner().publishClassicWorldSpellMonsterDamage(
                            BattleSpellCatalog.COUNTER_MIRROR, transition);
                }
                damage = 0;
            }
            hits.add(new ClassicWorldMonsterMagicHit(
                    target, sourceDamage, elementalResistance, armorReduction,
                    targetMagicResistance, damage));
            eraseMagicLeases.put(target.objectId(), eraseMagicLease);
        }

        long sequence = ATTACK_SPELL_SEQUENCE.getAndIncrement();
        byte[] packet;
        if (hits.isEmpty()) {
            packet = Protocol.objectAction(actor.objectId(), skill.actionId());
        } else if (skill.targeting()
                == ClassicWorldMonsterMagicSkillCatalog.Targeting.DIRECTIONAL) {
            ClassicWorldMonsterMagicHit hit = hits.get(0);
            packet = Protocol.attackSpell(
                    skill.actionId(), actor.objectId(), hit.target().objectId(),
                    hit.damage() > 0 ? 10 : 0, actor.heading(), sequence,
                    skill.effectGfx(), actor.x(), actor.y(),
                    hit.target().x(), hit.target().y());
        } else {
            packet = Protocol.attackMany(
                    skill.actionId(), actor.objectId(), actor.x(), actor.y(),
                    actor.heading(), sequence, skill.effectGfx(),
                    skill.targeting()
                            == ClassicWorldMonsterMagicSkillCatalog.Targeting.CASTER_CENTERED
                                    ? 0 : 8,
                    hits.stream().map(hit -> new Protocol.AttackManyTarget(
                            hit.target().objectId(), hit.damage() > 0)).toList());
        }

        for (ClientSession member : members) {
            boolean sees = BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, actor.x(), actor.y());
            if (!sees) {
                sees = hits.stream().anyMatch(hit ->
                        BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                hit.target().x(), hit.target().y()));
            }
            if (!sees) continue;
            member.sendEncrypted(packet,
                    (skill.targeting()
                            == ClassicWorldMonsterMagicSkillCatalog.Targeting.DIRECTIONAL
                            ? "S_ATTACK" : hits.isEmpty()
                                ? "S_ACTION" : "S_ATTACK_MANY")
                            + " classic-world-monster-magic=" + actor.objectId()
                            + " npc=" + actor.npcId() + " skill=" + skill.skillId()
                            + " targets=" + hits.size() + " action=" + skill.actionId()
                            + " gfx=" + skill.effectGfx() + " sequence=" + sequence
                            + " trigger-roll=" + (attack.triggerChanceApplied()
                                ? attack.triggerRoll() : "ignored")
                            + " leverage=" + skill.effectiveLeverage());
        }

        for (ClassicWorldMonsterMagicHit hit : hits) {
            System.out.println("[LiTo] classic-world monster magic npc="
                    + actor.npcId() + " object=" + actor.objectId()
                    + " skill=" + skill.skillId() + " target="
                    + hit.target().objectId() + " companion="
                    + hit.target().isCompanion() + " source-damage="
                    + hit.sourceDamage() + " caster-int="
                    + actorIntelligence + " elemental-resistance="
                    + hit.elementalResistance() + " leverage="
                    + skill.effectiveLeverage() + " armor-reduction="
                    + hit.armorReduction() + " target-mr="
                    + hit.targetMagicResistance() + " damage=" + hit.damage());
            if (hit.target().isCompanion()) {
                hit.target().owner().applyClassicWorldMonsterCompanionDamage(
                        hit.target().controlled(), hit.target().companion(),
                        hit.damage(), actor.objectId(), "monster-magic-death");
            } else {
                BattleJoyOfPainStatus.Lease joyLease = hit.damage() <= 0 ? null
                        : hub.captureClassicWorldMonsterJoyOfPain(
                                hit.target().owner().classicWorldMapId,
                                hit.target().owner().classicWorldInstanceId,
                                actor.objectId(), System.nanoTime());
                int joyDamage = joyLease == null ? 0
                        : hit.target().owner().currentJoyOfPainFeedbackDamage();
                hit.target().owner().takeClassicWorldMonsterDamage(
                        hit.damage(), actor.objectId());
                if (hit.damage() > 0) {
                    hit.target().owner()
                            .tryMortalBodyClassicWorldMonsterReflection(
                                    actor, "classic-world-monster-magic-"
                                            + skill.skillId());
                    hit.target().owner()
                            .applyJoyOfPainClassicWorldMonsterFeedback(
                                    actor, joyLease, joyDamage,
                                    "classic-world-monster-magic-"
                                            + skill.skillId());
                }
                hit.target().owner().eraseMagicStatus.consume(
                        eraseMagicLeases.get(hit.target().objectId()));
            }
        }
    }

    void serverClassicWorldMonsterStatusSkillAttack(
            ClassicWorldMonsterPopulation.StatusSkillAttack attack)
            throws IOException {
        serverClassicWorldMonsterStatusSkillAttack(attack, 0);
    }

    /** Test-only inner probability fixture; zero keeps the native random roll. */
    void serverClassicWorldMonsterStatusSkillAttack(
            ClassicWorldMonsterPopulation.StatusSkillAttack attack,
            int probabilityRollFixture) throws IOException {
        if (probabilityRollFixture < 0 || probabilityRollFixture > 100) {
            throw new IllegalArgumentException(
                    "invalid classic monster status probability fixture");
        }
        if (attack == null || phase != Phase.WORLD
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) return;
        ClassicWorldMonsterPopulation.Snapshot actor = attack.attacker();
        if (actor.mapId() != classicWorldMapId) return;
        if (attack.targetObjectId() == playerObjectId()
                && !classicWorldMonsterRetainedTargetEligible(actor.mapId())) return;

        ClassicWorldMonsterPhysicalTarget primary =
                classicWorldMonsterPhysicalTarget(attack.targetObjectId());
        if (primary == null || primary.x() != attack.targetX()
                || primary.y() != attack.targetY()) return;
        ClassicWorldMonsterStatusSkillCatalog.Definition skill = attack.skill();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(actor.mapId());
        if (!map.attackPosition(actor.x(), actor.y(),
                primary.x(), primary.y(), skill.maximumRange())) return;

        ClientSession target = primary.owner();
        CharacterSummary targetCharacter = primary.isCompanion()
                ? null : target.selectedCharacterSummary();
        int targetLevel = primary.isCompanion()
                ? primary.companion().level()
                : targetCharacter == null ? 1
                : Math.max(1, targetCharacter.level());
        long nowNanos = System.nanoTime();
        int actorIntelligence = classicWorldMonsterPanicAdjustedAbility(
                actor, actor.template().intelligence(), nowNanos);
        BattleEraseMagicStatus.Lease companionEraseMagicLease = null;
        int targetMagicResistance;
        if (primary.isCompanion()) {
            SourceNpcPhysicalStats targetStats;
            try {
                targetStats = target.selectedSourceAccounts().npcPhysicalStats(
                        primary.companion().npcId());
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] classic-world companion status defense"
                        + " source lookup failed owner=" + target.playerName()
                        + " npc=" + primary.companion().npcId()
                        + " reason=" + sourceFailure.getMessage());
                return;
            }
            companionEraseMagicLease = primary.controlled()
                    .captureEraseMagic(nowNanos);
            targetMagicResistance = primary.controlled()
                    .effectiveMagicResistance(
                            targetStats.magicResistance(), nowNanos);
        } else {
            targetMagicResistance = target.effectiveBaseMagicResistance();
        }
        int targetStoneResistance = primary.isCompanion() ? 0
                : Math.max(-128, Math.min(127,
                        target.requiredEquipmentMagicStats().totalStoneResistance()
                        + target.dragonEyeStatus.snapshot(nowNanos)
                            .stoneResistance()));
        int probability = skill.probability(
                actor.template().level(), actorIntelligence,
                targetLevel, targetMagicResistance, targetStoneResistance);
        int configuredRoll = probabilityRollFixture > 0
                ? probabilityRollFixture
                : config.classicWorldMonsterMagicFixtureDieRoll();
        int probabilityRoll = configuredRoll > 0
                ? configuredRoll : ThreadLocalRandom.current().nextInt(1, 101);
        boolean targetEarthBound = primary.isCompanion()
                ? primary.controlled().earthBindActive(nowNanos)
                : target.timedStatus.earthBindActive(nowNanos);
        boolean probabilitySuccess = !targetEarthBound
                && probability >= probabilityRoll;

        boolean eraseMagicConsumed;
        if (primary.isCompanion()) {
            eraseMagicConsumed = primary.controlled()
                    .consumeEraseMagic(companionEraseMagicLease);
        } else {
            eraseMagicConsumed = target.eraseMagicStatus.consume(nowNanos);
        }

        List<ClientSession> members = classicWorldMembers(classicWorldMapId);
        boolean countered = probabilitySuccess && !primary.isCompanion()
                && target.timedStatus.consumeCounterMagic(nowNanos);
        if (countered) {
            BattleSpellCatalog.CounterMagicSpell ward =
                    BattleSpellCatalog.counterMagicSpell(
                            BattleSpellCatalog.COUNTER_MAGIC);
            if (ward.consumeEffectGfx() > 0) {
                byte[] counterEffect = Protocol.effectObject(
                        primary.objectId(), ward.consumeEffectGfx());
                for (ClientSession member : members) {
                    if (!BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            primary.x(), primary.y())) continue;
                    member.sendEncrypted(counterEffect,
                            "S_EFFECT classic-world-counter-magic-consumed target="
                                    + primary.objectId() + " gfx="
                                    + ward.consumeEffectGfx() + " source-skill="
                                    + skill.skillId());
                }
            }
        }

        boolean applied = false;
        boolean nativeMonsterTarget = false;
        if (probabilitySuccess && !countered) {
            if (primary.isCompanion()) {
                BattleCompanion.NpcCurseParalysisInstallation installation =
                        primary.controlled().activateNpcCurseParalysis(
                                nowNanos, skill.paralysisDurationMillis());
                nativeMonsterTarget = installation.nativeMonsterTarget();
                applied = installation.applied();
            } else if (!target.timedStatus.freezeActive(nowNanos)) {
                applied = target.timedStatus.activateParalysis(
                        nowNanos, skill.warningDelayMillis(),
                        skill.paralysisDurationMillis());
            }
        }

        // runSkill installs the warning state before sendGrfx emits the
        // caster action and target effect.
        if (applied) {
            if (primary.isCompanion()) {
                target.broadcastClassicWorldCompanionPoisonPalette(
                        primary.companion(), 2,
                        "monster-curse-paralysis-active");
            } else {
                target.sendEncrypted(Protocol.messageCode(212),
                        "S_MESSAGE_CODE classic-world-curse-paralysis-warning=212 npc="
                                + actor.npcId());
                target.broadcastPoisonState(2,
                        "classic-world-monster-curse-paralysis-warning");
            }
        }

        byte[] action = Protocol.objectAction(actor.objectId(), skill.actionId());
        for (ClientSession member : members) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, actor.x(), actor.y())
                    && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY,
                    primary.x(), primary.y())) continue;
            member.sendEncrypted(action,
                    "S_ACTION classic-world-monster-status=" + actor.objectId()
                            + " npc=" + actor.npcId() + " skill=" + skill.skillId()
                            + " action=" + skill.actionId());
        }

        // L1SkillUse sends the target effect whenever probability succeeded;
        // L1CurseParalysis may still reject installation for an existing lock.
        if (probabilitySuccess && !countered) {
            byte[] effect = Protocol.effectObject(
                    primary.objectId(), skill.effectGfx());
            for (ClientSession member : members) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY,
                        primary.x(), primary.y())) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT classic-world-monster-status target="
                                + primary.objectId() + " skill=" + skill.skillId()
                                + " gfx=" + skill.effectGfx());
            }
        }

        System.out.println("[LiTo] classic-world monster status npc="
                + actor.npcId() + " object=" + actor.objectId()
                + " skill=" + skill.skillId() + " target="
                + primary.objectId() + " companion=" + primary.isCompanion()
                + " probability=" + probability + " roll=" + probabilityRoll
                + " success=" + probabilitySuccess + " countered=" + countered
                + " applied=" + applied + " target-level=" + targetLevel
                + " target-mr=" + targetMagicResistance
                + " stone-resistance=" + targetStoneResistance
                + " earth-bound=" + targetEarthBound
                + " erase-magic-consumed=" + eraseMagicConsumed
                + " native-monster-target=" + nativeMonsterTarget
                + " trigger-roll=" + (attack.triggerChanceApplied()
                    ? attack.triggerRoll() : "ignored")
                + " warning-ms=" + (primary.isCompanion()
                    ? 0 : skill.warningDelayMillis())
                + " active-ms=" + skill.paralysisDurationMillis());
    }

    void serverClassicWorldMonsterPhysicalSkillAttack(
            ClassicWorldMonsterPopulation.PhysicalSkillAttack attack)
            throws IOException {
        if (attack == null || phase != Phase.WORLD
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) return;
        ClassicWorldMonsterPopulation.Snapshot actor = attack.attacker();
        if (actor.mapId() != classicWorldMapId) return;
        if (attack.targetObjectId() == playerObjectId()
                && !classicWorldMonsterRetainedTargetEligible(actor.mapId())) return;

        ClassicWorldMonsterPhysicalTarget primary =
                classicWorldMonsterPhysicalTarget(attack.targetObjectId());
        if (primary == null || primary.x() != attack.targetX()
                || primary.y() != attack.targetY()) return;
        ClassicWorldMonsterPhysicalSkillCatalog.Definition skill = attack.skill();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(actor.mapId());
        if (!map.attackPosition(actor.x(), actor.y(),
                primary.x(), primary.y(), skill.range())) return;

        List<ClassicWorldMonsterPhysicalTarget> targets = skill.hasArea()
                ? classicWorldMonsterPhysicalAreaTargets(actor, skill)
                : List.of(primary);
        List<ClassicWorldMonsterPhysicalHit> hits = new ArrayList<>();
        long damageNowNanos = System.nanoTime();
        for (ClassicWorldMonsterPhysicalTarget target : targets) {
            hits.add(classicWorldMonsterPhysicalSkillHit(
                    actor, skill, target, damageNowNanos));
        }
        ClassicWorldMonsterPhysicalHit primaryHit = hits.stream()
                .filter(hit -> hit.target().objectId() == primary.objectId())
                .findFirst().orElse(new ClassicWorldMonsterPhysicalHit(
                        primary, 0, 0, 0, 0, 0, false, false, 0));

        // Retained L1MobSkillUse invokes L1AttackNpc.calcDamage before action(),
        // so poison_atk is resolved for every physically hit area target before
        // the skill/attack animation packet is published.
        for (ClassicWorldMonsterPhysicalHit hit : hits) {
            if (!hit.physicalHit()) continue;
            if (hit.target().isCompanion()) {
                hit.target().owner().applyClassicWorldMonsterPoisonToCompanion(
                        actor, hit.target().controlled(),
                        hit.target().companion(), damageNowNanos);
            } else {
                hit.target().owner().applyClassicWorldMonsterPoison(
                        actor, damageNowNanos);
            }
        }

        List<ClientSession> members = classicWorldMembers(classicWorldMapId);
        if (skill.gfxId() > 0) {
            byte[] effect = Protocol.effectObject(actor.objectId(), skill.gfxId());
            for (ClientSession member : members) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY,
                        actor.x(), actor.y())) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT classic-world-monster-physical="
                                + actor.objectId() + " npc=" + actor.npcId()
                                + " gfx=" + skill.gfxId());
            }
        }

        byte[] packet = Protocol.physicalDamageAttack(
                skill.actionId(), actor.objectId(), primary.objectId(),
                primaryHit.damage(), actor.heading());
        for (ClientSession member : members) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, actor.x(), actor.y())
                    && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY,
                    primary.x(), primary.y())) continue;
            member.sendEncrypted(packet,
                    "S_ATTACK classic-world-monster-physical=" + actor.objectId()
                            + " npc=" + actor.npcId() + " act-no=" + skill.actNo()
                            + " target=" + primary.objectId()
                            + " targets=" + hits.size() + " action="
                            + skill.actionId() + " gfx=" + skill.gfxId()
                            + " damage=" + primaryHit.damage()
                            + " trigger-roll=" + (attack.triggerChanceApplied()
                                ? attack.triggerRoll() : "ignored")
                            + " leverage=" + skill.effectiveLeverage()
                            + " secondary-actions=0 attack-all=0");
        }

        for (ClassicWorldMonsterPhysicalHit hit : hits) {
            System.out.println("[LiTo] classic-world monster physical skill npc="
                    + actor.npcId() + " object=" + actor.objectId()
                    + " act-no=" + skill.actNo() + " target="
                    + hit.target().objectId() + " companion="
                    + hit.target().isCompanion() + " source-damage="
                    + hit.sourceDamage() + " leverage=" + skill.effectiveLeverage()
                    + " weapon-break-stacks="
                    + hub.classicWorldMonsterWeaponBreakStacks(
                            actor.mapId(), classicWorldInstanceId,
                            actor.objectId())
                    + " armor-reduction=" + hit.armorReduction()
                    + " physical-hit=" + hit.physicalHit()
                    + " hit=" + hit.hit() + " hit-chance=" + hit.hitChance()
                    + " d20=" + hit.d20() + " d100=" + hit.d100()
                    + " damage=" + hit.damage());
            if (hit.damage() <= 0) continue;
            if (hit.target().isCompanion()) {
                hit.target().owner().applyClassicWorldMonsterCompanionDamage(
                        hit.target().controlled(), hit.target().companion(),
                        hit.damage(), actor.objectId(),
                        "monster-physical-skill-death");
            } else {
                BattleJoyOfPainStatus.Lease joyLease =
                        hub.captureClassicWorldMonsterJoyOfPain(
                                hit.target().owner().classicWorldMapId,
                                hit.target().owner().classicWorldInstanceId,
                                actor.objectId(), System.nanoTime());
                int joyDamage = joyLease == null ? 0
                        : hit.target().owner().currentJoyOfPainFeedbackDamage();
                hit.target().owner().takeClassicWorldMonsterDamage(
                        hit.damage(), actor.objectId());
                hit.target().owner().tryMortalBodyClassicWorldMonsterReflection(
                        actor, "classic-world-monster-physical-skill-"
                                + skill.actNo());
                hit.target().owner().applyJoyOfPainClassicWorldMonsterFeedback(
                        actor, joyLease, joyDamage,
                        "classic-world-monster-physical-skill-"
                                + skill.actNo());
            }
        }
    }

    private ClassicWorldMonsterPhysicalHit classicWorldMonsterPhysicalSkillHit(
            ClassicWorldMonsterPopulation.Snapshot actor,
            ClassicWorldMonsterPhysicalSkillCatalog.Definition skill,
            ClassicWorldMonsterPhysicalTarget target, long nowNanos) {
        ClientSession owner = target.owner();
        int targetArmorClass = target.isCompanion()
                ? target.companion().armorClass() : owner.battleArmorClass();
        int d20 = owner.config.uncannyDodgeHitFixtureD20() > 0
                ? owner.config.uncannyDodgeHitFixtureD20()
                : ThreadLocalRandom.current().nextInt(1, 21);
        int negativeAcRoll = targetArmorClass < 0
                ? ThreadLocalRandom.current().nextInt(1,
                    BattleNpcPhysicalAttack.negativeAcRollMaximum(
                            targetArmorClass) + 1)
                : 0;
        int dodgeModifier = target.isCompanion()
                ? 0 : owner.effectivePhysicalDodge(nowNanos);
        int dodgeDown = target.isCompanion()
                ? 0 : owner.effectivePhysicalDodgeDown(nowNanos);
        int hitChance = BattleNpcPhysicalAttack.hitChance(
                actor.template().level(), 0, targetArmorClass,
                dodgeModifier, dodgeDown, d20, negativeAcRoll);
        int d100 = owner.config.uncannyDodgeHitFixtureD100() > 0
                ? owner.config.uncannyDodgeHitFixtureD100()
                : ThreadLocalRandom.current().nextInt(1, 101);
        boolean hit = !owner.config.battlePhysicalHitEnabled()
                || BattleNpcPhysicalAttack.hits(hitChance, d100);
        if (!hit) {
            return new ClassicWorldMonsterPhysicalHit(
                    target, 0, 0, hitChance, d20, d100,
                    false, false, 0);
        }

        boolean physicalDamageZero = target.isCompanion()
                ? target.controlled().freezeActive(nowNanos)
                    || target.controlled().earthBindActive(nowNanos)
                : owner.timedStatus.freezeActive(nowNanos)
                    || owner.timedStatus.absoluteBarrierActive(nowNanos)
                    || owner.timedStatus.earthBindActive(nowNanos);
        if (physicalDamageZero) {
            return new ClassicWorldMonsterPhysicalHit(
                    target, 0, 0, hitChance, d20, d100,
                    false, false, 0);
        }

        int configuredLevelRoll = owner.config
                .classicWorldMonsterPhysicalSkillFixtureLevelRoll();
        int levelRoll = configuredLevelRoll > 0
                ? configuredLevelRoll
                : ThreadLocalRandom.current().nextInt(actor.template().level());
        int configuredCriticalRoll = owner.config
                .classicWorldMonsterPhysicalSkillFixtureCriticalRoll();
        int criticalRoll = configuredCriticalRoll > 0
                ? configuredCriticalRoll : ThreadLocalRandom.current().nextInt(100);
        int actorStrength = owner.classicWorldMonsterPanicAdjustedAbility(
                actor, actor.template().strength(), nowNanos);
        int sourceDamageBeforeWeaponBreak = ClassicWorldNpcDamage.sourceDamage(
                actor.template().level(), actorStrength,
                owner.requiredPhysicalGrowthStats().damage(
                        false, actorStrength),
                levelRoll, criticalRoll,
                switch (actor.template().undead()) {
                    case 1, 3, 4 -> ClassicWorldNpcDamage.retainedNight(
                            System.currentTimeMillis());
                    default -> false;
                }, actor.template().boss(), skill.effectiveLeverage());
        int weaponBreakStacks = owner.hub.classicWorldMonsterWeaponBreakStacks(
                actor.mapId(), owner.classicWorldInstanceId, actor.objectId());
        int sourceDamage = BattleWeaponBreak.damageAfterStacks(
                sourceDamageBeforeWeaponBreak, weaponBreakStacks);
        boolean armBreakerMelee = Math.max(
                Math.abs(actor.x() - target.x()),
                Math.abs(actor.y() - target.y())) <= 1
                || actor.template().bowActionId() <= 0;
        if (armBreakerMelee) {
            sourceDamage = Math.max(0, Math.addExact(sourceDamage,
                    owner.hub.classicWorldMonsterArmBreakerMeleeDamageModifier(
                            actor.mapId(), owner.classicWorldInstanceId,
                            actor.objectId(), nowNanos)));
        }

        if (target.isCompanion()) {
            SourceNpcPhysicalStats companionStats;
            try {
                companionStats = owner.selectedSourceAccounts().npcPhysicalStats(
                        target.companion().npcId());
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] classic-world companion physical skill"
                        + " defense source lookup failed owner=" + owner.playerName()
                        + " npc=" + target.companion().npcId()
                        + " reason=" + sourceFailure.getMessage());
                return new ClassicWorldMonsterPhysicalHit(
                        target, sourceDamage, 0, hitChance, d20, d100,
                        true, false, 0);
            }
            int defenseMaximum = BattlePhysicalDefense.npcAcMaximum(companionStats);
            int defenseRoll = defenseMaximum == 0 ? 0
                    : ThreadLocalRandom.current().nextInt(defenseMaximum);
            int damage = BattlePhysicalDefense.againstNpc(
                    sourceDamage, companionStats, defenseRoll,
                    false, false).damage();
            return new ClassicWorldMonsterPhysicalHit(
                    target, sourceDamage, defenseRoll, hitChance, d20, d100,
                    true, damage > 0, damage);
        }

        CharacterSummary character = owner.selectedCharacterSummary();
        int type = character == null ? 0 : character.type();
        int acMaximum = BattlePhysicalDefense.playerAcMaximum(
                type, targetArmorClass);
        int acRoll = acMaximum == 0 ? 0
                : ThreadLocalRandom.current().nextInt(acMaximum);
        int acReduction = acMaximum == 0 ? 0
                : acRoll + Math.max(1, acMaximum >> 3);
        int damage = owner.combatPhysicalDamageAfterArmorAndCooking(
                Math.max(0, sourceDamage - acReduction),
                "classic-world-monster-physical-skill-" + skill.actNo());
        damage = owner.earthBindProtectedCombatDamage(
                damage, "classic-world-monster-physical-skill-" + skill.actNo());
        return new ClassicWorldMonsterPhysicalHit(
                target, sourceDamage, acReduction, hitChance, d20, d100,
                true, damage > 0, damage);
    }

    private ClassicWorldMonsterPhysicalTarget classicWorldMonsterPhysicalTarget(
            long objectId) {
        if (phase != Phase.WORLD || !ClassicWorldMapCatalog.supports(classicWorldMapId)
                || objectId <= 0) return null;
        if (objectId == playerObjectId() && !observer && playerHp > 0) {
            return new ClassicWorldMonsterPhysicalTarget(
                    this, objectId, positionX, positionY, null, null);
        }
        BattleCompanion controlled = ownedCompanion(objectId);
        BattleCompanion.Snapshot companion = controlled == null
                ? null : controlled.snapshot();
        if (companion == null || !companion.active()
                || !companion.kind().classicWorldEligible() || companion.hp() <= 0) {
            return null;
        }
        return new ClassicWorldMonsterPhysicalTarget(
                this, objectId, companion.x(), companion.y(),
                controlled, companion);
    }

    private List<ClassicWorldMonsterPhysicalTarget>
            classicWorldMonsterPhysicalAreaTargets(
                    ClassicWorldMonsterPopulation.Snapshot actor,
                    ClassicWorldMonsterPhysicalSkillCatalog.Definition skill) {
        Map<Long, ClassicWorldMonsterPhysicalTarget> result = new LinkedHashMap<>();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(actor.mapId());
        for (ClientSession member : classicWorldMembers(actor.mapId())) {
            ClassicWorldMonsterPhysicalTarget player =
                    member.classicWorldMonsterPhysicalTarget(member.playerObjectId());
            if (player != null && skill.containsBoxTarget(
                    actor.x(), actor.y(), actor.heading(), player.x(), player.y())
                    && map.attackPosition(actor.x(), actor.y(),
                            player.x(), player.y(), skill.areaHeight())) {
                result.putIfAbsent(player.objectId(), player);
            }
            for (BattleCompanion.Snapshot companion
                    : member.classicWorldCompanionSnapshots()) {
                ClassicWorldMonsterPhysicalTarget target =
                        member.classicWorldMonsterPhysicalTarget(companion.objectId());
                if (target != null && skill.containsBoxTarget(
                        actor.x(), actor.y(), actor.heading(), target.x(), target.y())
                        && map.attackPosition(actor.x(), actor.y(),
                                target.x(), target.y(), skill.areaHeight())) {
                    result.putIfAbsent(target.objectId(), target);
                }
            }
        }
        return List.copyOf(result.values());
    }

