    private void usePatienceSpell(
            byte[] payload, BattleSpellCatalog.PatienceSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || spell.requestShape()
                    != BattleSpellCatalog.RequestShape.SELECTOR_ONLY) return;
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Patience rejected"
                    + " learned/action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long targetNow = System.nanoTime();
        PatienceTarget target = resolveSelectorOnlyPatienceTarget(
                originPhase, originRoomId, originMapId, originInstanceId,
                originX, originY, spell.maximumRange(), targetNow);
        if (target == null) return;

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int remainingMp;
        BattlePatienceStatus.Activation activation;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterContext = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (originPhase == Phase.WORLD
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            PatienceTarget currentTarget;
            if (target.player() == this) {
                currentTarget = sameCasterContext ? target : null;
            } else {
                Map<Long, PatienceTarget> current = patienceTargets(
                        originPhase, originRoomId, originMapId, originInstanceId,
                        originX, originY, spell.maximumRange(), castNow);
                currentTarget = current == null ? null
                        : current.get(target.objectId());
                if (currentTarget != null && currentTarget.kind() != target.kind()) {
                    currentTarget = null;
                }
            }
            if (castNow < readyAt || playerMp < mpCost || !sameCasterContext
                    || currentTarget == null) {
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE Patience-insufficient-mp=278");
                }
                System.out.println("[LiTo] C_USE_SPELL Patience rejected state"
                        + " player=" + playerName() + " target=" + target.objectId()
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow)
                        + " phase=" + originPhase);
                return;
            }
            target = currentTarget;
            activation = originPhase == Phase.WORLD
                    ? hub.activateClassicWorldPatience(
                        originMapId, originInstanceId, target.objectId(),
                        castNow, spell.durationSeconds())
                    : hub.activatePatience(originRoomId, target.objectId(),
                        castNow, spell.durationSeconds());
            if (!activation.accepted()) return;
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(target.objectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, originX, originY)
                            && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.x(), target.y()))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION Patience caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT Patience target=" + target.objectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Patience=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Patience caster=" + playerName()
                + " target=" + target.objectId() + " kind=" + target.kind()
                + " duration=" + spell.durationSeconds()
                + " physical-reduction-player-only="
                + spell.physicalDamageReduction()
                + " refreshed=" + activation.refreshed()
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " mp-cost=" + mpCost
                + " original-reduction=" + originalReduction
                + " counter-magic-bypass=" + spell.counterMagicBypass()
                + " persisted=" + spell.persisted()
                + " client-clock-ms=" + spell.clientCastClockMillis()
                + " phase=" + originPhase
                + " icon=omitted-no-selected-LiTo-packetbox-receiver");
    }

    private void usePhantasmSpell(
            byte[] payload, BattleSpellCatalog.PhantasmSpell spell)
            throws IOException {
        usePhantasmSpell(payload, spell,
                config.phantasmSpellFixtureEnabled()
                        ? config.phantasmFixturePercentileRoll() : 0);
    }

    /** Test-only fixed percentile; zero preserves the retained random roll. */
    private void usePhantasmSpell(
            byte[] payload, BattleSpellCatalog.PhantasmSpell spell,
            int percentileRollFixture) throws IOException {
        if (percentileRollFixture < 0 || percentileRollFixture > 100) {
            throw new IllegalArgumentException(
                    "invalid Phantasm percentile fixture");
        }
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || spell.requestShape()
                    != BattleSpellCatalog.RequestShape.SELECTOR_ONLY) return;
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Phantasm rejected"
                    + " learned/action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long targetNow = System.nanoTime();
        PatienceTarget target = resolveSelectorOnlyPhantasmTarget(
                originPhase, originRoomId, originMapId, originInstanceId,
                originX, originY, spell.maximumRange(), targetNow);
        if (target == null) return;

        ClientSession targetPlayer = target.player();
        BattleCompanion controlledCompanion = null;
        if (target.kind() == BattleTrueTarget.Kind.COMPANION) {
            List<ClientSession> owners = originPhase == Phase.WORLD
                    ? classicWorldMembers(originMapId)
                    : hub.visibleBattleCombatants(originRoomId, this);
            for (ClientSession owner : owners) {
                BattleCompanion candidate = owner.ownedCompanion(target.objectId());
                if (candidate != null && candidate.snapshot().active()
                        && candidate.snapshot().hp() > 0) {
                    controlledCompanion = candidate;
                    break;
                }
            }
        }
        ClassicWorldMonsterPopulation.Snapshot worldMonster =
                target.kind() == BattleTrueTarget.Kind.WORLD_MONSTER
                        ? hub.classicWorldMonster(
                            originMapId, originInstanceId, target.objectId()) : null;
        BattleQuestEncounter.Snapshot questTarget =
                target.kind() == BattleTrueTarget.Kind.QUEST_MONSTER
                        ? hub.questMonster(originRoomId, target.objectId()) : null;
        BattleTimeAttackEncounter.Snapshot timeTarget =
                target.kind() == BattleTrueTarget.Kind.TIME_ATTACK_ACTOR
                        ? hub.timeAttackActor(originRoomId, target.objectId()) : null;

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment =
                requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(targetNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int targetLevel = targetPlayer != null
                ? targetPlayer.selectedCharacterSummary() == null ? 1
                    : Math.max(1, targetPlayer.selectedCharacterSummary().level())
                : controlledCompanion != null
                    ? Math.max(1, controlledCompanion.snapshot().level())
                : worldMonster != null ? Math.max(1, worldMonster.template().level())
                : questTarget != null ? Math.max(1, questTarget.level())
                : timeTarget != null ? Math.max(1, timeTarget.level()) : 1;
        int targetStoneResistance = targetPlayer == null ? 0
                : Math.max(-128, Math.min(127, Math.addExact(
                    targetPlayer.requiredEquipmentMagicStats().totalStoneResistance(),
                    targetPlayer.dragonEyeStatus.snapshot(targetNow)
                        .stoneResistance())));
        boolean targetAbsoluteBarrierAtSelection = targetPlayer != null
                && targetPlayer.timedStatus.absoluteBarrierActive(targetNow);

        int remainingHp;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterContext = phase == originPhase && !observer
                    && playerHp > spell.hpCost()
                    && positionX == originX && positionY == originY
                    && (originPhase == Phase.WORLD
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            PatienceTarget currentTarget;
            if (target.player() == this) {
                currentTarget = sameCasterContext ? target : null;
            } else {
                Map<Long, PatienceTarget> current = phantasmTargets(
                        originPhase, originRoomId, originMapId, originInstanceId,
                        originX, originY, spell.maximumRange(), castNow);
                currentTarget = current == null ? null
                        : current.get(target.objectId());
                if (currentTarget != null && currentTarget.kind() != target.kind()) {
                    currentTarget = null;
                }
            }
            if (castNow < readyAt || playerMp < mpCost
                    || !sameCasterContext || currentTarget == null) {
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE Phantasm-insufficient-mp=278");
                }
                System.out.println("[LiTo] C_USE_SPELL Phantasm rejected state"
                        + " player=" + playerName() + " target=" + target.objectId()
                        + " hp=" + playerHp + " hp-cost=" + spell.hpCost()
                        + " mp=" + playerMp + " mp-cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow)
                        + " phase=" + originPhase);
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerHp -= spell.hpCost();
            playerMp -= mpCost;
            remainingHp = playerHp;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        boolean absoluteBarrierBlocked = targetPlayer != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                    targetAbsoluteBarrierAtSelection
                        || targetPlayer.timedStatus.absoluteBarrierActive(castNow),
                    spell.skillId());
        boolean earthBindBlocked = targetPlayer != null
                ? targetPlayer.timedStatus.earthBindActive(castNow)
                : questTarget != null
                    ? hub.questMonsterEarthBindActive(
                        originRoomId, questTarget.objectId(), castNow)
                    : timeTarget != null
                        && hub.timeAttackActorEarthBindActive(
                            originRoomId, timeTarget.objectId(), castNow);
        boolean targetFailure = target.kind() == BattleTrueTarget.Kind.GUARDIAN_TOWER
                || target.kind() == BattleTrueTarget.Kind.ARENA_BOT;
        boolean bossImmune = worldMonster != null
                && worldMonster.template().boss()
                || timeTarget != null && timeTarget.finalBoss();
        int probability = absoluteBarrierBlocked || earthBindBlocked
                || targetFailure || bossImmune ? 0
                : spell.probability(casterLevel, targetLevel,
                    totalMagicHit, targetStoneResistance);
        int percentileRoll = probability == 0 ? 100
                : percentileRollFixture == 0
                    ? ThreadLocalRandom.current().nextInt(1, 101)
                    : percentileRollFixture;

        if (targetPlayer != null) {
            targetPlayer.eraseMagicStatus.consume(castNow);
        } else if (controlledCompanion != null) {
            controlledCompanion.consumeEraseMagic(castNow);
        } else if (worldMonster != null) {
            hub.consumeClassicWorldMonsterEraseMagic(
                    originMapId, originInstanceId, target.objectId(), castNow);
        } else {
            consumeEraseMagicAfterProbability(
                    null, questTarget, timeTarget, castNow, spell.skillId());
        }

        // Retained TYPE_CURSE ordering removes FOG_OF_SLEEPING before the
        // success branch, so failure and Counter Magic both wake an old lease.
        if (targetPlayer != null) {
            targetPlayer.cancelSleep("probability-spell-" + spell.skillId());
        } else if (controlledCompanion != null) {
            controlledCompanion.cancelSleep();
        } else if (worldMonster != null) {
            hub.cancelClassicWorldMonsterSleep(
                    originMapId, originInstanceId, target.objectId());
        } else {
            breakSleepForStatusSpell(
                    null, questTarget, timeTarget,
                    "probability-spell-" + spell.skillId());
        }

        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, originX, originY)
                            && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.x(), target.y()))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION Phantasm caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
        }

        boolean probabilitySuccess = probability >= percentileRoll;
        boolean countered = probabilitySuccess && targetPlayer != null
                && targetPlayer.timedStatus.consumeCounterMagic(castNow);
        if (countered) publishCounterMagicConsumption(targetPlayer, spell.skillId());
        boolean applied = false;
        if (probabilitySuccess && !countered) {
            if (targetPlayer != null) {
                applied = targetPlayer.timedStatus.activateSleep(
                        castNow, spell.durationSeconds());
                if (applied) {
                    targetPlayer.sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.SLEEP_APPLY),
                            "S_PARALYSE mode=10 reason=Phantasm duration="
                                    + spell.durationSeconds());
                }
            } else if (controlledCompanion != null) {
                applied = controlledCompanion.activateSleep(
                        castNow, spell.durationSeconds());
            } else if (worldMonster != null) {
                applied = hub.sleepClassicWorldMonster(
                        originMapId, originInstanceId, target.objectId(),
                        castNow, spell.durationSeconds());
            } else if (questTarget != null) {
                applied = hub.sleepQuestMonster(
                        originRoomId, this, target.objectId(),
                        castNow, spell.durationSeconds());
            } else if (timeTarget != null) {
                applied = hub.sleepTimeAttackActor(
                        originRoomId, this, target.objectId(),
                        castNow, spell.durationSeconds());
            }
        }
        if (applied) {
            byte[] effect = Protocol.effectObject(
                    target.objectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                if (originPhase == Phase.WORLD
                        && (member.classicWorldMapId != originMapId
                            || member.classicWorldInstanceId != originInstanceId
                            || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.x(), target.y()))) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT Phantasm target=" + target.objectId()
                                + " gfx=" + spell.effectGfx());
            }
        }
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT Phantasm=" + remainingHp + "/" + playerMaxHp);
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Phantasm=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Phantasm caster=" + playerName()
                + " target=" + target.objectId() + " kind=" + target.kind()
                + " probability=" + probability + " roll=" + percentileRoll
                + " success=" + probabilitySuccess + " applied=" + applied
                + " countered=" + countered
                + " absolute-barrier-blocked=" + absoluteBarrierBlocked
                + " earth-bind-blocked=" + earthBindBlocked
                + " boss-immune=" + bossImmune
                + " target-failure=" + targetFailure
                + " stone-resistance=" + targetStoneResistance
                + " equipment-magic-hit=" + equipmentMagicHit
                + " buff-magic-hit=" + buffMagicHit
                + " total-magic-hit=" + totalMagicHit
                + " duration=" + spell.durationSeconds()
                + " hp-cost=" + spell.hpCost() + " mp-cost=" + mpCost
                + " hp=" + remainingHp + "/" + playerMaxHp
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " original-reduction=" + originalReduction
                + " persisted=" + spell.persisted()
                + " client-clock-ms=" + spell.clientCastClockMillis()
                + " phase=" + originPhase);
    }

    private void usePanicSpell(
            byte[] payload, BattleSpellCatalog.PanicSpell spell)
            throws IOException {
        usePanicSpell(payload, spell,
                config.panicSpellFixtureEnabled() ? 1 : 0);
    }

    /** Test-only fixed percentile; zero preserves the retained random roll. */
    private void usePanicSpell(
            byte[] payload, BattleSpellCatalog.PanicSpell spell,
            int percentileRollFixture) throws IOException {
        if (percentileRollFixture < 0 || percentileRollFixture > 100) {
            throw new IllegalArgumentException("invalid Panic percentile fixture");
        }
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || spell.requestShape()
                    != BattleSpellCatalog.RequestShape.SELECTOR_ONLY) return;
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Panic rejected"
                    + " learned/action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long targetNow = System.nanoTime();
        PatienceTarget target = resolveSelectorOnlyPanicTarget(
                originPhase, originRoomId, originMapId, originInstanceId,
                originX, originY, spell.maximumRange(), targetNow);
        if (target == null) return;

        ClientSession targetPlayer = target.player();
        BattleCompanion controlledCompanion = null;
        if (target.kind() == BattleTrueTarget.Kind.COMPANION) {
            List<ClientSession> owners = originPhase == Phase.WORLD
                    ? classicWorldMembers(originMapId)
                    : hub.visibleBattleCombatants(originRoomId, this);
            for (ClientSession owner : owners) {
                BattleCompanion candidate = owner.ownedCompanion(target.objectId());
                if (candidate != null && candidate.snapshot().active()
                        && candidate.snapshot().hp() > 0) {
                    controlledCompanion = candidate;
                    break;
                }
            }
        }
        ClassicWorldMonsterPopulation.Snapshot worldMonster =
                target.kind() == BattleTrueTarget.Kind.WORLD_MONSTER
                        ? hub.classicWorldMonster(
                            originMapId, originInstanceId, target.objectId()) : null;
        BattleQuestEncounter.Snapshot questTarget =
                target.kind() == BattleTrueTarget.Kind.QUEST_MONSTER
                        ? hub.questMonster(originRoomId, target.objectId()) : null;
        BattleTimeAttackEncounter.Snapshot timeTarget =
                target.kind() == BattleTrueTarget.Kind.TIME_ATTACK_ACTOR
                        ? hub.timeAttackActor(originRoomId, target.objectId()) : null;

        int npcId = controlledCompanion != null
                ? controlledCompanion.snapshot().npcId()
                : worldMonster != null ? worldMonster.npcId()
                : questTarget != null ? questTarget.npcId()
                : timeTarget != null ? timeTarget.npcId() : 0;
        SourceNpcPhysicalStats npcStats = null;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] C_USE_SPELL Panic rejected source"
                        + " npc=" + npcId + " reason="
                        + sourceFailure.getClass().getSimpleName() + ": "
                        + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                baseIntelligence(targetNow));
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(targetNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int targetLevel = targetPlayer != null
                ? targetPlayer.selectedCharacterSummary() == null ? 1
                    : Math.max(1, targetPlayer.selectedCharacterSummary().level())
                : controlledCompanion != null
                    ? Math.max(1, controlledCompanion.snapshot().level())
                : worldMonster != null ? Math.max(1, worldMonster.template().level())
                : questTarget != null ? Math.max(1, questTarget.level())
                : timeTarget != null ? Math.max(1, timeTarget.level()) : 1;
        int targetMr = targetPlayer != null
                ? targetPlayer.effectiveBaseMagicResistance(targetNow)
                : controlledCompanion != null
                    ? controlledCompanion.effectiveMagicResistance(
                        npcStats.magicResistance(), targetNow)
                : worldMonster != null
                    ? hub.classicWorldMonsterEffectiveMagicResistance(
                        originMapId, originInstanceId, target.objectId(),
                        npcStats.magicResistance(), targetNow)
                : effectiveNpcMagicResistance(
                        questTarget, timeTarget,
                        npcStats == null ? 0 : npcStats.magicResistance(),
                        targetNow);
        boolean targetAbsoluteBarrierAtSelection = targetPlayer != null
                && targetPlayer.timedStatus.absoluteBarrierActive(targetNow);
        boolean bossTarget = npcStats != null && npcStats.boss()
                || worldMonster != null && worldMonster.template().boss()
                || timeTarget != null && timeTarget.finalBoss();

        int remainingHp;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterContext = phase == originPhase && !observer
                    && playerHp > spell.hpCost()
                    && positionX == originX && positionY == originY
                    && (originPhase == Phase.WORLD
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            PatienceTarget currentTarget;
            if (target.player() == this) {
                currentTarget = sameCasterContext ? target : null;
            } else {
                Map<Long, PatienceTarget> current = phantasmTargets(
                        originPhase, originRoomId, originMapId, originInstanceId,
                        originX, originY, spell.maximumRange(), castNow);
                currentTarget = current == null ? null
                        : current.get(target.objectId());
                if (currentTarget != null && currentTarget.kind() != target.kind()) {
                    currentTarget = null;
                }
            }
            if (castNow < readyAt || playerMp < mpCost
                    || !sameCasterContext || currentTarget == null) {
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE Panic-insufficient-mp=278");
                }
                System.out.println("[LiTo] C_USE_SPELL Panic rejected state"
                        + " player=" + playerName() + " target=" + target.objectId()
                        + " hp=" + playerHp + " hp-cost=" + spell.hpCost()
                        + " mp=" + playerMp + " mp-cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow)
                        + " phase=" + originPhase);
                return;
            }
            target = currentTarget;
            cancelMeditation("spell-" + spell.skillId());
            playerHp -= spell.hpCost();
            playerMp -= mpCost;
            remainingHp = playerHp;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        boolean absoluteBarrierBlocked = targetPlayer != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                    targetAbsoluteBarrierAtSelection
                        || targetPlayer.timedStatus.absoluteBarrierActive(castNow),
                    spell.skillId());
        boolean earthBindBlocked = targetPlayer != null
                ? targetPlayer.timedStatus.earthBindActive(castNow)
                : questTarget != null
                    ? hub.questMonsterEarthBindActive(
                        originRoomId, target.objectId(), castNow)
                    : timeTarget != null
                        && hub.timeAttackActorEarthBindActive(
                            originRoomId, target.objectId(), castNow);
        boolean targetFailure = target.kind() == BattleTrueTarget.Kind.GUARDIAN_TOWER
                || target.kind() == BattleTrueTarget.Kind.ARENA_BOT;
        int probability = absoluteBarrierBlocked || earthBindBlocked
                || targetFailure ? 0
                : spell.probability(casterLevel, targetLevel,
                    effectiveIntelligence, totalMagicHit, targetMr, bossTarget);
        int percentileRoll = probability == 0 ? 100
                : percentileRollFixture == 0
                    ? ThreadLocalRandom.current().nextInt(1, 101)
                    : percentileRollFixture;

        if (targetPlayer != null) {
            targetPlayer.eraseMagicStatus.consume(castNow);
        } else if (controlledCompanion != null) {
            controlledCompanion.consumeEraseMagic(castNow);
        } else if (worldMonster != null) {
            hub.consumeClassicWorldMonsterEraseMagic(
                    originMapId, originInstanceId, target.objectId(), castNow);
        } else {
            consumeEraseMagicAfterProbability(
                    null, questTarget, timeTarget, castNow, spell.skillId());
        }
        if (targetPlayer != null) {
            targetPlayer.cancelSleep("probability-spell-" + spell.skillId());
        } else if (controlledCompanion != null) {
            controlledCompanion.cancelSleep();
        } else if (worldMonster != null) {
            hub.cancelClassicWorldMonsterSleep(
                    originMapId, originInstanceId, target.objectId());
        } else {
            breakSleepForStatusSpell(
                    null, questTarget, timeTarget,
                    "probability-spell-" + spell.skillId());
        }

        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, originX, originY)
                            && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.x(), target.y()))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION Panic caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
        }

        boolean probabilitySuccess = probability >= percentileRoll;
        boolean countered = probabilitySuccess && targetPlayer != null
                && targetPlayer.timedStatus.consumeCounterMagic(castNow);
        if (countered) publishCounterMagicConsumption(targetPlayer, spell.skillId());
        boolean firstApplied = false;
        if (probabilitySuccess && !countered) {
            if (targetPlayer != null) {
                firstApplied = targetPlayer.abilityStatus.activatePanic(
                        castNow, spell.durationSeconds(),
                        spell.abilityScoreModifier());
            } else if (controlledCompanion != null) {
                firstApplied = controlledCompanion.activatePanic(
                        castNow, spell.durationSeconds(),
                        spell.abilityScoreModifier());
            } else if (worldMonster != null) {
                firstApplied = hub.panicClassicWorldMonster(
                        originMapId, originInstanceId, target.objectId(),
                        castNow, spell.durationSeconds(),
                        spell.abilityScoreModifier());
            } else if (questTarget != null) {
                firstApplied = hub.panicQuestMonster(
                        originRoomId, this, target.objectId(), castNow,
                        spell.durationSeconds(), spell.abilityScoreModifier());
            } else if (timeTarget != null) {
                firstApplied = hub.panicTimeAttackActor(
                        originRoomId, this, target.objectId(), castNow,
                        spell.durationSeconds(), spell.abilityScoreModifier());
            }
        }
        boolean effectAccepted = probabilitySuccess && !countered;
        if (effectAccepted) {
            byte[] effect = Protocol.effectObject(target.objectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                if (originPhase == Phase.WORLD
                        && (member.classicWorldMapId != originMapId
                            || member.classicWorldInstanceId != originInstanceId
                            || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.x(), target.y()))) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT Panic target=" + target.objectId()
                                + " gfx=" + spell.effectGfx());
            }
            if (targetPlayer != null && firstApplied) {
                targetPlayer.sendAbilityScoresStatus(castNow, "panic-applied");
            }
        }
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT Panic=" + remainingHp + "/" + playerMaxHp);
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Panic=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Panic caster=" + playerName()
                + " target=" + target.objectId() + " kind=" + target.kind()
                + " probability=" + probability + " roll=" + percentileRoll
                + " success=" + probabilitySuccess
                + " first-applied=" + firstApplied
                + " countered=" + countered
                + " absolute-barrier-blocked=" + absoluteBarrierBlocked
                + " earth-bind-blocked=" + earthBindBlocked
                + " boss-immune=" + bossTarget
                + " target-failure=" + targetFailure
                + " effective-intelligence=" + effectiveIntelligence
                + " mr=" + targetMr
                + " equipment-magic-hit=" + equipmentMagicHit
                + " buff-magic-hit=" + buffMagicHit
                + " total-magic-hit=" + totalMagicHit
                + " duration=" + spell.durationSeconds()
                + " hp-cost=" + spell.hpCost() + " mp-cost=" + mpCost
                + " hp=" + remainingHp + "/" + playerMaxHp
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " original-reduction=" + originalReduction
                + " persisted=" + spell.persisted()
                + " client-clock-ms=" + spell.clientCastClockMillis()
                + " phase=" + originPhase);
    }

