    private void useWeightSpell(byte[] payload, BattleSpellCatalog.WeightSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=weight-spell-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE weight-spell-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=weight-spell-Silence-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE weight-spell-Silence-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE weight-spell-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL rejected unlearned weight spell"
                    + " player=" + playerName() + " skill=" + spell.skillId());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL weight spell rejected selector/action player="
                    + playerName() + " skill=" + request.skillId());
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        RuntimeInventory previousInventory;
        RuntimeInventory nextInventory;
        int remainingHp;
        int remainingMp;
        int rejectionMessage = 0;
        long now = System.nanoTime();
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameOrigin = phase == originPhase && !observer && playerHp > 0
                    && positionX == originX && positionY == originY
                    && (originPhase == Phase.BATTLE
                        ? currentRoomId == originRoomId
                        : classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId);
            if (now < readyAt || !sameOrigin) {
                System.out.println("[LiTo] C_USE_SPELL weight spell rejected state skill="
                        + spell.skillId() + " hp=" + playerHp + " mp=" + playerMp
                        + " cooldownNanos=" + Math.max(0L, readyAt - now));
                return;
            }
            if (playerHp < spell.hpCost() + 1) {
                rejectionMessage = 279;
            } else if (playerMp < spell.mpCost()) {
                rejectionMessage = 278;
            }
            if (rejectionMessage != 0) {
                previousInventory = inventory;
                nextInventory = inventory;
                remainingHp = playerHp;
                remainingMp = playerMp;
            } else {
                nextInventory = inventory.copy();
                if (spell.itemConsumeId() != 0
                        && !nextInventory.removeCatalog(
                                spell.itemConsumeId(), spell.itemConsumeCount())) {
                    System.out.println("[LiTo] C_USE_SPELL weight spell rejected missing reagent skill="
                            + spell.skillId() + " catalog=" + spell.itemConsumeId()
                            + " count=" + spell.itemConsumeCount());
                    return;
                }
                cancelMeditation("spell-" + spell.skillId());
                weightStatus.activate(spell.skillId(), now, spell.durationSeconds());
                previousInventory = inventory;
                inventory = nextInventory;
                playerHp -= spell.hpCost();
                playerMp -= spell.mpCost();
                remainingHp = playerHp;
                remainingMp = playerMp;
                commitSpellReady(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        }

        if (rejectionMessage != 0) {
            sendEncrypted(Protocol.messageCode(rejectionMessage),
                    "S_MESSAGE_CODE weight-spell-insufficient=" + rejectionMessage
                            + " skill=" + spell.skillId());
            System.out.println("[LiTo] C_USE_SPELL weight spell rejected resource skill="
                    + spell.skillId() + " message=" + rejectionMessage
                    + " hp=" + remainingHp + " mp=" + remainingMp);
            return;
        }

        if (spell.itemConsumeId() != 0) {
            sendInventoryDelta(previousInventory, inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        }
        revealInvisibility("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        byte[] action = new Protocol.Writer().c(Protocol.S_ACTION)
                .d(playerObjectId()).c(spell.actionId()).bytes();
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                member.positionX, member.positionY))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION weight-spell-cast object=" + playerObjectId()
                                + " action=" + spell.actionId()
                                + " skill=" + spell.skillId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT weight-spell target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        if (spell.hpCost() != 0) {
            sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                            .h(remainingHp).h(playerMaxHp).bytes(),
                    "S_HIT_POINT weight-spell=" + remainingHp + "/" + playerMaxHp);
            broadcastOwnHitRatio("weight-spell-hp-cost");
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT weight-spell=" + remainingMp + "/" + playerMaxMp);
        if (spell.itemConsumeId() == 0) {
            sendNativeBattleStatus(now, "weight-spell-" + spell.skillId());
        }
        System.out.println("[LiTo] C_USE_SPELL weight spell skill=" + spell.skillId()
                + " key=" + spell.key() + " caster=" + playerName()
                + " duration=" + spell.durationSeconds()
                + " weight240=" + currentWeight240(now)
                + " hp=" + remainingHp + "/" + playerMaxHp
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase);
    }

    /**
     * Skill206 has PC/range3 semantics in the selected database, but its exact
     * LiTo producer is selector-only. Reuse the last admitted combat target,
     * otherwise the sole eligible external PC, and finally the caster. More
     * than one unresolved external candidate fails closed.
     */
    private ClientSession resolveSelectorOnlyConcentrationTarget(
            BattleSpellCatalog.RegenSpell spell, Phase originPhase,
            long originRoomId, int originMapId, int originInstanceId,
            int originX, int originY, long nowNanos) {
        if (spell.targeting() == BattleSpellCatalog.Targeting.SELF_SELECTOR) {
            return this;
        }
        List<ClientSession> candidates = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.roomCombatants(originRoomId);
        ArrayList<ClientSession> eligibleExternal = new ArrayList<>();
        ClientSession lastExplicit = null;
        ClassicWorldMapCatalog.ClassicMap map = originPhase == Phase.WORLD
                ? ClassicWorldMapCatalog.forMap(originMapId) : null;
        for (ClientSession candidate : candidates) {
            if (candidate == null || candidate == this || candidate.observer
                    || candidate.playerHp <= 0 || candidate.invisible
                    || candidate.timedStatus.absoluteBarrierActive(nowNanos)) {
                continue;
            }
            boolean sameContext = originPhase == Phase.BATTLE
                    ? candidate.phase == Phase.BATTLE
                        && candidate.currentRoomId == originRoomId
                    : candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId;
            if (!sameContext || targetRange(originX, originY,
                    candidate.positionX, candidate.positionY)
                    > spell.maximumRange()) continue;
            if (map != null && !map.attackPosition(
                    originX, originY, candidate.positionX, candidate.positionY,
                    spell.maximumRange())) continue;
            eligibleExternal.add(candidate);
            if (candidate.playerObjectId() == lastCombatTargetObjectId) {
                lastExplicit = candidate;
            }
        }
        if (lastExplicit != null) return lastExplicit;
        if (eligibleExternal.size() == 1) return eligibleExternal.get(0);
        if (eligibleExternal.isEmpty()) return this;
        System.out.println("[LiTo] C_USE_SPELL Concentration rejected"
                + " ambiguous selector-only PC target player=" + playerName()
                + " last-explicit=" + lastCombatTargetObjectId
                + " eligible-external=" + eligibleExternal.size()
                + " phase=" + originPhase);
        return null;
    }

    private void useRegenSpell(byte[] payload, BattleSpellCatalog.RegenSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || spell.requestShape()
                    != BattleSpellCatalog.RequestShape.SELECTOR_ONLY) return;
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL regen buff rejected learned/action"
                    + " skill=" + spell.skillId() + " caster=" + playerName());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = casterEquipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);

        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long targetNow = System.nanoTime();
        ClientSession target = resolveSelectorOnlyConcentrationTarget(
                spell, originPhase, originRoomId, originMapId,
                originInstanceId, originX, originY, targetNow);
        if (target == null) return;

        ClientSession firstLock = playerObjectId() <= target.playerObjectId()
                ? this : target;
        ClientSession secondLock = firstLock == this ? target : this;
        int remainingHp;
        int remainingMp;
        int rejectionMessage = 0;
        long castNow = System.nanoTime();
        synchronized (firstLock) {
            synchronized (secondLock) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                boolean contextStillValid = originPhase == Phase.BATTLE
                        ? phase == Phase.BATTLE && currentRoomId == originRoomId
                            && target.phase == Phase.BATTLE
                            && target.currentRoomId == originRoomId
                        : phase == Phase.WORLD
                            && classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                            && target.phase == Phase.WORLD
                            && target.classicWorldMapId == originMapId
                            && target.classicWorldInstanceId == originInstanceId;
                boolean targetStillAllowed = target == this
                        || !target.observer && target.playerHp > 0
                            && !target.invisible
                            && !target.timedStatus.absoluteBarrierActive(castNow)
                            && targetRange(originX, originY,
                                target.positionX, target.positionY)
                                <= spell.maximumRange()
                            && (originPhase != Phase.WORLD
                                || ClassicWorldMapCatalog.forMap(originMapId)
                                    .attackPosition(originX, originY,
                                        target.positionX, target.positionY,
                                        spell.maximumRange()));
                if (castNow < readyAt || !contextStillValid || observer
                        || playerHp <= 0 || !targetStillAllowed) {
                    System.out.println("[LiTo] C_USE_SPELL regen buff rejected state skill="
                            + spell.skillId() + " hp=" + playerHp + " mp=" + playerMp
                            + " cooldownNanos=" + Math.max(0L, readyAt - castNow)
                            + " phase=" + originPhase);
                    return;
                }
                if (playerHp < spell.hpCost() + 1) {
                    rejectionMessage = 279;
                } else if (playerMp < mpCost) {
                    rejectionMessage = 278;
                }
                if (rejectionMessage == 0) {
                    cancelMeditation("spell-" + spell.skillId());
                    if (spell.effect() == BattleSpellCatalog.RegenEffect.MEDITATION) {
                        target.timedStatus.activateMeditation(
                                castNow, spell.durationSeconds());
                    } else {
                        target.timedStatus.activateConcentration(
                                castNow, spell.durationSeconds());
                    }
                    playerHp -= spell.hpCost();
                    playerMp -= mpCost;
                    commitSpellReady(spell.skillId(), castNow
                            + spell.reuseDelayMillis() * 1_000_000L);
                }
                remainingHp = playerHp;
                remainingMp = playerMp;
            }
        }
        if (rejectionMessage != 0) {
            sendEncrypted(Protocol.messageCode(rejectionMessage),
                    "S_MESSAGE_CODE regen-spell-insufficient=" + rejectionMessage
                            + " skill=" + spell.skillId());
            System.out.println("[LiTo] C_USE_SPELL regen buff rejected resource skill="
                    + spell.skillId() + " message=" + rejectionMessage
                    + " hp=" + remainingHp + " mp=" + remainingMp);
            return;
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(
                target.playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY)
                            && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.positionX, target.positionY))) continue;
            member.sendEncrypted(action,
                    "S_ACTION regen-spell-cast object=" + playerObjectId()
                            + " action=" + spell.actionId()
                            + " skill=" + spell.skillId());
            member.sendEncrypted(effect,
                    "S_EFFECT regen-spell target=" + target.playerObjectId()
                            + " gfx=" + spell.effectGfx()
                            + " skill=" + spell.skillId());
        }
        if (spell.hpCost() != 0) {
            sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                            .h(remainingHp).h(playerMaxHp).bytes(),
                    "S_HIT_POINT regen-spell=" + remainingHp + "/" + playerMaxHp);
            broadcastOwnHitRatio("regen-spell-hp-cost");
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT regen-spell=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL regen buff=" + spell.key()
                + " caster=" + playerName() + " target=" + target.playerName()
                + " duration=" + spell.durationSeconds() + " mpr=" + spell.mprBonus()
                + " client-clock-ms=" + spell.clientCastClockMillis()
                + " hp=" + remainingHp + "/" + playerMaxHp
                + " effective-int=" + effectiveIntelligence
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase);
    }

    private boolean sameNonemptyClan(ClientSession target) {
        return hub.sameClan(sourceCharacterIdentity(), target.sourceCharacterIdentity());
    }

    private boolean sameClassicParty(ClientSession target) {
        GameHub.ClassicPartyData party = hub.classicPartyData(sourceCharacterIdentity());
        return party.inParty() && party.memberIdentities().stream()
                .anyMatch(name -> name.equalsIgnoreCase(target.sourceCharacterIdentity()));
    }

    /**
     * Builds the retained L1Character-style world lookup for skill 113.  The
     * selected client supplies an object id plus advisory coordinates; every
     * accepted coordinate and identity below comes from current server state.
     */
    private BattleTrueTarget.Candidate resolveTrueTargetCandidate(
            long requestedObjectId, Phase originPhase, long originRoomId,
            int originMapId, int originInstanceId,
            int sourceX, int sourceY, long nowNanos) {
        List<BattleTrueTarget.Candidate> candidates = new ArrayList<>();
        if (originPhase == Phase.WORLD) {
            List<ClientSession> members = classicWorldMembers(originMapId);
            for (ClientSession candidate : members) {
                boolean sameWorld = candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId;
                boolean alive = !candidate.observer && candidate.playerHp > 0;
                boolean visible = (candidate == this || !candidate.invisible)
                        && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                                candidate.timedStatus.absoluteBarrierActive(nowNanos),
                                BattleSpellCatalog.TRUE_TARGET);
                candidates.add(new BattleTrueTarget.Candidate(
                        candidate.playerObjectId(), candidate.positionX,
                        candidate.positionY, BattleTrueTarget.Kind.PLAYER,
                        alive, visible, sameWorld));
            }
            for (ClientSession owner : members) {
                boolean sameWorld = owner.phase == Phase.WORLD
                        && owner.classicWorldMapId == originMapId
                        && owner.classicWorldInstanceId == originInstanceId;
                for (BattleCompanion.Snapshot companion
                        : owner.classicWorldCompanionSnapshots()) {
                    candidates.add(new BattleTrueTarget.Candidate(
                            companion.objectId(), companion.x(), companion.y(),
                            BattleTrueTarget.Kind.COMPANION,
                            companion.active() && companion.hp() > 0,
                            companion.active(), sameWorld));
                }
            }
            for (ClassicWorldMonsterPopulation.Snapshot monster
                    : hub.classicWorldMonstersInScreen(
                            originMapId, originInstanceId, sourceX, sourceY)) {
                candidates.add(new BattleTrueTarget.Candidate(
                        monster.objectId(), monster.x(), monster.y(),
                        BattleTrueTarget.Kind.WORLD_MONSTER,
                        monster.present() && monster.alive(), monster.present(),
                        monster.mapId() == originMapId));
            }
            return BattleTrueTarget.resolve(requestedObjectId, candidates);
        }

        BattleRules.Mode mode = hub.roomRules(originRoomId).mode();
        int casterMap = hub.battleMapId(originRoomId, this);
        List<ClientSession> combatants = hub.roomCombatants(originRoomId);
        List<ClientSession> visibleCombatants = hub.visibleBattleCombatants(
                originRoomId, this);

        for (ClientSession candidate : combatants) {
            boolean sameWorld = visibleCombatants.contains(candidate)
                    && hub.battleMapId(originRoomId, candidate) == casterMap;
            boolean alive = candidate.phase == Phase.BATTLE
                    && !candidate.observer && candidate.playerHp > 0;
            boolean visible = (candidate == this || !candidate.invisible)
                    && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                            candidate.timedStatus.absoluteBarrierActive(nowNanos),
                            BattleSpellCatalog.TRUE_TARGET);
            candidates.add(new BattleTrueTarget.Candidate(
                    candidate.playerObjectId(), candidate.positionX,
                    candidate.positionY, BattleTrueTarget.Kind.PLAYER,
                    alive, visible, sameWorld));
        }

        for (ClientSession owner : visibleCombatants) {
            boolean sameWorld = hub.battleMapId(originRoomId, owner) == casterMap;
            for (BattleCompanion.Snapshot companion
                    : owner.controlledCompanionSnapshots()) {
                candidates.add(new BattleTrueTarget.Candidate(
                        companion.objectId(), companion.x(), companion.y(),
                        BattleTrueTarget.Kind.COMPANION,
                        companion.active() && companion.hp() > 0,
                        companion.active(), sameWorld));
            }
        }

        for (BattleGuardianTower.Snapshot tower
                : hub.visibleGuardianTowers(originRoomId, this)) {
            candidates.add(new BattleTrueTarget.Candidate(
                    tower.objectId(), tower.x(), tower.y(),
                    BattleTrueTarget.Kind.GUARDIAN_TOWER,
                    !tower.destroyed() && tower.hp() > 0,
                    !tower.destroyed(), true));
        }
        for (BattleQuestEncounter.Snapshot monster
                : hub.visibleQuestMonsters(originRoomId, this)) {
            candidates.add(new BattleTrueTarget.Candidate(
                    monster.objectId(), monster.x(), monster.y(),
                    BattleTrueTarget.Kind.QUEST_MONSTER,
                    monster.alive() && monster.hp() > 0,
                    monster.alive(), true));
        }
        for (BattleTimeAttackEncounter.Snapshot actor
                : hub.visibleTimeAttackActors(originRoomId, this)) {
            candidates.add(new BattleTrueTarget.Candidate(
                    actor.objectId(), actor.x(), actor.y(),
                    BattleTrueTarget.Kind.TIME_ATTACK_ACTOR,
                    actor.alive() && actor.hp() > 0,
                    actor.alive(), true));
        }

        if (mode != BattleRules.Mode.QUEST_BATTLE
                && mode != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(originRoomId) < 2
                && hub.botHp(originRoomId) > 0) {
            ArenaMapCatalog.Point bot = hub.botPosition(originRoomId);
            if (bot == null) bot = ArenaMapCatalog.forMap(casterMap).botSpawn();
            if (bot != null) {
                candidates.add(new BattleTrueTarget.Candidate(
                        2, bot.x(), bot.y(), BattleTrueTarget.Kind.ARENA_BOT,
                        true, true, true));
            }
        }
        return BattleTrueTarget.resolve(requestedObjectId, candidates);
    }

    private void useTrueTargetSpell(byte[] payload,
                                    BattleSpellCatalog.TrueTargetSpell spell)
            throws IOException {
        Protocol.TrueTargetRequest request = Protocol.trueTargetRequest(payload);
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (originPhase != Phase.BATTLE && !classicWorld) {
            System.out.println("[LiTo] C_USE_SPELL True Target rejected phase="
                    + originPhase + " player=" + playerName());
            return;
        }
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "True-Target")) return;

        long originRoomId = currentRoomId;
        int originMapId = classicWorld
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long now = System.nanoTime();
        BattleTrueTarget.Candidate target = resolveTrueTargetCandidate(
                request.targetObjectId(), originPhase, originRoomId,
                originMapId, originInstanceId, originX, originY, now);
        if (target == null || !BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL True Target rejected target="
                    + request.targetObjectId() + " player=" + playerName());
            return;
        }

        boolean lineOfSight = classicWorld
                ? ClassicWorldMapCatalog.forMap(originMapId).hasLineOfSight(
                        originX, originY, target.x(), target.y())
                : BattleSpellCatalog.hasNativeLineOfSight(
                        ArenaMapCatalog.forMap(originMapId),
                        originX, originY, target.x(), target.y());
        if (!BattleSpellCatalog.isInNativeScreen(
                    originX, originY, target.x(), target.y())
                || !lineOfSight) {
            System.out.println("[LiTo] C_USE_SPELL True Target rejected outside-screen target="
                    + request.targetObjectId() + " source=" + originX + "," + originY
                    + " target-position=" + target.x() + "," + target.y());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int remainingMp = -1;
        boolean insufficientMp = false;
        BattleTrueTarget.Candidate commitTarget = resolveTrueTargetCandidate(
                request.targetObjectId(), originPhase, originRoomId,
                originMapId, originInstanceId, originX, originY,
                System.nanoTime());
        if (!target.equals(commitTarget)) {
            System.out.println("[LiTo] C_USE_SPELL True Target rejected moved target="
                    + request.targetObjectId() + " player=" + playerName());
            return;
        }
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterContext = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (classicWorld
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            if (now < readyAt || !sameCasterContext) {
                System.out.println("[LiTo] C_USE_SPELL True Target rejected state skill="
                        + spell.skillId() + " mp=" + playerMp
                        + " cooldownNanos=" + Math.max(0L, readyAt - now));
                return;
            }
            if (playerMp < mpCost) {
                insufficientMp = true;
            } else {
                cancelMeditation("spell-" + spell.skillId());
                playerMp -= mpCost;
                remainingMp = playerMp;
                commitSpellReady(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        }
        if (insufficientMp) {
            sendEncrypted(Protocol.messageCode(278),
                    "S_MESSAGE_CODE True-Target-insufficient-mp=278");
            System.out.println("[LiTo] C_USE_SPELL True Target rejected insufficient-mp"
                    + " player=" + playerName() + " mp=" + playerMp
                    + " mp-cost=" + mpCost);
            return;
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        byte[] action = new Protocol.Writer().c(Protocol.S_ACTION)
                .d(playerObjectId()).c(spell.actionId()).bytes();
        List<ClientSession> actionRecipients = classicWorld
                ? classicWorldMembers(originMapId).stream()
                    .filter(member -> member.phase == Phase.WORLD
                            && member.classicWorldMapId == originMapId
                            && member.classicWorldInstanceId == originInstanceId
                            && BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    originX, originY))
                    .toList()
                : hub.battleRecipients(
                        originRoomId, hub.forceOf(originRoomId, this));
        for (ClientSession member : actionRecipients) {
            member.sendEncrypted(action,
                    "S_ACTION True Target caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        LinkedHashSet<ClientSession> recipients = new LinkedHashSet<>();
        recipients.add(this);
        if (!hub.clanData(sourceCharacterIdentity()).name().isBlank()) {
            List<ClientSession> audience = classicWorld
                    ? classicWorldMembers(originMapId)
                    : hub.visibleBattleCombatants(originRoomId, this);
            for (ClientSession candidate : audience) {
                boolean sameWorld = classicWorld
                        ? candidate.phase == Phase.WORLD
                            && candidate.classicWorldMapId == originMapId
                            && candidate.classicWorldInstanceId == originInstanceId
                        : candidate.phase == Phase.BATTLE
                            && hub.battleMapId(originRoomId, candidate) == originMapId;
                if (sameWorld && !candidate.observer
                        && hub.sameClan(sourceCharacterIdentity(),
                                candidate.sourceCharacterIdentity())
                        && BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.positionX, candidate.positionY)) {
                    recipients.add(candidate);
                }
            }
        }
        byte[] marker = Protocol.commandTarget(
                target.objectId(), target.x(), target.y(), request.text());
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(marker,
                    "S_COMMAND_TARGET skill=" + spell.skillId()
                            + " target=" + target.objectId()
                            + " x=" + target.x() + " y=" + target.y()
                            + " caster=" + playerName());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT True Target=" + remainingMp + "/" + playerMaxMp);
        if (request.x() != target.x() || request.y() != target.y()) {
            System.out.println("[LiTo] C_USE_SPELL True Target ignored stale coordinates client="
                    + request.x() + "," + request.y() + " server="
                    + target.x() + "," + target.y());
        }
        System.out.println("[LiTo] C_USE_SPELL True Target accepted caster=" + playerName()
                + " target=" + target.objectId() + " kind=" + target.kind()
                + " recipients=" + recipients.size() + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " counter-magic-bypass=" + spell.counterMagicBypass());
    }

    private void useRoyalAuraSpell(
            byte[] payload, BattleSpellCatalog.RoyalAuraSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (request.skillId() != spell.skillId()
                || (originPhase != Phase.BATTLE && !classicWorld)
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL royal aura rejected selector/action"
                    + " player=" + playerName() + " skill=" + request.skillId());
            return;
        }
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Royal-Aura")) return;

        long now = System.nanoTime();
        long originRoomId = currentRoomId;
        int casterMap = classicWorld
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        LinkedHashSet<ClientSession> targets = new LinkedHashSet<>();
        targets.add(this);
        List<ClientSession> targetPool = classicWorld
                ? classicWorldMembers(casterMap)
                : hub.roomCombatants(originRoomId);
        for (ClientSession candidate : targetPool) {
            boolean partyTarget = (spell.targetTo() & 8) != 0
                    && sameClassicParty(candidate);
            boolean clanTarget = (spell.targetTo() & 4) != 0
                    && sameNonemptyClan(candidate);
            boolean sameWorld = classicWorld
                    ? candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == casterMap
                        && candidate.classicWorldInstanceId == originInstanceId
                    : candidate.phase == Phase.BATTLE
                        && candidate.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, candidate) == casterMap;
            if (candidate == this || !sameWorld
                    || candidate.observer || candidate.playerHp <= 0
                    || (!partyTarget && !clanTarget)
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY,
                            candidate.positionX, candidate.positionY)) {
                continue;
            }
            targets.add(candidate);
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int remainingMp;
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterContext = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (classicWorld
                        ? classicWorldMapId == casterMap
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == casterMap);
            if (now < readyAt || playerMp < mpCost || !sameCasterContext) {
                System.out.println("[LiTo] C_USE_SPELL royal aura rejected state skill="
                        + spell.skillId() + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - now));
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), now
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        targets.removeIf(target -> target != this && (target.phase != originPhase
                || target.observer || target.playerHp <= 0
                || (classicWorld
                    ? target.classicWorldMapId != casterMap
                        || target.classicWorldInstanceId != originInstanceId
                    : target.currentRoomId != originRoomId
                        || hub.battleMapId(originRoomId, target) != casterMap)
                || !(((spell.targetTo() & 8) != 0
                            && sameClassicParty(target))
                        || ((spell.targetTo() & 4) != 0
                            && sameNonemptyClan(target)))
                || !BattleSpellCatalog.isInNativeScreen(
                        originX, originY, target.positionX, target.positionY)));
        Map<ClientSession, Integer> replaced = new LinkedHashMap<>();
        boolean braveAura = spell.skillId() == BattleSpellCatalog.BRAVE_AURA;
        for (ClientSession target : targets) {
            synchronized (target) {
                if (braveAura) {
                    target.abilityStatus.activateBraveAura(
                            now, spell.durationSeconds(), spell.meleeDamage());
                    replaced.put(target, 0);
                } else {
                    replaced.put(target, target.abilityStatus.activateRoyalAura(
                            spell.skillId(), now, spell.durationSeconds(),
                            spell.armorClass(), spell.meleeHit(), spell.rangedHit(),
                            spell.magicResistance()));
                }
            }
        }

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(casterMap)
                : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            boolean seesCaster = !classicWorld || (member.phase == Phase.WORLD
                    && member.classicWorldMapId == casterMap
                    && member.classicWorldInstanceId == originInstanceId
                    && BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            originX, originY));
            if (seesCaster) {
                member.sendEncrypted(action,
                        "S_ACTION royal-aura caster=" + playerObjectId()
                                + " action=" + spell.actionId()
                                + " skill=" + spell.skillId());
            }
            for (ClientSession target : targets) {
                if (classicWorld && (member.phase != Phase.WORLD
                        || member.classicWorldMapId != casterMap
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.positionX, target.positionY))) continue;
                member.sendEncrypted(
                        Protocol.effectObject(target.playerObjectId(), spell.effectGfx()),
                        "S_EFFECT royal-aura target=" + target.playerObjectId()
                                + " gfx=" + spell.effectGfx()
                                + " skill=" + spell.skillId());
            }
        }
        for (ClientSession target : targets) {
            BattleSpellCatalog.RoyalAuraSpell previous =
                    BattleSpellCatalog.royalAuraSpell(replaced.get(target));
            if (spell.armorClass() != 0
                    || (previous != null && previous.armorClass() != 0)) {
                target.sendArmorClassStatus(
                        "royal-aura-start-" + spell.skillId());
            }
            if (spell.magicResistance() != 0
                    || (previous != null && previous.magicResistance() != 0)) {
                target.sendMagicStatus(
                        now, "royal-aura-start-" + spell.skillId());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT royal-aura=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL royal aura=" + spell.key()
                + " caster=" + playerName() + " targets="
                + targets.stream().map(ClientSession::playerName).toList()
                + " duration=" + spell.durationSeconds()
                + " ac=" + spell.armorClass()
                + " melee-hit=" + spell.meleeHit()
                + " ranged-hit=" + spell.rangedHit()
                + " mr=" + spell.magicResistance()
                + " melee-damage=" + spell.meleeDamage()
                + " effective-original-reduction=" + originalReduction
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " counter-magic-bypass=" + spell.counterMagicBypass()
                + " icon=omitted-selected-LiTo-FA-is-tournament-clan");
    }

    private void useCallClanSpell(
            byte[] payload, BattleSpellCatalog.CallClanSpell spell)
            throws IOException {
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Call-Clan")) return;
        Protocol.CallClanSpellRequest request = Protocol.callClanSpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            rejectCallClan(spell, "selector-or-action", spell.failureMessage(), null);
            return;
        }

        ClientSession target = classicWorld
                ? hub.onlineMemberByName(this, request.targetName())
                : hub.activeMemberByName(this, request.targetName());
        if (target == null) {
            rejectCallClan(spell, "target-offline-or-ambiguous", 73,
                    request.targetName());
            return;
        }
        if (!sameNonemptyClan(target)) {
            rejectCallClan(spell, "target-not-same-nonempty-clan", 414, null);
            return;
        }
        if (!callClanSharedContext(target)) {
            // Tournament rooms are separate authoritative worlds.  The
            // classic skill cannot import a lobby actor or another match.
            rejectCallClan(spell, "target-outside-caster-world", 629, null);
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int remainingMp;
        PendingCallClan invitation;
        long now = System.nanoTime();
        long originRoomId = classicWorld ? 0 : currentRoomId;
        int originMapId = classicWorld
                ? classicWorldMapId : hub.battleMapId(currentRoomId, this);
        int originInstanceId = classicWorld ? classicWorldInstanceId : -1;
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean originStillValid = classicWorld
                    ? phase == Phase.WORLD && classicWorldMapId == originMapId
                        && classicWorldInstanceId == originInstanceId
                    : phase == Phase.BATTLE && currentRoomId == originRoomId
                        && currentRoomId != 0;
            if (now < readyAt || playerMp < mpCost || !originStillValid
                    || observer || playerHp <= 0
                    || pendingPortal != null || hub.hasPrivateShop(this)) {
                rejectCallClan(spell, "mp-cooldown-or-caster-state",
                        spell.failureMessage(), null);
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), now
                    + spell.reuseDelayMillis() * 1_000_000L);
            invitation = new PendingCallClan(
                    this, originPhase, originRoomId, originMapId, originInstanceId,
                    positionX, positionY, Math.floorMod(playerHeading, 8),
                    now + CALL_CLAN_INVITE_TIMEOUT_NANOS);
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        boolean published = callClanSharedContext(target)
                && sameNonemptyClan(target)
                && publishCallClanPrompt(target, invitation, now);

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        List<ClientSession> actionRecipients = classicWorld
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : actionRecipients) {
            if (classicWorld && (member.classicWorldInstanceId != originInstanceId
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            invitation.casterX(), invitation.casterY()))) continue;
            member.sendEncrypted(action, "S_ACTION Call Clan caster="
                    + playerObjectId() + " action=" + spell.actionId()
                    + " phase=" + originPhase);
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Call Clan=" + remainingMp + "/" + playerMaxMp);
        if (published) {
            target.sendEncrypted(Protocol.callClanAsk(),
                    "S_ASK question=" + spell.questionId()
                            + " Call Clan caster=" + playerName());
        }
        System.out.println("[LiTo] C_USE_SPELL Call Clan caster=" + playerName()
                + " target=" + target.playerName() + " selector="
                + request.row() + "/" + request.column()
                + " snapshot=" + invitation.mapId() + ":"
                + invitation.casterX() + "," + invitation.casterY()
                + " heading=" + invitation.casterHeading()
                + " prompt-published=" + published
                + " effective-original-reduction=" + originalReduction
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " counter-magic-bypass=" + spell.counterMagicBypass());
    }

    private boolean callClanSharedContext(ClientSession target) {
        return phase == Phase.BATTLE
                ? callClanSharedBattle(target)
                : callClanSharedClassicWorld(target);
    }

    private boolean callClanSharedClassicWorld(ClientSession target) {
        GameHub.ClassicWorldLocation casterLocation = hub.classicWorldLocation(this);
        GameHub.ClassicWorldLocation targetLocation =
                target == null ? null : hub.classicWorldLocation(target);
        return target != null && phase == Phase.WORLD && target.phase == Phase.WORLD
                && !observer && !target.observer && playerHp > 0 && target.playerHp > 0
                && pendingPortal == null && target.pendingPortal == null
                && !hub.hasPrivateShop(this) && !hub.hasPrivateShop(target)
                && casterLocation != null && targetLocation != null
                && ClassicWorldMapCatalog.supports(casterLocation.mapId())
                && ClassicWorldMapCatalog.supports(targetLocation.mapId());
    }

    private void rejectCallClan(BattleSpellCatalog.CallClanSpell spell,
                                String reason, int messageId, String argument)
            throws IOException {
        if (messageId > 0) {
            byte[] message = argument == null
                    ? Protocol.messageCode(messageId)
                    : Protocol.messageCode(messageId, argument);
            sendEncrypted(message,
                    "S_MESSAGE_CODE Call Clan rejected=" + messageId
                            + " reason=" + reason
                            + (argument == null ? "" : " argument=" + argument));
        }
        System.out.println("[LiTo] C_USE_SPELL " + spell.key()
                + " rejected player=" + playerName() + " reason=" + reason);
    }

    private boolean callClanSharedBattle(ClientSession target) {
        if (target == null || currentRoomId == 0
                || phase != Phase.BATTLE || target.phase != Phase.BATTLE
                || observer || target.observer || playerHp <= 0 || target.playerHp <= 0
                || target.currentRoomId != currentRoomId
                || pendingPortal != null || target.pendingPortal != null
                || hub.hasPrivateShop(this) || hub.hasPrivateShop(target)
                || !hub.battleStarted(currentRoomId)) {
            return false;
        }
        List<ClientSession> combatants = hub.roomCombatants(currentRoomId);
        return combatants.contains(this) && combatants.contains(target)
                && hub.battleMapId(currentRoomId, this)
                        == hub.battleMapId(currentRoomId, target);
    }

    private boolean publishCallClanPrompt(ClientSession target,
                                          PendingCallClan invitation,
                                          long nowNanos) {
        synchronized (target) {
            PendingCallClan current = target.pendingCallClan;
            if (current != null && nowNanos - current.expiresAtNanos() < 0) {
                // Question 729 carries no generation or caller id.  Keep the
                // first unanswered prompt as the only acceptable capability.
                return false;
            }
        }
        hub.cancelPendingPlayerTradePrompt(target);
        synchronized (target) {
            PendingCallClan current = target.pendingCallClan;
            if (current != null && nowNanos - current.expiresAtNanos() < 0) {
                return false;
            }
            target.clearPendingAskCallbacks();
            target.pendingCallClan = invitation;
            return true;
        }
    }

    private void answerCallClan(Protocol.AskAnswer answer) throws IOException {
        PendingCallClan invitation = pendingCallClan;
        // One-shot capability: consume before id/text/answer/state validation.
        pendingCallClan = null;
        if (invitation == null || answer.questionId() != BattleCallClan.QUESTION_ID
                || !answer.text().isEmpty()) {
            System.out.println("[LiTo] C_ANSWER Call Clan rejected player="
                    + playerName() + " question=" + answer.questionId()
                    + " result=pending-unavailable-or-malformed");
            return;
        }
        if (answer.answer() == 0) {
            System.out.println("[LiTo] C_ANSWER Call Clan declined player="
                    + playerName() + " caster=" + invitation.caster().playerName());
            return;
        }

        long now = System.nanoTime();
        if (invitation.originPhase() == Phase.WORLD) {
            if (!ClassicWorldMapCatalog.supports(classicWorldMapId)
                    || !ClassicWorldMapCatalog.forMap(classicWorldMapId)
                            .allowsEscape()) {
                sendEncrypted(Protocol.messageCode(647),
                        "S_MESSAGE_CODE Call Clan source-not-escapable=647");
                return;
            }
            if (!callClanClassicWorldDestinationAllowed(invitation)) {
                sendEncrypted(Protocol.messageCode(629),
                        "S_MESSAGE_CODE Call Clan destination-too-far=629");
                return;
            }
        }
        if (timedStatus.actionLocked(now)
                || !callClanInvitationValid(invitation, now)) {
            System.out.println("[LiTo] C_ANSWER Call Clan rejected state player="
                    + playerName() + " caster="
                    + (invitation.caster() == null
                            ? "none" : invitation.caster().playerName()));
            return;
        }
        BattleCallClan.Destination destination =
                resolveCallClanDestination(invitation, now);
        if (destination == null) {
            sendEncrypted(Protocol.messageCode(627),
                    "S_MESSAGE_CODE Call Clan occupied-or-blocked=627");
            System.out.println("[LiTo] C_ANSWER Call Clan rejected destination player="
                    + playerName());
            return;
        }

        beginCallClanPortal(invitation, destination);
        System.out.println("[LiTo] C_ANSWER Call Clan accepted player=" + playerName()
                + " caster=" + invitation.caster().playerName()
                + " destination=" + destination.mapId() + ":"
                + destination.x() + "," + destination.y()
                + " heading=" + destination.heading());
    }

    private boolean callClanInvitationValid(PendingCallClan invitation,
                                             long nowNanos) {
        ClientSession caster = invitation == null ? null : invitation.caster();
        if (caster == null || nowNanos - invitation.expiresAtNanos() >= 0
                || observer || caster.observer || playerHp <= 0 || caster.playerHp <= 0
                || hub.hasPrivateShop(this) || hub.hasPrivateShop(caster)
                || caster.positionX != invitation.casterX()
                || caster.positionY != invitation.casterY()
                || !sameNonemptyClan(caster)) {
            return false;
        }
        if (pendingPortal != null && pendingCallClanPortal == null) return false;
        if (invitation.originPhase() == Phase.WORLD) {
            GameHub.ClassicWorldLocation inviteeLocation =
                    hub.classicWorldLocation(this);
            GameHub.ClassicWorldLocation casterLocation =
                    hub.classicWorldLocation(caster);
            return invitation.roomId() == 0
                    && phase == Phase.WORLD && caster.phase == Phase.WORLD
                    && inviteeLocation != null && casterLocation != null
                    && caster.classicWorldMapId == invitation.mapId()
                    && caster.classicWorldInstanceId == invitation.instanceId()
                    && casterLocation.mapId() == invitation.mapId();
        }
        return invitation.originPhase() == Phase.BATTLE
                && invitation.roomId() == currentRoomId
                && caster.currentRoomId == currentRoomId
                && phase == Phase.BATTLE && caster.phase == Phase.BATTLE
                && currentRoomId != 0 && hub.battleStarted(currentRoomId)
                && hub.roomCombatants(currentRoomId).contains(this)
                && hub.roomCombatants(currentRoomId).contains(caster)
                && hub.battleMapId(currentRoomId, this) == invitation.mapId()
                && hub.battleMapId(currentRoomId, caster) == invitation.mapId();
    }

    private boolean callClanClassicWorldDestinationAllowed(
            PendingCallClan invitation) {
        if (invitation == null || invitation.originPhase() != Phase.WORLD
                || invitation.instanceId() != -1
                || (invitation.mapId() != 0 && invitation.mapId() != 4
                    && invitation.mapId() != 304)) return false;
        if (invitation.mapId() != 4) return true;
        int castleId = callClanClassicWorldCastleId(
                invitation.casterX(), invitation.casterY());
        return castleId == 0 || hub.classicCastleWarActive(
                selectedClassicServerName, castleId);
    }

    private static int callClanClassicWorldCastleId(int x, int y) {
        if (inRectangle(x, y, 33089, 32717, 33219, 32827)) return 1;
        if (inRectangle(x, y, 32750, 32250, 32850, 32350)) return 2;
        if (inRectangle(x, y, 32571, 33350, 32721, 33460)) return 3;
        if (inRectangle(x, y, 33559, 32615, 33686, 32755)) return 4;
        if (inRectangle(x, y, 33458, 33315, 33583, 33490)) return 5;
        if (inRectangle(x, y, 34007, 33172, 34162, 33332)) return 7;
        return 0;
    }

    private static boolean inRectangle(int x, int y, int minX, int minY,
                                       int maxX, int maxY) {
        return x >= minX && x <= maxX && y >= minY && y <= maxY;
    }

    private BattleCallClan.Destination resolveCallClanDestination(
            PendingCallClan invitation, long nowNanos) {
        BattleCallClan.TileProbe passable;
        if (invitation.originPhase() == Phase.WORLD) {
            if (!ClassicWorldMapCatalog.supports(invitation.mapId())) return null;
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(invitation.mapId());
            passable = map::standingPassable;
        } else {
            ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(invitation.mapId());
            passable = arena::nativeStandingFloor;
        }
        return BattleCallClan.adjacentDestination(
                invitation.mapId(), invitation.casterX(), invitation.casterY(),
                invitation.casterHeading(), passable,
                (x, y) -> callClanDestinationOccupied(
                        invitation, x, y, nowNanos));
    }

    private boolean callClanDestinationOccupied(
            PendingCallClan invitation, int x, int y, long nowNanos) {
        if (invitation.originPhase() == Phase.WORLD) {
            int mapId = invitation.mapId();
            int instanceId = invitation.instanceId();
            for (ClientSession member : hub.classicWorldMembers(mapId, instanceId)) {
                if (member.playerHp > 0 && member.positionX == x
                        && member.positionY == y) return true;
                for (BattleCompanion.Snapshot companion
                        : member.controlledCompanionSnapshots()) {
                    if (companion.active() && companion.x() == x
                            && companion.y() == y) return true;
                }
            }
            if (hub.classicWorldMonsterOccupies(mapId, instanceId, x, y)) return true;
            return ClassicWorldNpcCatalog.all(mapId).stream()
                    .anyMatch(npc -> npc.x() == x && npc.y() == y);
        }
        int mapId = hub.battleMapId(currentRoomId, this);
        if (occupies(repairNpcPoint(), x, y)
                || occupies(spellShopNpcPoint(), x, y)
                || occupies(spellMaterialNpcPoint(), x, y)
                || occupies(classicMerchantNpcPoint(), x, y)
                || occupies(warehouseNpcPoint(), x, y)
                || occupies(castleStewardNpcPoint(), x, y)
                || occupies(houseAuctionBoardPoint(), x, y)
                || occupies(mercenaryCommanderNpcPoint(), x, y)) {
            return true;
        }
        List<ClientSession> combatants = hub.roomCombatants(currentRoomId);
        for (ClientSession combatant : combatants) {
            if (combatant.currentRoomId == currentRoomId
                    && hub.battleMapId(currentRoomId, combatant) == mapId
                    && combatant.positionX == x && combatant.positionY == y) {
                return true;
            }
            if (hub.battleMapId(currentRoomId, combatant) != mapId) continue;
            for (BattleCompanion.Snapshot companion
                    : combatant.controlledCompanionSnapshots()) {
                if (companion.active() && companion.x() == x && companion.y() == y) {
                    return true;
                }
            }
        }
        BattleRules.Mode mode = hub.roomRules(currentRoomId).mode();
        ArenaMapCatalog.Point bot = hub.botPosition(currentRoomId);
        if (mode != BattleRules.Mode.QUEST_BATTLE
                && mode != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(currentRoomId) < 2
                && bot != null && hub.botHp(currentRoomId) > 0
                && bot.x() == x && bot.y() == y) {
            return true;
        }
        if (hub.visibleGuardianTowers(currentRoomId, this).stream()
                .anyMatch(tower -> !tower.destroyed()
                        && tower.x() == x && tower.y() == y)) return true;
        if (hub.visibleQuestMonsters(currentRoomId, this).stream()
                .anyMatch(actor -> actor.alive() && actor.x() == x && actor.y() == y)) {
            return true;
        }
        if (hub.visibleTimeAttackActors(currentRoomId, this).stream()
                .anyMatch(actor -> actor.alive() && actor.x() == x && actor.y() == y)) {
            return true;
        }
        if (hub.battleDoorBlocks(currentRoomId, x, y)
                || hub.siegeGateBlocks(currentRoomId, x, y)) return true;
        if (hub.cookingFires(currentRoomId, nowNanos).stream()
                .anyMatch(fire -> fire.x() == x && fire.y() == y)) return true;
        return hub.shockStunEffects(currentRoomId, nowNanos).stream()
                .anyMatch(effect -> effect.x() == x && effect.y() == y);
    }

    private static boolean occupies(ArenaMapCatalog.Point point, int x, int y) {
        return point != null && point.x() == x && point.y() == y;
    }

    private void beginCallClanPortal(PendingCallClan invitation,
                                     BattleCallClan.Destination destination)
            throws IOException {
        if (pendingPortal != null) {
            throw new IllegalStateException("Call Clan portal already pending");
        }
        clearPendingAskCallbacks();
        pendingPortal = new Protocol.PortalDestination(
                destination.mapId(), destination.x(), destination.y(), true);
        pendingPortalReady = false;
        pendingRunClanPortal = null;
        pendingCallClanPortal = new PendingCallClanPortal(invitation, destination);
        pendingClassicWorldPortal = invitation.originPhase() == Phase.WORLD
                ? new PendingClassicWorldPortal(
                        pendingPortal, destination.heading(), 0,
                        "Call-Clan-116", invitation.instanceId())
                : null;
        sendEncrypted(Protocol.requestSummon(playerObjectId()),
                "S_REQUEST_SUMMON Call Clan player=" + playerName()
                        + " object=" + playerObjectId());
    }

    private boolean callClanPortalStillValid(PendingCallClanPortal portal,
                                               long nowNanos) {
        if (portal == null || portal != pendingCallClanPortal
                || !callClanInvitationValid(portal.invitation(), nowNanos)) {
            return false;
        }
        BattleCallClan.Destination current =
                resolveCallClanDestination(portal.invitation(), nowNanos);
        return portal.destination().equals(current);
    }

    private void useRunClanSpell(
            byte[] payload, BattleSpellCatalog.RunClanSpell spell)
            throws IOException {
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Run-Clan")) return;
        Protocol.RunClanSpellRequest request = Protocol.runClanSpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            rejectRunClan(spell, "selector-or-action", spell.failureMessage(), null);
            return;
        }

        ClientSession target = classicWorld
                ? hub.onlineMemberByName(this, request.targetName())
                : hub.activeMemberByName(this, request.targetName());
        if (target == null) {
            rejectRunClan(spell, "target-offline-or-ambiguous", 73,
                    request.targetName());
            return;
        }
        if (!sameNonemptyClan(target)) {
            rejectRunClan(spell, "target-not-same-nonempty-clan", 414, null);
            return;
        }
        if (!callClanSharedContext(target)) {
            rejectRunClan(spell, "target-outside-caster-world", 629, null);
            return;
        }
        if (classicWorld && !ClassicWorldMapCatalog.forMap(classicWorldMapId)
                .allowsEscape()) {
            rejectRunClan(spell, "source-not-escapable", 647, null);
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Run-Clan-source-not-escapable");
            return;
        }
        if (classicWorld && !runClanClassicWorldDestinationAllowed(target)) {
            rejectRunClan(spell, "destination-map-instance-or-war-area", 1192, null);
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Run-Clan-destination-rejected");
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int remainingMp;
        long now = System.nanoTime();
        long originRoomId = classicWorld ? 0 : currentRoomId;
        int sourceMapId = classicWorld
                ? classicWorldMapId : hub.battleMapId(currentRoomId, this);
        int sourceInstanceId = classicWorld ? classicWorldInstanceId : -1;
        int targetMapId = classicWorld
                ? target.classicWorldMapId : hub.battleMapId(currentRoomId, target);
        int targetInstanceId = classicWorld ? target.classicWorldInstanceId : -1;
        BattleRunClan.Destination destination = BattleRunClan.exactDestination(
                targetMapId, target.positionX, target.positionY);
        PendingRunClanPortal portal = new PendingRunClanPortal(
                target, originPhase, originRoomId, sourceMapId, sourceInstanceId,
                targetMapId, targetInstanceId, target.positionX, target.positionY,
                now + BattleRunClan.PORTAL_TIMEOUT_SECONDS * 1_000_000_000L,
                destination);
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean originStillValid = classicWorld
                    ? phase == Phase.WORLD && classicWorldMapId == sourceMapId
                        && classicWorldInstanceId == sourceInstanceId
                    : phase == Phase.BATTLE && currentRoomId == originRoomId
                        && currentRoomId != 0;
            if (now < readyAt || playerMp < mpCost || !originStillValid
                    || observer || playerHp <= 0
                    || pendingPortal != null || hub.hasPrivateShop(this)) {
                rejectRunClan(spell, "mp-cooldown-or-caster-state",
                        spell.failureMessage(), null);
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), now
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        boolean started = runClanPortalContextValid(portal, now);

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        List<ClientSession> actionRecipients = classicWorld
                ? classicWorldMembers(sourceMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : actionRecipients) {
            if (classicWorld && (member.classicWorldInstanceId != sourceInstanceId
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY))) continue;
            member.sendEncrypted(action,
                    "S_ACTION Run Clan caster=" + playerObjectId()
                            + " action=" + spell.actionId()
                            + " phase=" + originPhase);
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Run Clan=" + remainingMp + "/" + playerMaxMp);
        if (started) {
            beginRunClanPortal(portal);
        } else {
            sendEncrypted(Protocol.messageCode(629),
                    "S_MESSAGE_CODE Run Clan stale-target=629");
        }
        System.out.println("[LiTo] C_USE_SPELL Run Clan caster=" + playerName()
                + " target=" + target.playerName() + " selector="
                + request.row() + "/" + request.column()
                + " destination=" + destination.mapId() + ":"
                + destination.x() + "," + destination.y()
                + " heading=" + destination.heading()
                + " portal-started=" + started
                + " effective-original-reduction=" + originalReduction
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " source=" + sourceMapId + "/" + sourceInstanceId
                + " target-instance=" + targetInstanceId
                + " counter-magic-bypass=" + spell.counterMagicBypass());
    }

    private void rejectRunClan(BattleSpellCatalog.RunClanSpell spell,
                               String reason, int messageId, String argument)
            throws IOException {
        if (messageId > 0) {
            byte[] message = argument == null
                    ? Protocol.messageCode(messageId)
                    : Protocol.messageCode(messageId, argument);
            sendEncrypted(message,
                    "S_MESSAGE_CODE Run Clan rejected=" + messageId
                            + " reason=" + reason
                            + (argument == null ? "" : " argument=" + argument));
        }
        System.out.println("[LiTo] C_USE_SPELL " + spell.key()
                + " rejected player=" + playerName() + " reason=" + reason);
    }

    private void beginRunClanPortal(PendingRunClanPortal portal)
            throws IOException {
        if (pendingPortal != null || portal == null) {
            throw new IllegalStateException("Run Clan portal already pending");
        }
        clearPendingAskCallbacks();
        pendingPortal = new Protocol.PortalDestination(
                portal.destination().mapId(), portal.destination().x(),
                portal.destination().y(), true);
        pendingPortalReady = false;
        pendingCallClanPortal = null;
        pendingRunClanPortal = portal;
        pendingClassicWorldPortal = portal.originPhase() == Phase.WORLD
                ? new PendingClassicWorldPortal(
                        pendingPortal, portal.destination().heading(), 0,
                        "Run-Clan-118", portal.targetInstanceId())
                : null;
        sendEncrypted(Protocol.requestSummon(playerObjectId()),
                "S_REQUEST_SUMMON Run Clan player=" + playerName()
                        + " object=" + playerObjectId());
    }

    private boolean runClanPortalStillValid(PendingRunClanPortal portal,
                                             long nowNanos) {
        return portal != null && portal == pendingRunClanPortal
                && runClanPortalContextValid(portal, nowNanos);
    }

    private boolean runClanPortalContextValid(PendingRunClanPortal portal,
                                               long nowNanos) {
        ClientSession target = portal == null ? null : portal.target();
        if (portal == null || target == null
                || nowNanos - portal.expiresAtNanos() >= 0
                || observer || target.observer || playerHp <= 0 || target.playerHp <= 0
                || hub.hasPrivateShop(this) || hub.hasPrivateShop(target)
                || target.positionX != portal.targetX()
                || target.positionY != portal.targetY()
                || !sameNonemptyClan(target)
                || (target != this && target.pendingPortal != null)) {
            return false;
        }
        if (portal.originPhase() == Phase.WORLD) {
            if (portal.roomId() != 0 || phase != Phase.WORLD
                    || target.phase != Phase.WORLD
                    || classicWorldMapId != portal.sourceMapId()
                    || classicWorldInstanceId != portal.sourceInstanceId()
                    || target.classicWorldMapId != portal.targetMapId()
                    || target.classicWorldInstanceId != portal.targetInstanceId()
                    || !ClassicWorldMapCatalog.supports(portal.sourceMapId())
                    || !ClassicWorldMapCatalog.forMap(portal.sourceMapId()).allowsEscape()
                    || !runClanClassicWorldDestinationAllowed(target)) {
                return false;
            }
        } else if (portal.originPhase() == Phase.BATTLE) {
            if (portal.roomId() != currentRoomId
                    || target.currentRoomId != currentRoomId
                    || phase != Phase.BATTLE || target.phase != Phase.BATTLE
                    || currentRoomId == 0 || !hub.battleStarted(currentRoomId)
                    || !hub.roomCombatants(currentRoomId).contains(this)
                    || !hub.roomCombatants(currentRoomId).contains(target)
                    || hub.battleMapId(currentRoomId, this) != portal.sourceMapId()
                    || hub.battleMapId(currentRoomId, target) != portal.targetMapId()
                    || portal.sourceMapId() != portal.targetMapId()) {
                return false;
            }
        } else {
            return false;
        }
        BattleRunClan.Destination current = BattleRunClan.exactDestination(
                portal.targetMapId(), target.positionX, target.positionY);
        return portal.destination().equals(current);
    }

    private static boolean runClanClassicWorldDestinationAllowed(
            ClientSession target) {
        if (target == null || target.phase != Phase.WORLD
                || target.classicWorldInstanceId != -1
                || (target.classicWorldMapId != 0
                    && target.classicWorldMapId != 4
                    && target.classicWorldMapId != 304)) return false;
        if (target.classicWorldMapId != 4) return true;
        int castleId = callClanClassicWorldCastleId(
                target.positionX, target.positionY);
        return castleId == 0 || target.hub.classicCastleWarActive(
                target.selectedClassicServerName, castleId);
    }

    private void useInvisibilitySpell(byte[] payload,
                                      BattleSpellCatalog.InvisibilitySpell spell)
            throws IOException {
        Long clientTick = null;
        int requestSkillId;
        if (spell.requestShape() == BattleSpellCatalog.RequestShape.SELF_TICK) {
            Protocol.SelfSpellRequest request = Protocol.selfSpellRequest(payload);
            requestSkillId = request.skillId();
            clientTick = request.clientTick();
        } else {
            Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
            requestSkillId = request.skillId();
        }
        if (requestSkillId != spell.skillId()) {
            throw new IllegalArgumentException("invisibility selector/catalog mismatch");
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL invisibility rejected unavailable action player="
                    + playerName() + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        RuntimeInventory previousInventory = null;
        int remainingMp;
        boolean inventoryChanged = false;
        boolean previouslyInvisible;
        boolean toggleOff;
        long now = System.nanoTime();
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (now < readyAt || playerMp < mpCost
                    || (phase != Phase.BATTLE && phase != Phase.WORLD)
                    || playerHp <= 0) {
                System.out.println("[LiTo] C_USE_SPELL invisibility rejected state skill="
                        + spell.skillId() + " mp=" + playerMp + " invisible=" + invisible
                        + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - now));
                return;
            }
            if (spell.itemConsumeCount() > 0) {
                RuntimeInventory nextInventory = inventory.copy();
                if (!nextInventory.removeCatalog(
                        spell.itemConsumeId(), spell.itemConsumeCount())) {
                    System.out.println("[LiTo] C_USE_SPELL invisibility rejected missing reagent catalog="
                            + spell.itemConsumeId());
                    return;
                }
                previousInventory = inventory;
                inventory = nextInventory;
                inventoryChanged = true;
            }
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), now
                    + spell.reuseDelayMillis() * 1_000_000L);
            // Retained TYPE_NORMAL order first commits material, MP and the
            // action/reuse lease, then breaks Absolute Barrier/Meditation and
            // finally applies the invisibility toggle.  Keep every mutation
            // inside this admission lock so a rejected cast preserves all
            // three pre-existing status families.
            cancelMeditation("spell-" + spell.skillId());
            previouslyInvisible = invisible;
            toggleOff = previouslyInvisible
                    && invisibilityStatus.skillId() == spell.skillId();
            if (previouslyInvisible) cancelInvisibilityState();
            if (!toggleOff) {
                activateInvisibilityState(spell.skillId(), now, spell.durationSeconds());
            }
        }

        // The native hidden-actor contract removes the player as a direct
        // combat target. Drop every retained monster target at the same
        // admission boundary; the delivery-side gates above also reject any
        // skill work that was already queued on the scheduler thread.
        if (!toggleOff && phase == Phase.WORLD) {
            hub.clearClassicWorldMonsterTargets(playerObjectId());
        }

        if (inventoryChanged) {
            sendInventoryDelta(previousInventory, inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        }
        // Classic same-skill recast toggles off after committing cost/reuse.
        // Switching skill 60 <-> 97 also rebuilds the old actor before the
        // new cast action and remove-object transition.
        if (previouslyInvisible) {
            publishInvisibilityReveal("invisibility-recast-" + spell.skillId());
        }
        byte[] action = new Protocol.Writer().c(Protocol.S_ACTION)
                .d(playerObjectId()).c(spell.actionId()).bytes();
        byte[] removed = Protocol.removeObject(playerObjectId());
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (phase == Phase.WORLD && member != this
                    && !BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY,
                            member.positionX, member.positionY)) continue;
            member.sendEncrypted(action,
                    "S_ACTION invisibility-cast object=" + playerObjectId()
                            + " action=" + spell.actionId());
            if (!toggleOff && member == this) {
                member.sendEncrypted(Protocol.invisible(playerObjectId(), 1),
                        "S_INVISIBLE object=" + playerObjectId()
                                + " mode=1 skill=" + spell.skillId());
            } else if (!toggleOff) {
                member.sendEncrypted(removed,
                        "S_REMOVE_OBJECT invisible=" + playerObjectId());
            }
        }
        if (spell.effectGfx() > 0) {
            byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                if (phase == Phase.WORLD && member != this
                        && !BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY,
                                member.positionX, member.positionY)) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT invisibility skill=" + spell.skillId()
                                + " object=" + playerObjectId()
                                + " gfx=" + spell.effectGfx());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT invisibility=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL invisibility skill=" + spell.skillId()
                + " caster=" + playerName()
                + (clientTick == null ? " selector-only=true" : " client-tick="
                    + Long.toUnsignedString(clientTick))
                + " duration=" + spell.durationSeconds()
                + " toggle-off=" + toggleOff
                + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    private void useEnchantVenomSpell(
            byte[] payload, BattleSpellCatalog.EnchantVenomSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()) {
            throw new IllegalArgumentException(
                    "Enchant Venom selector/catalog mismatch");
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Enchant Venom rejected action player="
                    + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        RuntimeInventory previousInventory;
        int remainingHp;
        int remainingMp;
        Phase originPhase = phase;
        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long now = System.nanoTime();
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean validBattle = originPhase == Phase.BATTLE
                    && phase == Phase.BATTLE;
            boolean validWorld = originPhase == Phase.WORLD
                    && phase == Phase.WORLD
                    && classicWorldMapId == originMapId
                    && classicWorldInstanceId == originInstanceId
                    && positionX == originX && positionY == originY;
            if (now < readyAt || playerMp < mpCost || playerHp <= spell.hpCost()
                    || (!validBattle && !validWorld) || observer) {
                System.out.println("[LiTo] C_USE_SPELL Enchant Venom rejected state skill="
                        + spell.skillId() + " hp=" + playerHp
                        + " hp-cost=" + spell.hpCost() + " mp=" + playerMp
                        + " mp-cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - now));
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE Enchant-Venom-missing-reagent=299");
                System.out.println("[LiTo] C_USE_SPELL Enchant Venom rejected reagent="
                        + spell.itemConsumeId() + " count="
                        + spell.itemConsumeCount());
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            venomEnchantStatus.activate(now, spell.durationSeconds());
            previousInventory = inventory;
            inventory = nextInventory;
            playerHp -= spell.hpCost();
            playerMp -= mpCost;
            remainingHp = playerHp;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), now
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.phase != Phase.WORLD
                        || member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                member.positionX, member.positionY))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION Enchant-Venom caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT Enchant-Venom target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT Enchant-Venom-hp-cost=" + remainingHp
                        + "/" + playerMaxHp);
        broadcastOwnHitRatio("Enchant-Venom-hp-cost");
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Enchant-Venom=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Enchant Venom caster=" + playerName()
                + " duration=" + spell.durationSeconds()
                + " hp-cost=" + spell.hpCost() + " mp-cost=" + mpCost
                + " reagent=" + spell.itemConsumeId()
                + " proc=" + spell.procPercent() + "% tick-ms="
                + spell.tickIntervalMillis() + " tick-damage=" + spell.tickDamage()
                + " phase=" + originPhase
                + " selected-client-icon=unavailable hp=" + remainingHp
                + "/" + playerMaxHp + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    private void useBringStoneSpell(
            byte[] payload, BattleSpellCatalog.BringStoneSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != spell.skillId()) {
            throw new IllegalArgumentException("Bring Stone selector/catalog mismatch");
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Bring Stone rejected action player="
                    + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        long requestNow = System.nanoTime();
        if (phase != Phase.BATTLE && phase != Phase.WORLD) return;
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Bring-Stone-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Bring-Stone-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Bring-Stone-Silence-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Bring-Stone-Silence-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE Bring-Stone-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL rejected unlearned Bring Stone"
                    + " player=" + playerName() + " skill=" + spell.skillId());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int level = caster == null ? 0 : Math.max(0, caster.level());
        int wisdom = caster == null ? 0 : Math.max(0, caster.wisdom());
        RuntimeInventory previousInventory = null;
        long sourceCatalogId = 0;
        long targetCatalogId = 0;
        int threshold = 0;
        int oneBasedRoll = 0;
        int resultMessage = 0;
        String resultArgument = "";
        int remainingMp;
        Phase originPhase;
        long originRoomId;
        int originMapId;
        int originInstanceId;
        int originX;
        int originY;
        long now = System.nanoTime();
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (now < readyAt
                    || (phase != Phase.BATTLE && phase != Phase.WORLD)
                    || (phase == Phase.WORLD
                        && !ClassicWorldMapCatalog.supports(classicWorldMapId))
                    || observer || playerHp <= 0) {
                System.out.println("[LiTo] C_USE_SPELL Bring Stone rejected state skill="
                        + spell.skillId() + " mp=" + playerMp
                        + " cooldownNanos=" + Math.max(0L, readyAt - now));
                return;
            }
            if (playerMp < mpCost) {
                sendEncrypted(Protocol.messageCode(278),
                        "S_MESSAGE_CODE Bring-Stone-insufficient-mp=278");
                return;
            }

            RuntimeInventory.Item selected = inventory.item(request.targetObjectId());
            BattleSpellCatalog.StoneRefinement refinement = selected == null
                    ? null : BattleSpellCatalog.stoneRefinement(
                            selected.definition().catalogId());
            if (refinement != null) {
                sourceCatalogId = refinement.sourceCatalogId();
                targetCatalogId = refinement.targetCatalogId();
                threshold = spell.successThreshold(
                        refinement.tier(), level, wisdom);
                int configuredRoll = config.bringStoneFixtureRoll();
                oneBasedRoll = configuredRoll == 0
                        ? ThreadLocalRandom.current().nextInt(1, 101)
                        : configuredRoll;
                RuntimeInventory nextInventory = inventory.copy();
                if (!nextInventory.remove(request.targetObjectId(), 1)) {
                    throw new IllegalStateException(
                            "validated Bring Stone source removal failed");
                }
                if (spell.succeeds(threshold, oneBasedRoll)) {
                    if (nextInventory.add(
                            InventoryCatalog.require(refinement.targetCatalogId()), 1)) {
                        previousInventory = inventory;
                        inventory = nextInventory;
                        resultMessage = spell.successMessage();
                        resultArgument = refinement.targetNameId();
                    } else {
                        // The selected retained server compensates the removed
                        // source if the result cannot be delivered.
                        resultMessage = 79;
                    }
                } else {
                    previousInventory = inventory;
                    inventory = nextInventory;
                    resultMessage = spell.failureMessage();
                }
            }

            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), now
                    + spell.reuseDelayMillis() * 1_000_000L);
            originPhase = phase;
            originRoomId = currentRoomId;
            originMapId = classicWorldMapId;
            originInstanceId = classicWorldInstanceId;
            originX = positionX;
            originY = positionY;
        }

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                member.positionX, member.positionY))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION Bring-Stone caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
        }
        if (previousInventory != null) {
            sendInventoryDelta(previousInventory, inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        }
        if (resultMessage == spell.successMessage()) {
            sendEncrypted(Protocol.messageCode(resultMessage, resultArgument),
                    "S_MESSAGE_CODE Bring-Stone-success=" + resultMessage
                            + " target=" + resultArgument);
        } else if (resultMessage != 0) {
            sendEncrypted(Protocol.messageCode(resultMessage),
                    "S_MESSAGE_CODE Bring-Stone-result=" + resultMessage);
        }
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                member.positionX, member.positionY))) continue;
            member.sendEncrypted(effect,
                    "S_EFFECT Bring-Stone target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Bring-Stone=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Bring Stone caster=" + playerName()
                + " target-object=" + request.targetObjectId()
                + " source=" + sourceCatalogId + " target=" + targetCatalogId
                + " threshold=" + threshold + " roll=" + oneBasedRoll
                + " result-message=" + resultMessage + " mp-cost=" + mpCost
                + " phase=" + originPhase
                + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    private void useTurnUndeadSpell(byte[] payload,
                                    BattleSpellCatalog.TurnUndeadSpell spell)
            throws IOException {
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        List<ClientSession> combatants = hub.roomCombatants(currentRoomId);
        ClientSession target = combatants.stream()
                .filter(candidate -> candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        BattleGuardianTower.Snapshot targetTower =
                hub.guardianTower(currentRoomId, request.targetObjectId());
        BattleQuestEncounter.Snapshot targetMonster =
                hub.questMonster(currentRoomId, request.targetObjectId());
        BattleTimeAttackEncounter.Snapshot targetTimeBoss =
                hub.timeAttackActor(currentRoomId, request.targetObjectId());
        boolean botTarget = request.targetObjectId() == 2
                && hub.roomRules(currentRoomId).mode() != BattleRules.Mode.QUEST_BATTLE
                && hub.roomRules(currentRoomId).mode() != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(currentRoomId) < 2;
        ArenaMapCatalog.Point bot = botTarget ? hub.botPosition(currentRoomId) : null;
        if (botTarget && bot == null) {
            bot = ArenaMapCatalog.forMap(hub.battleMapId(currentRoomId, this)).botSpawn();
        }
        int targetX;
        int targetY;
        if (target != null) {
            targetX = target.positionX;
            targetY = target.positionY;
        } else if (targetTower != null) {
            targetX = targetTower.x();
            targetY = targetTower.y();
        } else if (targetMonster != null) {
            targetX = targetMonster.x();
            targetY = targetMonster.y();
        } else if (targetTimeBoss != null) {
            targetX = targetTimeBoss.x();
            targetY = targetTimeBoss.y();
        } else if (bot != null) {
            targetX = bot.x();
            targetY = bot.y();
        } else {
            System.out.println("[LiTo] C_USE_SPELL rejected unknown Turn Undead target="
                    + request.targetObjectId());
            return;
        }
        if (request.targetObjectId() == playerObjectId()
                || (target != null && (target.phase != Phase.BATTLE
                    || target.playerHp <= 0 || target.invisible))) {
            System.out.println("[LiTo] C_USE_SPELL rejected unavailable Turn Undead target="
                    + request.targetObjectId());
            return;
        }
        int range = Math.max(Math.abs(positionX - targetX), Math.abs(positionY - targetY));
        if (range > spell.maximumRange()) {
            System.out.println("[LiTo] C_USE_SPELL rejected Turn Undead range=" + range
                    + " max=" + spell.maximumRange());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL rejected unavailable Turn Undead action player="
                    + playerName() + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int npcId = targetMonster != null ? targetMonster.npcId()
                : targetTimeBoss != null ? targetTimeBoss.npcId() : 0;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected Turn Undead; source NPC lookup failed"
                        + " player=" + playerName() + " npc=" + npcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) {
                System.out.println("[LiTo] rejected blind; source NPC row missing"
                        + " player=" + playerName() + " npc=" + npcId);
                return;
            }
        }

        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < spell.mpCost()
                    || phase != Phase.BATTLE || playerHp <= 0) {
                System.out.println("[LiTo] C_USE_SPELL Turn Undead rejected target="
                        + request.targetObjectId() + " mp=" + playerMp
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= spell.mpCost();
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        breakSleepForStatusSpell(target, targetMonster, targetTimeBoss,
                "probability-spell-" + spell.skillId());

        List<ClientSession> recipients = targetMonster != null
                ? hub.battleRecipients(currentRoomId, targetMonster.force())
                : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION turn-undead caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        boolean earthBindBlocked = earthBindBlocksProbabilityMagic(
                target, targetMonster, targetTimeBoss, castNow, spell.skillId());
        boolean targetGate = !earthBindBlocked && (target != null
                ? hub.canAttack(currentRoomId, this, target)
                : targetMonster != null
                    ? hub.canAttackQuestMonster(
                            currentRoomId, this, targetMonster.objectId())
                            && BattleTurnUndead.eligible(npcStats)
                    : targetTimeBoss != null
                        && hub.canAttackTimeAttackActor(
                                currentRoomId, this, targetTimeBoss.objectId())
                        && BattleTurnUndead.eligible(npcStats));
        int baseTargetMr = target != null
                ? target.effectiveBaseMagicResistance(castNow)
                : npcStats == null ? 0 : npcStats.magicResistance();
        int targetMr = target != null ? baseTargetMr
                : targetMonster != null
                    ? hub.questMonsterEffectiveMagicResistance(
                            currentRoomId, targetMonster.objectId(),
                            baseTargetMr, castNow)
                    : targetTimeBoss != null
                        ? hub.timeAttackActorEffectiveMagicResistance(
                                currentRoomId, targetTimeBoss.objectId(),
                                baseTargetMr, castNow)
                        : baseTargetMr;
        int probability = 0;
        int percentileRoll = 0;
        int equipmentMagicHit = 0;
        int buffMagicHit = 0;
        int totalMagicHit = 0;
        boolean success = false;
        if (targetGate) {
            CharacterSummary caster = selectedCharacterSummary();
            SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
            int characterType = caster == null ? 0 : caster.type();
            int playerLevel = caster == null ? 1 : caster.level();
            int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
            equipmentMagicHit = equipment.totalMagicHit();
            buffMagicHit = dragonEyeStatus.snapshot(System.nanoTime()).magicHit();
            totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
            probability = BattleTurnUndead.probability(
                    characterType, playerLevel, effectiveIntelligence,
                    originalMagicHit(), totalMagicHit,
                    targetMr, spell.probabilityDice(), -1,
                    sides -> ThreadLocalRandom.current().nextInt(1, sides + 1));
            percentileRoll = ThreadLocalRandom.current().nextInt(1, 101);
            success = BattleTurnUndead.succeeds(probability, percentileRoll);
        }
        consumeEraseMagicAfterProbability(
                target, targetMonster, targetTimeBoss,
                castNow, spell.skillId());

        boolean countered = success && target != null
                && target.timedStatus.consumeCounterMagic(castNow);
        if (countered) {
            publishCounterMagicConsumption(target, spell.skillId());
            success = false;
        }
        if (success && targetMonster != null) {
            applyQuestMonsterDamage(targetMonster.objectId(), targetMonster.hp(), spell.key());
        } else if (success && targetTimeBoss != null) {
            applyTimeAttackActorDamage(targetTimeBoss.objectId(), targetTimeBoss.hp(), spell.key());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT turn-undead=" + remainingMp + "/" + playerMaxMp);
        if (success) {
            byte[] effect = Protocol.effectObject(request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(effect,
                        "S_EFFECT turn-undead target=" + request.targetObjectId()
                                + " gfx=" + spell.effectGfx());
            }
        } else {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE turn-undead-failure=" + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale Turn Undead coordinates"
                    + " client=" + request.x() + "," + request.y()
                    + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL Turn Undead caster=" + playerName()
                + " target=" + request.targetObjectId() + " npc=" + npcId
                + " undead=" + (npcStats == null ? -1 : npcStats.undead())
                + " isTU=" + (npcStats != null && npcStats.turnUndeadEligible())
                + " mr=" + targetMr + " probability=" + probability
                + " roll=" + percentileRoll + " success=" + success
                + " countered=" + countered + " mp=" + remainingMp + "/" + playerMaxMp
                + " earth-bind-blocked=" + earthBindBlocked
                + " equipment-magic-hit=" + equipmentMagicHit
                + " buff-magic-hit=" + buffMagicHit
                + " total-magic-hit=" + totalMagicHit);
    }

    /** Retained skill18 probability/death path for ordinary classic WORLD. */
    private void useClassicWorldTurnUndeadSpell(
            byte[] payload, BattleSpellCatalog.TurnUndeadSpell spell)
            throws IOException {
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-polymorph-turn-undead-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-polymorph-turn-undead-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-Silence-turn-undead-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-Silence-turn-undead-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE classic-world-turn-undead-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Turn Undead rejected"
                    + " learned/action player=" + playerName());
            return;
        }

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        ClientSession playerTarget = classicWorldMembers(originMapId).stream()
                .filter(candidate -> candidate != this
                        && sameClassicWorldMap(candidate)
                        && candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        ClassicWorldMonsterPopulation.Snapshot monsterTarget =
                hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId());
        if (playerTarget == null && (monsterTarget == null
                || !monsterTarget.present() || !monsterTarget.alive()
                || monsterTarget.mapId() != originMapId)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Turn Undead"
                    + " rejected unknown/dead target=" + request.targetObjectId());
            return;
        }

        int targetX = playerTarget != null ? playerTarget.positionX : monsterTarget.x();
        int targetY = playerTarget != null ? playerTarget.positionY : monsterTarget.y();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        boolean playerAvailable = playerTarget == null
                || playerTarget.phase == Phase.WORLD
                    && playerTarget.playerHp > 0
                    && !playerTarget.invisible
                    && sameClassicWorldMap(playerTarget);
        if (!playerAvailable
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY)
                || !map.attackPosition(positionX, positionY,
                        targetX, targetY, spell.maximumRange())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Turn Undead"
                    + " rejected gate/range target=" + request.targetObjectId());
            return;
        }
        if (playerTarget != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                        playerTarget.timedStatus.absoluteBarrierActive(requestNow),
                        spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Turn Undead"
                    + " rejected by Absolute Barrier target="
                    + playerTarget.playerName());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int npcId = monsterTarget == null ? 0 : monsterTarget.npcId();
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected classic-world Turn Undead; source"
                        + " NPC lookup failed player=" + playerName() + " npc="
                        + npcId + " reason=" + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) {
                System.out.println("[LiTo] rejected classic-world Turn Undead; source"
                        + " NPC row missing player=" + playerName() + " npc=" + npcId);
                return;
            }
        }

        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            ClassicWorldMonsterPopulation.Snapshot currentMonster = monsterTarget == null
                    ? null : hub.classicWorldMonster(
                            originMapId, originInstanceId, monsterTarget.objectId());
            boolean targetStillAvailable = playerTarget != null
                    ? playerTarget.phase == Phase.WORLD && playerTarget.playerHp > 0
                        && !playerTarget.invisible && sameClassicWorldMap(playerTarget)
                    : currentMonster != null && currentMonster.present()
                        && currentMonster.alive();
            if (castNow < readyAt || playerMp < spell.mpCost()
                    || phase != Phase.WORLD || playerHp <= 0 || observer
                    || classicWorldMapId != originMapId
                    || classicWorldInstanceId != originInstanceId
                    || !targetStillAvailable) {
                if (playerMp < spell.mpCost()) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE classic-world-turn-undead-insufficient-mp=278");
                }
                System.out.println("[LiTo] C_USE_SPELL classic-world Turn Undead"
                        + " rejected state target=" + request.targetObjectId()
                        + " mp=" + playerMp + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            if (currentMonster != null) {
                monsterTarget = currentMonster;
                targetX = currentMonster.x();
                targetY = currentMonster.y();
            }
            cancelMeditation("classic-world-spell-" + spell.skillId());
            playerMp -= spell.mpCost();
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        List<ClientSession> recipients = new ArrayList<>();
        for (ClientSession member : classicWorldMembers(originMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, positionX, positionY)
                        && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, targetX, targetY)) {
                continue;
            }
            recipients.add(member);
        }
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION classic-world turn-undead caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        int baseTargetMr = playerTarget != null
                ? playerTarget.effectiveBaseMagicResistance(castNow)
                : npcStats == null ? 0 : npcStats.magicResistance();
        int targetMr = playerTarget != null ? baseTargetMr
                : hub.classicWorldMonsterEffectiveMagicResistance(
                        originMapId, originInstanceId, monsterTarget.objectId(),
                        baseTargetMr, castNow);
        boolean sourceNpcGate = monsterTarget == null
                || BattleTurnUndead.eligible(npcStats);
        boolean npcSafetyBlocked = monsterTarget != null
                && (map.isSafetyZone(positionX, positionY)
                    || map.isSafetyZone(targetX, targetY));
        boolean targetGate = sourceNpcGate && !npcSafetyBlocked
                && (monsterTarget == null
                    || classicWorldCkewAttackAllowed(npcId, castNow));
        int probability = 0;
        int percentileRoll = 0;
        int equipmentMagicHit = 0;
        int buffMagicHit = 0;
        int totalMagicHit = 0;
        boolean success = false;
        if (targetGate) {
            CharacterSummary caster = selectedCharacterSummary();
            SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
            int casterType = caster == null ? 0 : caster.type();
            int casterLevel = caster == null ? 1 : caster.level();
            int effectiveIntelligence = equipment
                    .effectiveIntelligence(baseIntelligence());
            equipmentMagicHit = equipment.totalMagicHit();
            buffMagicHit = dragonEyeStatus.snapshot(castNow).magicHit();
            totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
            int configuredDieRoll = config.turnUndeadFixtureDieRoll();
            probability = BattleTurnUndead.probability(
                    casterType, casterLevel, effectiveIntelligence,
                    originalMagicHit(), totalMagicHit, targetMr,
                    spell.probabilityDice(), -1,
                    sides -> configuredDieRoll == 0
                            ? ThreadLocalRandom.current().nextInt(1, sides + 1)
                            : configuredDieRoll);
            int configuredPercentile = config.turnUndeadFixturePercentileRoll();
            percentileRoll = configuredPercentile == 0
                    ? ThreadLocalRandom.current().nextInt(1, 101)
                    : configuredPercentile;
            success = BattleTurnUndead.succeeds(probability, percentileRoll);
        }
        consumeEraseMagicAfterProbability(
                playerTarget, monsterTarget, null, null,
                castNow, spell.skillId());

        boolean countered = success && playerTarget != null
                && playerTarget.timedStatus.consumeCounterMagic(castNow);
        if (countered) {
            publishCounterMagicConsumption(playerTarget, spell.skillId());
            success = false;
        }
        if (success && monsterTarget != null) {
            ClassicWorldMonsterPopulation.Hit transition =
                    hub.damageClassicWorldMonster(
                            originMapId, originInstanceId, monsterTarget.objectId(),
                            playerObjectId(), monsterTarget.currentHp());
            if (transition == null) {
                success = false;
            } else {
                publishClassicWorldSpellMonsterDamage(spell.skillId(), transition);
            }
        }

        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world turn-undead="
                        + remainingMp + "/" + playerMaxMp);
        if (success) {
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(effect,
                        "S_EFFECT classic-world turn-undead target="
                                + request.targetObjectId() + " gfx="
                                + spell.effectGfx());
            }
        } else {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE classic-world turn-undead-failure="
                            + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale classic-world"
                    + " Turn Undead coordinates client=" + request.x() + ","
                    + request.y() + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world Turn Undead caster="
                + playerName() + " target=" + request.targetObjectId()
                + " npc=" + npcId + " undead="
                + (npcStats == null ? -1 : npcStats.undead()) + " isTU="
                + (npcStats != null && npcStats.turnUndeadEligible())
                + " target-gate=" + targetGate + " safety-blocked="
                + npcSafetyBlocked + " mr=" + targetMr + " probability="
                + probability + " roll=" + percentileRoll + " success="
                + success + " countered=" + countered + " mp=" + remainingMp
                + "/" + playerMaxMp + " equipment-magic-hit="
                + equipmentMagicHit + " buff-magic-hit=" + buffMagicHit
                + " total-magic-hit=" + totalMagicHit);
    }

    /** Retained skill39 MP-transfer path for ordinary classic WORLD. */
    private void useClassicWorldManaDrainSpell(
            byte[] payload, BattleSpellCatalog.ManaDrainSpell spell)
            throws IOException {
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-polymorph-mana-drain-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-polymorph-mana-drain-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-Silence-mana-drain-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-Silence-mana-drain-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE classic-world-mana-drain-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Mana Drain rejected"
                    + " learned/action player=" + playerName());
            return;
        }

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        ClientSession playerTarget = request.targetObjectId() == playerObjectId()
                ? this : classicWorldMembers(originMapId).stream()
                    .filter(candidate -> candidate != this
                            && sameClassicWorldMap(candidate)
                            && candidate.playerObjectId()
                                == request.targetObjectId())
                    .findFirst().orElse(null);
        ClassicWorldMonsterPopulation.Snapshot monsterTarget =
                hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId());
        if (playerTarget == null && (monsterTarget == null
                || !monsterTarget.present() || !monsterTarget.alive()
                || monsterTarget.mapId() != originMapId)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Mana Drain"
                    + " rejected unknown/dead target=" + request.targetObjectId());
            return;
        }

        int targetX = playerTarget != null ? playerTarget.positionX : monsterTarget.x();
        int targetY = playerTarget != null ? playerTarget.positionY : monsterTarget.y();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        boolean playerAvailable = playerTarget == null
                || playerTarget.phase == Phase.WORLD
                    && playerTarget.playerHp > 0
                    && !playerTarget.observer
                    && (playerTarget == this || !playerTarget.invisible)
                    && sameClassicWorldMap(playerTarget);
        boolean playerSafetyBlocked = playerTarget != null
                && playerTarget != this
                && (map.isSafetyZone(positionX, positionY)
                    || map.isSafetyZone(targetX, targetY));
        if (!playerAvailable || playerSafetyBlocked
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY)
                || !map.attackPosition(positionX, positionY,
                        targetX, targetY, spell.maximumRange())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Mana Drain"
                    + " rejected gate/range target=" + request.targetObjectId()
                    + " player-target=" + (playerTarget != null)
                    + " safety=" + playerSafetyBlocked);
            return;
        }
        if (playerTarget != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                        playerTarget.timedStatus.absoluteBarrierActive(requestNow),
                        spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Mana Drain"
                    + " rejected by Absolute Barrier target="
                    + playerTarget.playerName());
            return;
        }

        int npcId = monsterTarget == null ? 0 : monsterTarget.npcId();
        SourceNpcPhysicalStats npcStats = null;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected classic-world Mana Drain; source"
                        + " NPC lookup failed player=" + playerName() + " npc="
                        + npcId + " reason=" + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) {
                System.out.println("[LiTo] rejected classic-world Mana Drain; source"
                        + " NPC row missing player=" + playerName() + " npc=" + npcId);
                return;
            }
        }
        boolean npcEligible = playerTarget != null
                || BattleManaDrain.eligibleNpc(npcStats);
        boolean targetGate = monsterTarget == null
                || classicWorldCkewAttackAllowed(npcId, requestNow);

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        int baseTargetMr = playerTarget != null
                ? playerTarget.effectiveBaseMagicResistance(requestNow)
                : npcStats == null ? 0 : npcStats.magicResistance();
        int targetMr = playerTarget != null ? baseTargetMr
                : hub.classicWorldMonsterEffectiveMagicResistance(
                        originMapId, originInstanceId, monsterTarget.objectId(),
                        baseTargetMr, requestNow);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(requestNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int bossModifier = npcStats != null
                && (npcStats.boss() || monsterTarget.template().boss())
                ? spell.bossModifier() : -1;
        int probability = 0;
        int percentileRoll = 100;
        if (targetGate && npcEligible) {
            int configuredDieRoll = config.manaDrainFixtureDieRoll();
            probability = BattleManaDrain.probability(
                    casterType, casterLevel, effectiveIntelligence,
                    originalMagicHit(), totalMagicHit, targetMr,
                    spell.probabilityDice(), bossModifier,
                    sides -> configuredDieRoll == 0
                            ? ThreadLocalRandom.current().nextInt(1, sides + 1)
                            : configuredDieRoll);
            int configuredPercentile = config.manaDrainFixturePercentileRoll();
            percentileRoll = configuredPercentile == 0
                    ? ThreadLocalRandom.current().nextInt(1, 101)
                    : configuredPercentile;
        }

        int mpAfterCost;
        int remainingHp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            ClassicWorldMonsterPopulation.Snapshot currentMonster =
                    monsterTarget == null ? null : hub.classicWorldMonster(
                            originMapId, originInstanceId, monsterTarget.objectId());
            boolean targetStillAvailable = playerTarget != null
                    ? playerTarget.phase == Phase.WORLD
                        && playerTarget.playerHp > 0
                        && (playerTarget == this || !playerTarget.invisible)
                        && sameClassicWorldMap(playerTarget)
                    : currentMonster != null && currentMonster.present()
                        && currentMonster.alive();
            if (castNow < readyAt || playerMp < mpCost
                    || playerHp <= spell.hpCost() || observer
                    || phase != Phase.WORLD || classicWorldMapId != originMapId
                    || classicWorldInstanceId != originInstanceId
                    || !targetStillAvailable) {
                System.out.println("[LiTo] C_USE_SPELL classic-world Mana Drain"
                        + " rejected state target=" + request.targetObjectId()
                        + " hp=" + playerHp + " hp-cost=" + spell.hpCost()
                        + " mp=" + playerMp + " mp-cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            if (currentMonster != null) monsterTarget = currentMonster;
            cancelMeditation("classic-world-spell-" + spell.skillId());
            playerMp -= mpCost;
            playerHp -= spell.hpCost();
            mpAfterCost = playerMp;
            remainingHp = playerHp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());

        List<ClientSession> recipients = new ArrayList<>();
        for (ClientSession member : classicWorldMembers(originMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, positionX, positionY)
                        && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, targetX, targetY)) {
                continue;
            }
            recipients.add(member);
        }
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            member.sendEncrypted(action,
                    "S_ACTION classic-world mana-drain caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        boolean earthBindBlocked = playerTarget != null
                && playerTarget.timedStatus.earthBindActive(castNow);
        boolean success = targetGate && npcEligible && !earthBindBlocked
                && BattleManaDrain.succeeds(probability, percentileRoll);
        consumeEraseMagicAfterProbability(
                playerTarget, monsterTarget, null, null,
                castNow, spell.skillId());
        if (playerTarget != null) {
            playerTarget.cancelSleep(
                    "classic-world-probability-spell-" + spell.skillId());
        }
        boolean countered = success && playerTarget != null
                && playerTarget.timedStatus.consumeCounterMagic(castNow);
        if (countered) {
            publishCounterMagicConsumption(playerTarget, spell.skillId());
            success = false;
        }

        int requestedDrain = 0;
        int actualDrain = 0;
        int targetMpBefore = -1;
        int targetMpAfter = -1;
        int targetMaxMp = -1;
        if (success) {
            int configuredTransferRoll = config.manaDrainFixtureTransferRoll();
            requestedDrain = BattleManaDrain.requestedDrain(
                    effectiveIntelligence,
                    sides -> configuredTransferRoll == 0
                            ? ThreadLocalRandom.current().nextInt(1, sides + 1)
                            : configuredTransferRoll);
            if (playerTarget != null) {
                synchronized (playerTarget) {
                    targetMpBefore = playerTarget.playerMp;
                    actualDrain = Math.min(targetMpBefore, requestedDrain);
                    playerTarget.playerMp -= actualDrain;
                    targetMpAfter = playerTarget.playerMp;
                    targetMaxMp = playerTarget.playerMaxMp;
                }
            } else {
                ClassicWorldMonsterPopulation.ManaDrain result =
                        hub.drainClassicWorldMonsterMana(
                                originMapId, originInstanceId,
                                monsterTarget.objectId(), requestedDrain);
                if (result == null) {
                    success = false;
                } else {
                    actualDrain = result.actualDrain();
                    targetMpBefore = result.before().currentMp();
                    targetMpAfter = result.after().currentMp();
                    targetMaxMp = result.after().maximumMp();
                    if (actualDrain > 0) {
                        hub.provokeClassicWorldMonster(
                                originMapId, originInstanceId,
                                monsterTarget.objectId(), playerObjectId());
                    }
                }
            }
        }

        int finalCasterMp;
        synchronized (this) {
            if (success && actualDrain > 0) {
                playerMp = Math.min(playerMaxMp, playerMp + actualDrain);
            }
            finalCasterMp = playerMp;
        }
        if (success && playerTarget != null && actualDrain > 0) {
            playerTarget.revealInvisibility("accepted-mana-damage");
        }
        if (success && playerTarget != null && playerTarget != this) {
            playerTarget.sendEncrypted(Protocol.manaPoint(targetMpAfter, targetMaxMp),
                    "S_MANA_POINT classic-world mana-drain-target="
                            + targetMpAfter + "/" + targetMaxMp);
        }
        sendEncrypted(Protocol.manaPoint(finalCasterMp, playerMaxMp),
                "S_MANA_POINT classic-world mana-drain-caster="
                        + finalCasterMp + "/" + playerMaxMp);
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT classic-world mana-drain-hp-cost="
                        + remainingHp + "/" + playerMaxHp);
        broadcastOwnHitRatio("classic-world-mana-drain-hp-cost");

        if (success) {
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(effect,
                        "S_EFFECT classic-world mana-drain target="
                                + request.targetObjectId() + " gfx="
                                + spell.effectGfx());
            }
        } else {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE classic-world mana-drain-failure="
                            + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale classic-world"
                    + " mana-drain coordinates client=" + request.x() + ","
                    + request.y() + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world Mana Drain skill="
                + spell.skillId() + " caster=" + playerName() + " target="
                + request.targetObjectId() + " npc=" + npcId + " is-erase="
                + (npcStats != null && npcStats.eraseEligible())
                + " target-gate=" + targetGate + " npc-eligible=" + npcEligible
                + " probability=" + probability + " roll=" + percentileRoll
                + " success=" + success + " countered=" + countered
                + " earth-bind-blocked=" + earthBindBlocked
                + " boss-modifier=" + bossModifier + " mr=" + targetMr
                + " requested-drain=" + requestedDrain
                + " actual-drain=" + actualDrain + " target-mp="
                + targetMpBefore + "->" + targetMpAfter + "/" + targetMaxMp
                + " hp-cost=" + spell.hpCost() + " hp=" + remainingHp
                + "/" + playerMaxHp + " mp-cost=" + mpCost
                + " caster-mp=" + mpAfterCost + "->" + finalCasterMp
                + "/" + playerMaxMp + " total-magic-hit=" + totalMagicHit);
    }

    private void useManaDrainSpell(byte[] payload,
                                   BattleSpellCatalog.ManaDrainSpell spell)
            throws IOException {
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long originRoomId = currentRoomId;
        int originMapId = hub.battleMapId(originRoomId, this);
        int originX = positionX;
        int originY = positionY;
        List<ClientSession> combatants = hub.roomCombatants(originRoomId);
        ClientSession target = combatants.stream()
                .filter(candidate -> candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        BattleQuestEncounter.Snapshot questTarget =
                hub.questMonster(originRoomId, request.targetObjectId());
        BattleTimeAttackEncounter.Snapshot timeTarget =
                hub.timeAttackActor(originRoomId, request.targetObjectId());
        if (target == null && questTarget == null && timeTarget == null) {
            System.out.println("[LiTo] C_USE_SPELL mana-drain rejected unknown target="
                    + request.targetObjectId());
            return;
        }

        int targetX = target != null ? target.positionX
                : questTarget != null ? questTarget.x() : timeTarget.x();
        int targetY = target != null ? target.positionY
                : questTarget != null ? questTarget.y() : timeTarget.y();
        int range = Math.max(Math.abs(positionX - targetX), Math.abs(positionY - targetY));
        if (range > spell.maximumRange()) {
            System.out.println("[LiTo] C_USE_SPELL mana-drain rejected range=" + range
                    + " max=" + spell.maximumRange());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL mana-drain rejected unavailable action player="
                    + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        boolean targetGate = target != null
                ? target.phase == Phase.BATTLE && target.playerHp > 0
                    && (target == this || !target.invisible
                        && hub.canAttack(currentRoomId, this, target))
                : questTarget != null
                    ? hub.canAttackQuestMonster(
                            currentRoomId, this, questTarget.objectId())
                    : hub.canAttackTimeAttackActor(
                            currentRoomId, this, timeTarget.objectId());
        int npcId = questTarget != null ? questTarget.npcId()
                : timeTarget != null ? timeTarget.npcId() : 0;
        SourceNpcPhysicalStats npcStats = null;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected mana-drain; source NPC lookup failed"
                        + " player=" + playerName() + " npc=" + npcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
        }
        boolean npcEligible = target != null || BattleManaDrain.eligibleNpc(npcStats);

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        long gateNow = System.nanoTime();
        int baseTargetMr = npcStats == null ? 0 : npcStats.magicResistance();
        int targetMr = target != null
                ? target.effectiveBaseMagicResistance(gateNow)
                : effectiveNpcMagicResistance(
                        questTarget, timeTarget, baseTargetMr, gateNow);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(gateNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int bossModifier = npcStats != null
                && (npcStats.boss() || timeTarget != null && timeTarget.finalBoss())
                ? spell.bossModifier() : -1;
        int probability = 0;
        int percentileRoll = 100;
        if (targetGate && npcEligible) {
            int configuredDieRoll = config.manaDrainFixtureDieRoll();
            probability = BattleManaDrain.probability(
                    casterType, casterLevel, effectiveIntelligence,
                    originalMagicHit(), totalMagicHit, targetMr,
                    spell.probabilityDice(), bossModifier,
                    sides -> configuredDieRoll == 0
                            ? ThreadLocalRandom.current().nextInt(1, sides + 1)
                            : configuredDieRoll);
            int configuredPercentile = config.manaDrainFixturePercentileRoll();
            percentileRoll = configuredPercentile == 0
                    ? ThreadLocalRandom.current().nextInt(1, 101)
                    : configuredPercentile;
        }

        int mpAfterCost;
        int remainingHp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || playerHp <= spell.hpCost()
                    || phase != Phase.BATTLE || observer) {
                System.out.println("[LiTo] C_USE_SPELL mana-drain rejected state skill="
                        + spell.skillId() + " hp=" + playerHp
                        + " hp-cost=" + spell.hpCost() + " mp=" + playerMp
                        + " mp-cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            playerHp -= spell.hpCost();
            mpAfterCost = playerMp;
            remainingHp = playerHp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        breakSleepForStatusSpell(target, questTarget, timeTarget,
                "probability-spell-" + spell.skillId());
        List<ClientSession> recipients = questTarget != null
                ? hub.battleRecipients(currentRoomId, questTarget.force())
                : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION mana-drain caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        boolean earthBindBlocked = earthBindBlocksProbabilityMagic(
                target, questTarget, timeTarget, castNow, spell.skillId());
        boolean success = targetGate && npcEligible && !earthBindBlocked
                && BattleManaDrain.succeeds(probability, percentileRoll);
        consumeEraseMagicAfterProbability(
                target, questTarget, timeTarget, castNow, spell.skillId());
        boolean countered = success && target != null
                && target.timedStatus.consumeCounterMagic(castNow);
        if (countered) {
            publishCounterMagicConsumption(target, spell.skillId());
            success = false;
        }

        int requestedDrain = 0;
        int actualDrain = 0;
        int targetMpBefore = -1;
        int targetMpAfter = -1;
        int targetMaxMp = -1;
        if (success) {
            int configuredTransferRoll = config.manaDrainFixtureTransferRoll();
            requestedDrain = BattleManaDrain.requestedDrain(
                    effectiveIntelligence,
                    sides -> configuredTransferRoll == 0
                            ? ThreadLocalRandom.current().nextInt(1, sides + 1)
                            : configuredTransferRoll);
            if (target != null) {
                synchronized (target) {
                    targetMpBefore = target.playerMp;
                    actualDrain = Math.min(targetMpBefore, requestedDrain);
                    target.playerMp -= actualDrain;
                    targetMpAfter = target.playerMp;
                    targetMaxMp = target.playerMaxMp;
                }
            } else if (questTarget != null) {
                BattleQuestEncounter.ManaDrain result = hub.drainQuestMonsterMana(
                        currentRoomId, this, questTarget.objectId(),
                        npcStats.maxMp(), requestedDrain);
                if (result == null) {
                    success = false;
                } else {
                    actualDrain = result.drained();
                    targetMpBefore = result.beforeMp();
                    targetMpAfter = result.afterMp();
                    targetMaxMp = result.maximumMp();
                }
            } else {
                BattleTimeAttackEncounter.ManaDrain result = hub.drainTimeAttackActorMana(
                        currentRoomId, this, timeTarget.objectId(),
                        npcStats.maxMp(), requestedDrain);
                if (result == null) {
                    success = false;
                } else {
                    actualDrain = result.drained();
                    targetMpBefore = result.beforeMp();
                    targetMpAfter = result.afterMp();
                    targetMaxMp = result.maximumMp();
                }
            }
        }

        int finalCasterMp;
        synchronized (this) {
            if (success && actualDrain > 0) {
                playerMp = Math.min(playerMaxMp, playerMp + actualDrain);
            }
            finalCasterMp = playerMp;
        }
        if (success && target != null && actualDrain > 0) {
            target.revealInvisibility("accepted-mana-damage");
        }
        if (success && target != null && target != this) {
            target.sendEncrypted(Protocol.manaPoint(targetMpAfter, targetMaxMp),
                    "S_MANA_POINT mana-drain-target="
                            + targetMpAfter + "/" + targetMaxMp);
        }
        sendEncrypted(Protocol.manaPoint(finalCasterMp, playerMaxMp),
                "S_MANA_POINT mana-drain-caster="
                        + finalCasterMp + "/" + playerMaxMp);
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT mana-drain-hp-cost=" + remainingHp + "/" + playerMaxHp);
        broadcastOwnHitRatio("mana-drain-hp-cost");

        if (success) {
            byte[] effect = Protocol.effectObject(request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(effect,
                        "S_EFFECT mana-drain target=" + request.targetObjectId()
                                + " gfx=" + spell.effectGfx());
            }
        } else {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE mana-drain-failure=" + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale mana-drain coordinates"
                    + " client=" + request.x() + "," + request.y()
                    + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL mana-drain skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + request.targetObjectId()
                + " npc=" + npcId + " is-erase="
                + (npcStats != null && npcStats.eraseEligible())
                + " target-gate=" + targetGate + " npc-eligible=" + npcEligible
                + " probability=" + probability + " roll=" + percentileRoll
                + " success=" + success + " countered=" + countered
                + " earth-bind-blocked=" + earthBindBlocked
                + " boss-modifier=" + bossModifier + " mr=" + targetMr
                + " requested-drain=" + requestedDrain
                + " actual-drain=" + actualDrain + " target-mp="
                + targetMpBefore + "->" + targetMpAfter + "/" + targetMaxMp
                + " hp-cost=" + spell.hpCost() + " hp=" + remainingHp
                + "/" + playerMaxHp + " mp-cost=" + mpCost
                + " caster-mp=" + mpAfterCost + "->" + finalCasterMp
                + "/" + playerMaxMp + " total-magic-hit=" + totalMagicHit);
    }

    /** Retained skills 20/40/103 DARKNESS path for ordinary classic WORLD. */
    private void useClassicWorldBlindSpell(
            byte[] payload, BattleSpellCatalog.BlindSpell spell)
            throws IOException {
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;
        if (!admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Blind")) return;

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long requestNow = System.nanoTime();
        ClientSession playerTarget = classicWorldMembers(originMapId).stream()
                .filter(candidate -> candidate != this
                        && sameClassicWorldMap(candidate)
                        && candidate.playerObjectId()
                            == request.targetObjectId())
                .findFirst().orElse(null);
        ClassicWorldMonsterPopulation.Snapshot monsterTarget =
                hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId());
        if (playerTarget == null && (monsterTarget == null
                || !monsterTarget.present() || !monsterTarget.alive()
                || monsterTarget.mapId() != originMapId)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Blind"
                    + " rejected unknown/self/dead target="
                    + request.targetObjectId());
            return;
        }

        int targetX = playerTarget != null
                ? playerTarget.positionX : monsterTarget.x();
        int targetY = playerTarget != null
                ? playerTarget.positionY : monsterTarget.y();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        boolean playerAvailable = playerTarget == null
                || playerTarget.phase == Phase.WORLD
                    && playerTarget.playerHp > 0
                    && !playerTarget.observer
                    && !playerTarget.invisible
                    && sameClassicWorldMap(playerTarget);
        boolean playerSafetyBlocked = playerTarget != null
                && (map.isSafetyZone(originX, originY)
                    || map.isSafetyZone(targetX, targetY));
        boolean absoluteBarrierBlocked = playerTarget != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                        playerTarget.timedStatus.absoluteBarrierActive(requestNow),
                        spell.skillId());
        if (!playerAvailable || playerSafetyBlocked || absoluteBarrierBlocked
                || !BattleSpellCatalog.isInNativeScreen(
                        originX, originY, targetX, targetY)
                || !map.attackPosition(originX, originY,
                        targetX, targetY, spell.maximumRange())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Blind"
                    + " rejected gate/range target=" + request.targetObjectId()
                    + " player-target=" + (playerTarget != null)
                    + " safety=" + playerSafetyBlocked
                    + " absolute-barrier=" + absoluteBarrierBlocked
                    + " max-range=" + spell.maximumRange());
            return;
        }

        int npcId = monsterTarget == null ? 0 : monsterTarget.npcId();
        SourceNpcPhysicalStats npcStats = null;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected classic-world Blind; source"
                        + " NPC lookup failed player=" + playerName() + " npc="
                        + npcId + " reason=" + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) {
                System.out.println("[LiTo] rejected classic-world Blind; source"
                        + " NPC row missing player=" + playerName() + " npc="
                        + npcId);
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment =
                requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);
        CharacterSummary targetCharacter = playerTarget == null
                ? null : playerTarget.selectedCharacterSummary();
        int targetLevel = playerTarget != null
                ? targetCharacter == null ? 1
                    : Math.max(1, targetCharacter.level())
                : Math.max(1, monsterTarget.template().level());
        int baseTargetMr = playerTarget != null
                ? playerTarget.effectiveBaseMagicResistance(requestNow)
                : npcStats.magicResistance();
        int targetMr = playerTarget != null ? baseTargetMr
                : hub.classicWorldMonsterEffectiveMagicResistance(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), baseTargetMr, requestNow);
        int targetBlindResistance = playerTarget == null ? 0
                : playerTarget.requiredEquipmentMagicStats()
                    .totalBlindResistance();
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(requestNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int magicLevel = spell.includeMagicLevel()
                ? BattleTurnUndead.magicLevel(casterType, casterLevel) : 0;
        boolean bossTarget = monsterTarget != null
                && (monsterTarget.template().boss() || npcStats.boss());
        boolean bossImmune = bossTarget && spell.bossModifier() == 0;
        boolean targetGate = monsterTarget == null
                || classicWorldCkewAttackAllowed(npcId, requestNow);
        int probability = targetGate ? spell.probabilityForTarget(
                casterLevel, targetLevel, effectiveIntelligence, magicLevel,
                totalMagicHit, targetMr, targetBlindResistance, bossTarget) : 0;
        int configuredBlindRoll = (spell.skillId() == BattleSpellCatalog.DARK_BLIND
                || spell.skillId() == BattleSpellCatalog.DARKNESS)
                ? config.darkBlindFixtureRoll() : 0;
        int percentileRoll = bossImmune || !targetGate ? 100
                : configuredBlindRoll > 0 ? configuredBlindRoll
                : ThreadLocalRandom.current().nextInt(1, 101);

        RuntimeInventory previousInventory = null;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            ClassicWorldMonsterPopulation.Snapshot lockedMonster =
                    monsterTarget == null ? null : hub.classicWorldMonster(
                            originMapId, originInstanceId,
                            monsterTarget.objectId());
            boolean targetStillAvailable = playerTarget != null
                    ? playerTarget.phase == Phase.WORLD
                        && playerTarget.playerHp > 0
                        && !playerTarget.observer
                        && !playerTarget.invisible
                        && sameClassicWorldMap(playerTarget)
                    : lockedMonster != null && lockedMonster.present()
                        && lockedMonster.alive();
            if (castNow < readyAt || playerMp < mpCost || playerHp <= 0
                    || observer || phase != Phase.WORLD
                    || classicWorldMapId != originMapId
                    || classicWorldInstanceId != originInstanceId
                    || !targetStillAvailable) {
                System.out.println("[LiTo] C_USE_SPELL classic-world Blind"
                        + " rejected state target=" + request.targetObjectId()
                        + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            if (spell.itemConsumeId() != 0) {
                RuntimeInventory nextInventory = inventory.copy();
                if (!nextInventory.removeCatalog(
                        spell.itemConsumeId(), spell.itemConsumeCount())) {
                    sendEncrypted(Protocol.messageCode(299),
                            "S_MESSAGE_CODE classic-world-Blind-missing-reagent=299");
                    System.out.println("[LiTo] C_USE_SPELL classic-world Blind"
                            + " rejected missing reagent catalog="
                            + spell.itemConsumeId() + " count="
                            + spell.itemConsumeCount());
                    return;
                }
                previousInventory = inventory;
                inventory = nextInventory;
            }
            if (lockedMonster != null) monsterTarget = lockedMonster;
            cancelMeditation("classic-world-spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());

        if (previousInventory != null) {
            sendInventoryDelta(previousInventory, inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        }
        List<ClientSession> recipients = classicWorldMembers(originMapId).stream()
                .filter(member -> member.phase == Phase.WORLD
                        && member.classicWorldMapId == originMapId
                        && member.classicWorldInstanceId == originInstanceId
                        && (BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                positionX, positionY)
                            || BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                targetX, targetY)))
                .toList();
        byte[] action = Protocol.objectAction(
                playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION classic-world Blind caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        boolean earthBindBlocked = playerTarget != null
                && playerTarget.timedStatus.earthBindActive(castNow);
        boolean probabilitySuccess = targetGate && !bossImmune
                && !earthBindBlocked && probability >= percentileRoll;
        consumeEraseMagicAfterProbability(
                playerTarget, monsterTarget, null, null,
                castNow, spell.skillId());
        if (playerTarget != null) {
            playerTarget.cancelSleep(
                    "classic-world-probability-spell-" + spell.skillId());
        }

        boolean countered = probabilitySuccess && playerTarget != null
                && playerTarget.timedStatus.consumeCounterMagic(castNow);
        boolean applied = false;
        if (countered) {
            publishCounterMagicConsumption(playerTarget, spell.skillId());
        } else if (probabilitySuccess && playerTarget != null) {
            playerTarget.timedStatus.activateBlind(
                    castNow, spell.durationSeconds());
            playerTarget.sendEncrypted(Protocol.blind(1),
                    "S_BLIND classic-world " + spell.key()
                            + " mode=1 duration=" + spell.durationSeconds());
            applied = true;
        } else if (probabilitySuccess) {
            applied = hub.blindClassicWorldMonster(
                    originMapId, originInstanceId, monsterTarget.objectId(),
                    castNow, spell.durationSeconds());
        }

        if (applied) {
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY,
                        targetX, targetY)) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT classic-world Blind target="
                                + request.targetObjectId() + " gfx="
                                + spell.effectGfx());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world Blind=" + remainingMp
                        + "/" + playerMaxMp);
        if (!applied) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE classic-world-Blind-failure="
                            + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale classic-world"
                    + " Blind coordinates client=" + request.x() + ","
                    + request.y() + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world Blind skill="
                + spell.skillId() + " caster=" + playerName() + " target="
                + request.targetObjectId() + " npc=" + npcId
                + " player-target=" + (playerTarget != null)
                + " target-gate=" + targetGate + " probability=" + probability
                + " roll=" + percentileRoll + " probability-success="
                + probabilitySuccess + " applied=" + applied
                + " countered=" + countered + " mr=" + targetMr
                + " boss-target=" + bossTarget + " boss-immune=" + bossImmune
                + " earth-bind-blocked=" + earthBindBlocked
                + " blind-resistance=" + targetBlindResistance
                + " equipment-magic-hit=" + equipmentMagicHit
                + " buff-magic-hit=" + buffMagicHit
                + " total-magic-hit=" + totalMagicHit
                + " duration=" + spell.durationSeconds()
                + " mp-cost=" + mpCost + " mp=" + remainingMp
                + "/" + playerMaxMp);
    }

    private void useBlindSpell(byte[] payload,
                               BattleSpellCatalog.BlindSpell spell) throws IOException {
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        List<ClientSession> combatants = hub.roomCombatants(currentRoomId);
        ClientSession target = combatants.stream()
                .filter(candidate -> candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        BattleQuestEncounter.Snapshot questTarget =
                hub.questMonster(currentRoomId, request.targetObjectId());
        BattleTimeAttackEncounter.Snapshot timeTarget =
                hub.timeAttackActor(currentRoomId, request.targetObjectId());
        if (target == this || (target == null && questTarget == null && timeTarget == null)) {
            System.out.println("[LiTo] C_USE_SPELL blind rejected target="
                    + request.targetObjectId());
            return;
        }

        int targetX = target != null ? target.positionX
                : questTarget != null ? questTarget.x() : timeTarget.x();
        int targetY = target != null ? target.positionY
                : questTarget != null ? questTarget.y() : timeTarget.y();
        boolean targetGate = target != null
                ? target.phase == Phase.BATTLE && target.playerHp > 0
                    && !target.invisible && hub.canAttack(currentRoomId, this, target)
                : questTarget != null
                    ? hub.canAttackQuestMonster(
                            currentRoomId, this, questTarget.objectId())
                    : hub.canAttackTimeAttackActor(
                            currentRoomId, this, timeTarget.objectId());
        int range = Math.max(Math.abs(positionX - targetX), Math.abs(positionY - targetY));
        if (!targetGate || range > spell.maximumRange()) {
            System.out.println("[LiTo] C_USE_SPELL blind rejected gate/range target="
                    + request.targetObjectId() + " range=" + range
                    + " max=" + spell.maximumRange());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL blind rejected unavailable action player="
                    + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int npcId = questTarget != null ? questTarget.npcId()
                : timeTarget != null ? timeTarget.npcId() : 0;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected blind; source NPC lookup failed"
                        + " player=" + playerName() + " npc=" + npcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : caster.level();
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        CharacterSummary targetCharacter = target == null
                ? null : target.selectedCharacterSummary();
        int targetLevel = target != null
                ? targetCharacter == null ? 1 : Math.max(1, targetCharacter.level())
                : questTarget != null ? questTarget.level() : timeTarget.level();
        long targetMrNow = System.nanoTime();
        int targetMr = target != null
                ? target.effectiveBaseMagicResistance(targetMrNow)
                : effectiveNpcMagicResistance(
                        questTarget, timeTarget,
                        npcStats == null ? 0 : npcStats.magicResistance(),
                        targetMrNow);
        int targetBlindResistance = target == null ? 0
                : target.requiredEquipmentMagicStats().totalBlindResistance();
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(System.nanoTime()).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int magicLevel = spell.includeMagicLevel()
                ? BattleTurnUndead.magicLevel(casterType, casterLevel) : 0;
        boolean bossTarget = npcStats != null && npcStats.boss()
                || timeTarget != null && timeTarget.finalBoss();
        boolean bossImmune = bossTarget && spell.bossModifier() == 0;
        int probability = spell.probabilityForTarget(
                casterLevel, targetLevel, effectiveIntelligence, magicLevel,
                totalMagicHit, targetMr, targetBlindResistance, bossTarget);
        int configuredBlindRoll = (spell.skillId() == BattleSpellCatalog.DARK_BLIND
                || spell.skillId() == BattleSpellCatalog.DARKNESS)
                ? config.darkBlindFixtureRoll() : 0;
        int percentileRoll = bossImmune ? 100
                : configuredBlindRoll > 0 ? configuredBlindRoll
                : ThreadLocalRandom.current().nextInt(1, 101);

        RuntimeInventory previousInventory = null;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost
                    || phase != Phase.BATTLE || playerHp <= 0) {
                System.out.println("[LiTo] C_USE_SPELL blind rejected state target="
                        + request.targetObjectId() + " mp=" + playerMp
                        + " cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            if (spell.itemConsumeId() != 0) {
                RuntimeInventory nextInventory = inventory.copy();
                if (!nextInventory.removeCatalog(
                        spell.itemConsumeId(), spell.itemConsumeCount())) {
                    sendEncrypted(Protocol.messageCode(299),
                            "S_MESSAGE_CODE blind-missing-reagent=299");
                    System.out.println("[LiTo] C_USE_SPELL blind rejected missing reagent"
                            + " catalog=" + spell.itemConsumeId()
                            + " count=" + spell.itemConsumeCount());
                    return;
                }
                previousInventory = inventory;
                inventory = nextInventory;
            }
            playerMp -= mpCost;
            remainingMp = playerMp;
            spellReadyNanos.put(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelMeditation("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        if (previousInventory != null) {
            sendInventoryDelta(previousInventory, inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        }
        boolean earthBindBlocked = earthBindBlocksProbabilityMagic(
                target, questTarget, timeTarget, castNow, spell.skillId());
        boolean probabilitySuccess = !bossImmune && !earthBindBlocked
                && probability >= percentileRoll;
        consumeEraseMagicAfterProbability(
                target, questTarget, timeTarget, castNow, spell.skillId());

        breakSleepForStatusSpell(target, questTarget, timeTarget,
                "probability-spell-" + spell.skillId());

        List<ClientSession> recipients = questTarget != null
                ? hub.battleRecipients(currentRoomId, questTarget.force())
                : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION blind caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        boolean countered = probabilitySuccess && target != null
                && target.timedStatus.consumeCounterMagic(castNow);
        boolean applied = false;
        if (countered) {
            publishCounterMagicConsumption(target, spell.skillId());
        } else if (probabilitySuccess && target != null) {
            target.timedStatus.activateBlind(castNow, spell.durationSeconds());
            target.sendEncrypted(Protocol.blind(1),
                    "S_BLIND " + spell.key() + " mode=1 duration="
                            + spell.durationSeconds());
            applied = true;
        } else if (probabilitySuccess && questTarget != null) {
            applied = hub.blindQuestMonster(currentRoomId, this,
                    questTarget.objectId(), castNow, spell.durationSeconds());
        } else if (probabilitySuccess && timeTarget != null) {
            applied = hub.blindTimeAttackActor(currentRoomId, this,
                    timeTarget.objectId(), castNow, spell.durationSeconds());
        }

        if (applied) {
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(effect,
                        "S_EFFECT blind target=" + request.targetObjectId()
                                + " gfx=" + spell.effectGfx());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT blind=" + remainingMp + "/" + playerMaxMp);
        if (!applied) {
            // TYPE_CURSE removes both probability failures and Counter Magic
            // targets from the retained target list; sendFailMessageHandle then
            // emits the configured failure message after graphics/status output.
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE blind-failure=" + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale blind coordinates"
                    + " client=" + request.x() + "," + request.y()
                    + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL blind skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + request.targetObjectId()
                + " npc=" + npcId + " probability=" + probability
                + " roll=" + percentileRoll + " probability-success="
                + probabilitySuccess + " applied=" + applied
                + " countered=" + countered + " mr=" + targetMr
                + " boss-target=" + bossTarget + " boss-immune=" + bossImmune
                + " earth-bind-blocked=" + earthBindBlocked
                + " blind-resistance=" + targetBlindResistance
                + " equipment-magic-hit=" + equipmentMagicHit
                + " buff-magic-hit=" + buffMagicHit
                + " total-magic-hit=" + totalMagicHit
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    private void useClassicWorldSilenceSpell(
            byte[] payload, BattleSpellCatalog.SilenceSpell spell)
            throws IOException {
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;
        if (!admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Silence")) return;

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long requestNow = System.nanoTime();
        ClientSession playerTarget = classicWorldMembers(originMapId).stream()
                .filter(candidate -> candidate != this
                        && sameClassicWorldMap(candidate)
                        && candidate.playerObjectId()
                            == request.targetObjectId())
                .findFirst().orElse(null);
        ClassicWorldMonsterPopulation.Snapshot monsterTarget =
                hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId());
        if (playerTarget == null && (monsterTarget == null
                || !monsterTarget.present() || !monsterTarget.alive()
                || monsterTarget.mapId() != originMapId)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Silence"
                    + " rejected unknown/self/dead target="
                    + request.targetObjectId());
            return;
        }

        int targetX = playerTarget != null
                ? playerTarget.positionX : monsterTarget.x();
        int targetY = playerTarget != null
                ? playerTarget.positionY : monsterTarget.y();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        boolean playerAvailable = playerTarget == null
                || playerTarget.phase == Phase.WORLD
                    && playerTarget.playerHp > 0
                    && !playerTarget.observer
                    && !playerTarget.invisible
                    && sameClassicWorldMap(playerTarget);
        boolean playerSafetyBlocked = playerTarget != null
                && (map.isSafetyZone(originX, originY)
                    || map.isSafetyZone(targetX, targetY));
        boolean absoluteBarrierBlocked = playerTarget != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                        playerTarget.timedStatus.absoluteBarrierActive(requestNow),
                        spell.skillId());
        if (!playerAvailable || playerSafetyBlocked || absoluteBarrierBlocked
                || !BattleSpellCatalog.isInNativeScreen(
                        originX, originY, targetX, targetY)
                || !map.attackPosition(originX, originY,
                        targetX, targetY, spell.maximumRange())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Silence"
                    + " rejected gate/range target=" + request.targetObjectId()
                    + " player-target=" + (playerTarget != null)
                    + " safety=" + playerSafetyBlocked
                    + " absolute-barrier=" + absoluteBarrierBlocked
                    + " max-range=" + spell.maximumRange());
            return;
        }

        int npcId = monsterTarget == null ? 0 : monsterTarget.npcId();
        SourceNpcPhysicalStats npcStats = null;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected classic-world Silence;"
                        + " source NPC lookup failed player=" + playerName()
                        + " npc=" + npcId + " reason="
                        + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) {
                System.out.println("[LiTo] rejected classic-world Silence;"
                        + " source NPC row missing player=" + playerName()
                        + " npc=" + npcId);
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment =
                requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);
        CharacterSummary targetCharacter = playerTarget == null
                ? null : playerTarget.selectedCharacterSummary();
        int targetLevel = playerTarget != null
                ? targetCharacter == null ? 1
                    : Math.max(1, targetCharacter.level())
                : Math.max(1, monsterTarget.template().level());
        int baseTargetMr = playerTarget != null
                ? playerTarget.effectiveBaseMagicResistance(requestNow)
                : npcStats.magicResistance();
        int targetMr = playerTarget != null ? baseTargetMr
                : hub.classicWorldMonsterEffectiveMagicResistance(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), baseTargetMr, requestNow);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(requestNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int magicLevel = spell.includeMagicLevel()
                ? BattleTurnUndead.magicLevel(casterType, casterLevel) : 0;
        boolean bossTarget = monsterTarget != null
                && (monsterTarget.template().boss() || npcStats.boss());
        boolean bossImmune = bossTarget && spell.bossModifier() == 0;
        boolean targetGate = monsterTarget == null
                || classicWorldCkewAttackAllowed(npcId, requestNow);
        int probability = targetGate ? spell.probabilityForTarget(
                casterLevel, targetLevel, effectiveIntelligence, magicLevel,
                totalMagicHit, targetMr, bossTarget) : 0;
        int configuredRoll = config.silenceFixturePercentileRoll();
        int percentileRoll = !targetGate || bossImmune ? 100
                : configuredRoll == 0
                    ? ThreadLocalRandom.current().nextInt(1, 101)
                    : configuredRoll;

        RuntimeInventory previousInventory;
        int remainingMp;
        long castNow;
        ClientSession firstLock = playerTarget == null
                || playerObjectId() <= playerTarget.playerObjectId()
                ? this : playerTarget;
        ClientSession secondLock = playerTarget == null
                ? this : firstLock == this ? playerTarget : this;
        synchronized (firstLock) {
            synchronized (secondLock) {
                castNow = System.nanoTime();
                long readyAt = spellReadyNanos.getOrDefault(
                        spell.skillId(), 0L);
                ClassicWorldMonsterPopulation.Snapshot lockedMonster =
                        monsterTarget == null ? null : hub.classicWorldMonster(
                                originMapId, originInstanceId,
                                monsterTarget.objectId());
                boolean targetStillAvailable = playerTarget != null
                        ? playerTarget.phase == Phase.WORLD
                            && playerTarget.playerHp > 0
                            && !playerTarget.observer
                            && !playerTarget.invisible
                            && playerTarget.classicWorldMapId == originMapId
                            && playerTarget.classicWorldInstanceId
                                == originInstanceId
                            && playerTarget.positionX == targetX
                            && playerTarget.positionY == targetY
                            && !BattleAbsoluteBarrierRules
                                .blocksIncomingSpell(
                                    playerTarget.timedStatus
                                        .absoluteBarrierActive(castNow),
                                    spell.skillId())
                        : lockedMonster != null && lockedMonster.present()
                            && lockedMonster.alive()
                            && lockedMonster.mapId() == originMapId
                            && lockedMonster.x() == targetX
                            && lockedMonster.y() == targetY;
                boolean endpointStillAllowed = positionX == originX
                        && positionY == originY
                        && !map.isSafetyZone(originX, originY)
                        && !map.isSafetyZone(targetX, targetY)
                        && BattleSpellCatalog.isInNativeScreen(
                            originX, originY, targetX, targetY)
                        && map.attackPosition(originX, originY,
                            targetX, targetY, spell.maximumRange());
                boolean targetGateStillAllowed = playerTarget != null
                        || classicWorldCkewAttackAllowed(npcId, castNow);
                if (castNow < readyAt || playerMp < mpCost || playerHp <= 0
                        || observer || phase != Phase.WORLD
                        || classicWorldMapId != originMapId
                        || classicWorldInstanceId != originInstanceId
                        || !targetStillAvailable || !endpointStillAllowed
                        || !targetGateStillAllowed) {
                    System.out.println("[LiTo] C_USE_SPELL classic-world Silence"
                            + " rejected state target="
                            + request.targetObjectId() + " mp=" + playerMp
                            + " cost=" + mpCost + " target-available="
                            + targetStillAvailable + " endpoint="
                            + endpointStillAllowed + " target-gate="
                            + targetGateStillAllowed + " cooldownNanos="
                            + Math.max(0L, readyAt - castNow));
                    return;
                }
                RuntimeInventory nextInventory = inventory.copy();
                if (!nextInventory.removeCatalog(
                        spell.itemConsumeId(), spell.itemConsumeCount())) {
                    sendEncrypted(Protocol.messageCode(299),
                            "S_MESSAGE_CODE classic-world-Silence-missing-reagent=299");
                    return;
                }
                previousInventory = inventory;
                inventory = nextInventory;
                if (lockedMonster != null) monsterTarget = lockedMonster;
                playerMp -= mpCost;
                remainingMp = playerMp;
                spellReadyNanos.put(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        }
        cancelMeditation("classic-world-spell-" + spell.skillId());
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());
        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());

        List<ClientSession> recipients = classicWorldMembers(originMapId).stream()
                .filter(member -> member.phase == Phase.WORLD
                        && member.classicWorldMapId == originMapId
                        && member.classicWorldInstanceId == originInstanceId
                        && (BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY)
                            || BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                targetX, targetY)))
                .toList();
        byte[] action = Protocol.objectAction(
                playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION classic-world Silence caster="
                            + playerObjectId() + " action=" + spell.actionId());
        }

        boolean earthBindBlocked = playerTarget != null
                && playerTarget.timedStatus.earthBindActive(castNow);
        boolean probabilitySuccess = targetGate && !bossImmune
                && !earthBindBlocked && probability >= percentileRoll;
        consumeEraseMagicAfterProbability(
                playerTarget, monsterTarget, null, null,
                castNow, spell.skillId());
        if (playerTarget != null) {
            playerTarget.cancelSleep(
                    "classic-world-probability-spell-" + spell.skillId());
        }

        boolean countered = probabilitySuccess && playerTarget != null
                && playerTarget.timedStatus.consumeCounterMagic(castNow);
        boolean applied = false;
        if (countered) {
            publishCounterMagicConsumption(playerTarget, spell.skillId());
        } else if (probabilitySuccess && playerTarget != null) {
            playerTarget.timedStatus.activateSilence(
                    castNow, spell.durationSeconds());
            applied = true;
        } else if (probabilitySuccess) {
            applied = hub.silenceClassicWorldMonster(
                    originMapId, originInstanceId,
                    monsterTarget.objectId(), castNow,
                    spell.durationSeconds());
            if (applied) {
                hub.provokeClassicWorldMonster(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), playerObjectId());
            }
        }

        if (applied) {
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY,
                        targetX, targetY)) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT classic-world Silence target="
                                + request.targetObjectId() + " gfx="
                                + spell.effectGfx());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world Silence="
                        + remainingMp + "/" + playerMaxMp);
        if (!applied) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE classic-world-Silence-failure="
                            + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale classic-world"
                    + " Silence coordinates client=" + request.x() + ","
                    + request.y() + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world Silence skill="
                + spell.skillId() + " caster=" + playerName()
                + " target=" + request.targetObjectId() + " npc=" + npcId
                + " player-target=" + (playerTarget != null)
                + " target-gate=" + targetGate
                + " probability=" + probability + " roll=" + percentileRoll
                + " probability-success=" + probabilitySuccess
                + " applied=" + applied + " countered=" + countered
                + " mr=" + targetMr + " target-level=" + targetLevel
                + " boss-target=" + bossTarget + " boss-immune=" + bossImmune
                + " earth-bind-blocked=" + earthBindBlocked
                + " equipment-magic-hit=" + equipmentMagicHit
                + " buff-magic-hit=" + buffMagicHit
                + " total-magic-hit=" + totalMagicHit
                + " duration=" + spell.durationSeconds()
                + " mp-cost=" + mpCost + " mp=" + remainingMp
                + "/" + playerMaxMp);
    }

    private void useSilenceSpell(byte[] payload,
                                 BattleSpellCatalog.SilenceSpell spell)
            throws IOException {
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long originRoomId = currentRoomId;
        int originMapId = hub.battleMapId(originRoomId, this);
        int originX = positionX;
        int originY = positionY;
        List<ClientSession> combatants = hub.roomCombatants(originRoomId);
        ClientSession target = combatants.stream()
                .filter(candidate -> candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        BattleQuestEncounter.Snapshot questTarget =
                hub.questMonster(originRoomId, request.targetObjectId());
        BattleTimeAttackEncounter.Snapshot timeTarget =
                hub.timeAttackActor(originRoomId, request.targetObjectId());
        if (target == this || (target == null && questTarget == null && timeTarget == null)) {
            System.out.println("[LiTo] C_USE_SPELL Silence rejected target="
                    + request.targetObjectId());
            return;
        }

        int targetX = target != null ? target.positionX
                : questTarget != null ? questTarget.x() : timeTarget.x();
        int targetY = target != null ? target.positionY
                : questTarget != null ? questTarget.y() : timeTarget.y();
        boolean targetGate = target != null
                ? target.phase == Phase.BATTLE && target.playerHp > 0
                    && !target.observer && !target.invisible
                    && target.currentRoomId == originRoomId
                    && hub.battleMapId(originRoomId, target) == originMapId
                    && hub.canAttack(originRoomId, this, target)
                : questTarget != null
                    ? hub.canAttackQuestMonster(
                            originRoomId, this, questTarget.objectId())
                    : hub.canAttackTimeAttackActor(
                            originRoomId, this, timeTarget.objectId());
        int range = Math.max(Math.abs(originX - targetX),
                Math.abs(originY - targetY));
        boolean nativeScreen = BattleSpellCatalog.isInNativeScreen(
                originX, originY, targetX, targetY);
        boolean lineOfSight = BattleSpellCatalog.hasNativeLineOfSight(
                ArenaMapCatalog.forMap(originMapId),
                originX, originY, targetX, targetY);
        if (!targetGate || range > spell.maximumRange()
                || !nativeScreen || !lineOfSight) {
            System.out.println("[LiTo] C_USE_SPELL Silence rejected gate/range target="
                    + request.targetObjectId() + " range=" + range
                    + " max=" + spell.maximumRange() + " screen="
                    + nativeScreen + " line-of-sight=" + lineOfSight);
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Silence rejected unavailable action player="
                    + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int npcId = questTarget != null ? questTarget.npcId()
                : timeTarget != null ? timeTarget.npcId() : 0;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected Silence; source NPC lookup failed"
                        + " player=" + playerName() + " npc=" + npcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) {
                System.out.println("[LiTo] rejected Silence; source NPC row missing"
                        + " player=" + playerName() + " npc=" + npcId);
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        CharacterSummary targetCharacter = target == null
                ? null : target.selectedCharacterSummary();
        int targetLevel = target != null
                ? targetCharacter == null ? 1 : Math.max(1, targetCharacter.level())
                : questTarget != null ? questTarget.level() : timeTarget.level();
        long targetMrNow = System.nanoTime();
        int targetMr = target != null
                ? target.effectiveBaseMagicResistance(targetMrNow)
                : effectiveNpcMagicResistance(
                        questTarget, timeTarget,
                        npcStats == null ? 0 : npcStats.magicResistance(),
                        targetMrNow);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(System.nanoTime()).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int magicLevel = spell.includeMagicLevel()
                ? BattleTurnUndead.magicLevel(casterType, casterLevel) : 0;
        boolean bossTarget = npcStats != null && npcStats.boss()
                || timeTarget != null && timeTarget.finalBoss();
        boolean bossImmune = bossTarget && spell.bossModifier() == 0;
        int probability = spell.probabilityForTarget(
                casterLevel, targetLevel, effectiveIntelligence, magicLevel,
                totalMagicHit, targetMr, bossTarget);
        int configuredRoll = config.silenceFixturePercentileRoll();
        int percentileRoll = bossImmune ? 100
                : configuredRoll == 0
                    ? ThreadLocalRandom.current().nextInt(1, 101)
                    : configuredRoll;

        RuntimeInventory previousInventory;
        int remainingMp;
        long castNow;
        ClientSession firstLock = target == null
                || playerObjectId() <= target.playerObjectId()
                ? this : target;
        ClientSession secondLock = target == null
                ? this : firstLock == this ? target : this;
        synchronized (firstLock) {
            synchronized (secondLock) {
                castNow = System.nanoTime();
                long readyAt = spellReadyNanos.getOrDefault(
                        spell.skillId(), 0L);
                BattleQuestEncounter.Snapshot lockedQuest = questTarget == null
                        ? null : hub.questMonster(
                            originRoomId, questTarget.objectId());
                BattleTimeAttackEncounter.Snapshot lockedTime = timeTarget == null
                        ? null : hub.timeAttackActor(
                            originRoomId, timeTarget.objectId());
                boolean targetStillAvailable = target != null
                        ? target.phase == Phase.BATTLE && target.playerHp > 0
                            && !target.observer && !target.invisible
                            && target.currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, target)
                                == originMapId
                            && target.positionX == targetX
                            && target.positionY == targetY
                            && hub.canAttack(originRoomId, this, target)
                            && !BattleAbsoluteBarrierRules
                                .blocksIncomingSpell(
                                    target.timedStatus
                                        .absoluteBarrierActive(castNow),
                                    spell.skillId())
                        : lockedQuest != null
                            ? lockedQuest.alive()
                                && lockedQuest.x() == targetX
                                && lockedQuest.y() == targetY
                                && hub.canAttackQuestMonster(originRoomId,
                                    this, lockedQuest.objectId())
                            : lockedTime != null && lockedTime.alive()
                                && lockedTime.x() == targetX
                                && lockedTime.y() == targetY
                                && hub.canAttackTimeAttackActor(originRoomId,
                                    this, lockedTime.objectId());
                boolean endpointStillAllowed = currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, this) == originMapId
                        && positionX == originX && positionY == originY
                        && BattleSpellCatalog.isInNativeScreen(
                            originX, originY, targetX, targetY)
                        && BattleSpellCatalog.hasNativeLineOfSight(
                            ArenaMapCatalog.forMap(originMapId),
                            originX, originY, targetX, targetY)
                        && Math.max(Math.abs(originX - targetX),
                            Math.abs(originY - targetY))
                                <= spell.maximumRange();
                if (castNow < readyAt || playerMp < mpCost
                        || phase != Phase.BATTLE || playerHp <= 0 || observer
                        || !targetStillAvailable || !endpointStillAllowed) {
                    System.out.println("[LiTo] C_USE_SPELL Silence rejected state target="
                            + request.targetObjectId() + " mp=" + playerMp
                            + " cost=" + mpCost + " target-available="
                            + targetStillAvailable + " endpoint="
                            + endpointStillAllowed + " cooldownNanos="
                            + Math.max(0L, readyAt - castNow));
                    return;
                }
                RuntimeInventory nextInventory = inventory.copy();
                if (!nextInventory.removeCatalog(
                        spell.itemConsumeId(), spell.itemConsumeCount())) {
                    sendEncrypted(Protocol.messageCode(299),
                            "S_MESSAGE_CODE Silence-missing-reagent=299");
                    System.out.println("[LiTo] C_USE_SPELL Silence rejected missing reagent"
                            + " catalog=" + spell.itemConsumeId()
                            + " count=" + spell.itemConsumeCount());
                    return;
                }
                previousInventory = inventory;
                inventory = nextInventory;
                if (lockedQuest != null) questTarget = lockedQuest;
                if (lockedTime != null) timeTarget = lockedTime;
                playerMp -= mpCost;
                remainingMp = playerMp;
                spellReadyNanos.put(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        }

        cancelMeditation("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        boolean earthBindBlocked = earthBindBlocksProbabilityMagic(
                target, questTarget, timeTarget, castNow, spell.skillId());
        boolean probabilitySuccess = !bossImmune && !earthBindBlocked
                && probability >= percentileRoll;
        consumeEraseMagicAfterProbability(
                target, questTarget, timeTarget, castNow, spell.skillId());
        breakSleepForStatusSpell(target, questTarget, timeTarget,
                "probability-spell-" + spell.skillId());

        List<ClientSession> recipients = questTarget != null
                ? hub.battleRecipients(originRoomId, questTarget.force())
                : hub.roomMembers(originRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION Silence caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        boolean countered = probabilitySuccess && target != null
                && target.timedStatus.consumeCounterMagic(castNow);
        boolean applied = false;
        if (countered) {
            publishCounterMagicConsumption(target, spell.skillId());
        } else if (probabilitySuccess && target != null) {
            target.timedStatus.activateSilence(castNow, spell.durationSeconds());
            applied = true;
        } else if (probabilitySuccess && questTarget != null) {
            applied = hub.silenceQuestMonster(originRoomId, this,
                    questTarget.objectId(), castNow, spell.durationSeconds());
        } else if (probabilitySuccess && timeTarget != null) {
            applied = hub.silenceTimeAttackActor(originRoomId, this,
                    timeTarget.objectId(), castNow, spell.durationSeconds());
        }

        if (applied) {
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(effect,
                        "S_EFFECT Silence target=" + request.targetObjectId()
                                + " gfx=" + spell.effectGfx());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Silence=" + remainingMp + "/" + playerMaxMp);
        if (!applied) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE Silence-failure=" + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale Silence coordinates"
                    + " client=" + request.x() + "," + request.y()
                    + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL Silence skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + request.targetObjectId()
                + " npc=" + npcId + " probability=" + probability
                + " roll=" + percentileRoll + " probability-success="
                + probabilitySuccess + " applied=" + applied
                + " countered=" + countered + " mr=" + targetMr
                + " boss-target=" + bossTarget + " boss-immune=" + bossImmune
                + " earth-bind-blocked=" + earthBindBlocked
                + " equipment-magic-hit=" + equipmentMagicHit
                + " buff-magic-hit=" + buffMagicHit
                + " total-magic-hit=" + totalMagicHit
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    /**
     * Exact retained skill133 player-target path for Tournament and imported
     * classic WORLD. A zero roll fixture preserves the native random d100.
     */
    private void useElementalFallDownSpell(
            byte[] payload, BattleSpellCatalog.ElementalFallDownSpell spell,
            int probabilityRollFixture) throws IOException {
        if (probabilityRollFixture < 0 || probabilityRollFixture > 100) {
            throw new IllegalArgumentException(
                    "invalid Elemental Fall Down roll fixture");
        }
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        boolean classicWorld = phase == Phase.WORLD;
        if (classicWorld) {
            BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
            if (active != null && !active.skillUsable()) {
                sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                        "S_PARALYSE mode=7 reason=classic-world-polymorph-Elemental-Fall-Down-rejected");
                sendEncrypted(Protocol.messageCode(285),
                        "S_MESSAGE_CODE classic-world-polymorph-Elemental-Fall-Down-rejected=285");
                return;
            }
            if (timedStatus.silenceActive(requestNow)) {
                sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                        "S_PARALYSE mode=7 reason=classic-world-Silence-Elemental-Fall-Down-rejected");
                sendEncrypted(Protocol.messageCode(285),
                        "S_MESSAGE_CODE classic-world-Silence-Elemental-Fall-Down-rejected=285");
                return;
            }
            if (currentWeight240(requestNow)
                    >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
                sendEncrypted(Protocol.messageCode(316),
                        "S_MESSAGE_CODE classic-world-Elemental-Fall-Down-overweight=316");
                return;
            }
            if (!learnedSkills.contains(spell.skillId())) {
                System.out.println("[LiTo] C_USE_SPELL rejected unlearned"
                        + " classic-world Elemental Fall Down player="
                        + playerName());
                return;
            }
        }

        ClientSession target = (classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomCombatants(currentRoomId)).stream()
                .filter(candidate -> candidate != this
                        && candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        ClassicWorldMonsterPopulation.Snapshot worldMonster = classicWorld
                ? hub.classicWorldMonster(classicWorldMapId,
                        classicWorldInstanceId, request.targetObjectId()) : null;
        BattleQuestEncounter.Snapshot questTarget = classicWorld ? null
                : hub.questMonster(currentRoomId, request.targetObjectId());
        BattleTimeAttackEncounter.Snapshot timeTarget = classicWorld ? null
                : hub.timeAttackActor(currentRoomId, request.targetObjectId());
        if (target == null && worldMonster == null
                && questTarget == null && timeTarget == null) {
            System.out.println("[LiTo] C_USE_SPELL Elemental Fall Down rejected"
                    + " unsupported target=" + request.targetObjectId()
                    + " phase=" + phase);
            return;
        }

        int targetX = target != null ? target.positionX
                : worldMonster != null ? worldMonster.x()
                : questTarget != null ? questTarget.x() : timeTarget.x();
        int targetY = target != null ? target.positionY
                : worldMonster != null ? worldMonster.y()
                : questTarget != null ? questTarget.y() : timeTarget.y();
        int distance = Math.max(Math.abs(positionX - targetX),
                Math.abs(positionY - targetY));
        boolean targetGate;
        if (classicWorld) {
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(classicWorldMapId);
            boolean livingTarget = target != null
                    ? target.phase == Phase.WORLD && target.playerHp > 0
                        && !target.invisible && sameClassicWorldMap(target)
                    : worldMonster.present() && worldMonster.alive()
                        && worldMonster.mapId() == classicWorldMapId;
            targetGate = livingTarget
                    && !map.isSafetyZone(positionX, positionY)
                    && !map.isSafetyZone(targetX, targetY)
                    && map.attackPosition(positionX, positionY,
                            targetX, targetY, spell.maximumRange());
        } else {
            int casterMap = hub.battleMapId(currentRoomId, this);
            boolean attackable = target != null
                    ? target.phase == Phase.BATTLE && target.playerHp > 0
                        && !target.invisible
                        && hub.battleMapId(currentRoomId, target) == casterMap
                        && hub.canAttack(currentRoomId, this, target)
                    : questTarget != null
                        ? hub.canAttackQuestMonster(
                                currentRoomId, this, questTarget.objectId())
                        : hub.canAttackTimeAttackActor(
                                currentRoomId, this, timeTarget.objectId());
            targetGate = phase == Phase.BATTLE && attackable
                    && BattleSpellCatalog.hasNativeLineOfSight(
                            ArenaMapCatalog.forMap(casterMap),
                            positionX, positionY, targetX, targetY);
        }
        if (!targetGate || distance > spell.maximumRange()
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL Elemental Fall Down rejected"
                    + " gate/range target=" + request.targetObjectId()
                    + " range=" + distance + " max=" + spell.maximumRange()
                    + " phase=" + phase);
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Elemental Fall Down rejected"
                    + " unavailable action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        int npcId = worldMonster != null ? worldMonster.npcId()
                : questTarget != null ? questTarget.npcId()
                : timeTarget != null ? timeTarget.npcId() : 0;
        SourceNpcPhysicalStats npcStats = null;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected Elemental Fall Down; source"
                        + " NPC lookup failed player=" + playerName()
                        + " npc=" + npcId + " reason="
                        + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) {
                System.out.println("[LiTo] rejected Elemental Fall Down; source"
                        + " NPC row missing player=" + playerName()
                        + " npc=" + npcId);
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        CharacterSummary targetCharacter = target == null
                ? null : target.selectedCharacterSummary();
        int targetLevel = target != null
                ? targetCharacter == null ? 1
                    : Math.max(1, targetCharacter.level())
                : worldMonster != null ? worldMonster.template().level()
                : questTarget != null ? questTarget.level() : timeTarget.level();
        int targetMr = target != null
                ? target.effectiveBaseMagicResistance(requestNow)
                : effectiveNpcMagicResistance(
                        worldMonster, questTarget, timeTarget,
                        npcStats.magicResistance(), requestNow);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(requestNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int magicLevel = spell.includeMagicLevel()
                ? BattleTurnUndead.magicLevel(casterType, casterLevel) : 0;
        boolean bossTarget = npcStats != null && (npcStats.boss()
                || worldMonster != null && worldMonster.template().boss()
                || timeTarget != null && timeTarget.finalBoss());
        int probability = spell.probabilityForTarget(
                casterLevel, targetLevel, effectiveIntelligence, magicLevel,
                totalMagicHit, targetMr, bossTarget);
        int percentileRoll = bossTarget ? 100 : probabilityRollFixture > 0
                ? probabilityRollFixture
                : ThreadLocalRandom.current().nextInt(1, 101);

        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean phaseGate = classicWorld
                    ? phase == Phase.WORLD && (target != null
                        ? target.phase == Phase.WORLD
                            && sameClassicWorldMap(target)
                        : worldMonster.present() && worldMonster.alive()
                            && worldMonster.mapId() == classicWorldMapId)
                    : phase == Phase.BATTLE && currentRoomId != 0
                        && (target == null || target.phase == Phase.BATTLE);
            boolean livingTarget = target != null ? target.playerHp > 0
                    : worldMonster != null ? worldMonster.alive()
                    : questTarget != null ? questTarget.alive()
                    : timeTarget.alive();
            if (castNow < readyAt || playerMp < mpCost || observer
                    || playerHp <= 0 || !livingTarget || !phaseGate) {
                System.out.println("[LiTo] C_USE_SPELL Elemental Fall Down"
                        + " rejected state target=" + request.targetObjectId()
                        + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            cancelMeditation((classicWorld ? "classic-world-" : "")
                    + "spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        boolean probabilityBlocked = bossTarget
                || earthBindBlocksProbabilityMagic(
                        target, questTarget, timeTarget,
                        castNow, spell.skillId());
        boolean probabilitySuccess = !probabilityBlocked
                && probability >= percentileRoll;
        consumeEraseMagicAfterProbability(
                target, worldMonster, questTarget, timeTarget,
                castNow, spell.skillId());
        breakSleepForStatusSpell(target, questTarget, timeTarget,
                (classicWorld ? "classic-world-" : "")
                        + "probability-spell-" + spell.skillId());

        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : questTarget != null
                    ? hub.battleRecipients(currentRoomId, questTarget.force())
                    : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            if (classicWorld
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, positionX, positionY)
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, targetX, targetY)) {
                continue;
            }
            member.sendEncrypted(action,
                    "S_ACTION " + (classicWorld ? "classic-world " : "")
                            + "Elemental Fall Down caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        boolean counterMagicBypass =
                sourceCounterMagicBypassSkills.contains(spell.skillId());
        boolean countered = probabilitySuccess && target != null
                && !counterMagicBypass
                && target.timedStatus.consumeCounterMagic(castNow);
        if (countered) {
            publishCounterMagicConsumption(target, spell.skillId());
        }
        BattleElementalFallDownStatus.Activation activation = null;
        boolean applied = false;
        int appliedAttribute = 0;
        boolean refreshed = false;
        if (!countered && probabilitySuccess && target != null) {
            activation = target.elementalFallDownStatus.activate(
                    castNow, spell.durationSeconds(), elfAttribute);
            applied = true;
            appliedAttribute = activation.attributeKind();
            refreshed = activation.refreshed();
            target.sendNativeBattleStatus(castNow,
                    "elemental-fall-down-" + (activation.refreshed()
                            ? "refresh" : "start"));
        } else if (!countered && probabilitySuccess && worldMonster != null) {
            applied = hub.elementalFallDownClassicWorldMonster(
                    classicWorldMapId, classicWorldInstanceId,
                    worldMonster.objectId(), castNow,
                    spell.durationSeconds(), elfAttribute);
            appliedAttribute = BattleElementalFallDownStatus.retainedAttribute(
                    elfAttribute);
            if (applied) {
                hub.provokeClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        worldMonster.objectId(), playerObjectId());
            }
        } else if (!countered && probabilitySuccess && questTarget != null) {
            applied = hub.elementalFallDownQuestMonster(
                    currentRoomId, this, questTarget.objectId(), castNow,
                    spell.durationSeconds(), elfAttribute);
            appliedAttribute = BattleElementalFallDownStatus.retainedAttribute(
                    elfAttribute);
        } else if (!countered && probabilitySuccess && timeTarget != null) {
            applied = hub.elementalFallDownTimeAttackActor(
                    currentRoomId, this, timeTarget.objectId(), castNow,
                    spell.durationSeconds(), elfAttribute);
            appliedAttribute = BattleElementalFallDownStatus.retainedAttribute(
                    elfAttribute);
        }
        if (applied) {
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                if (classicWorld && !BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, targetX, targetY)) {
                    continue;
                }
                member.sendEncrypted(effect,
                        "S_EFFECT " + (classicWorld ? "classic-world " : "")
                                + "Elemental Fall Down target="
                                + request.targetObjectId() + " gfx="
                                + spell.effectGfx());
            }
            if (appliedAttribute == 0) {
                sendEncrypted(Protocol.messageCode(79),
                        "S_MESSAGE_CODE Elemental-Fall-Down-no-attribute=79");
            }
        }

        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Elemental-Fall-Down="
                        + remainingMp + "/" + playerMaxMp);
        if (!applied) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE Elemental-Fall-Down-failure="
                            + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale Elemental"
                    + " Fall Down coordinates client=" + request.x() + ","
                    + request.y() + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL Elemental Fall Down skill="
                + spell.skillId() + " caster=" + playerName() + " target="
                + request.targetObjectId() + " npc=" + npcId
                + " probability=" + probability
                + " roll=" + percentileRoll + " applied="
                + applied + " refreshed=" + refreshed
                + " attribute=" + appliedAttribute
                + " modifier=" + (!applied ? 0
                    : appliedAttribute == 0 ? 0
                    : -spell.resistanceDebuff())
                + " countered=" + countered
                + " counter-magic-bypass=" + counterMagicBypass
                + " earth-bind-or-barrier-blocked=" + probabilityBlocked
                + " boss-target=" + bossTarget
                + " mr=" + targetMr + " magic-hit=" + totalMagicHit
                + " duration=" + spell.durationSeconds()
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/"
                + playerMaxMp
                + " icon=omitted-no-selected-LiTo-packetbox-receiver");
    }

    private void useEntangleSpell(
            byte[] payload, BattleSpellCatalog.EntangleSpell spell,
            int probabilityRollFixture) throws IOException {
        if (probabilityRollFixture < 0 || probabilityRollFixture > 100) {
            throw new IllegalArgumentException("invalid Entangle roll fixture");
        }
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        boolean classicWorld = phase == Phase.WORLD;
        if (phase != Phase.BATTLE && !classicWorld) return;
        if (classicWorld) {
            BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
            if (active != null && !active.skillUsable()) {
                sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                        "S_PARALYSE mode=7 reason=classic-world-polymorph-Entangle-rejected");
                sendEncrypted(Protocol.messageCode(285),
                        "S_MESSAGE_CODE classic-world-polymorph-Entangle-rejected=285");
                return;
            }
            if (timedStatus.silenceActive(requestNow)) {
                sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                        "S_PARALYSE mode=7 reason=classic-world-Silence-Entangle-rejected");
                sendEncrypted(Protocol.messageCode(285),
                        "S_MESSAGE_CODE classic-world-Silence-Entangle-rejected=285");
                return;
            }
            if (currentWeight240(requestNow)
                    >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
                sendEncrypted(Protocol.messageCode(316),
                        "S_MESSAGE_CODE classic-world-Entangle-overweight=316");
                return;
            }
            if (!learnedSkills.contains(spell.skillId())) {
                System.out.println("[LiTo] C_USE_SPELL rejected unlearned"
                        + " classic-world Entangle player=" + playerName());
                return;
            }
        }

        ClientSession target = (classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomCombatants(currentRoomId)).stream()
                .filter(candidate -> candidate != this
                        && candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        ClientSession companionOwner = null;
        BattleCompanion controlledCompanion = null;
        BattleCompanion.Snapshot companionTarget = null;
        List<ClientSession> companionOwners = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomCombatants(currentRoomId);
        for (ClientSession owner : companionOwners) {
            List<BattleCompanion.Snapshot> snapshots = classicWorld
                    ? owner.classicWorldCompanionSnapshots()
                    : owner.controlledCompanionSnapshots();
            BattleCompanion.Snapshot candidate = snapshots.stream()
                    .filter(snapshot -> snapshot.objectId()
                            == request.targetObjectId())
                    .findFirst().orElse(null);
            if (candidate == null) continue;
            BattleCompanion controlled = owner.ownedCompanion(candidate.objectId());
            if (controlled == null) continue;
            companionOwner = owner;
            controlledCompanion = controlled;
            companionTarget = candidate;
            break;
        }
        ClassicWorldMonsterPopulation.Snapshot worldMonster = classicWorld
                ? hub.classicWorldMonster(classicWorldMapId,
                        classicWorldInstanceId, request.targetObjectId()) : null;
        BattleQuestEncounter.Snapshot questTarget = classicWorld ? null
                : hub.questMonster(currentRoomId, request.targetObjectId());
        BattleTimeAttackEncounter.Snapshot timeTarget = classicWorld ? null
                : hub.timeAttackActor(currentRoomId, request.targetObjectId());
        if (target == null && companionTarget == null && worldMonster == null
                && questTarget == null && timeTarget == null) {
            System.out.println("[LiTo] C_USE_SPELL Entangle rejected unsupported target="
                    + request.targetObjectId() + " phase=" + phase);
            return;
        }

        int targetX = target != null ? target.positionX
                : companionTarget != null ? companionTarget.x()
                : worldMonster != null ? worldMonster.x()
                : questTarget != null ? questTarget.x() : timeTarget.x();
        int targetY = target != null ? target.positionY
                : companionTarget != null ? companionTarget.y()
                : worldMonster != null ? worldMonster.y()
                : questTarget != null ? questTarget.y() : timeTarget.y();
        int distance = Math.max(Math.abs(positionX - targetX),
                Math.abs(positionY - targetY));
        boolean targetGate;
        if (classicWorld) {
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(classicWorldMapId);
            boolean livingTarget = target != null
                    ? target.phase == Phase.WORLD && target.playerHp > 0
                        && !target.invisible && sameClassicWorldMap(target)
                    : companionTarget != null
                        ? companionOwner.phase == Phase.WORLD
                            && sameClassicWorldMap(companionOwner)
                            && companionTarget.kind().classicWorldEligible()
                            && companionTarget.active() && companionTarget.hp() > 0
                    : worldMonster.present() && worldMonster.alive()
                        && worldMonster.mapId() == classicWorldMapId;
            targetGate = livingTarget
                    && !map.isSafetyZone(positionX, positionY)
                    && !map.isSafetyZone(targetX, targetY)
                    && map.attackPosition(positionX, positionY,
                            targetX, targetY, spell.maximumRange());
        } else {
            int casterMap = hub.battleMapId(currentRoomId, this);
            boolean attackable = target != null
                    ? target.phase == Phase.BATTLE && target.playerHp > 0
                        && !target.invisible
                        && hub.battleMapId(currentRoomId, target) == casterMap
                        && hub.canAttack(currentRoomId, this, target)
                    : companionTarget != null
                        ? companionOwner.phase == Phase.BATTLE
                            && companionTarget.active() && companionTarget.hp() > 0
                            && hub.battleMapId(currentRoomId, companionOwner)
                                == casterMap
                            && (companionOwner == this || hub.canAttack(currentRoomId, this, companionOwner))
                    : questTarget != null
                        ? hub.canAttackQuestMonster(
                                currentRoomId, this, questTarget.objectId())
                        : hub.canAttackTimeAttackActor(
                                currentRoomId, this, timeTarget.objectId());
            targetGate = phase == Phase.BATTLE && attackable
                    && BattleSpellCatalog.hasNativeLineOfSight(
                            ArenaMapCatalog.forMap(casterMap),
                            positionX, positionY, targetX, targetY);
        }
        if (!targetGate || distance > spell.maximumRange()
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL Entangle rejected gate/range target="
                    + request.targetObjectId() + " range=" + distance
                    + " max=" + spell.maximumRange() + " phase=" + phase);
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Entangle rejected unavailable action"
                    + " player=" + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        int npcId = worldMonster != null ? worldMonster.npcId()
                : companionTarget != null ? companionTarget.npcId()
                : questTarget != null ? questTarget.npcId()
                : timeTarget != null ? timeTarget.npcId() : 0;
        SourceNpcPhysicalStats npcStats = null;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected Entangle; source NPC lookup failed"
                        + " player=" + playerName() + " npc=" + npcId
                        + " reason=" + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null || !npcStats.eraseEligible()) {
                System.out.println("[LiTo] rejected Entangle; NPC not erase-eligible"
                        + " player=" + playerName() + " npc=" + npcId);
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);
        CharacterSummary targetCharacter = target == null
                ? null : target.selectedCharacterSummary();
        int targetLevel = target != null
                ? targetCharacter == null ? 1
                    : Math.max(1, targetCharacter.level())
                : companionTarget != null ? companionTarget.level()
                : worldMonster != null ? worldMonster.template().level()
                : questTarget != null ? questTarget.level() : timeTarget.level();
        int targetMr = target != null
                ? target.effectiveBaseMagicResistance(requestNow)
                : companionTarget != null
                    ? controlledCompanion.effectiveMagicResistance(
                            npcStats.magicResistance(), requestNow)
                : effectiveNpcMagicResistance(
                        worldMonster, questTarget, timeTarget,
                        npcStats.magicResistance(), requestNow);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(requestNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int magicLevel = spell.includeMagicLevel()
                ? BattleTurnUndead.magicLevel(casterType, casterLevel) : 0;
        boolean bossTarget = npcStats != null && (npcStats.boss()
                || worldMonster != null && worldMonster.template().boss()
                || timeTarget != null && timeTarget.finalBoss());
        int probability = spell.probabilityForTarget(
                casterLevel, targetLevel, effectiveIntelligence, magicLevel,
                totalMagicHit, targetMr, bossTarget);
        int percentileRoll = probabilityRollFixture > 0
                ? probabilityRollFixture
                : ThreadLocalRandom.current().nextInt(1, 101);

        RuntimeInventory previousInventory;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean phaseGate = classicWorld
                    ? phase == Phase.WORLD && (target != null
                        ? target.phase == Phase.WORLD && sameClassicWorldMap(target)
                        : companionTarget != null
                            ? companionOwner.phase == Phase.WORLD
                                && sameClassicWorldMap(companionOwner)
                                && companionTarget.kind().classicWorldEligible()
                        : worldMonster.present() && worldMonster.alive()
                            && worldMonster.mapId() == classicWorldMapId)
                    : phase == Phase.BATTLE && currentRoomId != 0
                        && (target != null ? target.phase == Phase.BATTLE
                            : companionTarget == null
                                || companionOwner.phase == Phase.BATTLE);
            boolean livingTarget = target != null ? target.playerHp > 0
                    : companionTarget != null
                        ? companionTarget.active() && companionTarget.hp() > 0
                    : worldMonster != null ? worldMonster.alive()
                    : questTarget != null ? questTarget.alive() : timeTarget.alive();
            if (castNow < readyAt || playerMp < mpCost || observer
                    || playerHp <= 0 || !livingTarget || !phaseGate) {
                System.out.println("[LiTo] C_USE_SPELL Entangle rejected state target="
                        + request.targetObjectId() + " mp=" + playerMp
                        + " cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE Entangle-missing-reagent=299");
                System.out.println("[LiTo] C_USE_SPELL Entangle rejected missing reagent"
                        + " catalog=" + spell.itemConsumeId()
                        + " count=" + spell.itemConsumeCount());
                return;
            }
            previousInventory = inventory;
            inventory = nextInventory;
            cancelMeditation((classicWorld ? "classic-world-" : "")
                    + "spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        boolean probabilityBlocked = probability == 0
                || controlledCompanion != null
                    && controlledCompanion.earthBindActive(castNow)
                || earthBindBlocksProbabilityMagic(
                        target, questTarget, timeTarget,
                        castNow, spell.skillId());
        boolean probabilitySuccess = !probabilityBlocked
                && probability >= percentileRoll;
        consumeEraseMagicAfterProbability(
                target, worldMonster, questTarget, timeTarget,
                castNow, spell.skillId());
        if (controlledCompanion != null) {
            controlledCompanion.consumeEraseMagic(castNow);
        }
        breakSleepForStatusSpell(target, questTarget, timeTarget,
                (classicWorld ? "classic-world-" : "")
                        + "probability-spell-" + spell.skillId());
        if (controlledCompanion != null) controlledCompanion.cancelSleep();

        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : questTarget != null
                    ? hub.battleRecipients(currentRoomId, questTarget.force())
                    : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            if (classicWorld
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, positionX, positionY)
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, targetX, targetY)) {
                continue;
            }
            member.sendEncrypted(action,
                    "S_ACTION " + (classicWorld ? "classic-world " : "")
                            + "Entangle caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        boolean countered = probabilitySuccess && target != null
                && !spell.counterMagicBypass()
                && target.timedStatus.consumeCounterMagic(castNow);
        if (countered) publishCounterMagicConsumption(target, spell.skillId());
        boolean nativeSpeedImmune = target != null
                && (target.inventory.hasEquippedHasteArmor()
                    || target.timedStatus.brave(castNow).mode()
                        == BattleTimedStatus.BRAVE_SECOND);
        boolean applied = false;
        int resultingSpeed = BattleTimedStatus.NORMAL;
        if (!countered && probabilitySuccess && target != null
                && !nativeSpeedImmune) {
            BattleTimedStatus.SpeedChange change = target.timedStatus.activateSlow(
                    castNow, spell.durationSeconds(), spell.skillId());
            resultingSpeed = change.type();
            if (change.stoppedSkillId() != 0) {
                target.sendHasteStopMessage(
                        change.stoppedSkillId(), "entangle-neutralized-haste");
            }
            if (resultingSpeed == BattleTimedStatus.NORMAL) {
                target.sendSlowStopMessage(
                        spell.skillId(), "entangle-neutralized-haste");
            }
            applied = true;
        } else if (!countered && probabilitySuccess && companionTarget != null) {
            BattleTimedStatus.SpeedChange change = controlledCompanion.activateSlow(
                    castNow, spell.durationSeconds(), spell.skillId());
            resultingSpeed = change.type();
            companionTarget = controlledCompanion.snapshot();
            applied = true;
        } else if (!countered && probabilitySuccess && worldMonster != null) {
            applied = hub.slowClassicWorldMonster(
                    classicWorldMapId, classicWorldInstanceId,
                    worldMonster.objectId(), castNow, spell.durationSeconds());
            resultingSpeed = applied && hub.classicWorldMonsterSlowActive(
                    classicWorldMapId, classicWorldInstanceId,
                    worldMonster.objectId(), castNow)
                            ? BattleTimedStatus.SLOW : BattleTimedStatus.NORMAL;
            if (applied) {
                hub.provokeClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        worldMonster.objectId(), playerObjectId());
            }
        } else if (!countered && probabilitySuccess && questTarget != null) {
            applied = hub.slowQuestMonster(currentRoomId, this,
                    questTarget.objectId(), castNow, spell.durationSeconds());
            resultingSpeed = applied && hub.questMonsterSlowActive(
                    currentRoomId, questTarget.objectId(), castNow)
                            ? BattleTimedStatus.SLOW : BattleTimedStatus.NORMAL;
        } else if (!countered && probabilitySuccess && timeTarget != null) {
            applied = hub.slowTimeAttackActor(currentRoomId, this,
                    timeTarget.objectId(), castNow, spell.durationSeconds());
            resultingSpeed = applied && hub.timeAttackActorSlowActive(
                    currentRoomId, timeTarget.objectId(), castNow)
                            ? BattleTimedStatus.SLOW : BattleTimedStatus.NORMAL;
        }

        if (applied) {
            for (ClientSession member : recipients) {
                if (classicWorld && !BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, targetX, targetY)) continue;
                int duration = member == target
                        && resultingSpeed == BattleTimedStatus.SLOW
                        ? spell.durationSeconds() : 0;
                member.sendEncrypted(Protocol.speed(
                                request.targetObjectId(),
                                Protocol.SpeedMode.fromWire(resultingSpeed), duration),
                        "S_SPEED " + (classicWorld ? "classic-world " : "")
                                + "Entangle target=" + request.targetObjectId()
                                + " type=" + resultingSpeed
                                + " duration=" + duration);
            }
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                if (classicWorld && !BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, targetX, targetY)) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT " + (classicWorld ? "classic-world " : "")
                                + "Entangle target=" + request.targetObjectId()
                                + " gfx=" + spell.effectGfx());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Entangle=" + remainingMp + "/" + playerMaxMp);
        if (!applied && !nativeSpeedImmune) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE Entangle-failure=" + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale Entangle coordinates"
                    + " client=" + request.x() + "," + request.y()
                    + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL Entangle skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + request.targetObjectId()
                + " npc=" + npcId + " probability=" + probability
                + " roll=" + percentileRoll + " applied=" + applied
                + " resulting-speed=" + resultingSpeed
                + " native-speed-immune=" + nativeSpeedImmune
                + " countered=" + countered
                + " earth-bind-or-boss-blocked=" + probabilityBlocked
                + " boss-target=" + bossTarget + " mr=" + targetMr
                + " magic-hit=" + totalMagicHit + " duration="
                + spell.durationSeconds() + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    /** Exact selected skill153/case152 cccdhh target path. */
    private void useEraseMagicSpell(
            byte[] payload, BattleSpellCatalog.EraseMagicSpell spell,
            int probabilityRollFixture) throws IOException {
        if (probabilityRollFixture < 0 || probabilityRollFixture > 100) {
            throw new IllegalArgumentException("invalid Erase Magic roll fixture");
        }
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        boolean classicWorld = phase == Phase.WORLD;
        if (phase != Phase.BATTLE && !classicWorld) return;
        if (classicWorld) {
            BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
            if (active != null && !active.skillUsable()) {
                sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                        "S_PARALYSE mode=7 reason=classic-world-polymorph-Erase-Magic-rejected");
                sendEncrypted(Protocol.messageCode(285),
                        "S_MESSAGE_CODE classic-world-polymorph-Erase-Magic-rejected=285");
                return;
            }
            if (timedStatus.silenceActive(requestNow)) {
                sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                        "S_PARALYSE mode=7 reason=classic-world-Silence-Erase-Magic-rejected");
                sendEncrypted(Protocol.messageCode(285),
                        "S_MESSAGE_CODE classic-world-Silence-Erase-Magic-rejected=285");
                return;
            }
            if (currentWeight240(requestNow)
                    >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
                sendEncrypted(Protocol.messageCode(316),
                        "S_MESSAGE_CODE classic-world-Erase-Magic-overweight=316");
                return;
            }
            if (!learnedSkills.contains(spell.skillId())) {
                System.out.println("[LiTo] C_USE_SPELL rejected unlearned"
                        + " classic-world Erase Magic player=" + playerName());
                return;
            }
        }

        ClientSession target = (classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomCombatants(currentRoomId)).stream()
                .filter(candidate -> candidate != this
                        && candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        ClientSession companionOwner = null;
        BattleCompanion controlledCompanion = null;
        BattleCompanion.Snapshot companionTarget = null;
        List<ClientSession> companionOwners = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomCombatants(currentRoomId);
        for (ClientSession owner : companionOwners) {
            List<BattleCompanion.Snapshot> snapshots = classicWorld
                    ? owner.classicWorldCompanionSnapshots()
                    : owner.controlledCompanionSnapshots();
            BattleCompanion.Snapshot candidate = snapshots.stream()
                    .filter(snapshot -> snapshot.objectId()
                            == request.targetObjectId())
                    .findFirst().orElse(null);
            if (candidate == null) continue;
            BattleCompanion controlled = owner.ownedCompanion(candidate.objectId());
            if (controlled == null) continue;
            companionOwner = owner;
            controlledCompanion = controlled;
            companionTarget = candidate;
            break;
        }
        ClassicWorldMonsterPopulation.Snapshot worldMonster = classicWorld
                ? hub.classicWorldMonster(classicWorldMapId,
                        classicWorldInstanceId, request.targetObjectId()) : null;
        BattleQuestEncounter.Snapshot questTarget = classicWorld ? null
                : hub.questMonster(currentRoomId, request.targetObjectId());
        BattleTimeAttackEncounter.Snapshot timeTarget = classicWorld ? null
                : hub.timeAttackActor(currentRoomId, request.targetObjectId());
        if (target == null && companionTarget == null && worldMonster == null
                && questTarget == null && timeTarget == null) {
            System.out.println("[LiTo] C_USE_SPELL Erase Magic rejected unsupported target="
                    + request.targetObjectId() + " phase=" + phase);
            return;
        }

        int targetX = target != null ? target.positionX
                : companionTarget != null ? companionTarget.x()
                : worldMonster != null ? worldMonster.x()
                : questTarget != null ? questTarget.x() : timeTarget.x();
        int targetY = target != null ? target.positionY
                : companionTarget != null ? companionTarget.y()
                : worldMonster != null ? worldMonster.y()
                : questTarget != null ? questTarget.y() : timeTarget.y();
        int distance = Math.max(Math.abs(positionX - targetX),
                Math.abs(positionY - targetY));
        boolean targetGate;
        if (classicWorld) {
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(classicWorldMapId);
            boolean livingTarget = target != null
                    ? target.phase == Phase.WORLD && target.playerHp > 0
                        && !target.invisible && sameClassicWorldMap(target)
                    : companionTarget != null
                        ? companionOwner.phase == Phase.WORLD
                            && sameClassicWorldMap(companionOwner)
                            && companionTarget.kind().classicWorldEligible()
                            && companionTarget.active() && companionTarget.hp() > 0
                    : worldMonster.present() && worldMonster.alive()
                        && worldMonster.mapId() == classicWorldMapId;
            targetGate = livingTarget
                    && !map.isSafetyZone(positionX, positionY)
                    && !map.isSafetyZone(targetX, targetY)
                    && map.attackPosition(positionX, positionY,
                            targetX, targetY, spell.selectionRange());
        } else {
            int casterMap = hub.battleMapId(currentRoomId, this);
            boolean attackable = target != null
                    ? target.phase == Phase.BATTLE && target.playerHp > 0
                        && !target.invisible
                        && hub.battleMapId(currentRoomId, target) == casterMap
                        && hub.canAttack(currentRoomId, this, target)
                    : companionTarget != null
                        ? companionOwner.phase == Phase.BATTLE
                            && companionTarget.active() && companionTarget.hp() > 0
                            && hub.battleMapId(currentRoomId, companionOwner)
                                == casterMap
                            && (companionOwner == this || hub.canAttack(currentRoomId, this, companionOwner))
                    : questTarget != null
                        ? hub.canAttackQuestMonster(
                                currentRoomId, this, questTarget.objectId())
                        : hub.canAttackTimeAttackActor(
                                currentRoomId, this, timeTarget.objectId());
            targetGate = phase == Phase.BATTLE && attackable
                    && BattleSpellCatalog.hasNativeLineOfSight(
                            ArenaMapCatalog.forMap(casterMap),
                            positionX, positionY, targetX, targetY);
        }
        if (!targetGate || distance > spell.selectionRange()
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL Erase Magic rejected gate/range target="
                    + request.targetObjectId() + " range=" + distance
                    + " selected-client-max=" + spell.selectionRange()
                    + " db-range=" + spell.maximumRange() + " phase=" + phase);
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Erase Magic rejected unavailable action"
                    + " player=" + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        int npcId = worldMonster != null ? worldMonster.npcId()
                : companionTarget != null ? companionTarget.npcId()
                : questTarget != null ? questTarget.npcId()
                : timeTarget != null ? timeTarget.npcId() : 0;
        SourceNpcPhysicalStats npcStats = null;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected Erase Magic; source NPC lookup failed"
                        + " player=" + playerName() + " npc=" + npcId
                        + " reason=" + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null || !npcStats.eraseEligible()) {
                System.out.println("[LiTo] rejected Erase Magic; NPC not erase-eligible"
                        + " player=" + playerName() + " npc=" + npcId);
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        CharacterSummary targetCharacter = target == null
                ? null : target.selectedCharacterSummary();
        int targetLevel = target != null
                ? targetCharacter == null ? 1 : Math.max(1, targetCharacter.level())
                : companionTarget != null ? companionTarget.level()
                : worldMonster != null ? worldMonster.template().level()
                : questTarget != null ? questTarget.level() : timeTarget.level();
        int baseTargetMr = target != null ? target.effectiveBaseMagicResistance()
                : npcStats.magicResistance();
        int targetMr = target != null ? baseTargetMr
                : companionTarget != null
                    ? controlledCompanion.effectiveMagicResistance(
                            baseTargetMr, requestNow)
                : worldMonster != null
                    ? hub.classicWorldMonsterEffectiveMagicResistance(
                            classicWorldMapId, classicWorldInstanceId,
                            worldMonster.objectId(), baseTargetMr, requestNow)
                    : questTarget != null
                        ? hub.questMonsterEffectiveMagicResistance(
                                currentRoomId, questTarget.objectId(),
                                baseTargetMr, requestNow)
                        : hub.timeAttackActorEffectiveMagicResistance(
                                currentRoomId, timeTarget.objectId(),
                                baseTargetMr, requestNow);
        int totalMagicHit = Math.addExact(casterEquipment.totalMagicHit(),
                dragonEyeStatus.snapshot(requestNow).magicHit());
        int magicLevel = spell.includeMagicLevel()
                ? BattleTurnUndead.magicLevel(casterType, casterLevel) : 0;
        boolean bossTarget = npcStats != null && (npcStats.boss()
                || worldMonster != null && worldMonster.template().boss()
                || timeTarget != null && timeTarget.finalBoss());
        int probability = spell.probabilityForTarget(
                casterLevel, targetLevel, effectiveIntelligence, magicLevel,
                totalMagicHit, targetMr, bossTarget);
        int percentileRoll = bossTarget ? 100 : probabilityRollFixture > 0
                ? probabilityRollFixture
                : ThreadLocalRandom.current().nextInt(1, 101);

        RuntimeInventory previousInventory;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean phaseGate = classicWorld
                    ? phase == Phase.WORLD && (target != null
                        ? target.phase == Phase.WORLD && sameClassicWorldMap(target)
                        : companionTarget != null
                            ? companionOwner.phase == Phase.WORLD
                                && sameClassicWorldMap(companionOwner)
                                && companionTarget.kind().classicWorldEligible()
                        : worldMonster.present() && worldMonster.alive()
                            && worldMonster.mapId() == classicWorldMapId)
                    : phase == Phase.BATTLE && currentRoomId != 0
                        && (target != null ? target.phase == Phase.BATTLE
                            : companionTarget == null
                                || companionOwner.phase == Phase.BATTLE);
            boolean livingTarget = target != null ? target.playerHp > 0
                    : companionTarget != null
                        ? companionTarget.active() && companionTarget.hp() > 0
                    : worldMonster != null ? worldMonster.alive()
                    : questTarget != null ? questTarget.alive() : timeTarget.alive();
            if (castNow < readyAt || playerMp < mpCost || observer
                    || playerHp <= 0 || !livingTarget || !phaseGate) {
                System.out.println("[LiTo] C_USE_SPELL Erase Magic rejected state target="
                        + request.targetObjectId() + " mp=" + playerMp
                        + " cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE Erase-Magic-missing-reagent=299");
                System.out.println("[LiTo] C_USE_SPELL Erase Magic rejected missing reagent"
                        + " catalog=" + spell.itemConsumeId()
                        + " count=" + spell.itemConsumeCount());
                return;
            }
            previousInventory = inventory;
            inventory = nextInventory;
            cancelMeditation((classicWorld ? "classic-world-" : "")
                    + "spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        boolean probabilityBlocked = bossTarget
                || earthBindBlocksProbabilityMagic(
                        target, questTarget, timeTarget,
                        castNow, spell.skillId());
        boolean probabilitySuccess = !probabilityBlocked
                && probability >= percentileRoll;
        consumeEraseMagicAfterProbability(
                target, worldMonster, questTarget, timeTarget,
                castNow, spell.skillId());
        breakSleepForStatusSpell(target, questTarget, timeTarget,
                (classicWorld ? "classic-world-" : "")
                        + "probability-spell-" + spell.skillId());

        boolean applied = false;
        if (probabilitySuccess && target != null) {
            target.eraseMagicStatus.activate(castNow, spell.durationSeconds());
            applied = true;
        } else if (probabilitySuccess && companionTarget != null) {
            applied = controlledCompanion.activateEraseMagic(
                    castNow, spell.durationSeconds());
        } else if (probabilitySuccess && worldMonster != null) {
            applied = hub.eraseMagicClassicWorldMonster(
                    classicWorldMapId, classicWorldInstanceId,
                    worldMonster.objectId(), castNow, spell.durationSeconds());
            if (applied) {
                hub.provokeClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        worldMonster.objectId(), playerObjectId());
            }
        } else if (probabilitySuccess && questTarget != null) {
            applied = hub.eraseMagicQuestMonster(currentRoomId, this,
                    questTarget.objectId(), castNow, spell.durationSeconds());
        } else if (probabilitySuccess && timeTarget != null) {
            applied = hub.eraseMagicTimeAttackActor(currentRoomId, this,
                    timeTarget.objectId(), castNow, spell.durationSeconds());
        }

        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : questTarget != null
                    ? hub.battleRecipients(currentRoomId, questTarget.force())
                    : hub.roomMembers(currentRoomId);
        if (applied) {
            byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                if (invisible && member != this) continue;
                if (classicWorld
                        && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                positionX, positionY)
                        && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                targetX, targetY)) continue;
                member.sendEncrypted(action,
                        "S_ACTION " + (classicWorld ? "classic-world " : "")
                                + "Erase Magic caster=" + playerObjectId()
                                + " action=" + spell.actionId());
                member.sendEncrypted(effect,
                        "S_EFFECT " + (classicWorld ? "classic-world " : "")
                                + "Erase Magic target=" + request.targetObjectId()
                                + " gfx=" + spell.effectGfx());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Erase-Magic=" + remainingMp + "/" + playerMaxMp);
        if (!applied) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE Erase-Magic-failure="
                            + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale Erase Magic coordinates"
                    + " client=" + request.x() + "," + request.y()
                    + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL Erase Magic skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + request.targetObjectId()
                + " npc=" + npcId + " probability=" + probability
                + " roll=" + percentileRoll + " applied=" + applied
                + " counter-magic-bypass=" + spell.counterMagicBypass()
                + " earth-bind-or-boss-blocked=" + probabilityBlocked
                + " boss-target=" + bossTarget + " mr=" + targetMr
                + " magic-hit=" + totalMagicHit + " duration="
                + spell.durationSeconds() + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " icon=omitted-no-selected-LiTo-packetbox-receiver");
    }

    /** Exact retained skill145 object/coordinate path for controlled actors. */
    private void useReturnToNatureSpell(
            byte[] payload, BattleSpellCatalog.ReturnToNatureSpell spell,
            int probabilityRollFixture) throws IOException {
        if (probabilityRollFixture < 0 || probabilityRollFixture > 100) {
            throw new IllegalArgumentException(
                    "invalid Return to Nature roll fixture");
        }
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        boolean classicWorld = phase == Phase.WORLD;
        if (phase != Phase.BATTLE && !classicWorld) return;
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Return-to-Nature-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Return-to-Nature-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Return-to-Nature-Silence-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Return-to-Nature-Silence-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE Return-to-Nature-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL rejected unlearned Return to Nature"
                    + " player=" + playerName());
            return;
        }

        ClientSession targetOwner = null;
        BattleCompanion controlled = null;
        BattleCompanion.Snapshot target = null;
        List<ClientSession> owners = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomCombatants(currentRoomId);
        for (ClientSession owner : owners) {
            List<BattleCompanion.Snapshot> snapshots = classicWorld
                    ? owner.classicWorldCompanionSnapshots()
                    : owner.controlledCompanionSnapshots();
            BattleCompanion.Snapshot candidate = snapshots.stream()
                    .filter(snapshot -> snapshot.objectId()
                            == request.targetObjectId())
                    .findFirst().orElse(null);
            if (candidate == null) continue;
            targetOwner = owner;
            controlled = owner.ownedCompanion(candidate.objectId());
            target = candidate;
            break;
        }
        if (targetOwner == null || controlled == null || target == null
                || !target.active() || target.hp() <= 0) {
            System.out.println("[LiTo] C_USE_SPELL Return to Nature rejected"
                    + " unresolved/inactive target=" + request.targetObjectId()
                    + " phase=" + phase);
            return;
        }

        int targetX = target.x();
        int targetY = target.y();
        boolean targetGate;
        if (classicWorld) {
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(classicWorldMapId);
            targetGate = targetOwner.phase == Phase.WORLD
                    && sameClassicWorldMap(targetOwner)
                    && !map.isSafetyZone(positionX, positionY)
                    && !map.isSafetyZone(targetX, targetY)
                    && map.hasLineOfSight(
                            positionX, positionY, targetX, targetY);
        } else {
            int casterMap = hub.battleMapId(currentRoomId, this);
            targetGate = targetOwner.phase == Phase.BATTLE
                    && targetOwner.currentRoomId == currentRoomId
                    && hub.battleMapId(currentRoomId, targetOwner) == casterMap
                    && BattleSpellCatalog.hasNativeLineOfSight(
                            ArenaMapCatalog.forMap(casterMap),
                            positionX, positionY, targetX, targetY);
        }
        if (!targetGate || !BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL Return to Nature rejected"
                    + " gate/screen target=" + target.objectId()
                    + " phase=" + phase);
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Return to Nature rejected"
                    + " unavailable action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        boolean releasable = target.kind() == BattleCompanion.Kind.SUMMON
                || target.kind() == BattleCompanion.Kind.TAMED;
        SourceNpcPhysicalStats npcStats = null;
        int probability = 0;
        int percentileRoll = 0;
        boolean bossTarget = false;
        int targetMr = 0;
        int totalMagicHit = 0;
        if (releasable) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(target.npcId());
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected Return to Nature; source NPC"
                        + " lookup failed player=" + playerName() + " npc="
                        + target.npcId() + " reason=" + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) {
                System.out.println("[LiTo] rejected Return to Nature; source NPC"
                        + " row missing player=" + playerName()
                        + " npc=" + target.npcId());
                return;
            }
            CharacterSummary caster = selectedCharacterSummary();
            SourceEquipmentMagicStats casterEquipment =
                    requiredEquipmentMagicStats();
            int casterType = caster == null ? 0 : caster.type();
            int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
            CharacterSummary ownerCharacter = targetOwner.selectedCharacterSummary();
            int ownerLevel = ownerCharacter == null
                    ? 1 : Math.max(1, ownerCharacter.level());
            int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                    baseIntelligence());
            int magicLevel = spell.includeMagicLevel()
                    ? BattleTurnUndead.magicLevel(casterType, casterLevel) : 0;
            totalMagicHit = Math.addExact(casterEquipment.totalMagicHit(),
                    dragonEyeStatus.snapshot(requestNow).magicHit());
            targetMr = npcStats.magicResistance();
            bossTarget = npcStats.boss();
            probability = spell.probability(
                    casterLevel, ownerLevel, effectiveIntelligence,
                    magicLevel, totalMagicHit, targetMr);
            percentileRoll = bossTarget ? 100 : probabilityRollFixture > 0
                    ? probabilityRollFixture
                    : ThreadLocalRandom.current().nextInt(1, 101);
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        RuntimeInventory previousInventory;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || observer
                    || playerHp <= 0
                    || (phase != Phase.BATTLE && phase != Phase.WORLD)) {
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE Return-to-Nature-insufficient-mp=278");
                }
                System.out.println("[LiTo] C_USE_SPELL Return to Nature rejected state"
                        + " target=" + request.targetObjectId() + " mp=" + playerMp
                        + " cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE Return-to-Nature-missing-reagent=299");
                System.out.println("[LiTo] C_USE_SPELL Return to Nature rejected"
                        + " missing reagent catalog=" + spell.itemConsumeId()
                        + " count=" + spell.itemConsumeCount());
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            previousInventory = inventory;
            inventory = nextInventory;
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (classicWorld && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, targetX, targetY)) {
                continue;
            }
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION Return to Nature caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Return-to-Nature="
                        + remainingMp + "/" + playerMaxMp);

        boolean invalidPetKind = !releasable;
        boolean probabilitySuccess = releasable && !bossTarget
                && probability >= percentileRoll;
        boolean released = probabilitySuccess
                && targetOwner.releaseCompanionToNature(
                        controlled, target, spell.effectGfx());
        if (invalidPetKind) {
            sendEncrypted(Protocol.messageCode(spell.invalidTargetMessage()),
                    "S_MESSAGE_CODE Return-to-Nature-invalid-pet="
                            + spell.invalidTargetMessage());
        } else if (!released) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE Return-to-Nature-failure="
                            + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale Return to Nature"
                    + " coordinates client=" + request.x() + "," + request.y()
                    + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL Return to Nature skill="
                + spell.skillId() + " caster=" + playerName() + " target="
                + target.objectId() + " owner=" + targetOwner.playerName()
                + " kind=" + target.kind() + " npc=" + target.npcId()
                + " probability=" + probability + " roll=" + percentileRoll
                + " boss-target=" + bossTarget + " released=" + released
                + " invalid-pet-kind=" + invalidPetKind + " mr=" + targetMr
                + " magic-hit=" + totalMagicHit + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    /** Owner-side atomic companion lifecycle transition for skill145. */
    private synchronized boolean releaseCompanionToNature(
            BattleCompanion controlled, BattleCompanion.Snapshot expected,
            int effectGfx) throws IOException {
        if (controlled == null || expected == null
                || ownedCompanion(expected.objectId()) != controlled) return false;
        BattleCompanion.Snapshot live = controlled.snapshot();
        if (!live.active() || live.objectId() != expected.objectId()
                || live.kind() != expected.kind()) return false;

        if (live.kind() == BattleCompanion.Kind.SUMMON) {
            transferCompanionItems(controlled);
            controlled.deactivate();
            synchronized (tamedCompanions) {
                tamedCompanions.removeIf(candidate ->
                        candidate.snapshot().objectId() == live.objectId());
            }
            if (phase == Phase.WORLD) {
                hub.transferClassicWorldMonsterTargets(
                        live.objectId(), playerObjectId());
            }
            publishReturnToNatureRemoval(live, effectGfx, "summon");
            return true;
        }
        if (live.kind() != BattleCompanion.Kind.TAMED) {
            return false;
        }

        ClassicWorldMonsterPopulation.Snapshot worldOrigin =
                controlled.classicWorldTamedOrigin();
        if (worldOrigin != null) {
            int originInstanceId = controlled.classicWorldTamedInstanceId();
            if (phase != Phase.WORLD || classicWorldMapId != worldOrigin.mapId()
                    || classicWorldInstanceId != originInstanceId) return false;
            ClassicWorldMonsterPopulation.TamedRelease worldReleased =
                    hub.releaseClassicWorldTamedMonster(
                            worldOrigin.mapId(), originInstanceId,
                            worldOrigin.objectId(), live);
            if (worldReleased == null) return false;
            transferCompanionItems(controlled);
            controlled.deactivate();
            synchronized (tamedCompanions) {
                tamedCompanions.removeIf(candidate ->
                        candidate.snapshot().objectId() == live.objectId());
            }
            hub.transferClassicWorldMonsterTargets(
                    live.objectId(), playerObjectId());
            byte[] effect = Protocol.effectObject(live.objectId(), effectGfx);
            byte[] remove = Protocol.removeObject(live.objectId());
            for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, live.x(), live.y())) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT Return-to-Nature tamed=" + live.objectId()
                                + " gfx=" + effectGfx + " phase=WORLD");
                member.sendEncrypted(remove,
                        "S_REMOVE_OBJECT Return-to-Nature tamed="
                                + live.objectId() + " phase=WORLD");
                member.sendClassicWorldMonster(
                        worldReleased.released(), "Return-to-Nature");
            }
            return true;
        }
        if (phase != Phase.BATTLE) return false;

        BattleQuestEncounter.Snapshot questReleased = null;
        BattleTimeAttackEncounter.Snapshot timeReleased = null;
        BattleQuestEncounter.Snapshot questOrigin = controlled.questTamedOrigin();
        BattleTimeAttackEncounter.Snapshot timeOrigin =
                controlled.timeAttackTamedOrigin();
        if (questOrigin != null) {
            questReleased = hub.releaseQuestTamedCompanion(
                    currentRoomId, this, questOrigin, live,
                    controlled.carriedItems());
        } else if (timeOrigin != null) {
            timeReleased = hub.releaseTimeAttackTamedCompanion(
                    currentRoomId, this, timeOrigin, live,
                    controlled.carriedItems());
        }
        if (questReleased == null && timeReleased == null) return false;

        controlled.clearCarriedItems();
        controlled.deactivate();
        synchronized (tamedCompanions) {
            tamedCompanions.removeIf(candidate ->
                    candidate.snapshot().objectId() == live.objectId());
        }
        List<ClientSession> recipients = questReleased != null
                ? hub.battleRecipients(currentRoomId, questReleased.force())
                : hub.roomMembers(currentRoomId);
        byte[] effect = Protocol.effectObject(live.objectId(), effectGfx);
        byte[] remove = Protocol.removeObject(live.objectId());
        for (ClientSession member : recipients) {
            member.sendEncrypted(effect,
                    "S_EFFECT Return-to-Nature tamed=" + live.objectId()
                            + " gfx=" + effectGfx);
            member.sendEncrypted(remove,
                    "S_REMOVE_OBJECT Return-to-Nature tamed=" + live.objectId());
            if (questReleased != null) {
                member.sendEncrypted(Protocol.questMonster(questReleased),
                        "S_PUT_OBJECT Return-to-Nature released-quest-monster="
                                + questReleased.objectId());
            } else {
                member.sendEncrypted(Protocol.timeAttackActor(timeReleased),
                        "S_PUT_OBJECT Return-to-Nature released-timeattack-actor="
                                + timeReleased.objectId());
            }
        }
        hub.armPveAi(currentRoomId);
        return true;
    }

    private void publishReturnToNatureRemoval(
            BattleCompanion.Snapshot target, int effectGfx, String source)
            throws IOException {
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        byte[] effect = Protocol.effectObject(target.objectId(), effectGfx);
        byte[] remove = Protocol.removeObject(target.objectId());
        for (ClientSession member : recipients) {
            if (phase == Phase.WORLD && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, target.x(), target.y())) {
                continue;
            }
            member.sendEncrypted(effect,
                    "S_EFFECT Return-to-Nature " + source + "="
                            + target.objectId() + " gfx=" + effectGfx);
            member.sendEncrypted(remove,
                    "S_REMOVE_OBJECT Return-to-Nature " + source + "="
                            + target.objectId());
        }
    }

    /** Exact selected/retained self-cast entry for skill134 Counter Mirror. */
    private void useCounterMirrorSpell(
            byte[] payload, BattleSpellCatalog.CounterMirrorSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        if (phase != Phase.BATTLE && phase != Phase.WORLD) return;
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Counter-Mirror-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Counter-Mirror-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Counter-Mirror-Silence-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Counter-Mirror-Silence-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE Counter-Mirror-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL rejected unlearned"
                    + " Counter Mirror player=" + playerName());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Counter Mirror rejected"
                    + " unavailable action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        RuntimeInventory previousInventory;
        RuntimeInventory nextInventory;
        int remainingMp;
        boolean refreshed;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || observer
                    || playerHp <= 0
                    || (phase != Phase.BATTLE && phase != Phase.WORLD)) {
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE Counter-Mirror-insufficient-mp=278");
                }
                System.out.println("[LiTo] C_USE_SPELL Counter Mirror rejected state"
                        + " player=" + playerName() + " mp=" + playerMp
                        + " cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow) + " phase=" + phase);
                return;
            }
            nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE Counter-Mirror-missing-reagent=299");
                System.out.println("[LiTo] C_USE_SPELL Counter Mirror rejected"
                        + " missing reagent catalog=" + spell.itemConsumeId()
                        + " count=" + spell.itemConsumeCount());
                return;
            }
            refreshed = counterMirrorStatus.active(castNow);
            cancelMeditation("spell-" + spell.skillId());
            counterMirrorStatus.activate(castNow, spell.durationSeconds());
            previousInventory = inventory;
            inventory = nextInventory;
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        byte[] action = Protocol.objectAction(
                playerObjectId(), spell.actionId());
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (phase == Phase.WORLD && (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY,
                            member.positionX, member.positionY))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION Counter-Mirror caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
        }
        // Retained L1SkillUse sends the activation S_SkillSound only to the
        // caster for Counter Magic, Counter Barrier and Counter Mirror.
        sendEncrypted(Protocol.effectObject(
                        playerObjectId(), spell.effectGfx()),
                "S_EFFECT Counter-Mirror owner-only target="
                        + playerObjectId() + " gfx=" + spell.effectGfx());
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Counter-Mirror="
                        + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Counter Mirror caster="
                + playerName() + " selector=" + request.row() + "/"
                + request.column() + " duration=" + spell.durationSeconds()
                + " refreshed=" + refreshed + " wisdom="
                + (caster == null ? 0 : caster.wisdom())
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/"
                + playerMaxMp + " reagent=" + spell.itemConsumeId() + "x"
                + spell.itemConsumeCount() + " phase=" + phase
                + " icon=omitted-no-selected-LiTo-packetbox-receiver");
    }

