    private List<ClassicWorldMonsterPopulation.Snapshot>
            classicCastleTrebuchetsInScreen(
                    String source, int mapId, int x, int y) {
        List<ClassicWorldMonsterPopulation.Snapshot> result = new ArrayList<>();
        for (ClassicWorldCastleWarField.WarObject object
                : hub.classicCastleWarObjectsInScreen(source, mapId, x, y)) {
            if (object.kind() != ClassicWorldCastleWarField.Kind.TREBUCHET
                    || object.currentHp() <= 0) continue;
            ClassicWorldMonsterPopulation.Snapshot snapshot =
                    hub.classicCastleTrebuchetCombatSnapshot(
                            source, mapId, object.objectId());
            if (snapshot != null && snapshot.present() && snapshot.alive()
                    && snapshot.mapId() == mapId) {
                result.add(snapshot);
            }
        }
        return List.copyOf(result);
    }

    /**
     * Rebuilds every live retained {@code L1TowerInstance} in native screen
     * from the authoritative castle-war field.  Towers deliberately remain a
     * distinct receiver: they own no monster hate, reward or timed-status
     * state, but attack magic still commits through their native damage
     * lifecycle.
     */
    private List<ClassicWorldMonsterPopulation.Snapshot>
            classicCastleTowersInScreen(
                    String source, int mapId, int x, int y) {
        List<ClassicWorldMonsterPopulation.Snapshot> result = new ArrayList<>();
        for (ClassicWorldCastleWarField.WarObject object
                : hub.classicCastleWarObjectsInScreen(source, mapId, x, y)) {
            if (object.kind() != ClassicWorldCastleWarField.Kind.TOWER
                    || object.currentHp() <= 0) continue;
            ClassicWorldMonsterPopulation.Snapshot snapshot =
                    hub.classicCastleTowerCombatSnapshot(
                            source, mapId, object.objectId());
            if (snapshot != null && snapshot.present() && snapshot.alive()
                    && snapshot.mapId() == mapId) {
                result.add(snapshot);
            }
        }
        return List.copyOf(result);
    }

    private ClassicWorldMonsterPopulation.Snapshot currentClassicCastleTower(
            ClassicWorldMonsterPopulation.Snapshot target) {
        if (target == null) return null;
        ClassicWorldMonsterPopulation.Snapshot current =
                hub.classicCastleTowerCombatSnapshot(
                        selectedClassicServerName, target.mapId(),
                        target.objectId());
        return current == null || !current.present() || !current.alive()
                ? null : current;
    }

    /** Exact retained L1TowerInstance.receiveDamage authorization/lifecycle. */
    private int applyClassicWorldCastleTowerMagicDamage(
            ClassicWorldMonsterPopulation.Snapshot target, int damage)
            throws IOException {
        if (target == null || damage <= 0) return 0;
        ClassicWorldCastleWarField.WarObject objective =
                hub.classicCastleWarObject(
                        selectedClassicServerName, target.mapId(),
                        target.objectId());
        if (objective == null
                || objective.kind() != ClassicWorldCastleWarField.Kind.TOWER
                || objective.currentHp() <= 0) return 0;
        CastleSummary defender;
        try {
            defender = effectiveClassicCastleById(objective.castleId());
        } catch (Exception error) {
            throw new IOException("castle defender lookup failed", error);
        }
        String attackerClan = hub.clanData(sourceCharacterIdentity()).name();
        ClassicWorldCastleWarField.TowerHit hit =
                hub.damageClassicCastleTower(
                        selectedClassicServerName, target.mapId(),
                        target.objectId(), attackerClan,
                        defender == null ? "" : defender.clanName(), damage);
        if (hit != null && hit.appliedDamage() > 0) {
            publishClassicCastleTowerHit(hit);
        }
        return hit == null ? 0 : hit.appliedDamage();
    }

    /**
     * Rebuilds every destructible retained {@code L1DoorInstance} as a magic
     * target from the authoritative door state.  The combat proxy places the
     * actor on the nearest retained entrance edge, matching the direct-spell
     * and physical routes without allowing a cast through a closed gate.
     */
    private List<ClassicWorldAreaCastleDoorTarget>
            classicCastleDoorMagicTargets(
                    int mapId, int casterX, int casterY) {
        Map<Long, ClassicWorldAreaCastleDoorTarget> result =
                new LinkedHashMap<>();
        for (ClassicWorldDwarfCastleDoorState.Snapshot door
                : hub.dwarfCastleDoors()) {
            if (door.definition().mapId() != mapId) continue;
            ClassicWorldMonsterPopulation.Snapshot combat =
                    hub.dwarfCastleDoorCombatSnapshot(
                            mapId, door.definition().objectId(),
                            casterX, casterY);
            if (combat != null) {
                result.put(combat.objectId(),
                        new ClassicWorldAreaCastleDoorTarget(
                                combat, true, null));
            }
        }
        for (ClassicWorldCastleDoorCombat.View door
                : hub.mainlandCastleDoors()) {
            if (door.definition().mapId() != mapId) continue;
            ClassicWorldCastleDoorCombat.Target target =
                    hub.mainlandCastleDoorCombatTarget(
                            mapId, door.definition().objectId(),
                            casterX, casterY);
            if (target != null) {
                result.put(target.combat().objectId(),
                        new ClassicWorldAreaCastleDoorTarget(
                                target.combat(), false,
                                target.view().definition().family()));
            }
        }
        for (ClassicWorldHeineCastleDoorState.Snapshot door
                : hub.heineCastleDoors()) {
            if (door.definition().mapId() != mapId) continue;
            ClassicWorldCastleDoorCombat.Target target =
                    hub.mainlandCastleDoorCombatTarget(
                            mapId, door.definition().objectId(),
                            casterX, casterY);
            if (target != null) {
                result.put(target.combat().objectId(),
                        new ClassicWorldAreaCastleDoorTarget(
                                target.combat(), false,
                                target.view().definition().family()));
            }
        }
        return List.copyOf(result.values());
    }

    private void applyClassicWorldAreaCastleDoorDamage(
            ClassicWorldAreaCastleDoorTarget target, int damage)
            throws IOException {
        if (target == null || damage <= 0) return;
        if (target.dwarf()) {
            ClassicWorldDwarfCastleDoorState.DoorHit hit =
                    hub.damageDwarfCastleDoor(
                            target.combat().mapId(),
                            target.combat().objectId(), damage);
            if (hit != null && hit.appliedDamage() > 0) {
                publishDwarfCastleDoorHit(hit);
            }
            return;
        }
        ClassicWorldCastleDoorCombat.Hit hit =
                hub.damageMainlandCastleDoor(
                        target.family(), target.combat().mapId(),
                        target.combat().objectId(), damage);
        if (hit != null && hit.appliedDamage() > 0) {
            publishMainlandCastleDoorHit(hit);
        }
    }

    private ClassicWorldAreaCastleDoorTarget
            currentClassicWorldAreaCastleDoorTarget(
                    ClassicWorldAreaCastleDoorTarget target,
                    int casterX, int casterY) {
        if (target == null) return null;
        if (target.dwarf()) {
            ClassicWorldMonsterPopulation.Snapshot combat =
                    hub.dwarfCastleDoorCombatSnapshot(
                            target.combat().mapId(),
                            target.combat().objectId(), casterX, casterY);
            return combat == null ? null
                    : new ClassicWorldAreaCastleDoorTarget(
                            combat, true, null);
        }
        ClassicWorldCastleDoorCombat.Target current =
                hub.mainlandCastleDoorCombatTarget(
                        target.combat().mapId(), target.combat().objectId(),
                        casterX, casterY);
        return current == null ? null
                : new ClassicWorldAreaCastleDoorTarget(
                        current.combat(), false,
                        current.view().definition().family());
    }

    /**
     * Retained selector-only, caster-centred area attack for ordinary WORLD.
     * The selected client sends no actor tail for range-zero spells, so every
     * target and coordinate is rebuilt from the authoritative map instance.
     */
    private void useClassicWorldCenteredAreaAttackSpell(
            byte[] payload, BattleSpellCatalog.AreaAttackSpell spell)
            throws IOException {
        Protocol.SpellSelector request =
                Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || spell.maximumRange() != 0
                || spell.areaRadius() <= 0
                || spell.requestShape()
                    != BattleSpellCatalog.RequestShape.SELECTOR_ONLY) return;
        if (!admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(),
                "centered-area-" + spell.key())) return;

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        int originHeading = playerHeading & 7;
        int radius = spell.areaRadius();
        long requestNow = System.nanoTime();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        List<ClientSession> worldMembers = classicWorldMembers(originMapId);

        List<ClientSession> playerTargets = worldMembers.stream()
                .filter(candidate -> candidate != this
                        && candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId
                        && candidate.playerHp > 0 && !candidate.observer
                        && !candidate.invisible
                        && map.isNormalZone(originX, originY)
                        && map.isNormalZone(
                                candidate.positionX, candidate.positionY)
                        && targetRange(originX, originY,
                                candidate.positionX, candidate.positionY)
                            <= radius
                        && BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.positionX, candidate.positionY)
                        && map.attackPosition(originX, originY,
                                candidate.positionX, candidate.positionY,
                                radius * 2)
                        && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                                candidate.timedStatus
                                    .absoluteBarrierActive(requestNow),
                                spell.skillId()))
                .toList();

        List<ClassicWorldAreaCompanionTarget> companionTargets =
                new ArrayList<>();
        List<ClassicWorldMonsterPopulation.Snapshot> monsterTargets =
                new ArrayList<>();
        List<ClassicWorldMonsterPopulation.Snapshot> trebuchetTargets =
                new ArrayList<>();
        List<ClassicWorldMonsterPopulation.Snapshot> castleTowerTargets =
                new ArrayList<>();
        List<ClassicWorldAreaCastleDoorTarget> castleDoorTargets =
                new ArrayList<>();
        Map<Long, SourceNpcPhysicalStats> monsterStats =
                new LinkedHashMap<>();
        try {
            if (map.isNormalZone(originX, originY)) {
                for (ClientSession owner : worldMembers) {
                    if (owner == this || owner.phase != Phase.WORLD
                            || owner.classicWorldMapId != originMapId
                            || owner.classicWorldInstanceId
                                != originInstanceId) continue;
                    for (BattleCompanion.Snapshot snapshot
                            : owner.classicWorldCompanionSnapshots()) {
                        if (!snapshot.kind().classicWorldEligible()
                                || !snapshot.active() || snapshot.hp() <= 0
                                || !map.isNormalZone(snapshot.x(), snapshot.y())
                                || targetRange(originX, originY,
                                        snapshot.x(), snapshot.y()) > radius
                                || !BattleSpellCatalog.isInNativeScreen(
                                        originX, originY,
                                        snapshot.x(), snapshot.y())
                                || !map.attackPosition(originX, originY,
                                        snapshot.x(), snapshot.y(),
                                        radius * 2)) continue;
                        BattleCompanion controlled =
                                owner.ownedCompanion(snapshot.objectId());
                        if (controlled == null) continue;
                        SourceNpcPhysicalStats stats = selectedSourceAccounts()
                                .npcPhysicalStats(snapshot.npcId());
                        if (stats == null) {
                            System.out.println("[LiTo] rejected classic-world"
                                    + " centered-area; companion source row"
                                    + " missing player=" + playerName()
                                    + " npc=" + snapshot.npcId());
                            return;
                        }
                        companionTargets.add(new ClassicWorldAreaCompanionTarget(
                                owner, controlled, snapshot, stats));
                    }
                }
            }
            for (ClassicWorldMonsterPopulation.Snapshot candidate
                    : hub.classicWorldMonstersInScreen(
                            originMapId, originInstanceId, originX, originY)) {
                if (!candidate.present() || !candidate.alive()
                        || candidate.mapId() != originMapId
                        || targetRange(originX, originY,
                                candidate.x(), candidate.y()) > radius
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.x(), candidate.y())
                        || !map.attackPosition(originX, originY,
                                candidate.x(), candidate.y(),
                                radius * 2)) continue;
                SourceNpcPhysicalStats stats = selectedSourceAccounts()
                        .npcPhysicalStats(candidate.npcId());
                if (stats == null) {
                    System.out.println("[LiTo] rejected classic-world"
                            + " centered-area; monster source row missing"
                            + " player=" + playerName() + " npc="
                            + candidate.npcId());
                    return;
                }
                monsterTargets.add(candidate);
                monsterStats.put(candidate.objectId(), stats);
            }
            for (ClassicWorldMonsterPopulation.Snapshot candidate
                    : classicCastleTrebuchetsInScreen(
                            selectedClassicServerName, originMapId,
                            originX, originY)) {
                if (targetRange(originX, originY,
                            candidate.x(), candidate.y()) > radius
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.x(), candidate.y())
                        || !map.attackPosition(originX, originY,
                                candidate.x(), candidate.y(), radius * 2)) {
                    continue;
                }
                SourceNpcPhysicalStats stats = selectedSourceAccounts()
                        .npcPhysicalStats(candidate.npcId());
                if (stats == null) {
                    System.out.println("[LiTo] rejected classic-world"
                            + " centered-area; trebuchet source row missing"
                            + " player=" + playerName() + " npc="
                            + candidate.npcId());
                    return;
                }
                trebuchetTargets.add(candidate);
                monsterStats.put(candidate.objectId(), stats);
            }
            for (ClassicWorldMonsterPopulation.Snapshot candidate
                    : classicCastleTowersInScreen(
                            selectedClassicServerName, originMapId,
                            originX, originY)) {
                if (targetRange(originX, originY,
                            candidate.x(), candidate.y()) > radius
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.x(), candidate.y())
                        || !map.attackPosition(originX, originY,
                                candidate.x(), candidate.y(), radius * 2)) {
                    continue;
                }
                SourceNpcPhysicalStats stats = selectedSourceAccounts()
                        .npcPhysicalStats(candidate.npcId());
                if (stats == null) {
                    System.out.println("[LiTo] rejected classic-world"
                            + " centered-area; castle tower source row missing"
                            + " player=" + playerName() + " npc="
                            + candidate.npcId());
                    return;
                }
                castleTowerTargets.add(candidate);
                monsterStats.put(candidate.objectId(), stats);
            }
            for (ClassicWorldAreaCastleDoorTarget candidate
                    : classicCastleDoorMagicTargets(
                            originMapId, originX, originY)) {
                ClassicWorldMonsterPopulation.Snapshot combat =
                        candidate.combat();
                if (targetRange(originX, originY,
                            combat.x(), combat.y()) > radius
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY, combat.x(), combat.y())
                        || !map.attackPosition(originX, originY,
                                combat.x(), combat.y(), radius * 2)) {
                    continue;
                }
                SourceNpcPhysicalStats stats = selectedSourceAccounts()
                        .npcPhysicalStats(
                                ClassicWorldCastleDoorCombat.NPC_TEMPLATE_ID);
                if (stats == null) {
                    System.out.println("[LiTo] rejected classic-world"
                            + " centered-area; castle door source row missing"
                            + " player=" + playerName() + " npc="
                            + ClassicWorldCastleDoorCombat.NPC_TEMPLATE_ID);
                    return;
                }
                castleDoorTargets.add(candidate);
                monsterStats.put(combat.objectId(), stats);
            }
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] rejected classic-world centered-area;"
                    + " source NPC lookup failed player=" + playerName()
                    + " skill=" + spell.skillId() + " reason="
                    + sourceFailure.getMessage());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment =
                requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = casterEquipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);

        int remainingHp;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || phase != Phase.WORLD || observer
                    || classicWorldMapId != originMapId
                    || classicWorldInstanceId != originInstanceId
                    || positionX != originX || positionY != originY
                    || playerHp <= spell.hpCost() || playerMp < mpCost
                    || !centeredAreaCasterStillAdmitted(
                            Phase.WORLD, spell.skillId(),
                            spell.actionId(), castNow)) {
                if (playerHp <= spell.hpCost()) {
                    sendEncrypted(Protocol.messageCode(279),
                            "S_MESSAGE_CODE classic-world-centered-area"
                                    + "-insufficient-hp=279 skill="
                                    + spell.skillId());
                } else if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE classic-world-centered-area"
                                    + "-insufficient-mp=278 skill="
                                    + spell.skillId());
                }
                System.out.println("[LiTo] C_USE_SPELL classic-world"
                        + " centered-area rejected state skill="
                        + spell.skillId() + " hp=" + playerHp + " hp-cost="
                        + spell.hpCost() + " mp=" + playerMp + " mp-cost="
                        + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            playerHp -= spell.hpCost();
            playerMp -= mpCost;
            remainingHp = playerHp;
            remainingMp = playerMp;
            spellReadyNanos.put(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelMeditation("classic-world-spell-" + spell.skillId());
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());

        Map<ClientSession, Integer> playerDamages = new LinkedHashMap<>();
        Map<ClientSession, BattleEraseMagicStatus.Lease> playerEraseLeases =
                new LinkedHashMap<>();
        Map<ClassicWorldAreaCompanionTarget, Integer> companionDamages =
                new LinkedHashMap<>();
        Map<ClassicWorldAreaCompanionTarget, BattleEraseMagicStatus.Lease>
                companionEraseLeases = new LinkedHashMap<>();
        Map<Long, Integer> monsterDamages = new LinkedHashMap<>();
        Map<Long, BattleEraseMagicStatus.Lease> monsterEraseLeases =
                new LinkedHashMap<>();
        Map<Long, Integer> trebuchetDamages = new LinkedHashMap<>();
        Map<Long, Integer> castleTowerDamages = new LinkedHashMap<>();
        Map<ClassicWorldAreaCastleDoorTarget, Integer> castleDoorDamages =
                new LinkedHashMap<>();
        List<ClientSession> counteredTargets = new ArrayList<>();
        List<Protocol.AttackManyTarget> wireTargets = new ArrayList<>();
        int counterMirrorTriggers = 0;

        for (ClientSession target : playerTargets) {
            if (!sameClassicWorldMap(target) || target.playerHp <= 0
                    || target.observer || target.invisible
                    || !map.isNormalZone(originX, originY)
                    || !map.isNormalZone(target.positionX, target.positionY)
                    || targetRange(originX, originY,
                            target.positionX, target.positionY) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY,
                            target.positionX, target.positionY)
                    || !map.attackPosition(originX, originY,
                            target.positionX, target.positionY,
                            radius * 2)
                    || BattleAbsoluteBarrierRules.blocksIncomingSpell(
                            target.timedStatus.absoluteBarrierActive(castNow),
                            spell.skillId())) continue;
            if (target.timedStatus.consumeCounterMagic(castNow)) {
                counteredTargets.add(target);
                continue;
            }
            BattleEraseMagicStatus.Lease eraseLease =
                    target.eraseMagicStatus.capture(castNow);
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell),
                    target.effectiveSpellElementalResistance(spell.attribute()),
                    target.effectiveBaseMagicResistance(castNow),
                    target.effectiveArmorMagicReductionBase(),
                    "classic-world-player=" + target.playerName());
            damage = target.combatDamageAfterCooking(
                    damage, "classic-world-centered-area-" + spell.skillId());
            damage = target.earthBindProtectedCombatDamage(
                    damage, "classic-world-centered-area-" + spell.skillId());
            BattleCounterMirrorStatus.Decision mirror =
                    target.counterMirrorDecision(
                            damage, true,
                            ThreadLocalRandom.current().nextInt(100), castNow);
            if (mirror.triggered()) {
                publishPlayerCounterMirrorTrigger(
                        target, mirror,
                        "classic-world-centered-area-" + spell.skillId());
                damage = 0;
                counterMirrorTriggers++;
            }
            playerDamages.put(target, damage);
            playerEraseLeases.put(target, eraseLease);
            wireTargets.add(new Protocol.AttackManyTarget(
                    target.playerObjectId(), damage > 0));
        }

        for (ClassicWorldAreaCompanionTarget target : companionTargets) {
            BattleCompanion.Snapshot current = target.controlled().snapshot();
            if (!sameClassicWorldMap(target.owner())
                    || current.objectId() != target.snapshot().objectId()
                    || !current.kind().classicWorldEligible()
                    || !current.active() || current.hp() <= 0
                    || !map.isNormalZone(originX, originY)
                    || !map.isNormalZone(current.x(), current.y())
                    || targetRange(originX, originY,
                            current.x(), current.y()) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, current.x(), current.y())
                    || !map.attackPosition(originX, originY,
                            current.x(), current.y(), radius * 2)) continue;
            BattleEraseMagicStatus.Lease eraseLease =
                    target.controlled().captureEraseMagic(castNow);
            int targetMr = target.controlled().effectiveMagicResistance(
                    target.stats().magicResistance(), castNow);
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    targetMr, 0,
                    "classic-world-companion=" + current.objectId());
            if (!classicWorldCkewAttackAllowed(current.npcId(), castNow)) {
                damage = 0;
            }
            companionDamages.put(target, damage);
            companionEraseLeases.put(target, eraseLease);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldMonsterPopulation.Snapshot target : monsterTargets) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    hub.classicWorldMonster(
                            originMapId, originInstanceId, target.objectId());
            if (current == null || !current.present() || !current.alive()
                    || targetRange(originX, originY,
                            current.x(), current.y()) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, current.x(), current.y())
                    || !map.attackPosition(originX, originY,
                            current.x(), current.y(), radius * 2)) continue;
            SourceNpcPhysicalStats stats = monsterStats.get(current.objectId());
            if (stats == null) continue;
            BattleEraseMagicStatus.Lease eraseLease =
                    hub.captureClassicWorldMonsterEraseMagic(
                            originMapId, originInstanceId,
                            current.objectId(), castNow);
            int targetMr = hub.classicWorldMonsterEffectiveMagicResistance(
                    originMapId, originInstanceId, current.objectId(),
                    stats.magicResistance(), castNow);
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell),
                    hub.classicWorldMonsterElementalFallDownModifier(
                            originMapId, originInstanceId, current.objectId(),
                            spell.attribute(), castNow),
                    targetMr, 0,
                    "classic-world-monster=" + current.objectId());
            if (!classicWorldCkewAttackAllowed(current.npcId(), castNow)) {
                damage = 0;
            }
            monsterDamages.put(current.objectId(), damage);
            monsterEraseLeases.put(current.objectId(), eraseLease);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldMonsterPopulation.Snapshot target : trebuchetTargets) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    hub.classicCastleTrebuchetCombatSnapshot(
                            selectedClassicServerName, originMapId,
                            target.objectId());
            if (current == null || !current.present() || !current.alive()
                    || targetRange(originX, originY,
                            current.x(), current.y()) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, current.x(), current.y())
                    || !map.attackPosition(originX, originY,
                            current.x(), current.y(), radius * 2)) continue;
            SourceNpcPhysicalStats stats = monsterStats.get(current.objectId());
            if (stats == null) continue;
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    stats.magicResistance(), 0,
                    "classic-world-castle-trebuchet=" + current.objectId());
            trebuchetDamages.put(current.objectId(), damage);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldMonsterPopulation.Snapshot target
                : castleTowerTargets) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    currentClassicCastleTower(target);
            if (current == null || targetRange(originX, originY,
                        current.x(), current.y()) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, current.x(), current.y())
                    || !map.attackPosition(originX, originY,
                            current.x(), current.y(), radius * 2)) continue;
            SourceNpcPhysicalStats stats = monsterStats.get(current.objectId());
            if (stats == null) continue;
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    stats.magicResistance(), 0,
                    "classic-world-castle-tower=" + current.objectId());
            castleTowerDamages.put(current.objectId(), damage);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldAreaCastleDoorTarget target : castleDoorTargets) {
            ClassicWorldAreaCastleDoorTarget current =
                    currentClassicWorldAreaCastleDoorTarget(
                            target, originX, originY);
            if (current == null || targetRange(originX, originY,
                        current.combat().x(), current.combat().y()) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY,
                            current.combat().x(), current.combat().y())
                    || !map.attackPosition(originX, originY,
                            current.combat().x(), current.combat().y(),
                            radius * 2)) {
                continue;
            }
            SourceNpcPhysicalStats stats =
                    monsterStats.get(current.combat().objectId());
            if (stats == null) continue;
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    stats.magicResistance(), 0,
                    "classic-world-castle-door="
                            + current.combat().objectId());
            castleDoorDamages.put(current, damage);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.combat().objectId(), damage > 0));
        }

        for (ClientSession target : counteredTargets) {
            publishCounterMagicConsumption(target, spell.skillId());
        }
        long sequence = ATTACK_SPELL_SEQUENCE.incrementAndGet();
        if (wireTargets.isEmpty()) {
            byte[] action = Protocol.objectAction(
                    playerObjectId(), spell.actionId());
            for (ClientSession member : worldMembers) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY)
                        || invisible && member != this) continue;
                member.sendEncrypted(action,
                        "S_ACTION classic-world centered-area-empty caster="
                                + playerObjectId() + " skill="
                                + spell.skillId());
            }
        } else {
            byte[] attack = Protocol.attackMany(
                    spell.actionId(), playerObjectId(), originX, originY,
                    originHeading, sequence, spell.effectGfx(), 0,
                    wireTargets);
            publishClassicWorldAreaAttackSpellPacket(
                    attack, originX, originY,
                    "centered=" + spell.skillId() + " key=" + spell.key()
                            + " targets=" + wireTargets.size()
                            + " gfx=" + spell.effectGfx()
                            + " type=0 sequence=" + sequence
                            + " countered=" + counteredTargets.size()
                            + " counter-mirror-triggered="
                            + counterMirrorTriggers);
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world centered-area="
                        + remainingMp + "/" + playerMaxMp);
        if (spell.hpCost() != 0) {
            sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                            .h(remainingHp).h(playerMaxHp).bytes(),
                    "S_HIT_POINT classic-world centered-area-hp-cost="
                            + remainingHp + "/" + playerMaxHp);
            broadcastOwnHitRatio("classic-world-centered-area-hp-cost");
        }
        applySpellLawfulDelta(spell.lawfulDelta(), spell.key());

        for (Map.Entry<ClientSession, Integer> entry
                : playerDamages.entrySet()) {
            if (entry.getValue() > 0) {
                entry.getKey().takeClassicWorldPlayerDamage(
                        entry.getValue(), this, false);
            }
            entry.getKey().eraseMagicStatus.consume(
                    playerEraseLeases.get(entry.getKey()));
        }
        for (Map.Entry<ClassicWorldAreaCompanionTarget, Integer> entry
                : companionDamages.entrySet()) {
            ClassicWorldAreaCompanionTarget target = entry.getKey();
            target.controlled().consumeEraseMagic(
                    companionEraseLeases.get(target));
            if (entry.getValue() > 0) {
                target.controlled().selectMasterTarget(playerObjectId());
                target.owner().applyClassicWorldMonsterCompanionDamage(
                        target.controlled(), target.snapshot(), entry.getValue(),
                        playerObjectId(),
                        "centered-area-spell-" + spell.skillId());
            }
        }
        for (Map.Entry<Long, Integer> entry : monsterDamages.entrySet()) {
            ClassicWorldMonsterPopulation.Hit transition = null;
            if (entry.getValue() > 0) {
                transition = hub.damageClassicWorldMonster(
                        originMapId, originInstanceId, entry.getKey(),
                        playerObjectId(), entry.getValue());
            }
            hub.consumeClassicWorldMonsterEraseMagic(
                    originMapId, originInstanceId, entry.getKey(),
                    monsterEraseLeases.get(entry.getKey()));
            if (transition == null) continue;
            hub.provokeClassicWorldMonster(
                    originMapId, originInstanceId,
                    entry.getKey(), playerObjectId());
            for (BattleCompanion.Snapshot companion
                    : classicWorldCompanionSnapshots()) {
                BattleCompanion controlled =
                        ownedCompanion(companion.objectId());
                if (controlled != null) {
                    controlled.selectMasterTarget(entry.getKey());
                }
            }
            publishClassicWorldSpellMonsterDamage(
                    spell.skillId(), transition);
        }
        for (Map.Entry<Long, Integer> entry : trebuchetDamages.entrySet()) {
            if (entry.getValue() <= 0) continue;
            ClassicWorldCastleWarField.TrebuchetHit hit =
                    hub.damageClassicCastleTrebuchet(
                            selectedClassicServerName, originMapId,
                            entry.getKey(), entry.getValue());
            if (hit == null || hit.appliedDamage() <= 0) continue;
            publishClassicCastleTrebuchetHit(hit);
            if (hit.diedNow()) {
                hub.scheduleClassicCastleTrebuchetCorpseRemoval(
                        selectedClassicServerName, hit.after());
            }
        }
        for (Map.Entry<Long, Integer> entry
                : castleTowerDamages.entrySet()) {
            if (entry.getValue() <= 0) continue;
            ClassicWorldMonsterPopulation.Snapshot target =
                    hub.classicCastleTowerCombatSnapshot(
                            selectedClassicServerName, originMapId,
                            entry.getKey());
            applyClassicWorldCastleTowerMagicDamage(
                    target, entry.getValue());
        }
        for (Map.Entry<ClassicWorldAreaCastleDoorTarget, Integer> entry
                : castleDoorDamages.entrySet()) {
            applyClassicWorldAreaCastleDoorDamage(
                    entry.getKey(), entry.getValue());
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world centered-area skill="
                + spell.skillId() + " key=" + spell.key() + " caster="
                + playerName() + " radius=" + radius + " players="
                + playerDamages.size() + " companions="
                + companionDamages.size() + " monsters="
                + monsterDamages.size() + " trebuchets="
                + trebuchetDamages.size() + " castle-towers="
                + castleTowerDamages.size() + " castle-doors="
                + castleDoorDamages.size() + " wire-targets="
                + wireTargets.size() + " countered="
                + counteredTargets.size() + " counter-mirror-triggered="
                + counterMirrorTriggers + " effective-int="
                + effectiveIntelligence + " mp-cost=" + mpCost
                + " hp-cost=" + spell.hpCost() + " hp=" + remainingHp
                + "/" + playerMaxHp + " lawful-delta="
                + spell.lawfulDelta() + " mp=" + remainingMp + "/"
                + playerMaxMp);
    }

    /**
     * Retained target-centred WORLD area attack.  The client supplies a stale
     * coordinate snapshot, but L1SkillUse rebuilds the area from the current
     * primary actor and World.getVisibleObjects(primary, area).  Keep the
     * primary first, independently resolve every admitted target and remove a
     * warded PC from S_ATTACK_MANY exactly like the retained TargetList path.
     */
    private void useClassicWorldAreaAttackSpell(
            byte[] payload, BattleSpellCatalog.AreaAttackSpell spell)
            throws IOException {
        useClassicWorldAreaAttackSpell(
                Protocol.attackSpellRequest(payload), spell);
    }

    private void useClassicWorldAreaAttackSpell(
            Protocol.AttackSpellRequest request,
            BattleSpellCatalog.AreaAttackSpell spell) throws IOException {
        if (request.skillId() != spell.skillId()) return;
        if (!admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(),
                "area-attack-" + spell.key())) return;

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        List<ClientSession> worldMembers = classicWorldMembers(originMapId);
        ClientSession primaryPlayer = worldMembers.stream()
                .filter(candidate -> candidate != this
                        && candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId
                        && candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        ClassicWorldMonsterMagicTarget primaryCompanion = null;
        for (ClientSession owner : worldMembers) {
            if (owner == this || owner.phase != Phase.WORLD
                    || owner.classicWorldMapId != originMapId
                    || owner.classicWorldInstanceId != originInstanceId) continue;
            BattleCompanion.Snapshot snapshot = owner
                    .classicWorldCompanionSnapshots().stream()
                    .filter(candidate -> candidate.objectId()
                            == request.targetObjectId())
                    .findFirst().orElse(null);
            if (snapshot == null) continue;
            BattleCompanion controlled = owner.ownedCompanion(
                    snapshot.objectId());
            if (controlled != null) {
                primaryCompanion = new ClassicWorldMonsterMagicTarget(
                        owner, snapshot.objectId(), snapshot.x(), snapshot.y(),
                        controlled, snapshot);
            }
            break;
        }
        ClassicWorldMonsterPopulation.Snapshot ordinaryPrimaryMonster =
                hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId());
        boolean validOrdinaryPrimary = ordinaryPrimaryMonster != null
                && ordinaryPrimaryMonster.present()
                && ordinaryPrimaryMonster.alive()
                && ordinaryPrimaryMonster.mapId() == originMapId;
        ClassicWorldMonsterPopulation.Snapshot primaryTrebuchet =
                validOrdinaryPrimary ? null
                    : hub.classicCastleTrebuchetCombatSnapshot(
                            selectedClassicServerName, originMapId,
                            request.targetObjectId());
        boolean validPrimaryTrebuchet = primaryTrebuchet != null
                && primaryTrebuchet.present() && primaryTrebuchet.alive()
                && primaryTrebuchet.mapId() == originMapId;
        ClassicWorldMonsterPopulation.Snapshot primaryCastleTower =
                validOrdinaryPrimary || validPrimaryTrebuchet ? null
                    : hub.classicCastleTowerCombatSnapshot(
                            selectedClassicServerName, originMapId,
                            request.targetObjectId());
        boolean validPrimaryCastleTower = primaryCastleTower != null
                && primaryCastleTower.present() && primaryCastleTower.alive()
                && primaryCastleTower.mapId() == originMapId;
        List<ClassicWorldAreaCastleDoorTarget> availableCastleDoorTargets =
                classicCastleDoorMagicTargets(
                        originMapId, positionX, positionY);
        ClassicWorldAreaCastleDoorTarget primaryCastleDoor =
                availableCastleDoorTargets.stream()
                        .filter(candidate -> candidate.combat().objectId()
                                == request.targetObjectId())
                        .findFirst().orElse(null);
        ClassicWorldMonsterPopulation.Snapshot primaryMonster =
                validOrdinaryPrimary ? ordinaryPrimaryMonster
                        : validPrimaryTrebuchet ? primaryTrebuchet : null;
        int primaryCount = (primaryPlayer == null ? 0 : 1)
                + (primaryCompanion == null ? 0 : 1)
                + (primaryMonster == null ? 0 : 1)
                + (validPrimaryCastleTower ? 1 : 0)
                + (primaryCastleDoor == null ? 0 : 1);
        if (primaryCount != 1) {
            System.out.println("[LiTo] C_USE_SPELL classic-world area rejected"
                    + " unknown/ambiguous primary skill=" + spell.skillId()
                    + " target=" + request.targetObjectId());
            return;
        }

        int targetX = primaryPlayer != null ? primaryPlayer.positionX
                : primaryCompanion != null ? primaryCompanion.x()
                : primaryMonster != null ? primaryMonster.x()
                : validPrimaryCastleTower ? primaryCastleTower.x()
                : primaryCastleDoor.combat().x();
        int targetY = primaryPlayer != null ? primaryPlayer.positionY
                : primaryCompanion != null ? primaryCompanion.y()
                : primaryMonster != null ? primaryMonster.y()
                : validPrimaryCastleTower ? primaryCastleTower.y()
                : primaryCastleDoor.combat().y();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        long requestNow = System.nanoTime();
        boolean playerPrimaryGate = primaryPlayer == null
                || primaryPlayer.playerHp > 0 && !primaryPlayer.observer
                    && !primaryPlayer.invisible
                    && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                            primaryPlayer.timedStatus
                                    .absoluteBarrierActive(requestNow),
                            spell.skillId());
        boolean companionPrimaryGate = primaryCompanion == null
                || primaryCompanion.owner().phase == Phase.WORLD
                    && primaryCompanion.owner().classicWorldMapId == originMapId
                    && primaryCompanion.owner().classicWorldInstanceId
                        == originInstanceId
                    && primaryCompanion.companion().kind().classicWorldEligible()
                    && primaryCompanion.companion().active()
                    && primaryCompanion.companion().hp() > 0;
        if (!playerPrimaryGate || !companionPrimaryGate
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY)
                || !map.attackPosition(positionX, positionY,
                        targetX, targetY, spell.maximumRange())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world area rejected"
                    + " primary gate/range skill=" + spell.skillId()
                    + " target=" + request.targetObjectId()
                    + " player-target=" + (primaryPlayer != null)
                    + " companion-target=" + (primaryCompanion != null));
            return;
        }

        // A PC primary establishes PC_PC retained targeting, so nearby PCs and
        // ordinary monsters can both enter the area.  An NPC primary establishes
        // PC_NPC targeting and deliberately excludes nearby PCs.
        List<ClientSession> playerTargets = new ArrayList<>();
        if (primaryPlayer != null) {
            playerTargets.add(primaryPlayer);
            for (ClientSession candidate : worldMembers) {
                if (candidate == this || candidate == primaryPlayer
                        || candidate.phase != Phase.WORLD
                        || candidate.classicWorldMapId != originMapId
                        || candidate.classicWorldInstanceId != originInstanceId
                        || candidate.observer || candidate.playerHp <= 0
                        || candidate.invisible) continue;
                int areaDistance = Math.max(
                        Math.abs(candidate.positionX - targetX),
                        Math.abs(candidate.positionY - targetY));
                if (areaDistance > spell.areaRadius()
                        || !BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY,
                                candidate.positionX, candidate.positionY)
                        || !map.attackPosition(positionX, positionY,
                                candidate.positionX, candidate.positionY,
                                spell.maximumRange() + spell.areaRadius() * 2)
                        || BattleAbsoluteBarrierRules.blocksIncomingSpell(
                                candidate.timedStatus
                                        .absoluteBarrierActive(requestNow),
                                spell.skillId())) continue;
                playerTargets.add(candidate);
            }
        }

        List<ClassicWorldAreaCompanionTarget> companionTargets =
                new ArrayList<>();
        try {
            if (primaryCompanion != null) {
                SourceNpcPhysicalStats stats = selectedSourceAccounts()
                        .npcPhysicalStats(primaryCompanion.companion().npcId());
                if (stats == null) {
                    System.out.println("[LiTo] rejected classic-world area spell;"
                            + " primary companion source row missing player="
                            + playerName() + " skill=" + spell.skillId()
                            + " npc=" + primaryCompanion.companion().npcId());
                    return;
                }
                companionTargets.add(new ClassicWorldAreaCompanionTarget(
                        primaryCompanion.owner(), primaryCompanion.controlled(),
                        primaryCompanion.companion(), stats));
            }
            for (ClientSession owner : worldMembers) {
                if (owner == this || owner.phase != Phase.WORLD
                        || owner.classicWorldMapId != originMapId
                        || owner.classicWorldInstanceId != originInstanceId) continue;
                for (BattleCompanion.Snapshot snapshot
                        : owner.classicWorldCompanionSnapshots()) {
                    if (primaryCompanion != null
                            && snapshot.objectId()
                                == primaryCompanion.objectId()) continue;
                    int areaDistance = targetRange(
                            snapshot.x(), snapshot.y(), targetX, targetY);
                    if (!snapshot.kind().classicWorldEligible()
                            || !snapshot.active() || snapshot.hp() <= 0
                            || areaDistance > spell.areaRadius()
                            || !BattleSpellCatalog.isInNativeScreen(
                                    positionX, positionY,
                                    snapshot.x(), snapshot.y())
                            || !map.attackPosition(
                                    positionX, positionY,
                                    snapshot.x(), snapshot.y(),
                                    spell.maximumRange()
                                        + spell.areaRadius() * 2)) continue;
                    BattleCompanion controlled = owner.ownedCompanion(
                            snapshot.objectId());
                    if (controlled == null) continue;
                    SourceNpcPhysicalStats stats = selectedSourceAccounts()
                            .npcPhysicalStats(snapshot.npcId());
                    if (stats == null) {
                        System.out.println("[LiTo] rejected classic-world area spell;"
                                + " companion source row missing player="
                                + playerName() + " skill=" + spell.skillId()
                                + " npc=" + snapshot.npcId());
                        return;
                    }
                    companionTargets.add(new ClassicWorldAreaCompanionTarget(
                            owner, controlled, snapshot, stats));
                }
            }
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] rejected classic-world area spell;"
                    + " companion source lookup failed player=" + playerName()
                    + " skill=" + spell.skillId() + " reason="
                    + sourceFailure.getMessage());
            return;
        }

        List<ClassicWorldMonsterPopulation.Snapshot> monsterTargets =
                new ArrayList<>();
        List<ClassicWorldMonsterPopulation.Snapshot> trebuchetTargets =
                new ArrayList<>();
        List<ClassicWorldMonsterPopulation.Snapshot> castleTowerTargets =
                new ArrayList<>();
        List<ClassicWorldAreaCastleDoorTarget> castleDoorTargets =
                new ArrayList<>();
        if (validOrdinaryPrimary) monsterTargets.add(primaryMonster);
        if (validPrimaryTrebuchet) trebuchetTargets.add(primaryMonster);
        if (validPrimaryCastleTower) {
            castleTowerTargets.add(primaryCastleTower);
        }
        if (primaryCastleDoor != null) {
            castleDoorTargets.add(primaryCastleDoor);
        }
        for (ClassicWorldMonsterPopulation.Snapshot candidate
                : hub.classicWorldMonstersInScreen(
                        originMapId, originInstanceId, targetX, targetY)) {
            if (!candidate.present() || !candidate.alive()
                    || candidate.mapId() != originMapId
                    || validOrdinaryPrimary
                        && candidate.objectId() == primaryMonster.objectId()) {
                continue;
            }
            int areaDistance = Math.max(Math.abs(candidate.x() - targetX),
                    Math.abs(candidate.y() - targetY));
            if (areaDistance > spell.areaRadius()
                    || !BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY, candidate.x(), candidate.y())
                    || !map.attackPosition(positionX, positionY,
                            candidate.x(), candidate.y(),
                            spell.maximumRange() + spell.areaRadius() * 2)) {
                continue;
            }
            monsterTargets.add(candidate);
        }
        for (ClassicWorldMonsterPopulation.Snapshot candidate
                : classicCastleTrebuchetsInScreen(
                        selectedClassicServerName, originMapId,
                        targetX, targetY)) {
            if (validPrimaryTrebuchet
                    && candidate.objectId() == primaryMonster.objectId()) {
                continue;
            }
            int areaDistance = Math.max(Math.abs(candidate.x() - targetX),
                    Math.abs(candidate.y() - targetY));
            if (areaDistance > spell.areaRadius()
                    || !BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY, candidate.x(), candidate.y())
                    || !map.attackPosition(positionX, positionY,
                            candidate.x(), candidate.y(),
                            spell.maximumRange() + spell.areaRadius() * 2)) {
                continue;
            }
            trebuchetTargets.add(candidate);
        }
        for (ClassicWorldMonsterPopulation.Snapshot candidate
                : classicCastleTowersInScreen(
                        selectedClassicServerName, originMapId,
                        targetX, targetY)) {
            if (validPrimaryCastleTower
                    && candidate.objectId()
                        == primaryCastleTower.objectId()) continue;
            int areaDistance = Math.max(Math.abs(candidate.x() - targetX),
                    Math.abs(candidate.y() - targetY));
            if (areaDistance > spell.areaRadius()
                    || !BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY,
                            candidate.x(), candidate.y())
                    || !map.attackPosition(positionX, positionY,
                            candidate.x(), candidate.y(),
                            spell.maximumRange()
                                + spell.areaRadius() * 2)) {
                continue;
            }
            castleTowerTargets.add(candidate);
        }
        for (ClassicWorldAreaCastleDoorTarget candidate
                : availableCastleDoorTargets) {
            ClassicWorldMonsterPopulation.Snapshot combat =
                    candidate.combat();
            if (primaryCastleDoor != null
                    && combat.objectId()
                        == primaryCastleDoor.combat().objectId()) {
                continue;
            }
            int areaDistance = Math.max(Math.abs(combat.x() - targetX),
                    Math.abs(combat.y() - targetY));
            if (areaDistance > spell.areaRadius()
                    || !BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY,
                            combat.x(), combat.y())
                    || !map.attackPosition(positionX, positionY,
                            combat.x(), combat.y(),
                            spell.maximumRange()
                                + spell.areaRadius() * 2)) {
                continue;
            }
            castleDoorTargets.add(candidate);
        }

        Map<Long, SourceNpcPhysicalStats> npcStats = new LinkedHashMap<>();
        for (ClassicWorldMonsterPopulation.Snapshot target : monsterTargets) {
            SourceNpcPhysicalStats stats;
            try {
                stats = selectedSourceAccounts().npcPhysicalStats(target.npcId());
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected classic-world area spell;"
                        + " source NPC lookup failed player=" + playerName()
                        + " skill=" + spell.skillId() + " npc=" + target.npcId()
                        + " reason=" + sourceFailure.getMessage());
                return;
            }
            if (stats == null) {
                System.out.println("[LiTo] rejected classic-world area spell;"
                        + " source NPC row missing player=" + playerName()
                        + " skill=" + spell.skillId() + " npc=" + target.npcId());
                return;
            }
            npcStats.put(target.objectId(), stats);
        }
        for (ClassicWorldMonsterPopulation.Snapshot target : trebuchetTargets) {
            SourceNpcPhysicalStats stats;
            try {
                stats = selectedSourceAccounts().npcPhysicalStats(target.npcId());
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected classic-world area spell;"
                        + " trebuchet source NPC lookup failed player="
                        + playerName() + " skill=" + spell.skillId() + " npc="
                        + target.npcId() + " reason="
                        + sourceFailure.getMessage());
                return;
            }
            if (stats == null) {
                System.out.println("[LiTo] rejected classic-world area spell;"
                        + " trebuchet source NPC row missing player="
                        + playerName() + " skill=" + spell.skillId() + " npc="
                        + target.npcId());
                return;
            }
            npcStats.put(target.objectId(), stats);
        }
        for (ClassicWorldMonsterPopulation.Snapshot target
                : castleTowerTargets) {
            SourceNpcPhysicalStats stats;
            try {
                stats = selectedSourceAccounts().npcPhysicalStats(
                        target.npcId());
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected classic-world area spell;"
                        + " castle tower source NPC lookup failed player="
                        + playerName() + " skill=" + spell.skillId()
                        + " npc=" + target.npcId() + " reason="
                        + sourceFailure.getMessage());
                return;
            }
            if (stats == null) {
                System.out.println("[LiTo] rejected classic-world area spell;"
                        + " castle tower source NPC row missing player="
                        + playerName() + " skill=" + spell.skillId()
                        + " npc=" + target.npcId());
                return;
            }
            npcStats.put(target.objectId(), stats);
        }
        for (ClassicWorldAreaCastleDoorTarget target : castleDoorTargets) {
            SourceNpcPhysicalStats stats;
            try {
                stats = selectedSourceAccounts().npcPhysicalStats(
                        ClassicWorldCastleDoorCombat.NPC_TEMPLATE_ID);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected classic-world area spell;"
                        + " castle door source NPC lookup failed player="
                        + playerName() + " skill=" + spell.skillId()
                        + " npc="
                        + ClassicWorldCastleDoorCombat.NPC_TEMPLATE_ID
                        + " reason=" + sourceFailure.getMessage());
                return;
            }
            if (stats == null) {
                System.out.println("[LiTo] rejected classic-world area spell;"
                        + " castle door source NPC row missing player="
                        + playerName() + " skill=" + spell.skillId()
                        + " npc="
                        + ClassicWorldCastleDoorCombat.NPC_TEMPLATE_ID);
                return;
            }
            npcStats.put(target.combat().objectId(), stats);
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);

        int remainingHp;
        int remainingMp;
        long castNow;
        ClientSession firstLock = primaryPlayer == null
                || playerObjectId() <= primaryPlayer.playerObjectId()
                ? this : primaryPlayer;
        ClientSession secondLock = primaryPlayer == null
                ? this : firstLock == this ? primaryPlayer : this;
        synchronized (firstLock) {
            synchronized (secondLock) {
                castNow = System.nanoTime();
                long readyAt = spellReadyNanos.getOrDefault(
                        spell.skillId(), 0L);
                boolean primaryPlayerStillValid = primaryPlayer == null
                        || primaryPlayer.phase == Phase.WORLD
                            && primaryPlayer.classicWorldMapId == originMapId
                            && primaryPlayer.classicWorldInstanceId
                                == originInstanceId
                            && primaryPlayer.playerHp > 0
                            && !primaryPlayer.observer
                            && !primaryPlayer.invisible
                            && primaryPlayer.positionX == targetX
                            && primaryPlayer.positionY == targetY
                            && map.isNormalZone(originX, originY)
                            && map.isNormalZone(targetX, targetY)
                            && !BattleAbsoluteBarrierRules
                                .blocksIncomingSpell(
                                    primaryPlayer.timedStatus
                                        .absoluteBarrierActive(castNow),
                                    spell.skillId());
                BattleCompanion.Snapshot currentPrimaryCompanion =
                        primaryCompanion == null ? null
                                : primaryCompanion.controlled().snapshot();
                boolean primaryCompanionStillValid = primaryCompanion == null
                        || currentPrimaryCompanion != null
                            && currentPrimaryCompanion.objectId()
                                == primaryCompanion.objectId()
                            && currentPrimaryCompanion.kind()
                                .classicWorldEligible()
                            && currentPrimaryCompanion.active()
                            && currentPrimaryCompanion.hp() > 0
                            && currentPrimaryCompanion.x() == targetX
                            && currentPrimaryCompanion.y() == targetY
                            && primaryCompanion.owner().phase == Phase.WORLD
                            && primaryCompanion.owner().classicWorldMapId
                                == originMapId
                            && primaryCompanion.owner().classicWorldInstanceId
                                == originInstanceId;
                ClassicWorldMonsterPopulation.Snapshot lockedOrdinary =
                        !validOrdinaryPrimary ? null
                            : hub.classicWorldMonster(
                                originMapId, originInstanceId,
                                ordinaryPrimaryMonster.objectId());
                boolean primaryOrdinaryStillValid = !validOrdinaryPrimary
                        || lockedOrdinary != null && lockedOrdinary.present()
                            && lockedOrdinary.alive()
                            && lockedOrdinary.mapId() == originMapId
                            && lockedOrdinary.x() == targetX
                            && lockedOrdinary.y() == targetY;
                ClassicWorldMonsterPopulation.Snapshot lockedTrebuchet =
                        !validPrimaryTrebuchet ? null
                            : hub.classicCastleTrebuchetCombatSnapshot(
                                selectedClassicServerName, originMapId,
                                primaryTrebuchet.objectId());
                boolean primaryTrebuchetStillValid = !validPrimaryTrebuchet
                        || lockedTrebuchet != null && lockedTrebuchet.present()
                            && lockedTrebuchet.alive()
                            && lockedTrebuchet.mapId() == originMapId
                            && lockedTrebuchet.x() == targetX
                            && lockedTrebuchet.y() == targetY;
                ClassicWorldMonsterPopulation.Snapshot lockedCastleTower =
                        !validPrimaryCastleTower ? null
                            : currentClassicCastleTower(primaryCastleTower);
                boolean primaryCastleTowerStillValid =
                        !validPrimaryCastleTower
                        || lockedCastleTower != null
                            && lockedCastleTower.x() == targetX
                            && lockedCastleTower.y() == targetY;
                ClassicWorldAreaCastleDoorTarget lockedCastleDoor =
                        primaryCastleDoor == null ? null
                            : currentClassicWorldAreaCastleDoorTarget(
                                primaryCastleDoor, originX, originY);
                boolean primaryCastleDoorStillValid = primaryCastleDoor == null
                        || lockedCastleDoor != null
                            && lockedCastleDoor.combat().x() == targetX
                            && lockedCastleDoor.combat().y() == targetY;
                boolean endpointStillAllowed = phase == Phase.WORLD
                        && !observer && classicWorldMapId == originMapId
                        && classicWorldInstanceId == originInstanceId
                        && positionX == originX && positionY == originY
                        && BattleSpellCatalog.isInNativeScreen(
                            originX, originY, targetX, targetY)
                        && map.attackPosition(originX, originY,
                            targetX, targetY, spell.maximumRange());
                boolean primaryStillAvailable = primaryPlayerStillValid
                        && primaryCompanionStillValid
                        && primaryOrdinaryStillValid
                        && primaryTrebuchetStillValid
                        && primaryCastleTowerStillValid
                        && primaryCastleDoorStillValid;
                if (castNow < readyAt || playerHp <= spell.hpCost()
                        || playerMp < mpCost || !primaryStillAvailable
                        || !endpointStillAllowed) {
                    if (playerHp <= spell.hpCost()) {
                        sendEncrypted(Protocol.messageCode(279),
                                "S_MESSAGE_CODE classic-world-area-spell"
                                        + "-insufficient-hp=279 skill="
                                        + spell.skillId());
                    } else if (playerMp < mpCost) {
                        sendEncrypted(Protocol.messageCode(278),
                                "S_MESSAGE_CODE classic-world-area-spell"
                                        + "-insufficient-mp=278 skill="
                                        + spell.skillId());
                    }
                    System.out.println("[LiTo] C_USE_SPELL classic-world area"
                            + " rejected state skill=" + spell.skillId()
                            + " target=" + request.targetObjectId() + " hp="
                            + playerHp + " hp-cost=" + spell.hpCost()
                            + " mp=" + playerMp + " mp-cost=" + mpCost
                            + " primary-available=" + primaryStillAvailable
                            + " endpoint=" + endpointStillAllowed
                            + " cooldownNanos="
                            + Math.max(0L, readyAt - castNow));
                    return;
                }
                playerHp -= spell.hpCost();
                playerMp -= mpCost;
                remainingHp = playerHp;
                remainingMp = playerMp;
                spellReadyNanos.put(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        }
        cancelMeditation("classic-world-spell-" + spell.skillId());
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());

        Map<ClientSession, Integer> playerDamages = new LinkedHashMap<>();
        Map<ClientSession, BattleEraseMagicStatus.Lease> playerEraseLeases =
                new LinkedHashMap<>();
        Map<ClassicWorldAreaCompanionTarget, Integer> companionDamages =
                new LinkedHashMap<>();
        Map<ClassicWorldAreaCompanionTarget, BattleEraseMagicStatus.Lease>
                companionEraseLeases = new LinkedHashMap<>();
        Map<Long, Integer> monsterDamages = new LinkedHashMap<>();
        Map<Long, BattleEraseMagicStatus.Lease> monsterEraseLeases =
                new LinkedHashMap<>();
        Map<Long, Integer> trebuchetDamages = new LinkedHashMap<>();
        Map<Long, Integer> castleTowerDamages = new LinkedHashMap<>();
        Map<ClassicWorldAreaCastleDoorTarget, Integer> castleDoorDamages =
                new LinkedHashMap<>();
        List<ClientSession> counteredTargets = new ArrayList<>();
        List<Protocol.AttackManyTarget> wireTargets = new ArrayList<>();
        int counterMirrorTriggers = 0;

        for (ClientSession target : playerTargets) {
            if (target.phase != Phase.WORLD || target.playerHp <= 0
                    || target.observer || target.invisible
                    || target.classicWorldMapId != originMapId
                    || target.classicWorldInstanceId != originInstanceId
                    || !map.isNormalZone(positionX, positionY)
                    || !map.isNormalZone(target.positionX, target.positionY)
                    || BattleAbsoluteBarrierRules.blocksIncomingSpell(
                            target.timedStatus.absoluteBarrierActive(castNow),
                            spell.skillId())) continue;
            int areaDistance = Math.max(Math.abs(target.positionX - targetX),
                    Math.abs(target.positionY - targetY));
            if (areaDistance > spell.areaRadius()) continue;
            if (target.timedStatus.consumeCounterMagic(castNow)) {
                counteredTargets.add(target);
                continue;
            }
            BattleEraseMagicStatus.Lease eraseLease =
                    target.eraseMagicStatus.capture(castNow);
            int sourceDamage = rollAreaSpellSourceDamage(spell);
            int damage = areaSpellDamage(
                    spell, sourceDamage,
                    target.effectiveSpellElementalResistance(spell.attribute()),
                    target.effectiveBaseMagicResistance(castNow),
                    target.effectiveArmorMagicReductionBase(),
                    "classic-world-player=" + target.playerName());
            damage = target.combatDamageAfterCooking(
                    damage, "classic-world-area-spell-" + spell.skillId());
            damage = target.earthBindProtectedCombatDamage(
                    damage, "classic-world-area-spell-" + spell.skillId());
            BattleCounterMirrorStatus.Decision mirror =
                    target.counterMirrorDecision(
                            damage, true,
                            ThreadLocalRandom.current().nextInt(100), castNow);
            if (mirror.triggered()) {
                publishPlayerCounterMirrorTrigger(
                        target, mirror,
                        "classic-world-area-spell-" + spell.skillId());
                damage = 0;
                counterMirrorTriggers++;
            }
            playerDamages.put(target, damage);
            playerEraseLeases.put(target, eraseLease);
            wireTargets.add(new Protocol.AttackManyTarget(
                    target.playerObjectId(), damage > 0));
        }

        for (ClassicWorldAreaCompanionTarget target : companionTargets) {
            BattleCompanion.Snapshot current = target.controlled().snapshot();
            if (target.owner().phase != Phase.WORLD
                    || target.owner().classicWorldMapId != originMapId
                    || target.owner().classicWorldInstanceId != originInstanceId
                    || current.objectId() != target.snapshot().objectId()
                    || !current.kind().classicWorldEligible()
                    || !current.active() || current.hp() <= 0
                    || targetRange(current.x(), current.y(), targetX, targetY)
                        > spell.areaRadius()) continue;
            BattleEraseMagicStatus.Lease eraseLease =
                    target.controlled().captureEraseMagic(castNow);
            int targetMr = target.controlled().effectiveMagicResistance(
                    target.stats().magicResistance(), castNow);
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    targetMr, 0,
                    "classic-world-companion=" + current.objectId());
            if (!classicWorldCkewAttackAllowed(current.npcId(), castNow)) {
                damage = 0;
            }
            companionDamages.put(target, damage);
            companionEraseLeases.put(target, eraseLease);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldMonsterPopulation.Snapshot target : monsterTargets) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    hub.classicWorldMonster(originMapId, originInstanceId,
                            target.objectId());
            if (current == null || !current.present() || !current.alive()) continue;
            int areaDistance = Math.max(Math.abs(current.x() - targetX),
                    Math.abs(current.y() - targetY));
            if (areaDistance > spell.areaRadius()) continue;
            SourceNpcPhysicalStats stats = npcStats.get(current.objectId());
            if (stats == null) continue;
            BattleEraseMagicStatus.Lease eraseLease =
                    hub.captureClassicWorldMonsterEraseMagic(
                            originMapId, originInstanceId,
                            current.objectId(), castNow);
            int sourceDamage = rollAreaSpellSourceDamage(spell);
            int elementalResistance =
                    hub.classicWorldMonsterElementalFallDownModifier(
                            originMapId, originInstanceId, current.objectId(),
                            spell.attribute(), castNow);
            int targetMr = hub.classicWorldMonsterEffectiveMagicResistance(
                    originMapId, originInstanceId, current.objectId(),
                    stats.magicResistance(), castNow);
            int damage = areaSpellDamage(
                    spell, sourceDamage, elementalResistance, targetMr, 0,
                    "classic-world-npc=" + current.objectId());
            if (!classicWorldCkewAttackAllowed(current.npcId(), castNow)) {
                damage = 0;
            }
            monsterDamages.put(current.objectId(), damage);
            monsterEraseLeases.put(current.objectId(), eraseLease);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldMonsterPopulation.Snapshot target : trebuchetTargets) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    hub.classicCastleTrebuchetCombatSnapshot(
                            selectedClassicServerName, originMapId,
                            target.objectId());
            if (current == null || !current.present() || !current.alive()) continue;
            int areaDistance = Math.max(Math.abs(current.x() - targetX),
                    Math.abs(current.y() - targetY));
            if (areaDistance > spell.areaRadius()) continue;
            SourceNpcPhysicalStats stats = npcStats.get(current.objectId());
            if (stats == null) continue;
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    stats.magicResistance(), 0,
                    "classic-world-castle-trebuchet=" + current.objectId());
            trebuchetDamages.put(current.objectId(), damage);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldMonsterPopulation.Snapshot target
                : castleTowerTargets) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    currentClassicCastleTower(target);
            if (current == null) continue;
            int areaDistance = Math.max(Math.abs(current.x() - targetX),
                    Math.abs(current.y() - targetY));
            if (areaDistance > spell.areaRadius()) continue;
            SourceNpcPhysicalStats stats = npcStats.get(current.objectId());
            if (stats == null) continue;
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    stats.magicResistance(), 0,
                    "classic-world-castle-tower=" + current.objectId());
            castleTowerDamages.put(current.objectId(), damage);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldAreaCastleDoorTarget target : castleDoorTargets) {
            ClassicWorldAreaCastleDoorTarget current =
                    currentClassicWorldAreaCastleDoorTarget(
                            target, positionX, positionY);
            if (current == null) continue;
            int areaDistance = Math.max(
                    Math.abs(current.combat().x() - targetX),
                    Math.abs(current.combat().y() - targetY));
            if (areaDistance > spell.areaRadius()) continue;
            SourceNpcPhysicalStats stats =
                    npcStats.get(current.combat().objectId());
            if (stats == null) continue;
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    stats.magicResistance(), 0,
                    "classic-world-castle-door="
                            + current.combat().objectId());
            castleDoorDamages.put(current, damage);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.combat().objectId(), damage > 0));
        }

        for (ClientSession counteredTarget : counteredTargets) {
            publishCounterMagicConsumption(counteredTarget, spell.skillId());
        }

        int attackHeading = heading(positionX, positionY, targetX, targetY);
        playerHeading = attackHeading;
        long sequence = ATTACK_SPELL_SEQUENCE.incrementAndGet();
        if (wireTargets.isEmpty()) {
            broadcastCounteredSpellAction(
                    spell.actionId(), spell.skillId(), spell.key());
        } else {
            byte[] attack = Protocol.attackMany(
                    spell.actionId(), playerObjectId(), positionX, positionY,
                    attackHeading, sequence, spell.effectGfx(), wireTargets);
            publishClassicWorldAreaAttackSpellPacket(
                    attack, targetX, targetY,
                    "skill=" + spell.skillId() + " key=" + spell.key()
                            + " primary=" + request.targetObjectId()
                            + " targets=" + wireTargets.size()
                            + " gfx=" + spell.effectGfx() + " type=8 sequence="
                            + sequence + " countered="
                            + counteredTargets.size()
                            + " counter-mirror-triggered="
                            + counterMirrorTriggers);
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world area-attack="
                        + remainingMp + "/" + playerMaxMp);
        if (spell.hpCost() != 0) {
            sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                            .h(remainingHp).h(playerMaxHp).bytes(),
                    "S_HIT_POINT classic-world area-attack-hp-cost="
                            + remainingHp + "/" + playerMaxHp);
            broadcastOwnHitRatio("classic-world-area-attack-hp-cost");
        }
        applySpellLawfulDelta(spell.lawfulDelta(), spell.key());

        for (Map.Entry<ClientSession, Integer> entry : playerDamages.entrySet()) {
            if (entry.getValue() > 0) {
                entry.getKey().takeClassicWorldPlayerDamage(
                        entry.getValue(), this, false);
            }
            entry.getKey().eraseMagicStatus.consume(
                    playerEraseLeases.get(entry.getKey()));
        }
        for (Map.Entry<ClassicWorldAreaCompanionTarget, Integer> entry
                : companionDamages.entrySet()) {
            ClassicWorldAreaCompanionTarget target = entry.getKey();
            target.controlled().consumeEraseMagic(
                    companionEraseLeases.get(target));
            if (entry.getValue() > 0) {
                target.controlled().selectMasterTarget(playerObjectId());
                target.owner().applyClassicWorldMonsterCompanionDamage(
                        target.controlled(), target.snapshot(), entry.getValue(),
                        playerObjectId(), "area-spell-" + spell.skillId());
            }
        }
        for (Map.Entry<Long, Integer> entry : monsterDamages.entrySet()) {
            ClassicWorldMonsterPopulation.Hit transition = null;
            if (entry.getValue() > 0) {
                transition = hub.damageClassicWorldMonster(
                        originMapId, originInstanceId, entry.getKey(),
                        playerObjectId(), entry.getValue());
            }
            hub.consumeClassicWorldMonsterEraseMagic(
                    originMapId, originInstanceId, entry.getKey(),
                    monsterEraseLeases.get(entry.getKey()));
            if (transition == null) continue;
            hub.provokeClassicWorldMonster(
                    originMapId, originInstanceId, entry.getKey(),
                    playerObjectId());
            for (BattleCompanion.Snapshot companion
                    : classicWorldCompanionSnapshots()) {
                BattleCompanion controlled = ownedCompanion(companion.objectId());
                if (controlled != null) controlled.selectMasterTarget(entry.getKey());
            }
            publishClassicWorldSpellMonsterDamage(spell.skillId(), transition);
        }
        for (Map.Entry<Long, Integer> entry : trebuchetDamages.entrySet()) {
            if (entry.getValue() <= 0) continue;
            ClassicWorldCastleWarField.TrebuchetHit hit =
                    hub.damageClassicCastleTrebuchet(
                            selectedClassicServerName, originMapId,
                            entry.getKey(), entry.getValue());
            if (hit == null || hit.appliedDamage() <= 0) continue;
            publishClassicCastleTrebuchetHit(hit);
            if (hit.diedNow()) {
                hub.scheduleClassicCastleTrebuchetCorpseRemoval(
                        selectedClassicServerName, hit.after());
            }
        }

        for (Map.Entry<Long, Integer> entry
                : castleTowerDamages.entrySet()) {
            if (entry.getValue() <= 0) continue;
            ClassicWorldMonsterPopulation.Snapshot target =
                    hub.classicCastleTowerCombatSnapshot(
                            selectedClassicServerName, originMapId,
                            entry.getKey());
            applyClassicWorldCastleTowerMagicDamage(
                    target, entry.getValue());
        }

        for (Map.Entry<ClassicWorldAreaCastleDoorTarget, Integer> entry
                : castleDoorDamages.entrySet()) {
            applyClassicWorldAreaCastleDoorDamage(
                    entry.getKey(), entry.getValue());
        }

        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale classic-world"
                    + " area coordinates skill=" + spell.skillId() + " client="
                    + request.x() + "," + request.y() + " server="
                    + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world area skill="
                + spell.skillId() + " caster=" + playerName() + " primary="
                + request.targetObjectId() + " player-primary="
                + (primaryPlayer != null) + " companion-primary="
                + (primaryCompanion != null) + " player-targets="
                + playerDamages.size() + " npc-targets="
                + monsterDamages.size() + " trebuchet-targets="
                + trebuchetDamages.size() + " castle-tower-targets="
                + castleTowerDamages.size() + " castle-door-targets="
                + castleDoorDamages.size() + " companion-targets="
                + companionDamages.size() + " wire-targets="
                + wireTargets.size() + " countered=" + counteredTargets.size()
                + " counter-mirror-triggered=" + counterMirrorTriggers
                + " effective-int=" + effectiveIntelligence + " mp-cost="
                + mpCost + " hp-cost=" + spell.hpCost() + " lawful-delta="
                + spell.lawfulDelta() + " mp=" + remainingMp + "/"
                + playerMaxMp);
    }

    private void publishClassicWorldAreaAttackSpellPacket(
            byte[] packet, int targetX, int targetY, String reason)
            throws IOException {
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY)
                        && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            targetX, targetY)) continue;
            if (invisible && member != this) continue;
            member.sendEncrypted(packet,
                    "S_ATTACK_MANY classic-world area " + reason);
        }
    }

    private void useClassicWorldAttackSpell(
            byte[] payload, BattleSpellCatalog.AttackSpell spell)
            throws IOException {
        useClassicWorldAttackSpell(
                Protocol.attackSpellRequest(payload), spell);
    }

    private void useClassicWorldAttackSpell(
            Protocol.AttackSpellRequest request,
            BattleSpellCatalog.AttackSpell spell) throws IOException {
        if (request.skillId() != spell.skillId()) return;
        BattleSpellCatalog.ThunderGrabSpell thunderGrab =
                BattleSpellCatalog.thunderGrabSpell(spell.skillId());
        BattleSpellCatalog.ConfusionSpell confusion =
                BattleSpellCatalog.confusionSpell(spell.skillId());
        BattleSpellCatalog.MindBreakSpell mindBreak =
                BattleSpellCatalog.mindBreakSpell(spell.skillId());
        BattleSpellCatalog.BoneBreakSpell boneBreak =
                BattleSpellCatalog.boneBreakSpell(spell.skillId());
        BattleSpellCatalog.ArmBreakerSpell armBreaker =
                BattleSpellCatalog.armBreakerSpell(spell.skillId());

        long requestNow = System.nanoTime();
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-polymorph-attack-spell-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-polymorph-attack-spell-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-Silence-attack-spell-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-Silence-attack-spell-rejected=285");
            return;
        }
        int weight240 = currentWeight240(requestNow);
        if (weight240 >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE classic-world-attack-spell-overweight=316 weight240="
                            + weight240);
            return;
        }
        if (!learnedSkills.contains(spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL rejected unlearned classic-world"
                    + " attack skill=" + spell.skillId() + " player=" + playerName());
            return;
        }
        if (!spell.canCastAtLawful(playerLawful)) {
            sendEncrypted(Protocol.messageCode(352, "$967"),
                    "S_MESSAGE_CODE classic-world-Disintegrate-lawful-gate=352 argument=$967");
            System.out.println("[LiTo] C_USE_SPELL classic-world attack rejected lawful"
                    + " skill=" + spell.skillId() + " player=" + playerName()
                    + " lawful=" + playerLawful + " minimum=" + spell.minimumLawful());
            return;
        }

        List<ClientSession> worldMembers =
                classicWorldMembers(classicWorldMapId);
        ClientSession playerTarget = worldMembers.stream()
                .filter(candidate -> candidate != this
                        && sameClassicWorldMap(candidate)
                        && candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        ClientSession companionOwner = null;
        BattleCompanion controlledCompanion = null;
        BattleCompanion.Snapshot companionTarget = null;
        for (ClientSession owner : worldMembers) {
            if (!sameClassicWorldMap(owner)) continue;
            BattleCompanion.Snapshot candidate = owner
                    .classicWorldCompanionSnapshots().stream()
                    .filter(snapshot -> snapshot.objectId()
                            == request.targetObjectId())
                    .findFirst().orElse(null);
            if (candidate == null) continue;
            BattleCompanion controlled = owner.ownedCompanion(
                    candidate.objectId());
            if (controlled == null) continue;
            companionOwner = owner;
            controlledCompanion = controlled;
            companionTarget = candidate;
            break;
        }
        ClassicWorldMonsterPopulation.Snapshot ordinaryMonsterTarget =
                hub.classicWorldMonster(classicWorldMapId, classicWorldInstanceId,
                        request.targetObjectId());
        boolean validOrdinaryMonster = ordinaryMonsterTarget != null
                && ordinaryMonsterTarget.present() && ordinaryMonsterTarget.alive()
                && ordinaryMonsterTarget.mapId() == classicWorldMapId;
        ClassicWorldMonsterPopulation.Snapshot castleTrebuchetSnapshot =
                validOrdinaryMonster ? null
                    : hub.classicCastleTrebuchetCombatSnapshot(
                            selectedClassicServerName, classicWorldMapId,
                            request.targetObjectId());
        boolean castleTrebuchetTarget = castleTrebuchetSnapshot != null
                && castleTrebuchetSnapshot.present()
                && castleTrebuchetSnapshot.alive()
                && castleTrebuchetSnapshot.mapId() == classicWorldMapId;
        ClassicWorldMonsterPopulation.Snapshot castleTowerSnapshot =
                validOrdinaryMonster || castleTrebuchetTarget ? null
                    : hub.classicCastleTowerCombatSnapshot(
                            selectedClassicServerName, classicWorldMapId,
                            request.targetObjectId());
        boolean castleTowerTarget = castleTowerSnapshot != null
                && castleTowerSnapshot.present()
                && castleTowerSnapshot.alive()
                && castleTowerSnapshot.mapId() == classicWorldMapId;
        ClassicWorldMonsterPopulation.Snapshot dwarfCastleDoorTarget =
                validOrdinaryMonster || castleTrebuchetTarget
                        || castleTowerTarget ? null
                    : hub.dwarfCastleDoorCombatSnapshot(
                            classicWorldMapId, request.targetObjectId(),
                            positionX, positionY);
        ClassicWorldCastleDoorCombat.Target mainlandCastleDoorTarget =
                validOrdinaryMonster || castleTrebuchetTarget
                        || castleTowerTarget
                        || dwarfCastleDoorTarget != null ? null
                    : hub.mainlandCastleDoorCombatTarget(
                            classicWorldMapId, request.targetObjectId(),
                            positionX, positionY);
        ClassicWorldMonsterPopulation.Snapshot castleDoorTarget =
                dwarfCastleDoorTarget != null ? dwarfCastleDoorTarget
                    : mainlandCastleDoorTarget == null ? null
                        : mainlandCastleDoorTarget.combat();
        boolean validCastleDoor = castleDoorTarget != null
                && castleDoorTarget.present() && castleDoorTarget.alive()
                && castleDoorTarget.mapId() == classicWorldMapId;
        ClassicWorldMonsterPopulation.Snapshot monsterTarget =
                validOrdinaryMonster ? ordinaryMonsterTarget
                        : castleTrebuchetTarget ? castleTrebuchetSnapshot
                        : castleTowerTarget ? castleTowerSnapshot : null;
        boolean validMonster = validOrdinaryMonster || castleTrebuchetTarget;
        int targetCount = (playerTarget == null ? 0 : 1)
                + (companionTarget == null ? 0 : 1)
                + (validMonster ? 1 : 0)
                + (castleTowerTarget ? 1 : 0)
                + (validCastleDoor ? 1 : 0);
        if (confusion != null && companionTarget != null) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Confusion rejected"
                    + " companion target=" + request.targetObjectId());
            return;
        }
        if (targetCount != 1) {
            System.out.println("[LiTo] C_USE_SPELL classic-world attack rejected"
                    + " unknown/ambiguous target"
                    + " skill=" + spell.skillId() + " target="
                    + request.targetObjectId() + " matches=" + targetCount);
            return;
        }
        int targetX = playerTarget != null ? playerTarget.positionX
                : companionTarget != null ? companionTarget.x()
                : validMonster || castleTowerTarget
                    ? monsterTarget.x() : castleDoorTarget.x();
        int targetY = playerTarget != null ? playerTarget.positionY
                : companionTarget != null ? companionTarget.y()
                : validMonster || castleTowerTarget
                    ? monsterTarget.y() : castleDoorTarget.y();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        boolean playerTargetGate = playerTarget == null
                || playerTarget.phase == Phase.WORLD
                    && playerTarget.playerHp > 0
                    && !playerTarget.invisible
                    && sameClassicWorldMap(playerTarget);
        boolean companionTargetGate = companionTarget == null
                || companionOwner.phase == Phase.WORLD
                    && sameClassicWorldMap(companionOwner)
                    && companionTarget.kind().classicWorldEligible()
                    && companionTarget.active() && companionTarget.hp() > 0;
        if (!playerTargetGate || !companionTargetGate
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY)
                || !map.attackPosition(positionX, positionY,
                        targetX, targetY, spell.maximumRange())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world attack rejected gate/range"
                    + " skill=" + spell.skillId() + " target="
                    + request.targetObjectId() + " player-target="
                    + (playerTarget != null) + " companion-target="
                    + (companionTarget != null));
            return;
        }
        if (playerTarget != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                        playerTarget.timedStatus.absoluteBarrierActive(requestNow),
                        spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world attack rejected by"
                    + " Absolute Barrier caster=" + playerName() + " target="
                    + playerTarget.playerName() + " skill=" + spell.skillId());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world attack rejected"
                    + " unavailable action player=" + playerName() + " gfx="
                    + battleGfx() + " action=" + spell.actionId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int npcId = companionTarget != null ? companionTarget.npcId()
                : validMonster || castleTowerTarget ? monsterTarget.npcId()
                    : validCastleDoor
                        ? ClassicWorldCastleDoorCombat.NPC_TEMPLATE_ID : 0;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected classic-world attack spell; source"
                        + " NPC lookup failed player=" + playerName() + " skill="
                        + spell.skillId() + " npc=" + npcId + " reason="
                        + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) {
                System.out.println("[LiTo] rejected classic-world attack spell; source"
                        + " NPC row missing player=" + playerName() + " skill="
                        + spell.skillId() + " npc=" + npcId);
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = casterEquipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        int hpCost = confusion != null ? confusion.hpCost()
                : mindBreak != null ? mindBreak.hpCost()
                : thunderGrab == null ? spell.hpCost() : thunderGrab.hpCost();
        boolean confusionBossTarget = confusion != null && monsterTarget != null
                && (monsterTarget.template().boss()
                    || npcStats != null && npcStats.boss());
        int confusionRoll = confusion == null ? 0
                : config.confusionFixtureD100() > 0
                    ? config.confusionFixtureD100()
                    : ThreadLocalRandom.current().nextInt(1, 101);
        boolean confusionEarthBindBlocked = confusion != null
                && playerTarget != null
                && playerTarget.timedStatus.earthBindActive(requestNow);
        boolean confusionSuccess = confusion != null
                && !confusionEarthBindBlocked
                && confusion.succeeds(confusionBossTarget, confusionRoll);

        int sourceDamage;
        int remainingHp;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            BattleCompanion.Snapshot currentCompanion =
                    controlledCompanion == null
                            ? null : controlledCompanion.snapshot();
            boolean companionStillValid = companionTarget == null
                    || currentCompanion != null
                        && currentCompanion.objectId()
                            == companionTarget.objectId()
                        && currentCompanion.kind().classicWorldEligible()
                        && currentCompanion.active()
                        && currentCompanion.hp() > 0
                        && companionOwner.phase == Phase.WORLD
                        && sameClassicWorldMap(companionOwner);
            if (castNow < readyAt || phase != Phase.WORLD || playerHp <= 0
                    || !companionStillValid
                    || castleTowerTarget
                        && currentClassicCastleTower(castleTowerSnapshot) == null
                    || playerTarget != null
                        && (playerTarget.phase != Phase.WORLD
                            || playerTarget.playerHp <= 0
                            || playerTarget.invisible
                            || !sameClassicWorldMap(playerTarget))) {
                System.out.println("[LiTo] C_USE_SPELL classic-world attack rejected state"
                        + " skill=" + spell.skillId() + " target="
                        + request.targetObjectId() + " mp=" + playerMp
                        + " cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            if (hpCost > 0 && playerHp <= hpCost) {
                sendEncrypted(Protocol.messageCode(279),
                        "S_MESSAGE_CODE classic-world-attack-spell-insufficient-hp=279"
                                + " skill=" + spell.skillId());
                return;
            }
            if (playerMp < mpCost) {
                sendEncrypted(Protocol.messageCode(278),
                        "S_MESSAGE_CODE classic-world-attack-spell-insufficient-mp=278"
                                + " skill=" + spell.skillId());
                System.out.println("[LiTo] C_USE_SPELL classic-world attack rejected MP"
                        + " skill=" + spell.skillId() + " target="
                        + request.targetObjectId() + " mp=" + playerMp
                        + " cost=" + mpCost);
                return;
            }
            if (spell.finalBurn()) {
                sourceDamage = playerMp;
            } else {
                sourceDamage = spell.baseDamage();
                for (int index = 0; index < spell.diceCount(); index++) {
                    sourceDamage += ThreadLocalRandom.current().nextInt(
                            1, spell.dieSides() + 1);
                }
            }
            if (spell.finalBurn()) {
                playerHp = 1;
                playerMp = 0;
            } else {
                playerHp -= hpCost;
                playerMp -= mpCost;
            }
            remainingHp = playerHp;
            remainingMp = playerMp;
            // Retained TYPE_NORMAL commits resources and the cast lock before
            // breaking Meditation, Absolute Barrier and invisibility.
            spellReadyNanos.put(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelMeditation("classic-world-spell-" + spell.skillId());
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());
        if (boneBreak != null) {
            applySpellLawfulDelta(
                    boneBreak.lawfulDelta(), boneBreak.key());
        }

        boolean safetyMotion = (playerTarget != null || companionTarget != null)
                && (map.isSafetyZone(positionX, positionY)
                    || map.isSafetyZone(targetX, targetY));
        if (safetyMotion) {
            long sequence = ATTACK_SPELL_SEQUENCE.incrementAndGet();
            byte[] motion = Protocol.attackSpell(
                    spell.actionId(), playerObjectId(), 0, 0,
                    heading(positionX, positionY, targetX, targetY), sequence,
                    spell.effectGfx(false), positionX, positionY, targetX, targetY);
            publishClassicWorldAttackSpellPacket(motion, targetX, targetY,
                    "safety-motion skill=" + spell.skillId() + " target=0"
                            + " sequence=" + sequence);
            publishClassicWorldAttackSpellResources(
                    spell, remainingHp, remainingMp, "safety-motion");
            System.out.println("[LiTo] C_USE_SPELL classic-world attack safety motion"
                    + " skill=" + spell.skillId() + " caster=" + playerName()
                    + " target=" + request.targetObjectId()
                    + " player-target=" + (playerTarget != null)
                    + " companion-target=" + (companionTarget != null)
                    + " damage=0"
                    + " counter-magic-consumed=false criminal=false mp-cost="
                    + mpCost + " mp=" + remainingMp + "/" + playerMaxMp);
            return;
        }

        // Retained L1SkillUse probability order: Erase Magic is consumed and
        // sleep is broken after the probability attempt, before Counter Magic.
        if (confusion != null) {
            consumeEraseMagicAfterProbability(
                    playerTarget,
                    validOrdinaryMonster ? ordinaryMonsterTarget : null,
                    null, null, castNow, spell.skillId());
            if (playerTarget != null) {
                playerTarget.cancelSleep(
                        "classic-world-probability-spell-" + spell.skillId());
            }
        }

        boolean countered = playerTarget != null
                && (confusion == null || confusionSuccess)
                && (thunderGrab == null || !thunderGrab.counterMagicBypass())
                && playerTarget.timedStatus.consumeCounterMagic(castNow);
        if (countered) {
            publishCounterMagicConsumption(playerTarget, spell.skillId());
            broadcastCounteredSpellAction(
                    spell.actionId(), spell.skillId(), spell.key());
            publishClassicWorldAttackSpellResources(
                    spell, remainingHp, remainingMp, "countered");
            System.out.println("[LiTo] C_USE_SPELL classic-world attack countered"
                    + " skill=" + spell.skillId() + " caster=" + playerName()
                    + " target=" + playerTarget.playerName() + " damage=0"
                    + " mp=" + remainingMp + "/" + playerMaxMp);
            return;
        }

        BattleEraseMagicStatus.Lease eraseMagicLease = playerTarget != null
                ? playerTarget.eraseMagicStatus.capture(castNow)
                : controlledCompanion != null
                    ? controlledCompanion.captureEraseMagic(castNow)
                : castleTrebuchetTarget || castleTowerTarget || validCastleDoor
                    ? BattleEraseMagicStatus.Lease.none()
                : hub.captureClassicWorldMonsterEraseMagic(
                        classicWorldMapId, classicWorldInstanceId,
                        monsterTarget.objectId(), castNow);

        MindBreakTargetMpDebit mindBreakDebit = null;
        if (mindBreak != null) {
            int requestedDrain = rollMindBreakTargetMpDrain(mindBreak);
            mindBreakDebit = debitClassicWorldMindBreakTargetMp(
                    requestedDrain, playerTarget, controlledCompanion,
                    validMonster ? monsterTarget : null,
                    castleTrebuchetTarget,
                    "classic-world-skill-" + spell.skillId());
        }

        boolean specialCritical = spell.specialCritical(
                sides -> ThreadLocalRandom.current().nextInt(1, sides + 1));
        int npcElementalStatusModifier = validOrdinaryMonster
                ? hub.classicWorldMonsterElementalFallDownModifier(
                        classicWorldMapId, classicWorldInstanceId,
                        monsterTarget.objectId(), spell.attribute(), castNow)
                : 0;
        int targetElementalResistance = playerTarget != null
                ? playerTarget.effectiveSpellElementalResistance(spell.attribute())
                : npcStats == null ? npcElementalStatusModifier
                    : ClassicWorldMonsterMagicDamage.npcElementalResistance(
                            npcStats.weakAttribute(), spell.attribute(),
                            npcElementalStatusModifier);
        int baseTargetMagicResistance = playerTarget != null
                ? playerTarget.effectiveBaseMagicResistance(castNow)
                : npcStats == null ? 0 : npcStats.magicResistance();
        int targetMagicResistance = playerTarget != null
                ? baseTargetMagicResistance
                : controlledCompanion != null
                    ? controlledCompanion.effectiveMagicResistance(
                            baseTargetMagicResistance, castNow)
                : castleTrebuchetTarget || castleTowerTarget || validCastleDoor
                    ? baseTargetMagicResistance
                : hub.classicWorldMonsterEffectiveMagicResistance(
                        classicWorldMapId, classicWorldInstanceId,
                        monsterTarget.objectId(), baseTargetMagicResistance,
                        castNow);
        int targetArmorReductionBase = playerTarget == null ? 0
                : playerTarget.effectiveArmorMagicReductionBase();
        int damage;
        int boneBreakFirstDamage = 0;
        if (confusion != null) {
            damage = 0;
        } else if (mindBreak != null) {
            damage = mindBreakDebit != null && mindBreakDebit.debited()
                    ? ordinaryMagicDamage(
                            spell.skillId(), spell.attribute(), sourceDamage,
                            targetElementalResistance, targetMagicResistance,
                            targetArmorReductionBase,
                            playerTarget == null ? "classic-world-npc="
                                    + request.targetObjectId()
                                    : "classic-world-player="
                                        + playerTarget.playerName())
                    : 0;
        } else if (spell.finalBurn()) {
            int reductionOffset = targetArmorReductionBase > 10
                    ? ThreadLocalRandom.current().nextInt(
                            targetArmorReductionBase - 10) : 0;
            damage = BattleFinalBurn.resolve(
                    sourceDamage, targetArmorReductionBase, reductionOffset,
                    targetMagicResistance, originalMagicHit()).damage();
        } else if (boneBreak != null || armBreaker != null) {
            boneBreakFirstDamage = ordinaryMagicDamage(
                    spell.skillId(), spell.attribute(), sourceDamage,
                    targetElementalResistance, targetMagicResistance,
                    targetArmorReductionBase,
                    playerTarget == null ? (boneBreak != null
                            ? "classic-world-bone-first-npc="
                            : "classic-world-arm-breaker-first-npc=")
                            + request.targetObjectId()
                            : (boneBreak != null
                                ? "classic-world-bone-first-player="
                                : "classic-world-arm-breaker-first-player=")
                                + playerTarget.playerName());
            damage = ordinaryMagicDamage(
                    spell.skillId(), spell.attribute(), sourceDamage,
                    targetElementalResistance, targetMagicResistance,
                    targetArmorReductionBase,
                    playerTarget == null ? (boneBreak != null
                            ? "classic-world-bone-mode-npc="
                            : "classic-world-arm-breaker-mode-npc=")
                            + request.targetObjectId()
                            : (boneBreak != null
                                ? "classic-world-bone-mode-player="
                                : "classic-world-arm-breaker-mode-player=")
                                + playerTarget.playerName());
        } else {
            damage = ordinaryMagicDamage(
                    spell.skillId(), spell.attribute(), sourceDamage,
                    targetElementalResistance, targetMagicResistance,
                    targetArmorReductionBase,
                    playerTarget == null ? "classic-world-npc="
                            + request.targetObjectId()
                            : "classic-world-player=" + playerTarget.playerName());
        }
        damage = spell.damageAfterSpecialCritical(damage, specialCritical);
        BattleCounterMirrorStatus.Decision counterMirror = null;
        BattleCounterMirrorStatus.Decision boneBreakFirstMirror = null;
        if (playerTarget != null
                && (boneBreak != null || armBreaker != null)) {
            int firstMirrorDamage = playerTarget.combatDamageAfterCooking(
                    boneBreakFirstDamage,
                    (boneBreak != null
                            ? "classic-world-bone-break-first-"
                            : "classic-world-arm-breaker-first-")
                            + spell.skillId());
            firstMirrorDamage = playerTarget.earthBindProtectedCombatDamage(
                    firstMirrorDamage,
                    (boneBreak != null
                            ? "classic-world-bone-break-first-"
                            : "classic-world-arm-breaker-first-")
                            + spell.skillId());
            boneBreakFirstMirror = playerTarget.counterMirrorDecision(
                    firstMirrorDamage, true,
                    ThreadLocalRandom.current().nextInt(100), castNow);
            if (boneBreakFirstMirror.triggered()) {
                publishPlayerCounterMirrorTrigger(
                        playerTarget, boneBreakFirstMirror,
                        (boneBreak != null
                                ? "classic-world-bone-break-first-"
                                : "classic-world-arm-breaker-first-")
                                + spell.skillId());
            }
        }
        if (playerTarget != null && mindBreak != null) {
            int mirrorEligibleDamage = playerTarget
                    .earthBindProtectedCombatDamage(
                            damage, "classic-world-mind-break-pre-multiplier");
            counterMirror = playerTarget.counterMirrorDecision(
                    mirrorEligibleDamage, true,
                    ThreadLocalRandom.current().nextInt(100), castNow);
            if (counterMirror.triggered()) {
                publishPlayerCounterMirrorTrigger(
                        playerTarget, counterMirror,
                        "classic-world-mind-break-" + spell.skillId());
                damage = 0;
            } else {
                damage = mindBreak.damageAfterMultiplier(
                        mirrorEligibleDamage);
            }
        } else if (mindBreak != null) {
            damage = mindBreak.damageAfterMultiplier(damage);
        }
        if (playerTarget != null) {
            damage = playerTarget.combatDamageAfterCooking(
                    damage, "classic-world-attack-spell-" + spell.skillId());
            damage = playerTarget.earthBindProtectedCombatDamage(
                    damage, "classic-world-attack-spell-" + spell.skillId());
        } else if (!validCastleDoor && !castleTowerTarget
                && !classicWorldCkewAttackAllowed(npcId, castNow)) {
            damage = 0;
        }

        if (playerTarget != null && mindBreak == null) {
            counterMirror = playerTarget.counterMirrorDecision(
                    damage, true, ThreadLocalRandom.current().nextInt(100),
                    castNow);
            if (counterMirror.triggered()) {
                publishPlayerCounterMirrorTrigger(
                        playerTarget, counterMirror,
                        "classic-world-attack-spell-" + spell.skillId());
                damage = 0;
            }
        }

        BoneBreakApplication boneBreakApplication = boneBreak == null
                ? BoneBreakApplication.ineligible()
                : applyClassicWorldBoneBreak(
                        boneBreak, playerTarget, controlledCompanion,
                        validMonster ? monsterTarget : null,
                        castleTrebuchetTarget,
                        request.targetObjectId(), targetX, targetY,
                        castNow, config.boneBreakFixtureD1000(), worldMembers);
        BattleArmBreakerStatus.Activation armBreakerActivation =
                armBreaker == null
                    ? BattleArmBreakerStatus.Activation.rejected()
                    : playerTarget != null
                        ? playerTarget.armBreakerStatus.activateIfAbsent(
                                castNow, armBreaker.durationSeconds())
                        : controlledCompanion != null
                            ? controlledCompanion.activateArmBreaker(
                                    castNow, armBreaker.durationSeconds())
                            : castleTrebuchetTarget
                                ? hub.armBreakerClassicCastleTrebuchet(
                                        selectedClassicServerName,
                                        classicWorldMapId,
                                        monsterTarget.objectId(), castNow,
                                        armBreaker.durationSeconds())
                                : validOrdinaryMonster
                                    ? hub.armBreakerClassicWorldMonster(
                                            classicWorldMapId,
                                            classicWorldInstanceId,
                                            monsterTarget.objectId(), castNow,
                                            armBreaker.durationSeconds())
                                : BattleArmBreakerStatus.Activation.rejected();

        int attackHeading = heading(positionX, positionY, targetX, targetY);
        playerHeading = attackHeading;
        long sequence = ATTACK_SPELL_SEQUENCE.incrementAndGet();
        int effectGfx = spell.effectGfx(specialCritical);
        byte[] attack = Protocol.attackSpell(
                spell.actionId(), playerObjectId(), request.targetObjectId(),
                damage > 0 ? 10 : 0, attackHeading, sequence, effectGfx,
                positionX, positionY, targetX, targetY);
        publishClassicWorldAttackSpellPacket(attack, targetX, targetY,
                "resolved skill=" + spell.skillId() + " target="
                        + request.targetObjectId() + " damage=" + damage
                        + " gfx=" + effectGfx + " target-mr="
                        + targetMagicResistance + " sequence=" + sequence);
        publishClassicWorldAttackSpellResources(
                spell, remainingHp, remainingMp, "resolved");

        boolean confusionApplied = false;
        int lifeDrainHealing = 0;
        if (playerTarget != null) {
            if (damage > 0) {
                int targetHpBefore = playerTarget.playerHp;
                playerTarget.takeClassicWorldPlayerDamage(damage, this, false);
                if (playerTarget.playerHp < targetHpBefore) {
                    lifeDrainHealing = applyAcceptedLifeDrain(
                            spell, damage, "classic-world-player");
                }
                if (thunderGrab != null && playerTarget.playerHp > 0) {
                    applyPlayerThunderGrab(playerTarget, thunderGrab,
                            casterLevel, castNow, -1, -1,
                            "classic-world-attack-spell");
                }
            }
            playerTarget.eraseMagicStatus.consume(eraseMagicLease);
            if (confusionSuccess && playerTarget.playerHp > 0) {
                confusionApplied = playerTarget.timedStatus
                        .activateSilenceIfAbsent(
                                castNow, confusion.durationSeconds());
                if (confusionApplied) {
                    playerTarget.sendEncrypted(
                            Protocol.messageCode(confusion.targetMessageCode()),
                            "S_MESSAGE_CODE classic-world-Confusion-target="
                                    + confusion.targetMessageCode());
                }
            }
        } else if (controlledCompanion != null && companionTarget != null
                && companionOwner != null) {
            controlledCompanion.consumeEraseMagic(eraseMagicLease);
            if (damage > 0) {
                int targetHpBefore = controlledCompanion.snapshot().hp();
                controlledCompanion.selectMasterTarget(playerObjectId());
                companionOwner.applyClassicWorldMonsterCompanionDamage(
                        controlledCompanion, companionTarget, damage,
                        playerObjectId(), "attack-spell-" + spell.skillId());
                if (controlledCompanion.snapshot().hp() < targetHpBefore) {
                    lifeDrainHealing = applyAcceptedLifeDrain(
                            spell, damage, "classic-world-companion");
                }
                if (thunderGrab != null) {
                    BattleCompanion.Snapshot after =
                            controlledCompanion.snapshot();
                    boolean bossTarget = npcStats != null && npcStats.boss();
                    int duration = !after.active() || after.hp() <= 0 ? 0
                            : rollNpcThunderGrabDuration(thunderGrab,
                                    casterLevel, companionTarget.level(),
                                    bossTarget,
                                    config.thunderGrabFixtureD100() > 0
                                            ? config.thunderGrabFixtureD100() : -1,
                                    config.thunderGrabFixtureDurationOffset(),
                                    companionTarget.objectId(),
                                    "classic-world-companion");
                    if (duration > 0 && controlledCompanion
                            .activateThunderGrab(castNow, duration)) {
                        System.out.println("[LiTo] Thunder Grab NPC MOVE_STOP"
                                + " activated target="
                                + companionTarget.objectId()
                                + " source=classic-world-companion duration="
                                + duration);
                    }
                }
            }
        } else if (castleTowerTarget) {
            int acceptedDamage = applyClassicWorldCastleTowerMagicDamage(
                    castleTowerSnapshot, damage);
            if (acceptedDamage > 0) {
                lifeDrainHealing = applyAcceptedLifeDrain(
                        spell, damage, "classic-world-castle-tower");
            }
        } else if (validCastleDoor) {
            if (dwarfCastleDoorTarget != null) {
                ClassicWorldDwarfCastleDoorState.DoorHit doorHit = damage <= 0
                        ? null : hub.damageDwarfCastleDoor(
                                classicWorldMapId,
                                castleDoorTarget.objectId(), damage);
                if (doorHit != null && doorHit.appliedDamage() > 0) {
                    publishDwarfCastleDoorHit(doorHit);
                    lifeDrainHealing = applyAcceptedLifeDrain(
                            spell, damage, "classic-world-dwarf-castle-door");
                }
            } else {
                ClassicWorldCastleDoorCombat.Hit doorHit = damage <= 0
                        ? null : hub.damageMainlandCastleDoor(
                                mainlandCastleDoorTarget.view().definition().family(),
                                classicWorldMapId,
                                castleDoorTarget.objectId(), damage);
                if (doorHit != null && doorHit.appliedDamage() > 0) {
                    publishMainlandCastleDoorHit(doorHit);
                    lifeDrainHealing = applyAcceptedLifeDrain(
                            spell, damage, "classic-world-mainland-castle-door");
                }
            }
        } else if (castleTrebuchetTarget) {
            ClassicWorldCastleWarField.TrebuchetHit trebuchetHit = damage <= 0
                    ? null : hub.damageClassicCastleTrebuchet(
                            selectedClassicServerName, classicWorldMapId,
                            monsterTarget.objectId(), damage);
            if (trebuchetHit != null && trebuchetHit.appliedDamage() > 0) {
                publishClassicCastleTrebuchetHit(trebuchetHit);
                lifeDrainHealing = applyAcceptedLifeDrain(
                        spell, damage, "classic-world-castle-trebuchet");
                if (trebuchetHit.diedNow()) {
                    hub.scheduleClassicCastleTrebuchetCorpseRemoval(
                            selectedClassicServerName, trebuchetHit.after());
                }
            }
            if (confusionSuccess) {
                confusionApplied = hub.confusionSilenceClassicCastleTrebuchet(
                        selectedClassicServerName, classicWorldMapId,
                        monsterTarget.objectId(), castNow,
                        confusion.durationSeconds());
            }
            if (thunderGrab != null && trebuchetHit != null
                    && trebuchetHit.after().currentHp() > 0) {
                boolean bossTarget = monsterTarget.template().boss()
                        || npcStats != null && npcStats.boss();
                int duration = rollNpcThunderGrabDuration(
                        thunderGrab, casterLevel, monsterTarget.template().level(),
                        bossTarget,
                        config.thunderGrabFixtureD100() > 0
                                ? config.thunderGrabFixtureD100() : -1,
                        config.thunderGrabFixtureDurationOffset(),
                        monsterTarget.objectId(),
                        "classic-castle-trebuchet");
                if (duration > 0 && hub.thunderGrabClassicCastleTrebuchet(
                        selectedClassicServerName, classicWorldMapId,
                        monsterTarget.objectId(), castNow, duration)) {
                    System.out.println("[LiTo] Thunder Grab NPC MOVE_STOP"
                            + " activated target=" + monsterTarget.objectId()
                            + " source=classic-castle-trebuchet duration="
                            + duration);
                }
            }
        } else {
            ClassicWorldMonsterPopulation.Hit transition = damage <= 0 ? null
                    : hub.damageClassicWorldMonster(
                            classicWorldMapId, classicWorldInstanceId,
                            monsterTarget.objectId(), playerObjectId(), damage);
            hub.consumeClassicWorldMonsterEraseMagic(
                    classicWorldMapId, classicWorldInstanceId,
                    monsterTarget.objectId(), eraseMagicLease);
            if (confusionSuccess) {
                confusionApplied = hub.confusionSilenceClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        monsterTarget.objectId(), castNow,
                        confusion.durationSeconds());
            }
            if (transition != null) {
                if (transition.after().currentHp()
                        < transition.before().currentHp()) {
                    lifeDrainHealing = applyAcceptedLifeDrain(
                            spell, damage, "classic-world-monster");
                }
                hub.provokeClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        monsterTarget.objectId(), playerObjectId());
                for (BattleCompanion.Snapshot companion
                        : classicWorldCompanionSnapshots()) {
                    BattleCompanion controlled = ownedCompanion(companion.objectId());
                    if (controlled != null) {
                        controlled.selectMasterTarget(monsterTarget.objectId());
                    }
                }
                publishClassicWorldSpellMonsterDamage(
                        spell.skillId(), transition);
                if (thunderGrab != null && transition.after().alive()) {
                    boolean bossTarget = monsterTarget.template().boss()
                            || npcStats != null && npcStats.boss();
                    int duration = rollNpcThunderGrabDuration(thunderGrab,
                            casterLevel, monsterTarget.template().level(),
                            bossTarget,
                            config.thunderGrabFixtureD100() > 0
                                    ? config.thunderGrabFixtureD100() : -1,
                            config.thunderGrabFixtureDurationOffset(),
                            monsterTarget.objectId(),
                            "classic-world-monster");
                    if (duration > 0 && hub.thunderGrabClassicWorldMonster(
                            classicWorldMapId, classicWorldInstanceId,
                            monsterTarget.objectId(), castNow, duration)) {
                        System.out.println("[LiTo] Thunder Grab NPC MOVE_STOP"
                                + " activated target=" + monsterTarget.objectId()
                                + " source=classic-world-monster duration="
                                + duration);
                    }
                }
            }
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale classic-world"
                    + " attack coordinates skill=" + spell.skillId() + " client="
                    + request.x() + "," + request.y() + " server="
                    + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world attack skill="
                + spell.skillId() + " caster=" + playerName() + " target="
                + request.targetObjectId() + " npc=" + npcId + " player-target="
                + (playerTarget != null) + " companion-target="
                + (companionTarget != null) + " castle-trebuchet-target="
                + castleTrebuchetTarget + " castle-tower-target="
                + castleTowerTarget + " castle-door-target="
                + validCastleDoor + " damage=" + damage
                + " special-critical=" + specialCritical + " gfx=" + effectGfx
                + " counter-mirror-active="
                + (counterMirror != null && counterMirror.active())
                + " counter-mirror-triggered="
                + (counterMirror != null && counterMirror.triggered())
                + " bone-break-first-mirror-triggered="
                + (boneBreakFirstMirror != null
                    && boneBreakFirstMirror.triggered())
                + " bone-break-eligible="
                + boneBreakApplication.targetEligible()
                + " bone-break-already-active="
                + boneBreakApplication.alreadyActive()
                + " bone-break-roll=" + boneBreakApplication.roll()
                + " bone-break-applied=" + boneBreakApplication.applied()
                + " bone-break-effect="
                + boneBreakApplication.effectObjectId()
                + " arm-breaker-applied="
                + (armBreakerActivation.accepted()
                    && !armBreakerActivation.alreadyActive())
                + " arm-breaker-already-active="
                + armBreakerActivation.alreadyActive()
                + " life-drain-healing=" + lifeDrainHealing
                + " target-mr=" + targetMagicResistance + " mp-cost=" + mpCost
                + " confusion-probability="
                + (confusion == null ? "n/a" : confusion.chancePercent(
                        confusionBossTarget))
                + " confusion-roll="
                + (confusion == null ? "n/a" : confusionRoll)
                + " confusion-success=" + confusionSuccess
                + " confusion-applied=" + confusionApplied
                + " confusion-earth-bind-blocked=" + confusionEarthBindBlocked
                + " mind-break-target-mp="
                + (mindBreakDebit == null ? "n/a"
                    : mindBreakDebit.before() + "->" + mindBreakDebit.after()
                        + "/requested=" + mindBreakDebit.requested()
                        + "/debited=" + mindBreakDebit.debited()
                        + "/kind=" + mindBreakDebit.kind())
                + " hp=" + remainingHp + "/" + playerMaxHp + " mp="
                + remainingMp + "/" + playerMaxMp);
    }

    private BoneBreakApplication applyClassicWorldBoneBreak(
            BattleSpellCatalog.BoneBreakSpell spell,
            ClientSession playerTarget,
            BattleCompanion controlledCompanion,
            ClassicWorldMonsterPopulation.Snapshot monsterTarget,
            boolean castleTrebuchetTarget,
            long targetObjectId, int targetX, int targetY,
            long nowNanos, int rollFixture,
            List<ClientSession> worldMembers) throws IOException {
        boolean eligible = playerTarget != null
                ? playerTarget.phase == Phase.WORLD
                    && playerTarget.playerHp > 0
                    && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                            playerTarget.timedStatus.absoluteBarrierActive(
                                    nowNanos), spell.skillId())
                : controlledCompanion != null
                    ? controlledCompanion.snapshot().active()
                        && controlledCompanion.snapshot().hp() > 0
                    : monsterTarget != null && monsterTarget.present()
                        && monsterTarget.alive();
        if (!eligible) return BoneBreakApplication.ineligible();

        boolean alreadyActive = playerTarget != null
                ? playerTarget.timedStatus.boneBreakActive(nowNanos)
                : controlledCompanion != null
                    ? controlledCompanion.boneBreakActive(nowNanos)
                    : castleTrebuchetTarget
                        ? hub.classicCastleTrebuchetBoneBreakActive(
                                selectedClassicServerName, classicWorldMapId,
                                monsterTarget.objectId(), nowNanos)
                        : hub.classicWorldMonsterBoneBreakActive(
                                classicWorldMapId, classicWorldInstanceId,
                                monsterTarget.objectId(), nowNanos);
        if (alreadyActive) {
            return new BoneBreakApplication(true, true, 0, false, 0);
        }
        int roll = rollFixture > 0 ? rollFixture
                : ThreadLocalRandom.current().nextInt(
                        spell.minimumRoll(), spell.maximumRoll() + 1);
        if (!spell.succeeds(roll)) {
            return new BoneBreakApplication(true, false, roll, false, 0);
        }
        boolean activated = playerTarget != null
                ? playerTarget.timedStatus.activateBoneBreak(
                        nowNanos, spell.durationSeconds())
                : controlledCompanion != null
                    ? controlledCompanion.activateBoneBreak(
                            nowNanos, spell.durationSeconds())
                    : castleTrebuchetTarget
                        ? hub.boneBreakClassicCastleTrebuchet(
                                selectedClassicServerName, classicWorldMapId,
                                monsterTarget.objectId(), nowNanos,
                                spell.durationSeconds())
                        : hub.boneBreakClassicWorldMonster(
                                classicWorldMapId, classicWorldInstanceId,
                                monsterTarget.objectId(), nowNanos,
                                spell.durationSeconds());
        if (!activated) {
            return new BoneBreakApplication(true, true, roll, false, 0);
        }
        BattleBoneBreakEffects.Effect effect =
                hub.placeClassicWorldBoneBreakEffect(
                        classicWorldMapId, classicWorldInstanceId,
                        targetObjectId, targetX, targetY,
                        nowNanos, spell.durationSeconds());
        if (effect == null) {
            throw new IllegalStateException(
                    "classic-world Bone Break status activated without effect");
        }
        byte[] put = Protocol.boneBreakEffect(effect);
        for (ClientSession member : worldMembers) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            targetX, targetY)) continue;
            member.sendEncrypted(put,
                    "S_PUT_OBJECT classic-world Bone Break effect="
                            + effect.objectId() + " target=" + targetObjectId
                            + " npc=" + spell.effectNpcId()
                            + " gfx=" + spell.effectNpcGfx()
                            + " duration=" + spell.durationSeconds());
        }
        if (playerTarget != null) {
            playerTarget.sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.STUN_APPLY),
                    "S_PARALYSE mode=22 classic-world Bone Break duration="
                            + spell.durationSeconds());
        }
        return new BoneBreakApplication(
                true, false, roll, true, effect.objectId());
    }

    private void publishClassicWorldAttackSpellPacket(
            byte[] packet, int targetX, int targetY, String reason)
            throws IOException {
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, positionX, positionY)
                        && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, targetX, targetY)) {
                continue;
            }
            member.sendEncrypted(packet,
                    "S_ATTACK classic-world spell " + reason);
        }
    }

    private void publishClassicWorldAttackSpellResources(
            BattleSpellCatalog.AttackSpell spell,
            int remainingHp, int remainingMp, String reason) throws IOException {
        BattleSpellCatalog.ThunderGrabSpell thunderGrab =
                BattleSpellCatalog.thunderGrabSpell(spell.skillId());
        BattleSpellCatalog.ConfusionSpell confusion =
                BattleSpellCatalog.confusionSpell(spell.skillId());
        BattleSpellCatalog.MindBreakSpell mindBreak =
                BattleSpellCatalog.mindBreakSpell(spell.skillId());
        if (spell.finalBurn()
                || thunderGrab != null && thunderGrab.hpCost() > 0
                || confusion != null && confusion.hpCost() > 0
                || mindBreak != null && mindBreak.hpCost() > 0) {
            sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                            .h(remainingHp).h(playerMaxHp).bytes(),
                    "S_HIT_POINT classic-world attack-spell-" + reason + "="
                            + remainingHp + "/" + playerMaxHp);
            broadcastOwnHitRatio("classic-world-attack-spell-hp-cost-" + reason);
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world attack-spell-" + reason + "="
                        + remainingMp + "/" + playerMaxMp);
    }

    /**
     * Retained CHILL_TOUCH/VAMPIRIC_TOUCH semantics: the caster receives the
     * final positive magic damage after the target commit is accepted.  The
     * requested damage is intentionally used rather than the target's
     * remaining HP; L1SkillUse passes its calculated _dmg to
     * adjustCurrentHpIfAlive after an accepted terminal hit as well.
     */
    private int applyAcceptedLifeDrain(
            BattleSpellCatalog.AttackSpell spell, int damage, String reason)
            throws IOException {
        if (!spell.drainsLife() || damage <= 0) return 0;
        int before;
        int after;
        synchronized (this) {
            if (playerHp <= 0) return 0;
            before = playerHp;
            playerHp = (int) Math.min((long) playerMaxHp,
                    Math.addExact((long) playerHp, (long) damage));
            after = playerHp;
        }
        if (after == before) return 0;
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(after).h(playerMaxHp).bytes(),
                "S_HIT_POINT life-drain skill=" + spell.skillId()
                        + " reason=" + reason + " restored=" + (after - before)
                        + " hp=" + after + "/" + playerMaxHp);
        broadcastOwnHitRatio("life-drain-" + spell.skillId() + "-" + reason);
        return after - before;
    }

    private void publishClassicWorldSpellMonsterDamage(
            int skillId, ClassicWorldMonsterPopulation.Hit transition)
            throws IOException {
        ClassicWorldMonsterPopulation.Snapshot after = transition.after();
        byte[] ratio = Protocol.hitRatio(
                after.objectId(), after.currentHp(), after.maximumHp());
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            after.x(), after.y())) continue;
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO classic-world-monster=" + after.objectId()
                            + " hp=" + after.currentHp() + "/" + after.maximumHp()
                            + " source=spell-" + skillId);
            if (transition.diedNow()) {
                member.sendEncrypted(Protocol.objectAction(
                                after.objectId(), BattleActionCodes.DIE),
                        "S_ACTION classic-world-monster=" + after.objectId()
                                + " action=" + BattleActionCodes.DIE
                                + " source=spell-" + skillId);
            }
        }
        System.out.println("[LiTo] classic-world spell damaged monster player="
                + playerName() + " skill=" + skillId + " object="
                + after.objectId() + " npc=" + after.npcId() + " damage="
                + transition.appliedDamage() + " hp=" + after.currentHp() + "/"
                + after.maximumHp() + " died=" + transition.diedNow());
        if (transition.diedNow()) {
            handleClassicWorldWaterDragonDeath(after, transition.contributions());
            distributeClassicWorldMonsterRewards(after, transition.contributions());
            hub.scheduleClassicWorldMonsterLifecycle(classicWorldInstanceId, after);
        }
    }

    /**
     * Environmental L1Bow damage has a null attacker in the retained server:
     * it publishes HP/death and normal corpse lifecycle, but creates no hate,
     * experience, lawful or drop recipient.
     */
    void serverClassicWorldBowMonsterDamage(
            ClassicWorldNpcCatalog.StaticNpc bow,
            ClassicWorldMonsterPopulation.Hit transition) throws IOException {
        if (!ClassicWorldBowCatalog.isBow(bow) || transition == null
                || phase != Phase.WORLD || classicWorldMapId != bow.mapId()) return;
        ClassicWorldMonsterPopulation.Snapshot after = transition.after();
        byte[] ratio = Protocol.hitRatio(
                after.objectId(), after.currentHp(), after.maximumHp());
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            after.x(), after.y())) continue;
            try {
                member.sendEncrypted(ratio,
                        "S_HIT_RATIO classic-world-monster=" + after.objectId()
                                + " hp=" + after.currentHp() + "/" + after.maximumHp()
                                + " source=bow-aperture-" + bow.spawnId());
                if (transition.diedNow()) {
                    member.sendEncrypted(Protocol.objectAction(
                                    after.objectId(), BattleActionCodes.DIE),
                            "S_ACTION classic-world-monster=" + after.objectId()
                                    + " action=" + BattleActionCodes.DIE
                                    + " source=bow-aperture-" + bow.spawnId());
                }
            } catch (IOException disconnectedViewer) {
                // Retained world broadcast continues past a viewer that left
                // concurrently with this environmental damage pass.
            }
        }
        System.out.println("[LiTo] classic-world bow damaged monster bow="
                + bow.objectId() + " spawn=" + bow.spawnId() + " object="
                + after.objectId() + " npc=" + after.npcId() + " damage="
                + transition.appliedDamage() + " hp=" + after.currentHp() + "/"
                + after.maximumHp() + " died=" + transition.diedNow()
                + " contributor=none");
        if (transition.diedNow()) {
            hub.scheduleClassicWorldMonsterLifecycle(classicWorldInstanceId, after);
        }
    }

    /** Retained skill-11 target path for ordinary classic WORLD actors. */
    private void useClassicWorldPoisonSpell(
            byte[] payload, BattleSpellCatalog.PoisonSpell spell)
            throws IOException {
        // Exact selected LiTo.bin zero-based case10 enters loc_4CB938 and
        // sub_4CA6E0, which emits cccdhh rather than the target-only cccd
        // accepted by the retained older C_UseSkill parser.
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-Curse-Poison-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-Curse-Poison-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-Curse-Poison-silenced-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-Curse-Poison-silenced-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE classic-world-Curse-Poison-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Curse Poison rejected"
                    + " learned/action player=" + playerName());
            return;
        }

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        ClientSession playerTarget = classicWorldMembers(originMapId).stream()
                .filter(candidate -> candidate != this
                        && sameClassicWorldMap(candidate)
                        && candidate.playerObjectId()
                            == request.targetObjectId())
                .findFirst().orElse(null);
        ClassicWorldMonsterPopulation.Snapshot monsterTarget =
                hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId());
        if (playerTarget == null && (monsterTarget == null
                || !monsterTarget.present() || !monsterTarget.alive()
                || monsterTarget.mapId() != originMapId)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Curse Poison"
                    + " rejected target=" + request.targetObjectId());
            return;
        }

        int targetX = playerTarget != null
                ? playerTarget.positionX : monsterTarget.x();
        int targetY = playerTarget != null
                ? playerTarget.positionY : monsterTarget.y();
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale classic-world"
                    + " Curse Poison coordinates target=" + request.targetObjectId()
                    + " client=" + request.x() + "," + request.y()
                    + " server=" + targetX + "," + targetY);
        }
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        boolean livingTarget = playerTarget == null
                || playerTarget.phase == Phase.WORLD
                    && playerTarget.playerHp > 0
                    && !playerTarget.observer
                    && !playerTarget.invisible
                    && sameClassicWorldMap(playerTarget)
                    && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                            playerTarget.timedStatus.absoluteBarrierActive(
                                    requestNow), spell.skillId());
        boolean safetyBlocked = playerTarget != null
                && (map.isSafetyZone(positionX, positionY)
                    || map.isSafetyZone(targetX, targetY));
        if (!livingTarget || safetyBlocked
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY)
                || !map.attackPosition(positionX, positionY,
                        targetX, targetY, spell.maximumRange())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Curse Poison"
                    + " rejected gate/range target=" + request.targetObjectId()
                    + " player-target=" + (playerTarget != null)
                    + " safety=" + safetyBlocked);
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int npcId = monsterTarget == null ? 0 : monsterTarget.npcId();
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected classic-world Curse Poison;"
                        + " source NPC lookup failed player=" + playerName()
                        + " npc=" + npcId + " reason="
                        + sourceFailure.getClass().getSimpleName() + ": "
                        + sourceFailure.getMessage());
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment =
                requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);
        BattleEraseMagicStatus.Lease eraseMagicLease = playerTarget != null
                ? playerTarget.eraseMagicStatus.capture(requestNow)
                : hub.captureClassicWorldMonsterEraseMagic(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), requestNow);
        int baseTargetMr = playerTarget != null
                ? playerTarget.effectiveBaseMagicResistance(requestNow)
                : npcStats == null ? 0 : npcStats.magicResistance();
        int targetMr = playerTarget != null ? baseTargetMr
                : hub.classicWorldMonsterEffectiveMagicResistance(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), baseTargetMr, requestNow);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(requestNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        boolean bossImmune = monsterTarget != null
                && (monsterTarget.template().boss()
                    || npcStats != null && npcStats.boss());
        int configuredDieRoll = config.cursePoisonFixtureDieRoll();
        int probability = spell.probability(
                casterType, casterLevel, effectiveIntelligence,
                originalMagicHit(), totalMagicHit, targetMr, bossImmune,
                sides -> configuredDieRoll == 0
                        ? ThreadLocalRandom.current().nextInt(1, sides + 1)
                        : configuredDieRoll);
        int configuredPercentile = config.cursePoisonFixturePercentileRoll();
        int percentileRoll = bossImmune ? 100 : configuredPercentile == 0
                ? ThreadLocalRandom.current().nextInt(1, 101)
                : configuredPercentile;

        RuntimeInventory previousInventory;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || playerHp <= 0
                    || observer || phase != Phase.WORLD
                    || classicWorldMapId != originMapId
                    || classicWorldInstanceId != originInstanceId) {
                System.out.println("[LiTo] C_USE_SPELL classic-world Curse Poison"
                        + " rejected state mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE classic-world-Curse-Poison-missing-reagent=299");
                return;
            }
            cancelMeditation("classic-world-spell-" + spell.skillId());
            previousInventory = inventory;
            inventory = nextInventory;
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());

        boolean earthBindBlocked = playerTarget != null
                && playerTarget.timedStatus.earthBindActive(castNow);
        boolean probabilitySuccess = !earthBindBlocked && !bossImmune
                && BattleTurnUndead.succeeds(probability, percentileRoll);
        if (playerTarget != null) {
            playerTarget.eraseMagicStatus.consume(eraseMagicLease);
            playerTarget.cancelSleep(
                    "classic-world-probability-spell-" + spell.skillId());
        } else {
            hub.consumeClassicWorldMonsterEraseMagic(
                    originMapId, originInstanceId,
                    monsterTarget.objectId(), eraseMagicLease);
        }
        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        applySpellLawfulDelta(spell.lawfulDelta(), spell.key());

        List<ClientSession> recipients = classicWorldMembers(originMapId);
        byte[] action = Protocol.objectAction(
                playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY)
                        && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            targetX, targetY)) continue;
            member.sendEncrypted(action,
                    "S_ACTION classic-world Curse-Poison caster="
                            + playerObjectId() + " action=" + spell.actionId());
        }

        boolean countered = probabilitySuccess && playerTarget != null
                && playerTarget.timedStatus.consumeCounterMagic(castNow);
        boolean poisonBlocked = false;
        boolean applied = false;
        if (countered) {
            publishCounterMagicConsumption(playerTarget, spell.skillId());
        } else if (probabilitySuccess && playerTarget != null) {
            synchronized (playerTarget) {
                poisonBlocked = playerTarget.timedStatus.poisonActive(castNow)
                        || !playerTarget.timedStatus.acceptsPoison(
                                castNow,
                                BattleTimedStatus.PoisonKind.DAMAGE)
                        || playerTarget.dragonEyeStatus.snapshot(castNow)
                                .poisonResistance() > 0;
                if (!poisonBlocked) {
                    applied = playerTarget.timedStatus.activatePoison(
                            castNow, spell.durationSeconds(),
                            spell.tickIntervalMillis());
                    if (applied) playerTarget.poisonAttacker = this;
                }
            }
        } else if (probabilitySuccess) {
            poisonBlocked = hub.classicWorldMonsterPoisonActive(
                    originMapId, originInstanceId,
                    monsterTarget.objectId(), castNow);
            applied = !poisonBlocked && hub.poisonClassicWorldMonster(
                    originMapId, originInstanceId, monsterTarget.objectId(),
                    playerObjectId(), castNow, spell.durationSeconds(),
                    spell.tickIntervalMillis());
            if (applied) {
                hub.provokeClassicWorldMonster(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), playerObjectId());
            }
        }

        boolean accepted = probabilitySuccess && !countered;
        if (accepted) {
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                targetX, targetY)) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT classic-world Curse-Poison target="
                                + request.targetObjectId() + " gfx="
                                + spell.effectGfx());
            }
        }
        if (applied) {
            int palette = playerTarget != null
                    ? playerTarget.currentPoisonPalette(castNow)
                    : hub.classicWorldMonsterPoisonPalette(
                            originMapId, originInstanceId,
                            monsterTarget.objectId(), castNow);
            byte[] poison = Protocol.poison(
                    request.targetObjectId(), palette);
            for (ClientSession member : recipients) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                targetX, targetY)) continue;
                member.sendEncrypted(poison,
                        "S_POISON classic-world target="
                                + request.targetObjectId() + " type=" + palette
                                + " skill=" + spell.skillId());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world Curse-Poison=" + remainingMp
                        + "/" + playerMaxMp);
        if (!accepted) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE classic-world-Curse-Poison-failure="
                            + spell.failureMessage());
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world Curse Poison skill="
                + spell.skillId() + " caster=" + playerName() + " target="
                + request.targetObjectId() + " npc=" + npcId
                + " player-target=" + (playerTarget != null)
                + " probability=" + probability + " roll=" + percentileRoll
                + " probability-success=" + probabilitySuccess
                + " accepted=" + accepted + " applied=" + applied
                + " poison-blocked=" + poisonBlocked + " countered="
                + countered + " boss-immune=" + bossImmune
                + " earth-bind-blocked=" + earthBindBlocked + " mr="
                + targetMr + " duration=" + spell.durationSeconds()
                + " tick-ms=" + spell.tickIntervalMillis() + " damage="
                + spell.tickDamage() + " mp-cost=" + mpCost + " mp="
                + remainingMp + "/" + playerMaxMp);
    }

    private void usePoisonSpell(byte[] payload,
                                BattleSpellCatalog.PoisonSpell spell) throws IOException {
        // Exact selected LiTo.bin case10 uses the shared object-coordinate
        // producer. Server-resolved actor coordinates remain authoritative.
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        ClientSession target = hub.roomCombatants(currentRoomId).stream()
                .filter(candidate -> candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        BattleQuestEncounter.Snapshot questTarget =
                hub.questMonster(currentRoomId, request.targetObjectId());
        BattleTimeAttackEncounter.Snapshot timeTarget =
                hub.timeAttackActor(currentRoomId, request.targetObjectId());
        if (target == this || (target == null && questTarget == null && timeTarget == null)) {
            System.out.println("[LiTo] C_USE_SPELL poison rejected target="
                    + request.targetObjectId());
            return;
        }

        int targetX = target != null ? target.positionX
                : questTarget != null ? questTarget.x() : timeTarget.x();
        int targetY = target != null ? target.positionY
                : questTarget != null ? questTarget.y() : timeTarget.y();
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale poison coordinates"
                    + " target=" + request.targetObjectId() + " client="
                    + request.x() + "," + request.y() + " server="
                    + targetX + "," + targetY);
        }
        boolean targetGate = target != null
                ? target.phase == Phase.BATTLE && target.playerHp > 0
                    && !target.invisible && hub.canAttack(currentRoomId, this, target)
                : questTarget != null
                    ? hub.canAttackQuestMonster(
                            currentRoomId, this, questTarget.objectId())
                    : hub.canAttackTimeAttackActor(
                            currentRoomId, this, timeTarget.objectId());
        int range = Math.max(Math.abs(positionX - targetX),
                Math.abs(positionY - targetY));
        if (!targetGate || range > spell.maximumRange()) {
            System.out.println("[LiTo] C_USE_SPELL poison rejected gate/range target="
                    + request.targetObjectId() + " range=" + range
                    + " max=" + spell.maximumRange());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL poison rejected unavailable action player="
                    + playerName() + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int npcId = questTarget != null ? questTarget.npcId()
                : timeTarget != null ? timeTarget.npcId() : 0;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected poison; source NPC lookup failed"
                        + " player=" + playerName() + " npc=" + npcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
        }

        long gateNow = System.nanoTime();
        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        int targetMr = target != null
                ? target.effectiveBaseMagicResistance(gateNow)
                : effectiveNpcMagicResistance(
                        questTarget, timeTarget,
                        npcStats == null ? 0 : npcStats.magicResistance(), gateNow);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(gateNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        boolean bossImmune = (npcStats != null && npcStats.boss())
                || (timeTarget != null && timeTarget.finalBoss());
        int configuredDieRoll = config.cursePoisonFixtureDieRoll();
        int probability = spell.probability(
                casterType, casterLevel, effectiveIntelligence,
                originalMagicHit(), totalMagicHit, targetMr, bossImmune,
                sides -> configuredDieRoll == 0
                        ? ThreadLocalRandom.current().nextInt(1, sides + 1)
                        : configuredDieRoll);
        int configuredPercentile = config.cursePoisonFixturePercentileRoll();
        int percentileRoll = bossImmune ? 100 : configuredPercentile == 0
                ? ThreadLocalRandom.current().nextInt(1, 101) : configuredPercentile;

        RuntimeInventory previousInventory;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost
                    || phase != Phase.BATTLE || playerHp <= 0) {
                System.out.println("[LiTo] C_USE_SPELL poison rejected state skill="
                        + spell.skillId() + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE poison-missing-reagent=299");
                System.out.println("[LiTo] C_USE_SPELL poison rejected missing reagent catalog="
                        + spell.itemConsumeId() + " count=" + spell.itemConsumeCount());
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            cancelAbsoluteBarrier("spell-" + spell.skillId());
            previousInventory = inventory;
            inventory = nextInventory;
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        boolean earthBindBlocked = earthBindBlocksProbabilityMagic(
                target, questTarget, timeTarget, castNow, spell.skillId());
        boolean probabilitySuccess = !earthBindBlocked && !bossImmune
                && BattleTurnUndead.succeeds(probability, percentileRoll);
        consumeEraseMagicAfterProbability(
                target, questTarget, timeTarget, castNow, spell.skillId());
        breakSleepForStatusSpell(target, questTarget, timeTarget,
                "probability-spell-" + spell.skillId());
        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        applySpellLawfulDelta(spell.lawfulDelta(), spell.key());

        List<ClientSession> recipients = questTarget != null
                ? hub.battleRecipients(currentRoomId, questTarget.force())
                : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            member.sendEncrypted(action, "S_ACTION poison-cast object=" + playerObjectId()
                    + " action=" + spell.actionId());
        }

        boolean countered = probabilitySuccess && target != null
                && target.timedStatus.consumeCounterMagic(castNow);
        boolean poisonBlocked = false;
        boolean applied = false;
        if (countered) {
            publishCounterMagicConsumption(target, spell.skillId());
        } else if (probabilitySuccess && target != null) {
            synchronized (target) {
                poisonBlocked = target.timedStatus.poisonActive(castNow)
                        || !target.timedStatus.acceptsPoison(
                                castNow, BattleTimedStatus.PoisonKind.DAMAGE)
                        || target.dragonEyeStatus.snapshot(castNow)
                                .poisonResistance() > 0;
                if (!poisonBlocked) {
                    applied = target.timedStatus.activatePoison(
                            castNow, spell.durationSeconds(), spell.tickIntervalMillis());
                    if (applied) target.poisonAttacker = this;
                }
            }
        } else if (probabilitySuccess && questTarget != null) {
            poisonBlocked = hub.questMonsterPoisonActive(
                    currentRoomId, questTarget.objectId(), castNow);
            applied = !poisonBlocked && hub.poisonQuestMonster(
                    currentRoomId, this, questTarget.objectId(), castNow,
                    spell.durationSeconds(), spell.tickIntervalMillis());
        } else if (probabilitySuccess && timeTarget != null) {
            poisonBlocked = hub.timeAttackActorPoisonActive(
                    currentRoomId, timeTarget.objectId(), castNow);
            applied = !poisonBlocked && hub.poisonTimeAttackActor(
                    currentRoomId, this, timeTarget.objectId(), castNow,
                    spell.durationSeconds(), spell.tickIntervalMillis());
        }

        boolean accepted = probabilitySuccess && !countered;
        if (accepted) {
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(effect,
                        "S_EFFECT poison target=" + request.targetObjectId()
                                + " gfx=" + spell.effectGfx());
            }
        }
        if (applied) {
            int palette = target != null ? target.currentPoisonPalette(castNow)
                    : questTarget != null ? hub.questMonsterPoisonPalette(
                            currentRoomId, questTarget.objectId(), castNow)
                    : hub.timeAttackActorPoisonPalette(
                            currentRoomId, timeTarget.objectId(), castNow);
            byte[] poison = Protocol.poison(request.targetObjectId(), palette);
            for (ClientSession member : recipients) {
                member.sendEncrypted(poison,
                        "S_POISON target=" + request.targetObjectId()
                                + " type=" + palette + " skill=" + spell.skillId());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT poison-spell=" + remainingMp + "/" + playerMaxMp);
        if (!accepted) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE poison-failure=" + spell.failureMessage());
        }
        System.out.println("[LiTo] C_USE_SPELL poison skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + request.targetObjectId()
                + " npc=" + npcId + " probability=" + probability
                + " roll=" + percentileRoll + " probability-success="
                + probabilitySuccess + " accepted=" + accepted
                + " applied=" + applied + " poison-blocked=" + poisonBlocked
                + " countered=" + countered + " boss-immune=" + bossImmune
                + " earth-bind-blocked=" + earthBindBlocked + " mr=" + targetMr
                + " equipment-magic-hit=" + equipmentMagicHit
                + " buff-magic-hit=" + buffMagicHit
                + " total-magic-hit=" + totalMagicHit
                + " duration=" + spell.durationSeconds() + " tick-ms="
                + spell.tickIntervalMillis() + " damage=" + spell.tickDamage()
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    /** Retained skill-33 path for ordinary classic WORLD players and monsters. */
    private void useClassicWorldParalysisSpell(
            byte[] payload, BattleSpellCatalog.ParalysisSpell spell)
            throws IOException {
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-Curse-Paralysis-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-Curse-Paralysis-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-Curse-Paralysis-silenced-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-Curse-Paralysis-silenced-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE classic-world-Curse-Paralysis-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Curse Paralysis"
                    + " rejected learned/action player=" + playerName());
            return;
        }

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        ClientSession playerTarget = classicWorldMembers(originMapId).stream()
                .filter(candidate -> candidate != this
                        && sameClassicWorldMap(candidate)
                        && candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        ClassicWorldMonsterPopulation.Snapshot monsterTarget =
                hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId());
        if (playerTarget == null && (monsterTarget == null
                || !monsterTarget.present() || !monsterTarget.alive()
                || monsterTarget.mapId() != originMapId)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Curse Paralysis"
                    + " rejected target=" + request.targetObjectId());
            return;
        }

        int targetX = playerTarget != null
                ? playerTarget.positionX : monsterTarget.x();
        int targetY = playerTarget != null
                ? playerTarget.positionY : monsterTarget.y();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        boolean livingTarget = playerTarget == null
                || playerTarget.phase == Phase.WORLD
                    && playerTarget.playerHp > 0
                    && !playerTarget.observer
                    && !playerTarget.invisible
                    && sameClassicWorldMap(playerTarget)
                    && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                            playerTarget.timedStatus.absoluteBarrierActive(
                                    requestNow), spell.skillId());
        boolean safetyBlocked = playerTarget != null
                && (map.isSafetyZone(positionX, positionY)
                    || map.isSafetyZone(targetX, targetY));
        if (!livingTarget || safetyBlocked
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY)
                || !map.attackPosition(positionX, positionY,
                        targetX, targetY, spell.maximumRange())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Curse Paralysis"
                    + " rejected gate/range target=" + request.targetObjectId()
                    + " player-target=" + (playerTarget != null)
                    + " safety=" + safetyBlocked);
            return;
        }
        boolean alreadyParalyzed = playerTarget != null
                ? playerTarget.timedStatus.paralysisVisualActive(requestNow)
                : hub.classicWorldMonsterParalysisActive(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), requestNow);
        if (alreadyParalyzed) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Curse Paralysis"
                    + " rejected same-status target=" + request.targetObjectId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int npcId = monsterTarget == null ? 0 : monsterTarget.npcId();
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected classic-world Curse Paralysis;"
                        + " source NPC lookup failed player=" + playerName()
                        + " npc=" + npcId + " reason="
                        + sourceFailure.getClass().getSimpleName() + ": "
                        + sourceFailure.getMessage());
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment =
                requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);
        CharacterSummary targetCharacter = playerTarget == null
                ? null : playerTarget.selectedCharacterSummary();
        int targetLevel = playerTarget != null
                ? targetCharacter == null ? 1
                    : Math.max(1, targetCharacter.level())
                : Math.max(1, monsterTarget.template().level());
        BattleEraseMagicStatus.Lease eraseMagicLease = playerTarget != null
                ? playerTarget.eraseMagicStatus.capture(requestNow)
                : hub.captureClassicWorldMonsterEraseMagic(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), requestNow);
        int baseTargetMr = playerTarget != null
                ? playerTarget.effectiveBaseMagicResistance(requestNow)
                : npcStats == null ? 0 : npcStats.magicResistance();
        int targetMr = playerTarget != null ? baseTargetMr
                : hub.classicWorldMonsterEffectiveMagicResistance(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), baseTargetMr, requestNow);
        int targetStoneResistance = playerTarget == null ? 0
                : Math.max(-128, Math.min(127,
                        playerTarget.requiredEquipmentMagicStats()
                                .totalStoneResistance()
                        + playerTarget.dragonEyeStatus.snapshot(requestNow)
                                .stoneResistance()));
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(requestNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int magicLevel = spell.includeMagicLevel()
                ? BattleTurnUndead.magicLevel(casterType, casterLevel) : 0;
        boolean bossImmune = monsterTarget != null
                && (monsterTarget.template().boss()
                    || npcStats != null && npcStats.boss());
        int probability = bossImmune ? 0 : spell.probability(
                casterLevel, targetLevel, effectiveIntelligence,
                magicLevel, totalMagicHit, targetMr, targetStoneResistance);
        int configuredPercentile =
                config.curseParalysisFixturePercentileRoll();
        int percentileRoll = bossImmune ? 100 : configuredPercentile == 0
                ? ThreadLocalRandom.current().nextInt(1, 101)
                : configuredPercentile;

        RuntimeInventory previousInventory;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || playerHp <= 0
                    || observer || phase != Phase.WORLD
                    || classicWorldMapId != originMapId
                    || classicWorldInstanceId != originInstanceId) {
                System.out.println("[LiTo] C_USE_SPELL classic-world Curse Paralysis"
                        + " rejected state mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE classic-world-Curse-Paralysis-missing-reagent=299");
                return;
            }
            cancelMeditation("classic-world-spell-" + spell.skillId());
            previousInventory = inventory;
            inventory = nextInventory;
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());

        boolean earthBindBlocked = playerTarget != null
                && playerTarget.timedStatus.earthBindActive(castNow);
        boolean freezeBlocked = playerTarget != null
                && playerTarget.timedStatus.freezeActive(castNow);
        boolean probabilitySuccess = !earthBindBlocked && !freezeBlocked
                && !bossImmune && probability >= percentileRoll;
        if (playerTarget != null) {
            playerTarget.eraseMagicStatus.consume(eraseMagicLease);
            playerTarget.cancelSleep(
                    "classic-world-probability-spell-" + spell.skillId());
        } else {
            hub.consumeClassicWorldMonsterEraseMagic(
                    originMapId, originInstanceId,
                    monsterTarget.objectId(), eraseMagicLease);
        }
        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        applySpellLawfulDelta(spell.lawfulDelta(), spell.key());

        List<ClientSession> recipients = classicWorldMembers(originMapId);
        byte[] action = Protocol.objectAction(
                playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY)
                        && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            targetX, targetY)) continue;
            member.sendEncrypted(action,
                    "S_ACTION classic-world Curse-Paralysis caster="
                            + playerObjectId() + " action=" + spell.actionId());
        }

        boolean countered = probabilitySuccess && playerTarget != null
                && playerTarget.timedStatus.consumeCounterMagic(castNow);
        boolean applied = false;
        if (countered) {
            publishCounterMagicConsumption(playerTarget, spell.skillId());
        } else if (probabilitySuccess && playerTarget != null) {
            applied = playerTarget.timedStatus.activateParalysis(
                    castNow, spell.warningDelayMillis(),
                    spell.paralysisDurationMillis());
        } else if (probabilitySuccess) {
            applied = hub.paralyzeClassicWorldMonster(
                    originMapId, originInstanceId, monsterTarget.objectId(),
                    castNow, spell.paralysisDurationMillis());
            if (applied) {
                hub.provokeClassicWorldMonster(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), playerObjectId());
            }
        }

        if (applied) {
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                targetX, targetY)) continue;
                member.sendEncrypted(effect,
                        "S_EFFECT classic-world Curse-Paralysis target="
                                + request.targetObjectId() + " gfx="
                                + spell.effectGfx());
            }
            if (playerTarget != null) {
                playerTarget.sendEncrypted(Protocol.messageCode(212),
                        "S_MESSAGE_CODE classic-world-paralysis-warning=212");
                playerTarget.broadcastPoisonState(
                        playerTarget.currentPoisonPalette(castNow),
                        "classic-world-curse-paralysis-warning");
            } else {
                int palette = hub.classicWorldMonsterPoisonPalette(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), castNow);
                byte[] poison = Protocol.poison(
                        monsterTarget.objectId(), palette);
                for (ClientSession member : recipients) {
                    if (!sameClassicWorldMap(member)
                            || !BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    targetX, targetY)) continue;
                    member.sendEncrypted(poison,
                            "S_POISON classic-world-monster="
                                    + monsterTarget.objectId() + " type="
                                    + palette + " reason=curse-paralysis-33");
                }
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world Curse-Paralysis=" + remainingMp
                        + "/" + playerMaxMp);
        if (!applied) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE classic-world-Curse-Paralysis-failure="
                            + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale classic-world"
                    + " Curse-Paralysis coordinates client=" + request.x() + ","
                    + request.y() + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world Curse Paralysis skill="
                + spell.skillId() + " caster=" + playerName() + " target="
                + request.targetObjectId() + " npc=" + npcId
                + " player-target=" + (playerTarget != null)
                + " probability=" + probability + " roll=" + percentileRoll
                + " probability-success=" + probabilitySuccess
                + " applied=" + applied + " countered=" + countered
                + " boss-immune=" + bossImmune
                + " earth-bind-blocked=" + earthBindBlocked
                + " freeze-blocked=" + freezeBlocked + " mr=" + targetMr
                + " stone-resistance=" + targetStoneResistance
                + " warning-ms=" + (playerTarget == null
                    ? 0 : spell.warningDelayMillis())
                + " active-ms=" + spell.paralysisDurationMillis()
                + " lawful-delta=" + spell.lawfulDelta()
                + " mp-cost=" + mpCost + " mp=" + remainingMp
                + "/" + playerMaxMp);
    }

    private void useParalysisSpell(byte[] payload,
                                   BattleSpellCatalog.ParalysisSpell spell)
            throws IOException {
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        ClientSession target = hub.roomCombatants(currentRoomId).stream()
                .filter(candidate -> candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        BattleQuestEncounter.Snapshot questTarget =
                hub.questMonster(currentRoomId, request.targetObjectId());
        BattleTimeAttackEncounter.Snapshot timeTarget =
                hub.timeAttackActor(currentRoomId, request.targetObjectId());
        if (target == this || (target == null && questTarget == null && timeTarget == null)) {
            System.out.println("[LiTo] C_USE_SPELL paralysis rejected target="
                    + request.targetObjectId());
            return;
        }

        int targetX = target != null ? target.positionX
                : questTarget != null ? questTarget.x() : timeTarget.x();
        int targetY = target != null ? target.positionY
                : questTarget != null ? questTarget.y() : timeTarget.y();
        boolean targetGate = target != null
                ? target.phase == Phase.BATTLE && target.playerHp > 0
                    && !target.invisible && hub.canAttack(currentRoomId, this, target)
                : questTarget != null
                    ? hub.canAttackQuestMonster(
                            currentRoomId, this, questTarget.objectId())
                    : hub.canAttackTimeAttackActor(
                            currentRoomId, this, timeTarget.objectId());
        int range = Math.max(Math.abs(positionX - targetX),
                Math.abs(positionY - targetY));
        if (!targetGate || range > spell.maximumRange()) {
            System.out.println("[LiTo] C_USE_SPELL paralysis rejected gate/range target="
                    + request.targetObjectId() + " range=" + range
                    + " max=" + spell.maximumRange());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL paralysis rejected unavailable action player="
                    + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        long gateNow = System.nanoTime();
        boolean alreadyParalyzed = target != null
                ? target.timedStatus.paralysisVisualActive(gateNow)
                : questTarget != null
                    ? hub.questMonsterParalysisActive(
                            currentRoomId, questTarget.objectId(), gateNow)
                    : hub.timeAttackActorParalysisActive(
                            currentRoomId, timeTarget.objectId(), gateNow);
        if (alreadyParalyzed) {
            System.out.println("[LiTo] C_USE_SPELL paralysis rejected same-status target="
                    + request.targetObjectId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int npcId = questTarget != null ? questTarget.npcId()
                : timeTarget != null ? timeTarget.npcId() : 0;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected paralysis; source NPC lookup failed"
                        + " player=" + playerName() + " npc=" + npcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        CharacterSummary targetCharacter = target == null
                ? null : target.selectedCharacterSummary();
        int targetLevel = target != null
                ? targetCharacter == null ? 1 : Math.max(1, targetCharacter.level())
                : questTarget != null ? questTarget.level() : timeTarget.level();
        long targetMrNow = System.nanoTime();
        int targetMr = target != null
                ? target.effectiveBaseMagicResistance(targetMrNow)
                : effectiveNpcMagicResistance(
                        questTarget, timeTarget,
                        npcStats == null ? 0 : npcStats.magicResistance(),
                        targetMrNow);
        int targetStoneResistance = target == null ? 0
                : Math.max(-128, Math.min(127,
                        target.requiredEquipmentMagicStats().totalStoneResistance()
                        + target.dragonEyeStatus.snapshot(gateNow).stoneResistance()));
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(gateNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int magicLevel = spell.includeMagicLevel()
                ? BattleTurnUndead.magicLevel(casterType, casterLevel) : 0;
        boolean bossImmune = timeTarget != null && timeTarget.finalBoss();
        int probability = bossImmune ? 0 : spell.probability(
                casterLevel, Math.max(1, targetLevel), effectiveIntelligence,
                magicLevel, totalMagicHit, targetMr, targetStoneResistance);
        int configuredPercentile =
                config.curseParalysisFixturePercentileRoll();
        int percentileRoll = bossImmune ? 100 : configuredPercentile == 0
                ? ThreadLocalRandom.current().nextInt(1, 101)
                : configuredPercentile;

        RuntimeInventory previousInventory;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost
                    || phase != Phase.BATTLE || playerHp <= 0) {
                System.out.println("[LiTo] C_USE_SPELL paralysis rejected state skill="
                        + spell.skillId() + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE paralysis-missing-reagent=299");
                System.out.println("[LiTo] C_USE_SPELL paralysis rejected missing reagent catalog="
                        + spell.itemConsumeId() + " count=" + spell.itemConsumeCount());
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            previousInventory = inventory;
            inventory = nextInventory;
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        boolean earthBindBlocked = earthBindBlocksProbabilityMagic(
                target, questTarget, timeTarget, castNow, spell.skillId());
        boolean freezeBlocked = target != null
                ? target.timedStatus.freezeActive(castNow)
                : questTarget != null
                    ? hub.questMonsterFreezeActive(
                            currentRoomId, questTarget.objectId(), castNow)
                    : hub.timeAttackActorFreezeActive(
                            currentRoomId, timeTarget.objectId(), castNow);
        boolean probabilitySuccess = !earthBindBlocked && !freezeBlocked
                && !bossImmune && probability >= percentileRoll;
        consumeEraseMagicAfterProbability(
                target, questTarget, timeTarget, castNow, spell.skillId());

        breakSleepForStatusSpell(target, questTarget, timeTarget,
                "probability-spell-" + spell.skillId());
        sendInventoryDelta(previousInventory, inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        applySpellLawfulDelta(spell.lawfulDelta(), spell.key());

        List<ClientSession> recipients = questTarget != null
                ? hub.battleRecipients(currentRoomId, questTarget.force())
                : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION paralysis caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        boolean countered = probabilitySuccess && target != null
                && target.timedStatus.consumeCounterMagic(castNow);
        boolean applied = false;
        if (countered) {
            publishCounterMagicConsumption(target, spell.skillId());
        } else if (probabilitySuccess && target != null) {
            applied = target.timedStatus.activateParalysis(
                    castNow, spell.warningDelayMillis(),
                    spell.paralysisDurationMillis());
        } else if (probabilitySuccess && questTarget != null) {
            applied = hub.paralyzeQuestMonster(currentRoomId, this,
                    questTarget.objectId(), castNow,
                    spell.paralysisDurationMillis());
        } else if (probabilitySuccess && timeTarget != null) {
            applied = hub.paralyzeTimeAttackActor(currentRoomId, this,
                    timeTarget.objectId(), castNow,
                    spell.paralysisDurationMillis());
        }

        if (applied) {
            byte[] effect = Protocol.effectObject(
                    request.targetObjectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(effect,
                        "S_EFFECT paralysis target=" + request.targetObjectId()
                                + " gfx=" + spell.effectGfx());
            }
            if (target != null) {
                target.sendEncrypted(Protocol.messageCode(212),
                        "S_MESSAGE_CODE paralysis-warning=212");
                target.broadcastPoisonState(2, "curse-paralysis-warning");
            } else {
                byte[] poison = Protocol.poison(request.targetObjectId(), 2);
                for (ClientSession member : recipients) {
                    member.sendEncrypted(poison,
                            "S_POISON paralysis target=" + request.targetObjectId()
                                    + " type=2");
                }
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT paralysis-spell=" + remainingMp + "/" + playerMaxMp);
        if (!applied) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE paralysis-failure=" + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale paralysis coordinates skill="
                    + spell.skillId() + " client=" + request.x() + "," + request.y()
                    + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL paralysis skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + request.targetObjectId()
                + " npc=" + npcId + " probability=" + probability
                + " roll=" + percentileRoll + " probability-success="
                + probabilitySuccess + " applied=" + applied
                + " countered=" + countered + " boss-immune=" + bossImmune
                + " earth-bind-blocked=" + earthBindBlocked
                + " freeze-blocked=" + freezeBlocked + " mr=" + targetMr
                + " stone-resistance=" + targetStoneResistance
                + " equipment-magic-hit=" + equipmentMagicHit
                + " buff-magic-hit=" + buffMagicHit
                + " total-magic-hit=" + totalMagicHit
                + " warning-ms=" + spell.warningDelayMillis()
                + " active-ms=" + spell.paralysisDurationMillis()
                + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    /** Retained skill-37 cure path for WORLD players and monster poison. */
    private void useClassicWorldCurseRemovalSpell(
            byte[] payload, BattleSpellCatalog.CurseRemovalSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-Remove-Curse-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-Remove-Curse-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-Remove-Curse-silenced-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-Remove-Curse-silenced-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE classic-world-Remove-Curse-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Remove Curse"
                    + " rejected learned/action player=" + playerName());
            return;
        }

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        ClientSession playerTarget = classicWorldMembers(originMapId).stream()
                .filter(candidate -> sameClassicWorldMap(candidate)
                        && candidate.playerObjectId()
                            == request.targetObjectId())
                .findFirst().orElse(null);
        ClientSession companionOwner = null;
        BattleCompanion controlledCompanion = null;
        BattleCompanion.Snapshot companionTarget = null;
        for (ClientSession candidate : classicWorldMembers(originMapId)) {
            if (!sameClassicWorldMap(candidate)) continue;
            BattleCompanion controlled =
                    candidate.ownedCompanion(request.targetObjectId());
            BattleCompanion.Snapshot snapshot = controlled == null
                    ? null : controlled.snapshot();
            if (snapshot == null || !snapshot.active() || snapshot.hp() <= 0
                    || !snapshot.kind().classicWorldEligible()) continue;
            companionOwner = candidate;
            controlledCompanion = controlled;
            companionTarget = snapshot;
            break;
        }
        ClassicWorldMonsterPopulation.Snapshot monsterTarget =
                hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId());
        if (playerTarget == null && companionTarget == null
                && (monsterTarget == null
                || !monsterTarget.present() || !monsterTarget.alive()
                || monsterTarget.mapId() != originMapId)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Remove Curse"
                    + " rejected target=" + request.targetObjectId());
            return;
        }
        int targetX = playerTarget != null
                ? playerTarget.positionX
                : companionTarget != null ? companionTarget.x() : monsterTarget.x();
        int targetY = playerTarget != null
                ? playerTarget.positionY
                : companionTarget != null ? companionTarget.y() : monsterTarget.y();
        boolean livingTarget = playerTarget == null
                ? companionTarget != null
                    || monsterTarget != null && monsterTarget.alive()
                : playerTarget.phase == Phase.WORLD
                    && !playerTarget.observer && playerTarget.playerHp > 0
                    && sameClassicWorldMap(playerTarget);
        if (!livingTarget || !BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world Remove Curse"
                    + " rejected gate/screen target="
                    + request.targetObjectId());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment =
                requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || playerHp <= 0
                    || observer || phase != Phase.WORLD
                    || classicWorldMapId != originMapId
                    || classicWorldInstanceId != originInstanceId) {
                System.out.println("[LiTo] C_USE_SPELL classic-world Remove Curse"
                        + " rejected state mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            cancelMeditation("classic-world-spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());

        List<ClientSession> recipients = classicWorldMembers(originMapId);
        byte[] action = Protocol.objectAction(
                playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(
                request.targetObjectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY)
                        && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            targetX, targetY)) continue;
            member.sendEncrypted(action,
                    "S_ACTION classic-world Remove-Curse caster="
                            + playerObjectId() + " action=" + spell.actionId());
            member.sendEncrypted(effect,
                    "S_EFFECT classic-world Remove-Curse target="
                            + request.targetObjectId() + " gfx="
                            + spell.effectGfx());
        }

        boolean poisonCured = false;
        boolean paralysisCured = false;
        if (playerTarget != null) {
            boolean poisonParalysis = playerTarget.classicWorldPoisonKind
                    == ClassicWorldMonsterPoisonAttack.Kind.PARALYSIS;
            BattleTimedStatus.ParalysisCancellation cancellation;
            if (spell.curesCurseParalysis()) {
                BattleTimedStatus.CurseRemoval removal =
                        playerTarget.timedStatus.removeCurse();
                poisonCured = removal.poisonCured();
                cancellation = removal.paralysisCancellation();
            } else {
                poisonCured = playerTarget.timedStatus.curePoison()
                        | playerTarget.timedStatus.curePoisonSilence();
                cancellation = poisonParalysis
                        ? playerTarget.timedStatus.cancelParalysis()
                        : new BattleTimedStatus.ParalysisCancellation(false, false);
            }
            paralysisCured = cancellation.present();
            if (poisonCured || poisonParalysis && paralysisCured) {
                playerTarget.poisonAttacker = null;
                playerTarget.classicWorldPoisonAttackerObjectId = 0;
                playerTarget.classicWorldPoisonKind =
                        ClassicWorldMonsterPoisonAttack.Kind.NONE;
            }
            if (paralysisCured) {
                playerTarget.sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.PARALYSIS_RELEASE),
                        "S_PARALYSE mode=3 reason=classic-world-"
                                + spell.key());
            }
            if (poisonCured || paralysisCured) {
                playerTarget.broadcastPoisonState(
                        playerTarget.currentPoisonPalette(System.nanoTime()),
                        "classic-world-" + spell.key());
            }
        } else if (companionTarget != null) {
            BattleCompanion.NpcPoisonCancellation cancellation =
                    controlledCompanion.removeCurseNpcPoison(
                            spell.curesCurseParalysis());
            poisonCured = cancellation.poison();
            paralysisCured = cancellation.paralysis();
            if (poisonCured || paralysisCured) {
                byte[] clear = Protocol.poison(companionTarget.objectId(), 0);
                for (ClientSession member : recipients) {
                    if (!sameClassicWorldMap(member)
                            || !BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    targetX, targetY)) continue;
                    member.sendEncrypted(clear,
                            "S_POISON classic-world-companion="
                                    + companionTarget.objectId()
                                    + " type=0 reason=" + spell.key());
                }
            }
        } else {
            poisonCured = hub.cureClassicWorldMonsterPoison(
                    originMapId, originInstanceId, monsterTarget.objectId());
            BattleTimedStatus.ParalysisCancellation cancellation =
                    spell.curesCurseParalysis()
                    ? hub.cureClassicWorldMonsterParalysis(
                            originMapId, originInstanceId,
                            monsterTarget.objectId())
                    : new BattleTimedStatus.ParalysisCancellation(false, false);
            paralysisCured = cancellation.present();
            if (poisonCured || paralysisCured) {
                int palette = hub.classicWorldMonsterPoisonPalette(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), System.nanoTime());
                byte[] clear = Protocol.poison(
                        monsterTarget.objectId(), palette);
                for (ClientSession member : recipients) {
                    if (!sameClassicWorldMap(member)
                            || !BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    targetX, targetY)) continue;
                    member.sendEncrypted(clear,
                            "S_POISON classic-world-monster="
                                    + monsterTarget.objectId() + " type="
                                    + palette + " reason=" + spell.key());
                }
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world Remove-Curse=" + remainingMp
                        + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL classic-world Remove Curse skill="
                + spell.skillId() + " caster=" + playerName() + " target="
                + request.targetObjectId() + " player-target="
                + (playerTarget != null) + " companion-target="
                + (companionTarget != null) + " companion-owner="
                + (companionOwner == null ? "" : companionOwner.playerName())
                + " poison-cured=" + poisonCured
                + " paralysis-cured=" + paralysisCured + " mp-cost="
                + mpCost + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    private void useCurseRemovalSpell(
            byte[] payload, BattleSpellCatalog.CurseRemovalSpell spell) throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Remove-Curse-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Remove-Curse-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Remove-Curse-silenced-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Remove-Curse-silenced-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE Remove-Curse-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL remove-curse"
                    + " rejected learned/action player=" + playerName());
            return;
        }

        List<ClientSession> visibleCombatants =
                hub.visibleBattleCombatants(currentRoomId, this);
        ClientSession playerTarget = visibleCombatants.stream()
                .filter(candidate -> candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        BattleQuestEncounter.Snapshot questTarget = hub.visibleQuestMonsters(
                        currentRoomId, this).stream()
                .filter(candidate -> candidate.objectId() == request.targetObjectId())
                .findFirst().orElse(null);
        BattleTimeAttackEncounter.Snapshot timeTarget = hub.visibleTimeAttackActors(
                        currentRoomId, this).stream()
                .filter(candidate -> candidate.objectId() == request.targetObjectId())
                .findFirst().orElse(null);
        BattleGuardianTower.Snapshot towerTarget = hub.visibleGuardianTowers(
                        currentRoomId, this).stream()
                .filter(candidate -> candidate.objectId() == request.targetObjectId())
                .findFirst().orElse(null);

        ClientSession companionOwner = null;
        BattleCompanion.Snapshot companionTarget = null;
        for (ClientSession candidate : visibleCombatants) {
            BattleCompanion.Snapshot match = candidate.controlledCompanionSnapshots().stream()
                    .filter(companion -> companion.objectId() == request.targetObjectId())
                    .findFirst().orElse(null);
            if (match != null) {
                companionOwner = candidate;
                companionTarget = match;
                break;
            }
        }

        boolean botTarget = request.targetObjectId() == 2
                && hub.roomRules(currentRoomId).mode() != BattleRules.Mode.QUEST_BATTLE
                && hub.roomRules(currentRoomId).mode() != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(currentRoomId) < 2
                && hub.botHp(currentRoomId) > 0;
        ArenaMapCatalog.Point botPosition = botTarget
                ? hub.botPosition(currentRoomId) : null;

        int targetX;
        int targetY;
        if (playerTarget != null) {
            targetX = playerTarget.positionX;
            targetY = playerTarget.positionY;
        } else if (questTarget != null) {
            targetX = questTarget.x();
            targetY = questTarget.y();
        } else if (timeTarget != null) {
            targetX = timeTarget.x();
            targetY = timeTarget.y();
        } else if (towerTarget != null) {
            targetX = towerTarget.x();
            targetY = towerTarget.y();
        } else if (companionTarget != null) {
            targetX = companionTarget.x();
            targetY = companionTarget.y();
        } else if (botPosition != null) {
            targetX = botPosition.x();
            targetY = botPosition.y();
        } else {
            System.out.println("[LiTo] C_USE_SPELL remove-curse rejected unknown target="
                    + request.targetObjectId());
            return;
        }

        boolean sameMap = playerTarget == null || hub.battleMapId(currentRoomId, this)
                == hub.battleMapId(currentRoomId, playerTarget);
        if (companionOwner != null) {
            sameMap &= hub.battleMapId(currentRoomId, this)
                    == hub.battleMapId(currentRoomId, companionOwner);
        }
        boolean livingTarget = playerTarget != null
                ? playerTarget.phase == Phase.BATTLE && !playerTarget.observer
                    && !playerTarget.invisible && playerTarget.playerHp > 0
                : questTarget != null ? questTarget.alive()
                : timeTarget != null ? timeTarget.alive()
                : towerTarget != null ? towerTarget.hp() > 0
                : companionTarget != null ? companionTarget.active() && companionTarget.hp() > 0
                : botTarget;
        if (!sameMap || !livingTarget || !BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL remove-curse rejected gate/screen target="
                    + request.targetObjectId() + " same-map=" + sameMap
                    + " living=" + livingTarget);
            return;
        }
        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost
                    || phase != Phase.BATTLE || observer || playerHp <= 0) {
                System.out.println("[LiTo] C_USE_SPELL remove-curse rejected state skill="
                        + spell.skillId() + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        int targetForce = questTarget != null ? questTarget.force()
                : towerTarget != null ? towerTarget.force()
                : companionOwner != null ? hub.forceOf(currentRoomId, companionOwner)
                : -1;
        List<ClientSession> recipients = targetForce >= 0
                && hub.roomRules(currentRoomId).mode() == BattleRules.Mode.QUEST_BATTLE
                ? hub.battleRecipients(currentRoomId, targetForce)
                : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(
                request.targetObjectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION remove-curse caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT remove-curse target=" + request.targetObjectId()
                            + " gfx=" + spell.effectGfx());
        }

        boolean poisonCured = false;
        boolean paralysisCured = false;
        if (playerTarget != null) {
            BattleTimedStatus.ParalysisCancellation cancellation;
            if (spell.curesCurseParalysis()) {
                BattleTimedStatus.CurseRemoval removal =
                        playerTarget.timedStatus.removeCurse();
                poisonCured = removal.poisonCured();
                cancellation = removal.paralysisCancellation();
            } else {
                poisonCured = playerTarget.timedStatus.curePoison()
                        | playerTarget.timedStatus.curePoisonSilence();
                cancellation = new BattleTimedStatus.ParalysisCancellation(false, false);
            }
            if (poisonCured) playerTarget.poisonAttacker = null;
            paralysisCured = cancellation.present();
            if (paralysisCured) {
                // Retained L1CurseParalysis.cure sends TYPE_PARALYSIS=false
                // even during the warning phase; LiTo maps that to mode 3.
                playerTarget.sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.PARALYSIS_RELEASE),
                        "S_PARALYSE mode=3 reason=" + spell.key());
            }
            if (poisonCured || paralysisCured) {
                playerTarget.broadcastPoisonState(
                        playerTarget.currentPoisonPalette(System.nanoTime()),
                        spell.key());
            }
        } else if (questTarget != null) {
            poisonCured = hub.cureQuestMonsterPoison(
                    currentRoomId, questTarget.objectId());
            paralysisCured = spell.curesCurseParalysis()
                    && hub.cancelQuestMonsterParalysis(
                            currentRoomId, questTarget.objectId());
            if (poisonCured || paralysisCured) {
                int palette = hub.questMonsterPoisonPalette(
                        currentRoomId, questTarget.objectId(), System.nanoTime());
                byte[] clear = Protocol.poison(questTarget.objectId(), palette);
                for (ClientSession member : recipients) {
                    member.sendEncrypted(clear,
                            "S_POISON quest-monster=" + questTarget.objectId()
                                    + " type=" + palette + " reason=" + spell.key());
                }
            }
        } else if (timeTarget != null) {
            poisonCured = hub.cureTimeAttackActorPoison(
                    currentRoomId, timeTarget.objectId());
            paralysisCured = spell.curesCurseParalysis()
                    && hub.cancelTimeAttackActorParalysis(
                            currentRoomId, timeTarget.objectId());
            if (poisonCured || paralysisCured) {
                int palette = hub.timeAttackActorPoisonPalette(
                        currentRoomId, timeTarget.objectId(), System.nanoTime());
                byte[] clear = Protocol.poison(timeTarget.objectId(), palette);
                for (ClientSession member : recipients) {
                    member.sendEncrypted(clear,
                            "S_POISON timeattack-actor=" + timeTarget.objectId()
                                    + " type=" + palette + " reason=" + spell.key());
                }
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT remove-curse=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL remove-curse skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + request.targetObjectId()
                + " poison-cured=" + poisonCured
                + " paralysis-cured=" + paralysisCured
                + " effective-int=" + effectiveIntelligence
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    private void useElementalSummonSpell(
            byte[] payload, BattleSpellCatalog.ElementalSummonSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;
        String elementalName = spell.skillId() == BattleSpellCatalog.GREATER_ELEMENTAL
                ? "Greater Elemental" : "Lesser Elemental";
        String elementalKey = spell.key();

        boolean classicWorld = phase == Phase.WORLD;
        ArenaMapCatalog.Arena arena = classicWorld ? null : ArenaMapCatalog.forMap(
                hub.battleMapId(currentRoomId, this));
        boolean mapAllowsPetRecall = classicWorld
                ? ClassicWorldMapCatalog.forMap(classicWorldMapId).allowsPetRecall()
                : arena.allowsPetRecall();
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL " + elementalName + " rejected"
                    + " unavailable action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        RuntimeInventory previousInventory;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            int mpCost = spell.effectiveMpCost();
            if (castNow < readyAt || playerMp < mpCost || playerHp <= 0
                    || (phase != Phase.BATTLE && phase != Phase.WORLD)
                    || observer) {
                System.out.println("[LiTo] C_USE_SPELL " + elementalName
                        + " rejected state skill=" + spell.skillId()
                        + " hp=" + playerHp + " mp=" + playerMp
                        + " mp-cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE " + elementalKey + "-missing-reagent=299");
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            previousInventory = inventory;
            inventory = nextInventory;
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] castEffect = Protocol.effectObject(
                playerObjectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            if (classicWorld && member != this
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY)) continue;
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION " + elementalKey + " caster=" + playerObjectId()
                            + " action=" + spell.actionId());
            member.sendEncrypted(castEffect,
                    "S_EFFECT " + elementalKey + " caster=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT " + elementalKey + "=" + remainingMp
                        + "/" + playerMaxMp);

        // Retained LESSER/GREATER_ELEMENTAL modes run after the accepted cast has
        // committed materials/MP and published its cast action.  Attribute
        // zero and an existing pet-cost actor are silent no-op outcomes;
        // only a nonzero attribute on a no-recall map emits message353.
        int elementalNpcId = spell.summonNpcId(elfAttribute);
        if (elementalNpcId == 0) {
            System.out.println("[LiTo] C_USE_SPELL " + elementalName + " committed"
                    + " without summon: ElfAttr=0 player=" + playerName());
            return;
        }
        if (!mapAllowsPetRecall) {
            sendEncrypted(Protocol.messageCode(spell.mapFailureMessage()),
                    "S_MESSAGE_CODE " + elementalKey + "-map="
                            + spell.mapFailureMessage());
            return;
        }
        List<BattleCompanion.Snapshot> active = (classicWorld
                ? classicWorldCompanionSnapshots()
                : controlledCompanionSnapshots()).stream()
                .filter(BattleCompanion.Snapshot::active).toList();
        int usedPetCost = active.stream()
                .mapToInt(BattleCompanion.Snapshot::petCost).sum();
        if (usedPetCost != 0) {
            System.out.println("[LiTo] C_USE_SPELL " + elementalName + " committed"
                    + " without summon: existing-pet-cost=" + usedPetCost
                    + " player=" + playerName());
            return;
        }

        SourceSummonTemplate template;
        SourceNpcPhysicalStats companionDefense;
        try {
            template = selectedSourceAccounts().summonTemplate(elementalNpcId);
            companionDefense = selectedSourceAccounts()
                    .npcPhysicalStats(elementalNpcId);
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] C_USE_SPELL " + elementalName + " source"
                    + " lookup failed npc=" + elementalNpcId + " reason="
                    + sourceFailure.getClass().getSimpleName() + ": "
                    + sourceFailure.getMessage());
            return;
        }
        if (template.npcId() != elementalNpcId) {
            throw new IllegalStateException(
                    elementalName + " source NPC identity mismatch");
        }
        ArenaMapCatalog.Point spawn = summonSpawnPoint(arena, classicWorld);
        if (spawn == null) {
            System.out.println("[LiTo] C_USE_SPELL " + elementalName + " committed"
                    + " without summon: no authoritative landing player="
                    + playerName());
            return;
        }
        CharacterSummary caster = selectedCharacterSummary();
        int charisma = caster == null ? 9 : Math.max(0, caster.charisma());
        BattleCompanion companion = spell.skillId() == BattleSpellCatalog.GREATER_ELEMENTAL
                ? BattleCompanion.greaterElemental(
                        COMPANION_SEQUENCE.getAndIncrement(), template,
                        spell.petCost(charisma), spell.lifetimeSeconds(),
                        spawn.x(), spawn.y(), castNow)
                : BattleCompanion.lesserElemental(
                        COMPANION_SEQUENCE.getAndIncrement(), template,
                        spell.petCost(charisma), spell.lifetimeSeconds(),
                        spawn.x(), spawn.y(), castNow);
        companion.qualifyNpcDefense(companionDefense);
        synchronized (tamedCompanions) {
            tamedCompanions.add(companion);
        }
        publishSummonedCompanion(companion, recipients, spell);
        BattleCompanion.Snapshot created = companion.snapshot();
        System.out.println("[LiTo] C_USE_SPELL " + elementalName + " skill="
                + spell.skillId() + " caster=" + playerName()
                + " elf-attr=" + elfAttribute + " npc=" + created.npcId()
                + " object=" + created.objectId() + " gfx=" + created.gfx()
                + " pet-cost=" + created.petCost() + " mp=" + remainingMp
                + "/" + playerMaxMp);
    }

    private void useSummonSpell(byte[] payload,
                                BattleSpellCatalog.SummonSpell spell) throws IOException {
        Protocol.SummonSpellRequest request = Protocol.summonSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        CharacterSummary caster = selectedCharacterSummary();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        boolean controlRing = inventory.controlAbilityEnabled(5);
        BattleSpellCatalog.SummonChoice choice;
        if (controlRing) {
            choice = BattleSpellCatalog.summonChoice(request.selection());
            if (choice == null) {
                closeSummonList("invalid-selection");
                System.out.println("[LiTo] C_USE_SPELL summon rejected invalid ring selection="
                        + request.selection() + " player=" + playerName());
                return;
            }
            if (!spell.permitsControlSelection(
                    casterLevel, request.selection())
                    || casterLevel < choice.requiredLevel()) {
                sendEncrypted(Protocol.messageCode(spell.levelFailureMessage()),
                        "S_MESSAGE_CODE summon-level=" + spell.levelFailureMessage());
                closeSummonList("level");
                System.out.println("[LiTo] C_USE_SPELL summon rejected level player="
                        + playerName() + " level=" + casterLevel + " selection="
                        + request.selection() + " required=" + choice.requiredLevel());
                return;
            }
        } else {
            int authoritativeGrade = spell.directGrade(casterLevel);
            choice = BattleSpellCatalog.summonChoice(authoritativeGrade);
            if (request.selection() != authoritativeGrade || choice == null
                    || !choice.directChoice()) {
                System.out.println("[LiTo] C_USE_SPELL summon rejected direct grade player="
                        + playerName() + " client=" + request.selection()
                        + " authoritative=" + authoritativeGrade);
                return;
            }
        }

        boolean classicWorld = phase == Phase.WORLD;
        ArenaMapCatalog.Arena arena = classicWorld ? null : ArenaMapCatalog.forMap(
                hub.battleMapId(currentRoomId, this));
        boolean mapAllowsPetRecall = classicWorld
                ? ClassicWorldMapCatalog.forMap(classicWorldMapId).allowsPetRecall()
                : arena.allowsPetRecall();
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL summon rejected unavailable action player="
                    + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        SourceSummonTemplate template;
        SourceNpcPhysicalStats companionDefense;
        try {
            template = selectedSourceAccounts().summonTemplate(choice.npcId());
            companionDefense = selectedSourceAccounts()
                    .npcPhysicalStats(choice.npcId());
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] rejected summon; source NPC lookup failed player="
                    + playerName() + " npc=" + choice.npcId() + " reason="
                    + sourceFailure.getClass().getSimpleName() + ": "
                    + sourceFailure.getMessage());
            if (controlRing) closeSummonList("source-failure");
            return;
        }
        if (template.npcId() != choice.npcId()) {
            throw new IllegalStateException("summon source NPC identity mismatch");
        }
        BattleAnimationCatalog.get().requireBattleCapableSprite(
                template.gfx(), BattleActionCodes.WALK);

        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);

        RuntimeInventory previousInventory;
        int remainingMp;
        int remainingHp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || playerHp <= spell.hpCost()
                    || (phase != Phase.BATTLE && phase != Phase.WORLD) || observer) {
                System.out.println("[LiTo] C_USE_SPELL summon rejected state skill="
                        + spell.skillId() + " hp=" + playerHp + " hp-cost="
                        + spell.hpCost() + " mp=" + playerMp + " mp-cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE summon-missing-reagent=299");
                System.out.println("[LiTo] C_USE_SPELL summon rejected missing reagent catalog="
                        + spell.itemConsumeId() + " count=" + spell.itemConsumeCount());
                return;
            }
            previousInventory = inventory;
            inventory = nextInventory;
            playerMp -= mpCost;
            playerHp -= spell.hpCost();
            remainingMp = playerMp;
            remainingHp = playerHp;
            spellReadyNanos.put(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelMeditation("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        sendInventoryDelta(previousInventory, inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] castEffect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            if (classicWorld && member != this
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, positionX, positionY)) continue;
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION summon caster=" + playerObjectId()
                            + " action=" + spell.actionId());
            member.sendEncrypted(castEffect,
                    "S_EFFECT summon caster=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT summon=" + remainingMp + "/" + playerMaxMp);
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT summon-hp-cost=" + remainingHp + "/" + playerMaxHp);
        broadcastOwnHitRatio("summon-hp-cost");
        applySpellLawfulDelta(spell.lawfulDelta(), "summon-monster");
        // Retained L1SkillUse admits the normal cast, commits its reagent/reuse,
        // breaks cast-interrupted states and publishes the cast before
        // SUMMON_MONSTER.start() checks L1Map.isRecallPets().  Message 353 is
        // therefore a committed no-summon result, not a free preflight reject;
        // the native ring list also remains client-owned in this branch.
        if (!mapAllowsPetRecall) {
            sendEncrypted(Protocol.messageCode(spell.mapFailureMessage()),
                    "S_MESSAGE_CODE summon-map=" + spell.mapFailureMessage());
            System.out.println("[LiTo] C_USE_SPELL summon committed without summon:"
                    + " map-recall-disabled player=" + playerName()
                    + " map=" + (classicWorld ? classicWorldMapId
                            : arena.mapId())
                    + " hp=" + remainingHp + "/" + playerMaxHp
                    + " mp=" + remainingMp + "/" + playerMaxMp);
            return;
        }
        if (controlRing) closeSummonList("cast");

        List<BattleCompanion.Snapshot> active = (classicWorld
                ? classicWorldCompanionSnapshots()
                : controlledCompanionSnapshots()).stream()
                .filter(BattleCompanion.Snapshot::active).toList();
        int usedPetCost = active.stream()
                .mapToInt(BattleCompanion.Snapshot::petCost).sum();
        if (controlRing && choice.exclusive() && usedPetCost != 0) {
            System.out.println("[LiTo] C_USE_SPELL summon exclusive rejected player="
                    + playerName() + " npc=" + choice.npcId()
                    + " existing-pet-cost=" + usedPetCost);
            return;
        }
        int capacityPetCost = controlRing ? choice.petCost() : 6;
        int storedPetCost = controlRing ? choice.effectivePetCost() : 6;
        int charisma = caster == null ? 9 : Math.max(0, caster.charisma());
        int availableCharisma = charisma + 6 - usedPetCost;
        int count = Math.min(Math.max(0, availableCharisma) / capacityPetCost,
                Math.max(0, 8 - active.size()));
        if (charisma + 6 < capacityPetCost || count <= 0) {
            sendEncrypted(Protocol.messageCode(spell.capacityFailureMessage()),
                    "S_MESSAGE_CODE summon-capacity=" + spell.capacityFailureMessage());
            System.out.println("[LiTo] C_USE_SPELL summon capacity rejected player="
                    + playerName() + " charisma=" + charisma + " used=" + usedPetCost
                    + " pet-cost=" + capacityPetCost + " active=" + active.size());
            return;
        }

        int created = 0;
        for (int index = 0; index < count; index++) {
            ArenaMapCatalog.Point spawn = summonSpawnPoint(arena, classicWorld);
            if (spawn == null) break;
            BattleCompanion companion = BattleCompanion.summoned(
                    COMPANION_SEQUENCE.getAndIncrement(), choice, template,
                    storedPetCost, spell.lifetimeSeconds(), spawn.x(), spawn.y(), castNow);
            companion.qualifyNpcDefense(companionDefense);
            synchronized (tamedCompanions) {
                tamedCompanions.add(companion);
            }
            publishSummonedCompanion(companion, recipients, spell);
            created++;
        }
        if (created == 0) {
            sendEncrypted(Protocol.messageCode(spell.capacityFailureMessage()),
                    "S_MESSAGE_CODE summon-no-spawn=" + spell.capacityFailureMessage());
        }
        System.out.println("[LiTo] C_USE_SPELL summon skill=" + spell.skillId()
                + " caster=" + playerName() + " selection=" + request.selection()
                + " control-ring=" + controlRing + " npc=" + choice.npcId()
                + " source-name=" + template.name() + " gfx=" + template.gfx()
                + " created=" + created + "/" + count + " pet-cost=" + storedPetCost
                + " effective-int=" + effectiveIntelligence + " hp-cost=" + spell.hpCost()
                + " mp-cost=" + mpCost + " hp=" + remainingHp + "/" + playerMaxHp
                + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    private void closeSummonList(String reason) throws IOException {
        sendEncrypted(Protocol.closeHypertext(playerObjectId()),
                "S_HYPERTEXT close-summonlist reason=" + reason);
    }

    /** Exact retained Pet_Collar withdrawal order for one persistent WORLD pet. */
    private void usePetCollar(RuntimeInventory.Item collar) throws Exception {
        if (phase != Phase.WORLD || observer || playerHp <= 0
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) {
            System.out.println("[LiTo] C_USE_ITEM pet-collar rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }
        if (rejectWhileParalyzed("C_USE_ITEM pet-collar")) return;
        if (!inventory.items().stream().anyMatch(item ->
                item.definition().catalogId() == InventoryCatalog.PET_CALLING_FLUTE)) {
            sendEncrypted(Protocol.messageCode(79),
                    "S_MESSAGE_CODE pet-collar-missing-flute=79");
            return;
        }
        if (!ClassicWorldMapCatalog.forMap(classicWorldMapId).allowsPetRecall()) {
            sendEncrypted(Protocol.messageCode(563),
                    "S_MESSAGE_CODE pet-collar-map=563 map=" + classicWorldMapId);
            return;
        }
        boolean alreadyActive;
        synchronized (tamedCompanions) {
            alreadyActive = tamedCompanions.stream()
                    .map(BattleCompanion::snapshot)
                    .anyMatch(pet -> pet.active() && pet.kind() == BattleCompanion.Kind.PET
                            && pet.collarObjectId() == collar.objectId());
        }
        if (alreadyActive) return;

        GameStateStore.PetState durable = state.petForCollar(collar.objectId());
        if (durable == null || durable.collarCatalogId()
                != collar.definition().catalogId()) {
            System.out.println("[LiTo] C_USE_ITEM pet-collar has no durable pet object="
                    + collar.objectId());
            return;
        }
        SourcePetTemplate template = selectedSourceAccounts().petTemplate(durable.npcId());
        List<BattleCompanion.Snapshot> active = classicWorldCompanionSnapshots().stream()
                .filter(BattleCompanion.Snapshot::active).toList();
        int usedPetCost = active.stream().mapToInt(BattleCompanion.Snapshot::petCost).sum();
        CharacterSummary character = selectedCharacterSummary();
        int charisma = character == null ? 9 : Math.max(0, character.charisma());
        if (active.size() >= 8 || charisma + 6 - usedPetCost < template.charismaCost()) {
            sendEncrypted(Protocol.messageCode(489),
                    "S_MESSAGE_CODE pet-collar-capacity=489 charisma=" + charisma
                            + " used=" + usedPetCost + " pet-cost="
                            + template.charismaCost());
            return;
        }
        ArenaMapCatalog.Point spawn = summonSpawnPoint(null, true);
        if (spawn == null) {
            sendEncrypted(Protocol.messageCode(489),
                    "S_MESSAGE_CODE pet-collar-no-spawn=489");
            return;
        }

        RuntimeInventory previous = inventory.copy();
        if (!inventory.removeCatalog(InventoryCatalog.PET_CALLING_FLUTE, 1)) return;
        BattleCompanion pet = BattleCompanion.pet(
                durable, template, spawn.x(), spawn.y());
        synchronized (tamedCompanions) {
            tamedCompanions.add(pet);
        }
        try {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
            sendInventoryDelta(previous, inventory);
            BattleCompanion.Snapshot snapshot = pet.snapshot();
            for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, snapshot.x(), snapshot.y())) continue;
                member.sendClassicWorldCompanionObject(this, snapshot, "pet-collar-recall");
                member.sendEncrypted(Protocol.effectObject(snapshot.objectId(), 755),
                        "S_EFFECT persistent-pet=" + snapshot.objectId()
                                + " gfx=755 reason=collar-recall");
            }
            System.out.println("[LiTo] C_USE_ITEM pet-collar recalled owner=" + playerName()
                    + " collar=" + collar.objectId() + " pet=" + snapshot.objectId()
                    + " npc=" + snapshot.npcId() + " level=" + snapshot.level()
                    + " hp=" + snapshot.hp() + "/" + snapshot.maxHp()
                    + " flute-consumed=1");
        } catch (Exception failure) {
            synchronized (tamedCompanions) {
                tamedCompanions.remove(pet);
            }
            inventory = previous;
            throw failure;
        }
    }

    private ArenaMapCatalog.Point summonSpawnPoint(
            ArenaMapCatalog.Arena arena, boolean classicWorld) {
        for (int radius = 1; radius <= 8; radius++) {
            for (int dy = -radius; dy <= radius; dy++) {
                for (int dx = -radius; dx <= radius; dx++) {
                    if (Math.max(Math.abs(dx), Math.abs(dy)) != radius) continue;
                    int x = positionX + dx;
                    int y = positionY + dy;
                    boolean standing = classicWorld
                            ? ClassicWorldMapCatalog.forMap(
                                    classicWorldMapId).standingPassable(x, y)
                            : arena.nativeStandingFloor(x, y);
                    boolean occupied = classicWorld
                            ? classicWorldCompanionTileOccupied(x, y, 0, 0)
                            : companionTileOccupied(currentRoomId, x, y, 0, 0);
                    if (standing && !occupied) {
                        return new ArenaMapCatalog.Point(x, y);
                    }
                }
            }
        }
        return null;
    }

    private void publishSummonedCompanion(
            BattleCompanion companion, List<ClientSession> recipients,
            BattleSpellCatalog.SummonSpell spell) throws IOException {
        publishSummonedCompanion(
                companion, recipients, spell.spawnEffectGfx(), "summoned");
    }

    private void publishSummonedCompanion(
            BattleCompanion companion, List<ClientSession> recipients,
            BattleSpellCatalog.ElementalSummonSpell spell) throws IOException {
        publishSummonedCompanion(
                companion, recipients, spell.spawnEffectGfx(), spell.key());
    }

    private void publishSummonedCompanion(
            BattleCompanion companion, List<ClientSession> recipients,
            int spawnEffectGfx, String source) throws IOException {
        BattleCompanion.Snapshot snapshot = companion.snapshot();
        boolean classicWorld = phase == Phase.WORLD;
        for (ClientSession member : recipients) {
            if (classicWorld && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, snapshot.x(), snapshot.y())) continue;
            member.sendBattleObject(snapshot.objectId(), snapshot.name(), snapshot.name(),
                    snapshot.x(), snapshot.y(), snapshot.gfx(), BattleActionCodes.WALK,
                    0, snapshot.moveSpeed(), 0, snapshot.level(), 0, playerName(),
                    classicWorld && member != this ? 0xFF
                            : Protocol.healthRatio(snapshot.hp(), snapshot.maxHp()));
            member.sendEncrypted(Protocol.master(snapshot.objectId(), playerName()),
                    "S_MASTER " + source + "-companion=" + snapshot.objectId()
                            + " owner=" + playerName());
            member.sendEncrypted(Protocol.speed(
                            snapshot.objectId(),
                            Protocol.SpeedMode.fromWire(snapshot.moveSpeed()), 0),
                    "S_SPEED " + source + "-companion=" + snapshot.objectId()
                            + " mode=" + snapshot.moveSpeed());
            member.sendEncrypted(Protocol.effectObject(
                            snapshot.objectId(), spawnEffectGfx),
                    "S_EFFECT " + source + "-companion=" + snapshot.objectId()
                            + " gfx=" + spawnEffectGfx);
        }
    }

    private void applySpellLawfulDelta(int delta, String source) throws IOException {
        if (delta == 0) return;
        CharacterSummary character = selectedCharacterSummary();
        int sourceLawful = character == null ? 0 : nativeLawful(character.lawful());
        GameStateStore.LawfulMutation mutation = state.addLawful(
                stateCharacter(), sourceLawful, delta);
        playerLawful = mutation.after();
        if (!mutation.changed()) return;
        byte[] packet = Protocol.changeAlignment(playerObjectId(), playerLawful);
        boolean classicWorld = phase == Phase.WORLD;
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (classicWorld && member != this
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, positionX, positionY)) continue;
            member.sendEncrypted(packet,
                    "S_CHANGE_ALIGNMENT player=" + playerName()
                            + " object=" + playerObjectId()
                            + " requested-delta=" + mutation.requestedDelta()
                            + " applied-delta=" + mutation.appliedDelta()
                            + " lawful=" + mutation.before() + "->" + mutation.after()
                            + " source=" + source);
        }
    }

    private void useCreateZombieSpell(byte[] payload,
                                      BattleSpellCatalog.CreateZombieSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = originPhase == Phase.WORLD
                ? classicWorldInstanceId : 0;
        int originX = positionX;
        int originY = positionY;

        long targetNow = System.nanoTime();
        BattleQuestEncounter.Snapshot questCorpse = originPhase == Phase.BATTLE
                ? hub.questCorpse(originRoomId, this,
                        request.targetObjectId(), targetNow) : null;
        BattleTimeAttackEncounter.Snapshot timeCorpse = originPhase == Phase.BATTLE
                && questCorpse == null
                ? hub.timeAttackCorpse(originRoomId, this,
                        request.targetObjectId(), targetNow) : null;
        ClassicWorldMonsterPopulation.Snapshot worldCorpse =
                originPhase == Phase.WORLD
                ? hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId()) : null;
        int targetCount = (questCorpse == null ? 0 : 1)
                + (timeCorpse == null ? 0 : 1)
                + (worldCorpse == null ? 0 : 1);
        boolean eligibleWorldCorpse = worldCorpse != null
                && worldCorpse.present() && !worldCorpse.alive();
        if (targetCount != 1 || (originPhase == Phase.WORLD
                && !eligibleWorldCorpse)) {
            System.out.println("[LiTo] C_USE_SPELL create-zombie rejected non-corpse target="
                    + request.targetObjectId() + " phase=" + originPhase
                    + " count=" + targetCount);
            return;
        }
        int targetX = questCorpse != null ? questCorpse.x()
                : timeCorpse != null ? timeCorpse.x() : worldCorpse.x();
        int targetY = questCorpse != null ? questCorpse.y()
                : timeCorpse != null ? timeCorpse.y() : worldCorpse.y();
        if (!BattleSpellCatalog.isInNativeScreen(
                originX, originY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL create-zombie rejected screen target="
                    + request.targetObjectId());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL create-zombie rejected unavailable action player="
                    + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        BattleSpellCatalog.ZombieTemplate template =
                BattleSpellCatalog.zombieTemplate(casterType, casterLevel);
        SourceNpcPhysicalStats zombieStats;
        try {
            zombieStats = selectedSourceAccounts().npcPhysicalStats(template.npcId());
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] rejected create-zombie; source NPC lookup failed player="
                    + playerName() + " npc=" + template.npcId() + " reason="
                    + sourceFailure.getClass().getSimpleName() + ": "
                    + sourceFailure.getMessage());
            return;
        }
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);

        RuntimeInventory previousInventory;
        int remainingMp;
        int remainingHp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameContext = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (originPhase == Phase.BATTLE
                        ? currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId
                        : classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId);
            boolean corpseStillPresent;
            if (originPhase == Phase.WORLD) {
                ClassicWorldMonsterPopulation.Snapshot current =
                        hub.classicWorldMonster(originMapId, originInstanceId,
                                request.targetObjectId());
                corpseStillPresent = current != null && current.present()
                        && !current.alive() && current.x() == targetX
                        && current.y() == targetY;
            } else if (questCorpse != null) {
                BattleQuestEncounter.Snapshot current = hub.questCorpse(
                        originRoomId, this, request.targetObjectId(), castNow);
                corpseStillPresent = current != null && current.x() == targetX
                        && current.y() == targetY;
            } else {
                BattleTimeAttackEncounter.Snapshot current = hub.timeAttackCorpse(
                        originRoomId, this, request.targetObjectId(), castNow);
                corpseStillPresent = current != null && current.x() == targetX
                        && current.y() == targetY;
            }
            if (castNow < readyAt || playerMp < mpCost || playerHp <= spell.hpCost()
                    || !sameContext || !corpseStillPresent) {
                System.out.println("[LiTo] C_USE_SPELL create-zombie rejected state skill="
                        + spell.skillId() + " hp=" + playerHp
                        + " hp-cost=" + spell.hpCost() + " mp=" + playerMp
                        + " mp-cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow)
                        + " context=" + sameContext
                        + " corpse=" + corpseStillPresent);
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE create-zombie-missing-reagent=299");
                System.out.println("[LiTo] C_USE_SPELL create-zombie rejected missing reagent catalog="
                        + spell.itemConsumeId() + " count=" + spell.itemConsumeCount());
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            previousInventory = inventory;
            inventory = nextInventory;
            playerMp -= mpCost;
            playerHp -= spell.hpCost();
            remainingMp = playerMp;
            remainingHp = playerHp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? hub.classicWorldMembers(originMapId, originInstanceId)
                : questCorpse != null
                    ? hub.battleRecipients(originRoomId, questCorpse.force())
                    : hub.roomMembers(originRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            originX, originY)) continue;
            member.sendEncrypted(action,
                    "S_ACTION create-zombie caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT create-zombie=" + remainingMp + "/" + playerMaxMp);
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT create-zombie-hp-cost=" + remainingHp + "/" + playerMaxHp);
        broadcastOwnHitRatio("create-zombie-hp-cost");

        boolean capacity = canTakeControlledCompanion(spell.petCost());
        if (!capacity) {
            sendEncrypted(Protocol.messageCode(319),
                    "S_MESSAGE_CODE create-zombie-capacity=319");
        }
        byte[] effect = Protocol.effectObject(request.targetObjectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            targetX, targetY)) continue;
            member.sendEncrypted(effect,
                    "S_EFFECT create-zombie corpse=" + request.targetObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        if (!capacity) {
            System.out.println("[LiTo] C_USE_SPELL create-zombie capacity rejected player="
                    + playerName() + " corpse=" + request.targetObjectId()
                    + " hp=" + remainingHp + "/" + playerMaxHp
                    + " mp=" + remainingMp + "/" + playerMaxMp);
            return;
        }

        BattleCompanion companion = BattleCompanion.zombie(
                COMPANION_SEQUENCE.getAndIncrement(), template, zombieStats,
                spell.petCost(), targetX, targetY);
        Object consumed = questCorpse != null
                ? hub.consumeQuestCorpse(originRoomId, this,
                        request.targetObjectId(), System.nanoTime())
                : timeCorpse != null
                    ? hub.consumeTimeAttackCorpse(originRoomId, this,
                            request.targetObjectId(), System.nanoTime())
                    : hub.consumeClassicWorldMonsterCorpse(
                            originMapId, originInstanceId,
                            request.targetObjectId());
        if (consumed == null) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE create-zombie-stale=" + spell.failureMessage());
            System.out.println("[LiTo] C_USE_SPELL create-zombie stale corpse="
                    + request.targetObjectId());
            return;
        }
        synchronized (tamedCompanions) {
            tamedCompanions.add(companion);
        }
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            targetX, targetY)) continue;
            member.sendEncrypted(Protocol.removeObject(request.targetObjectId()),
                    "S_REMOVE_OBJECT corpse=" + request.targetObjectId()
                            + " reason=create-zombie");
        }
        List<ClientSession> zombieRecipients = originPhase == Phase.WORLD
                ? recipients.stream().filter(member ->
                        BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                targetX, targetY)).toList()
                : recipients;
        publishCreatedZombie(companion, zombieRecipients);
        System.out.println("[LiTo] C_USE_SPELL create-zombie skill=" + spell.skillId()
                + " caster=" + playerName() + " corpse=" + request.targetObjectId()
                + " zombie-object=" + companion.snapshot().objectId()
                + " zombie-npc=" + template.npcId() + " zombie-gfx=" + template.gfx()
                + " effective-int=" + effectiveIntelligence + " hp-cost=" + spell.hpCost()
                + " mp-cost=" + mpCost + " hp=" + remainingHp + "/" + playerMaxHp
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase + " map=" + originMapId
                + " instance=" + originInstanceId);
    }

    private void useClassicWorldResurrectionSpell(
            byte[] payload, BattleSpellCatalog.ResurrectionSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != spell.skillId() || phase != Phase.WORLD) return;

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        List<ClientSession> contextMembers = hub.classicWorldMembers(
                originMapId, originInstanceId);
        ClientSession playerTarget = contextMembers.stream()
                .filter(candidate -> candidate.playerObjectId()
                        == request.targetObjectId())
                .findFirst().orElse(null);

        ClientSession companionOwner = null;
        BattleCompanion.Snapshot companionCorpse = null;
        for (ClientSession member : contextMembers) {
            for (BattleCompanion.Snapshot candidate
                    : member.classicWorldCompanionSnapshots()) {
                if (candidate.objectId() != request.targetObjectId()) continue;
                if (companionCorpse != null) {
                    System.out.println("[LiTo] C_USE_SPELL classic-world-resurrection"
                            + " rejected duplicate companion target="
                            + request.targetObjectId());
                    return;
                }
                companionOwner = member;
                companionCorpse = candidate;
            }
        }
        ClassicWorldMonsterPopulation.Snapshot worldCorpse =
                playerTarget == null && companionCorpse == null
                ? hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId()) : null;

        int targetCount = (playerTarget == null ? 0 : 1)
                + (companionCorpse == null ? 0 : 1)
                + (worldCorpse == null ? 0 : 1);
        int targetX = playerTarget != null ? playerTarget.positionX
                : companionCorpse != null ? companionCorpse.x()
                : worldCorpse != null ? worldCorpse.x() : 0;
        int targetY = playerTarget != null ? playerTarget.positionY
                : companionCorpse != null ? companionCorpse.y()
                : worldCorpse != null ? worldCorpse.y() : 0;
        boolean eligiblePlayer = playerTarget != null && playerTarget != this
                && playerTarget.phase == Phase.WORLD && !playerTarget.observer
                && playerTarget.playerHp == 0
                && playerTarget.classicWorldMapId == originMapId
                && playerTarget.classicWorldInstanceId == originInstanceId;
        boolean eligibleCompanion = companionCorpse != null
                && companionCorpse.active() && companionCorpse.hp() == 0
                && companionOwner != null;
        boolean eligibleWorldNpc = worldCorpse != null && worldCorpse.present()
                && !worldCorpse.alive()
                && ClassicWorldResurrectionCatalog.allowsSelectedTemplate(
                        worldCorpse.npcId(), true);
        boolean nativeScreen = targetCount == 1
                && BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY);
        if (targetCount != 1
                || (!eligiblePlayer && !eligibleCompanion && !eligibleWorldNpc)
                || !nativeScreen
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world-resurrection"
                    + " rejected target=" + request.targetObjectId()
                    + " count=" + targetCount + " player=" + eligiblePlayer
                    + " companion=" + eligibleCompanion
                    + " world-npc=" + eligibleWorldNpc
                    + " native-screen=" + nativeScreen);
            return;
        }

        boolean occupancySensitive = playerTarget != null
                || (companionCorpse != null
                    && companionCorpse.kind() == BattleCompanion.Kind.PET);
        boolean occupied = occupancySensitive && contextMembers.stream()
                .anyMatch(member -> member != playerTarget
                        && member.phase == Phase.WORLD && !member.observer
                        && member.playerHp > 0
                        && member.positionX == targetX
                        && member.positionY == targetY);
        if (occupied) {
            sendEncrypted(Protocol.messageCode(592),
                    "S_MESSAGE_CODE classic-world-resurrection-occupied=592");
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        ResurrectionCastCommit commit;
        long castNow = System.nanoTime();
        ClientSession firstLock = playerTarget == null
                || playerObjectId() <= playerTarget.playerObjectId()
                ? this : playerTarget;
        ClientSession secondLock = playerTarget == null ? null
                : firstLock == this ? playerTarget : this;
        synchronized (firstLock) {
            if (secondLock != null) synchronized (secondLock) {
                commit = commitClassicWorldResurrectionCast(
                        spell, playerTarget, originMapId, originInstanceId,
                        mpCost, castNow);
            } else {
                commit = commitClassicWorldResurrectionCast(
                        spell, null, originMapId, originInstanceId,
                        mpCost, castNow);
            }
        }
        if (!commit.accepted()) {
            if (commit.missingReagent()) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE classic-world-resurrection-missing-reagent=299"
                                + " skill=" + spell.skillId());
            } else if (playerMp < mpCost) {
                sendEncrypted(Protocol.messageCode(278),
                        "S_MESSAGE_CODE classic-world-resurrection-insufficient-mp=278"
                                + " skill=" + spell.skillId());
            }
            return;
        }
        if (spell.itemConsumeId() != 0) {
            sendInventoryDelta(commit.previousInventory(), inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        }
        cancelMeditation("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(
                request.targetObjectId(), spell.effectGfx());
        for (ClientSession member : contextMembers) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, targetX, targetY)) continue;
            member.sendEncrypted(action,
                    "S_ACTION classic-world-resurrection caster=" + playerObjectId()
                            + " action=" + spell.actionId());
            member.sendEncrypted(effect,
                    "S_EFFECT classic-world-resurrection target="
                            + request.targetObjectId() + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(commit.remainingMp(), playerMaxMp),
                "S_MANA_POINT classic-world-resurrection="
                        + commit.remainingMp() + "/" + playerMaxMp);

        if (playerTarget != null) {
            // Retained RESURRECTION.runSkill() suppresses the question on a
            // map where mapids.resurrection=0, but L1SkillUse continues with
            // useConsume(), sendGrfx(true) and setDelay(). Keep that native
            // order: the accepted cast above has already consumed MP/reagent,
            // cleared cast-breaking statuses and emitted action/effect.
            if (!ClassicWorldResurrectionCatalog.allowsSelectedMap(
                    originMapId, true)) {
                System.out.println("[LiTo] C_USE_SPELL classic-world-resurrection"
                        + " prompt suppressed map-resurrection-disabled map="
                        + originMapId + " target=" + playerTarget.playerName()
                        + " caster=" + playerName() + " skill=" + spell.skillId());
                return;
            }
            hub.cancelPendingPlayerTradePrompt(playerTarget);
            playerTarget.clearPendingAskCallbacks();
            playerTarget.pendingResurrection = new PendingResurrection(
                    this, Phase.WORLD, 0, originMapId, originInstanceId, spell);
            byte[] question = spell.questionId() == 321
                    ? Protocol.resurrectionAsk() : Protocol.greaterResurrectionAsk();
            playerTarget.sendEncrypted(question,
                    "S_ASK classic-world-resurrection question=" + spell.questionId()
                            + " caster=" + playerObjectId());
            System.out.println("[LiTo] C_USE_SPELL classic-world-resurrection prompt"
                    + " target=" + playerTarget.playerName()
                    + " caster=" + playerName() + " skill=" + spell.skillId()
                    + " question=" + spell.questionId() + " mp-cost=" + mpCost
                    + " reagent=" + spell.itemConsumeId() + "x"
                    + spell.itemConsumeCount());
            return;
        }

        int restoredHp;
        int restoredMaxHp;
        int restoredGfx;
        int restoredNpcId;
        if (companionCorpse != null) {
            BattleCompanion companion = companionOwner.ownedCompanion(
                    companionCorpse.objectId());
            restoredHp = spell.restoredNpcHp(companionCorpse.maxHp());
            if (companion == null || !companion.resurrect(restoredHp)) {
                sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                        "S_MESSAGE_CODE classic-world-resurrection-stale="
                                + spell.failureMessage());
                return;
            }
            restoredMaxHp = companionCorpse.maxHp();
            restoredGfx = companionCorpse.gfx();
            restoredNpcId = companionCorpse.npcId();
        } else {
            ClassicWorldMonsterPopulation.Resurrection result =
                    hub.resurrectClassicWorldMonster(originMapId,
                            originInstanceId, request.targetObjectId(),
                            spell.restoredNpcHp(worldCorpse.maximumHp()));
            restoredHp = result == null ? 0 : result.after().currentHp();
            restoredMaxHp = result == null ? 0 : result.after().maximumHp();
            restoredGfx = result == null ? 0 : result.after().gfxId();
            restoredNpcId = worldCorpse.npcId();
        }
        if (restoredHp <= 0) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE classic-world-resurrection-stale="
                            + spell.failureMessage());
            return;
        }
        byte[] resurrected = Protocol.resurrect(
                request.targetObjectId(), 0, request.targetObjectId(), restoredGfx);
        byte[] ratio = Protocol.hitRatio(
                request.targetObjectId(), restoredHp, restoredMaxHp);
        for (ClientSession member : contextMembers) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, targetX, targetY)) continue;
            member.sendEncrypted(resurrected,
                    "S_RESURRECT classic-world-npc target="
                            + request.targetObjectId() + " hp=" + restoredHp
                            + "/" + restoredMaxHp);
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO classic-world-npc-resurrection="
                            + request.targetObjectId() + " hp=" + restoredHp
                            + "/" + restoredMaxHp);
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world-resurrection npc="
                + restoredNpcId + " target=" + request.targetObjectId()
                + " hp=" + restoredHp + "/" + restoredMaxHp
                + " skill=" + spell.skillId() + " mp-cost=" + mpCost);
    }

    private ResurrectionCastCommit commitClassicWorldResurrectionCast(
            BattleSpellCatalog.ResurrectionSpell spell,
            ClientSession playerTarget, int originMapId, int originInstanceId,
            int mpCost, long castNow) throws IOException {
        long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
        boolean sameCasterContext = phase == Phase.WORLD && !observer
                && playerHp > 0 && classicWorldMapId == originMapId
                && classicWorldInstanceId == originInstanceId;
        boolean samePlayerContext = playerTarget == null
                || playerTarget.phase == Phase.WORLD && !playerTarget.observer
                    && playerTarget.playerHp == 0
                    && playerTarget.classicWorldMapId == originMapId
                    && playerTarget.classicWorldInstanceId == originInstanceId;
        if (castNow < readyAt || playerMp < mpCost
                || !sameCasterContext || !samePlayerContext) {
            System.out.println("[LiTo] C_USE_SPELL classic-world-resurrection"
                    + " rejected state skill=" + spell.skillId()
                    + " hp=" + playerHp + " mp=" + playerMp
                    + " mp-cost=" + mpCost + " cooldownNanos="
                    + Math.max(0L, readyAt - castNow));
            return new ResurrectionCastCommit(false, false, null, playerMp);
        }
        RuntimeInventory nextInventory = inventory.copy();
        if (spell.itemConsumeId() != 0 && !nextInventory.removeCatalog(
                spell.itemConsumeId(), spell.itemConsumeCount())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world-resurrection"
                    + " rejected missing reagent skill=" + spell.skillId()
                    + " catalog=" + spell.itemConsumeId()
                    + " count=" + spell.itemConsumeCount());
            return new ResurrectionCastCommit(false, true, null, playerMp);
        }
        RuntimeInventory previousInventory = inventory;
        inventory = nextInventory;
        playerMp -= mpCost;
        spellReadyNanos.put(spell.skillId(), castNow
                + spell.reuseDelayMillis() * 1_000_000L);
        return new ResurrectionCastCommit(
                true, false, previousInventory, playerMp);
    }

    private void useCallOfNatureSpell(
            byte[] payload, BattleSpellCatalog.ResurrectionSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != BattleSpellCatalog.CALL_OF_NATURE
                || request.skillId() != spell.skillId()) return;
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;

        // Retained isAttrAgrees() runs before target/resource processing.
        if ((elfAttribute & spell.requiredElfAttribute()) == 0
                && !isAdministrator()) {
            System.out.println("[LiTo] C_USE_SPELL Call-of-Nature rejected"
                    + " attribute player=" + playerName() + " required="
                    + spell.requiredElfAttribute() + " elf-attr=" + elfAttribute
                    + " phase=" + originPhase);
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = originPhase == Phase.WORLD
                ? classicWorldInstanceId : 0;
        List<ClientSession> contextMembers = originPhase == Phase.WORLD
                ? hub.classicWorldMembers(originMapId, originInstanceId)
                : hub.roomCombatants(originRoomId);
        ClientSession playerTarget = contextMembers.stream()
                .filter(candidate -> candidate.playerObjectId()
                        == request.targetObjectId())
                .findFirst().orElse(null);

        ClientSession companionOwner = null;
        BattleCompanion.Snapshot companionCorpse = null;
        for (ClientSession member : contextMembers) {
            List<BattleCompanion.Snapshot> companions = originPhase == Phase.WORLD
                    ? member.classicWorldCompanionSnapshots()
                    : member.controlledCompanionSnapshots();
            for (BattleCompanion.Snapshot candidate : companions) {
                if (candidate.objectId() != request.targetObjectId()) continue;
                if (companionCorpse != null) {
                    System.out.println("[LiTo] C_USE_SPELL Call-of-Nature rejected"
                            + " duplicate companion target=" + request.targetObjectId());
                    return;
                }
                companionOwner = member;
                companionCorpse = candidate;
            }
        }

        long targetNow = System.nanoTime();
        BattleQuestEncounter.Snapshot questCorpse = originPhase == Phase.BATTLE
                && playerTarget == null && companionCorpse == null
                ? hub.questCorpse(originRoomId, this,
                        request.targetObjectId(), targetNow) : null;
        BattleTimeAttackEncounter.Snapshot timeCorpse = originPhase == Phase.BATTLE
                && playerTarget == null && companionCorpse == null
                && questCorpse == null
                ? hub.timeAttackCorpse(originRoomId, this,
                        request.targetObjectId(), targetNow) : null;
        ClassicWorldMonsterPopulation.Snapshot worldCorpse =
                originPhase == Phase.WORLD && playerTarget == null
                && companionCorpse == null
                ? hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId()) : null;

        int targetCount = (playerTarget == null ? 0 : 1)
                + (companionCorpse == null ? 0 : 1)
                + (questCorpse == null ? 0 : 1)
                + (timeCorpse == null ? 0 : 1)
                + (worldCorpse == null ? 0 : 1);
        int targetX = playerTarget != null ? playerTarget.positionX
                : companionCorpse != null ? companionCorpse.x()
                : questCorpse != null ? questCorpse.x()
                : timeCorpse != null ? timeCorpse.x()
                : worldCorpse != null ? worldCorpse.x() : 0;
        int targetY = playerTarget != null ? playerTarget.positionY
                : companionCorpse != null ? companionCorpse.y()
                : questCorpse != null ? questCorpse.y()
                : timeCorpse != null ? timeCorpse.y()
                : worldCorpse != null ? worldCorpse.y() : 0;
        boolean eligiblePlayer = playerTarget != null && playerTarget != this
                && playerTarget.phase == originPhase && !playerTarget.observer
                && playerTarget.playerHp == 0
                && (originPhase == Phase.BATTLE
                    ? playerTarget.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, playerTarget) == originMapId
                    : playerTarget.classicWorldMapId == originMapId
                        && playerTarget.classicWorldInstanceId == originInstanceId);
        boolean eligibleCompanion = companionCorpse != null
                && companionCorpse.active() && companionCorpse.hp() == 0
                && companionOwner != null;
        boolean eligibleBattleNpc = (questCorpse != null || timeCorpse != null)
                && BattleSpellCatalog.npcAllowsResurrection(
                        questCorpse != null ? questCorpse.npcId() : timeCorpse.npcId());
        boolean eligibleWorldNpc = worldCorpse != null && worldCorpse.present()
                && !worldCorpse.alive()
                && ClassicWorldResurrectionCatalog.allowsSelectedTemplate(
                        worldCorpse.npcId(), true);
        int range = Math.max(Math.abs(positionX - targetX),
                Math.abs(positionY - targetY));
        if (targetCount != 1
                || (!eligiblePlayer && !eligibleCompanion
                    && !eligibleBattleNpc && !eligibleWorldNpc)
                || range > spell.maximumRange()
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Call-of-Nature rejected target="
                    + request.targetObjectId() + " count=" + targetCount
                    + " player=" + eligiblePlayer
                    + " companion=" + eligibleCompanion
                    + " battle-npc=" + eligibleBattleNpc
                    + " world-npc=" + eligibleWorldNpc
                    + " range=" + range + " max=" + spell.maximumRange()
                    + " phase=" + originPhase);
            return;
        }

        // Retained player and L1PetInstance resurrection refuses a corpse cell
        // occupied by any living player. Summons and ordinary NPCs do not use
        // this check.
        boolean occupancySensitive = playerTarget != null
                || (companionCorpse != null
                    && companionCorpse.kind() == BattleCompanion.Kind.PET);
        boolean occupied = occupancySensitive && contextMembers.stream()
                .anyMatch(candidate -> candidate != playerTarget
                        && candidate.phase == originPhase && !candidate.observer
                        && candidate.playerHp > 0
                        && candidate.positionX == targetX
                        && candidate.positionY == targetY);
        if (occupied) {
            sendEncrypted(Protocol.messageCode(592),
                    "S_MESSAGE_CODE Call-of-Nature-occupied=592");
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);
        RuntimeInventory previousInventory;
        int remainingMp;
        long castNow = System.nanoTime();
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameContext = phase == originPhase && !observer && playerHp > 0
                    && (originPhase == Phase.BATTLE
                        ? currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId
                        : classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId);
            if (castNow < readyAt || playerMp < mpCost || !sameContext) {
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE Call-of-Nature-insufficient-mp=278");
                }
                return;
            }
            RuntimeInventory next = inventory.copy();
            if (!next.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE Call-of-Nature-missing-reagent=299");
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            previousInventory = inventory;
            inventory = next;
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? hub.classicWorldMembers(originMapId, originInstanceId)
                : questCorpse != null
                    ? hub.battleRecipients(originRoomId, questCorpse.force())
                    : hub.roomMembers(originRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(
                request.targetObjectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            targetX, targetY)) continue;
            member.sendEncrypted(action,
                    "S_ACTION Call-of-Nature caster=" + playerObjectId()
                            + " action=" + spell.actionId());
            member.sendEncrypted(effect,
                    "S_EFFECT Call-of-Nature target=" + request.targetObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Call-of-Nature=" + remainingMp + "/" + playerMaxMp);

        if (playerTarget != null) {
            hub.cancelPendingPlayerTradePrompt(playerTarget);
            playerTarget.clearPendingAskCallbacks();
            playerTarget.pendingResurrection = new PendingResurrection(
                    this, originPhase, originRoomId,
                    originMapId, originInstanceId, spell);
            playerTarget.sendEncrypted(Protocol.greaterResurrectionAsk(),
                    "S_ASK Call-of-Nature question=322 caster=" + playerObjectId());
            System.out.println("[LiTo] C_USE_SPELL Call-of-Nature prompt target="
                    + playerTarget.playerName() + " caster=" + playerName()
                    + " phase=" + originPhase + " mp-cost=" + mpCost);
            return;
        }

        int restoredHp;
        int restoredMaxHp;
        int restoredGfx;
        int restoredNpcId;
        if (companionCorpse != null) {
            BattleCompanion companion = companionOwner.ownedCompanion(
                    companionCorpse.objectId());
            restoredHp = spell.restoredNpcHp(companionCorpse.maxHp());
            if (companion == null || !companion.resurrect(restoredHp)) {
                sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                        "S_MESSAGE_CODE Call-of-Nature-stale="
                                + spell.failureMessage());
                return;
            }
            restoredMaxHp = companionCorpse.maxHp();
            restoredGfx = companionCorpse.gfx();
            restoredNpcId = companionCorpse.npcId();
        } else if (questCorpse != null) {
            BattleQuestEncounter.Resurrection result = hub.resurrectQuestCorpse(
                    originRoomId, this, request.targetObjectId(),
                    System.nanoTime(), spell.npcHpDivisor());
            restoredHp = result == null ? 0 : result.after().hp();
            restoredMaxHp = result == null ? 0 : result.after().maxHp();
            restoredGfx = result == null ? 0 : result.after().gfx();
            restoredNpcId = questCorpse.npcId();
        } else if (timeCorpse != null) {
            BattleTimeAttackEncounter.Resurrection result =
                    hub.resurrectTimeAttackCorpse(originRoomId, this,
                            request.targetObjectId(), System.nanoTime(),
                            spell.npcHpDivisor());
            restoredHp = result == null ? 0 : result.after().hp();
            restoredMaxHp = result == null ? 0 : result.after().maxHp();
            restoredGfx = result == null ? 0 : result.after().gfx();
            restoredNpcId = timeCorpse.npcId();
        } else {
            ClassicWorldMonsterPopulation.Resurrection result =
                    hub.resurrectClassicWorldMonster(originMapId,
                            originInstanceId, request.targetObjectId(),
                            spell.restoredNpcHp(worldCorpse.maximumHp()));
            restoredHp = result == null ? 0 : result.after().currentHp();
            restoredMaxHp = result == null ? 0 : result.after().maximumHp();
            restoredGfx = result == null ? 0 : result.after().gfxId();
            restoredNpcId = worldCorpse.npcId();
        }
        if (restoredHp <= 0) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE Call-of-Nature-stale="
                            + spell.failureMessage());
            return;
        }
        byte[] resurrected = Protocol.resurrect(request.targetObjectId(), 0,
                request.targetObjectId(), restoredGfx);
        byte[] ratio = Protocol.hitRatio(
                request.targetObjectId(), restoredHp, restoredMaxHp);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            targetX, targetY)) continue;
            member.sendEncrypted(resurrected,
                    "S_RESURRECT Call-of-Nature target="
                            + request.targetObjectId() + " hp=" + restoredHp
                            + "/" + restoredMaxHp);
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO Call-of-Nature target="
                            + request.targetObjectId() + " hp=" + restoredHp
                            + "/" + restoredMaxHp);
        }
        System.out.println("[LiTo] C_USE_SPELL Call-of-Nature npc="
                + restoredNpcId + " target=" + request.targetObjectId()
                + " hp=" + restoredHp + "/" + restoredMaxHp
                + " phase=" + originPhase + " mp-cost=" + mpCost);
    }

    private void useResurrectionSpell(byte[] payload,
                                      BattleSpellCatalog.ResurrectionSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        ClientSession playerTarget = hub.roomCombatants(currentRoomId).stream()
                .filter(candidate -> candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        long targetNow = System.nanoTime();
        BattleQuestEncounter.Snapshot questCorpse = playerTarget == null
                ? hub.questCorpse(currentRoomId, this, request.targetObjectId(), targetNow) : null;
        BattleTimeAttackEncounter.Snapshot timeCorpse = playerTarget == null && questCorpse == null
                ? hub.timeAttackCorpse(currentRoomId, this,
                        request.targetObjectId(), targetNow) : null;
        int targetCount = (playerTarget == null ? 0 : 1)
                + (questCorpse == null ? 0 : 1) + (timeCorpse == null ? 0 : 1);
        int targetX = playerTarget != null ? playerTarget.positionX
                : questCorpse != null ? questCorpse.x() : timeCorpse != null ? timeCorpse.x() : 0;
        int targetY = playerTarget != null ? playerTarget.positionY
                : questCorpse != null ? questCorpse.y() : timeCorpse != null ? timeCorpse.y() : 0;
        boolean eligiblePlayer = playerTarget != null && playerTarget != this
                && playerTarget.phase == Phase.BATTLE && !playerTarget.observer
                && playerTarget.playerHp == 0
                && hub.battleMapId(currentRoomId, this)
                        == hub.battleMapId(currentRoomId, playerTarget);
        int npcId = questCorpse != null ? questCorpse.npcId()
                : timeCorpse != null ? timeCorpse.npcId() : 0;
        boolean eligibleNpc = (questCorpse != null || timeCorpse != null)
                && BattleSpellCatalog.npcAllowsResurrection(npcId);
        if (targetCount != 1 || (!eligiblePlayer && !eligibleNpc)
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY)
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL resurrection rejected target="
                    + request.targetObjectId() + " player=" + eligiblePlayer
                    + " npc=" + eligibleNpc + " count=" + targetCount);
            return;
        }
        // Retained RESURRECTION applies the same-tile player check to a dead
        // PC (and separately to L1PetInstance). Current Quest/Time targets are
        // monsters, not pets, so they must not inherit the PC occupancy gate.
        boolean occupied = playerTarget != null && hub.roomCombatants(currentRoomId).stream()
                .anyMatch(candidate -> candidate != playerTarget
                        && candidate.phase == Phase.BATTLE && !candidate.observer
                        && candidate.playerHp > 0 && candidate.positionX == targetX
                        && candidate.positionY == targetY
                        && hub.battleMapId(currentRoomId, candidate)
                                == hub.battleMapId(currentRoomId, this));
        if (occupied) {
            sendEncrypted(Protocol.messageCode(592),
                    "S_MESSAGE_CODE resurrection-occupied=592");
            System.out.println("[LiTo] C_USE_SPELL resurrection rejected occupied target="
                    + request.targetObjectId() + " x=" + targetX + " y=" + targetY);
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        ResurrectionCastCommit commit;
        long castNow = System.nanoTime();
        ClientSession firstLock = playerTarget == null || playerObjectId() <= playerTarget.playerObjectId()
                ? this : playerTarget;
        ClientSession secondLock = playerTarget == null ? null
                : firstLock == this ? playerTarget : this;
        synchronized (firstLock) {
            if (secondLock != null) synchronized (secondLock) {
                commit = commitResurrectionCast(spell, playerTarget, mpCost, castNow);
            } else {
                commit = commitResurrectionCast(spell, null, mpCost, castNow);
            }
        }
        if (!commit.accepted()) {
            if (commit.missingReagent()) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE resurrection-missing-reagent=299 skill="
                                + spell.skillId());
            }
            return;
        }
        if (spell.itemConsumeId() != 0) {
            sendInventoryDelta(commit.previousInventory(), inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        }
        cancelMeditation("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        List<ClientSession> recipients = questCorpse != null
                ? hub.battleRecipients(currentRoomId, questCorpse.force())
                : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(request.targetObjectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION resurrection caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT resurrection target=" + request.targetObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(commit.remainingMp(), playerMaxMp),
                "S_MANA_POINT resurrection=" + commit.remainingMp() + "/" + playerMaxMp);

        if (playerTarget != null) {
            hub.cancelPendingPlayerTradePrompt(playerTarget);
            playerTarget.clearPendingAskCallbacks();
            playerTarget.pendingResurrection = new PendingResurrection(
                    this, currentRoomId, spell);
            byte[] question = spell.questionId() == 321
                    ? Protocol.resurrectionAsk() : Protocol.greaterResurrectionAsk();
            playerTarget.sendEncrypted(question,
                    "S_ASK resurrection question=" + spell.questionId()
                            + " caster=" + playerObjectId());
            System.out.println("[LiTo] C_USE_SPELL resurrection prompt target="
                    + playerTarget.playerName() + " caster=" + playerName()
                    + " skill=" + spell.skillId() + " question=" + spell.questionId()
                    + " mp-cost=" + mpCost + " reagent=" + spell.itemConsumeId()
                    + "x" + spell.itemConsumeCount());
            return;
        }

        BattleQuestEncounter.Resurrection questResult = questCorpse == null ? null
                : hub.resurrectQuestCorpse(currentRoomId, this,
                        request.targetObjectId(), System.nanoTime());
        BattleTimeAttackEncounter.Resurrection timeResult = timeCorpse == null ? null
                : hub.resurrectTimeAttackCorpse(currentRoomId, this,
                        request.targetObjectId(), System.nanoTime());
        int restoredHp = questResult != null ? questResult.after().hp()
                : timeResult != null ? timeResult.after().hp() : 0;
        int restoredMaxHp = questResult != null ? questResult.after().maxHp()
                : timeResult != null ? timeResult.after().maxHp() : 0;
        int restoredGfx = questResult != null ? questResult.after().gfx()
                : timeResult != null ? timeResult.after().gfx() : 0;
        if (restoredHp <= 0) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE resurrection-stale=" + spell.failureMessage());
            return;
        }
        byte[] resurrected = Protocol.resurrect(
                request.targetObjectId(), 0, request.targetObjectId(), restoredGfx);
        byte[] ratio = Protocol.hitRatio(
                request.targetObjectId(), restoredHp, restoredMaxHp);
        for (ClientSession member : recipients) {
            member.sendEncrypted(resurrected,
                    "S_RESURRECT npc target=" + request.targetObjectId()
                            + " hp=" + restoredHp + "/" + restoredMaxHp);
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO npc-resurrection=" + request.targetObjectId()
                            + " hp=" + restoredHp + "/" + restoredMaxHp);
        }
        System.out.println("[LiTo] C_USE_SPELL resurrection npc=" + npcId
                + " target=" + request.targetObjectId() + " hp=" + restoredHp
                + "/" + restoredMaxHp + " mp-cost=" + mpCost);
    }

    private ResurrectionCastCommit commitResurrectionCast(
            BattleSpellCatalog.ResurrectionSpell spell,
            ClientSession playerTarget, int mpCost, long castNow) throws IOException {
        long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
        if (castNow < readyAt || playerMp < mpCost || playerHp <= 0
                || phase != Phase.BATTLE || observer
                || (playerTarget != null && (playerTarget.phase != Phase.BATTLE
                        || playerTarget.observer || playerTarget.playerHp != 0))) {
            System.out.println("[LiTo] C_USE_SPELL resurrection rejected state skill="
                    + spell.skillId() + " hp=" + playerHp + " mp=" + playerMp
                    + " mp-cost=" + mpCost + " cooldownNanos="
                    + Math.max(0L, readyAt - castNow));
            return new ResurrectionCastCommit(false, false, null, playerMp);
        }
        RuntimeInventory nextInventory = inventory.copy();
        if (spell.itemConsumeId() != 0 && !nextInventory.removeCatalog(
                spell.itemConsumeId(), spell.itemConsumeCount())) {
            System.out.println("[LiTo] C_USE_SPELL resurrection rejected missing reagent skill="
                    + spell.skillId() + " catalog=" + spell.itemConsumeId()
                    + " count=" + spell.itemConsumeCount());
            return new ResurrectionCastCommit(false, true, null, playerMp);
        }
        RuntimeInventory previousInventory = inventory;
        inventory = nextInventory;
        playerMp -= mpCost;
        spellReadyNanos.put(spell.skillId(), castNow
                + spell.reuseDelayMillis() * 1_000_000L);
        return new ResurrectionCastCommit(
                true, false, previousInventory, playerMp);
    }

    private void publishCreatedZombie(BattleCompanion companion,
                                      List<ClientSession> recipients)
            throws IOException {
        BattleCompanion.Snapshot snapshot = companion.snapshot();
        for (ClientSession member : recipients) {
            member.sendBattleObject(snapshot.objectId(), snapshot.name(), snapshot.name(),
                    snapshot.x(), snapshot.y(), snapshot.gfx(), BattleActionCodes.WALK,
                    0, snapshot.moveSpeed(), 0, snapshot.level(), 0, playerName(),
                    Protocol.healthRatio(snapshot.hp(), snapshot.maxHp()));
            member.sendEncrypted(Protocol.master(snapshot.objectId(), playerName()),
                    "S_MASTER created-zombie=" + snapshot.objectId()
                            + " owner=" + playerName());
        }
    }

    private void useTamingSpell(byte[] payload,
                                BattleSpellCatalog.TamingSpell spell) throws IOException {
        Protocol.AttackSpellRequest request = Protocol.attackSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        boolean classicWorld = phase == Phase.WORLD;
        ClassicWorldMonsterPopulation.Snapshot worldTarget = classicWorld
                ? hub.classicWorldMonster(classicWorldMapId,
                        classicWorldInstanceId, request.targetObjectId()) : null;
        BattleQuestEncounter.Snapshot questTarget =
                classicWorld ? null
                        : hub.questMonster(currentRoomId, request.targetObjectId());
        BattleTimeAttackEncounter.Snapshot timeTarget =
                classicWorld ? null
                        : hub.timeAttackActor(currentRoomId, request.targetObjectId());
        if (worldTarget == null && questTarget == null && timeTarget == null) {
            System.out.println("[LiTo] C_USE_SPELL taming rejected non-monster target="
                    + request.targetObjectId());
            return;
        }
        int targetX = worldTarget != null ? worldTarget.x()
                : questTarget != null ? questTarget.x() : timeTarget.x();
        int targetY = worldTarget != null ? worldTarget.y()
                : questTarget != null ? questTarget.y() : timeTarget.y();
        boolean targetGate;
        if (worldTarget != null) {
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(classicWorldMapId);
            targetGate = worldTarget.present() && worldTarget.alive()
                    && !map.isSafetyZone(positionX, positionY)
                    && !map.isSafetyZone(targetX, targetY)
                    && map.hasLineOfSight(positionX, positionY, targetX, targetY);
        } else {
            targetGate = questTarget != null
                    ? hub.canAttackQuestMonster(
                            currentRoomId, this, questTarget.objectId())
                    : hub.canAttackTimeAttackActor(
                            currentRoomId, this, timeTarget.objectId());
        }
        if (!targetGate || !BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL taming rejected gate/screen target="
                    + request.targetObjectId());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL taming rejected unavailable action player="
                    + playerName() + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        int npcId = worldTarget != null ? worldTarget.npcId()
                : questTarget != null ? questTarget.npcId() : timeTarget.npcId();
        SourceNpcPhysicalStats npcStats;
        try {
            npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] rejected taming; source NPC lookup failed player="
                    + playerName() + " npc=" + npcId + " reason="
                    + sourceFailure.getClass().getSimpleName() + ": "
                    + sourceFailure.getMessage());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int targetLevel = worldTarget != null ? worldTarget.template().level()
                : questTarget != null ? questTarget.level() : timeTarget.level();
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        long gateNow = System.nanoTime();
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(gateNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        int magicLevel = spell.includeMagicLevel()
                ? BattleTurnUndead.magicLevel(casterType, casterLevel) : 0;
        boolean bossImmune = npcStats.boss()
                || worldTarget != null && worldTarget.template().boss()
                || timeTarget != null && timeTarget.finalBoss();
        int targetMr = effectiveNpcMagicResistance(worldTarget,
                questTarget, timeTarget, npcStats.magicResistance(), gateNow);
        int probability = bossImmune ? 0 : spell.probability(
                casterLevel, Math.max(1, targetLevel), effectiveIntelligence,
                magicLevel, totalMagicHit, targetMr);
        int configuredPercentileRoll = config.tamingMonsterFixturePercentileRoll();
        int percentileRoll = bossImmune ? 100
                : configuredPercentileRoll > 0 ? configuredPercentileRoll
                : ThreadLocalRandom.current().nextInt(1, 101);

        RuntimeInventory previousInventory;
        int remainingMp;
        int remainingHp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || playerHp <= spell.hpCost()
                    || (phase != Phase.BATTLE && phase != Phase.WORLD) || observer) {
                System.out.println("[LiTo] C_USE_SPELL taming rejected state skill="
                        + spell.skillId() + " hp=" + playerHp + " hp-cost=" + spell.hpCost()
                        + " mp=" + playerMp + " mp-cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            RuntimeInventory nextInventory = inventory.copy();
            if (!nextInventory.removeCatalog(
                    spell.itemConsumeId(), spell.itemConsumeCount())) {
                sendEncrypted(Protocol.messageCode(299),
                        "S_MESSAGE_CODE taming-missing-reagent=299");
                System.out.println("[LiTo] C_USE_SPELL taming rejected missing reagent catalog="
                        + spell.itemConsumeId() + " count=" + spell.itemConsumeCount());
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            previousInventory = inventory;
            inventory = nextInventory;
            playerMp -= mpCost;
            playerHp -= spell.hpCost();
            remainingMp = playerMp;
            remainingHp = playerHp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        sendInventoryDelta(previousInventory, inventory);
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        List<ClientSession> recipients = worldTarget != null
                ? classicWorldMembers(classicWorldMapId).stream()
                    .filter(member -> BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, positionX, positionY)
                            || BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    targetX, targetY))
                    .toList()
                : questTarget != null
                    ? hub.battleRecipients(currentRoomId, questTarget.force())
                    : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION taming caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT taming=" + remainingMp + "/" + playerMaxMp);
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT taming-hp-cost=" + remainingHp + "/" + playerMaxHp);
        broadcastOwnHitRatio("taming-hp-cost");

        boolean earthBindBlocked = worldTarget != null
                ? BattleEarthBindRules.blocksProbabilityMagic(
                    hub.classicWorldMonsterEarthBindActive(
                            classicWorldMapId, classicWorldInstanceId,
                            worldTarget.objectId(), castNow), spell.skillId())
                : earthBindBlocksProbabilityMagic(
                    null, questTarget, timeTarget, castNow, spell.skillId());
        boolean probabilitySuccess = !earthBindBlocked && !bossImmune
                && probability >= percentileRoll;
        consumeEraseMagicAfterProbability(null, worldTarget,
                questTarget, timeTarget, castNow, spell.skillId());
        if (worldTarget != null) {
            hub.cancelClassicWorldMonsterSleep(
                    classicWorldMapId, classicWorldInstanceId,
                    worldTarget.objectId());
        } else {
            breakSleepForStatusSpell(
                    null, questTarget, timeTarget,
                    "probability-spell-" + spell.skillId());
        }
        boolean converted = false;
        long effectTarget = request.targetObjectId();
        if (probabilitySuccess && npcStats.tamable()) {
            if (!canTakeControlledCompanion(6)) {
                sendEncrypted(Protocol.messageCode(319),
                        "S_MESSAGE_CODE taming-capacity=319");
            } else if (worldTarget != null) {
                ClassicWorldMonsterPopulation.Capture capture =
                        hub.captureClassicWorldMonster(
                                classicWorldMapId, classicWorldInstanceId,
                                worldTarget.objectId());
                BattleCompanion companion = capture == null ? null
                        : createTamedCompanion(capture.captured(),
                                classicWorldInstanceId, npcStats);
                if (capture != null && companion != null) {
                    converted = true;
                    effectTarget = companion.snapshot().objectId();
                    publishClassicWorldTaming(
                            capture, companion, spell, recipients);
                }
            } else if (questTarget != null) {
                BattleQuestEncounter.Capture capture = hub.captureQuestMonster(
                        currentRoomId, this, questTarget.objectId());
                BattleCompanion companion = capture == null ? null
                        : createTamedCompanion(capture.captured(), npcStats);
                if (capture != null && companion != null) {
                    converted = true;
                    effectTarget = companion.snapshot().objectId();
                    publishQuestTaming(capture, companion, spell);
                }
            } else {
                BattleTimeAttackEncounter.Capture capture = hub.captureTimeAttackActor(
                        currentRoomId, this, timeTarget.objectId());
                BattleCompanion companion = capture == null ? null
                        : createTamedCompanion(capture.captured(), npcStats);
                if (capture != null && companion != null) {
                    converted = true;
                    effectTarget = companion.snapshot().objectId();
                    publishTimeAttackTaming(capture, companion, spell);
                }
            }
        }

        if (probabilitySuccess && !converted) {
            byte[] effect = Protocol.effectObject(effectTarget, spell.effectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(effect,
                        "S_EFFECT taming target=" + effectTarget
                                + " gfx=" + spell.effectGfx());
            }
        } else if (!probabilitySuccess) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE taming-failure=" + spell.failureMessage());
        }
        if (request.x() != targetX || request.y() != targetY) {
            System.out.println("[LiTo] C_USE_SPELL ignored stale taming coordinates skill="
                    + spell.skillId() + " client=" + request.x() + "," + request.y()
                    + " server=" + targetX + "," + targetY);
        }
        System.out.println("[LiTo] C_USE_SPELL taming skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + request.targetObjectId()
                + " npc=" + npcId + " tamable=" + npcStats.tamable()
                + " boss-immune=" + bossImmune + " probability=" + probability
                + " roll=" + percentileRoll + " success=" + probabilitySuccess
                + " converted=" + converted + " earth-bind-blocked=" + earthBindBlocked
                + " magic-level=" + magicLevel + " total-magic-hit=" + totalMagicHit
                + " mr=" + npcStats.magicResistance() + " hp-cost=" + spell.hpCost()
                + " mp-cost=" + mpCost + " hp=" + remainingHp + "/" + playerMaxHp
                + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    private boolean canTakeControlledCompanion(int petCost) {
        CharacterSummary character = selectedCharacterSummary();
        int type = character == null ? 0 : character.type();
        int classBonus = switch (type) {
            case 2 -> 12;
            case 0, 1, 3, 4, 5, 6 -> 6;
            default -> 0;
        };
        int charisma = character == null ? 9 : Math.max(0, character.charisma());
        List<BattleCompanion.Snapshot> active = controlledCompanionSnapshots().stream()
                .filter(BattleCompanion.Snapshot::active).toList();
        int used = active.stream().mapToInt(BattleCompanion.Snapshot::petCost).sum();
        return active.size() < 8 && charisma + classBonus - used >= petCost;
    }

    private BattleCompanion createTamedCompanion(
            BattleQuestEncounter.Snapshot captured, SourceNpcPhysicalStats stats) {
        BattleCompanion companion = BattleCompanion.tamedFromQuest(
                COMPANION_SEQUENCE.getAndIncrement(), captured, stats);
        synchronized (tamedCompanions) {
            tamedCompanions.add(companion);
        }
        return companion;
    }

