    private void publishTamedCompanion(BattleCompanion companion,
                                       List<ClientSession> recipients,
                                       BattleSpellCatalog.TamingSpell spell)
            throws IOException {
        BattleCompanion.Snapshot snapshot = companion.snapshot();
        for (ClientSession member : recipients) {
            member.sendBattleObject(snapshot.objectId(), snapshot.name(), snapshot.name(),
                    snapshot.x(), snapshot.y(), snapshot.gfx(), BattleActionCodes.WALK,
                    0, snapshot.moveSpeed(), 0, snapshot.level(), 0, playerName(),
                    Protocol.healthRatio(snapshot.hp(), snapshot.maxHp()));
            member.sendEncrypted(Protocol.master(snapshot.objectId(), playerName()),
                    "S_MASTER tamed-companion=" + snapshot.objectId()
                            + " owner=" + playerName());
            member.sendEncrypted(Protocol.effectObject(
                            snapshot.objectId(), spell.effectGfx()),
                    "S_EFFECT taming-success target=" + snapshot.objectId()
                            + " gfx=" + spell.effectGfx());
        }
    }

    private void publishClassicWorldTaming(
            ClassicWorldMonsterPopulation.Capture capture,
            BattleCompanion companion, BattleSpellCatalog.TamingSpell spell,
            List<ClientSession> recipients) throws IOException {
        BattleCompanion.Snapshot snapshot = companion.snapshot();
        byte[] removed = Protocol.removeObject(capture.captured().objectId());
        byte[] effect = Protocol.effectObject(snapshot.objectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            member.sendEncrypted(removed,
                    "S_REMOVE_OBJECT classic-world-monster="
                            + capture.captured().objectId() + " reason=tamed");
            member.sendClassicWorldCompanionObject(this, snapshot, "taming");
            member.sendEncrypted(effect,
                    "S_EFFECT taming-success target=" + snapshot.objectId()
                            + " gfx=" + spell.effectGfx() + " phase=WORLD");
        }
    }

    private void publishQuestTaming(BattleQuestEncounter.Capture capture,
                                    BattleCompanion companion,
                                    BattleSpellCatalog.TamingSpell spell)
            throws IOException {
        BattleQuestEncounter.Snapshot captured = capture.captured();
        List<ClientSession> recipients = hub.battleRecipients(
                currentRoomId, captured.force());
        for (ClientSession member : recipients) {
            member.sendEncrypted(Protocol.removeObject(captured.objectId()),
                    "S_REMOVE_OBJECT quest-monster=" + captured.objectId()
                            + " reason=tamed");
        }
        publishTamedCompanion(companion, recipients, spell);
        if (capture.waveCleared()) {
            publishQuestWaveAdvance(captured.force(), capture.clearedRoom(),
                    capture.spawned(), capture.objectiveUnlocked(), "taming");
        }
    }

    private void publishTimeAttackTaming(BattleTimeAttackEncounter.Capture capture,
                                         BattleCompanion companion,
                                         BattleSpellCatalog.TamingSpell spell)
            throws IOException {
        List<ClientSession> recipients = hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            member.sendEncrypted(Protocol.removeObject(capture.captured().objectId()),
                    "S_REMOVE_OBJECT timeattack-actor="
                            + capture.captured().objectId() + " reason=tamed");
        }
        publishTamedCompanion(companion, recipients, spell);
        for (ClientSession member : recipients) {
            for (BattleTimeAttackEncounter.Snapshot spawned : capture.spawned()) {
                member.sendEncrypted(Protocol.timeAttackActor(spawned),
                        "S_PUT_OBJECT timeattack-actor=" + spawned.objectId()
                                + " npc=" + spawned.npcId() + " final-boss="
                                + spawned.finalBoss() + " source=taming");
            }
        }
        if (capture.spawned().stream()
                .anyMatch(BattleTimeAttackEncounter.Snapshot::activeAi)) {
            hub.armPveAi(currentRoomId);
        }
    }

    private static int heading(int sourceX, int sourceY, int targetX, int targetY) {
        int dx = Integer.compare(targetX, sourceX);
        int dy = Integer.compare(targetY, sourceY);
        if (dx > 0 && dy > 0) return 3;
        if (dx < 0 && dy < 0) return 7;
        if (dx > 0 && dy == 0) return 2;
        if (dx < 0 && dy == 0) return 6;
        if (dx == 0 && dy > 0) return 4;
        if (dx < 0) return 5;
        if (dx > 0) return 1;
        return 0;
    }

    private void useGroundSpell(byte[] payload,
                                BattleSpellCatalog.GroundSpell spell) throws IOException {
        Protocol.GroundSpellRequest request = Protocol.groundSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        BattleAnimationCatalog animations = BattleAnimationCatalog.get();
        if (!animations.supportsTimedAction(battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL rejected unavailable cast action player="
                    + playerName() + " gfx=" + battleGfx() + " action=" + spell.actionId()
                    + " skill=" + spell.skillId());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);
        RuntimeInventory previousInventory;
        BattleGroundEffects.CastResult placed;
        int remainingMp;
        long originRoomId;
        int originX;
        int originY;
        int committedHeading;
        synchronized (this) {
            long castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            originRoomId = currentRoomId;
            originX = positionX;
            originY = positionY;
            committedHeading = heading(originX, originY, request.x(), request.y());
            ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(
                    hub.battleMapId(originRoomId, this));
            int range = Math.max(Math.abs(originX - request.x()),
                    Math.abs(originY - request.y()));
            if (phase != Phase.BATTLE || observer || playerHp <= 0
                    || castNow < readyAt || playerMp < mpCost
                    || !arena.nativeStandingFloor(originX, originY)
                    || !arena.contains(request.x(), request.y())
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, request.x(), request.y())
                    || spell.maximumRange() >= 0
                        && range > spell.maximumRange()) {
                System.out.println("[LiTo] C_USE_SPELL ground rejected skill="
                        + spell.skillId() + " x=" + request.x() + " y="
                        + request.y() + " range=" + range + " max="
                        + spell.maximumRange() + " mp=" + playerMp + " cost="
                        + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }

            RuntimeInventory nextInventory = inventory.copy();
            if (spell.itemConsumeId() != 0
                    && !nextInventory.removeCatalog(
                            spell.itemConsumeId(), spell.itemConsumeCount())) {
                System.out.println("[LiTo] C_USE_SPELL ground rejected missing reagent skill="
                        + spell.skillId() + " catalog=" + spell.itemConsumeId()
                        + " count=" + spell.itemConsumeCount());
                return;
            }
            previousInventory = inventory;
            placed = hub.placeGroundSpell(originRoomId, this, spell,
                    originX, originY, request.x(), request.y(), castNow, () -> {
                        inventory = nextInventory;
                        playerMp -= mpCost;
                        spellReadyNanos.put(spell.skillId(), castNow
                                + spell.reuseDelayMillis() * 1_000_000L);
                        if (spell.skillId() == BattleSpellCatalog.FIRE_WALL) {
                            playerHeading = committedHeading;
                        }
                    });
            if (!placed.accepted()) {
                System.out.println("[LiTo] C_USE_SPELL ground rejected placement skill="
                        + spell.skillId() + " x=" + request.x() + " y="
                        + request.y());
                return;
            }
            remainingMp = playerMp;
        }

        cancelMeditation("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        if (spell.itemConsumeId() != 0) {
            sendInventoryDelta(previousInventory, inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        }

        byte[] action = new Protocol.Writer().c(Protocol.S_ACTION)
                .d(playerObjectId()).c(spell.actionId()).bytes();
        byte[] direction = spell.skillId() == BattleSpellCatalog.FIRE_WALL
                ? new Protocol.Writer().c(Protocol.S_CHANGE_DIRECTION).d(playerObjectId())
                        .c(committedHeading).bytes()
                : null;
        for (ClientSession member : hub.roomMembers(originRoomId)) {
            if (direction != null) {
                member.sendEncrypted(direction,
                        "S_CHANGE_DIRECTION fire-wall object=" + playerObjectId());
            }
            member.sendEncrypted(action,
                    "S_ACTION spell-cast object=" + playerObjectId()
                            + " action=" + spell.actionId() + " skill=" + spell.skillId());
            for (ArenaMapCatalog.Point point : placed.points()) {
                member.sendEncrypted(Protocol.effectLocation(
                                point.x(), point.y(), spell.effectGfx()),
                        "S_EFFECT_LOC skill=" + spell.skillId() + " key=" + spell.key()
                                + " x=" + point.x() + " y=" + point.y()
                                + " gfx=" + spell.effectGfx());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT ground-spell=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL ground skill=" + spell.skillId()
                + " caster=" + playerName() + " points=" + placed.points().size()
                + " duration=" + spell.durationSeconds() + "s mp="
                + remainingMp + "/" + playerMaxMp + " cost=" + mpCost
                + " effective-int=" + effectiveIntelligence);
    }

    /**
     * Native ordinary-WORLD {@code ccchh} producer shared by Fire Wall (58)
     * and Life Stream (63). Placement, MP, reagent, reuse and heading are
     * committed atomically; interruptible cast statuses are cleared only
     * after that commit, then delivery is scoped to the selected client's
     * exact native screen predicate.
     */
    private void useClassicWorldGroundSpell(
            byte[] payload, BattleSpellCatalog.GroundSpell spell)
            throws IOException {
        Protocol.GroundSpellRequest request =
                Protocol.groundSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;
        if (!admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "ground-" + spell.key())) {
            return;
        }

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        int range = Math.max(Math.abs(originX - request.x()),
                Math.abs(originY - request.y()));
        if (!map.contains(request.x(), request.y())
                || !BattleSpellCatalog.isInNativeScreen(
                        originX, originY, request.x(), request.y())
                || spell.maximumRange() >= 0
                    && range > spell.maximumRange()) {
            System.out.println("[LiTo] C_USE_SPELL classic-world ground rejected"
                    + " target skill=" + spell.skillId() + " x=" + request.x()
                    + " y=" + request.y() + " range=" + range + " max="
                    + spell.maximumRange() + " map=" + originMapId
                    + " instance=" + originInstanceId);
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);
        RuntimeInventory previousInventory;
        ClassicWorldGroundEffects.CastResult placed;
        int remainingMp;
        int committedHeading = heading(
                originX, originY, request.x(), request.y());
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(
                    spell.skillId(), 0L);
            int commitRange = Math.max(Math.abs(originX - request.x()),
                    Math.abs(originY - request.y()));
            if (phase != Phase.WORLD || observer || playerHp <= 0
                    || classicWorldMapId != originMapId
                    || classicWorldInstanceId != originInstanceId
                    || positionX != originX || positionY != originY
                    || castNow < readyAt || playerMp < mpCost
                    || !map.standingPassable(originX, originY)
                    || !map.contains(request.x(), request.y())
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, request.x(), request.y())
                    || spell.maximumRange() >= 0
                        && commitRange > spell.maximumRange()) {
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE classic-world-ground-insufficient-mp=278"
                                    + " skill=" + spell.skillId());
                }
                System.out.println("[LiTo] C_USE_SPELL classic-world ground"
                        + " rejected state skill=" + spell.skillId()
                        + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }

            RuntimeInventory nextInventory = inventory.copy();
            if (spell.itemConsumeId() != 0
                    && !nextInventory.removeCatalog(
                            spell.itemConsumeId(), spell.itemConsumeCount())) {
                System.out.println("[LiTo] C_USE_SPELL classic-world ground"
                        + " rejected missing reagent skill=" + spell.skillId()
                        + " catalog=" + spell.itemConsumeId() + " count="
                        + spell.itemConsumeCount());
                return;
            }
            previousInventory = inventory;
            placed = hub.placeClassicWorldGroundSpell(
                    originMapId, originInstanceId, this, spell,
                    originX, originY, request.x(), request.y(), castNow, () -> {
                        inventory = nextInventory;
                        playerMp -= mpCost;
                        spellReadyNanos.put(spell.skillId(), castNow
                                + spell.reuseDelayMillis() * 1_000_000L);
                        if (spell.skillId() == BattleSpellCatalog.FIRE_WALL) {
                            playerHeading = committedHeading;
                        }
                    });
            if (!placed.accepted()) {
                System.out.println("[LiTo] C_USE_SPELL classic-world ground"
                        + " rejected placement skill=" + spell.skillId()
                        + " x=" + request.x() + " y=" + request.y());
                return;
            }
            remainingMp = playerMp;
        }

        cancelMeditation("classic-world-spell-" + spell.skillId());
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());
        if (spell.itemConsumeId() != 0) {
            sendInventoryDelta(previousInventory, inventory);
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
        }

        byte[] action = Protocol.objectAction(
                playerObjectId(), spell.actionId());
        byte[] direction = spell.skillId() == BattleSpellCatalog.FIRE_WALL
                ? Protocol.changeDirection(playerObjectId(), committedHeading)
                : null;
        for (ClientSession member : hub.classicWorldMembers(
                originMapId, originInstanceId)) {
            boolean seesCaster = BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, originX, originY);
            if (seesCaster && direction != null) {
                member.sendEncrypted(direction,
                        "S_CHANGE_DIRECTION classic-world Fire-Wall object="
                                + playerObjectId() + " heading="
                                + committedHeading);
            }
            if (seesCaster) {
                member.sendEncrypted(action,
                        "S_ACTION classic-world ground-cast object="
                                + playerObjectId() + " action="
                                + spell.actionId() + " skill="
                                + spell.skillId());
            }
            for (ClassicWorldGroundEffects.Point point : placed.points()) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY,
                        point.x(), point.y())) continue;
                member.sendEncrypted(Protocol.effectLocation(
                                point.x(), point.y(), spell.effectGfx()),
                        "S_EFFECT_LOC classic-world skill=" + spell.skillId()
                                + " key=" + spell.key() + " x=" + point.x()
                                + " y=" + point.y() + " gfx="
                                + spell.effectGfx());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world ground-spell=" + remainingMp
                        + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL classic-world ground skill="
                + spell.skillId() + " caster=" + playerName() + " map="
                + originMapId + " instance=" + originInstanceId + " points="
                + placed.points().size() + " duration="
                + spell.durationSeconds() + "s mp=" + remainingMp + "/"
                + playerMaxMp + " cost=" + mpCost + " effective-int="
                + effectiveIntelligence);
    }

    private boolean admitClassicWorldSpellFamily(
            int skillId, int actionId, String family) throws IOException {
        if (phase != Phase.WORLD) return true;
        long now = System.nanoTime();
        BattlePolymorphCatalog.Form active = polymorphStatus.active(now);
        if (active != null && !active.skillUsable()
                && !awakenStatus.snapshot().active()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-" + family
                            + "-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-" + family
                            + "-polymorph-rejected=285");
            return false;
        }
        if (timedStatus.silenceActive(now)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-" + family
                            + "-silenced-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-" + family
                            + "-silenced-rejected=285");
            return false;
        }
        if (currentWeight240(now) >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE classic-world-" + family
                            + "-overweight=316");
            return false;
        }
        if (!learnedSkills.contains(skillId)
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), actionId)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world " + family
                    + " rejected learned/action player=" + playerName()
                    + " skill=" + skillId + " action=" + actionId);
            return false;
        }
        return true;
    }

    /**
     * Revalidates mutable caster admission at the same atomic boundary that
     * spends centered-area HP/MP and publishes the authoritative reuse time.
     * Target discovery can perform source lookups, so the request-time checks
     * alone are not sufficient when another session applies a status while
     * that work is in progress.
     */
    private boolean centeredAreaCasterStillAdmitted(
            Phase expectedPhase, int skillId, int actionId, long now) {
        BattlePolymorphCatalog.Form active = polymorphStatus.active(now);
        boolean polymorphRejected = active != null && !active.skillUsable()
                && (expectedPhase != Phase.WORLD
                    || !awakenStatus.snapshot().active());
        return !timedStatus.actionLocked(now)
                && !timedStatus.silenceActive(now)
                && currentWeight240(now)
                    < BattleInventoryWeight.BUFFED_REGEN_LIMIT
                && learnedSkills.contains(skillId)
                && !polymorphRejected
                && BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), actionId);
    }

    /** Atomic caster-side admission for selected skill71 after source lookup. */
    private boolean decayPotionCasterStillAdmitted(
            Phase expectedPhase, BattleSpellCatalog.DecayPotionSpell spell,
            long now) {
        BattlePolymorphCatalog.Form active = polymorphStatus.active(now);
        boolean polymorphRejected = active != null && !active.skillUsable()
                && (expectedPhase != Phase.WORLD
                    || !awakenStatus.snapshot().active());
        return !timedStatus.actionLocked(now)
                && !timedStatus.silenceActive(now)
                && currentWeight240(now)
                    < BattleInventoryWeight.BUFFED_REGEN_LIMIT
                && learnedSkills.contains(spell.skillId())
                && !polymorphRejected
                && BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId());
    }

    /** Atomic caster-side admission for selector-only native skill72. */
    private boolean counterDetectionCasterStillAdmitted(
            Phase expectedPhase,
            BattleSpellCatalog.CounterDetectionSpell spell,
            long now) {
        BattlePolymorphCatalog.Form active = polymorphStatus.active(now);
        boolean polymorphRejected = active != null && !active.skillUsable()
                && (expectedPhase != Phase.WORLD
                    || !awakenStatus.snapshot().active());
        return !timedStatus.actionLocked(now)
                && !timedStatus.silenceActive(now)
                && currentWeight240(now)
                    < BattleInventoryWeight.BUFFED_REGEN_LIMIT
                && learnedSkills.contains(spell.skillId())
                && !polymorphRejected
                && BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId());
    }

    private void useNaturesBlessingSpell(
            byte[] payload, BattleSpellCatalog.NaturesBlessingSpell spell)
            throws IOException {
        useNaturesBlessingSpell(payload, spell, 0);
    }

    /** Test-only fixed die result; zero preserves the native independent d12 rolls. */
    private void useNaturesBlessingSpell(
            byte[] payload, BattleSpellCatalog.NaturesBlessingSpell spell,
            int dieRollFixture) throws IOException {
        if (dieRollFixture < 0 || dieRollFixture > spell.dieSides()) {
            throw new IllegalArgumentException(
                    "invalid Nature's Blessing die fixture");
        }
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        if (originPhase == Phase.WORLD
                && !admitClassicWorldSpellFamily(
                        spell.skillId(), spell.actionId(), "Natures-Blessing")) {
            return;
        }

        // Retained isNormalSkillUsable()/isAttrAgrees() precedes target and
        // resource handling and rejects a non-water ordinary elf silently.
        if ((elfAttribute & spell.attribute()) == 0 && !isAdministrator()) {
            System.out.println("[LiTo] C_USE_SPELL Nature's Blessing rejected"
                    + " attribute player=" + playerName() + " required="
                    + spell.attribute() + " elf-attr=" + elfAttribute
                    + " phase=" + originPhase);
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Nature's Blessing rejected"
                    + " unavailable action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long targetNow = System.nanoTime();
        List<ClientSession> possiblePlayers = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.roomCombatants(originRoomId);
        LinkedHashSet<ClientSession> playerTargets = new LinkedHashSet<>();
        // target=none, non-attack and area=-1 explicitly inserts the caster.
        playerTargets.add(this);
        for (ClientSession candidate : possiblePlayers) {
            if (candidate == this || candidate.phase != originPhase
                    || candidate.observer || candidate.invisible
                    || candidate.playerHp <= 0 || !sameClassicParty(candidate)
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY,
                            candidate.positionX, candidate.positionY)
                    || BattleAbsoluteBarrierRules.blocksIncomingSpell(
                            candidate.timedStatus.absoluteBarrierActive(targetNow),
                            spell.skillId())) {
                continue;
            }
            boolean sameWorld = originPhase == Phase.WORLD
                    ? candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId
                    : candidate.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, candidate) == originMapId;
            if (sameWorld) playerTargets.add(candidate);
        }
        List<BattleCompanion.Snapshot> companionTargets =
                (originPhase == Phase.WORLD
                        ? classicWorldCompanionSnapshots()
                        : controlledCompanionSnapshots()).stream()
                .filter(BattleCompanion.Snapshot::active)
                .filter(companion -> companion.hp() > 0)
                .filter(companion -> BattleSpellCatalog.isInNativeScreen(
                        originX, originY, companion.x(), companion.y()))
                .toList();

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int intelligence = equipment.effectiveIntelligence(
                caster == null ? 8 : caster.intelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterWorld = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (originPhase == Phase.WORLD
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            if (castNow < readyAt || playerMp < mpCost || !sameCasterWorld) {
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE Natures-Blessing-insufficient-mp=278");
                }
                System.out.println("[LiTo] C_USE_SPELL Nature's Blessing rejected"
                        + " state player=" + playerName() + " mp=" + playerMp
                        + " cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow)
                        + " phase=" + phase);
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        // A successful ordinary cast ends the caster's barrier/invisibility.
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        record PlayerHealing(ClientSession target, int afterHp, int rolled,
                             int lawfulHealing, int adjustedHealing,
                             boolean consumedWaterLife) {}
        record CompanionHealing(BattleCompanion.Snapshot after, int rolled,
                                int lawfulHealing) {}
        List<PlayerHealing> healedPlayers = new ArrayList<>();
        for (ClientSession target : playerTargets) {
            synchronized (target) {
                boolean stillSameWorld = target.phase == originPhase
                        && !target.observer && target.playerHp > 0
                        && (target == this || !target.invisible)
                        && BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                target.positionX, target.positionY)
                        && (target == this || sameClassicParty(target))
                        && (target == this || !BattleAbsoluteBarrierRules
                                .blocksIncomingSpell(
                                    target.timedStatus.absoluteBarrierActive(castNow),
                                    spell.skillId()))
                        && (originPhase == Phase.WORLD
                            ? target.classicWorldMapId == originMapId
                                && target.classicWorldInstanceId == originInstanceId
                            : target.currentRoomId == originRoomId
                                && hub.battleMapId(originRoomId, target) == originMapId);
                if (!stillSameWorld) continue;
                int rolled = spell.rollHealing(intelligence,
                        sides -> dieRollFixture == 0
                                ? ThreadLocalRandom.current().nextInt(1, sides + 1)
                                : dieRollFixture);
                int lawfulHealing = spell.applyLawfulRevision(
                        rolled, caster == null ? 0 : characterLawful());
                boolean waterLife = target.waterLifeStatus.active(castNow);
                int beforeRecovery = waterLife
                        ? Math.multiplyExact(lawfulHealing, 2) : lawfulHealing;
                int adjustedHealing = BattleHealingRecovery.adjustedAmount(
                        beforeRecovery,
                        target.timedStatus.polluteWaterActive(castNow),
                        target.timedStatus.waterDragonDirtyCurrentActive(castNow),
                        target.timedStatus.waterDragonHealingErosionActive(castNow));
                boolean consumedWaterLife = target.waterLifeStatus.cancel();
                if (adjustedHealing >= 0) {
                    target.playerHp = Math.min(target.playerMaxHp,
                            Math.addExact(target.playerHp, adjustedHealing));
                }
                healedPlayers.add(new PlayerHealing(
                        target, target.playerHp, rolled, lawfulHealing,
                        adjustedHealing, consumedWaterLife));
            }
        }

        List<CompanionHealing> healedCompanions = new ArrayList<>();
        for (BattleCompanion.Snapshot expected : companionTargets) {
            BattleCompanion companion = ownedCompanion(expected.objectId());
            if (companion == null) continue;
            BattleCompanion.Snapshot current = companion.snapshot();
            if (!current.active() || current.hp() <= 0
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, current.x(), current.y())) continue;
            int rolled = spell.rollHealing(intelligence,
                    sides -> dieRollFixture == 0
                            ? ThreadLocalRandom.current().nextInt(1, sides + 1)
                            : dieRollFixture);
            int lawfulHealing = spell.applyLawfulRevision(
                    rolled, caster == null ? 0 : characterLawful());
            companion.heal(lawfulHealing);
            healedCompanions.add(new CompanionHealing(
                    companion.snapshot(), rolled, lawfulHealing));
        }

        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                member.positionX, member.positionY))) continue;
            member.sendEncrypted(action,
                    "S_ACTION Natures-Blessing caster=" + playerObjectId()
                            + " action=" + spell.actionId());
            member.sendEncrypted(effect,
                    "S_EFFECT Natures-Blessing target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Natures-Blessing="
                        + remainingMp + "/" + playerMaxMp);
        for (PlayerHealing healing : healedPlayers) {
            ClientSession target = healing.target();
            if (healing.adjustedHealing() < 0) {
                if (originPhase == Phase.WORLD) {
                    target.takeClassicWorldPlayerDamage(
                            -healing.adjustedHealing(), this, false);
                } else {
                    target.takePlayerDamage(
                            -healing.adjustedHealing(), this, false);
                }
            } else {
                target.sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                                .h(healing.afterHp()).h(target.playerMaxHp).bytes(),
                        "S_HIT_POINT Natures-Blessing=" + healing.afterHp()
                                + "/" + target.playerMaxHp);
                target.broadcastHitRatio(target.playerObjectId(),
                        healing.afterHp(), target.playerMaxHp,
                        "spell-natures-blessing");
            }
        }
        for (CompanionHealing healing : healedCompanions) {
            BattleCompanion.Snapshot after = healing.after();
            byte[] ratio = Protocol.hitRatio(
                    after.objectId(), after.hp(), after.maxHp());
            for (ClientSession member : recipients) {
                if (originPhase == Phase.WORLD
                        && (member.classicWorldMapId != originMapId
                            || member.classicWorldInstanceId != originInstanceId
                            || !BattleSpellCatalog.isInNativeScreen(
                                    after.x(), after.y(),
                                    member.positionX, member.positionY))) continue;
                member.sendEncrypted(ratio,
                        "S_HIT_RATIO Natures-Blessing-companion="
                                + after.objectId() + " hp=" + after.hp()
                                + "/" + after.maxHp());
            }
        }
        System.out.println("[LiTo] C_USE_SPELL Nature's Blessing caster="
                + playerName() + " selector=" + request.row() + "/"
                + request.column() + " player-targets=" + healedPlayers.size()
                + " companion-targets=" + healedCompanions.size()
                + " self-healed="
                + healedPlayers.stream().anyMatch(healing -> healing.target() == this)
                + " dice-per-target=" + spell.diceCount(intelligence) + "d"
                + spell.dieSides() + " effective-int=" + intelligence
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/"
                + playerMaxMp + " attribute-gate=water"
                + " target-to=party|pet area=native-screen"
                + " counter-magic-bypass=" + spell.counterMagicBypass()
                + " phase=" + originPhase
                + " custom-extra-heal=excluded");
    }

    private void useGroupHealingSpell(
            byte[] payload, BattleSpellCatalog.GroupHealingSpell spell) throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        if (originPhase == Phase.WORLD
                && !admitClassicWorldSpellFamily(
                        spell.skillId(), spell.actionId(), "group-healing")) {
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL group-heal rejected unavailable action player="
                    + playerName() + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int intelligence = equipment.effectiveIntelligence(
                caster == null ? 8 : caster.intelligence());
        int characterType = caster == null ? 0 : caster.type();
        int originalIntelligence = caster == null
                ? 0 : Math.max(0, caster.originalIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                characterType, originalIntelligence);
        int mpCost = spell.effectiveMpCost(intelligence, originalReduction);
        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        ArenaMapCatalog.Arena casterArena = originPhase == Phase.BATTLE
                ? ArenaMapCatalog.forMap(originMapId) : null;
        ClassicWorldMapCatalog.ClassicMap casterWorldMap =
                originPhase == Phase.WORLD
                        ? ClassicWorldMapCatalog.forMap(originMapId) : null;
        long targetNow = System.nanoTime();

        List<ClientSession> possiblePlayers = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.visibleBattleCombatants(originRoomId, this);
        List<ClientSession> playerTargets = possiblePlayers.stream()
                // Retained HEAL_ALL explicitly excludes the caster even though
                // target=none normally inserts the user into an area target list.
                .filter(candidate -> candidate != this)
                .filter(candidate -> candidate.phase == originPhase
                        && !candidate.observer && !candidate.invisible
                        && candidate.playerHp > 0)
                .filter(candidate -> !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                        candidate.timedStatus.absoluteBarrierActive(targetNow),
                        spell.skillId()))
                .filter(candidate -> originPhase == Phase.WORLD
                        ? candidate.classicWorldMapId == originMapId
                            && candidate.classicWorldInstanceId == originInstanceId
                        : candidate.currentRoomId == originRoomId
                            && originMapId == hub.battleMapId(originRoomId, candidate))
                .filter(candidate -> BattleSpellCatalog.isInNativeScreen(
                        originX, originY,
                        candidate.positionX, candidate.positionY))
                .filter(candidate -> originPhase == Phase.WORLD
                        ? casterWorldMap.hasLineOfSight(
                            originX, originY,
                            candidate.positionX, candidate.positionY)
                        : BattleSpellCatalog.hasNativeLineOfSight(
                            casterArena, originX, originY,
                            candidate.positionX, candidate.positionY))
                // DB target_to=20 contains CLAN(4) but not PARTY(8).
                .filter(candidate -> hub.sameClan(sourceCharacterIdentity(),
                        candidate.sourceCharacterIdentity()))
                .toList();
        List<BattleCompanion.Snapshot> companionTargets =
                (originPhase == Phase.WORLD
                        ? classicWorldCompanionSnapshots()
                        : controlledCompanionSnapshots()).stream()
                .filter(BattleCompanion.Snapshot::active)
                .filter(companion -> companion.hp() > 0)
                .filter(companion -> BattleSpellCatalog.isInNativeScreen(
                        originX, originY, companion.x(), companion.y()))
                .filter(companion -> originPhase == Phase.WORLD
                        ? casterWorldMap.hasLineOfSight(
                            originX, originY, companion.x(), companion.y())
                        : BattleSpellCatalog.hasNativeLineOfSight(
                            casterArena, originX, originY,
                            companion.x(), companion.y()))
                .toList();

        int remainingHp;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            // Same-family isHPMPConsume requires hpConsume+1, so a valid cast
            // can never spend the caster down to zero HP.
            boolean sameCasterWorld = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (originPhase == Phase.WORLD
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            if (castNow < readyAt || playerMp < mpCost || playerHp <= spell.hpCost()
                    || !sameCasterWorld) {
                System.out.println("[LiTo] C_USE_SPELL group-heal rejected skill="
                        + spell.skillId() + " hp=" + playerHp + " hp-cost="
                        + spell.hpCost() + " mp=" + playerMp + " mp-cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow)
                        + " phase=" + phase);
                return;
            }
            playerHp -= spell.hpCost();
            playerMp -= mpCost;
            remainingHp = playerHp;
            remainingMp = playerMp;
            spellReadyNanos.put(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        // Normal retained casts break barrier/invisibility before action/GFX.
        cancelMeditation("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        record PlayerHealing(ClientSession target, int beforeHp, int afterHp,
                             int rolled, int appliedHealing) {}
        record CompanionHealing(BattleCompanion.Snapshot before,
                                BattleCompanion.Snapshot after,
                                int rolled, int lawfulHealing) {}
        List<PlayerHealing> healedPlayers = new ArrayList<>();
        for (ClientSession target : playerTargets) {
            int rolled = spell.rollHealing(intelligence,
                    sides -> ThreadLocalRandom.current().nextInt(1, sides + 1));
            int lawfulHealing = spell.applyLawfulRevision(
                    rolled, caster == null ? 0 : characterLawful());
            synchronized (target) {
                boolean stillSameWorld = target.phase == originPhase
                        && (originPhase == Phase.WORLD
                            ? target.classicWorldMapId == originMapId
                                && target.classicWorldInstanceId == originInstanceId
                            : target.currentRoomId == originRoomId
                                && hub.battleMapId(originRoomId, target) == originMapId);
                boolean lineOfSight = originPhase == Phase.WORLD
                        ? casterWorldMap.hasLineOfSight(
                            originX, originY,
                            target.positionX, target.positionY)
                        : BattleSpellCatalog.hasNativeLineOfSight(
                            casterArena, originX, originY,
                            target.positionX, target.positionY);
                if (!stillSameWorld || target.observer
                        || target.invisible || target.playerHp <= 0
                        || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY,
                            target.positionX, target.positionY)
                        || !lineOfSight
                        || !hub.sameClan(sourceCharacterIdentity(),
                            target.sourceCharacterIdentity())) {
                    continue;
                }
                int beforeHp = target.playerHp;
                long recoveryNow = System.nanoTime();
                int appliedHealing = BattleHealingRecovery.adjustedAmount(
                        lawfulHealing,
                        target.timedStatus.polluteWaterActive(recoveryNow),
                        target.timedStatus.waterDragonDirtyCurrentActive(recoveryNow),
                        target.timedStatus.waterDragonHealingErosionActive(recoveryNow));
                if (appliedHealing >= 0) {
                    target.playerHp = Math.min(
                            target.playerMaxHp, target.playerHp + appliedHealing);
                }
                healedPlayers.add(new PlayerHealing(
                        target, beforeHp, target.playerHp, rolled, appliedHealing));
            }
        }
        List<CompanionHealing> healedCompanions = new ArrayList<>();
        for (BattleCompanion.Snapshot before : companionTargets) {
            BattleCompanion companion = ownedCompanion(before.objectId());
            if (companion == null) continue;
            BattleCompanion.Snapshot current = companion.snapshot();
            boolean lineOfSight = originPhase == Phase.WORLD
                    ? casterWorldMap.hasLineOfSight(
                        originX, originY, current.x(), current.y())
                    : BattleSpellCatalog.hasNativeLineOfSight(
                        casterArena, originX, originY,
                        current.x(), current.y());
            if (!current.active() || current.hp() <= 0
                    || !BattleSpellCatalog.isInNativeScreen(
                        originX, originY, current.x(), current.y())
                    || !lineOfSight) {
                continue;
            }
            int rolled = spell.rollHealing(intelligence,
                    sides -> ThreadLocalRandom.current().nextInt(1, sides + 1));
            int lawfulHealing = spell.applyLawfulRevision(
                    rolled, caster == null ? 0 : characterLawful());
            companion.heal(lawfulHealing);
            healedCompanions.add(new CompanionHealing(
                    current, companion.snapshot(), rolled, lawfulHealing));
        }

        List<ClientSession> recipients;
        if (originPhase == Phase.WORLD) {
            recipients = classicWorldMembers(originMapId);
        } else {
            BattleRules.RuleSet rules = hub.roomRules(originRoomId);
            recipients = rules.mode() == BattleRules.Mode.QUEST_BATTLE
                    ? hub.battleRecipients(
                        originRoomId, hub.forceOf(originRoomId, this))
                    : hub.roomMembers(originRoomId);
        }
        byte[] action = new Protocol.Writer().c(Protocol.S_ACTION)
                .d(playerObjectId()).c(spell.actionId()).bytes();
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY,
                            member.positionX, member.positionY))) continue;
            member.sendEncrypted(action,
                    "S_ACTION group-healing-cast object=" + playerObjectId()
                            + " action=" + spell.actionId() + " skill=" + spell.skillId());
            member.sendEncrypted(effect,
                    "S_EFFECT group-healing skill=" + spell.skillId()
                            + " key=" + spell.key() + " target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT group-healing-hp-cost=" + remainingHp + "/" + playerMaxHp);
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT group-healing=" + remainingMp + "/" + playerMaxMp);
        for (PlayerHealing healing : healedPlayers) {
            ClientSession target = healing.target();
            if (healing.appliedHealing() < 0) {
                if (originPhase == Phase.WORLD) {
                    target.takeClassicWorldPlayerDamage(
                            -healing.appliedHealing(), this, false);
                } else {
                    target.takePlayerDamage(
                            -healing.appliedHealing(), this, false);
                }
            } else {
                target.sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                                .h(healing.afterHp()).h(target.playerMaxHp).bytes(),
                        "S_HIT_POINT group-healing=" + healing.afterHp()
                                + "/" + target.playerMaxHp + " skill=" + spell.skillId());
                target.broadcastHitRatio(target.playerObjectId(), healing.afterHp(),
                        target.playerMaxHp, "spell-group-heal-" + spell.skillId());
            }
        }
        for (CompanionHealing healing : healedCompanions) {
            BattleCompanion.Snapshot after = healing.after();
            byte[] ratio = Protocol.hitRatio(
                    after.objectId(), after.hp(), after.maxHp());
            for (ClientSession member : recipients) {
                if (originPhase == Phase.WORLD
                        && (member.classicWorldMapId != originMapId
                            || member.classicWorldInstanceId != originInstanceId
                            || !BattleSpellCatalog.isInNativeScreen(
                                after.x(), after.y(),
                                member.positionX, member.positionY))) continue;
                member.sendEncrypted(ratio,
                        "S_HIT_RATIO group-healing-companion="
                                + after.objectId() + " hp=" + after.hp()
                                + "/" + after.maxHp()
                                + " skill=" + spell.skillId());
            }
        }
        System.out.println("[LiTo] C_USE_SPELL group-healing skill=" + spell.skillId()
                + " caster=" + playerName() + " selector=" + request.row()
                + "/" + request.column() + " player-targets=" + healedPlayers.size()
                + " pet-targets=" + healedCompanions.size()
                + " self-healed=false effective-int=" + intelligence
                + " dice-per-target=" + spell.diceCount(intelligence) + "d"
                + spell.dieSides() + " hp-cost=" + spell.hpCost()
                + " mp-cost=" + mpCost + " hp=" + remainingHp + "/" + playerMaxHp
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " target-to=clan|own-pet area=native-screen");
    }

    private void useClassicWorldHealingSpell(
            byte[] payload, BattleSpellCatalog.HealingSpell spell)
            throws IOException {
        useClassicWorldHealingSpell(payload, spell, 0);
    }

    /** Test-only die fixture; zero preserves the native random healing dice. */
    private void useClassicWorldHealingSpell(
            byte[] payload, BattleSpellCatalog.HealingSpell spell,
            int dieRollFixture) throws IOException {
        if (dieRollFixture < 0 || dieRollFixture > spell.dieSides()) {
            throw new IllegalArgumentException(
                    "invalid classic-world healing die fixture");
        }
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-healing-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-healing-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-healing-silenced-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-healing-silenced-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE classic-world-healing-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world healing rejected"
                    + " learned/action player=" + playerName()
                    + " skill=" + spell.skillId());
            return;
        }

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        List<ClientSession> worldMembers = classicWorldMembers(originMapId);
        ClientSession playerTarget = worldMembers.stream()
                .filter(candidate -> sameClassicWorldMap(candidate)
                        && candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        ClientSession companionOwner = worldMembers.stream()
                .filter(this::sameClassicWorldMap)
                .filter(candidate -> candidate.classicWorldCompanionSnapshot(
                        request.targetObjectId()) != null)
                .findFirst().orElse(null);
        BattleCompanion.Snapshot companionTarget = companionOwner == null ? null
                : companionOwner.classicWorldCompanionSnapshot(
                        request.targetObjectId());
        ClassicWorldMonsterPopulation.Snapshot monsterTarget =
                hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId());
        boolean validMonster = monsterTarget != null && monsterTarget.present()
                && monsterTarget.alive() && monsterTarget.mapId() == originMapId;
        int targetCount = (playerTarget == null ? 0 : 1)
                + (companionTarget == null ? 0 : 1)
                + (validMonster ? 1 : 0);
        if (targetCount != 1) {
            System.out.println("[LiTo] C_USE_SPELL classic-world healing rejected"
                    + " unknown/dead/ambiguous target=" + request.targetObjectId()
                    + " matches=" + targetCount
                    + " skill=" + spell.skillId());
            return;
        }

        int targetX = playerTarget != null ? playerTarget.positionX
                : companionTarget != null ? companionTarget.x()
                : monsterTarget.x();
        int targetY = playerTarget != null ? playerTarget.positionY
                : companionTarget != null ? companionTarget.y()
                : monsterTarget.y();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        boolean livingPlayer = playerTarget == null
                || playerTarget.phase == Phase.WORLD
                    && !playerTarget.observer && playerTarget.playerHp > 0
                    && (playerTarget == this || !playerTarget.invisible)
                    && sameClassicWorldMap(playerTarget);
        boolean livingCompanion = companionTarget == null
                || companionTarget.active() && companionTarget.hp() > 0;
        boolean absoluteBarrierBlocked = playerTarget != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                    playerTarget.timedStatus.absoluteBarrierActive(requestNow),
                    spell.skillId());
        if (!livingPlayer || !livingCompanion
                || absoluteBarrierBlocked
                || !BattleSpellCatalog.isInNativeScreen(
                        originX, originY, targetX, targetY)
                || !map.hasLineOfSight(originX, originY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world healing rejected"
                    + " gate/screen target=" + request.targetObjectId()
                    + " absolute-barrier=" + absoluteBarrierBlocked
                    + " skill=" + spell.skillId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int targetNpcId = companionTarget != null ? companionTarget.npcId()
                : monsterTarget != null ? monsterTarget.npcId() : 0;
        if (targetNpcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(targetNpcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] classic-world healing source NPC lookup"
                        + " failed player=" + playerName() + " npc=" + targetNpcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int intelligence = equipment.effectiveIntelligence(
                caster == null ? 8 : caster.intelligence());
        int characterType = caster == null ? 0 : caster.type();
        int originalIntelligence = caster == null
                ? 0 : Math.max(0, caster.originalIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                characterType, originalIntelligence);
        int mpCost = spell.effectiveMpCost(
                intelligence, originalReduction, equipment.healingHelmEquipped());
        int rolled = 0;
        for (int index = 0; index < spell.diceCount(intelligence); index++) {
            rolled += dieRollFixture == 0
                    ? ThreadLocalRandom.current().nextInt(1, spell.dieSides() + 1)
                    : dieRollFixture;
        }
        int lawfulHealing = spell.applyLawfulRevision(
                rolled, caster == null ? 0 : characterLawful());

        int adjustedHealing = lawfulHealing;
        boolean targetWaterLife = false;
        boolean consumedWaterLife = false;
        boolean targetPolluteWater = false;
        int hpAfter = -1;
        int remainingMp;
        long castNow;
        ClientSession targetLock = playerTarget != null
                ? playerTarget : companionOwner;
        ClientSession firstLock = targetLock == null
                || playerObjectId() <= targetLock.playerObjectId()
                ? this : targetLock;
        ClientSession secondLock = targetLock == null
                ? this : firstLock == this ? targetLock : this;
        synchronized (firstLock) {
            synchronized (secondLock) {
                castNow = System.nanoTime();
                long readyAt = spellReadyNanos.getOrDefault(
                        spell.skillId(), 0L);
                BattleCompanion.Snapshot lockedCompanion = null;
                if (companionTarget != null && companionOwner != null) {
                    BattleCompanion controlled = companionOwner.ownedCompanion(
                            companionTarget.objectId());
                    lockedCompanion = controlled == null
                            ? null : controlled.snapshot();
                }
                ClassicWorldMonsterPopulation.Snapshot lockedMonster =
                        monsterTarget == null ? null : hub.classicWorldMonster(
                            originMapId, originInstanceId,
                            monsterTarget.objectId());
                boolean targetStillAvailable = playerTarget != null
                        ? playerTarget.phase == Phase.WORLD
                            && !playerTarget.observer
                            && playerTarget.playerHp > 0
                            && (playerTarget == this
                                || !playerTarget.invisible)
                            && playerTarget.classicWorldMapId == originMapId
                            && playerTarget.classicWorldInstanceId
                                == originInstanceId
                            && playerTarget.positionX == targetX
                            && playerTarget.positionY == targetY
                            && !BattleAbsoluteBarrierRules
                                .blocksIncomingSpell(
                                    playerTarget.timedStatus
                                        .absoluteBarrierActive(castNow),
                                    spell.skillId())
                        : companionTarget != null
                            ? lockedCompanion != null
                                && lockedCompanion.active()
                                && lockedCompanion.hp() > 0
                                && lockedCompanion.x() == targetX
                                && lockedCompanion.y() == targetY
                            : lockedMonster != null
                                && lockedMonster.present()
                                && lockedMonster.alive()
                                && lockedMonster.mapId() == originMapId
                                && lockedMonster.x() == targetX
                                && lockedMonster.y() == targetY;
                boolean endpointStillAllowed = phase == Phase.WORLD
                        && !observer && playerHp > 0
                        && classicWorldMapId == originMapId
                        && classicWorldInstanceId == originInstanceId
                        && positionX == originX && positionY == originY
                        && BattleSpellCatalog.isInNativeScreen(
                            originX, originY, targetX, targetY)
                        && map.hasLineOfSight(
                            originX, originY, targetX, targetY);
                if (!targetStillAvailable || !endpointStillAllowed
                        || castNow < readyAt || playerMp < mpCost) {
                    if (playerMp < mpCost) {
                        sendEncrypted(Protocol.messageCode(278),
                                "S_MESSAGE_CODE classic-world-healing-insufficient-mp=278");
                    }
                    System.out.println("[LiTo] C_USE_SPELL classic-world healing rejected"
                            + " state player=" + playerName() + " skill="
                            + spell.skillId() + " mp=" + playerMp
                            + " cost=" + mpCost + " target-available="
                            + targetStillAvailable + " endpoint="
                            + endpointStillAllowed + " cooldownNanos="
                            + Math.max(0L, readyAt - castNow));
                    return;
                }
                if (lockedCompanion != null) companionTarget = lockedCompanion;
                if (lockedMonster != null) monsterTarget = lockedMonster;
                if (monsterTarget != null) {
                    targetPolluteWater =
                            hub.classicWorldMonsterPolluteWaterActive(
                                originMapId, originInstanceId,
                                monsterTarget.objectId(), castNow);
                    adjustedHealing =
                            BattleHealingRecovery.adjustedSingleTargetAmount(
                                lawfulHealing, false, targetPolluteWater,
                                false, false);
                } else if (playerTarget != null) {
                    targetWaterLife =
                            playerTarget.waterLifeStatus.active(castNow);
                    targetPolluteWater = playerTarget.timedStatus
                            .polluteWaterActive(castNow);
                    adjustedHealing =
                            BattleHealingRecovery.adjustedSingleTargetAmount(
                                lawfulHealing, targetWaterLife,
                                targetPolluteWater,
                                playerTarget.timedStatus
                                    .waterDragonDirtyCurrentActive(castNow),
                                playerTarget.timedStatus
                                    .waterDragonHealingErosionActive(castNow));
                }
                playerMp -= mpCost;
                remainingMp = playerMp;
                spellReadyNanos.put(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
                if (playerTarget != null) {
                    consumedWaterLife = playerTarget.waterLifeStatus.cancel();
                    if (adjustedHealing >= 0) {
                        playerTarget.playerHp = Math.min(
                                playerTarget.playerMaxHp,
                                Math.addExact(playerTarget.playerHp,
                                    adjustedHealing));
                    }
                    hpAfter = playerTarget.playerHp;
                }
            }
        }
        cancelMeditation("classic-world-spell-" + spell.skillId());
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(request.targetObjectId(), spell.effectGfx());
        for (ClientSession member : worldMembers) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, originX, originY)
                        && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, targetX, targetY)) {
                continue;
            }
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION classic-world healing caster=" + playerObjectId()
                                + " action=" + spell.actionId()
                                + " skill=" + spell.skillId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT classic-world healing target="
                            + request.targetObjectId() + " gfx="
                            + spell.effectGfx() + " skill=" + spell.skillId());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world healing="
                        + remainingMp + "/" + playerMaxMp);

        int npcHpDelta = npcStats == null ? 0
                : spell.npcHpDelta(npcStats.undead(), adjustedHealing);
        if (playerTarget != null) {
            if (hpAfter >= 0) {
                if (adjustedHealing < 0) {
                    playerTarget.takeClassicWorldPlayerDamage(
                            -adjustedHealing, this, false);
                    hpAfter = playerTarget.playerHp;
                } else {
                    playerTarget.sendEncrypted(
                            new Protocol.Writer().c(Protocol.S_HIT_POINT)
                                    .h(hpAfter).h(playerTarget.playerMaxHp).bytes(),
                            "S_HIT_POINT classic-world healing=" + hpAfter
                                    + "/" + playerTarget.playerMaxHp);
                    playerTarget.broadcastHitRatio(
                            playerTarget.playerObjectId(), hpAfter,
                            playerTarget.playerMaxHp,
                            "classic-world-healing-" + spell.skillId());
                }
                if (spell.happenMessage() > 0) {
                    playerTarget.sendEncrypted(
                            Protocol.messageCode(spell.happenMessage()),
                            "S_MESSAGE_CODE classic-world healing-applied="
                                    + spell.happenMessage()
                                    + " skill=" + spell.skillId());
                }
            }
        } else if (companionTarget != null && companionOwner != null) {
            BattleCompanion companion = companionOwner.ownedCompanion(
                    companionTarget.objectId());
            if (companion != null && npcHpDelta < 0) {
                companionOwner.applyClassicWorldMonsterCompanionDamage(
                        companion, companionTarget, -npcHpDelta,
                        playerObjectId(), "healing-spell-undead");
                hpAfter = companion.snapshot().hp();
            } else if (companion != null && npcHpDelta > 0) {
                companion.heal(npcHpDelta);
                BattleCompanion.Snapshot after = companion.snapshot();
                hpAfter = after.hp();
                byte[] ratio = Protocol.hitRatio(
                        after.objectId(), after.hp(), after.maxHp());
                for (ClientSession member : worldMembers) {
                    if (sameClassicWorldMap(member)
                            && BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                after.x(), after.y())) {
                        member.sendEncrypted(ratio,
                                "S_HIT_RATIO classic-world companion-healing="
                                        + after.objectId() + " hp=" + after.hp()
                                        + "/" + after.maxHp()
                                        + " skill=" + spell.skillId());
                    }
                }
            }
        } else if (monsterTarget != null && npcHpDelta < 0) {
            ClassicWorldMonsterPopulation.Hit transition =
                    hub.damageClassicWorldMonster(
                            originMapId, originInstanceId,
                            monsterTarget.objectId(), playerObjectId(),
                            -npcHpDelta);
            if (transition != null) {
                hub.provokeClassicWorldMonster(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), playerObjectId());
                publishClassicWorldSpellMonsterDamage(
                        spell.skillId(), transition);
                hpAfter = transition.after().currentHp();
            }
        } else if (monsterTarget != null && npcHpDelta > 0) {
            ClassicWorldMonsterPopulation.Healing healing =
                    hub.healClassicWorldMonster(
                            originMapId, originInstanceId,
                            monsterTarget.objectId(), npcHpDelta);
            if (healing != null) {
                ClassicWorldMonsterPopulation.Snapshot after = healing.after();
                hpAfter = after.currentHp();
                byte[] ratio = Protocol.hitRatio(
                        after.objectId(), after.currentHp(), after.maximumHp());
                for (ClientSession member : worldMembers) {
                    if (sameClassicWorldMap(member)
                            && BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                after.x(), after.y())) {
                        member.sendEncrypted(ratio,
                                "S_HIT_RATIO classic-world monster-healing="
                                        + after.objectId() + " hp="
                                        + after.currentHp() + "/"
                                        + after.maximumHp() + " skill="
                                        + spell.skillId());
                    }
                }
            }
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world healing skill="
                + spell.skillId() + " caster=" + playerName() + " target="
                + request.targetObjectId() + " player-target="
                + (playerTarget != null) + " companion-target="
                + (companionTarget != null) + " npc=" + targetNpcId
                + " undead=" + (npcStats == null ? 0 : npcStats.undead())
                + " rolled=" + rolled + " lawful-healing=" + lawfulHealing
                + " adjusted-healing=" + adjustedHealing
                + " water-life=" + targetWaterLife
                + " water-life-consumed=" + consumedWaterLife
                + " pollute-water=" + targetPolluteWater
                + " npc-hp-delta=" + npcHpDelta + " hp-after=" + hpAfter
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/"
                + playerMaxMp);
    }


    /** Resolve only active actors in this room/map; never substitute the caster for a missing target. */
    private MassSlowCompanionTarget resolveBattleSpellCompanion(long objectId) {
        if (phase != Phase.BATTLE || observer || objectId == 0) return null;
        int map = hub.battleMapId(currentRoomId, this);
        for (ClientSession owner : hub.roomCombatants(currentRoomId)) {
            if (owner.phase != Phase.BATTLE || owner.observer || owner.currentRoomId != currentRoomId
                    || hub.battleMapId(currentRoomId, owner) != map) continue;
            BattleCompanion controlled = owner.ownedCompanion(objectId);
            if (controlled == null) continue;
            BattleCompanion.Snapshot actor = controlled.snapshot();
            if (!actor.active() || actor.hp() <= 0) return null;
            try {
                SourceNpcPhysicalStats stats = selectedSourceAccounts().npcPhysicalStats(actor.npcId());
                return new MassSlowCompanionTarget(owner, controlled, actor, stats);
            } catch (Exception failure) {
                System.out.println("[LiTo] battle companion spell target lookup failed npc=" + actor.npcId()
                        + " reason=" + failure.getClass().getSimpleName());
                return null;
            }
        }
        return null;
    }

    private boolean battleSpellCompanionStillAvailable(MassSlowCompanionTarget target) {
        ClientSession owner = target.owner();
        BattleCompanion.Snapshot actor = target.controlled().snapshot();
        return phase == Phase.BATTLE && !observer && playerHp > 0
                && owner.phase == Phase.BATTLE && !owner.observer
                && owner.currentRoomId == currentRoomId
                && hub.battleMapId(currentRoomId, owner) == hub.battleMapId(currentRoomId, this)
                && owner.ownedCompanion(actor.objectId()) == target.controlled()
                && actor.active() && actor.hp() > 0
                && actor.objectId() == target.snapshot().objectId()
                && actor.x() == target.snapshot().x() && actor.y() == target.snapshot().y();
    }

    private int applyBattleSpellCompanionDamage(MassSlowCompanionTarget target, int damage, int skillId)
            throws IOException {
        if (damage <= 0 || !battleSpellCompanionStillAvailable(target)) return 0;
        BattleCompanion.Damage hit = applyBattleCompanionFeedbackDamage(target.controlled(), damage,
                hub.roomMembers(currentRoomId), "targeted-spell-" + skillId);
        if (hit == null || hit.appliedDamage() <= 0) return 0;
        markBattleCombatWith(target.owner());
        return hit.appliedDamage();
    }

    private void useHealingSpell(byte[] payload,
                                 BattleSpellCatalog.HealingSpell spell) throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        long originRoomId = currentRoomId;
        int originMapId = hub.battleMapId(originRoomId, this);
        int originX = positionX;
        int originY = positionY;
        List<ClientSession> combatants = hub.roomCombatants(originRoomId);
        ClientSession target = combatants.stream()
                .filter(candidate -> candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        BattleGuardianTower.Snapshot targetTower =
                hub.guardianTower(originRoomId, request.targetObjectId());
        BattleQuestEncounter.Snapshot targetMonster =
                hub.questMonster(originRoomId, request.targetObjectId());
        BattleTimeAttackEncounter.Snapshot targetTimeActor =
                hub.timeAttackActor(originRoomId, request.targetObjectId());
        boolean botTarget = request.targetObjectId() == 2
                && hub.roomRules(originRoomId).mode() != BattleRules.Mode.QUEST_BATTLE
                && hub.roomRules(originRoomId).mode() != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(originRoomId) < 2
                && hub.botHp(originRoomId) > 0;
        ArenaMapCatalog.Point bot = botTarget ? hub.botPosition(originRoomId) : null;

        MassSlowCompanionTarget companionTarget = resolveBattleSpellCompanion(request.targetObjectId());
        int targetX;
        int targetY;
        int targetNpcId = 0;
        if (target != null) {
            targetX = target.positionX;
            targetY = target.positionY;
        } else if (targetTower != null) {
            targetX = targetTower.x();
            targetY = targetTower.y();
        } else if (targetMonster != null) {
            targetX = targetMonster.x();
            targetY = targetMonster.y();
            targetNpcId = targetMonster.npcId();
        } else if (targetTimeActor != null) {
            targetX = targetTimeActor.x();
            targetY = targetTimeActor.y();
            targetNpcId = targetTimeActor.npcId();
        } else if (companionTarget != null) {
            targetX = companionTarget.snapshot().x();
            targetY = companionTarget.snapshot().y();
            targetNpcId = companionTarget.snapshot().npcId();
        } else if (bot != null) {
            targetX = bot.x();
            targetY = bot.y();
        } else {
            System.out.println("[LiTo] C_USE_SPELL rejected unknown healing target skill="
                    + spell.skillId() + " target=" + request.targetObjectId());
            return;
        }
        boolean sameMap = target == null || originMapId
                == hub.battleMapId(originRoomId, target);
        boolean visibleQuestTarget = targetMonster == null
                || hub.visibleQuestMonsters(originRoomId, this).stream()
                .anyMatch(snapshot -> snapshot.objectId() == targetMonster.objectId());
        boolean visibleTowerTarget = targetTower == null
                || hub.visibleGuardianTowers(originRoomId, this).stream()
                .anyMatch(snapshot -> snapshot.objectId() == targetTower.objectId());
        boolean visibleTimeTarget = targetTimeActor == null
                || hub.visibleTimeAttackActors(originRoomId, this).stream()
                .anyMatch(snapshot -> snapshot.objectId()
                        == targetTimeActor.objectId());
        boolean healableTowerTarget = targetTower == null
                || hub.canHealGuardianTower(
                        originRoomId, this, targetTower.objectId());
        long requestNow = System.nanoTime();
        boolean absoluteBarrierBlocked = target != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                    target.timedStatus.absoluteBarrierActive(requestNow),
                    spell.skillId());
        boolean validLivingTarget = target != null
                ? target.phase == Phase.BATTLE && !target.observer
                    && !target.invisible && target.playerHp > 0
                    && target.currentRoomId == originRoomId
                    && !absoluteBarrierBlocked
                : targetTower != null ? targetTower.hp() > 0
                    && visibleTowerTarget && healableTowerTarget
                : targetMonster != null ? targetMonster.alive() && visibleQuestTarget
                : targetTimeActor != null ? targetTimeActor.alive()
                    && visibleTimeTarget
                : companionTarget != null ? battleSpellCompanionStillAvailable(companionTarget)
                : botTarget;
        if (!sameMap || !validLivingTarget
                || !BattleSpellCatalog.isInNativeScreen(
                        originX, originY, targetX, targetY)
                || !BattleSpellCatalog.hasNativeLineOfSight(
                        ArenaMapCatalog.forMap(originMapId),
                        originX, originY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL rejected unavailable healing target skill="
                    + spell.skillId() + " target=" + request.targetObjectId()
                    + " same-map=" + sameMap + " visible-quest=" + visibleQuestTarget
                    + " visible-tower=" + visibleTowerTarget
                    + " visible-time=" + visibleTimeTarget
                    + " healable-tower=" + healableTowerTarget
                    + " absolute-barrier=" + absoluteBarrierBlocked);
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL rejected unavailable heal action player="
                    + playerName() + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        if (targetNpcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(targetNpcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected healing spell; source NPC lookup failed"
                        + " player=" + playerName() + " npc=" + targetNpcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int intelligence = equipment.effectiveIntelligence(
                caster == null ? 8 : caster.intelligence());
        int characterType = caster == null ? 0 : caster.type();
        int originalIntelligence = caster == null
                ? 0 : Math.max(0, caster.originalIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                characterType, originalIntelligence);
        int mpCost = spell.effectiveMpCost(
                intelligence, originalReduction, equipment.healingHelmEquipped());
        int rolled = 0;
        for (int index = 0; index < spell.diceCount(intelligence); index++) {
            rolled += ThreadLocalRandom.current().nextInt(1, spell.dieSides() + 1);
        }
        int healedAmount = spell.applyLawfulRevision(
                rolled, caster == null ? 0 : characterLawful());
        int adjustedHealingAmount = healedAmount;
        boolean targetWaterLife = false;
        boolean consumedWaterLife = false;
        boolean targetPolluteWater = false;
        boolean targetWaterDragonDirtyCurrent = false;
        boolean targetWaterDragonHealingErosion = false;
        int healedHp = -1;
        int remainingMp;
        long castNow;
        ClientSession firstLock = target == null
                || playerObjectId() <= target.playerObjectId()
                ? this : target;
        ClientSession secondLock = target == null
                ? this : firstLock == this ? target : this;
        synchronized (firstLock) {
            synchronized (secondLock) {
                castNow = System.nanoTime();
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                BattleGuardianTower.Snapshot lockedTower = targetTower == null
                        ? null : hub.guardianTower(
                            originRoomId, targetTower.objectId());
                BattleQuestEncounter.Snapshot lockedMonster = targetMonster == null
                        ? null : hub.questMonster(
                            originRoomId, targetMonster.objectId());
                BattleTimeAttackEncounter.Snapshot lockedTime =
                        targetTimeActor == null ? null : hub.timeAttackActor(
                            originRoomId, targetTimeActor.objectId());
                ArenaMapCatalog.Point lockedBot = botTarget
                        ? hub.botPosition(originRoomId) : null;
                boolean targetStillAvailable = target != null
                        ? target.phase == Phase.BATTLE && !target.observer
                            && !target.invisible && target.playerHp > 0
                            && target.currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, target)
                                == originMapId
                            && target.positionX == targetX
                            && target.positionY == targetY
                            && !BattleAbsoluteBarrierRules
                                .blocksIncomingSpell(
                                    target.timedStatus
                                        .absoluteBarrierActive(castNow),
                                    spell.skillId())
                        : targetTower != null
                            ? lockedTower != null && lockedTower.hp() > 0
                                && lockedTower.x() == targetX
                                && lockedTower.y() == targetY
                                && hub.canHealGuardianTower(originRoomId,
                                    this, lockedTower.objectId())
                                && hub.visibleGuardianTowers(
                                    originRoomId, this).stream().anyMatch(
                                        row -> row.objectId()
                                            == lockedTower.objectId())
                            : targetMonster != null
                                ? lockedMonster != null
                                    && lockedMonster.alive()
                                    && lockedMonster.x() == targetX
                                    && lockedMonster.y() == targetY
                                    && hub.visibleQuestMonsters(
                                        originRoomId, this).stream().anyMatch(
                                            row -> row.objectId()
                                                == lockedMonster.objectId())
                                : targetTimeActor != null
                                    ? lockedTime != null && lockedTime.alive()
                                        && lockedTime.x() == targetX
                                        && lockedTime.y() == targetY
                                        && hub.visibleTimeAttackActors(
                                            originRoomId, this).stream().anyMatch(
                                                row -> row.objectId()
                                                    == lockedTime.objectId())
                                    : companionTarget != null
                                        ? battleSpellCompanionStillAvailable(companionTarget)
                                        : lockedBot != null
                                        && hub.botHp(originRoomId) > 0
                                        && lockedBot.x() == targetX
                                        && lockedBot.y() == targetY;
                boolean endpointStillAllowed = phase == Phase.BATTLE
                        && !observer && playerHp > 0
                        && currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, this) == originMapId
                        && positionX == originX && positionY == originY
                        && BattleSpellCatalog.isInNativeScreen(
                            originX, originY, targetX, targetY)
                        && BattleSpellCatalog.hasNativeLineOfSight(
                            ArenaMapCatalog.forMap(originMapId),
                            originX, originY, targetX, targetY);
                if (castNow < readyAt || playerMp < mpCost
                        || !targetStillAvailable || !endpointStillAllowed) {
                    System.out.println("[LiTo] C_USE_SPELL heal rejected skill="
                            + spell.skillId() + " target="
                            + request.targetObjectId() + " mp=" + playerMp
                            + " cost=" + mpCost + " target-available="
                            + targetStillAvailable + " endpoint="
                            + endpointStillAllowed + " cooldownNanos="
                            + Math.max(0L, readyAt - castNow));
                    return;
                }
                playerMp -= mpCost;
                remainingMp = playerMp;
                spellReadyNanos.put(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
                if (target != null) {
                    targetPolluteWater =
                            target.timedStatus.polluteWaterActive(castNow);
                    targetWaterLife = target.waterLifeStatus.active(castNow);
                    targetWaterDragonDirtyCurrent = target.timedStatus
                            .waterDragonDirtyCurrentActive(castNow);
                    targetWaterDragonHealingErosion = target.timedStatus
                            .waterDragonHealingErosionActive(castNow);
                    adjustedHealingAmount =
                            BattleHealingRecovery.adjustedSingleTargetAmount(
                                healedAmount, targetWaterLife,
                                targetPolluteWater,
                                targetWaterDragonDirtyCurrent,
                                targetWaterDragonHealingErosion);
                    consumedWaterLife = target.waterLifeStatus.cancel();
                    if (adjustedHealingAmount >= 0) {
                        target.playerHp = Math.min(
                                target.playerMaxHp,
                                Math.addExact(target.playerHp,
                                    adjustedHealingAmount));
                    }
                    healedHp = target.playerHp;
                } else {
                    targetPolluteWater = targetMonster != null
                            ? hub.questMonsterPolluteWaterActive(
                                originRoomId, targetMonster.objectId(), castNow)
                            : targetTimeActor != null
                                && hub.timeAttackActorPolluteWaterActive(
                                    originRoomId,
                                    targetTimeActor.objectId(), castNow);
                    adjustedHealingAmount =
                            BattleHealingRecovery.adjustedSingleTargetAmount(
                                healedAmount, false, targetPolluteWater,
                                false, false);
                }
            }
        }
        cancelMeditation("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        byte[] action = new Protocol.Writer().c(Protocol.S_ACTION)
                .d(playerObjectId()).c(spell.actionId()).bytes();
        byte[] effect = Protocol.effectObject(request.targetObjectId(), spell.effectGfx());
        List<ClientSession> recipients = targetMonster != null
                ? hub.battleRecipients(originRoomId, targetMonster.force())
                : targetTower != null
                    && hub.roomRules(originRoomId).mode() == BattleRules.Mode.QUEST_BATTLE
                    ? hub.battleRecipients(originRoomId, targetTower.force())
                    : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION healing-cast object=" + playerObjectId()
                                + " action=" + spell.actionId() + " skill=" + spell.skillId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT healing skill=" + spell.skillId() + " key=" + spell.key()
                            + " target=" + request.targetObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT healing=" + remainingMp + "/" + playerMaxMp);
        int undeadType = npcStats == null ? 0 : npcStats.undead();
        int npcHpDelta = target == null
                ? spell.npcHpDelta(undeadType, adjustedHealingAmount) : 0;
        if (target != null) {
            if (adjustedHealingAmount < 0) {
                target.takePlayerDamage(-adjustedHealingAmount, this, false);
                healedHp = target.playerHp;
            } else {
                target.sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                                .h(healedHp).h(target.playerMaxHp).bytes(),
                        "S_HIT_POINT healing=" + healedHp + "/" + target.playerMaxHp);
                target.broadcastHitRatio(target.playerObjectId(), healedHp,
                        target.playerMaxHp, "spell-heal-" + spell.skillId());
            }
            if (spell.happenMessage() > 0) {
                target.sendEncrypted(Protocol.messageCode(spell.happenMessage()),
                        "S_MESSAGE_CODE healing-applied=" + spell.happenMessage()
                                + " skill=" + spell.skillId());
            }
        } else if (companionTarget != null) {
            if (battleSpellCompanionStillAvailable(companionTarget)) {
                if (npcHpDelta < 0) {
                    applyBattleSpellCompanionDamage(companionTarget, -npcHpDelta, spell.skillId());
                } else if (npcHpDelta > 0) {
                    companionTarget.controlled().heal(npcHpDelta);
                    BattleCompanion.Snapshot after = companionTarget.controlled().snapshot();
                    for (ClientSession member : recipients) {
                        member.sendEncrypted(Protocol.hitRatio(after.objectId(), after.hp(), after.maxHp()),
                                "S_HIT_RATIO battle-companion-healing=" + after.objectId()
                                    + " skill=" + spell.skillId() + " hp=" + after.hp());
                    }
                }
                healedHp = companionTarget.controlled().snapshot().hp();
            }
        } else if (npcHpDelta < 0) {
            if (targetMonster != null) {
                applyQuestMonsterDamage(targetMonster.objectId(), -npcHpDelta,
                        "healing-spell-undead-" + spell.skillId());
            } else if (targetTimeActor != null) {
                applyTimeAttackActorDamage(targetTimeActor.objectId(), -npcHpDelta,
                        "healing-spell-undead-" + spell.skillId());
            }
        } else if (npcHpDelta > 0) {
            if (targetTower != null) {
                BattleGuardianTower.Healing healing = hub.healGuardianTower(
                        originRoomId, this, targetTower.objectId(), npcHpDelta);
                if (healing != null) {
                    BattleGuardianTower.Snapshot after = healing.after();
                    byte[] ratio = Protocol.hitRatio(
                            after.objectId(), after.hp(), after.maxHp());
                    for (ClientSession member : recipients) {
                        member.sendEncrypted(ratio,
                                "S_HIT_RATIO honor-relic-healing="
                                        + after.objectId() + " force=" + after.force()
                                        + " hp=" + after.hp() + "/" + after.maxHp()
                                        + " restored=" + healing.restoredHp()
                                        + " skill=" + spell.skillId());
                        if (healing.actionChanged()) {
                            member.sendEncrypted(Protocol.objectAction(
                                            after.objectId(), after.action()),
                                    "S_ACTION honor-relic-healing="
                                            + after.objectId() + " action="
                                            + after.action() + " skill="
                                            + spell.skillId());
                        }
                    }
                    healedHp = after.hp();
                }
            } else if (targetMonster != null) {
                BattleQuestEncounter.Healing healing = hub.healQuestMonster(
                        originRoomId, this, targetMonster.objectId(), npcHpDelta);
                if (healing != null) {
                    BattleQuestEncounter.Snapshot after = healing.after();
                    byte[] ratio = Protocol.hitRatio(after.objectId(), after.hp(), after.maxHp());
                    for (ClientSession member : recipients) {
                        member.sendEncrypted(ratio,
                                "S_HIT_RATIO quest-monster-healing=" + after.objectId()
                                        + " hp=" + after.hp() + "/" + after.maxHp()
                                        + " skill=" + spell.skillId());
                    }
                    healedHp = after.hp();
                }
            } else if (targetTimeActor != null) {
                BattleTimeAttackEncounter.Healing healing = hub.healTimeAttackActor(
                        originRoomId, this, targetTimeActor.objectId(), npcHpDelta);
                if (healing != null) {
                    BattleTimeAttackEncounter.Snapshot after = healing.after();
                    byte[] ratio = Protocol.hitRatio(after.objectId(), after.hp(), after.maxHp());
                    for (ClientSession member : recipients) {
                        member.sendEncrypted(ratio,
                                "S_HIT_RATIO timeattack-actor-healing=" + after.objectId()
                                        + " hp=" + after.hp() + "/" + after.maxHp()
                                        + " skill=" + spell.skillId());
                    }
                    healedHp = after.hp();
                }
            } else if (botTarget) {
                healedHp = hub.healBot(originRoomId, npcHpDelta);
                broadcastHitRatio(2, healedHp, GameHub.ARENA_BOT_MAX_HP,
                        "spell-heal-" + spell.skillId());
            }
        }
        System.out.println("[LiTo] C_USE_SPELL healing skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + request.targetObjectId()
                + " npc=" + targetNpcId + " undead=" + undeadType
                + " effective-int=" + intelligence + " dice="
                + spell.diceCount(intelligence) + " rolled=" + rolled
                + " lawful-healing=" + healedAmount
                + " adjusted-healing=" + adjustedHealingAmount
                + " water-life=" + targetWaterLife
                + " water-life-consumed=" + consumedWaterLife
                + " pollute-water=" + targetPolluteWater
                + " water-dragon-dirty-current="
                + targetWaterDragonDirtyCurrent
                + " water-dragon-healing-erosion="
                + targetWaterDragonHealingErosion
                + " npc-hp-delta=" + npcHpDelta
                + " hp-after=" + healedHp
                + " mp-cost=" + mpCost + " helm=" + equipment.healingHelmEquipped()
                + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    private void notifyPeersOfDisconnect() throws IOException {
        if (phase == Phase.WORLD) {
            notifyClassicWorldPeersOfRemoval("disconnect");
            return;
        }
        if (rentalTownRoomState && phase == Phase.BATTLE) {
            prepareRentalHotelDeparture("disconnect");
            notifyRentalTownDeparture("disconnect");
            return;
        }
        if (phase != Phase.ROOM && phase != Phase.BATTLE && phase != Phase.RESULT) return;
        boolean battleCombatantDisconnect = phase == Phase.BATTLE
                && hub.registerBattleDisconnect(currentRoomId, this);
        byte[] roomExit = new Protocol.Writer().c(Protocol.S_LITO_EXIT_ROOM)
                .d(currentRoomId).s(litoDisplayName()).bytes();
        byte[] removed = Protocol.removeObject(playerObjectId());
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            if (member == this) continue;
            try {
                if (phase == Phase.BATTLE && !observer) {
                    member.sendEncrypted(removed, "S_REMOVE_OBJECT disconnected=" + playerName());
                }
                member.sendEncrypted(roomExit, "S_LITO_EXIT_ROOM disconnected=" + playerName());
            } catch (IOException error) {
                // Near-simultaneous closes legitimately make the peer socket
                // unavailable. The authoritative resolver still observes both
                // sessions and must not be cancelled by this best-effort UI hint.
                System.out.println("[LiTo] disconnect peer notification skipped recipient="
                        + member.playerName() + " reason=" + error.getMessage());
            }
        }
        if (battleCombatantDisconnect) {
            System.out.println("[LiTo] battle disconnect pending room=" + currentRoomId
                    + " player=" + playerName() + " graceMs="
                    + GameHub.BATTLE_DISCONNECT_GRACE_MS);
        }
    }

    private void attack(byte[] payload, AttackEnvelope envelope) throws IOException {
        int expectedOpcode = switch (envelope) {
            case DIRECT -> Protocol.C_ATTACK;
            case FAR -> Protocol.C_FAR_ATTACK;
            case ALTERNATE -> Protocol.C_ALT_ATTACK;
        };
        Protocol.AttackRequest request = Protocol.attackRequest(payload, expectedOpcode);
        int attackAction = BattleActionCodes.attackForWalk(battleWalkAction());
        if (!admitWindShackleAction(attackAction,
                "C_" + envelope.name() + "_ATTACK")) return;
        attack(request, envelope);
    }

    private boolean admitWindShackleAction(int actionId, String operation) {
        long nowNanos = System.nanoTime();
        BattleWindShackleStatus.Snapshot status =
                windShackleStatus.snapshot(nowNanos);
        if (!status.active()) return true;
        BattleAnimationCatalog.Animation animation = BattleAnimationCatalog.get()
                .requireTimedAction(battleGfx(), actionId);
        boolean admitted = windShackleStatus.tryAction(
                nowNanos, animation.durationMillis());
        if (!admitted) {
            System.out.println("[LiTo] Wind Shackle action throttled player="
                    + playerName() + " operation=" + operation
                    + " gfx=" + battleGfx() + " action=" + actionId
                    + " native-ms=" + animation.durationMillis()
                    + " multiplier=" + BattleWindShackleStatus.ACTION_MULTIPLIER
                    + " remaining=" + status.remainingSeconds());
        }
        return admitted;
    }

    /**
     * One retained weapon-buff authority shared by BATTLE, WORLD-player and
     * WORLD-monster physical attack consumers.
     */
    private NativeWeaponBuffModifiers nativeWeaponBuffModifiers(
            boolean ranged, long nowNanos) {
        int hit = Math.addExact(
                Math.addExact(
                        Math.addExact(
                                windShotStatus.physicalHit(ranged, nowNanos),
                                stormEyeStatus.physicalHit(ranged, nowNanos)),
                        stormShotStatus.physicalHit(ranged, nowNanos)),
                burningWeaponStatus.physicalHit(ranged, nowNanos));
        int damage = Math.addExact(
                Math.addExact(
                        Math.addExact(
                                Math.addExact(
                                        fireWeaponStatus.physicalDamage(ranged, nowNanos),
                                        fireBlessStatus.physicalDamage(ranged, nowNanos)),
                                stormEyeStatus.physicalDamage(ranged, nowNanos)),
                        stormShotStatus.physicalDamage(ranged, nowNanos)),
                burningWeaponStatus.physicalDamage(ranged, nowNanos));
        return new NativeWeaponBuffModifiers(hit, damage);
    }

    /**
     * Consumes native skill182 only for an admitted ordinary melee hit and
     * publishes its retained location effect to the relevant visibility set.
     */
    private boolean consumeBurningSlash(
            boolean eligible, long nowNanos, long targetObjectId,
            int targetX, int targetY, List<ClientSession> recipients,
            String source) throws IOException {
        if (!eligible || !burningSlashStatus.consume(nowNanos)) return false;
        BattleSpellCatalog.BurningSlashSpell spell =
                BattleSpellCatalog.burningSlashSpell(
                        BattleSpellCatalog.BURNING_SLASH);
        byte[] impact = Protocol.effectLocation(
                targetX, targetY, spell.impactGfx());
        for (ClientSession recipient : recipients) {
            if (phase == Phase.WORLD
                    && (recipient.phase != Phase.WORLD
                        || !sameClassicWorldMap(recipient)
                        || !BattleSpellCatalog.isInNativeScreen(
                                recipient.positionX, recipient.positionY,
                                targetX, targetY))) continue;
            recipient.sendEncrypted(impact,
                    "S_EFFECT_LOCATION Burning-Slash target=" + targetObjectId
                            + " x=" + targetX + " y=" + targetY
                            + " gfx=" + spell.impactGfx()
                            + " source=" + source);
        }
        System.out.println("[LiTo] Burning Slash consumed attacker="
                + playerName() + " target=" + targetObjectId
                + " x=" + targetX + " y=" + targetY
                + " source-damage-bonus=" + spell.nextMeleeDamage()
                + " impact-gfx=" + spell.impactGfx()
                + " source=" + source);
        return true;
    }

    /**
     * Retained ordinary-WORLD physical multiplier family. Burning Spirit and
     * Elemental Fire share one inclusive 1..100 roll; weapon double damage,
     * Double Brake and Soul of Flame contribute candidates, and only the
     * greatest multiplier is applied.
     */
    private ClassicWorldPhysicalProc classicWorldPhysicalProc(
            SourceWeaponPhysicalStats weapon, boolean physicalHit,
            boolean ranged, boolean soulOfFlameActive, long nowNanos) {
        boolean kiringkuAttack = weapon.present()
                && weapon.weaponType() == BattleKiringkuDamage.WEAPON_TYPE;
        boolean meleeProcEligible = physicalHit && !ranged && !kiringkuAttack;
        boolean burningSpiritActive = timedStatus.burningSpiritActive(nowNanos);
        boolean elementalFireActive = timedStatus.elementalFireActive(nowNanos);
        boolean sharedRollRequired = burningSpiritActive && meleeProcEligible
                || elementalFireActive && meleeProcEligible;
        int configuredSharedRoll = config.elementalFireProcFixtureRoll() > 0
                ? config.elementalFireProcFixtureRoll()
                : config.burningSpiritProcFixtureRoll();
        int sharedRoll = !sharedRollRequired ? 0
                : configuredSharedRoll > 0 ? configuredSharedRoll
                    : ThreadLocalRandom.current().nextInt(1, 101);
        BattlePhysicalProcBuff.Outcome burningSpirit =
                BattlePhysicalProcBuff.burningSpirit(
                        burningSpiritActive, meleeProcEligible,
                        burningSpiritActive && meleeProcEligible
                                ? sharedRoll : 0);
        BattlePhysicalProcBuff.Outcome elementalFire =
                BattlePhysicalProcBuff.elementalFire(
                        elementalFireActive, meleeProcEligible,
                        elementalFireActive && meleeProcEligible
                                ? sharedRoll : 0);
        boolean doubleBrakeActive = timedStatus.doubleBrakeActive(nowNanos);
        boolean doubleBrakeEligible = physicalHit && !ranged && weapon.present()
                && (weapon.weaponType() == 11 || weapon.weaponType() == 12);
        int doubleBrakeRoll = !doubleBrakeActive || !doubleBrakeEligible
                ? 0 : config.doubleBrakeProcFixtureRoll() > 0
                    ? config.doubleBrakeProcFixtureRoll()
                    : ThreadLocalRandom.current().nextInt(1, 101);
        BattlePhysicalProcBuff.Outcome doubleBrake =
                BattlePhysicalProcBuff.doubleBrake(
                        doubleBrakeActive, weapon.weaponType(), physicalHit,
                        doubleBrakeRoll);
        double multiplier = Math.max(
                Math.max(
                        Math.max(burningSpirit.multiplier(),
                                elementalFire.multiplier()),
                        doubleBrake.multiplier()),
                BattlePhysicalProcBuff.soulOfFlameMultiplier(
                        soulOfFlameActive));
        return new ClassicWorldPhysicalProc(
                burningSpirit, elementalFire, doubleBrake, multiplier);
    }

    private int chainswordWeaknessRoll(long nowNanos) {
        if (!config.chainswordWeaknessAdvanceFixtureEnabled()) {
            return ThreadLocalRandom.current().nextInt(100);
        }
        // Isolated TCP evidence needs a reproducible 0->1->2->3 transition.
        // The values are still exact members of the retained native windows:
        // 19 enters level1, while 39 advances levels1/2 through the 20..39 arm.
        int level = chainswordWeakness.snapshot(nowNanos).level();
        return level == 0 ? 19 : level < 3 ? 39 : 0;
    }

    private void attack(
            Protocol.AttackRequest request, AttackEnvelope envelope) throws IOException {
        if (phase == Phase.WORLD) {
            attackClassicWorld(request, envelope);
            return;
        }
        if (phase != Phase.BATTLE || observer) return;
        if (isPetRaceBattle()) {
            // Server-selected race pets intentionally expose only walk action
            // 0. A crafted attack must not enter ordinary combat resolution.
            System.out.println("[LiTo] PET_RACE attack rejected player="
                    + playerName() + " envelope=" + envelope
                    + " target=" + request.targetObjectId());
            return;
        }
        closePersonalShopIfOpen("attack");
        if (rejectWhileParalyzed("C_" + envelope.name() + "_ATTACK")) return;
        int weight240 = currentWeight240(System.nanoTime());
        if (weight240 >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(110),
                    "S_MESSAGE_CODE attack-overweight=110 weight240=" + weight240);
            System.out.println("[LiTo] rejected attack overweight player="
                    + playerName() + " weight240=" + weight240);
            return;
        }
        naturalHpRegen.noteAttack();
        naturalMpRegen.noteAttack();
        int walkAction = battleWalkAction();
        BattleAnimationCatalog.Animation attackAnimation = BattleAnimationCatalog.get()
                .requireTimedAction(battleGfx(),
                        BattleActionCodes.attackForWalk(walkAction));
        long target = request.targetObjectId();
        int x = request.x();
        int y = request.y();
        ClientSession targetSession = null;
        for (ClientSession candidate : hub.roomCombatants(currentRoomId)) {
            if (candidate.playerObjectId() == target) {
                targetSession = candidate;
                break;
            }
        }
        BattleGuardianTower.Snapshot targetTower =
                hub.guardianTower(currentRoomId, target);
        BattleQuestEncounter.Snapshot targetMonster =
                hub.questMonster(currentRoomId, target);
        BattleTimeAttackEncounter.Snapshot targetTimeBoss =
                hub.timeAttackActor(currentRoomId, target);
        MassSlowCompanionTarget targetCompanion = resolveBattleSpellCompanion(target);
        BattleRules.RuleSet rules = hub.roomRules(currentRoomId);
        List<ClientSession> combatants = hub.roomCombatants(currentRoomId);
        boolean botPresent = rules.mode() != BattleRules.Mode.QUEST_BATTLE
                && rules.mode() != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(currentRoomId) < 2;
        ArenaMapCatalog.Point botSpawn = ArenaMapCatalog
                .forMap(hub.battleMapId(currentRoomId, this)).botSpawn();
        int targetX = target == 2 && botPresent ? botSpawn.x()
                : targetSession != null ? targetSession.positionX
                : targetTower != null ? targetTower.x()
                : targetMonster != null ? targetMonster.x()
                : targetTimeBoss != null ? targetTimeBoss.x()
                : targetCompanion != null ? targetCompanion.snapshot().x() : x;
        int targetY = target == 2 && botPresent ? botSpawn.y()
                : targetSession != null ? targetSession.positionY
                : targetTower != null ? targetTower.y()
                : targetMonster != null ? targetMonster.y()
                : targetTimeBoss != null ? targetTimeBoss.y()
                : targetCompanion != null ? targetCompanion.snapshot().y() : y;
        int range = Math.max(Math.abs(positionX - targetX), Math.abs(positionY - targetY));
        boolean ranged = envelope == AttackEnvelope.FAR
                || (envelope == AttackEnvelope.ALTERNATE
                    && (walkAction == BattleActionCodes.BOW_WALK
                        || walkAction == BattleActionCodes.THROWING_KNIFE_WALK));
        if (target == playerObjectId()
                || (targetSession == null && targetTower == null
                    && targetMonster == null && targetTimeBoss == null && targetCompanion == null
                    && !(target == 2 && botPresent))
                || (targetSession != null && targetSession.invisible)) {
            System.out.printf("[LiTo] rejected invalid attack target player=%s "
                            + "target=%d ranged=%s range=%d%n",
                    playerName(), target, ranged, range);
            return;
        }
        if (targetSession != null
                && !hub.canAttack(currentRoomId, this, targetSession)) {
            System.out.printf("[LiTo] rejected friendly/non-PvP attack room=%d attacker=%s target=%s%n",
                    currentRoomId, playerName(), targetSession.playerName());
            return;
        }
        if (targetTower != null
                && !hub.canAttackGuardianTower(currentRoomId, this, target)) {
            System.out.printf("[LiTo] rejected friendly/destroyed guardian tower room=%d "
                            + "attacker=%s target=%d towerForce=%d%n",
                    currentRoomId, playerName(), target, targetTower.force());
            return;
        }
        if (targetMonster != null
                && !hub.canAttackQuestMonster(currentRoomId, this, target)) {
            System.out.printf("[LiTo] rejected foreign/dead Quest monster room=%d "
                            + "attacker=%s target=%d monsterForce=%d%n",
                    currentRoomId, playerName(), target, targetMonster.force());
            return;
        }
        if (targetTimeBoss != null
                && !hub.canAttackTimeAttackActor(currentRoomId, this, target)) {
            System.out.printf("[LiTo] rejected dead Time Attack actor room=%d "
                            + "attacker=%s target=%d%n",
                    currentRoomId, playerName(), target);
            return;
        }
        if (targetCompanion != null && (!battleSpellCompanionStillAvailable(targetCompanion)
                || targetCompanion.owner() != this
                    && !hub.canAttack(currentRoomId, this, targetCompanion.owner()))) return;
        int targetNpcId = targetMonster != null ? targetMonster.npcId()
                : targetTimeBoss != null ? targetTimeBoss.npcId()
                : targetCompanion != null ? targetCompanion.snapshot().npcId() : 0;
        SourceNpcPhysicalStats targetNpcPhysical = null;
        if (targetNpcId != 0) {
            try {
                targetNpcPhysical = selectedSourceAccounts().npcPhysicalStats(targetNpcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] rejected attack; source NPC physical lookup failed"
                        + " player=" + playerName() + " npc=" + targetNpcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
        }
        cancelMeditation("attack");
        // S_ATTACK's fixed header is c,d,d,c,c,d.  A zero trailing d selects
        // the no-extra-effect branch in LiTo's native 0x23 parser.
        int eventForce = targetMonster != null ? targetMonster.force()
                : targetTower != null ? targetTower.force()
                : hub.forceOf(currentRoomId, this);
        List<ClientSession> members = (targetMonster != null
                || (targetTower != null
                    && rules.mode() == BattleRules.Mode.QUEST_BATTLE))
                ? hub.battleRecipients(currentRoomId, eventForce)
                : hub.roomMembers(currentRoomId);
        BattleCookingStatus.Snapshot attackerCooking =
                cookingStatus.active(System.nanoTime());
        BattleDragonEyeStatus.Snapshot attackerDragonEye =
                dragonEyeStatus.snapshot(System.nanoTime());
        int cookingHitBonus = attackerCooking.physicalHit(ranged);
        int cookingDamageBonus = attackerCooking.physicalDamage(ranged);
        int dragonEyeMeleeDamage = ranged ? 0 : attackerDragonEye.meleeDamage();
        SourceEquipmentMagicStats attackerEquipment = requiredEquipmentMagicStats();
        SourceEquipmentPhysicalStats equipmentPhysical = attackerEquipment.physical();
        boolean sourceWeaponActive = !inventory.hasEquippedWeapon()
                && !sourceWeaponSuppressed;
        RuntimeInventory.Item runtimeWeaponSnapshot = sourceWeaponActive
                ? null : inventory.equippedWeaponItem();
        long runtimeWeaponObjectId = runtimeWeaponSnapshot == null
                ? 0 : runtimeWeaponSnapshot.objectId();
        SourceWeaponPhysicalStats sourceWeaponSnapshot =
                equipmentPhysical.weapon();
        SourceWeaponPhysicalStats activeWeapon = sourceWeaponActive
                ? sourceWeaponSnapshot
                : runtimeWeaponSnapshot == null
                    ? SourceWeaponPhysicalStats.none()
                    : inventory.equippedPhysicalWeapon();
        boolean sourceWeaponBonusesActive = sourceWeaponActive
                || runtimeWeaponSnapshot != null
                    && runtimeWeaponSnapshot.sourceBound()
                    && activeWeapon.present();
        if (sourceWeaponActive && activeWeapon.present()) {
            GameStateStore.SourceWeaponDurabilityBalance durability =
                    state.sourceWeaponDurabilityBalance(
                            stateCharacter(), sourceWeaponSnapshot);
            activeWeapon = activeWeapon.withDurability(
                    durability.effectiveDurability());
        }
        boolean kiringkuAttack = activeWeapon.present()
                && activeWeapon.weaponType() == BattleKiringkuDamage.WEAPON_TYPE;
        if (activeWeapon.present() && activeWeapon.ranged() != ranged) {
            System.out.println("[LiTo] rejected attack weapon/envelope mismatch player="
                    + playerName() + " weapon-type=" + activeWeapon.weaponType()
                    + " envelope=" + envelope + " ranged=" + ranged);
            return;
        }
        int sourceMaximumRange = BattlePhysicalAttack.maximumRange(activeWeapon);
        if (!BattlePhysicalAttack.supportsPosition(activeWeapon,
                positionX, positionY, targetX, targetY)) {
            System.out.println("[LiTo] rejected attack outside source weapon range player="
                    + playerName() + " target=" + target
                    + " weapon-item=" + activeWeapon.itemId()
                    + " weapon-type=" + activeWeapon.weaponType()
                    + " range=" + range + " max=" + sourceMaximumRange);
            return;
        }
        SourceProjectilePhysicalStats projectile = activeWeapon.projectile();
        GameStateStore.SourceProjectileReservation projectileReservation = null;
        long projectileRuntimeObjectId = 0;
        RuntimeInventory.Item projectileBefore = null;
        RuntimeInventory.Item projectileAfter = null;
        if (ranged) {
            RuntimeInventory.Item runtimeProjectile = projectile.present()
                    ? inventory.item(projectile.objectId()) : null;
            if (runtimeProjectile != null && runtimeProjectile.sourceBound()) {
                long sourceProjectileObjectId = sourceProjectileObjects.entrySet().stream()
                        .filter(entry -> entry.getValue() == runtimeProjectile.objectId())
                        .mapToLong(Map.Entry::getKey).findFirst().orElse(0L);
                if (sourceProjectileObjectId == 0) {
                    System.out.println("[LiTo] rejected ranged attack source projectile "
                            + "has no provenance player=" + playerName()
                            + " runtime-object=" + runtimeProjectile.objectId());
                    return;
                }
                projectile = projectile.withObjectId(sourceProjectileObjectId);
                activeWeapon = activeWeapon.withProjectile(projectile);
            }
            if (!projectile.present()) {
                notifyMissingBattleProjectile();
                System.out.println("[LiTo] rejected ranged attack missing qualified projectile player="
                        + playerName() + " weapon-item=" + activeWeapon.itemId()
                        + " weapon-type=" + activeWeapon.weaponType());
                return;
            }
        }
        if (targetSession != null || targetMonster != null || targetTimeBoss != null || targetCompanion != null
                || target == 2 && botPresent) {
            lastCombatTargetObjectId = target;
        }
        // Retained L1SkillUse/L1Attack order: an otherwise admitted physical
        // attack reveals the attacker, then proceeds through hit/reflection
        // resolution. Invisibility is not an attack prohibition.
        revealInvisibility("physical-attack-" + envelope.name().toLowerCase());
        long physicalAttackNowNanos = System.nanoTime();
        boolean soulOfFlameActive = timedStatus.soulOfFlameActive(
                physicalAttackNowNanos);
        BattleWeaponBuffStatus.Modifier weaponBuff =
                weaponBuffStatus.modifier(physicalAttackNowNanos);
        NativeWeaponBuffModifiers nativeWeaponBuffs =
                nativeWeaponBuffModifiers(ranged, physicalAttackNowNanos);
        BattleItemWeaponEnchantStatus.Modifier itemWeaponEnchant =
                itemWeaponEnchantStatus.modifier(
                        physicalAttackNowNanos, runtimeWeaponObjectId);
        BattleAbilityStatus.Berserk berserk =
                abilityStatus.berserk(physicalAttackNowNanos);
        BattleAbilityStatus.BounceAttack bounceAttack =
                abilityStatus.bounceAttack(physicalAttackNowNanos);
        BattleAbilityStatus.IllusionOgre illusionOgre =
                abilityStatus.illusionOgre(physicalAttackNowNanos);
        BattleAbilityStatus.IllusionAvatar illusionAvatar =
                abilityStatus.illusionAvatar(physicalAttackNowNanos);
        int weaponBuffHit = weaponBuff.hit(ranged);
        int weaponBuffDamage = weaponBuff.damage(ranged);
        int itemWeaponEnchantDamage = itemWeaponEnchant.damage(ranged);
        int berserkHit = ranged ? 0 : berserk.meleeHit();
        int berserkDamage = ranged ? 0 : berserk.meleeDamage();
        int bounceAttackHit = ranged ? 0 : bounceAttack.meleeHit();
        int illusionOgreHit = ranged ? 0 : illusionOgre.meleeHit();
        int illusionOgreDamage = ranged ? 0 : illusionOgre.meleeDamage();
        int illusionAvatarDamage = ranged
                ? illusionAvatar.rangedDamage() : illusionAvatar.meleeDamage();
        BattleAbilityStatus.RoyalAura royalAura =
                abilityStatus.royalAura(physicalAttackNowNanos);
        BattleAbilityStatus.BraveAura braveAura =
                abilityStatus.braveAura(physicalAttackNowNanos);
        int royalAuraHit = ranged ? royalAura.rangedHit() : royalAura.meleeHit();
        int braveAuraDamage = ranged ? 0 : braveAura.meleeDamage();
        ClassicWorldWaterDragonCatalog.Blessing waterDragonBlessing =
                waterDragonBlessing(physicalAttackNowNanos);
        int waterDragonBowHit = ranged && waterDragonBlessing != null
                ? waterDragonBlessing.bowHit() : 0;
        int waterDragonBowDamage = ranged && waterDragonBlessing != null
                ? waterDragonBlessing.bowDamage() : 0;
        NativeMagicDollPowers dollPowers = activeMagicDollPowers();
        int dollHit = dollPowers.value(ranged
                ? "PASSIVE_BOW_HIT" : "PASSIVE_HIT");
        int dollDamage = dollPowers.value(ranged
                ? "PASSIVE_BOW_DMG" : "PASSIVE_DMG");
        int equipmentHitBonus = Math.addExact(
                Math.addExact(equipmentPhysical.totalHit(
                                ranged, sourceWeaponBonusesActive),
                        weaponBuffHit), Math.addExact(
                        Math.addExact(Math.addExact(berserkHit, bounceAttackHit),
                                illusionOgreHit),
                        Math.addExact(royalAuraHit, waterDragonBowHit)));
        equipmentHitBonus = Math.addExact(
                Math.addExact(equipmentHitBonus, nativeWeaponBuffs.hit()), dollHit);
        int equipmentDamageBonus = Math.addExact(
                Math.addExact(Math.addExact(equipmentPhysical.totalDamageBonus(ranged,
                        sourceWeaponBonusesActive), weaponBuffDamage),
                        itemWeaponEnchantDamage),
                Math.addExact(Math.addExact(
                                Math.addExact(berserkDamage, braveAuraDamage),
                                illusionOgreDamage),
                        Math.addExact(waterDragonBowDamage,
                                nativeWeaponBuffs.damage())));
        equipmentDamageBonus = Math.addExact(
                Math.addExact(equipmentDamageBonus, illusionAvatarDamage), dollDamage);
        BattleSpellCatalog.WeaknessSpell weaknessSpell =
                BattleSpellCatalog.weaknessSpell(BattleSpellCatalog.WEAKNESS);
        BattleSpellCatalog.WeaknessSpell diseaseSpell =
                BattleSpellCatalog.weaknessSpell(BattleSpellCatalog.DISEASE);
        boolean weaknessActive = !ranged
                && timedStatus.weaknessActive(physicalAttackNowNanos);
        boolean diseaseActive = !ranged
                && timedStatus.diseaseActive(physicalAttackNowNanos);
        int weaknessHitModifier = weaknessActive
                ? weaknessSpell.meleeHitModifier() : 0;
        int weaknessDamageModifier = weaknessActive
                ? weaknessSpell.meleeDamageModifier() : 0;
        int diseaseHitModifier = diseaseActive
                ? diseaseSpell.meleeHitModifier() : 0;
        int diseaseDamageModifier = diseaseActive
                ? diseaseSpell.meleeDamageModifier() : 0;
        int armBreakerDamageModifier = ranged ? 0
                : armBreakerStatus.meleeDamageModifier(
                        physicalAttackNowNanos);
        CharacterSummary attackerCharacter = selectedCharacterSummary();
        int attackerCharacterType = attackerCharacter == null ? 0 : attackerCharacter.type();
        boolean chainswordAttack = activeWeapon.present()
                && activeWeapon.weaponType() == BattleChainswordWeakness.WEAPON_TYPE
                && attackerCharacterType == BattleChainswordWeakness.DRAGON_KNIGHT_TYPE;
        int attackerLevel = attackerCharacter == null
                ? 1 : Math.max(1, attackerCharacter.level());
        int strength = Math.max(1, battleStrength());
        int dexterity = Math.max(1, battleDexterity());
        int statHitBonus = requiredPhysicalGrowthStats().hit(
                ranged, ranged ? dexterity : strength);
        int statDamageBonus = requiredPhysicalGrowthStats().damage(
                ranged, ranged ? dexterity : strength);
        int targetArmorClass = targetSession != null
                ? targetSession.battleArmorClass()
                : targetNpcPhysical != null ? targetNpcPhysical.armorClass() : 10;
        int physicalD20 = 0;
        int physicalD100 = 0;
        int physicalHitChance = 100;
        boolean physicalHit = true;
        int targetDodgeModifier = targetSession == null
                ? 0 : targetSession.effectivePhysicalDodge(physicalAttackNowNanos);
        int targetDodgeDown = targetSession == null
                ? 0 : targetSession.effectivePhysicalDodgeDown(
                        physicalAttackNowNanos);
        boolean rangedEvasionChecked = false;
        int targetEvasionRate = 0;
        int rangedEvasionRoll = 0;
        if (config.battlePhysicalHitEnabled() && !kiringkuAttack) {
            physicalD20 = config.uncannyDodgeHitFixtureD20() > 0
                    ? config.uncannyDodgeHitFixtureD20()
                    : ThreadLocalRandom.current().nextInt(1, 21);
            int negativeAcRoll = targetArmorClass < 0
                    ? ThreadLocalRandom.current().nextInt(1,
                        BattlePhysicalAttack.negativeAcRollMaximum(targetArmorClass) + 1)
                    : 0;
            physicalHitChance = BattlePhysicalAttack.hitChanceWithStatBonus(
                    attackerCharacterType, attackerLevel, statHitBonus,
                    targetArmorClass,
                    Math.addExact(equipmentHitBonus,
                            Math.addExact(weaknessHitModifier, diseaseHitModifier)),
                    cookingHitBonus,
                    targetDodgeModifier, targetDodgeDown,
                    physicalD20, negativeAcRoll);
            physicalD100 = config.uncannyDodgeHitFixtureD100() > 0
                    ? config.uncannyDodgeHitFixtureD100()
                    : ThreadLocalRandom.current().nextInt(1, 101);
            physicalHit = BattlePhysicalAttack.hits(physicalHitChance, physicalD100);
            // Exact L1AttackPc branch: only a bow hit strictly above the first
            // d100 threshold proceeds to the independent ER 1..100 roll.
            if (physicalHit && physicalHitChance > physicalD100
                    && targetSession != null && activeWeapon.bow()) {
                rangedEvasionChecked = true;
                targetEvasionRate = targetSession.effectiveRangedEvasionRate(
                        System.nanoTime());
                rangedEvasionRoll = config.rangedEvasionFixtureD100() > 0
                        ? config.rangedEvasionFixtureD100()
                        : ThreadLocalRandom.current().nextInt(1, 101);
                physicalHit = BattleRangedEvasion.hitsAfterEvasion(
                        targetEvasionRate, rangedEvasionRoll);
            }
        }
        BattleCounterBarrier.Decision counterBarrierDecision =
                BattleCounterBarrier.Decision.inactive();
        if (physicalHit && !ranged && targetSession != null) {
            int counterBarrierRoll = counterBarrierRoll();
            counterBarrierDecision = targetSession.counterBarrierDecision(
                    attackerLevel, effectiveBaseMagicResistance(),
                    false, counterBarrierRoll, System.nanoTime());
            if (counterBarrierDecision.triggered()) {
                commitPlayerCounterBarrier(
                        targetSession, counterBarrierDecision, members);
                return;
            }
        }
        boolean targetLarge = targetNpcPhysical != null && targetNpcPhysical.large();
        int weaponDieMaximum = BattlePhysicalDamage.weaponDieMaximum(
                activeWeapon, targetLarge);
        int soulOfFlameRangedWeaponBase = BattleSoulOfFlame.rangedWeaponBase(
                soulOfFlameActive, activeWeapon, targetLarge);
        int weaponRoll = 0;
        int projectileRoll = 0;
        BattleWeaponCritical.RollOutcome maximumDamage =
                BattleWeaponCritical.RollOutcome.none();
        if (activeWeapon.present()) {
            int maximum = ranged
                    ? projectile.damageMaximum(targetLarge) : weaponDieMaximum;
            int maximumChance = activeWeapon.combatTraits().maximumDamageChance();
            int maximumChanceRoll = maximumChance == 0 ? 0
                    : ThreadLocalRandom.current().nextInt(1, 101);
            boolean maximumTriggered = maximumChance > 0
                    && maximumChanceRoll <= maximumChance;
            int ordinaryRoll;
            if (maximumTriggered || (!ranged && activeWeapon.weaponType() == 11)) {
                ordinaryRoll = 0;
            } else {
                int ordinaryMaximum = !ranged && maximumChance > 0 && maximum > 1
                        ? maximum - 1 : maximum;
                int shadowFangFixtureRoll =
                        config.shadowFangDamageFixtureWeaponRoll();
                ordinaryRoll = shadowFangFixtureRoll > 0
                        ? Math.min(shadowFangFixtureRoll, ordinaryMaximum)
                        : ThreadLocalRandom.current().nextInt(
                                1, ordinaryMaximum + 1);
            }
            maximumDamage = BattleWeaponCritical.roll(
                    activeWeapon, maximum, ordinaryRoll, maximumChanceRoll);
            if (ranged) {
                projectileRoll = maximumDamage.damage();
            } else {
                weaponRoll = BattleSoulOfFlame.meleeWeaponRoll(
                        soulOfFlameActive, maximumDamage.damage(),
                        weaponDieMaximum);
            }
        }
        int unarmedRoll = activeWeapon.present() ? 0
                : BattlePhysicalDamage.unarmedDamage(
                        ThreadLocalRandom.current().nextInt(4, 9));
        int appliedStatDamageBonus = kiringkuAttack
                ? BattleKiringkuDamage.classAttackLevel(
                        attackerCharacterType, attackerLevel)
                : statDamageBonus;
        int sourceBasePhysicalDamage = BattlePhysicalDamage.sourceDamage(
                activeWeapon, ranged, targetLarge, weaponRoll, projectileRoll, unarmedRoll,
                appliedStatDamageBonus,
                Math.addExact(equipmentDamageBonus, dragonEyeMeleeDamage),
                cookingDamageBonus);
        sourceBasePhysicalDamage = Math.addExact(
                sourceBasePhysicalDamage, soulOfFlameRangedWeaponBase);
        BattlePhysicalOffense.NpcOutcome offense = BattlePhysicalOffense.NpcOutcome.none();
        BattlePhysicalOffense.PlayerOutcome playerOffense =
                BattlePhysicalOffense.PlayerOutcome.none();
        if (physicalHit && targetNpcPhysical != null) {
            int materialMaximum = BattlePhysicalOffense.materialMaximum(
                    activeWeapon, targetNpcPhysical);
            int materialRoll = materialMaximum == 0 ? 0
                    : ThreadLocalRandom.current().nextInt(1, materialMaximum + 1);
            int blessingMaximum = BattlePhysicalOffense.blessingMaximum(
                    activeWeapon, targetNpcPhysical);
            int blessingRoll = blessingMaximum == 0 ? 0
                    : ThreadLocalRandom.current().nextInt(1, blessingMaximum + 1);
            offense = BattlePhysicalOffense.againstNpc(
                    activeWeapon, targetNpcPhysical, materialRoll, blessingRoll);
        } else if (physicalHit && targetSession != null) {
            int playerAttributeResistance = targetSession
                    .effectiveWeaponAttributeResistance(
                            activeWeapon.combatTraits().attributeKind());
            playerOffense = BattlePhysicalOffense.againstPlayer(
                    activeWeapon, playerAttributeResistance);
        }
        int physicalOffenseBonus = Math.addExact(
                offense.totalBonus(), playerOffense.attributeDamage());
        long weaknessNowNanos = System.nanoTime();
        BattleFoeSlayerSequence.Strike foeSlayerStrike =
                foeSlayerSequence.next(target);
        BattleChainswordWeakness.AttackOutcome chainswordWeaknessOutcome =
                BattleChainswordWeakness.AttackOutcome.none();
        if (!foeSlayerStrike.active() && chainswordAttack && physicalHit) {
            chainswordWeaknessOutcome = chainswordWeakness.attack(
                    attackerCharacterType, activeWeapon.weaponType(), target,
                    weaknessNowNanos, chainswordWeaknessRoll(weaknessNowNanos));
        } else {
            chainswordWeakness.snapshot(weaknessNowNanos);
        }
        int preCriticalPhysicalDamage = Math.max(0, Math.addExact(
                Math.addExact(
                        Math.addExact(
                                Math.addExact(sourceBasePhysicalDamage,
                                        physicalOffenseBonus),
                                Math.addExact(
                                        chainswordWeaknessOutcome.damageBonus(),
                                        foeSlayerStrike.active()
                                            ? foeSlayerStrike.damageBonus() : 0)),
                        weaknessDamageModifier),
                Math.addExact(diseaseDamageModifier,
                        armBreakerDamageModifier)));
        int doubleDamageChance = activeWeapon.present()
                ? activeWeapon.combatTraits().doubleDamageChance() : 0;
        int doubleDamageChanceRoll = doubleDamageChance == 0 ? 0
                : ThreadLocalRandom.current().nextInt(1, 101);
        boolean burningSpiritActive = timedStatus.burningSpiritActive(
                weaknessNowNanos);
        boolean burningSpiritEligible = physicalHit && !ranged && !kiringkuAttack;
        boolean elementalFireActive = timedStatus.elementalFireActive(
                weaknessNowNanos);
        boolean elementalFireEligible = physicalHit && !ranged && !kiringkuAttack;
        boolean sharedMeleeRollRequired = burningSpiritActive
                && burningSpiritEligible
                || elementalFireActive && elementalFireEligible;
        int configuredMeleeProcRoll = config.elementalFireProcFixtureRoll() > 0
                ? config.elementalFireProcFixtureRoll()
                : config.burningSpiritProcFixtureRoll();
        int sharedMeleeProcRoll = !sharedMeleeRollRequired ? 0
                : configuredMeleeProcRoll > 0 ? configuredMeleeProcRoll
                    : ThreadLocalRandom.current().nextInt(1, 101);
        int burningSpiritRoll = !burningSpiritActive || !burningSpiritEligible
                ? 0 : sharedMeleeProcRoll;
        BattlePhysicalProcBuff.Outcome burningSpirit =
                BattlePhysicalProcBuff.burningSpirit(
                        burningSpiritActive, burningSpiritEligible,
                        burningSpiritRoll);
        int elementalFireRoll = !elementalFireActive || !elementalFireEligible
                ? 0 : sharedMeleeProcRoll;
        BattlePhysicalProcBuff.Outcome elementalFire =
                BattlePhysicalProcBuff.elementalFire(
                        elementalFireActive, elementalFireEligible,
                        elementalFireRoll);
        boolean doubleBrakeActive = timedStatus.doubleBrakeActive(weaknessNowNanos);
        boolean doubleBrakeEligible = physicalHit && !ranged && activeWeapon.present()
                && (activeWeapon.weaponType() == 11 || activeWeapon.weaponType() == 12);
        int doubleBrakeRoll = !doubleBrakeActive || !doubleBrakeEligible
                ? 0 : config.doubleBrakeProcFixtureRoll() > 0
                    ? config.doubleBrakeProcFixtureRoll()
                    : ThreadLocalRandom.current().nextInt(1, 101);
        BattlePhysicalProcBuff.Outcome doubleBrake =
                BattlePhysicalProcBuff.doubleBrake(
                        doubleBrakeActive, activeWeapon.weaponType(), physicalHit,
                        doubleBrakeRoll);
        double physicalProcMultiplier = Math.max(
                Math.max(
                        Math.max(burningSpirit.multiplier(),
                                elementalFire.multiplier()),
                        doubleBrake.multiplier()),
                BattlePhysicalProcBuff.soulOfFlameMultiplier(
                        soulOfFlameActive));
        BattleWeaponCritical.DamageOutcome criticalDamage =
                BattleWeaponCritical.apply(
                        activeWeapon, preCriticalPhysicalDamage,
                        doubleDamageChanceRoll, physicalProcMultiplier);
        BattleKiringkuDamage.Outcome kiringkuDamage =
                BattleKiringkuDamage.Outcome.none();
        if (kiringkuAttack) {
            int targetMagicResistance = targetSession != null
                    ? targetSession.effectiveBaseMagicResistance()
                    : targetNpcPhysical != null ? targetNpcPhysical.magicResistance() : 0;
            kiringkuDamage = BattleKiringkuDamage.roll(
                    ThreadLocalRandom.current().nextInt(1, 6),
                    ThreadLocalRandom.current().nextInt(1, 6),
                    attackerEquipment.effectiveIntelligence(baseIntelligence()),
                    attackerEquipment.itemSpellPower(),
                    activeWeapon.enchantLevel(), targetMagicResistance,
                    originalMagicHit(), activeWeapon.combatTraits().inventoryGfx());
        }
        int scaledKiringkuDamage = (int) (kiringkuDamage.damage()
                * criticalDamage.multiplier());
        int sourcePhysicalDamage = Math.addExact(
                criticalDamage.damage(), scaledKiringkuDamage);
        boolean burningSlashConsumed = consumeBurningSlash(
                physicalHit && !ranged && !kiringkuAttack,
                weaknessNowNanos, target, targetX, targetY, members,
                "battle-physical");
        if (burningSlashConsumed) {
            sourcePhysicalDamage = Math.addExact(sourcePhysicalDamage,
                    BattleSpellCatalog.burningSlashSpell(
                            BattleSpellCatalog.BURNING_SLASH)
                            .nextMeleeDamage());
        }
        int equipmentPierce = Math.addExact(equipmentPhysical.totalPierce(),
                dollPowers.value("PASSIVE_PIERCE"));
        int npcAcMaximum = 0;
        int npcAcRoll = 0;
        int npcTotalReduction = 0;
        boolean hardRangedHalved = false;
        int playerAcMaximum = 0;
        int playerAcRoll = 0;
        int playerAcReduction = 0;
        int playerArmorReductionBase = 0;
        int playerArmorReductionRoll = 0;
        int playerArmorReduction = 0;
        int attackerIgnoreReduction = 0;
        int playerEffectiveArmorReduction = 0;
        int playerDirectionalReduction = 0;
        int physicalDamage;
        if (!physicalHit) {
            physicalDamage = 0;
        } else if (targetNpcPhysical != null) {
            npcAcMaximum = BattlePhysicalDefense.npcAcMaximum(targetNpcPhysical);
            npcAcRoll = npcAcMaximum == 0 ? 0
                    : ThreadLocalRandom.current().nextInt(npcAcMaximum);
            BattlePhysicalDefense.NpcOutcome defense =
                    BattlePhysicalDefense.againstNpc(
                            sourcePhysicalDamage, targetNpcPhysical, npcAcRoll,
                            ranged, equipmentPierce > 0);
            physicalDamage = defense.damage();
            npcTotalReduction = defense.totalReduction();
            hardRangedHalved = defense.hardRangedHalved();
        } else if (targetSession != null) {
            int targetCharacterType = targetSession.battleCharacterType();
            playerAcMaximum = BattlePhysicalDefense.playerAcMaximum(
                    targetCharacterType, targetArmorClass);
            playerAcRoll = playerAcMaximum == 0 ? 0
                    : ThreadLocalRandom.current().nextInt(playerAcMaximum);
            playerArmorReductionBase = targetSession.effectiveArmorMagicReductionBase();
            playerArmorReductionRoll = playerArmorReductionBase <= 10 ? 0
                    : ThreadLocalRandom.current().nextInt(playerArmorReductionBase - 10);
            attackerIgnoreReduction = Math.addExact(
                    equipmentPhysical.totalIgnoreReduction(),
                    dollPowers.value("PASSIVE_IGNORE_REDUCTION"));
            int sourceDirectionalReduction = targetSession.requiredEquipmentMagicStats()
                    .physical().directionalReduction(ranged);
            NativeMagicDollPowers targetDollPowers =
                    targetSession.activeMagicDollPowers();
            sourceDirectionalReduction = Math.addExact(sourceDirectionalReduction,
                    targetDollPowers.value(ranged
                            ? "PASSIVE_BOW_REDUX" : "PASSIVE_MELEE_REDUX"));
            BattlePhysicalDefense.PlayerOutcome defense =
                    BattlePhysicalDefense.againstPlayer(
                            sourcePhysicalDamage, targetCharacterType, targetArmorClass,
                            playerAcRoll, playerArmorReductionBase,
                            playerArmorReductionRoll, attackerIgnoreReduction,
                            sourceDirectionalReduction);
            playerAcReduction = defense.acReduction();
            playerArmorReduction = defense.armorReduction();
            playerEffectiveArmorReduction = defense.effectiveArmorReduction();
            playerDirectionalReduction = defense.directionalReduction();
            physicalDamage = targetSession.combatDamageAfterCooking(
                    defense.damage(), "player-physical", true,
                    activeWeapon.weaponType());
        } else {
            physicalDamage = sourcePhysicalDamage;
        }
        boolean armorBreakDamageActive = targetSession != null
                ? hub.armorBreakActive(currentRoomId, target, System.nanoTime())
                : targetTower == null
                    && hub.armorBreakActive(currentRoomId, target, System.nanoTime());
        if (targetSession == null && targetTower == null) {
            physicalDamage = BattleArmorBreak.damageAfterBreak(
                    physicalDamage, armorBreakDamageActive,
                    activeWeapon.weaponType());
        }
        if (targetTimeBoss != null
                && config.timeAttackPlayerPhysicalDamageFixture() > 0) {
            physicalDamage = config.timeAttackPlayerPhysicalDamageFixture();
        }
        boolean strikerGaleDamageActive = targetSession != null
                ? targetSession.timedStatus.strikerGaleActive(
                        physicalAttackNowNanos)
                : targetMonster != null
                    ? hub.questMonsterStrikerGaleActive(
                            currentRoomId, targetMonster.objectId(),
                            physicalAttackNowNanos)
                    : targetTimeBoss != null
                        && hub.timeAttackActorStrikerGaleActive(
                                currentRoomId, targetTimeBoss.objectId(),
                                physicalAttackNowNanos);
        physicalDamage = BattleStrikerGale.damageAfterStatus(
                physicalDamage, strikerGaleDamageActive,
                BattleStrikerGale.playerWeaponEligible(
                        activeWeapon.weaponType()));
        long earthBindDamageGateNow = System.nanoTime();
        boolean earthBindDamageImmune = targetSession != null
                ? targetSession.timedStatus.earthBindActive(earthBindDamageGateNow)
                : targetMonster != null
                    ? hub.questMonsterEarthBindActive(
                            currentRoomId, targetMonster.objectId(), earthBindDamageGateNow)
                    : targetTimeBoss != null && hub.timeAttackActorEarthBindActive(
                            currentRoomId, targetTimeBoss.objectId(), earthBindDamageGateNow);
        boolean absoluteBarrierDamageImmune = targetSession != null
                && targetSession.timedStatus.absoluteBarrierActive(earthBindDamageGateNow);
        if (targetCompanion != null) earthBindDamageImmune |=
                targetCompanion.controlled().earthBindActive(earthBindDamageGateNow)
                || targetCompanion.controlled().freezeActive(earthBindDamageGateNow);
        if (earthBindDamageImmune || absoluteBarrierDamageImmune) physicalDamage = 0;
        boolean acceptedPhysicalHit = physicalHit && physicalDamage > 0;
        NativeMagicDollEffects.AttackProc magicDollAttackProc =
                acceptedPhysicalHit
                        ? NativeMagicDollEffects.attack(dollPowers,
                            () -> ThreadLocalRandom.current().nextInt(1000))
                        : NativeMagicDollEffects.AttackProc.empty();
        if (ranged) {
            try {
                Long mappedRuntimeObject = sourceProjectileObjects.get(
                        projectile.objectId());
                RuntimeInventory.Item localProjectile = mappedRuntimeObject == null
                        ? inventory.item(projectile.objectId()) : null;
                if (localProjectile != null && !localProjectile.sourceBound()
                        && localProjectile.definition().projectile()) {
                    projectileRuntimeObjectId = localProjectile.objectId();
                    projectileBefore = localProjectile;
                    RuntimeInventory candidate = inventory.copy();
                    if (projectile.consumeOnAttack()
                            && !candidate.remove(projectileRuntimeObjectId, 1)) {
                        throw new IOException(
                                "runtime projectile candidate debit was rejected");
                    }
                    state.saveEconomyState(stateCharacter(), shopPoints,
                            candidate.catalogCounts(), candidate.catalogItemStates());
                    inventory = candidate;
                    projectileAfter = inventory.item(projectileRuntimeObjectId);
                    long remaining = projectileAfter == null
                            ? 0 : projectileAfter.quantity();
                    projectileReservation = new GameStateStore.SourceProjectileReservation(
                            true, new GameStateStore.SourceProjectileBalance(
                                    projectile.objectId(), projectile.itemId(),
                                    projectile.count(), remaining));
                } else if (mappedRuntimeObject == null) {
                    // Memory fixtures and older state files may still have a
                    // qualified projectile without a materialized source row.
                    projectileReservation = state.reserveSourceProjectile(
                            stateCharacter(), projectile);
                } else {
                    projectileRuntimeObjectId = mappedRuntimeObject;
                    projectileBefore = inventory.item(projectileRuntimeObjectId);
                    RuntimeInventory candidate = inventory.copy();
                    if (projectile.consumeOnAttack() && projectileBefore != null
                            && candidate.consumeSourceProjectile(
                                    projectileRuntimeObjectId) == null) {
                        throw new IOException(
                                "source projectile candidate debit was rejected");
                    }
                    projectileReservation = state.reserveSourceProjectile(
                            stateCharacter(), projectile, projectileRuntimeObjectId,
                            candidate.catalogCounts(), candidate.catalogItemStates());
                    if (projectileReservation.accepted()
                            && projectile.consumeOnAttack()) {
                        inventory = candidate;
                        projectileAfter = inventory.item(projectileRuntimeObjectId);
                    }
                }
            } catch (IOException persistenceFailure) {
                System.out.println("[LiTo] rejected ranged attack projectile ledger failure player="
                        + playerName() + " projectile-object=" + projectile.objectId()
                        + " reason=" + persistenceFailure.getMessage());
                return;
            }
            if (!projectileReservation.accepted()) {
                System.out.println("[LiTo] rejected ranged attack projectile exhausted player="
                        + playerName() + " projectile-object=" + projectile.objectId()
                        + " item=" + projectile.itemId());
                return;
            }
        }
        if (projectileBefore != null && projectile.consumeOnAttack()) {
            if (projectileAfter == null) {
                sendEncrypted(Protocol.removeInventory(projectileRuntimeObjectId),
                        "S_REMOVE_INVENTORY source-projectile object="
                                + projectileRuntimeObjectId + " remaining=0");
            } else {
                sendEncrypted(Protocol.changeInventoryCount(
                                projectileRuntimeObjectId, projectileAfter.quantity()),
                        "S_CHANGE_COUNT source-projectile object="
                                + projectileRuntimeObjectId + " remaining="
                                + projectileAfter.quantity());
            }
        }
        markBattleCombat();
        int physicalHeading = heading(positionX, positionY, targetX, targetY);
        int wireDamageMarker = Math.min(0xFF, physicalDamage);
        long projectileSequence = ranged
                ? ATTACK_SPELL_SEQUENCE.incrementAndGet() : 0;
        byte[] attack = ranged
                ? Protocol.rangedPhysicalAttack(
                        attackAnimation.actionId(), playerObjectId(),
                        acceptedPhysicalHit ? target : 0,
                        wireDamageMarker, physicalHeading,
                        projectileSequence, projectile.effectGfx(),
                        positionX, positionY, targetX, targetY)
                : new Protocol.Writer().c(Protocol.S_ATTACK)
                        .c(attackAnimation.actionId()).d(playerObjectId()).d(target)
                        .c(physicalDamage).c(0).d(0).bytes();
        if (kiringkuAttack) {
            byte[] effect = Protocol.effectObject(
                    playerObjectId(), kiringkuDamage.effectGfx());
            for (ClientSession member : members) {
                member.sendEncrypted(effect,
                        "S_EFFECT kiringku attacker=" + playerObjectId()
                                + " inventory-gfx="
                                + activeWeapon.combatTraits().inventoryGfx()
                                + " effect-gfx=" + kiringkuDamage.effectGfx());
            }
        }
        for (ClientSession member : members) {
            member.sendEncrypted(attack,
                    "S_ATTACK attacker=" + playerObjectId() + " target=" + target + " ranged=" + ranged
                            + " envelope=" + envelope
                            + " x=" + x + " y=" + y
                            + " action=" + attackAnimation.actionId()
                            + " equipment-hit=" + equipmentHitBonus
                            + " equipment-damage=" + equipmentDamageBonus
                            + " weapon-buff-skill=" + weaponBuff.skillId()
                            + " weapon-buff-hit=" + weaponBuffHit
                            + " weapon-buff-damage=" + weaponBuffDamage
                            + " item-weapon-enchant-skill="
                            + itemWeaponEnchant.skillId()
                            + " item-weapon-enchant-object="
                            + itemWeaponEnchant.itemObjectId()
                            + " item-weapon-enchant-damage="
                            + itemWeaponEnchantDamage
                            + " berserkers-hit=" + berserkHit
                            + " berserkers-damage=" + berserkDamage
                            + " brave-aura-damage=" + braveAuraDamage
                            + " bounce-attack-hit=" + bounceAttackHit
                            + " illusion-ogre-hit=" + illusionOgreHit
                            + " illusion-ogre-damage=" + illusionOgreDamage
                            + " dragon-eye-melee-damage=" + dragonEyeMeleeDamage
                            + " source-weapon-active=" + sourceWeaponBonusesActive
                            + " weapon-item=" + activeWeapon.itemId()
                            + " weapon-type=" + activeWeapon.weaponType()
                            + " weapon-roll=" + weaponRoll
                            + " soul-of-flame-active=" + soulOfFlameActive
                            + " soul-of-flame-ranged-weapon-base="
                            + soulOfFlameRangedWeaponBase
                            + " soul-of-flame-multiplier="
                            + BattlePhysicalProcBuff.soulOfFlameMultiplier(
                                    soulOfFlameActive)
                            + " projectile-object=" + projectile.objectId()
                            + " projectile-item=" + projectile.itemId()
                            + " projectile-roll=" + projectileRoll
                            + " projectile-remaining=" + (projectileReservation == null
                                    ? 0 : projectileReservation.balance().remainingCount())
                            + " projectile-sequence=" + projectileSequence
                            + " unarmed-roll=" + unarmedRoll
                            + " maximum-damage-chance=" + maximumDamage.chance()
                            + " maximum-damage-roll=" + maximumDamage.chanceRoll()
                            + " maximum-damage-triggered=" + maximumDamage.triggered()
                            + " maximum-damage-effect=" + maximumDamage.effectEnabled()
                            + " stat-hit=" + statHitBonus
                            + " stat-damage=" + statDamageBonus
                            + " applied-stat-or-class-damage=" + appliedStatDamageBonus
                            + " cooking-hit=" + cookingHitBonus
                            + " cooking-damage=" + cookingDamageBonus
                            + " weakness-active=" + weaknessActive
                            + " weakness-hit=" + weaknessHitModifier
                            + " weakness-damage=" + weaknessDamageModifier
                            + " disease-active=" + diseaseActive
                            + " disease-hit=" + diseaseHitModifier
                            + " disease-damage=" + diseaseDamageModifier
                            + " source-base-damage=" + sourceBasePhysicalDamage
                            + " weapon-material=" + activeWeapon.attackMaterial()
                            + " weapon-blessing=" + activeWeapon.attackBlessing()
                            + " material-maximum=" + offense.materialMaximum()
                            + " material-roll=" + offense.materialRoll()
                            + " blessing-maximum=" + offense.blessingMaximum()
                            + " blessing-roll=" + offense.blessingRoll()
                            + " attribute-kind=" + activeWeapon.combatTraits().attributeKind()
                            + " attribute-level=" + activeWeapon.combatTraits().attributeLevel()
                            + " attribute-base-damage="
                            + activeWeapon.combatTraits().attributeDamage()
                            + " attribute-resistance=" + offense.attributeResistance()
                            + " attribute-damage=" + offense.attributeDamage()
                            + " player-attribute-resistance="
                            + playerOffense.attributeResistance()
                            + " player-attribute-damage=" + playerOffense.attributeDamage()
                            + " pre-critical-damage=" + preCriticalPhysicalDamage
                            + " special-fixed-bonus=" + criticalDamage.fixedBonus()
                            + " double-damage-chance=" + criticalDamage.chance()
                            + " double-damage-roll=" + criticalDamage.chanceRoll()
                            + " double-damage-multiplier=" + criticalDamage.multiplier()
                            + " double-damage-triggered=" + criticalDamage.triggered()
                            + " double-damage-effect=" + criticalDamage.effectEnabled()
                            + " burning-spirit-active=" + burningSpirit.active()
                            + " burning-spirit-eligible=" + burningSpirit.eligible()
                            + " burning-spirit-chance=" + burningSpirit.chance()
                            + " burning-spirit-roll=" + burningSpirit.roll()
                            + " burning-spirit-triggered=" + burningSpirit.triggered()
                            + " burning-spirit-multiplier=" + burningSpirit.multiplier()
                            + " elemental-fire-active=" + elementalFire.active()
                            + " elemental-fire-eligible=" + elementalFire.eligible()
                            + " elemental-fire-chance=" + elementalFire.chance()
                            + " elemental-fire-roll=" + elementalFire.roll()
                            + " elemental-fire-triggered=" + elementalFire.triggered()
                            + " elemental-fire-multiplier=" + elementalFire.multiplier()
                            + " double-brake-active=" + doubleBrake.active()
                            + " double-brake-eligible=" + doubleBrake.eligible()
                            + " double-brake-chance=" + doubleBrake.chance()
                            + " double-brake-roll=" + doubleBrake.roll()
                            + " double-brake-triggered=" + doubleBrake.triggered()
                            + " double-brake-multiplier=" + doubleBrake.multiplier()
                            + " chainsword=" + chainswordAttack
                            + " chainsword-weakness-roll="
                            + chainswordWeaknessOutcome.chanceRoll()
                            + " chainsword-weakness-before="
                            + chainswordWeaknessOutcome.beforeLevel()
                            + " chainsword-weakness-after="
                            + chainswordWeaknessOutcome.afterLevel()
                            + " chainsword-weakness-triggered="
                            + chainswordWeaknessOutcome.triggered()
                            + " chainsword-weakness-target-reset="
                            + chainswordWeaknessOutcome.targetReset()
                            + " chainsword-weakness-expired="
                            + chainswordWeaknessOutcome.expired()
                            + " chainsword-weakness-bonus="
                            + chainswordWeaknessOutcome.damageBonus()
                            + " chainsword-weakness-target="
                            + chainswordWeaknessOutcome.targetObjectId()
                            + " chainsword-weakness-remaining-nanos="
                            + chainswordWeaknessOutcome.remainingNanos()
                            + " chainsword-weakness-ui=unavailable-in-selected-LiTo-bin"
                            + " foe-slayer-strike=" + foeSlayerStrike.active()
                            + " foe-slayer-strike-index="
                            + foeSlayerStrike.strikeIndex()
                            + " foe-slayer-strike-total="
                            + foeSlayerStrike.totalStrikes()
                            + " foe-slayer-exposure-level="
                            + foeSlayerStrike.exposureLevel()
                            + " foe-slayer-damage-bonus="
                            + (foeSlayerStrike.active()
                                ? foeSlayerStrike.damageBonus() : 0)
                            + " foe-slayer-final-strike="
                            + foeSlayerStrike.finalStrike()
                            + " kiringku=" + kiringkuAttack
                            + " kiringku-inventory-gfx="
                            + activeWeapon.combatTraits().inventoryGfx()
                            + " kiringku-dice-total=" + kiringkuDamage.diceTotal()
                            + " kiringku-int-term=" + kiringkuDamage.intelligenceTerm()
                            + " kiringku-int-coefficient="
                            + kiringkuDamage.intelligenceCoefficient()
                            + " kiringku-scaled-dice=" + kiringkuDamage.scaledDiceDamage()
                            + " kiringku-pre-mr=" + kiringkuDamage.preResistanceDamage()
                            + " kiringku-target-mr="
                            + kiringkuDamage.targetMagicResistance()
                            + " kiringku-original-magic-hit="
                            + kiringkuDamage.originalMagicHit()
                            + " kiringku-mr-floor=" + kiringkuDamage.resistanceFloor()
                            + " kiringku-mr-coefficient="
                            + kiringkuDamage.resistanceCoefficient()
                            + " kiringku-damage=" + kiringkuDamage.damage()
                            + " kiringku-scaled-damage=" + scaledKiringkuDamage
                            + " kiringku-effect-gfx=" + kiringkuDamage.effectGfx()
                            + " equipment-pierce=" + equipmentPierce
                            + " source-damage=" + sourcePhysicalDamage
                            + " target-npc=" + targetNpcId
                            + " target-large=" + targetLarge
                            + " npc-ac-maximum=" + npcAcMaximum
                            + " npc-ac-roll=" + npcAcRoll
                            + " npc-total-reduction=" + npcTotalReduction
                            + " npc-hard-ranged-halved=" + hardRangedHalved
                            + " player-ac-maximum=" + playerAcMaximum
                            + " player-ac-roll=" + playerAcRoll
                            + " player-ac-reduction=" + playerAcReduction
                            + " player-armor-reduction-base=" + playerArmorReductionBase
                            + " player-armor-reduction-roll=" + playerArmorReductionRoll
                            + " player-armor-reduction=" + playerArmorReduction
                            + " attacker-ignore-reduction=" + attackerIgnoreReduction
                            + " player-effective-armor-reduction="
                            + playerEffectiveArmorReduction
                            + " player-directional-reduction=" + playerDirectionalReduction
                            + " wire-damage-marker=" + wireDamageMarker
                            + " target-ac=" + targetArmorClass
                            + " target-dodge-modifier=" + targetDodgeModifier
                            + " target-dodge-down=" + targetDodgeDown
                            + " ranged-er-checked=" + rangedEvasionChecked
                            + " target-er=" + targetEvasionRate
                            + " ranged-er-roll=" + rangedEvasionRoll
                            + " attack-roll-hit=" + physicalHit
                            + " counter-barrier-active="
                            + counterBarrierDecision.active()
                            + " counter-barrier-probability="
                            + counterBarrierDecision.probability()
                            + " counter-barrier-roll="
                            + counterBarrierDecision.roll()
                            + " counter-barrier-triggered="
                            + counterBarrierDecision.triggered()
                            + " earth-bind-damage-immune=" + earthBindDamageImmune
                            + " absolute-barrier-damage-immune="
                            + absoluteBarrierDamageImmune
                            + " armor-break-active=" + armorBreakDamageActive
                            + " armor-break-weapon-eligible="
                            + BattleArmorBreak.supportsWeaponType(
                                    activeWeapon.weaponType())
                            + " accepted-hit=" + acceptedPhysicalHit
                            + " hit-chance=" + physicalHitChance
                            + " d20=" + physicalD20 + " d100=" + physicalD100
                            + " duration-ms=" + attackAnimation.durationMillis());
        }
        attemptEnchantVenomPoison(
                targetSession, targetMonster, targetTimeBoss, null,
                activeWeapon.present(), physicalHit, target);
        if (!acceptedPhysicalHit) return;
        if (targetCompanion != null) {
            if (!battleSpellCompanionStillAvailable(targetCompanion)) return;
            targetCompanion.owner().applyBattleCompanionFeedbackDamage(
                    targetCompanion.controlled(), physicalDamage, members, "player-physical");
            markBattleCombatWith(targetCompanion.owner());
            return;
        }
        if (targetTower != null) {
            applyGuardianTowerDamage(target, sourcePhysicalDamage, "physical");
            return;
        }
        if (targetMonster != null) {
            applyQuestMonsterDamage(target, physicalDamage, "physical");
            applyNativeMagicDollAttackProcs(magicDollAttackProc, target,
                    null, targetMonster, null, targetNpcPhysical);
            return;
        }
        if (targetTimeBoss != null) {
            applyTimeAttackActorDamage(target, physicalDamage, "physical");
            applyNativeMagicDollAttackProcs(magicDollAttackProc, target,
                    null, null, targetTimeBoss, targetNpcPhysical);
            return;
        }
        if (targetSession != null) {
            targetSession.applyBounceAttackWeaponDamage(
                    this, activeWeapon, sourceWeaponSnapshot,
                    sourceWeaponActive, runtimeWeaponObjectId);
            targetSession.takePlayerDamage(physicalDamage, this);
            applyNativeMagicDollAttackProcs(magicDollAttackProc, target,
                    targetSession, null, null, null);
            return;
        }
        if (target == 2 && botPresent) {
            int remainingBotHp = hub.damageBot(currentRoomId, sourcePhysicalDamage);
            broadcastHitRatio(2, remainingBotHp, GameHub.ARENA_BOT_MAX_HP,
                    remainingBotHp == 0 ? "bot-death" : "bot-damage");
            if (remainingBotHp == 0) {
                byte[] death = new Protocol.Writer().c(Protocol.S_ACTION).d(2)
                        .c(BattleActionCodes.DIE).bytes();
                for (ClientSession member : members) {
                    member.sendEncrypted(death, "S_ACTION bot death");
                }
                BattleRules.Resolution resolution = new BattleRules.Resolution(
                        true, false, Set.of(playerObjectId()), Set.of(), "arena-bot-defeated");
                for (ClientSession member : members) member.serverEndBattle(resolution);
                hub.endBattle(currentRoomId);
                return;
            }
        }
        if (!botPresent) return;
        if (config.battleAiEnabled()) return;
        // The synchronous single-player fallback is the same ArenaBot attack
        // as the scheduled AI path. Honour the configured source damage in
        // both modes; a hard-coded five here made battle.ai.damage misleading
        // whenever deterministic/self-test scheduling was selected.
        int counterDamage = combatPhysicalDamageAfterArmorAndCooking(
                Math.max(0, Math.addExact(config.battleAiDamage(),
                        hub.botArmBreakerMeleeDamageModifier(
                                currentRoomId, System.nanoTime()))),
                "arena-bot-counter");
        counterDamage = earthBindProtectedCombatDamage(
                counterDamage, "arena-bot-counter");
        byte[] counter = new Protocol.Writer().c(Protocol.S_ATTACK)
                .c(BattleActionCodes.ATTACK).d(2).d(playerObjectId())
                .c(counterDamage).c(0).d(0).bytes();
        for (ClientSession member : members) {
            member.sendEncrypted(counter, "S_ATTACK bot counter target=" + playerObjectId());
        }
        takePlayerDamage(counterDamage, null);
    }

    private void attackClassicWorld(
            Protocol.AttackRequest request, AttackEnvelope envelope) throws IOException {
        if (observer || playerHp <= 0
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) return;
        if (rejectWhileParalyzed("C_" + envelope.name() + "_ATTACK")) return;
        closePersonalShopIfOpen("classic-world-attack");
        ClassicWorldCastleWarField.WarObject castleObjective =
                hub.classicCastleWarObject(selectedClassicServerName,
                        classicWorldMapId, request.targetObjectId());
        if (castleObjective != null
                && castleObjective.kind() == ClassicWorldCastleWarField.Kind.CROWN) {
            claimClassicCastleCrown(castleObjective);
            return;
        }
        ClassicWorldDwarfCastleDoorState.Snapshot dwarfCastleDoor =
                hub.dwarfCastleDoor(
                        classicWorldMapId, request.targetObjectId());
        ClassicWorldCastleDoorCombat.Target mainlandCastleDoor =
                hub.mainlandCastleDoorCombatTarget(
                        classicWorldMapId, request.targetObjectId(),
                        positionX, positionY);
        int weight240 = currentWeight240(System.nanoTime());
        if (weight240 >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(110),
                    "S_MESSAGE_CODE classic-world-attack-overweight=110 weight240="
                            + weight240);
            return;
        }

        ClientSession playerTarget = classicWorldMembers(classicWorldMapId).stream()
                .filter(candidate -> candidate != this
                        && sameClassicWorldMap(candidate)
                        && candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        if (playerTarget != null) {
            attackClassicWorldPlayer(request, envelope, playerTarget);
            return;
        }

        boolean castleTowerTarget = castleObjective != null
                && castleObjective.kind() == ClassicWorldCastleWarField.Kind.TOWER;
        boolean castleTrebuchetTarget = castleObjective != null
                && castleObjective.kind() == ClassicWorldCastleWarField.Kind.TREBUCHET;
        boolean dwarfCastleDoorTarget = dwarfCastleDoor != null;
        boolean mainlandCastleDoorTarget = mainlandCastleDoor != null;
        ClassicWorldDspyEscorts.Snapshot targetDspy =
                hub.classicWorldDspyEscorts().find(request.targetObjectId());
        boolean dspyTarget = targetDspy != null && targetDspy.alive()
                && targetDspy.mapId() == classicWorldMapId;
        ClassicWorldNpcCatalog.StaticNpc targetScarecrow =
                ClassicWorldScarecrowCatalog.target(
                        classicWorldMapId, request.targetObjectId());
        boolean scarecrowTarget = targetScarecrow != null;
        ClassicWorldNpcCatalog.StaticNpc targetMonsterGuard =
                ClassicWorldMonsterGuardCatalog.target(
                        classicWorldMapId, request.targetObjectId());
        boolean monsterGuardTarget = targetMonsterGuard != null;
        ClassicWorldMonsterPopulation.Snapshot target = dspyTarget
                ? ClassicWorldDspyCatalog.combatProjection(targetDspy)
                : monsterGuardTarget
                ? ClassicWorldMonsterGuardCatalog.combatProjection(
                        targetMonsterGuard,
                        hub.classicWorldNpcHeading(targetMonsterGuard))
                : scarecrowTarget
                ? ClassicWorldScarecrowCatalog.combatProjection(
                        targetScarecrow,
                        hub.classicWorldNpcHeading(targetScarecrow))
                : castleTowerTarget
                ? hub.classicCastleTowerCombatSnapshot(
                        selectedClassicServerName, classicWorldMapId,
                        request.targetObjectId())
                : castleTrebuchetTarget
                    ? hub.classicCastleTrebuchetCombatSnapshot(
                            selectedClassicServerName, classicWorldMapId,
                            request.targetObjectId())
                : dwarfCastleDoorTarget
                    ? hub.dwarfCastleDoorCombatSnapshot(
                            classicWorldMapId, request.targetObjectId(),
                            positionX, positionY)
                : mainlandCastleDoorTarget
                    ? mainlandCastleDoor.combat()
                : hub.classicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        request.targetObjectId());
        if (target == null && !dspyTarget && !monsterGuardTarget
                && !scarecrowTarget && !castleTowerTarget
                && !castleTrebuchetTarget && !dwarfCastleDoorTarget
                && !mainlandCastleDoorTarget) {
            ClassicWorldMonsterPopulation.Snapshot hiddenTarget =
                    hub.classicWorldMonsterIncludingHidden(
                            classicWorldMapId, classicWorldInstanceId,
                            request.targetObjectId());
            if (hiddenTarget != null
                    && (hiddenTarget.hiddenStatus()
                        == ClassicWorldMonsterPopulation.HIDDEN_STATUS_SINK
                    || hiddenTarget.hiddenStatus()
                        == ClassicWorldMonsterPopulation.HIDDEN_STATUS_FLY)) {
                System.out.println("[LiTo] rejected classic-world attack player="
                        + playerName() + " target=" + request.targetObjectId()
                        + " reason=hidden-status-"
                        + hiddenTarget.hiddenStatus());
                return;
            }
        }
        if (target == null || !target.present() || !target.alive()
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, target.x(), target.y())) {
            System.out.println("[LiTo] rejected classic-world attack player="
                    + playerName() + " target=" + request.targetObjectId()
                    + " reason=missing/dead/out-of-screen");
            return;
        }

        SourceEquipmentPhysicalStats equipment =
                requiredEquipmentMagicStats().physical();
        boolean sourceWeaponActive = !inventory.hasEquippedWeapon()
                && !sourceWeaponSuppressed;
        RuntimeInventory.Item runtimeWeapon = sourceWeaponActive
                ? null : inventory.equippedWeaponItem();
        long runtimeWeaponObjectId = runtimeWeapon == null
                ? 0 : runtimeWeapon.objectId();
        SourceWeaponPhysicalStats weapon = activePhysicalWeapon();
        boolean sourceWeaponBonusesActive = sourceWeaponActive
                || runtimeWeapon != null && runtimeWeapon.sourceBound()
                    && weapon.present();
        boolean ranged = envelope == AttackEnvelope.FAR
                || (envelope == AttackEnvelope.ALTERNATE && weapon.ranged());
        int maximumRange = BattlePhysicalAttack.maximumRange(weapon);
        int range = Math.max(Math.abs(positionX - target.x()),
                Math.abs(positionY - target.y()));
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        boolean targetAttackPosition = monsterGuardTarget
                ? ClassicWorldMonsterGuardCatalog.attackPosition(
                        map, positionX, positionY,
                        target.x(), target.y(), maximumRange)
                : map.attackPosition(
                        positionX, positionY,
                        target.x(), target.y(), maximumRange);
        if ((weapon.present() && weapon.ranged() != ranged)
                || range > maximumRange || !targetAttackPosition) {
            System.out.println("[LiTo] rejected classic-world attack player="
                    + playerName() + " target=" + target.objectId()
                    + " envelope=" + envelope + " weapon=" + weapon.weaponType()
                    + " range=" + range + " max=" + maximumRange
                    + " reason=weapon-envelope/range/los");
            return;
        }
        lastCombatTargetObjectId = target.objectId();

        ClassicWorldProjectileDebit projectileDebit = null;
        SourceProjectilePhysicalStats projectile = weapon.projectile();
        if (ranged) {
            projectileDebit = debitClassicWorldProjectile(weapon);
            if (projectileDebit == null) return;
            weapon = projectileDebit.weapon();
            projectile = projectileDebit.projectile();
        }

        naturalHpRegen.noteAttack();
        naturalMpRegen.noteAttack();
        cancelMeditation("classic-world-attack");
        revealInvisibility("classic-world-physical-attack");
        long physicalAttackNowNanos = System.nanoTime();
        boolean soulOfFlameActive = timedStatus.soulOfFlameActive(
                physicalAttackNowNanos);
        BattleWeaponBuffStatus.Modifier weaponBuff =
                weaponBuffStatus.modifier(physicalAttackNowNanos);
        NativeWeaponBuffModifiers nativeWeaponBuffs =
                nativeWeaponBuffModifiers(ranged, physicalAttackNowNanos);
        BattleItemWeaponEnchantStatus.Modifier itemWeaponEnchant =
                itemWeaponEnchantStatus.modifier(
                        physicalAttackNowNanos, runtimeWeaponObjectId);
        BattleAbilityStatus.Berserk berserk =
                abilityStatus.berserk(physicalAttackNowNanos);
        BattleAbilityStatus.BraveAura braveAura =
                abilityStatus.braveAura(physicalAttackNowNanos);
        BattleAbilityStatus.IllusionOgre illusionOgre =
                abilityStatus.illusionOgre(physicalAttackNowNanos);
        BattleAbilityStatus.IllusionAvatar illusionAvatar =
                abilityStatus.illusionAvatar(physicalAttackNowNanos);
        BattleAnimationCatalog.Animation animation = BattleAnimationCatalog.get()
                .requireTimedAction(battleGfx(),
                        BattleActionCodes.attackForWalk(battleWalkAction()));
        CharacterSummary character = selectedCharacterSummary();
        int characterType = character == null ? 0 : character.type();
        int level = effectiveClassicLevel(character);
        int attackStat = ranged ? battleDexterity() : battleStrength();
        int statHit = requiredPhysicalGrowthStats().hit(ranged, attackStat);
        int equipmentHit = equipment.totalHit(ranged, sourceWeaponBonusesActive);
        equipmentHit = Math.addExact(equipmentHit, weaponBuff.hit(ranged));
        equipmentHit = Math.addExact(equipmentHit, nativeWeaponBuffs.hit());
        equipmentHit = Math.addExact(
                equipmentHit, ranged ? 0 : berserk.meleeHit());
        equipmentHit = Math.addExact(
                equipmentHit, ranged ? 0 : illusionOgre.meleeHit());
        int d20 = 1;
        int d100 = 1;
        int negativeAcRoll = 0;
        int hitChance = 100;
        boolean hit = true;
        if (config.battlePhysicalHitEnabled()) {
            d20 = config.uncannyDodgeHitFixtureD20() > 0
                    ? config.uncannyDodgeHitFixtureD20()
                    : ThreadLocalRandom.current().nextInt(1, 21);
            if (target.template().armorClass() < 0) {
                negativeAcRoll = ThreadLocalRandom.current().nextInt(1,
                        BattlePhysicalAttack.negativeAcRollMaximum(
                                target.template().armorClass()) + 1);
            }
            hitChance = BattlePhysicalAttack.hitChanceWithStatBonus(
                    characterType, level, statHit, target.template().armorClass(),
                    equipmentHit, 0, d20, negativeAcRoll);
            d100 = config.uncannyDodgeHitFixtureD100() > 0
                    ? config.uncannyDodgeHitFixtureD100()
                    : ThreadLocalRandom.current().nextInt(1, 101);
            hit = BattlePhysicalAttack.hits(hitChance, d100);
        }

        boolean targetLarge = target.template().large();
        int weaponRoll = 0;
        int projectileRoll = 0;
        int unarmedRoll = 0;
        if (weapon.present() && ranged) {
            projectileRoll = ThreadLocalRandom.current().nextInt(
                    1, projectile.damageMaximum(targetLarge) + 1);
        } else if (weapon.present()) {
            int maximum = BattlePhysicalDamage.weaponDieMaximum(
                    weapon, targetLarge);
            int fixedWeaponRoll = config.shadowFangDamageFixtureWeaponRoll();
            int ordinaryRoll = fixedWeaponRoll > 0
                    ? Math.min(fixedWeaponRoll, maximum)
                    : ThreadLocalRandom.current().nextInt(1, maximum + 1);
            weaponRoll = BattleSoulOfFlame.meleeWeaponRoll(
                    soulOfFlameActive, ordinaryRoll, maximum);
        } else {
            unarmedRoll = BattlePhysicalDamage.unarmedDamage(
                    ThreadLocalRandom.current().nextInt(4, 9));
        }
        int statDamage = requiredPhysicalGrowthStats().damage(ranged, attackStat);
        int equipmentDamage = equipment.totalDamageBonus(
                ranged, sourceWeaponBonusesActive);
        equipmentDamage = Math.addExact(
                equipmentDamage, weaponBuff.damage(ranged));
        equipmentDamage = Math.addExact(
                equipmentDamage, nativeWeaponBuffs.damage());
        equipmentDamage = Math.addExact(
                equipmentDamage, itemWeaponEnchant.damage(ranged));
        equipmentDamage = Math.addExact(
                equipmentDamage, ranged ? 0 : berserk.meleeDamage());
        equipmentDamage = Math.addExact(
                equipmentDamage, ranged ? 0 : braveAura.meleeDamage());
        equipmentDamage = Math.addExact(
                equipmentDamage, ranged ? 0 : illusionOgre.meleeDamage());
        equipmentDamage = Math.addExact(equipmentDamage,
                ranged ? illusionAvatar.rangedDamage()
                        : illusionAvatar.meleeDamage());
        int sourceDamage = BattlePhysicalDamage.sourceDamage(
                weapon, ranged, targetLarge, weaponRoll,
                projectileRoll, unarmedRoll,
                statDamage, equipmentDamage, 0);
        int soulOfFlameRangedWeaponBase = BattleSoulOfFlame.rangedWeaponBase(
                soulOfFlameActive, weapon, targetLarge);
        sourceDamage = Math.addExact(
                sourceDamage, soulOfFlameRangedWeaponBase);
        SourceNpcPhysicalStats targetPhysical = new SourceNpcPhysicalStats(
                target.npcId(), target.template().armorClass(),
                target.template().large(), target.template().damageReduction(),
                target.template().hard(), target.template().undead(),
                target.template().weakAttribute(), target.template().magicResistance(),
                false, target.lawful(), false, target.template().boss(),
                target.template().mp(), target.template().strength(),
                target.template().dexterity());
        int materialMaximum = BattlePhysicalOffense.materialMaximum(
                weapon, targetPhysical);
        int materialRoll = materialMaximum == 0 ? 0
                : ThreadLocalRandom.current().nextInt(1, materialMaximum + 1);
        int blessingMaximum = BattlePhysicalOffense.blessingMaximum(
                weapon, targetPhysical);
        int blessingRoll = blessingMaximum == 0 ? 0
                : ThreadLocalRandom.current().nextInt(1, blessingMaximum + 1);
        BattlePhysicalOffense.NpcOutcome offense =
                BattlePhysicalOffense.againstNpc(
                        weapon, targetPhysical, materialRoll, blessingRoll);
        boolean chainswordAttack = characterType
                == BattleChainswordWeakness.DRAGON_KNIGHT_TYPE
                && weapon.weaponType() == BattleChainswordWeakness.WEAPON_TYPE;
        BattleFoeSlayerSequence.Strike foeSlayerStrike =
                foeSlayerSequence.next(target.objectId());
        BattleChainswordWeakness.AttackOutcome chainswordWeaknessOutcome =
                BattleChainswordWeakness.AttackOutcome.none();
        if (!foeSlayerStrike.active() && chainswordAttack && hit) {
            chainswordWeaknessOutcome = chainswordWeakness.attack(
                    characterType, weapon.weaponType(), target.objectId(),
                    physicalAttackNowNanos,
                    chainswordWeaknessRoll(physicalAttackNowNanos));
        } else {
            chainswordWeakness.snapshot(physicalAttackNowNanos);
        }
        int preCritical = Math.max(0, Math.addExact(
                Math.addExact(sourceDamage, offense.totalBonus()),
                Math.addExact(
                        Math.addExact(chainswordWeaknessOutcome.damageBonus(),
                                foeSlayerStrike.active()
                                    ? foeSlayerStrike.damageBonus() : 0),
                        ranged ? 0
                            : armBreakerStatus.meleeDamageModifier(
                                    physicalAttackNowNanos))));
        ClassicWorldPhysicalProc physicalProc = classicWorldPhysicalProc(
                weapon, hit, ranged, soulOfFlameActive,
                physicalAttackNowNanos);
        int doubleDamageChance = weapon.present()
                ? weapon.combatTraits().doubleDamageChance() : 0;
        BattleWeaponCritical.DamageOutcome critical = BattleWeaponCritical.apply(
                weapon, preCritical,
                doubleDamageChance == 0 ? 0
                    : ThreadLocalRandom.current().nextInt(1, 101),
                physicalProc.multiplier());
        boolean altarAttackAllowed = classicWorldCkewAttackAllowed(
                target.npcId(), System.nanoTime());
        if (!altarAttackAllowed) hit = false;
        boolean kiringkuAttack = weapon.present()
                && weapon.weaponType() == BattleKiringkuDamage.WEAPON_TYPE;
        boolean burningSlashConsumed = consumeBurningSlash(
                hit && !ranged && !kiringkuAttack,
                physicalAttackNowNanos, target.objectId(), target.x(), target.y(),
                classicWorldMembers(classicWorldMapId),
                "classic-world-monster-physical");
        int beforeDefense = burningSlashConsumed
                ? Math.addExact(critical.damage(),
                    BattleSpellCatalog.burningSlashSpell(
                            BattleSpellCatalog.BURNING_SLASH).nextMeleeDamage())
                : critical.damage();
        int acMaximum = BattlePhysicalDefense.npcAcMaximum(targetPhysical);
        int acRoll = acMaximum == 0 ? 0
                : config.shadowFangDamageFixtureWeaponRoll() > 0 ? 0
                    : ThreadLocalRandom.current().nextInt(acMaximum);
        BattlePhysicalDefense.NpcOutcome defense =
                BattlePhysicalDefense.againstNpc(
                        beforeDefense, targetPhysical, acRoll, ranged,
                        equipment.totalPierce() > 0);
        int damage = hit ? defense.damage() : 0;
        boolean armorBreakDamageActive =
                hub.classicWorldMonsterArmorBreakActive(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), physicalAttackNowNanos);
        damage = BattleArmorBreak.damageAfterBreak(
                damage, armorBreakDamageActive, weapon.weaponType());
        long strikerGaleNowNanos = System.nanoTime();
        damage = BattleStrikerGale.damageAfterStatus(
                damage,
                hub.classicWorldMonsterStrikerGaleActive(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), strikerGaleNowNanos),
                BattleStrikerGale.playerWeaponEligible(weapon.weaponType()));
        damage = BattleEarthBindRules.protectedCombatDamage(
                hub.classicWorldMonsterEarthBindActive(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), physicalAttackNowNanos),
                damage);
        NativeMagicDollEffects.AttackProc magicDollAttackProc = hit
                ? NativeMagicDollEffects.attack(activeMagicDollPowers(),
                    () -> ThreadLocalRandom.current().nextInt(1000))
                : NativeMagicDollEffects.AttackProc.empty();
        boolean guardianHarvest = ClassicWorldGuardianCatalog.isGuardian(target)
                && characterType == 2 && !weapon.present();
        if (guardianHarvest && hit && !harvestClassicWorldGuardian(
                target, ThreadLocalRandom.current().nextInt(1, 101))) {
            return;
        }
        int attackHeading = heading(positionX, positionY, target.x(), target.y());
        playerHeading = attackHeading;
        long projectileSequence = ranged
                ? ATTACK_SPELL_SEQUENCE.incrementAndGet() : 0;
        byte[] attack = ranged
                ? Protocol.rangedPhysicalAttack(
                        animation.actionId(), playerObjectId(),
                        damage > 0 ? target.objectId() : 0,
                        Math.min(0xFF, Math.max(0, damage)), attackHeading,
                        projectileSequence, projectile.effectGfx(),
                        positionX, positionY, target.x(), target.y())
                : new Protocol.Writer().c(Protocol.S_ATTACK)
                        .c(animation.actionId()).d(playerObjectId()).d(target.objectId())
                        .c(Math.min(0xFF, damage)).c(0).d(0).bytes();
        if (scarecrowTarget && hit) {
            resolveClassicWorldScarecrowHit(
                    targetScarecrow, target.template(), level);
        }
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)
                    && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, target.x(), target.y())) {
                continue;
            }
            member.sendEncrypted(attack,
                    "S_ATTACK classic-world attacker=" + playerObjectId()
                            + " target=" + target.objectId()
                            + " npc=" + target.npcId() + " damage=" + damage
                            + " ranged=" + ranged
                            + " projectile=" + projectile.itemId()
                            + " projectile-remaining="
                            + (projectileDebit == null ? 0
                                : projectileDebit.reservation().balance()
                                        .remainingCount())
                            + " hit=" + hit + " hit-chance=" + hitChance
                            + " d20=" + d20 + " d100=" + d100
                            + " source-damage=" + sourceDamage
                            + " soul-of-flame-active=" + soulOfFlameActive
                            + " soul-of-flame-ranged-weapon-base="
                            + soulOfFlameRangedWeaponBase
                            + " weapon-buff-skill=" + weaponBuff.skillId()
                            + " weapon-buff-hit=" + weaponBuff.hit(ranged)
                            + " weapon-buff-damage=" + weaponBuff.damage(ranged)
                            + " item-weapon-enchant-active="
                            + itemWeaponEnchant.active()
                            + " item-weapon-enchant-damage="
                            + itemWeaponEnchant.damage(ranged)
                            + " berserkers-hit="
                            + (ranged ? 0 : berserk.meleeHit())
                            + " berserkers-damage="
                            + (ranged ? 0 : berserk.meleeDamage())
                            + " brave-aura-damage="
                            + (ranged ? 0 : braveAura.meleeDamage())
                            + " burning-spirit-active="
                            + physicalProc.burningSpirit().active()
                            + " burning-spirit-eligible="
                            + physicalProc.burningSpirit().eligible()
                            + " burning-spirit-chance="
                            + physicalProc.burningSpirit().chance()
                            + " burning-spirit-roll="
                            + physicalProc.burningSpirit().roll()
                            + " burning-spirit-triggered="
                            + physicalProc.burningSpirit().triggered()
                            + " burning-spirit-multiplier="
                            + physicalProc.burningSpirit().multiplier()
                            + " elemental-fire-active="
                            + physicalProc.elementalFire().active()
                            + " elemental-fire-triggered="
                            + physicalProc.elementalFire().triggered()
                            + " double-brake-active="
                            + physicalProc.doubleBrake().active()
                            + " double-brake-triggered="
                            + physicalProc.doubleBrake().triggered()
                            + " physical-proc-multiplier="
                            + physicalProc.multiplier()
                            + " double-damage-chance=" + critical.chance()
                            + " double-damage-roll=" + critical.chanceRoll()
                            + " double-damage-triggered=" + critical.triggered()
                            + " double-damage-multiplier=" + critical.multiplier()
                            + " burning-slash-consumed=" + burningSlashConsumed
                            + " chainsword=" + chainswordAttack
                            + " chainsword-weakness-roll="
                            + chainswordWeaknessOutcome.chanceRoll()
                            + " chainsword-weakness-before="
                            + chainswordWeaknessOutcome.beforeLevel()
                            + " chainsword-weakness-after="
                            + chainswordWeaknessOutcome.afterLevel()
                            + " chainsword-weakness-triggered="
                            + chainswordWeaknessOutcome.triggered()
                            + " chainsword-weakness-bonus="
                            + chainswordWeaknessOutcome.damageBonus()
                            + " chainsword-weakness-ui=unavailable-in-selected-LiTo-bin"
                            + " foe-slayer-strike=" + foeSlayerStrike.active()
                            + " foe-slayer-strike-index="
                            + foeSlayerStrike.strikeIndex()
                            + " foe-slayer-strike-total="
                            + foeSlayerStrike.totalStrikes()
                            + " foe-slayer-exposure-level="
                            + foeSlayerStrike.exposureLevel()
                            + " foe-slayer-damage-bonus="
                            + (foeSlayerStrike.active()
                                ? foeSlayerStrike.damageBonus() : 0)
                            + " foe-slayer-final-strike="
                            + foeSlayerStrike.finalStrike()
                            + " before-defense=" + beforeDefense
                            + " npc-reduction=" + defense.totalReduction()
                            + " armor-break-active=" + armorBreakDamageActive
                            + " action=" + animation.actionId());
        }
        // Retained L1GuardianInstance.receiveDamage discards every unarmed
        // elf hit after the normal attack action has been published.
        if (guardianHarvest) return;
        // Retained L1ScarecrowInstance and L1MonsterGuardInstance both ignore
        // committed HP damage. The attack animation remains visible, but the
        // static receiver cannot gain hate, lose HP, die, drop or respawn.
        if (scarecrowTarget || monsterGuardTarget) return;
        if (!dspyTarget && !castleTowerTarget && !castleTrebuchetTarget
                && !dwarfCastleDoorTarget && !mainlandCastleDoorTarget) {
            attemptEnchantVenomPoison(
                    null, null, null, target,
                    weapon.present(), hit, target.objectId());
        }
        if (damage <= 0) return;

        if (castleTowerTarget) {
            CastleSummary defender;
            try {
                defender = effectiveClassicCastleById(
                        castleObjective.castleId());
            } catch (Exception error) {
                throw new IOException("castle defender lookup failed", error);
            }
            String attackerClan = hub.clanData(
                    sourceCharacterIdentity()).name();
            ClassicWorldCastleWarField.TowerHit towerHit =
                    hub.damageClassicCastleTower(
                            selectedClassicServerName, classicWorldMapId,
                            target.objectId(), attackerClan,
                            defender == null ? "" : defender.clanName(), damage);
            if (towerHit == null || towerHit.appliedDamage() <= 0) {
                System.out.println("[LiTo] classic castle tower damage rejected player="
                        + playerName() + " object=" + target.objectId()
                        + " castle=" + castleObjective.castleId()
                        + " clan=" + attackerClan);
                return;
            }
            publishClassicCastleTowerHit(towerHit);
            return;
        }

        if (dwarfCastleDoorTarget) {
            ClassicWorldDwarfCastleDoorState.DoorHit doorHit =
                    hub.damageDwarfCastleDoor(
                            classicWorldMapId, target.objectId(), damage);
            if (doorHit == null || doorHit.appliedDamage() <= 0) return;
            publishDwarfCastleDoorHit(doorHit);
            return;
        }

        if (mainlandCastleDoorTarget) {
            ClassicWorldCastleDoorCombat.Hit doorHit =
                    hub.damageMainlandCastleDoor(
                            mainlandCastleDoor.view().definition().family(),
                            classicWorldMapId, target.objectId(), damage);
            if (doorHit == null || doorHit.appliedDamage() <= 0) return;
            publishMainlandCastleDoorHit(doorHit);
            return;
        }

        if (castleTrebuchetTarget) {
            ClassicWorldCastleWarField.TrebuchetHit trebuchetHit =
                    hub.damageClassicCastleTrebuchet(
                            selectedClassicServerName, classicWorldMapId,
                            target.objectId(), damage);
            if (trebuchetHit == null || trebuchetHit.appliedDamage() <= 0) return;
            publishClassicCastleTrebuchetHit(trebuchetHit);
            if (trebuchetHit.diedNow()) {
                hub.scheduleClassicCastleTrebuchetCorpseRemoval(
                        selectedClassicServerName, trebuchetHit.after());
            }
            return;
        }

        if (dspyTarget) {
            ClassicWorldDspyEscorts.Damage transition =
                    hub.classicWorldDspyEscorts().damage(
                            target.objectId(), damage, System.nanoTime());
            if (transition == null || transition.appliedDamage() <= 0) return;
            byte[] ratio = Protocol.hitRatio(
                    target.objectId(), transition.after().currentHp(),
                    transition.after().maximumHp());
            for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY,
                        target.x(), target.y())) continue;
                member.sendEncrypted(ratio,
                        "S_HIT_RATIO Dspy-follower=" + target.objectId()
                                + " hp=" + transition.after().currentHp() + "/"
                                + transition.after().maximumHp()
                                + " source=player-physical");
                if (transition.diedNow()) {
                    member.sendEncrypted(Protocol.objectAction(
                                    target.objectId(), BattleActionCodes.DIE),
                            "S_ACTION Dspy-follower-death=" + target.objectId()
                                    + " attacker=" + playerObjectId()
                                    + " delete-delay-ms="
                                    + ClassicWorldDspyEscorts.CORPSE_MILLIS);
                }
            }
            if (transition.diedNow()) {
                hub.clearClassicWorldMonsterTargets(target.objectId());
            }
            System.out.println("[LiTo] Dspy follower damaged player="
                    + playerName() + " follower=" + target.objectId()
                    + " applied=" + transition.appliedDamage()
                    + " hp=" + transition.after().currentHp() + "/"
                    + transition.after().maximumHp()
                    + " died=" + transition.diedNow());
            return;
        }

        boolean sleepActiveBeforeDamage =
                hub.classicWorldMonsterSleepActive(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), System.nanoTime());
        ClassicWorldMonsterPopulation.Hit transition =
                hub.damageClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), playerObjectId(), damage);
        if (transition == null) return;
        boolean sleepActiveAfterDamage =
                hub.classicWorldMonsterSleepActive(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), System.nanoTime());
        hub.provokeClassicWorldMonster(
                classicWorldMapId, classicWorldInstanceId,
                target.objectId(), playerObjectId());
        for (BattleCompanion.Snapshot companion : classicWorldCompanionSnapshots()) {
            BattleCompanion controlled = ownedCompanion(companion.objectId());
            if (controlled != null) controlled.selectMasterTarget(target.objectId());
        }
        ClassicWorldMonsterPopulation.Snapshot after = transition.after();
        byte[] ratio = Protocol.hitRatio(
                after.objectId(), after.currentHp(), after.maximumHp());
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, after.x(), after.y())) continue;
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO classic-world-monster=" + after.objectId()
                            + " hp=" + after.currentHp() + "/" + after.maximumHp());
            if (transition.diedNow()) {
                member.sendEncrypted(Protocol.objectAction(
                                after.objectId(), BattleActionCodes.DIE),
                        "S_ACTION classic-world-monster=" + after.objectId()
                                + " action=" + BattleActionCodes.DIE);
            }
        }
        System.out.println("[LiTo] classic-world monster damaged player="
                + playerName() + " object=" + after.objectId()
                + " spawn=" + after.spawnId() + " npc=" + after.npcId()
                + " damage=" + transition.appliedDamage()
                + " hp=" + after.currentHp() + "/" + after.maximumHp()
                + " died=" + transition.diedNow()
                + " sleep-before=" + sleepActiveBeforeDamage
                + " sleep-after=" + sleepActiveAfterDamage);
        if (transition.diedNow()) {
            handleClassicWorldWaterDragonDeath(
                    after, transition.contributions());
            distributeClassicWorldMonsterRewards(
                    after, transition.contributions());
            hub.scheduleClassicWorldMonsterLifecycle(
                    classicWorldInstanceId, after);
        }
        applyNativeMagicDollClassicWorldAttackProcs(
                magicDollAttackProc, target, targetPhysical);
    }

    /**
     * Retained L1GuardianInstance harvest happens before attack.action().
     * False means storeItem failed and the source returns without publishing
     * the attack; a no-reward roll remains a successful no-op.
     */
    private boolean harvestClassicWorldGuardian(
            ClassicWorldMonsterPopulation.Snapshot guardian,
            int oneBasedRoll) throws IOException {
        if (!ClassicWorldGuardianCatalog.isGuardian(guardian)) {
            throw new IllegalArgumentException("harvest target is not L1Guardian");
        }
        ClassicWorldGuardianCatalog.Harvest harvest =
                ClassicWorldGuardianCatalog.harvest(
                        guardian.npcId(), oneBasedRoll);
        if (harvest == null) {
            System.out.println("[LiTo] L1Guardian harvest no-drop player="
                    + playerName() + " npc=" + guardian.npcId()
                    + " roll=" + oneBasedRoll);
            return true;
        }
        InventoryCatalog.Definition reward =
                InventoryCatalog.require(harvest.itemId());
        RuntimeInventory next = inventory.copy();
        boolean weightAllowed = permitsInventoryAddition(
                next, reward, harvest.quantity());
        boolean added = weightAllowed && next.add(reward, harvest.quantity());
        if (!added) {
            if (!weightAllowed) sendInventoryWeightOver("L1Guardian-harvest");
            else sendInventoryCapacityOver("L1Guardian-harvest");
            System.out.println("[LiTo] L1Guardian harvest storeItem failed player="
                    + playerName() + " npc=" + guardian.npcId()
                    + " item=" + harvest.itemId() + " count="
                    + harvest.quantity() + " roll=" + oneBasedRoll);
            return false;
        }
        state.saveEconomyState(stateCharacter(), shopPoints,
                next.catalogCounts(), next.catalogItemStates());
        RuntimeInventory previous = inventory;
        inventory = next;
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.messageCode(
                        ClassicWorldGuardianCatalog.HARVEST_MESSAGE,
                        harvest.giverNameId(), harvest.itemMessageArgument()),
                "S_MESSAGE_CODE L1Guardian-harvest=143 npc="
                        + guardian.npcId() + " item=" + harvest.itemId()
                        + " count=" + harvest.quantity());
        System.out.println("[LiTo] L1Guardian harvest player=" + playerName()
                + " npc=" + guardian.npcId() + " roll=" + oneBasedRoll
                + " item=" + harvest.itemId() + " count="
                + harvest.quantity());
        return true;
    }

    /** Exact hit-side behavior of retained L1ScarecrowInstance.onAction. */
    private void resolveClassicWorldScarecrowHit(
            ClassicWorldNpcCatalog.StaticNpc scarecrow,
            ClassicWorldMonsterCatalog.MonsterTemplate combatTemplate,
            int attackerLevel) throws IOException {
        if (scarecrow == null || combatTemplate == null
                || !ClassicWorldScarecrowCatalog.isScarecrow(scarecrow)) {
            throw new IllegalArgumentException("invalid classic scarecrow hit");
        }
        if (attackerLevel < config.classicWorldScarecrowMaxLevel()) {
            applyClassicWorldNpcReward(
                    combatTemplate, scarecrow.experience(), 0, 1, 1);
        }
        int previousHeading = hub.classicWorldNpcHeading(scarecrow);
        int nextHeading = (previousHeading + 1) & 7;
        if (!hub.changeClassicWorldNpcHeading(scarecrow, nextHeading)) {
            throw new IOException("canonical scarecrow heading update failed object="
                    + scarecrow.objectId());
        }
        byte[] changed = new Protocol.Writer().c(Protocol.S_CHANGE_DIRECTION)
                .d(scarecrow.objectId()).c(nextHeading).bytes();
        for (ClientSession member : classicWorldMembers(scarecrow.mapId())) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY,
                    scarecrow.x(), scarecrow.y())) continue;
            member.sendEncrypted(changed,
                    "S_CHANGE_DIRECTION L1Scarecrow=" + scarecrow.objectId()
                            + " npc=" + scarecrow.npcId()
                            + " heading=" + previousHeading + "->" + nextHeading);
        }
        System.out.println("[LiTo] classic-world L1Scarecrow hit player="
                + playerName() + " object=" + scarecrow.objectId()
                + " npc=" + scarecrow.npcId() + " heading="
                + previousHeading + "->" + nextHeading
                + " training-level=" + attackerLevel + "/"
                + config.classicWorldScarecrowMaxLevel()
                + " exp=" + (attackerLevel < config.classicWorldScarecrowMaxLevel()
                    ? scarecrow.experience() : 0));
    }

    private void publishClassicCastleTrebuchetHit(
            ClassicWorldCastleWarField.TrebuchetHit hit) throws IOException {
        ClassicWorldCastleWarField.WarObject after = hit.after();
        byte[] ratio = Protocol.hitRatio(
                after.objectId(), after.currentHp(), after.maximumHp());
        for (ClientSession member : classicWorldMembers(after.mapId())) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, after.x(), after.y())) continue;
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO castle-trebuchet=" + after.objectId()
                            + " hp=" + after.currentHp() + "/" + after.maximumHp());
            if (hit.diedNow()) {
                member.sendEncrypted(Protocol.objectAction(
                                after.objectId(), BattleActionCodes.DIE),
                        "S_ACTION castle-trebuchet=" + after.objectId()
                                + " action=" + BattleActionCodes.DIE);
            }
        }
        System.out.println("[LiTo] classic castle trebuchet damaged player="
                + playerName() + " object=" + after.objectId()
                + " npc=" + after.npcId() + " applied=" + hit.appliedDamage()
                + " hp=" + after.currentHp() + "/" + after.maximumHp()
                + " died=" + hit.diedNow());
    }

    private void publishMainlandCastleDoorHit(
            ClassicWorldCastleDoorCombat.Hit hit) throws IOException {
        ClassicWorldCastleDoorCombat.View after = hit.after();
        ClassicWorldCastleDoorCombat.Definition door = after.definition();
        byte[] action = hit.action() == 0 ? null
                : Protocol.objectAction(door.objectId(), hit.action());
        for (ClientSession member : classicWorldMembers(door.mapId())) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, door.x(), door.y())) continue;
            if (action != null) {
                member.sendEncrypted(action,
                        "S_ACTION " + door.family().name().toLowerCase(Locale.ROOT)
                                + "-castle-door=" + door.doorId()
                                + " action=" + hit.action()
                                + " hp=" + after.currentHp() + "/"
                                + door.maximumHp());
            }
            if (hit.diedNow()) {
                member.sendMainlandCastleDoorAttributes(
                        door, BattleDoor.PASSABLE, "door-death");
            }
        }
        System.out.println("[LiTo] mainland castle door damaged player="
                + playerName() + " family=" + door.family()
                + " door=" + door.doorId() + " object=" + door.objectId()
                + " applied=" + hit.appliedDamage()
                + " hp=" + after.currentHp() + "/" + door.maximumHp()
                + " crack-stage=" + after.crackStage()
                + " action=" + hit.action() + " died=" + hit.diedNow());
    }

