    /** Retained CKEW50_Altar: complete quest122 and award 49241 to the whole show. */
    private void completeClassicWorldCkewAltar(
            ClassicWorldMonsterPopulation.Snapshot defeated) throws IOException {
        if (defeated.mapId() != ClassicWorldCkewCatalog.MAP_ID
                || defeated.npcId() != 87000 || classicWorldInstanceId < 0) return;
        int showId = classicWorldInstanceId;
        for (ClientSession member : hub.classicWorldMembers(
                ClassicWorldCkewCatalog.MAP_ID, showId)) {
            member.serverClassicWorldCkewAltarCompleted(showId, defeated);
        }
    }

    private void serverClassicWorldCkewAltarCompleted(
            int showId, ClassicWorldMonsterPopulation.Snapshot altar)
            throws IOException {
        if (phase != Phase.WORLD
                || classicWorldMapId != ClassicWorldCkewCatalog.MAP_ID
                || classicWorldInstanceId != showId || altar == null) return;
        InventoryCatalog.Definition definition = InventoryCatalog.find(
                ClassicWorldCkewCatalog.ALTAR_PROOF);
        if (definition == null) {
            throw new IOException("CKEW altar proof definition vanished");
        }

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        boolean alreadyOwned = next.catalogCounts().containsKey(
                (long) ClassicWorldCkewCatalog.ALTAR_PROOF);
        boolean stored = alreadyOwned || (permitsInventoryAddition(
                inventory, definition, 1) && next.add(definition, 1));
        Map<Integer, Integer> quests = new LinkedHashMap<>(
                state.storyQuests(stateCharacter()).effective());
        quests.put(ClassicWorldCkewCatalog.QUEST_ID,
                ClassicWorldCkewCatalog.QUEST_COMPLETED);
        state.saveEconomyStateAndStoryQuests(
                stateCharacter(), shopPoints, next.catalogCounts(),
                next.catalogItemStates(), quests);
        inventory = next;
        if (alreadyOwned) return;

        RuntimeInventory.Item source = new RuntimeInventory.Item(
                1, definition, 1, false, 0, 0, true,
                RuntimeInventory.BLESSING_NORMAL);
        if (stored) {
            sendInventoryDelta(previous, inventory);
        } else {
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    altar.mapId(), classicWorldInstanceId,
                    source, 1, positionX, positionY, altar.npcId());
            if (ground == null) {
                throw new IOException("CKEW altar proof ground handoff failed");
            }
            broadcastClassicWorldGroundItem(ground, "CKEW-altar-proof-overflow");
        }
        sendEncrypted(Protocol.messageCode(
                        143, altar.template().nameId(), source.nativeViewName()),
                "S_MESSAGE_CODE CKEW-altar-proof=143 show=" + showId
                        + " item=" + ClassicWorldCkewCatalog.ALTAR_PROOF
                        + " stored=" + stored);
        System.out.println("[LiTo] CKEW altar completed player=" + playerName()
                + " show=" + showId + " quest-step="
                + ClassicWorldCkewCatalog.QUEST_COMPLETED
                + " proof-stored=" + stored);
    }

    /** A liberated pet keeps its former bag until the replacement monster dies. */
    private void distributeReleasedPetItems(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            List<ClassicWorldMonsterPopulation.Contribution> contributions,
            Map<Long, ClientSession> eligible,
            List<RuntimeInventory.Item> releasedItems) throws IOException {
        int autoLoot = config.classicWorldDropAutoLoot();
        for (RuntimeInventory.Item item : releasedItems) {
            ClientSession recipient = autoLoot == 0 ? null
                    : selectClassicWorldDropRecipient(
                            defeated, contributions, eligible, autoLoot);
            boolean granted = recipient != null
                    && recipient.receiveReleasedPetItem(defeated, item);
            if (granted) continue;
            int x;
            int y;
            if (recipient == null) {
                int[] location = classicWorldAdjacentDropLocation(defeated);
                x = location[0];
                y = location[1];
            } else {
                x = recipient.positionX;
                y = recipient.positionY;
            }
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    defeated.mapId(), classicWorldInstanceId,
                    item, item.quantity(), x, y, defeated.npcId());
            if (ground == null) {
                throw new IllegalStateException(
                        "released pet item ground handoff was rejected");
            }
            broadcastClassicWorldGroundItem(ground,
                    recipient == null ? "released-pet-drop" : "released-pet-overflow");
            System.out.println("[LiTo] released pet item dropped wild="
                    + defeated.objectId() + " catalog="
                    + item.definition().catalogId() + " object=" + ground.objectId()
                    + " quantity=" + ground.quantity() + " x=" + x + " y=" + y);
        }
    }

    private boolean receiveReleasedPetItem(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            RuntimeInventory.Item item) throws IOException {
        RuntimeInventory next = inventory.copy();
        if (!next.add(item, item.quantity())
                || !permitsInventoryAddition(
                        inventory, item.definition(), item.quantity())) {
            return false;
        }
        RuntimeInventory previous = inventory;
        inventory = next;
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.messageCode(
                        143, defeated.nameId(), item.nativeViewName()),
                "S_MESSAGE_CODE released-pet-autoloot=143 wild="
                        + defeated.objectId() + " catalog="
                        + item.definition().catalogId() + " quantity="
                        + item.quantity());
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        return true;
    }

    private ClientSession selectClassicWorldDropRecipient(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            List<ClassicWorldMonsterPopulation.Contribution> contributions,
            Map<Long, ClientSession> eligible, int autoLoot) {
        List<ClassicWorldMonsterPopulation.Contribution> candidates = new ArrayList<>();
        long totalHate = 0;
        for (ClassicWorldMonsterPopulation.Contribution contribution : contributions) {
            ClientSession recipient = eligible.get(contribution.playerObjectId());
            if (recipient == null || contribution.hate() <= 0) continue;
            if (autoLoot == 1 && Math.max(
                    Math.abs(recipient.positionX - defeated.x()),
                    Math.abs(recipient.positionY - defeated.y()))
                    > config.classicWorldDropLootingRange()) continue;
            candidates.add(contribution);
            totalHate = Math.addExact(totalHate, contribution.hate());
        }
        if (totalHate <= 0) return null;
        long selected = ThreadLocalRandom.current().nextLong(totalHate);
        for (ClassicWorldMonsterPopulation.Contribution contribution : candidates) {
            if (selected < contribution.hate()) {
                return eligible.get(contribution.playerObjectId());
            }
            selected -= contribution.hate();
        }
        return eligible.get(candidates.get(candidates.size() - 1).playerObjectId());
    }

    private boolean receiveClassicWorldMonsterDrop(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            ClassicWorldDropCatalog.RolledItem drop) throws IOException {
        ClassicWorldDropCatalog.ItemWire wire = drop.item();
        InventoryCatalog.Definition definition = wire.inventoryDefinition();
        RuntimeInventory.Item source = new RuntimeInventory.Item(
                1, definition, drop.quantity(), false, 0, 0, false, wire.blessing());
        RuntimeInventory next = inventory.copy();
        if (!next.add(source, drop.quantity())
                || !permitsInventoryAddition(inventory, definition, drop.quantity())) {
            System.out.println("[LiTo] classic-world autoloot overflow player=" + playerName()
                    + " npc=" + defeated.npcId() + " catalog=" + wire.itemId()
                    + " quantity=" + drop.quantity());
            return false;
        }
        RuntimeInventory previous = inventory;
        inventory = next;
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.messageCode(
                        143, defeated.nameId(),
                        classicWorldDropLogName(definition, drop.quantity())),
                "S_MESSAGE_CODE classic-world-autoloot=143 npc=" + defeated.npcId()
                        + " catalog=" + wire.itemId() + " quantity=" + drop.quantity());
        state.saveEconomyState(stateCharacter(), shopPoints,
                inventory.catalogCounts(), inventory.catalogItemStates());
        System.out.println("[LiTo] classic-world autoloot player=" + playerName()
                + " npc=" + defeated.npcId() + " catalog=" + wire.itemId()
                + " quantity=" + drop.quantity() + " chance-roll=" + drop.chanceRoll());
        return true;
    }

    private static String classicWorldDropLogName(
            InventoryCatalog.Definition definition, int quantity) {
        if (definition.stackable()) return definition.name() + " (" + quantity + ")";
        return definition.name();
    }

    private void putClassicWorldMonsterDrop(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            ClassicWorldDropCatalog.RolledItem drop,
            int x, int y, String reason) throws IOException {
        int objects = drop.item().stackable() ? 1 : drop.quantity();
        int quantity = drop.item().stackable() ? drop.quantity() : 1;
        for (int index = 0; index < objects; index++) {
            ClassicWorldGroundItems.Item item = hub.putClassicWorldGroundItem(
                    defeated.mapId(), classicWorldInstanceId,
                    drop.item(), quantity, x, y, defeated.npcId());
            if (item == null) {
                throw new IllegalStateException("validated classic WORLD drop was rejected");
            }
            broadcastClassicWorldGroundItem(item, reason);
            System.out.println("[LiTo] classic-world ground drop npc=" + defeated.npcId()
                    + " catalog=" + drop.item().itemId() + " object=" + item.objectId()
                    + " quantity=" + item.quantity() + " x=" + x + " y=" + y
                    + " chance-roll=" + drop.chanceRoll() + " reason=" + reason);
        }
    }

    private int[] classicWorldAdjacentDropLocation(
            ClassicWorldMonsterPopulation.Snapshot defeated) {
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(defeated.mapId());
        int start = ThreadLocalRandom.current().nextInt(CLASSIC_GROUND_DX.length);
        for (int offset = 0; offset < CLASSIC_GROUND_DX.length; offset++) {
            int direction = (start + offset) & 7;
            int x = defeated.x() + CLASSIC_GROUND_DX[direction];
            int y = defeated.y() + CLASSIC_GROUND_DY[direction];
            if (map.canStep(defeated.x(), defeated.y(), x, y)) {
                return new int[]{x, y};
            }
        }
        return new int[]{defeated.x(), defeated.y()};
    }

    private void applyClassicWorldNpcReward(
            ClassicWorldMonsterCatalog.MonsterTemplate npc,
            long baseExperience, int sourceLawfulShare,
            long hate, long totalHate) throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null || phase != Phase.WORLD || playerHp <= 0) return;

        int requestedLawfulDelta = -((int) (
                sourceLawfulShare * config.classicWorldLawfulRate()));
        GameStateStore.LawfulMutation lawful = state.addLawful(
                stateCharacter(), nativeLawful(character.lawful()), requestedLawfulDelta);
        playerLawful = lawful.after();
        if (lawful.changed()) {
            byte[] packet = Protocol.changeAlignment(playerObjectId(), playerLawful);
            for (ClientSession viewer : classicWorldMembers(classicWorldMapId)) {
                if (viewer != this && !BattleSpellCatalog.isInNativeScreen(
                        viewer.positionX, viewer.positionY, positionX, positionY)) continue;
                viewer.sendEncrypted(packet,
                        "S_CHANGE_ALIGNMENT classic-world player=" + playerName()
                                + " object=" + playerObjectId() + " npc=" + npc.npcId()
                                + " source-share=" + sourceLawfulShare
                                + " requested-delta=" + lawful.requestedDelta()
                                + " applied-delta=" + lawful.appliedDelta()
                                + " lawful=" + lawful.before() + "->" + lawful.after());
            }
        }

        int sourceLevel = Math.max(1,
                Math.min(ClassicExperienceCatalog.MAXIMUM_LEVEL, character.level()));
        int fixedExperienceBonus = experienceGemStatus.snapshot(
                System.nanoTime()).bonusExperience();
        NativeMagicDollPowers dollPowers = activeMagicDollPowers();
        double dollExperienceMultiplier =
                dollPowers.percentMultiplier("PASSIVE_EXP_RATE");
        double effectiveExperienceRate = config.classicWorldExperienceRate()
                * dollExperienceMultiplier;
        GameStateStore.ClassicExperienceMutation experience =
                 state.addClassicExperience(
                        stateCharacter(), character.experience(), sourceLevel, baseExperience,
                        effectiveExperienceRate,
                        fixedExperienceBonus);
        playerClassicExperience = experience.afterExperience();
        playerClassicLevel = experience.afterLevel();
        if (experience.changed()) {
            if (experience.levelChanged()) {
                sendNativeBattleStatus(System.nanoTime(), "classic-world-level-up");
            } else {
                sendEncrypted(Protocol.experience(
                                playerClassicLevel, playerClassicExperience),
                        "S_EXP classic-world player=" + playerName()
                                + " npc=" + npc.npcId()
                                + " level=" + playerClassicLevel
                                + " experience=" + experience.beforeExperience()
                                + "->" + experience.afterExperience()
                                + " base=" + baseExperience
                                + " adjusted=" + experience.adjustedExperience());
            }
        }
        System.out.println("[LiTo] classic-world NPC reward player=" + playerName()
                + " npc=" + npc.npcId() + " hate=" + hate + "/" + totalHate
                + " exp-base=" + baseExperience
                + " exp-server-rate=" + config.classicWorldExperienceRate()
                + " exp-doll-percent=" + dollPowers.value("PASSIVE_EXP_RATE")
                + " exp-rate=" + effectiveExperienceRate
                + " dragon-gem-fixed=" + fixedExperienceBonus
                + " exp-adjusted=" + experience.adjustedExperience()
                + " exp=" + experience.beforeExperience() + "->"
                + experience.afterExperience() + " level="
                + experience.beforeLevel() + "->" + experience.afterLevel()
                + " lawful-source-share=" + sourceLawfulShare
                + " lawful-rate=" + config.classicWorldLawfulRate()
                + " lawful=" + lawful.before() + "->" + lawful.after());
    }

    private synchronized BattleCounterBarrier.Decision counterBarrierDecision(
            int attackerLevel, int attackerMagicResistance,
            boolean attackerBoss, int oneBasedRoll, long nowNanos) {
        BattleSpellCatalog.CounterBarrierSpell spell =
                BattleSpellCatalog.counterBarrierSpell(
                        BattleSpellCatalog.COUNTER_BARRIER);
        boolean active = abilityStatus.counterBarrier(nowNanos)
                .remainingSeconds() != 0;
        SourceWeaponPhysicalStats weapon = activePhysicalWeapon();
        if (active && !spell.supportsWeapon(weapon)) {
            abilityStatus.removeCounterBarrier();
            active = false;
            System.out.println("[LiTo] Counter Barrier removed player=" + playerName()
                    + " reason=trigger-without-two-hand-sword");
        }
        int holderMagicHit = Math.addExact(
                requiredEquipmentMagicStats().totalMagicHit(),
                dragonEyeStatus.snapshot(nowNanos).magicHit());
        return BattleCounterBarrier.decide(
                spell, active, weapon, battleLevel(), attackerLevel,
                holderMagicHit, attackerMagicResistance, attackerBoss,
                oneBasedRoll);
    }

    private int counterBarrierRoll() {
        int fixture = config.counterBarrierFixtureD100();
        return fixture > 0 ? fixture
                : ThreadLocalRandom.current().nextInt(1, 101);
    }

    private int mortalBodyRoll() {
        int fixture = config.mortalBodyFixtureD100();
        return fixture > 0 ? fixture
                : ThreadLocalRandom.current().nextInt(1, 101);
    }

    /**
     * Retained receiveDamage feedback runs only after a positive damage commit.
     * This method is invoked on the Mortal Body holder (the damaged player).
     */
    private void tryMortalBodyPlayerReflection(
            ClientSession attacker, String source) throws IOException {
        if (attacker == null || attacker == this || attacker.playerHp <= 0) return;
        long nowNanos = System.nanoTime();
        BattleSpellCatalog.MortalBodySpell spell =
                BattleSpellCatalog.mortalBodySpell(BattleSpellCatalog.MORTAL_BODY);
        boolean active = abilityStatus.mortalBody(nowNanos).remainingSeconds() != 0;
        if (!active) return;
        SourceEquipmentPhysicalStats attackerPhysical =
                attacker.requiredEquipmentMagicStats().physical();
        SourceWeaponPhysicalStats attackerWeapon = attacker.activePhysicalWeapon();
        int armorBase = attacker.effectiveArmorMagicReductionBase();
        int armorRoll = armorBase <= 10 ? 0
                : ThreadLocalRandom.current().nextInt(armorBase - 10);
        int armorReduction = BattlePhysicalDefense.armorReduction(
                armorBase, armorRoll);
        int pvpReduction = attackerPhysical.totalPvpReduction();
        int meleeReduction = Math.max(0,
                attackerPhysical.directionalReduction(false));
        BattleMortalBody.Decision decision = BattleMortalBody.decide(
                spell, active, battleLevel(), attacker.battleLevel(),
                false, mortalBodyRoll(), true,
                attackerWeapon == null ? 0 : attackerWeapon.enchantLevel(),
                armorReduction, pvpReduction, meleeReduction);
        if (!decision.triggered()) {
            if (decision.active()) {
                System.out.println("[LiTo] Mortal Body roll defender="
                        + playerName() + " attacker=" + attacker.playerName()
                        + " probability=" + decision.probability()
                        + " roll=" + decision.roll() + " triggered=false"
                        + " source=" + source);
            }
            return;
        }

        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        byte[] reaction = Protocol.objectAction(
                attacker.playerObjectId(), BattleActionCodes.DAMAGE);
        for (ClientSession recipient : recipients) {
            if (phase == Phase.WORLD && (!sameClassicWorldMap(recipient)
                    || !BattleSpellCatalog.isInNativeScreen(
                            recipient.positionX, recipient.positionY,
                            positionX, positionY)
                        && !BattleSpellCatalog.isInNativeScreen(
                            recipient.positionX, recipient.positionY,
                            attacker.positionX, attacker.positionY))) continue;
            recipient.sendEncrypted(reaction,
                    "S_ACTION Mortal-Body-reflected attacker="
                            + attacker.playerObjectId() + " defender="
                            + playerObjectId() + " action="
                            + BattleActionCodes.DAMAGE + " source=" + source);
        }
        if (phase == Phase.WORLD) {
            attacker.takeClassicWorldPlayerDamage(
                    decision.reflectedDamage(), this, false, true);
        } else {
            attacker.takePlayerDamage(
                    decision.reflectedDamage(), this, false, true);
        }
        System.out.println("[LiTo] Mortal Body triggered defender="
                + playerName() + " attacker=" + attacker.playerName()
                + " probability=" + decision.probability()
                + " roll=" + decision.roll()
                + " base-damage=" + decision.baseDamage()
                + " weapon-enchant="
                + (attackerWeapon == null ? 0 : attackerWeapon.enchantLevel())
                + " armor-reduction=" + armorReduction
                + " armor-roll=" + armorRoll
                + " pvp-reduction=" + pvpReduction
                + " melee-reduction=" + meleeReduction
                + " total-reduction=" + decision.totalReduction()
                + " reflected-damage=" + decision.reflectedDamage()
                + " source=" + source
                + " trigger-effect-gfx=none"
                + " recursive-feedback-suppressed=true");
    }

    private int joyOfPainEquipmentAddedHp() {
        long total = Math.addExact(
                (long) requiredEquipmentVitalStats().totalMaximumHp(),
                (long) inventory.equippedNativeArmorBonuses().maximumHp());
        return (int) Math.max(0L, Math.min(0x7FFFL, total));
    }

    /** Runs after Mortal Body, matching retained LegacyDefenseFeedbackPlan. */
    private void applyJoyOfPainPlayerFeedback(
            ClientSession attacker, BattleJoyOfPainStatus.Lease lease,
            int feedbackDamage, String source) throws IOException {
        if (attacker == null || attacker == this || lease == null
                || !attacker.joyOfPainStatus.consume(lease)) return;
        if (feedbackDamage <= 0 || attacker.playerHp <= 0) {
            System.out.println("[LiTo] Joy of Pain consumed attacker="
                    + attacker.playerName() + " defender=" + playerName()
                    + " feedback-damage=" + feedbackDamage
                    + " source=" + source);
            return;
        }
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        byte[] reaction = Protocol.objectAction(
                attacker.playerObjectId(), BattleActionCodes.DAMAGE);
        for (ClientSession recipient : recipients) {
            if (phase == Phase.WORLD && (!sameClassicWorldMap(recipient)
                    || !BattleSpellCatalog.isInNativeScreen(
                        recipient.positionX, recipient.positionY,
                        positionX, positionY)
                        && !BattleSpellCatalog.isInNativeScreen(
                            recipient.positionX, recipient.positionY,
                            attacker.positionX, attacker.positionY))) continue;
            recipient.sendEncrypted(reaction,
                    "S_ACTION Joy-of-Pain-feedback attacker="
                            + attacker.playerObjectId() + " defender="
                            + playerObjectId() + " action="
                            + BattleActionCodes.DAMAGE + " source=" + source);
        }
        if (phase == Phase.WORLD) {
            attacker.takeClassicWorldPlayerDamage(
                    feedbackDamage, this, false, true);
        } else {
            attacker.takePlayerDamage(feedbackDamage, this, false, true);
        }
        System.out.println("[LiTo] Joy of Pain triggered attacker="
                + attacker.playerName() + " defender=" + playerName()
                + " feedback-damage=" + feedbackDamage
                + " divisor=" + BattleJoyOfPain.MISSING_HP_DIVISOR
                + " cap=" + BattleJoyOfPain.MAXIMUM_FEEDBACK_DAMAGE
                + " source=" + source
                + " lease-consumed=true recursive-feedback-suppressed=true");
    }

    private void commitPlayerCounterBarrier(
            ClientSession defender, BattleCounterBarrier.Decision decision,
            List<ClientSession> recipients) throws IOException {
        BattleSpellCatalog.CounterBarrierSpell spell =
                BattleSpellCatalog.counterBarrierSpell(
                        BattleSpellCatalog.COUNTER_BARRIER);
        byte[] effect = Protocol.effectObject(
                defender.playerObjectId(), spell.triggerEffectGfx());
        byte[] reaction = Protocol.objectAction(
                playerObjectId(), BattleActionCodes.DAMAGE);
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(effect,
                    "S_EFFECT counter-barrier-trigger defender="
                            + defender.playerObjectId() + " attacker="
                            + playerObjectId() + " gfx="
                            + spell.triggerEffectGfx()
                            + " probability=" + decision.probability()
                            + " roll=" + decision.roll());
            recipient.sendEncrypted(reaction,
                    "S_ACTION counter-barrier-reflected attacker="
                            + playerObjectId() + " defender="
                            + defender.playerObjectId() + " action="
                            + BattleActionCodes.DAMAGE);
        }
        int appliedDamage = combatDamageAfterCooking(
                decision.sourceDamage(), "counter-barrier-reflection", true);
        takePlayerDamage(appliedDamage, defender, false, true);
        System.out.println("[LiTo] Counter Barrier triggered defender="
                + defender.playerName() + " attacker=" + playerName()
                + " probability=" + decision.probability()
                + " roll=" + decision.roll()
                + " source-damage=" + decision.sourceDamage()
                + " applied-damage=" + appliedDamage
                + " original-attack-damage=0 trigger-gfx="
                + spell.triggerEffectGfx()
                + " recursive-reflection-suppressed=true");
    }

    private void applyBounceAttackWeaponDamage(
            ClientSession attacker, SourceWeaponPhysicalStats activeWeapon,
            SourceWeaponPhysicalStats sourceWeaponSnapshot,
            boolean sourceWeaponActive, long runtimeWeaponObjectId) throws IOException {
        if (attacker.timedStatus.soulOfFlameActive(System.nanoTime())) {
            System.out.println("[LiTo] Bounce Attack weapon-damage suppressed"
                    + " attacker=" + attacker.playerName()
                    + " reason=Soul-of-Flame");
            return;
        }
        BattleAbilityStatus.BounceAttack status =
                abilityStatus.bounceAttack(System.nanoTime());
        if (status.remainingSeconds() == 0 || activeWeapon == null
                || !activeWeapon.present() || activeWeapon.ranged()) {
            return;
        }
        int roll = ThreadLocalRandom.current().nextInt(1, 101);
        BattleBounceAttack.Decision decision = BattleBounceAttack.decide(
                status, activeWeapon, roll);
        System.out.println("[LiTo] Bounce Attack weapon-damage roll target="
                + playerName() + " attacker=" + attacker.playerName()
                + " weapon-item=" + activeWeapon.itemId()
                + " chance=" + decision.chance() + " roll=" + decision.roll()
                + " triggered=" + decision.damagesWeapon());
        if (decision.damagesWeapon()) {
            attacker.damageAttackingWeapon(
                    activeWeapon, sourceWeaponSnapshot,
                    sourceWeaponActive, runtimeWeaponObjectId);
        }
    }

    private void damageAttackingWeapon(
            SourceWeaponPhysicalStats activeWeapon,
            SourceWeaponPhysicalStats sourceWeaponSnapshot,
            boolean sourceWeaponActive, long runtimeWeaponObjectId) throws IOException {
        if (sourceWeaponActive) {
            GameStateStore.SourceWeaponDurabilityBalance result;
            synchronized (this) {
                SourceWeaponPhysicalStats current =
                        requiredEquipmentMagicStats().physical().weapon();
                if (playerHp <= 0 || sourceWeaponSuppressed
                        || inventory.hasEquippedWeapon() || !current.present()
                        || current.itemId() != sourceWeaponSnapshot.itemId()
                        || current.durability() != sourceWeaponSnapshot.durability()) {
                    return;
                }
                result = state.damageSourceWeapon(
                        stateCharacter(), sourceWeaponSnapshot);
            }
            sendEncrypted(Protocol.messageCode(
                            268, activeWeaponLogName(activeWeapon)),
                    "S_MESSAGE_CODE bounce-attack-weapon-damaged=268 source-item="
                            + result.itemId() + " durability="
                            + result.effectiveDurability());
            System.out.println("[LiTo] Bounce Attack damaged source weapon player="
                    + playerName() + " item=" + result.itemId()
                    + " observed=" + result.observedDurability()
                    + " effective=" + result.effectiveDurability());
            return;
        }

        RuntimeInventory previous;
        RuntimeInventory.Item damaged;
        synchronized (this) {
            RuntimeInventory.Item equipped = inventory.equippedWeaponItem();
            if (playerHp <= 0 || equipped == null
                    || equipped.objectId() != runtimeWeaponObjectId
                    || equipped.definition().catalogId() != activeWeapon.itemId()
                    || equipped.durability() >= 0x7F) {
                return;
            }
            RuntimeInventory next = inventory.copy();
            if (!next.damageWeapon(
                    equipped.objectId(), equipped.durability() + 1)) return;
            previous = inventory;
            inventory = next;
            try {
                state.saveEconomyState(stateCharacter(), shopPoints,
                        inventory.catalogCounts(), inventory.catalogItemStates());
            } catch (IOException failure) {
                inventory = previous;
                throw failure;
            }
            damaged = inventory.item(equipped.objectId());
        }
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.messageCode(268, damaged.definition().name()),
                "S_MESSAGE_CODE bounce-attack-weapon-damaged=268 object="
                        + damaged.objectId() + " durability=" + damaged.durability());
        sendEncrypted(Protocol.changeInventoryDescriptionExtended(
                        damaged.objectId(), damaged.nativeViewName(), damaged.quantity(),
                        damaged.nativeStatusDetail()),
                "S_CHANGE_ITEM_DESC_EX bounce-attack-weapon-damaged object="
                        + damaged.objectId() + " durability=" + damaged.durability());
        System.out.println("[LiTo] Bounce Attack damaged runtime weapon player="
                + playerName() + " object=" + damaged.objectId()
                + " catalog=" + damaged.definition().catalogId()
                + " durability=" + damaged.durability());
    }

    private void applyWeaponBreakWeaponDamage(int points) throws IOException {
        if (points <= 0 || points > 0x7F) {
            throw new IllegalArgumentException("invalid Weapon Break damage points");
        }

        RuntimeInventory.Item runtimeWeapon = inventory.equippedWeaponItem();
        if (runtimeWeapon != null) {
            RuntimeInventory previous;
            RuntimeInventory.Item damaged;
            synchronized (this) {
                RuntimeInventory.Item current = inventory.equippedWeaponItem();
                if (playerHp <= 0 || current == null
                        || current.objectId() != runtimeWeapon.objectId()) return;
                int nextDurability = BattleWeaponBreak.durabilityAfterDamage(
                        current.durability(), current.enchantLevel(), points);
                previous = inventory;
                if (nextDurability != current.durability()) {
                    RuntimeInventory next = inventory.copy();
                    if (!next.damageWeapon(
                            current.objectId(), nextDurability)) return;
                    inventory = next;
                    try {
                        state.saveEconomyState(stateCharacter(), shopPoints,
                                inventory.catalogCounts(),
                                inventory.catalogItemStates());
                    } catch (IOException failure) {
                        inventory = previous;
                        throw failure;
                    }
                }
                damaged = inventory.item(current.objectId());
            }
            sendInventoryDelta(previous, inventory);
            sendEncrypted(Protocol.messageCode(268, damaged.definition().name()),
                    "S_MESSAGE_CODE weapon-break-weapon-damaged=268 object="
                            + damaged.objectId() + " durability="
                            + damaged.durability());
            sendEncrypted(Protocol.changeInventoryDescriptionExtended(
                            damaged.objectId(), damaged.nativeViewName(),
                            damaged.quantity(), damaged.nativeStatusDetail()),
                    "S_CHANGE_ITEM_DESC_EX weapon-break-weapon-damaged object="
                            + damaged.objectId() + " durability="
                            + damaged.durability());
            return;
        }

        SourceWeaponPhysicalStats sourceWeapon =
                requiredEquipmentMagicStats().physical().weapon();
        if (sourceWeaponSuppressed || sourceWeapon == null
                || !sourceWeapon.present()) return;
        GameStateStore.SourceWeaponDurabilityBalance result;
        synchronized (this) {
            if (playerHp <= 0 || sourceWeaponSuppressed
                    || inventory.hasEquippedWeapon()) return;
            SourceWeaponPhysicalStats current =
                    requiredEquipmentMagicStats().physical().weapon();
            if (current == null || !current.present()
                    || current.itemId() != sourceWeapon.itemId()) return;
            result = state.damageSourceWeapon(
                    stateCharacter(), current, points);
        }
        sendEncrypted(Protocol.messageCode(268, activeWeaponLogName(sourceWeapon)),
                "S_MESSAGE_CODE weapon-break-source-weapon-damaged=268 item="
                        + result.itemId() + " durability="
                        + result.effectiveDurability());
        System.out.println("[LiTo] Weapon Break damaged source weapon player="
                + playerName() + " item=" + result.itemId() + " durability="
                + result.effectiveDurability() + " points=" + points);
    }

    private int applyGuardianTowerDamage(long objectId, int damage, String source)
            throws IOException {
        markBattleCombat();
        BattleGuardianTowers.Hit hit = hub.damageGuardianTower(
                currentRoomId, this, objectId, damage);
        if (hit == null) {
            System.out.println("[LiTo] guardian-tower damage rejected room=" + currentRoomId
                    + " attacker=" + playerName() + " object=" + objectId
                    + " damage=" + damage + " source=" + source);
            return 0;
        }
        BattleGuardianTower.Damage transition = hit.damage();
        BattleGuardianTower.Snapshot tower = transition.after();
        String objectiveLabel = tower.objectiveKind().wireLabel();
        byte[] ratio = Protocol.hitRatio(tower.objectId(), tower.hp(), tower.maxHp());
        List<ClientSession> recipients = hub.roomRules(currentRoomId).mode()
                == BattleRules.Mode.QUEST_BATTLE
                ? hub.battleRecipients(currentRoomId, tower.force())
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO " + objectiveLabel + "=" + tower.objectId()
                            + " force=" + tower.force() + " hp=" + tower.hp()
                            + "/" + tower.maxHp() + " source=" + source);
            if (transition.actionChanged()) {
                member.sendEncrypted(Protocol.objectAction(
                                tower.objectId(), tower.action()),
                        "S_ACTION " + objectiveLabel + "=" + tower.objectId()
                                + " action=" + tower.action()
                                + " source=" + source);
            }
            if (!hit.spawnedTimeAttackActors().isEmpty()) {
                int seconds = hub.roomRules(currentRoomId).timeLimitSeconds();
                member.sendEncrypted(Protocol.litoTimeLimit(seconds),
                        "S_LITO_TIMELIMIT timeattack-start-tower="
                                + tower.objectId() + " battle-seconds=" + seconds
                                + " destroyer-role=" + hit.timeAttackStartRole()
                                + " dragon-policy="
                                + (hit.timeAttackStartRole().equals("leader")
                                    ? BattleTimeAttackEncounter.DRAGON_SELECTION_SOURCE
                                    : BattleTimeAttackEncounter
                                            .NON_LEADER_DRAGON_BOUNDARY_SOURCE));
            }
            if (hit.openedSiegeGate() != null) {
                BattleDoor.Snapshot gate = hit.openedSiegeGate();
                member.sendEncrypted(Protocol.objectAction(
                                gate.objectId(), gate.action()),
                        "S_ACTION siege-inner-gate=" + gate.objectId()
                                + " action=" + gate.action()
                                + " source=two-outer-towers-destroyed");
                member.sendEncrypted(Protocol.doorAttribute(
                                gate.x(), gate.y(), gate.direction(), gate.passable()),
                        "S_CHANGE_ATTR siege-inner-gate=" + gate.objectId()
                                + " x=" + gate.x() + " y=" + gate.y()
                                + " direction=" + gate.direction()
                                + " passable=" + gate.passable()
                                + " source=two-outer-towers-destroyed");
            }
            for (BattleTimeAttackEncounter.Snapshot boss
                    : hit.spawnedTimeAttackActors()) {
                member.sendEncrypted(Protocol.timeAttackActor(boss),
                        "S_PUT_OBJECT timeattack-actor=" + boss.objectId()
                                + " npc=" + boss.npcId()
                                + " gfx=" + boss.gfx()
                                + " final-boss=" + boss.finalBoss()
                                + " hp=" + boss.hp() + "/" + boss.maxHp()
                                + " start-tower=" + tower.objectId()
                                + " destroyer-role=" + hit.timeAttackStartRole()
                                + " wave-source=" + boss.ordinaryWaveSource());
            }
        }
        if (hit.spawnedTimeAttackActors().stream()
                .anyMatch(BattleTimeAttackEncounter.Snapshot::activeAi)) {
            hub.armPveAi(currentRoomId);
        }
        if (!hit.spawnedQuestActors().isEmpty()) {
            publishQuestWaveAdvance(tower.force(), hit.completedQuestRoom(),
                    hit.spawnedQuestActors(), false,
                    tower.objectiveKind().wireLabel() + "-destroyed");
        }
        System.out.println("[LiTo] " + objectiveLabel + " damaged room=" + currentRoomId
                + " attacker=" + playerName() + " object=" + tower.objectId()
                + " force=" + tower.force() + " damage=" + damage
                + " hp=" + tower.hp() + "/" + tower.maxHp()
                + " action=" + tower.action() + " source=" + source);
        int appliedDamage = Math.max(0,
                transition.before().hp() - transition.after().hp());
        if (!hit.resolution().ended()) return appliedDamage;
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.serverEndBattle(hit.resolution());
        }
        hub.endBattle(currentRoomId);
        return appliedDamage;
    }

    private int applyQuestMonsterDamage(long objectId, int damage, String source)
            throws IOException {
        markBattleCombat();
        int poisonPaletteBeforeDamage = hub.questMonsterPoisonPalette(
                currentRoomId, objectId, System.nanoTime());
        BattleQuestEncounter.Hit hit = hub.damageQuestMonster(
                currentRoomId, this, objectId, damage);
        if (hit == null) {
            System.out.println("[LiTo] Quest monster damage rejected room=" + currentRoomId
                    + " attacker=" + playerName() + " object=" + objectId
                    + " damage=" + damage + " source=" + source);
            return 0;
        }
        BattleQuestEncounter.Damage transition = hit.damage();
        BattleQuestEncounter.Snapshot monster = transition.after();
        List<ClientSession> recipients = hub.battleRecipients(
                currentRoomId, monster.force());
        byte[] ratio = Protocol.hitRatio(
                monster.objectId(), monster.hp(), monster.maxHp());
        for (ClientSession member : recipients) {
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO quest-monster=" + monster.objectId()
                            + " force=" + monster.force()
                            + " room=" + monster.roomNumber()
                            + " hp=" + monster.hp() + "/" + monster.maxHp()
                            + " source=" + source);
            if (transition.diedNow()) {
                if (poisonPaletteBeforeDamage > 0) {
                    member.sendEncrypted(Protocol.poison(monster.objectId(), 0),
                            "S_POISON quest-monster=" + monster.objectId()
                                    + " type=0 reason=death");
                }
                member.sendEncrypted(Protocol.objectAction(
                                monster.objectId(), BattleActionCodes.DIE),
                        "S_ACTION quest-monster=" + monster.objectId()
                                + " action=" + BattleActionCodes.DIE
                                + " source=" + source);
            }
        }
        if (transition.diedNow()) {
            hub.cancelArmorBreak(currentRoomId, monster.objectId());
            applyNpcLawfulReward(monster.npcId(), "quest-" + source);
        }
        if (hit.waveCleared()) {
            publishQuestWaveAdvance(monster.force(), hit.clearedRoom(),
                    hit.spawned(), hit.objectiveUnlocked(), source);
        }
        System.out.println("[LiTo] Quest monster damaged room=" + currentRoomId
                + " attacker=" + playerName() + " object=" + monster.objectId()
                + " force=" + monster.force() + " quest-room=" + monster.roomNumber()
                + " damage=" + damage + " hp=" + monster.hp() + "/" + monster.maxHp()
                + " died=" + transition.diedNow()
                + " wave-cleared=" + hit.waveCleared()
                + " objective-unlocked=" + hit.objectiveUnlocked()
                + " source=" + source);
        return Math.max(0,
                transition.before().hp() - transition.after().hp());
    }

    private void publishQuestWaveAdvance(
            int force, int clearedRoom,
            List<BattleQuestEncounter.Snapshot> spawned,
            boolean objectiveUnlocked, String source) throws IOException {
        List<ClientSession> recipients = hub.battleRecipients(currentRoomId, force);
        if (!spawned.isEmpty()) {
            int nextRoom = clearedRoom + 1;
            String announcement = BattleQuestEncounter.armyAnnouncement(force, nextRoom);
            byte[] announcementPacket = Protocol.systemMessage(9, announcement);
            for (ClientSession member : hub.roomMembers(currentRoomId)) {
                member.sendEncrypted(announcementPacket,
                        "S_MESSAGE quest-army force=" + force
                                + " room=" + nextRoom
                                + " source=room-monsters-eliminated+"
                                + BattleQuestEncounter.ARMY_ANNOUNCEMENT_SOURCE);
            }
            for (ClientSession member : recipients) {
                for (BattleQuestBoundary.Attribute edge
                        : hub.openedQuestBoundary(currentRoomId, force, clearedRoom)) {
                    member.sendEncrypted(Protocol.doorAttribute(
                                    edge.x(), edge.y(), edge.direction(), edge.passable()),
                            "S_CHANGE_ATTR quest-boundary-open force=" + force
                                    + " after-room=" + clearedRoom
                                    + " x=" + edge.x() + " y=" + edge.y()
                                    + " direction=" + edge.direction()
                                    + " source=room-monsters-eliminated+"
                                    + BattleQuestBoundary.WIRE_SOURCE);
                }
                for (BattleQuestEncounter.Snapshot actor : spawned) {
                    member.sendEncrypted(Protocol.questMonster(actor),
                            "S_PUT_OBJECT quest-monster=" + actor.objectId()
                                    + " force=" + actor.force()
                                    + " room=" + actor.roomNumber()
                                    + " npc=" + actor.npcId()
                                    + " after-cleared-room=" + clearedRoom);
                }
            }
            hub.armPveAi(currentRoomId);
            return;
        }
        if (!objectiveUnlocked) return;
        for (ClientSession member : recipients) {
            BattleGuardianTower.Snapshot tower =
                    hub.visibleGuardianTowers(currentRoomId, member).stream()
                            .filter(candidate -> candidate.force() == force
                                    && candidate.objectiveKind()
                                    != BattleGuardianTower.ObjectiveKind
                                            .COMMON_GUARDIAN_TOWER)
                            .findFirst().orElse(null);
            if (tower == null) {
                throw new IllegalStateException("missing visible Quest objective: "
                        + "force=" + force + " room=" + clearedRoom);
            }
            member.sendEncrypted(Protocol.guardianTower(tower),
                    "S_PUT_OBJECT " + tower.objectiveKind().wireLabel()
                            + "=" + tower.objectId()
                            + " force=" + force
                            + " room=" + clearedRoom
                            + " flow-source="
                            + BattleQuestEncounter.MAP_SPECIFIC_FLOW_SOURCE
                            + " presentation-source=" + tower.placementSource()
                            + " trigger=" + source);
        }
    }

    private int applyTimeAttackActorDamage(long objectId, int damage, String source)
            throws IOException {
        markBattleCombat();
        int committedDamage = config.timeAttackPlayerPhysicalDamageFixture() > 0
                && "physical".equals(source)
                    ? config.timeAttackPlayerPhysicalDamageFixture() : damage;
        int poisonPaletteBeforeDamage = hub.timeAttackActorPoisonPalette(
                currentRoomId, objectId, System.nanoTime());
        GameHub.TimeAttackActorHit outcome = hub.damageTimeAttackActor(
                currentRoomId, this, objectId, committedDamage);
        if (outcome == null) {
            System.out.println("[LiTo] Time Attack actor damage rejected room="
                    + currentRoomId + " attacker=" + playerName()
                    + " object=" + objectId + " damage=" + committedDamage
                    + " source=" + source);
            return 0;
        }
        BattleTimeAttackEncounter.Hit hit = outcome.hit();
        BattleTimeAttackEncounter.Damage transition = hit.damage();
        BattleTimeAttackEncounter.Snapshot boss = transition.after();
        byte[] ratio = Protocol.hitRatio(
                boss.objectId(), boss.hp(), boss.maxHp());
        List<ClientSession> recipients = hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO timeattack-actor=" + boss.objectId()
                            + " npc=" + boss.npcId()
                            + " hp=" + boss.hp() + "/" + boss.maxHp()
                            + " remaining=" + hit.actorsRemaining()
                            + " source=" + source);
            if (transition.diedNow()) {
                if (poisonPaletteBeforeDamage > 0) {
                    member.sendEncrypted(Protocol.poison(boss.objectId(), 0),
                            "S_POISON timeattack-actor=" + boss.objectId()
                                    + " type=0 reason=death");
                }
                member.sendEncrypted(Protocol.objectAction(
                                boss.objectId(), BattleActionCodes.DIE),
                        "S_ACTION timeattack-actor=" + boss.objectId()
                                + " action=" + BattleActionCodes.DIE
                                + " source=" + source);
            }
            for (BattleTimeAttackEncounter.Snapshot spawned : hit.spawned()) {
                member.sendEncrypted(Protocol.timeAttackActor(spawned),
                        "S_PUT_OBJECT timeattack-actor=" + spawned.objectId()
                                + " npc=" + spawned.npcId()
                                + " gfx=" + spawned.gfx()
                                + " final-boss=" + spawned.finalBoss()
                                + " active-ai=" + spawned.activeAi()
                                + " hp=" + spawned.hp() + "/" + spawned.maxHp()
                                + " after-ordinary-fragment=" + boss.objectId());
            }
        }
        if (transition.diedNow()) {
            hub.cancelArmorBreak(currentRoomId, boss.objectId());
            applyNpcLawfulReward(boss.npcId(), "timeattack-" + source);
        }
        if (hit.spawned().stream()
                .anyMatch(BattleTimeAttackEncounter.Snapshot::activeAi)) {
            hub.armPveAi(currentRoomId);
        }
        System.out.println("[LiTo] Time Attack actor damaged room=" + currentRoomId
                + " attacker=" + playerName() + " object=" + boss.objectId()
                + " npc=" + boss.npcId() + " damage=" + committedDamage
                + " hp=" + boss.hp() + "/" + boss.maxHp()
                + " died=" + transition.diedNow()
                + " remaining=" + hit.actorsRemaining()
                + " completed=" + hit.finalBossesCleared()
                + " source=" + source
                + (committedDamage == damage ? "" : ";acceptance-fixture"));
        int appliedDamage = Math.max(0,
                transition.before().hp() - transition.after().hp());
        if (!outcome.resolution().ended()) return appliedDamage;
        for (ClientSession member : recipients) {
            member.serverEndBattle(outcome.resolution());
        }
        hub.endBattle(currentRoomId);
        return appliedDamage;
    }

    /**
     * Publishes damage that was already committed by the quest encounter's
     * retained poison clock.  This deliberately mirrors the ordinary attack
     * path without applying the damage a second time.
     */
    private void publishQuestMonsterPoisonUpdate(
            GameHub.QuestMonsterPoisonUpdate outcome, long nowNanos) throws IOException {
        BattleQuestEncounter.PoisonUpdate update = outcome.update();
        for (BattleQuestEncounter.Hit hit : update.hits()) {
            BattleQuestEncounter.Damage transition = hit.damage();
            BattleQuestEncounter.Snapshot monster = transition.after();
            List<ClientSession> recipients = hub.battleRecipients(
                    currentRoomId, monster.force());
            byte[] ratio = Protocol.hitRatio(
                    monster.objectId(), monster.hp(), monster.maxHp());
            for (ClientSession member : recipients) {
                member.sendEncrypted(ratio,
                        "S_HIT_RATIO quest-monster=" + monster.objectId()
                                + " force=" + monster.force()
                                + " room=" + monster.roomNumber()
                                + " hp=" + monster.hp() + "/" + monster.maxHp()
                                + " source=enchant-venom-poison-tick");
                if (transition.diedNow()) {
                    member.sendEncrypted(Protocol.poison(monster.objectId(), 0),
                            "S_POISON quest-monster=" + monster.objectId()
                                    + " type=0 reason=damage-poison-death");
                    member.sendEncrypted(Protocol.objectAction(
                                    monster.objectId(), BattleActionCodes.DIE),
                            "S_ACTION quest-monster=" + monster.objectId()
                                    + " action=" + BattleActionCodes.DIE
                                    + " source=enchant-venom-poison-tick");
                }
            }
            if (transition.diedNow() && outcome.attacker() != null) {
                outcome.attacker().applyNpcLawfulReward(
                        monster.npcId(), "quest-enchant-venom-poison");
            }
            if (hit.waveCleared()) {
                publishQuestWaveAdvance(monster.force(), hit.clearedRoom(),
                        hit.spawned(), hit.objectiveUnlocked(),
                        "enchant-venom-poison-tick");
            }
            System.out.println("[LiTo] Quest monster poison tick room=" + currentRoomId
                    + " attacker=" + update.attackerObjectId()
                    + " object=" + monster.objectId()
                    + " damage=" + (transition.before().hp() - transition.after().hp())
                    + " hp=" + monster.hp() + "/" + monster.maxHp()
                    + " died=" + transition.diedNow()
                    + " wave-cleared=" + hit.waveCleared());
        }
        if (update.expired() && update.target().alive()) {
            int palette = hub.questMonsterPoisonPalette(
                    currentRoomId, update.target().objectId(), nowNanos);
            byte[] clear = Protocol.poison(update.target().objectId(), palette);
            for (ClientSession member : hub.battleRecipients(
                    currentRoomId, update.target().force())) {
                member.sendEncrypted(clear,
                        "S_POISON quest-monster=" + update.target().objectId()
                                + " type=" + palette
                                + " reason=damage-poison-expired");
            }
        }
    }

    /** Publishes damage already committed by the WORLD monster poison clock. */
    private void publishClassicWorldMonsterPoisonUpdate(
            ClassicWorldMonsterPopulation.PoisonUpdate update,
            long nowNanos) throws IOException {
        List<ClientSession> recipients =
                classicWorldMembers(classicWorldMapId);
        ClientSession attacker = recipients.stream()
                .filter(candidate -> sameClassicWorldMap(candidate)
                        && candidate.playerObjectId()
                            == update.playerObjectId())
                .findFirst().orElse(null);
        for (ClassicWorldMonsterPopulation.Hit hit : update.hits()) {
            ClassicWorldMonsterPopulation.Snapshot monster = hit.after();
            byte[] ratio = Protocol.hitRatio(
                    monster.objectId(), monster.currentHp(),
                    monster.maximumHp());
            for (ClientSession member : recipients) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                monster.x(), monster.y())) continue;
                member.sendEncrypted(ratio,
                        "S_HIT_RATIO classic-world-monster="
                                + monster.objectId() + " hp="
                                + monster.currentHp() + "/"
                                + monster.maximumHp()
                                + " source=Curse-Poison-tick");
                if (hit.diedNow()) {
                    member.sendEncrypted(
                            Protocol.poison(monster.objectId(), 0),
                            "S_POISON classic-world-monster="
                                    + monster.objectId()
                                    + " type=0 reason=damage-poison-death");
                    member.sendEncrypted(Protocol.objectAction(
                                    monster.objectId(), BattleActionCodes.DIE),
                            "S_ACTION classic-world-monster="
                                    + monster.objectId() + " action="
                                    + BattleActionCodes.DIE
                                    + " source=Curse-Poison-tick");
                }
            }
            if (hit.diedNow()) {
                handleClassicWorldWaterDragonDeath(
                        monster, hit.contributions());
                if (attacker != null) {
                    attacker.distributeClassicWorldMonsterRewards(
                            monster, hit.contributions());
                }
                hub.scheduleClassicWorldMonsterLifecycle(
                        classicWorldInstanceId, monster);
            }
            System.out.println("[LiTo] classic-world monster poison tick"
                    + " map=" + classicWorldMapId + " instance="
                    + classicWorldInstanceId + " attacker="
                    + update.attackerObjectId() + " owner="
                    + update.playerObjectId() + " contributor="
                    + update.contributorKind() + " object="
                    + monster.objectId() + " damage=" + hit.appliedDamage()
                    + " hp=" + monster.currentHp() + "/"
                    + monster.maximumHp() + " died=" + hit.diedNow());
        }
        if (update.expired() && update.target().alive()) {
            int palette = hub.classicWorldMonsterPoisonPalette(
                    classicWorldMapId, classicWorldInstanceId,
                    update.target().objectId(), nowNanos);
            byte[] clear = Protocol.poison(
                    update.target().objectId(), palette);
            for (ClientSession member : recipients) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                update.target().x(), update.target().y())) continue;
                member.sendEncrypted(clear,
                        "S_POISON classic-world-monster="
                                + update.target().objectId() + " type="
                                + palette + " reason=damage-poison-expired");
            }
        }
    }

    /** Publishes an already-committed Time Attack poison transition. */
    private void publishTimeAttackPoisonUpdate(
            GameHub.TimeAttackPoisonUpdate outcome, long nowNanos) throws IOException {
        BattleTimeAttackEncounter.PoisonUpdate update = outcome.update();
        List<ClientSession> recipients = hub.roomMembers(currentRoomId);
        for (BattleTimeAttackEncounter.Hit hit : update.hits()) {
            BattleTimeAttackEncounter.Damage transition = hit.damage();
            BattleTimeAttackEncounter.Snapshot actor = transition.after();
            byte[] ratio = Protocol.hitRatio(
                    actor.objectId(), actor.hp(), actor.maxHp());
            for (ClientSession member : recipients) {
                member.sendEncrypted(ratio,
                        "S_HIT_RATIO timeattack-actor=" + actor.objectId()
                                + " npc=" + actor.npcId()
                                + " hp=" + actor.hp() + "/" + actor.maxHp()
                                + " remaining=" + hit.actorsRemaining()
                                + " source=enchant-venom-poison-tick");
                if (transition.diedNow()) {
                    member.sendEncrypted(Protocol.poison(actor.objectId(), 0),
                            "S_POISON timeattack-actor=" + actor.objectId()
                                    + " type=0 reason=damage-poison-death");
                    member.sendEncrypted(Protocol.objectAction(
                                    actor.objectId(), BattleActionCodes.DIE),
                            "S_ACTION timeattack-actor=" + actor.objectId()
                                    + " action=" + BattleActionCodes.DIE
                                    + " source=enchant-venom-poison-tick");
                }
                for (BattleTimeAttackEncounter.Snapshot spawned : hit.spawned()) {
                    member.sendEncrypted(Protocol.timeAttackActor(spawned),
                            "S_PUT_OBJECT timeattack-actor=" + spawned.objectId()
                                    + " npc=" + spawned.npcId()
                                    + " gfx=" + spawned.gfx()
                                    + " final-boss=" + spawned.finalBoss()
                                    + " active-ai=" + spawned.activeAi()
                                    + " hp=" + spawned.hp() + "/" + spawned.maxHp()
                                    + " after-poisoned-fragment=" + actor.objectId());
                }
            }
            if (transition.diedNow() && outcome.attacker() != null) {
                outcome.attacker().applyNpcLawfulReward(
                        actor.npcId(), "timeattack-enchant-venom-poison");
            }
            if (hit.spawned().stream()
                    .anyMatch(BattleTimeAttackEncounter.Snapshot::activeAi)) {
                hub.armPveAi(currentRoomId);
            }
            System.out.println("[LiTo] Time Attack actor poison tick room="
                    + currentRoomId + " attacker=" + update.attackerObjectId()
                    + " object=" + actor.objectId()
                    + " damage=" + (transition.before().hp() - transition.after().hp())
                    + " hp=" + actor.hp() + "/" + actor.maxHp()
                    + " died=" + transition.diedNow()
                    + " remaining=" + hit.actorsRemaining());
        }
        if (update.expired() && update.target().alive()) {
            int palette = hub.timeAttackActorPoisonPalette(
                    currentRoomId, update.target().objectId(), nowNanos);
            byte[] clear = Protocol.poison(update.target().objectId(), palette);
            for (ClientSession member : recipients) {
                member.sendEncrypted(clear,
                        "S_POISON timeattack-actor=" + update.target().objectId()
                                + " type=" + palette
                                + " reason=damage-poison-expired");
            }
        }
        if (!outcome.resolution().ended()) return;
        for (ClientSession member : recipients) {
            member.serverEndBattle(outcome.resolution());
        }
        hub.endBattle(currentRoomId);
    }

    /**
     * Exact retained CalcExp/L1PcInstance lawful path: negate the defeated
     * NPC's source lawful value, clamp the character to a signed word, then
     * publish S_CHANGE_ALIGNMENT to every room member that owns the actor.
     */
    private void applyNpcLawfulReward(int npcId, String source) throws IOException {
        SourceNpcPhysicalStats npc;
        try {
            npc = selectedSourceAccounts().npcPhysicalStats(npcId);
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] lawful reward skipped; source NPC lookup failed"
                    + " player=" + playerName() + " npc=" + npcId
                    + " reason=" + sourceFailure.getClass().getSimpleName()
                    + ": " + sourceFailure.getMessage());
            return;
        }
        if (npc.lawful() == 0) return;

        CharacterSummary character = selectedCharacterSummary();
        int sourceLawful = character == null ? 0 : nativeLawful(character.lawful());
        GameStateStore.LawfulMutation mutation = state.addLawful(
                stateCharacter(), sourceLawful, -npc.lawful());
        playerLawful = mutation.after();
        if (!mutation.changed()) return;

        byte[] packet = Protocol.changeAlignment(playerObjectId(), playerLawful);
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.sendEncrypted(packet,
                    "S_CHANGE_ALIGNMENT player=" + playerName()
                            + " object=" + playerObjectId()
                            + " npc=" + npcId
                            + " source-npc-lawful=" + npc.lawful()
                            + " requested-delta=" + mutation.requestedDelta()
                            + " applied-delta=" + mutation.appliedDelta()
                            + " lawful=" + mutation.before() + "->" + mutation.after()
                            + " source=" + source);
        }
        System.out.println("[LiTo] lawful changed player=" + playerName()
                + " npc=" + npcId + " source-npc-lawful=" + npc.lawful()
                + " lawful=" + mutation.before() + "->" + mutation.after()
                + " source=" + source);
    }

    private void attemptEnchantVenomPoison(
            ClientSession target, BattleQuestEncounter.Snapshot questTarget,
            BattleTimeAttackEncounter.Snapshot timeTarget,
            ClassicWorldMonsterPopulation.Snapshot worldTarget,
            boolean weaponPresent,
            boolean physicalHit, long targetObjectId) throws IOException {
        long now = System.nanoTime();
        boolean enchantActive = venomEnchantStatus.active(now);
        boolean npcTarget = questTarget != null || timeTarget != null
                || worldTarget != null;
        if (!enchantActive || !weaponPresent
                || (target == null && !npcTarget) || target == this) return;
        int configuredRoll = config.enchantVenomProcFixtureRoll();
        int oneBasedRoll = configuredRoll == 0
                ? ThreadLocalRandom.current().nextInt(1, 101) : configuredRoll;
        boolean triggered = BattleVenomEnchantStatus.triggers(
                enchantActive, weaponPresent, oneBasedRoll);
        boolean applied = false;
        boolean poisonResistance = false;
        boolean alreadyPoisoned = false;
        if (triggered) {
            BattleSpellCatalog.EnchantVenomSpell spell =
                    BattleSpellCatalog.enchantVenomSpell(
                            BattleSpellCatalog.ENCHANT_VENOM);
            if (target != null) {
                synchronized (target) {
                    poisonResistance = target.dragonEyeStatus.snapshot(now)
                            .poisonResistance() > 0
                            || !target.timedStatus.acceptsPoison(
                                    now, BattleTimedStatus.PoisonKind.DAMAGE);
                    alreadyPoisoned = target.timedStatus.poisonActive(now);
                    boolean sameBattle = phase == Phase.BATTLE
                            && target.phase == Phase.BATTLE
                            && target.currentRoomId == currentRoomId;
                    boolean sameWorld = phase == Phase.WORLD
                            && target.phase == Phase.WORLD
                            && sameClassicWorldMap(target);
                    if ((sameBattle || sameWorld) && !target.observer
                            && target.playerHp > 0 && !poisonResistance
                            && !alreadyPoisoned) {
                        applied = target.timedStatus.activatePoison(
                                now, spell.poisonDurationSeconds(),
                                spell.tickIntervalMillis());
                        if (applied) target.poisonAttacker = this;
                    }
                }
            } else if (questTarget != null) {
                alreadyPoisoned = hub.questMonsterPoisonActive(
                        currentRoomId, questTarget.objectId(), now);
                applied = !alreadyPoisoned && hub.poisonQuestMonster(
                        currentRoomId, this, questTarget.objectId(), now,
                        spell.poisonDurationSeconds(), spell.tickIntervalMillis());
            } else if (timeTarget != null) {
                alreadyPoisoned = hub.timeAttackActorPoisonActive(
                        currentRoomId, timeTarget.objectId(), now);
                applied = !alreadyPoisoned && hub.poisonTimeAttackActor(
                        currentRoomId, this, timeTarget.objectId(), now,
                        spell.poisonDurationSeconds(), spell.tickIntervalMillis());
            } else if (worldTarget != null) {
                alreadyPoisoned = hub.classicWorldMonsterPoisonActive(
                        classicWorldMapId, classicWorldInstanceId,
                        worldTarget.objectId(), now);
                applied = !alreadyPoisoned && hub.poisonClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        worldTarget.objectId(), playerObjectId(), now,
                        spell.poisonDurationSeconds(), spell.tickIntervalMillis());
                if (applied) {
                    hub.provokeClassicWorldMonster(
                            classicWorldMapId, classicWorldInstanceId,
                            worldTarget.objectId(), playerObjectId());
                }
            }
        }
        if (applied) {
            if (target != null) {
                target.broadcastPoisonState(target.currentPoisonPalette(now),
                        "Enchant-Venom-proc");
            } else if (questTarget != null) {
                int palette = hub.questMonsterPoisonPalette(
                        currentRoomId, questTarget.objectId(), now);
                byte[] packet = Protocol.poison(questTarget.objectId(), palette);
                for (ClientSession recipient : hub.battleRecipients(
                        currentRoomId, questTarget.force())) {
                    recipient.sendEncrypted(packet,
                            "S_POISON quest-monster=" + questTarget.objectId()
                                    + " type=" + palette
                                    + " reason=Enchant-Venom-proc");
                }
            } else if (timeTarget != null) {
                int palette = hub.timeAttackActorPoisonPalette(
                        currentRoomId, timeTarget.objectId(), now);
                byte[] packet = Protocol.poison(timeTarget.objectId(), palette);
                for (ClientSession recipient : hub.roomMembers(currentRoomId)) {
                    recipient.sendEncrypted(packet,
                            "S_POISON timeattack-actor=" + timeTarget.objectId()
                                    + " type=" + palette
                                    + " reason=Enchant-Venom-proc");
                }
            } else if (worldTarget != null) {
                int palette = hub.classicWorldMonsterPoisonPalette(
                        classicWorldMapId, classicWorldInstanceId,
                        worldTarget.objectId(), now);
                byte[] packet = Protocol.poison(worldTarget.objectId(), palette);
                for (ClientSession recipient
                        : classicWorldMembers(classicWorldMapId)) {
                    if (!sameClassicWorldMap(recipient)
                            || !BattleSpellCatalog.isInNativeScreen(
                                    recipient.positionX, recipient.positionY,
                                    worldTarget.x(), worldTarget.y())) continue;
                    recipient.sendEncrypted(packet,
                            "S_POISON classic-world-monster="
                                    + worldTarget.objectId()
                                    + " type=" + palette
                                    + " reason=Enchant-Venom-proc");
                }
            }
        }
        System.out.println("[LiTo] Enchant Venom proc attacker=" + playerName()
                + " target=" + targetObjectId + " roll=" + oneBasedRoll
                + " chance=" + BattleVenomEnchantStatus.PROC_PERCENT
                + " physical-hit=" + physicalHit + " triggered=" + triggered
                + " applied=" + applied + " poison-resistance=" + poisonResistance
                + " already-poisoned=" + alreadyPoisoned
                + " quest-npc=" + (questTarget != null)
                + " timeattack-npc=" + (timeTarget != null)
                + " classic-world-npc=" + (worldTarget != null)
                + " poison-duration="
                + BattleVenomEnchantStatus.POISON_DURATION_SECONDS
                + "s tick-ms="
                + BattleVenomEnchantStatus.POISON_TICK_MILLIS
                + " tick-damage=" + BattleVenomEnchantStatus.POISON_TICK_DAMAGE);
    }

    private void takePlayerDamage(int damage, ClientSession attacker) throws IOException {
        takePlayerDamage(damage, attacker, true, false);
    }

    private void takePlayerPoisonDamage(int damage, ClientSession attacker)
            throws IOException {
        takePlayerDamage(damage, attacker, false, true);
    }

    private ClassicWorldFatalContext takeClassicWorldMonsterDamage(
            int damage, long attackerObjectId)
            throws IOException {
        return takeClassicWorldDirectDamage(damage, attackerObjectId);
    }

    /** Common retained L1PcInstance direct-damage tail after attacker-side Calc. */
    private ClassicWorldFatalContext takeClassicWorldDirectDamage(
            double sourceDamage, long attackerObjectId) throws IOException {
        if (phase != Phase.WORLD || playerHp <= 0 || sourceDamage <= 0) {
            return ClassicWorldFatalContext.NON_FATAL;
        }
        ClassicWorldMonsterPopulation.Snapshot worldNpcAttacker =
                hub.classicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        attackerObjectId);
        BattleAbilityStatus.IllusionAvatar avatar =
                abilityStatus.illusionAvatar(System.nanoTime());
        int damage = (int) (sourceDamage * avatar.incomingDamageRate());
        damage = nativeMagicDollDamageAfterActiveReduction(
                damage, true, "classic-world");
        if (damage <= 0) return ClassicWorldFatalContext.NON_FATAL;
        playerHp = Math.max(0, playerHp - damage);
        cancelSleep(playerHp == 0
                ? "classic-world-fatal-damage" : "classic-world-damage");
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(playerHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT classic-world player=" + playerHp + "/" + playerMaxHp
                        + " attacker=" + attackerObjectId);
        byte[] ratio = Protocol.hitRatio(
                playerObjectId(), playerHp, playerMaxHp);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) continue;
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO classic-world-player=" + playerObjectId()
                            + " hp=" + playerHp + "/" + playerMaxHp);
        }
        revealInvisibility(playerHp == 0
                ? "classic-world-fatal-damage" : "classic-world-damage");
        if (playerHp != 0) return ClassicWorldFatalContext.NON_FATAL;

        if (ClassicWorldGuardCatalog.isGuard(worldNpcAttacker)) {
            GameStateStore.GeneralPkState cleared =
                    state.clearGeneralPkAfterGuardDeath(stateCharacter());
            generalPkCount = cleared.count();
            lastPkEpochSeconds = cleared.lastPkEpochSeconds();
            System.out.println("[LiTo] L1Guard death absolution player="
                    + playerName() + " guard=" + worldNpcAttacker.objectId()
                    + " pk-count=" + generalPkCount
                    + " last-pk-cleared=true");
        }

        if (ClassicWorldGuardianCatalog.isGuardian(worldNpcAttacker)) {
            GameStateStore.ElfPkState cleared =
                    state.clearElfPkAfterGuardianDeath(stateCharacter());
            elfPkCount = cleared.count();
            lastPkForElfEpochSeconds = cleared.lastPkEpochSeconds();
            System.out.println("[LiTo] L1Guardian death absolution player="
                    + playerName() + " guardian=" + worldNpcAttacker.objectId()
                    + " elf-pk-count=" + elfPkCount
                    + " last-pk-for-elf-cleared=true");
        }

        deathConfirmationPending = false;
        timedStatus.clearWaterDragonAffliction();
        dragonSkinStatus.clear();
        if (awakenStatus.clear().active()) {
            polymorphStatus.clear();
            rebuildMaximumVitals(System.nanoTime());
        }
        burningSlashStatus.clear();
        guardBrakeStatus.clear();
        armBreakerStatus.clear();
        joyOfPainStatus.clear();
        resistFearStatus.clear();
        state.saveTimedResistFearBuff(
                stateCharacter(), GameStateStore.TimedResistFearBuff.none());
        cancelClassicWorldArmorBreak();
        hub.cancelClassicWorldPatience(
                classicWorldMapId, classicWorldInstanceId, playerObjectId());
        hub.clearClassicWorldMonsterTargets(playerObjectId());
        boolean damagePoisonCured = timedStatus.curePoison();
        boolean silencePoisonCured = timedStatus.curePoisonSilence();
        poisonAttacker = null;
        if (silencePoisonCured) {
            sendEncrypted(Protocol.messageCode(311),
                    "S_MESSAGE_CODE classic-world-silence-poison-death-cured=311");
        }
        cancelParalysis("classic-world-player-death");
        classicWorldPoisonAttackerObjectId = 0;
        classicWorldPoisonKind = ClassicWorldMonsterPoisonAttack.Kind.NONE;
        if (damagePoisonCured || silencePoisonCured) {
            broadcastPoisonState(currentPoisonPalette(System.nanoTime()),
                    "classic-world-player-death");
        }
        cancelFreeze("classic-world-player-death");
        cancelEarthBind("classic-world-player-death");
        cancelShockStun("classic-world-player-death");
        cancelThunderGrab("classic-world-player-death");
        byte[] death = Protocol.objectAction(
                playerObjectId(), BattleActionCodes.DIE);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) continue;
            member.sendEncrypted(death,
                    "S_ACTION classic-world player-death=" + playerObjectId()
                            + " attacker=" + attackerObjectId
                            + " tournament-confirm-death=false");
        }
        ClassicWorldFatalContext fatalContext =
                handleClassicWorldWarLeaderDeath(attackerObjectId);
        publishClassicWorldPlayerKill(attackerObjectId, fatalContext.warDeath());
        applyClassicWorldDeathExperiencePenalty(attackerObjectId);
        System.out.println("[LiTo] classic-world player defeated player="
                + playerName() + " attacker=" + attackerObjectId
                + " C_RESTART-awaiting=true S_LITO_CONFIRM_DEATH=false");
        return fatalContext;
    }

    /**
     * Retained order after action 8 and the encounter return: attacking castle
     * leaders leave their first siege, then a simulated-war clan owner ends
     * that war. The same-war result survives deletion for this one fatal hit.
     */
    private ClassicWorldFatalContext handleClassicWorldWarLeaderDeath(
            long attackerObjectId) {
        ClientSession attacker = classicWorldPlayerAttacker(attackerObjectId);
        if (attacker == null || ClassicWorldDeathContext.encounterProtects(
                battleLevel(), attacker.battleLevel())) {
            return new ClassicWorldFatalContext(true, false, false);
        }

        int victimCastleId = ClassicWorldCastleWarField.castleIdAt(
                classicWorldMapId, positionX, positionY);
        boolean activeCastleWarAtVictim = victimCastleId != 0
                && hub.classicCastleWarActive(
                        selectedClassicServerName, victimCastleId);
        boolean sameClanWar = hub.classicClanWarActiveBetween(
                sourceCharacterIdentity(), attacker.sourceCharacterIdentity());
        boolean warDeath = activeCastleWarAtVictim || sameClanWar;

        GameHub.ClassicCastleSiegeResult castle =
                hub.ceaseClassicCastleSiegeForAttackingLeaderDeath(
                        selectedClassicServerName, sourceCharacterIdentity());
        if (castle.mutation() == GameHub.ClassicCastleSiegeMutation.CEASED) {
            List<ClientSession> sourceRecipients = hub.connectedSessionsSnapshot()
                    .stream().filter(session -> session.usesClassicSource(
                            selectedClassicServerName)).toList();
            GameHub.deliverClassicCastleWarNotices(
                    selectedClassicServerName, castle.notices(), sourceRecipients);
            System.out.println("[LiTo] classic castle-war attacking leader death player="
                    + playerName() + " clan="
                    + hub.clanData(sourceCharacterIdentity()).name()
                    + " castle=" + castle.castleId()
                    + " remaining-attackers=" + castle.attackingClans());
        }

        GameHub.ClassicClanWarLeaderDeathResolution clanWar =
                hub.endClassicClanWarForLeaderDeath(
                        sourceCharacterIdentity(), attacker.sourceCharacterIdentity());
        if (!clanWar.ended()) {
            return new ClassicWorldFatalContext(true, false, warDeath);
        }
        byte[] ended = Protocol.clanWar(
                Protocol.ClanWarNoticeType.ENDED,
                clanWar.war().clanOne(), clanWar.war().clanTwo());
        for (ClientSession recipient : clanWar.recipients()) {
            try {
                recipient.sendEncrypted(ended,
                        "S_WAR type=3 clanOne=" + clanWar.war().clanOne()
                                + " clanTwo=" + clanWar.war().clanTwo()
                                + " reason=clan-leader-death");
            } catch (IOException failure) {
                System.err.println("[LiTo] clan-war leader-death notice failed player="
                        + recipient.playerName() + " error=" + failure.getMessage());
            }
        }
        System.out.println("[LiTo] classic clan-war leader death player="
                + playerName() + " clan=" + clanWar.war().clanOne()
                + " enemy=" + clanWar.war().clanTwo()
                + " attacker-same-war=" + clanWar.attackerSameWar()
                + " recipients=" + clanWar.recipients().size());
        return new ClassicWorldFatalContext(
                true, clanWar.attackerSameWar(), warDeath);
    }

    /**
     * Retained Death announcement/count branch. The selected LiTo client uses
     * opcode FA for S_LITO_CLAN, so the incompatible retained FA/54/02 centre
     * banner is represented by its native S_SystemMessage channel instead.
     */
    private void publishClassicWorldPlayerKill(
            long attackerObjectId, boolean warDeath) throws IOException {
        ClientSession attacker = classicWorldPlayerAttacker(attackerObjectId);
        if (attacker == null
                || ClassicWorldDeathContext.encounterProtects(
                        battleLevel(), attacker.battleLevel())
                || battleLevel() < 10
                || attacker.isAdministrator()) {
            return;
        }
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        if (!warDeath && map.isCombatZone(positionX, positionY)) return;

        GameStateStore.ClassicPlayerKillMutation mutation =
                state.recordClassicPlayerKill(
                        attacker.stateCharacter(), stateCharacter());
        attacker.classicKillCount = mutation.attackerAfter().kills();
        attacker.classicDeathCount = mutation.attackerAfter().deaths();
        classicKillCount = mutation.victimAfter().kills();
        classicDeathCount = mutation.victimAfter().deaths();

        String message = "\\fX[" + attacker.playerName()
                + "] \\fT擊殺 \\fR[" + playerName() + "]";
        byte[] announcement = Protocol.systemMessage(9, message);
        for (ClientSession recipient : hub.connectedSessionsSnapshot()) {
            if ((recipient.phase != Phase.WORLD
                    && recipient.phase != Phase.BATTLE)
                    || recipient.selectedCharacter.isBlank()
                    || !recipient.usesClassicSource(selectedClassicServerName)) {
                continue;
            }
            try {
                recipient.sendEncrypted(announcement,
                        "S_MESSAGE classic-player-kill winner="
                                + attacker.playerName() + " loser=" + playerName()
                                + " retained-green-fa54-incompatible=true");
            } catch (IOException failure) {
                System.err.println("[LiTo] classic player-kill announcement failed player="
                        + recipient.playerName() + " error="
                        + failure.getMessage());
            }
        }
        System.out.println("[LiTo] classic player-kill counted winner="
                + attacker.playerName() + " loser=" + playerName()
                + " war=" + warDeath + " winner-kills="
                + attacker.classicKillCount + " loser-deaths="
                + classicDeathCount);
    }

    /** Retained Death ordering: action8, encounter gate, then map/zone penalties. */
    private void applyClassicWorldDeathExperiencePenalty(long attackerObjectId)
            throws IOException {
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        ClientSession playerAttacker = classicWorldPlayerAttacker(attackerObjectId);
        if (playerAttacker != null && ClassicWorldDeathContext.encounterProtects(
                battleLevel(), playerAttacker.battleLevel())) {
            System.out.println("[LiTo] classic-world death penalties skipped player="
                    + playerName() + " reason=encounter-guardian victim-level="
                    + battleLevel() + " attacker=" + playerAttacker.playerName()
                    + " attacker-level=" + playerAttacker.battleLevel());
            return;
        }
        boolean protectedZone = !map.isNormalZone(positionX, positionY);
        if (!map.allowsDeathPenalty() || protectedZone) {
            System.out.println("[LiTo] classic-world death EXP penalty skipped player="
                    + playerName() + " map=" + classicWorldMapId
                    + " zone=" + map.zoneType(positionX, positionY)
                    + " player-attacker=" + (playerAttacker != null)
                    + " map-penalty=" + map.allowsDeathPenalty());
            return;
        }

        CharacterSummary character = selectedCharacterSummary();
        if (character == null) return;
        int nonConsumeMask = classicWorldDeathSafeNonConsumeMask();
        boolean[] nonConsumeNotified = { false };
        if (playerLawful < 32_767) {
            applyClassicWorldDeathItemPenalty(
                    nonConsumeMask, nonConsumeNotified);
            applyClassicWorldDeathSkillPenalty(
                    nonConsumeMask, nonConsumeNotified);
        }
        if (applyClassicWorldDeathExperienceProtection(
                nonConsumeMask, nonConsumeNotified)) {
            System.out.println("[LiTo] classic-world death EXP protected player="
                    + playerName() + " map=" + classicWorldMapId
                    + " zone=" + map.zoneType(positionX, positionY));
            return;
        }
        int sourceLevel = Math.max(1,
                Math.min(ClassicExperienceCatalog.MAXIMUM_LEVEL, character.level()));
        GameStateStore.ClassicDeathPenaltyMutation penalty =
                state.applyClassicDeathPenalty(
                        stateCharacter(), character.experience(), sourceLevel);
        playerClassicExperience = penalty.afterExperience();
        playerClassicLevel = penalty.afterLevel();
        if (penalty.changed()) {
            if (penalty.levelChanged()) {
                sendNativeBattleStatus(
                        System.nanoTime(), "classic-world-death-level-down");
            } else {
                sendEncrypted(Protocol.experience(
                                playerClassicLevel, playerClassicExperience),
                        "S_EXP classic-world death-penalty player=" + playerName()
                                + " level=" + playerClassicLevel
                                + " experience=" + penalty.beforeExperience()
                                + "->" + penalty.afterExperience()
                                + " requested=" + penalty.requestedPenalty()
                                + " applied=" + penalty.appliedPenalty());
            }
        }
        System.out.println("[LiTo] classic-world death EXP penalty player="
                + playerName() + " map=" + classicWorldMapId
                + " zone=" + map.zoneType(positionX, positionY)
                + " player-attacker=" + (playerAttacker != null)
                + " requested=" + penalty.requestedPenalty()
                + " applied=" + penalty.appliedPenalty()
                + " exp=" + penalty.beforeExperience() + "->"
                + penalty.afterExperience() + " level="
                + penalty.beforeLevel() + "->" + penalty.afterLevel());
    }

    /**
     * Retained add.DeathSafe EXP category: a non-consuming mask wins first;
     * otherwise the first consumable carrier in native inventory order loses
     * one unit durably before the protected death is exposed to the client.
     */
    private boolean applyClassicWorldDeathExperienceProtection(
            int nonConsumeMask, boolean[] nonConsumeNotified)
            throws IOException {
        if ((nonConsumeMask
                & ClassicWorldDeathPenaltyCatalog.EXPERIENCE_CATEGORY) != 0) {
            sendClassicWorldDeathSafeNonConsumeOnce(
                    nonConsumeNotified, "experience");
            return true;
        }
        return consumeClassicWorldDeathSafe(
                ClassicWorldDeathPenaltyCatalog.EXPERIENCE_CATEGORY,
                "experience");
    }

    private int classicWorldDeathSafeNonConsumeMask() {
        int mask = 0;
        for (RuntimeInventory.Item item : inventory.items()) {
            ClassicWorldDeathPenaltyCatalog.DeathSafe safe =
                    ClassicWorldDeathPenaltyCatalog.deathSafe(
                            item.definition().catalogId());
            if (safe != null && !safe.consume()) {
                mask |= safe.categoryMask();
            }
        }
        return mask;
    }

    private void sendClassicWorldDeathSafeNonConsumeOnce(
            boolean[] notified, String category) throws IOException {
        if (notified[0]) return;
        sendEncrypted(Protocol.messageCode(
                        166, "死亡保護道具發揮了作用"),
                "S_MESSAGE_CODE death-safe-nonconsume=166 category=" + category);
        notified[0] = true;
    }

    private boolean consumeClassicWorldDeathSafe(int category, String categoryName)
            throws IOException {
        RuntimeInventory.Item carrier = null;
        for (RuntimeInventory.Item item : inventory.items()) {
            ClassicWorldDeathPenaltyCatalog.DeathSafe safe =
                    ClassicWorldDeathPenaltyCatalog.deathSafe(
                            item.definition().catalogId());
            if (safe != null && safe.consume() && safe.protects(category)) {
                carrier = item;
                break;
            }
        }
        if (carrier == null) return false;

        RuntimeInventory previous = inventory;
        RuntimeInventory next = previous.copy();
        if (!next.remove(carrier.objectId(), 1)) {
            throw new IOException("validated DeathSafe EXP carrier disappeared");
        }
        Set<Long> consumedSourceObjects = carrier.sourceBound()
                && carrier.quantity() == 1 ? Set.of(carrier.objectId()) : Set.of();
        if (consumedSourceObjects.isEmpty()) {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    next.catalogCounts(), next.catalogItemStates());
        } else {
            state.saveEconomyStateAndStoryQuestsConsumingSourceObjects(
                    stateCharacter(), shopPoints,
                    next.catalogCounts(), next.catalogItemStates(),
                    state.storyQuests(stateCharacter()).effective(),
                    consumedSourceObjects);
        }
        inventory = next;
        sendInventoryDelta(previous, next, false);
        sendEncrypted(Protocol.messageCode(
                        166, "已消耗一個死亡保護道具"),
                "S_MESSAGE_CODE death-safe-consumed=166 category=" + categoryName
                        + " object=" + carrier.objectId()
                        + " catalog=" + carrier.definition().catalogId());
        return true;
    }

    private void applyClassicWorldDeathSkillPenalty(
            int nonConsumeMask, boolean[] nonConsumeNotified) throws IOException {
        if ((nonConsumeMask & ClassicWorldDeathPenaltyCatalog.SKILL_CATEGORY) != 0) {
            sendClassicWorldDeathSafeNonConsumeOnce(nonConsumeNotified, "skill");
            return;
        }
        if (learnedSkills.isEmpty()) return;
        ClassicWorldDeathPenaltyCatalog.Rule rule =
                ClassicWorldDeathPenaltyCatalog.skillRule(playerLawful);
        if (rule.chancePercent() <= 0 || rule.maximumLoss() <= 0) return;
        int chanceFixture = config.classicWorldDeathSkillChanceFixtureRoll();
        int chanceRoll = classicDeathSkillChanceRollOverride >= 1
                ? classicDeathSkillChanceRollOverride
                : chanceFixture >= 1 ? chanceFixture
                : ThreadLocalRandom.current().nextInt(100) + 1;
        if (chanceRoll > rule.chancePercent()) return;
        int countFixture = config.classicWorldDeathSkillCountFixtureRoll();
        int countRoll = classicDeathSkillCountRollOverride >= 1
                ? Math.min(classicDeathSkillCountRollOverride, rule.maximumLoss())
                : countFixture >= 1 ? Math.min(countFixture, rule.maximumLoss())
                : ThreadLocalRandom.current().nextInt(rule.maximumLoss()) + 1;
        int count = Math.min(countRoll, learnedSkills.size());
        for (int slot = 0; slot < count; slot++) {
            if (consumeClassicWorldDeathSafe(
                    ClassicWorldDeathPenaltyCatalog.SKILL_CATEGORY, "skill")) {
                continue;
            }
            if (learnedSkills.isEmpty()) return;
            List<Integer> candidates = new ArrayList<>(learnedSkills);
            int selectorFixture = config.classicWorldDeathSkillSelectorFixtureIndex();
            int index = classicDeathSkillSelectorOverride >= 0
                    ? Math.min(classicDeathSkillSelectorOverride,
                            candidates.size() - 1)
                    : selectorFixture >= 0
                    ? Math.min(selectorFixture, candidates.size() - 1)
                    : ThreadLocalRandom.current().nextInt(candidates.size());
            int skillId = candidates.get(index);
            LinkedHashSet<Integer> nextLost = new LinkedHashSet<>(deathLostSkills);
            nextLost.add(skillId);
            state.saveDeathLostSkills(stateCharacter(), nextLost);
            LinkedHashSet<Integer> nextLearned = new LinkedHashSet<>(learnedSkills);
            nextLearned.remove(skillId);
            deathLostSkills = Set.copyOf(nextLost);
            learnedSkills = Set.copyOf(nextLearned);
            sendEncrypted(Protocol.removeSpells(Set.of(skillId)),
                    "S_REMOVE_SPELL death-penalty skill=" + skillId);
            sendEncrypted(Protocol.messageCode(166,
                            "死亡懲罰：遺失了技能 「#" + skillId + "」"),
                    "S_MESSAGE_CODE death-skill-lost=166 skill=" + skillId);
        }
        System.out.println("[LiTo] classic-world death skill penalty player="
                + playerName() + " lawful=" + playerLawful
                + " chance-roll=" + chanceRoll + "/100 threshold="
                + rule.chancePercent() + " slots=" + count);
    }

    private void applyClassicWorldDeathItemPenalty(
            int nonConsumeMask, boolean[] nonConsumeNotified) throws IOException {
        if ((nonConsumeMask & ClassicWorldDeathPenaltyCatalog.ITEM_CATEGORY) != 0) {
            sendClassicWorldDeathSafeNonConsumeOnce(nonConsumeNotified, "item");
            return;
        }
        for (RuntimeInventory.Item item : List.copyOf(inventory.items())) {
            if (ClassicWorldDeathPenaltyCatalog.control(
                    item.definition().catalogId())
                    == ClassicWorldDeathPenaltyCatalog.Control.ALWAYS_DROP
                    && classicWorldDeathItemEligible(item)) {
                if (!consumeClassicWorldDeathSafe(
                        ClassicWorldDeathPenaltyCatalog.ITEM_CATEGORY, "item")) {
                    applyClassicWorldDeathItem(item, false, "always-drop");
                }
            }
        }
        for (RuntimeInventory.Item item : List.copyOf(inventory.items())) {
            if (ClassicWorldDeathPenaltyCatalog.control(
                    item.definition().catalogId())
                    == ClassicWorldDeathPenaltyCatalog.Control.ALWAYS_VANISH
                    && classicWorldDeathItemEligible(item)) {
                if (!consumeClassicWorldDeathSafe(
                        ClassicWorldDeathPenaltyCatalog.ITEM_CATEGORY, "item")) {
                    applyClassicWorldDeathItem(item, true, "always-vanish");
                }
            }
        }

        ClassicWorldDeathPenaltyCatalog.Rule rule =
                ClassicWorldDeathPenaltyCatalog.itemRule(playerLawful);
        if (rule.chancePercent() <= 0 || rule.maximumLoss() <= 0) return;
        int chanceFixture = config.classicWorldDeathItemChanceFixtureRoll();
        int chanceRoll = classicDeathItemChanceRollOverride >= 1
                ? classicDeathItemChanceRollOverride
                : chanceFixture >= 1 ? chanceFixture
                : ThreadLocalRandom.current().nextInt(100) + 1;
        if (chanceRoll > rule.chancePercent()) return;
        int countFixture = config.classicWorldDeathItemCountFixtureRoll();
        int count = classicDeathItemCountRollOverride >= 1
                ? Math.min(classicDeathItemCountRollOverride, rule.maximumLoss())
                : countFixture >= 1 ? Math.min(countFixture, rule.maximumLoss())
                : ThreadLocalRandom.current().nextInt(rule.maximumLoss()) + 1;
        for (int slot = 0; slot < count; slot++) {
            if (consumeClassicWorldDeathSafe(
                    ClassicWorldDeathPenaltyCatalog.ITEM_CATEGORY, "item")) {
                continue;
            }
            List<RuntimeInventory.Item> candidates = inventory.items();
            if (candidates.isEmpty()) return;
            int selectorFixture = config.classicWorldDeathItemSelectorFixtureIndex();
            int index = classicDeathItemSelectorOverride >= 0
                    ? Math.min(classicDeathItemSelectorOverride,
                            candidates.size() - 1)
                    : selectorFixture >= 0
                    ? Math.min(selectorFixture, candidates.size() - 1)
                    : ThreadLocalRandom.current().nextInt(candidates.size());
            RuntimeInventory.Item selected = candidates.get(index);
            ClassicWorldDeathPenaltyCatalog.Control control =
                    ClassicWorldDeathPenaltyCatalog.control(
                            selected.definition().catalogId());
            // Retained caoPenalty selects from the whole list once. An
            // ineligible selection consumes this slot and is never rerolled.
            if (!classicWorldDeathItemEligible(selected)
                    || control == ClassicWorldDeathPenaltyCatalog.Control.NEVER_DROP
                    || control == ClassicWorldDeathPenaltyCatalog.Control.ALWAYS_VANISH) {
                continue;
            }
            applyClassicWorldDeathItem(selected,
                    control == ClassicWorldDeathPenaltyCatalog.Control.VANISH_IF_DROPPED,
                    "random-slot-" + (slot + 1));
        }
        System.out.println("[LiTo] classic-world death item penalty player="
                + playerName() + " lawful=" + playerLawful
                + " chance-roll=" + chanceRoll + "/100 threshold="
                + rule.chancePercent() + " slots=" + count);
    }

    private boolean classicWorldDeathItemEligible(RuntimeInventory.Item item) {
        if (item == null) return false;
        long itemId = item.definition().catalogId();
        return itemId != 44070 && itemId != InventoryCatalog.ADENA
                && !item.definition().cantDelete()
                && item.definition().tradable()
                && !item.timed() && !item.sealed()
                && !activePetCollar(item)
                && !activeMagicDoll(item.objectId());
    }

    private void applyClassicWorldDeathItem(
            RuntimeInventory.Item selected, boolean vanish, String reason)
            throws IOException {
        RuntimeInventory.Item current = inventory.item(selected.objectId());
        if (current == null || !classicWorldDeathItemEligible(current)) return;
        RuntimeInventory previous = inventory;
        RuntimeInventory next = previous.copy();
        RuntimeInventory.Item removed = next.removeEntireForDeath(current.objectId());
        if (removed == null) {
            throw new IOException("validated death item disappeared");
        }

        Map<Long, Long> retainedEquipmentObjects =
                new LinkedHashMap<>(sourceEquipmentObjects);
        Set<Long> consumedEquipmentObjects =
                new LinkedHashSet<>(consumedSourceEquipmentObjects);
        Long removedSourceEquipmentObject =
                retainedEquipmentObjects.remove(removed.objectId());
        SourceEquipmentEvaluation equipmentEvaluation = null;
        if (removedSourceEquipmentObject != null) {
            consumedEquipmentObjects.add(removedSourceEquipmentObject);
            CharacterSummary character = selectedCharacterSummary();
            if (character == null) {
                throw new IOException("death-dropped source equipment has no character");
            }
            try {
                equipmentEvaluation = selectedSourceAccounts().equipmentEvaluation(
                        character.objectId(), sourceEquipmentOverrides(
                                next, retainedEquipmentObjects,
                                consumedEquipmentObjects));
            } catch (Exception sourceFailure) {
                throw new IOException(
                        "cannot evaluate equipment after death item drop",
                        sourceFailure);
            }
            if (equipmentEvaluation.magic().matchedArmorRows()
                    != next.equippedSourceArmorCount()) {
                throw new IOException(
                        "death item source armor evaluation differs");
            }
        }

        Set<Long> consumedLocalSourceObjects = removed.sourceBound()
                ? Set.of(removed.objectId()) : Set.of();
        DurableCommit commit = consumedLocalSourceObjects.isEmpty()
                ? () -> state.saveEconomyState(stateCharacter(), shopPoints,
                        next.catalogCounts(), next.catalogItemStates())
                : () -> state.saveEconomyStateAndStoryQuestsConsumingSourceObjects(
                        stateCharacter(), shopPoints,
                        next.catalogCounts(), next.catalogItemStates(),
                        state.storyQuests(stateCharacter()).effective(),
                        consumedLocalSourceObjects);
        ClassicWorldGroundItems.Item ground = null;
        if (vanish) {
            commit.commit();
        } else {
            RuntimeInventory.Item detached = removed.withEquipped(false)
                    .withoutSourceBinding();
            ground = hub.putClassicWorldGroundItemPersisted(
                    classicWorldMapId, classicWorldInstanceId,
                    detached, detached.quantity(), positionX, positionY,
                    Math.toIntExact(playerObjectId()), commit);
            if (ground == null) {
                throw new IOException("death item ground handoff failed");
            }
        }

        inventory = next;
        sourceEquipmentObjects = Map.copyOf(retainedEquipmentObjects);
        consumedSourceEquipmentObjects = Set.copyOf(consumedEquipmentObjects);
        if (equipmentEvaluation != null) {
            sourceEquipmentMagicStats = equipmentEvaluation.magic();
            sourceEquipmentVitalStats = equipmentEvaluation.vital();
            sourceEquippedFireResistance = new SourceEquippedFireResistance(
                    NumericBreakthrough.clampElementalResistance(
                            sourceEquipmentMagicStats.totalFireResistance()),
                    sourceEquipmentMagicStats.matchedArmorRows());
        }
        if (removed.sourceBound()) {
            Map<Long, Long> projectiles = new LinkedHashMap<>(sourceProjectileObjects);
            projectiles.entrySet().removeIf(
                    entry -> entry.getValue() == removed.objectId());
            sourceProjectileObjects = Map.copyOf(projectiles);
        }
        if (removed.equipped()) {
            sendInventoryEquipmentState(removed.withEquipped(false),
                    "classic-world-death-drop");
        }
        sendInventoryDelta(previous, inventory, false);
        sendEncrypted(Protocol.messageCode(638, removed.nativeLogName()),
                "S_MESSAGE_CODE death-item=" + (vanish ? "vanished" : "dropped")
                        + " catalog=" + removed.definition().catalogId());
        if (ground != null) {
            broadcastClassicWorldGroundItem(ground,
                    "player-death-" + reason);
        }
        if (removed.equipped() && removed.definition().weapon()) {
            sourceWeaponSuppressed = removed.sourceBound();
            broadcastWieldState();
        }
        if (removed.equipped()) {
            sendNativeBattleStatus(System.nanoTime(),
                    "classic-world-death-item");
        }
    }

    private void takeClassicWorldPlayerDamage(
            int damage, ClientSession attacker) throws IOException {
        takeClassicWorldPlayerDamage(damage, attacker, true, false);
    }

    private void takeClassicWorldPlayerDamage(
            int damage, ClientSession attacker, boolean earthBindBlocks)
            throws IOException {
        takeClassicWorldPlayerDamage(damage, attacker, earthBindBlocks, false);
    }

    private void takeClassicWorldPlayerDamage(
            int damage, ClientSession attacker, boolean earthBindBlocks,
            boolean suppressCombatFeedback)
            throws IOException {
        if (phase != Phase.WORLD || playerHp <= 0 || damage <= 0
                || attacker == null || !sameClassicWorldMap(attacker)) return;
        if (earthBindBlocks) {
            damage = earthBindProtectedCombatDamage(
                    damage, "classic-world-player-" + attacker.playerName());
            if (damage <= 0) return;
        }
        BattleJoyOfPainStatus.Lease joyLease = !suppressCombatFeedback
                && attacker != this ? attacker.joyOfPainStatus.capture(
                        System.nanoTime()) : null;
        int joyDamage = joyLease == null ? 0 : BattleJoyOfPain.feedbackDamage(
                playerMaxHp, playerHp, joyOfPainEquipmentAddedHp());
        int before = playerHp;
        lastAttacker = attacker;
        ClassicWorldFatalContext fatalContext = takeClassicWorldMonsterDamage(
                damage, attacker.playerObjectId());
        if (playerHp >= before) return;
        applyClassicWorldPlayerLiability(attacker, fatalContext);
        if (!suppressCombatFeedback && attacker.playerHp > 0) {
            tryMortalBodyPlayerReflection(attacker,
                    "classic-world-accepted-player-damage");
        }
        applyJoyOfPainPlayerFeedback(attacker, joyLease, joyDamage,
                "classic-world-accepted-player-damage");
    }

    /**
     * Retained pet/summon receiveDamage path. The attacking object remains the
     * companion through Death so war/death attribution can resolve its master,
     * while PK liability and pink-name state are applied to that master.
     */
    private void takeClassicWorldCompanionDamage(
            int damage, ClientSession attacker, BattleCompanion companion)
            throws IOException {
        if (phase != Phase.WORLD || playerHp <= 0 || damage <= 0
                || attacker == null || attacker == this || companion == null
                || !sameClassicWorldMap(attacker)) return;
        BattleCompanion.Snapshot source = companion.snapshot();
        if (!source.active() || !source.kind().classicWorldEligible()) return;
        int before = playerHp;
        lastAttacker = attacker;
        ClassicWorldFatalContext fatalContext = takeClassicWorldMonsterDamage(
                damage, source.objectId());
        if (playerHp >= before) return;
        applyClassicWorldPlayerLiability(attacker, fatalContext);
    }

    /** Shared retained player liability after direct, pet, or summon damage. */
    private void applyClassicWorldPlayerLiability(
            ClientSession attacker, ClassicWorldFatalContext fatalContext)
            throws IOException {
        boolean fatalPkExempt = playerHp == 0
                && (fatalContext.clanWarPkExempt()
                    || classicWorldPlayerKillPkExempt(attacker));
        boolean nativePk = playerHp == 0
                && !fatalPkExempt
                && attacker.classicWorldPinkNameEligible(
                        this, ClassicWorldMapCatalog.forMap(classicWorldMapId));
        if (nativePk) {
            boolean incrementPkCount = attacker.playerLawful < 30_000;
            GameStateStore.GeneralPkState recorded =
                    attacker.state.recordGeneralPkKill(
                            attacker.stateCharacter(),
                            incrementPkCount);
            attacker.generalPkCount = recorded.count();
            attacker.lastPkEpochSeconds = recorded.lastPkEpochSeconds();
            attacker.applyGeneralPkLawfulPenalty();
            System.out.println("[LiTo] native general-PK recorded attacker="
                    + attacker.playerName() + " victim=" + playerName()
                    + " count=" + attacker.generalPkCount
                    + " wanted-seconds=" + ClassicWorldGuardCatalog.WANTED_SECONDS);

            if (attacker.isElfCharacter() && isElfCharacter()) {
                GameStateStore.ElfPkState elfRecorded =
                        attacker.state.recordElfPkKill(
                                attacker.stateCharacter(),
                                incrementPkCount);
                attacker.elfPkCount = elfRecorded.count();
                attacker.lastPkForElfEpochSeconds =
                        elfRecorded.lastPkEpochSeconds();
                System.out.println("[LiTo] native elf-PK recorded attacker="
                        + attacker.playerName() + " victim=" + playerName()
                        + " count=" + attacker.elfPkCount
                        + " wanted-seconds="
                        + ClassicWorldGuardianCatalog.WANTED_SECONDS);
            }
            if (incrementPkCount && attacker.generalPkCount >= 5
                    && attacker.generalPkCount < ClassicWorldHell.PK_THRESHOLD) {
                attacker.sendEncrypted(Protocol.messageCode(551,
                                Integer.toString(attacker.generalPkCount),
                                Integer.toString(ClassicWorldHell.PK_THRESHOLD)),
                        "S_MESSAGE_CODE Hell-warning=551 pk="
                                + attacker.generalPkCount + " threshold="
                                + ClassicWorldHell.PK_THRESHOLD);
            } else if (incrementPkCount
                    && attacker.generalPkCount >= ClassicWorldHell.PK_THRESHOLD) {
                attacker.beginClassicWorldHell(true);
            }
        }
        attacker.publishClassicWorldPinkName(this);
    }

    private ClientSession classicWorldPlayerAttacker(long attackerObjectId) {
        if (attackerObjectId == playerObjectId()) return null;
        List<ClientSession> members = classicWorldMembers(classicWorldMapId);
        ClientSession direct = members.stream()
                .filter(member -> member != this
                        && member.playerObjectId() == attackerObjectId
                        && sameClassicWorldMap(member))
                .findFirst().orElse(null);
        if (direct != null) return direct;
        return members.stream()
                .filter(member -> member != this && sameClassicWorldMap(member))
                .filter(member -> member.classicWorldCompanionSnapshots().stream()
                        .anyMatch(companion -> companion.active()
                                && companion.objectId() == attackerObjectId))
                .findFirst().orElse(null);
    }

    /** Retained Death post-penalty exemptions; pink-name action is independent. */
    private boolean classicWorldPlayerKillPkExempt(ClientSession attacker) {
        if (attacker == null) return false;
        if (ClassicWorldDeathContext.encounterProtects(
                battleLevel(), attacker.battleLevel())) {
            return true;
        }
        if (ClassicWorldDeathContext.castleAreaSuppressesPk(
                classicWorldMapId, positionX, positionY)) {
            return true;
        }
        return hub.classicClanWarActiveBetween(
                sourceCharacterIdentity(), attacker.sourceCharacterIdentity());
    }

    /**
     * A retained poison lease keeps damaging after its caster leaves the map;
     * pink-name publication still requires both players to share this WORLD.
     */
    private void takeClassicWorldPlayerPoisonDamage(
            int damage, ClientSession attacker) throws IOException {
        if (phase != Phase.WORLD || playerHp <= 0 || damage <= 0
                || attacker == null) return;
        int before = playerHp;
        lastAttacker = attacker;
        takeClassicWorldMonsterDamage(damage, attacker.playerObjectId());
        if (playerHp < before && sameClassicWorldMap(attacker)) {
            attacker.publishClassicWorldPinkName(this);
        }
    }

    private boolean classicWorldPinkNameEligible(
            ClientSession target, ClassicWorldMapCatalog.ClassicMap map) {
        if (target == null || target == this || !sameClassicWorldMap(target)) {
            return false;
        }
        int castleId = ClassicWorldCastleWarField.castleIdAt(
                target.classicWorldMapId, target.positionX, target.positionY);
        return (castleId == 0 || !hub.classicCastleWarActive(
                        target.selectedClassicServerName, castleId))
                && map.isNormalZone(positionX, positionY)
                && map.isNormalZone(target.positionX, target.positionY)
                && target.playerLawful >= 0
                && !target.classicWorldPinkName.active();
    }

    /** Exact retained player-kill lawful formula from L1PcInstance.Death. */
    private void applyGeneralPkLawfulPenalty() throws IOException {
        int level = Math.max(1, battleLevel());
        int calculated = level < 50
                ? -Math.multiplyExact(Math.multiplyExact(level, level), 4)
                : -(int) (Math.pow(level, 3) * 0.08D);
        int target = Math.max(Short.MIN_VALUE,
                Math.min(calculated, playerLawful - 1_000));
        GameStateStore.LawfulMutation mutation = state.addLawful(
                stateCharacter(), selectedCharacterSummary() == null ? 0
                        : nativeLawful(selectedCharacterSummary().lawful()),
                target - playerLawful);
        playerLawful = mutation.after();
        if (!mutation.changed()) return;
        byte[] packet = Protocol.changeAlignment(playerObjectId(), playerLawful);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY)) continue;
            member.sendEncrypted(packet,
                    "S_CHANGE_ALIGNMENT native-general-PK player=" + playerName()
                            + " level=" + level + " calculated=" + calculated
                            + " lawful=" + mutation.before() + "->"
                            + mutation.after());
        }
    }

    private void publishClassicWorldPinkName(ClientSession target)
            throws IOException {
        if (phase != Phase.WORLD || target == null
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) return;
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        if (!classicWorldPinkNameEligible(target, map)) return;

        // Retained publishPinkNameActive sends the 180 packet on every eligible
        // accepted hit, even while the attacker's original timer is still active.
        byte[] activePacket = Protocol.criminalStatus(
                playerObjectId(), ClassicWorldPinkNameStatus.WIRE_SECONDS);
        publishClassicWorldCriminalPacket(activePacket,
                "active target=" + target.playerName());
        ClassicWorldPinkNameStatus.Publication publication =
                classicWorldPinkName.publishActive(
                        classicWorldMapId, classicWorldInstanceId,
                        positionX, positionY, System.nanoTime());
        System.out.println("[LiTo] classic-world pink-name active attacker="
                + playerName() + " target=" + target.playerName()
                + " started=" + publication.started() + " generation="
                + publication.snapshot().generation() + " origin="
                + publication.snapshot().originX() + ","
                + publication.snapshot().originY() + " wire-seconds="
                + ClassicWorldPinkNameStatus.WIRE_SECONDS);
    }

    private void publishClassicWorldCriminalPacket(byte[] packet, String reason)
            throws IOException {
        List<ClientSession> recipients = phase == Phase.WORLD
                && ClassicWorldMapCatalog.supports(classicWorldMapId)
                ? classicWorldMembers(classicWorldMapId) : List.of(this);
        IOException first = null;
        for (ClientSession member : recipients) {
            if (member != this && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) continue;
            try {
                member.sendEncrypted(packet,
                        "S_CRIMINAL classic-world player=" + playerObjectId()
                                + " " + reason);
            } catch (IOException failure) {
                if (first == null) first = failure;
            }
        }
        if (first != null) throw first;
    }

    private void expireClassicWorldPinkName(long nowNanos) throws IOException {
        boolean inClassicWorld = phase == Phase.WORLD
                && ClassicWorldMapCatalog.supports(classicWorldMapId);
        ClassicWorldPinkNameStatus.Expiration expiration =
                classicWorldPinkName.expire(
                        inClassicWorld, playerHp > 0,
                        classicWorldMapId, classicWorldInstanceId,
                        positionX, positionY, nowNanos);
        if (!expiration.cleared()) return;
        publishClassicWorldCriminalPacket(
                Protocol.criminalStatus(playerObjectId(), 0),
                "clear reason=" + expiration.reason());
        System.out.println("[LiTo] classic-world pink-name cleared player="
                + playerName() + " generation="
                + expiration.previous().generation() + " reason="
                + expiration.reason());
    }

    private void takePlayerDamage(int damage, ClientSession attacker,
                                  boolean earthBindBlocks) throws IOException {
        takePlayerDamage(damage, attacker, earthBindBlocks, false);
    }

    private void takePlayerDamage(int damage, ClientSession attacker,
                                  boolean earthBindBlocks,
                                  boolean suppressCombatFeedback) throws IOException {
        takePlayerDamage(damage, attacker, earthBindBlocks,
                suppressCombatFeedback, 0);
    }

    private void takePlayerDamage(int damage, ClientSession attacker,
                                  boolean earthBindBlocks,
                                  boolean suppressCombatFeedback,
                                  long terminalEffectMillis) throws IOException {
        if (phase != Phase.BATTLE || playerHp <= 0 || damage <= 0) return;
        if (earthBindBlocks) {
            damage = earthBindProtectedCombatDamage(damage,
                    attacker == null ? "server-actor" : attacker.playerName());
            if (damage <= 0) return;
        }
        damage = nativeMagicDollDamageAfterActiveReduction(
                damage, !suppressCombatFeedback, "battle");
        if (damage <= 0) return;
        damage = abilityStatus.illusionAvatar(System.nanoTime())
                .applyIncomingDamage(damage);
        BattleJoyOfPainStatus.Lease joyLease = !suppressCombatFeedback
                && attacker != null && attacker != this
                ? attacker.joyOfPainStatus.capture(System.nanoTime()) : null;
        int joyDamage = joyLease == null ? 0 : BattleJoyOfPain.feedbackDamage(
                playerMaxHp, playerHp, joyOfPainEquipmentAddedHp());
        markBattleCombatWith(attacker);
        lastAttacker = attacker;
        playerHp = Math.max(0, playerHp - damage);
        if (playerHp == 0 && terminalEffectMillis > 0) {
            terminalEffectResultNotBeforeNanos = Math.max(
                    terminalEffectResultNotBeforeNanos,
                    System.nanoTime() + terminalEffectMillis * 1_000_000L);
        }
        cancelSleep(playerHp == 0 ? "accepted-fatal-damage" : "accepted-damage");
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(playerHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT player=" + playerHp + "/" + playerMaxHp);
        broadcastOwnHitRatio(playerHp == 0 ? "player-death" : "player-damage");
        if (playerHp == 0) {
            hub.cancelArmorBreak(currentRoomId, playerObjectId());
            hub.cancelPatience(currentRoomId, playerObjectId());
            timedStatus.clearWaterDragonAffliction();
            dragonSkinStatus.clear();
            if (awakenStatus.clear().active()) {
                polymorphStatus.clear();
                rebuildMaximumVitals(System.nanoTime());
            }
            burningSlashStatus.clear();
            guardBrakeStatus.clear();
            armBreakerStatus.clear();
            joyOfPainStatus.clear();
            resistFearStatus.clear();
            state.saveTimedResistFearBuff(
                    stateCharacter(), GameStateStore.TimedResistFearBuff.none());
            cancelParalysis("player-death");
            cancelFreeze("player-death");
            cancelEarthBind("player-death");
            cancelShockStun("player-death");
            cancelThunderGrab("player-death");
        }
        revealInvisibility(playerHp == 0 ? "accepted-fatal-damage" : "accepted-damage");
        if (playerHp == 0) {
            deathConfirmationPending = true;
            byte[] death = new Protocol.Writer().c(Protocol.S_ACTION).d(playerObjectId())
                    .c(BattleActionCodes.DIE).bytes();
            for (ClientSession member : hub.roomMembers(currentRoomId)) {
                member.sendEncrypted(death, "S_ACTION player death object=" + playerObjectId());
            }
            sendEncrypted(new Protocol.Writer().c(Protocol.S_LITO_CONFIRM_DEATH).bytes(),
                    "S_LITO_CONFIRM_DEATH required");
        }
        if (!suppressCombatFeedback && attacker != null && attacker != this
                && attacker.playerHp > 0) {
            tryMortalBodyPlayerReflection(attacker,
                    "battle-accepted-player-damage");
        }
        applyJoyOfPainPlayerFeedback(attacker, joyLease, joyDamage,
                "battle-accepted-player-damage");
    }

    private int earthBindProtectedCombatDamage(int damage, String source) {
        long nowNanos = System.nanoTime();
        boolean barrierActive = timedStatus.absoluteBarrierActive(nowNanos);
        int barrierProtectedDamage = BattleAbsoluteBarrierRules.protectedCombatDamage(
                barrierActive, damage);
        if (barrierActive && damage > 0) {
            System.out.println("[LiTo] player combat damage blocked by Absolute Barrier target="
                    + playerName() + " damage=" + damage + " source=" + source);
            return barrierProtectedDamage;
        }
        boolean active = timedStatus.earthBindActive(nowNanos);
        int protectedDamage = BattleEarthBindRules.protectedCombatDamage(
                active, barrierProtectedDamage);
        if (!active || damage <= 0) {
            return protectedDamage;
        }
        System.out.println("[LiTo] player combat damage blocked by Earth Bind target="
                + playerName() + " damage=" + damage + " source=" + source);
        return protectedDamage;
    }

    private boolean earthBindBlocksProbabilityMagic(
            ClientSession playerTarget,
            BattleQuestEncounter.Snapshot questTarget,
            BattleTimeAttackEncounter.Snapshot timeTarget,
            long nowNanos, int skillId) {
        boolean barrierBlocked = playerTarget != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                        playerTarget.timedStatus.absoluteBarrierActive(nowNanos),
                        skillId);
        boolean active = playerTarget != null
                ? playerTarget.timedStatus.earthBindActive(nowNanos)
                : questTarget != null
                    ? hub.questMonsterEarthBindActive(
                            currentRoomId, questTarget.objectId(), nowNanos)
                    : timeTarget != null && hub.timeAttackActorEarthBindActive(
                            currentRoomId, timeTarget.objectId(), nowNanos);
        return barrierBlocked
                || BattleEarthBindRules.blocksProbabilityMagic(active, skillId);
    }

    /** Must be called after probability calculation and before Counter Magic. */
    private int effectiveNpcMagicResistance(
            BattleQuestEncounter.Snapshot questTarget,
            BattleTimeAttackEncounter.Snapshot timeTarget,
            int baseMagicResistance, long nowNanos) {
        return questTarget != null
                ? hub.questMonsterEffectiveMagicResistance(
                        currentRoomId, questTarget.objectId(),
                        baseMagicResistance, nowNanos)
                : timeTarget != null
                    ? hub.timeAttackActorEffectiveMagicResistance(
                            currentRoomId, timeTarget.objectId(),
                            baseMagicResistance, nowNanos)
                    : baseMagicResistance;
    }

    private int effectiveNpcMagicResistance(
            ClassicWorldMonsterPopulation.Snapshot worldTarget,
            BattleQuestEncounter.Snapshot questTarget,
            BattleTimeAttackEncounter.Snapshot timeTarget,
            int baseMagicResistance, long nowNanos) {
        return worldTarget != null
                ? hub.classicWorldMonsterEffectiveMagicResistance(
                        classicWorldMapId, classicWorldInstanceId,
                        worldTarget.objectId(), baseMagicResistance, nowNanos)
                : effectiveNpcMagicResistance(
                        questTarget, timeTarget, baseMagicResistance, nowNanos);
    }

    /** Must be called after probability calculation and before Counter Magic. */
    private void consumeEraseMagicAfterProbability(
            ClientSession playerTarget,
            BattleQuestEncounter.Snapshot questTarget,
            BattleTimeAttackEncounter.Snapshot timeTarget,
            long nowNanos, int skillId) {
        if (skillId == BattleSpellCatalog.ERASE_MAGIC) return;
        if (playerTarget != null) {
            playerTarget.eraseMagicStatus.consume(nowNanos);
        } else if (questTarget != null) {
            hub.consumeQuestMonsterEraseMagic(
                    currentRoomId, questTarget.objectId(), nowNanos);
        } else if (timeTarget != null) {
            hub.consumeTimeAttackActorEraseMagic(
                    currentRoomId, timeTarget.objectId(), nowNanos);
        }
    }

    /** Variant for the ordinary world where the NPC target is population-owned. */
    private void consumeEraseMagicAfterProbability(
            ClientSession playerTarget,
            ClassicWorldMonsterPopulation.Snapshot worldTarget,
            BattleQuestEncounter.Snapshot questTarget,
            BattleTimeAttackEncounter.Snapshot timeTarget,
            long nowNanos, int skillId) {
        consumeEraseMagicAfterProbability(
                playerTarget, questTarget, timeTarget, nowNanos, skillId);
        if (skillId != BattleSpellCatalog.ERASE_MAGIC
                && playerTarget == null && worldTarget != null) {
            hub.consumeClassicWorldMonsterEraseMagic(
                    classicWorldMapId, classicWorldInstanceId,
                    worldTarget.objectId(), nowNanos);
        }
    }

    private boolean absoluteBarrierBlocksSpellTarget(
            byte[] payload, int skillId, long nowNanos) {
        if (!BattleAbsoluteBarrierRules.blocksIncomingSpell(true, skillId)) return false;
        // Skill 116 carries a CP950 name, not an object dword.  Its retained
        // mode publishes a question capability and never applies an incoming
        // effect at cast time, so it must not enter the object-tail decoder.
        if (BattleSpellCatalog.callClanSpell(skillId) != null
                || BattleSpellCatalog.runClanSpell(skillId) != null) return false;
        long targetObjectId;
        try {
            if (payload.length == 11) {
                targetObjectId = Protocol.attackSpellRequest(payload).targetObjectId();
            } else if (payload.length == 7
                    && BattleSpellCatalog.groundSpell(skillId) == null) {
                targetObjectId = Protocol.objectSpellRequest(payload).targetObjectId();
            } else {
                return false;
            }
        } catch (IllegalArgumentException malformed) {
            return false;
        }
        List<ClientSession> candidates = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomCombatants(currentRoomId);
        ClientSession target = candidates.stream()
                .filter(candidate -> (phase != Phase.WORLD
                            || sameClassicWorldMap(candidate))
                        && candidate.playerObjectId() == targetObjectId)
                .findFirst().orElse(null);
        boolean blocked = target != null
                && target.timedStatus.absoluteBarrierActive(nowNanos);
        if (blocked) {
            System.out.println("[LiTo] C_USE_SPELL rejected by Absolute Barrier caster="
                    + playerName() + " target=" + target.playerName()
                    + " skill=" + skillId);
        }
        return blocked;
    }

    private int npcEarthBindProtectedCombatDamage(
            int damage, long questObjectId, long timeAttackObjectId,
            long nowNanos, String source) {
        boolean active = questObjectId > 0
                ? hub.questMonsterEarthBindActive(
                        currentRoomId, questObjectId, nowNanos)
                : timeAttackObjectId > 0 && hub.timeAttackActorEarthBindActive(
                        currentRoomId, timeAttackObjectId, nowNanos);
        int protectedDamage = BattleEarthBindRules.protectedCombatDamage(active, damage);
        if (active && damage > 0) {
            long objectId = questObjectId > 0 ? questObjectId : timeAttackObjectId;
            System.out.println("[LiTo] NPC combat damage blocked by Earth Bind target="
                    + objectId + " damage=" + damage + " source=" + source);
        }
        return protectedDamage;
    }

    /**
     * An accepted positive hit ends the exact invisibility lease captured by
     * the target. The owner receives S_INVISIBLE mode 0; every other room
     * client receives a fresh authoritative actor, matching classic
     * S_OtherCharPacks rather than trying to mutate an object that was removed.
     */
    private void revealInvisibility(String reason) throws IOException {
        if (!cancelInvisibilityState()) return;
        publishInvisibilityReveal(reason);
    }

    /**
     * The retained normal-cast order commits resources first, then breaks
     * invisibility before cast motion/effect packets. Every recovered spell
     * writes its reuse clock at that admission boundary, including zero-delay
     * spells, so this is the common fail-closed commit point.
     */
    private void commitSpellReady(int skillId, long readyAtNanos)
            throws IOException {
        spellReadyNanos.put(skillId, readyAtNanos);
        if (BattleSpellCatalog.invisibilitySpell(skillId) == null) {
            revealInvisibility("spell-" + skillId);
        }
    }

    private synchronized void activateInvisibilityState(
            int skillId, long nowNanos, int durationSeconds) {
        invisibilityStatus.activate(skillId, nowNanos, durationSeconds);
        invisible = true;
    }

    private synchronized boolean cancelInvisibilityState() {
        boolean active = invisibilityStatus.cancel();
        if (!invisible && !active) return false;
        invisible = false;
        return true;
    }

    private synchronized void clearInvisibilityStateSilently() {
        invisibilityStatus.cancel();
        invisible = false;
    }

    private synchronized int expireInvisibilityState(long nowNanos) {
        int skillId = invisibilityStatus.expire(nowNanos);
        if (skillId != 0) invisible = false;
        return skillId;
    }

    private void publishInvisibilityReveal(String reason) throws IOException {
        sendEncrypted(Protocol.invisible(playerObjectId(), 0),
                "S_INVISIBLE object=" + playerObjectId() + " mode=0 reason=" + reason);
        long nowNanos = System.nanoTime();
        int palette = currentPoisonPalette(nowNanos);
        GameHub.ClanData clan = hub.clanData(sourceCharacterIdentity());
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession recipient : recipients) {
            if (recipient == this) continue;
            if (phase == Phase.WORLD && !BattleSpellCatalog.isInNativeScreen(
                    recipient.positionX, recipient.positionY, positionX, positionY)) {
                continue;
            }
            recipient.sendBattleObject(playerObjectId(), litoDisplayName(), sourceCharacterIdentity(),
                    positionX, positionY, battleGfx(), battleWalkAction(),
                    battleLightRange(), battleMoveSpeed(), 4, battleLevel(),
                    nativeLawful(characterLawful()), classicTitle, battleHpRatio());
            if (!clan.name().isBlank()) {
                recipient.sendEncrypted(Protocol.battleClanMetadata(
                                playerObjectId(), 0, clan.name(), true),
                        "S_LITO_CLAN reveal object=" + playerObjectId()
                                + " clan=" + clan.name());
            }
            if (palette != 0) {
                recipient.sendEncrypted(Protocol.poison(playerObjectId(), palette),
                        "S_POISON object=" + playerObjectId()
                                + " type=" + palette
                                + " reason=invisibility-reveal-rebuild");
            }
        }
    }

    /**
     * Advances the native anicom target selected through S_57/C_4F.
     *
     * <p>Sprite 936's imported action rows are 14 frames for action 0 and
     * 24 frames for action 1 at 24 fps. The classic interval calculation is
     * therefore 560 ms per tile and 960 ms per physical strike. Movement
     * sends the source tile because LiTo's S_12 receiver applies the heading
     * itself before committing the destination.</p>
     */
    void serverClassicWorldCompanionTick(int mapId, long nowNanos) throws IOException {
        if (phase != Phase.WORLD || observer || classicWorldMapId != mapId) return;
        serverClassicWorldRescueFollowerTick(mapId, nowNanos);
        serverClassicWorldDspyFollowerTick(mapId, nowNanos);
        serverClassicWorldRoiFollowerTick(mapId, nowNanos);
        for (BattleCompanion.Snapshot snapshot : classicWorldCompanionSnapshots()) {
            BattleCompanion controlled = ownedCompanion(snapshot.objectId());
            if (controlled == null || !snapshot.active()) continue;
            if (controlled.expired(nowNanos)) {
                removeClassicWorldCompanion(controlled, snapshot, "expired", true);
                continue;
            }
            serverClassicWorldCompanionTick(controlled, mapId, nowNanos);
        }
    }

    private void serverClassicWorldDspyFollowerTick(
            int mapId, long nowNanos) throws IOException {
        if (mapId != ClassicWorldDspyCatalog.MAP_ID) return;
        for (ClassicWorldDspyEscorts.Snapshot corpse
                : hub.classicWorldDspyEscorts().expireCorpses(nowNanos)) {
            broadcastClassicWorldDspyReplacement(
                    corpse, null, "death-delete-10s");
            hub.clearClassicWorldMonsterTargets(corpse.objectId());
        }

        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(mapId);
        ClassicWorldDspyEscorts.Cycle cycle =
                hub.classicWorldDspyEscorts().cycle(
                        sourceCharacterIdentity(), mapId,
                        positionX, positionY, playerHp > 0, nowNanos,
                        (fromX, fromY, toX, toY, movingObjectId) ->
                                map.canStep(fromX, fromY, toX, toY)
                                        && !ClassicWorldNpcCatalog.occupies(
                                            mapId, toX, toY),
                        map::standingPassable);
        if (cycle.assassin() != null) {
            spawnClassicWorldDspyAssassin(cycle.assassin());
        }
        ClassicWorldDspyEscorts.Transition transition = cycle.transition();
        switch (transition.kind()) {
            case NONE -> { }
            case MOVED -> broadcastClassicWorldDspyMovement(
                    transition.before(), transition.after());
            case ABANDONED -> {
                broadcastClassicWorldDspyReplacement(
                        transition.before(), transition.after(), "owner-lost");
                System.out.println("[LiTo] Dspy follower abandoned owner="
                        + playerName() + " old=" + transition.before().objectId()
                        + " free=" + transition.after().objectId()
                        + " x=" + transition.after().x()
                        + " y=" + transition.after().y());
            }
            case ARRIVED -> completeClassicWorldDspyArrival(transition.before());
            case DEAD_REMOVED -> broadcastClassicWorldDspyReplacement(
                    transition.before(), null, "dead-owner-lost");
        }
    }

    private void spawnClassicWorldDspyAssassin(
            ClassicWorldDspyEscorts.AssassinSpawn request) throws IOException {
        byte[] effect = Protocol.effectLocation(
                request.x(), request.y(),
                ClassicWorldDspyCatalog.ASSASSIN_APPEARANCE_GFX);
        List<ClientSession> members = classicWorldMembers(request.mapId());
        for (ClientSession member : members) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY,
                    request.x(), request.y())) continue;
            member.sendEncrypted(effect,
                    "S_EFFECT Dspy-assassin x=" + request.x()
                            + " y=" + request.y() + " gfx="
                            + ClassicWorldDspyCatalog.ASSASSIN_APPEARANCE_GFX
                            + " linked=" + request.linkedObjectId());
        }
        ClassicWorldMonsterPopulation.Snapshot spawned =
                hub.spawnClassicWorldDspyAssassin(request);
        if (spawned != null) {
            for (ClientSession member : members) {
                member.serverClassicWorldMonsterSpawned(spawned);
            }
        }
        System.out.println("[LiTo] Dspy assassin roll accepted owner="
                + playerName() + " linked=" + request.linkedObjectId()
                + " location=" + request.x() + "," + request.y()
                + " spawned=" + (spawned == null ? 0 : spawned.objectId()));
    }

