    private void completeClassicWorldDspyArrival(
            ClassicWorldDspyEscorts.Snapshot removed) throws IOException {
        ClassicWorldStoryQuestCatalog.Event event =
                ClassicWorldStoryQuestCatalog.all().stream()
                        .filter(candidate -> candidate.id()
                                == ClassicWorldDspyCatalog.COMPLETION_EVENT_ID)
                        .findFirst().orElseThrow(() -> new IOException(
                                "Dspy completion story event is unavailable id="
                                + ClassicWorldDspyCatalog.COMPLETION_EVENT_ID));
        if (event.questId() != ClassicWorldDspyCatalog.QUEST_ID
                || event.npcId() != ClassicWorldDspyCatalog.DSPY_NPC_ID
                || !"start".equalsIgnoreCase(event.action())
                || event.givenItems().size() != 1
                || event.givenItems().get(0).itemId()
                    != ClassicWorldDspyCatalog.REWARD_ITEM_ID
                || event.givenItems().get(0).count() != 1) {
            hub.classicWorldDspyEscorts().restoreAfterFailedArrival(removed);
            throw new IOException("Dspy completion event diverged id=" + event.id());
        }

        InventoryCatalog.Definition reward = InventoryCatalog.find(
                ClassicWorldDspyCatalog.REWARD_ITEM_ID);
        if (reward == null) {
            hub.classicWorldDspyEscorts().restoreAfterFailedArrival(removed);
            throw new IOException("Dspy reward is unavailable item="
                    + ClassicWorldDspyCatalog.REWARD_ITEM_ID);
        }
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        boolean alreadyHadReward = inventory.catalogCounts().getOrDefault(
                ClassicWorldDspyCatalog.REWARD_ITEM_ID, 0) > 0;
        boolean rewardStored = !alreadyHadReward
                && permitsInventoryAddition(inventory, reward, 1)
                && next.add(reward, 1);
        if (!rewardStored) next = inventory.copy();
        Map<Integer, Integer> nextQuests =
                ClassicWorldStoryQuestCatalog.applyQuestMutation(
                        event, state.storyQuests(stateCharacter()).effective());
        try {
            state.saveEconomyStateAndStoryQuests(
                    stateCharacter(), shopPoints, next.catalogCounts(),
                    next.catalogItemStates(), nextQuests);
            inventory = next;
        } catch (IOException | RuntimeException failure) {
            hub.classicWorldDspyEscorts().restoreAfterFailedArrival(removed);
            throw failure;
        }

        if (rewardStored) {
            sendInventoryDelta(previous, inventory);
        } else if (!alreadyHadReward) {
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    classicWorldMapId, classicWorldInstanceId, reward, 1,
                    positionX, positionY, ClassicWorldDspyCatalog.DSPY_NPC_ID);
            if (ground == null) {
                throw new IOException("Dspy reward ground handoff failed item="
                        + ClassicWorldDspyCatalog.REWARD_ITEM_ID);
            }
            broadcastClassicWorldGroundItem(ground,
                    "Dspy-completion-overflow");
        }
        broadcastClassicWorldDspyReplacement(
                removed, null, "quest-complete");
        hub.clearClassicWorldMonsterTargets(removed.objectId());
        System.out.println("[LiTo] Dspy quest complete player=" + playerName()
                + " quest=" + ClassicWorldDspyCatalog.QUEST_ID
                + " follower=" + removed.objectId() + " reward="
                + ClassicWorldDspyCatalog.REWARD_ITEM_ID
                + " stored=" + rewardStored
                + " already-owned=" + alreadyHadReward
                + " next-quests=" + nextQuests);
    }

    private void serverClassicWorldRescueFollowerTick(
            int mapId, long nowNanos) throws IOException {
        if (mapId != ClassicWorldRescueFollowers.MAP_ID) return;
        if (completeClassicWorldRescueFollowerIfReady()) return;
        ClassicWorldMapCatalog.ClassicMap map = ClassicWorldMapCatalog.forMap(mapId);
        ClassicWorldRescueFollowers.Transition transition =
                hub.classicWorldRescueFollowers().tick(
                        sourceCharacterIdentity(), mapId, positionX, positionY,
                        playerHp > 0, nowNanos,
                        (fromX, fromY, toX, toY, movingObjectId) ->
                                map.canStep(fromX, fromY, toX, toY)
                                        && !ClassicWorldNpcCatalog.occupies(
                                            mapId, toX, toY));
        if (transition.kind()
                == ClassicWorldRescueFollowers.TransitionKind.MOVED) {
            broadcastClassicWorldRescueMovement(
                    transition.before(), transition.after());
            completeClassicWorldRescueFollowerIfReady();
        } else if (transition.kind()
                == ClassicWorldRescueFollowers.TransitionKind.ABANDONED) {
            broadcastClassicWorldRescueReplacement(
                    transition.before(), transition.after(), "owner-lost");
            System.out.println("[LiTo] rescue follower abandoned owner="
                    + playerName() + " kind="
                    + transition.before().definition().kind()
                    + " old=" + transition.before().objectId()
                    + " free=" + transition.after().objectId()
                    + " x=" + transition.after().x()
                    + " y=" + transition.after().y());
        }
    }

