    private boolean completeClassicWorldRoiFollowerIfReady() throws IOException {
        ClassicWorldNpcCatalog.StaticNpc basch = ClassicWorldNpcCatalog
                .all(ClassicWorldRoiFollowers.MAP_ID).stream()
                .filter(ClassicWorldDemonTempleCatalog::isBasch)
                .findFirst().orElseThrow(() ->
                        new IOException("retained Basch spawn is unavailable"));
        ClassicWorldRoiFollowers.Snapshot removed = hub.classicWorldRoiFollowers()
                .completeIfNear(sourceCharacterIdentity(), positionX, positionY,
                        basch.x(), basch.y());
        if (removed == null) return false;

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        boolean weightAllowed;
        boolean rewardAdded;
        try {
            GameStateStore.StoryQuestState current = state.storyQuests(stateCharacter());
            InventoryCatalog.Definition reward = InventoryCatalog.find(
                    InventoryCatalog.ROI_POUCH);
            if (reward == null) throw new IOException("Roi pouch 41003 is unavailable");
            weightAllowed = permitsInventoryAddition(inventory, reward, 1);
            rewardAdded = weightAllowed && next.add(reward, 1);
            Map<Integer, Integer> quests = new LinkedHashMap<>(current.effective());
            quests.put(ClassicWorldRoiFollowers.QUEST_ID,
                    ClassicWorldRoiFollowers.QUEST_COMPLETE);
            state.saveEconomyStateAndStoryQuests(
                    stateCharacter(), shopPoints, next.catalogCounts(),
                    next.catalogItemStates(), quests);
            inventory = next;
        } catch (IOException | RuntimeException failure) {
            hub.classicWorldRoiFollowers().restoreAfterFailedCompletion(removed);
            throw failure;
        }
        if (rewardAdded) {
            sendInventoryDelta(previous, inventory);
        } else if (!weightAllowed) {
            sendInventoryWeightOver("Roi-quest-reward");
        } else {
            sendInventoryCapacityOver("Roi-quest-reward");
        }
        broadcastClassicWorldRoiReplacement(removed, null, "quest-complete");
        System.out.println("[LiTo] Roi quest complete player=" + playerName()
                + " quest=138 step=255 follower=" + removed.objectId()
                + " reward=41003 added=" + rewardAdded);
        return true;
    }

