    private int battleArmorClass(long nowNanos) {
        BattleSpellCatalog.WeaknessSpell disease =
                BattleSpellCatalog.weaknessSpell(BattleSpellCatalog.DISEASE);
        int diseaseArmorClass = timedStatus.diseaseActive(nowNanos)
                ? disease.armorClassModifier() : 0;
        long armorClass = (long) baseArmorClass()
                + activeMagicDollPowers().value("PASSIVE_AC")
                + abilityStatus.shield(nowNanos).amount()
                + earthBlessStatus.armorClass(nowNanos)
                + ironSkinStatus.armorClass(nowNanos)
                + guardBrakeStatus.armorClass(nowNanos)
                + abilityStatus.berserk(nowNanos).armorClass()
                + abilityStatus.bounceAttack(nowNanos).armorClass()
                + abilityStatus.royalAura(nowNanos).armorClass()
                + abilityStatus.diamondGolem(nowNanos).armorClass()
                + awakenStatus.snapshot().armorClassModifier()
                + cookingStatus.active(nowNanos).armorClass()
                + activeItemArmorEnchantModifier(nowNanos)
                + diseaseArmorClass
                + waterDragonBlessingArmorClass(nowNanos);
        return NumericBreakthrough.clampArmorClass(armorClass);
    }

    private int activeItemArmorEnchantModifier(long nowNanos) {
        int modifier = 0;
        for (RuntimeInventory.Item item : inventory.items()) {
            InventoryCatalog.NativeArmorStatus armor =
                    item.definition().sourceArmorStatus();
            if (!item.equipped() || armor == null || armor.armorType() != 2) continue;
            modifier += itemArmorEnchantStatus.modifier(
                    nowNanos, item.objectId()).armorClass();
        }
        return modifier;
    }

