    private BattleInventoryWeight.Profile rentalTownWeightProfile(
            RuntimeInventory candidate, long nowNanos) {
        if (candidate == null) {
            throw new IllegalArgumentException("candidate inventory is required");
        }
        CharacterSummary character = selectedCharacterSummary();
        RentalEquipmentBonuses bonuses =
                RentalEquipmentBonuses.from(candidate.items());
        int baseStrength = character == null ? 13
                : Math.max(1, character.strength());
        int baseConstitution = character == null ? 10
                : Math.max(1, character.constitution());
        int strength = NumericBreakthrough.clampAbility(
                Math.addExact(baseStrength, bonuses.strength()));
        int constitution = NumericBreakthrough.clampAbility(
                Math.addExact(baseConstitution, bonuses.constitution()));
        BattleWeightStatus.Snapshot weight = weightStatus.snapshot(nowNanos);
        return new BattleInventoryWeight.Profile(
                candidate.totalWeight(), 1.0,
                character == null ? 0 : character.type(),
                strength, constitution,
                character == null ? baseStrength
                        : Math.max(0, character.originalStrength()),
                character == null ? baseConstitution
                        : Math.max(0, character.originalConstitution()),
                bonuses.weightReduction(), 0,
                weight.decreaseWeightActive());
    }

    private BattleInventoryWeight.Profile weightProfile(
            RuntimeInventory candidate, long nowNanos, int strength) {
        if (candidate == null) {
            throw new IllegalArgumentException("candidate inventory is required");
        }
        CharacterSummary character = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        SourceInventoryWeightStats sourceWeight = requiredInventoryWeightStats();
        int sourceOnlyWeight = retainedSourceInventoryWeight < 0
                ? sourceWeight.rawWeight() : retainedSourceInventoryWeight;
        int rawWeight = BattleInventoryWeight.addWeight(
                sourceOnlyWeight, candidate.totalWeight());
        BattleWeightStatus.Snapshot weight = weightStatus.snapshot(nowNanos);
        int constitution = effectiveConstitution();
        return new BattleInventoryWeight.Profile(
                rawWeight, sourceWeight.serverWeightRate(),
                character == null ? 0 : character.type(), strength, constitution,
                character == null ? strength : Math.max(0, character.originalStrength()),
                character == null ? constitution
                        : Math.max(0, character.originalConstitution()),
                Math.addExact(equipment.totalWeightReduction(),
                        activeMagicDollPowers().value(
                                "PASSIVE_WEIGHT_REDUCTION")),
                0, weight.decreaseWeightActive());
    }

