    void serverCubeIgnitionExpired(
            long roomId, int mapId, int instanceId,
            BattleCubeIgnitionEffects.Cube cube) throws IOException {
        if (cube == null || !cubeIgnitionContextMatches(
                roomId, mapId, instanceId)) return;
        if (mapId >= 0 && !BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, cube.x(), cube.y())) return;
        sendEncrypted(Protocol.removeObject(cube.objectId()),
                "S_REMOVE_OBJECT Cube-Ignition=" + cube.objectId()
                        + " npc=" + BattleCubeIgnitionEffects.NPC_ID
                        + " gfx=" + BattleCubeIgnitionEffects.CUBE_GFX);
    }

    void serverCubeIgnitionStatus(
            long roomId, int mapId, int instanceId, ClientSession caster,
            BattleCubeIgnitionEffects.Event event) throws IOException {
        if (event == null || event.targetObjectId() != playerObjectId()
                || !cubeIgnitionContextMatches(roomId, mapId, instanceId)) return;
        boolean allyApplied = event.kind()
                == BattleCubeIgnitionEffects.EventKind.ALLY_APPLIED;
        boolean enemyApplied = event.kind()
                == BattleCubeIgnitionEffects.EventKind.ENEMY_APPLIED;
        if (allyApplied || enemyApplied) {
            int gfx = allyApplied ? BattleCubeIgnitionEffects.ALLY_GFX
                    : BattleCubeIgnitionEffects.ENEMY_GFX;
            byte[] effect = Protocol.effectObject(playerObjectId(), gfx);
            for (ClientSession recipient : cubeIgnitionRecipients(
                    roomId, mapId, instanceId)) {
                if (mapId >= 0 && !BattleSpellCatalog.isInNativeScreen(
                        recipient.positionX, recipient.positionY,
                        positionX, positionY)) continue;
                recipient.sendEncrypted(effect,
                        "S_EFFECT Cube-Ignition-"
                                + (allyApplied ? "ally" : "enemy")
                                + " target=" + playerObjectId()
                                + " caster=" + (caster == null ? 0
                                    : caster.playerObjectId())
                                + " gfx=" + gfx);
            }
        }
        if (allyApplied || event.kind()
                == BattleCubeIgnitionEffects.EventKind.ALLY_EXPIRED) {
            sendNativeBattleStatus(System.nanoTime(), allyApplied
                    ? "cube-ignition-ally-applied"
                    : "cube-ignition-ally-expired");
        }
        System.out.println("[LiTo] Cube: Ignition status=" + event.kind()
                + " target=" + playerName()
                + " caster=" + (caster == null ? "detached" : caster.playerName())
                + " object=" + event.cube().objectId()
                + " fire-bonus=" + effectiveCubeIgnitionFireResistance(
                        System.nanoTime()));
    }

    void serverCubeIgnitionDamage(
            long roomId, int mapId, int instanceId, ClientSession caster,
            BattleCubeIgnitionEffects.Event event) throws IOException {
        if (caster == null || event == null
                || event.targetObjectId() != playerObjectId()
                || playerHp <= 0 || !cubeIgnitionContextMatches(
                        roomId, mapId, instanceId)) return;
        long now = System.nanoTime();
        boolean protectedStatus = timedStatus.freezeActive(now)
                || timedStatus.absoluteBarrierActive(now)
                || timedStatus.earthBindActive(now);
        if (protectedStatus) {
            System.out.println("[LiTo] Cube: Ignition damage blocked target="
                    + playerName() + " object=" + event.cube().objectId()
                    + " freeze=" + timedStatus.freezeActive(now)
                    + " absolute-barrier="
                    + timedStatus.absoluteBarrierActive(now)
                    + " earth-bind=" + timedStatus.earthBindActive(now));
            return;
        }
        byte[] reaction = Protocol.objectAction(
                playerObjectId(), BattleActionCodes.DAMAGE);
        for (ClientSession recipient : cubeIgnitionRecipients(
                roomId, mapId, instanceId)) {
            if (mapId >= 0 && !BattleSpellCatalog.isInNativeScreen(
                    recipient.positionX, recipient.positionY,
                    positionX, positionY)) continue;
            recipient.sendEncrypted(reaction,
                    "S_ACTION Cube-Ignition damage target=" + playerObjectId()
                            + " caster=" + caster.playerObjectId());
        }
        takePlayerDamage(BattleCubeIgnitionEffects.ENEMY_DAMAGE, caster);
        System.out.println("[LiTo] Cube: Ignition damage target=" + playerName()
                + " caster=" + caster.playerName()
                + " damage=" + BattleCubeIgnitionEffects.ENEMY_DAMAGE
                + " object=" + event.cube().objectId());
    }

    void serverCubeIgnitionBotDamage(
            long roomId, BattleCubeIgnitionEffects.Event event)
            throws IOException {
        if (event == null || phase != Phase.BATTLE || currentRoomId != roomId
                || hub.botHp(roomId) <= 0) return;
        byte[] reaction = Protocol.objectAction(2, BattleActionCodes.DAMAGE);
        for (ClientSession member : hub.roomMembers(roomId)) {
            member.sendEncrypted(reaction,
                    "S_ACTION Cube-Ignition bot damage caster=" + playerObjectId());
        }
        int remaining = hub.damageBot(
                roomId, BattleCubeIgnitionEffects.ENEMY_DAMAGE);
        broadcastHitRatio(2, remaining, GameHub.ARENA_BOT_MAX_HP,
                remaining == 0 ? "cube-ignition-bot-death"
                        : "cube-ignition-bot-damage");
        if (remaining == 0) {
            byte[] death = Protocol.objectAction(2, BattleActionCodes.DIE);
            for (ClientSession member : hub.roomMembers(roomId)) {
                member.sendEncrypted(death, "S_ACTION Cube-Ignition bot death");
            }
            BattleRules.Resolution resolution = new BattleRules.Resolution(
                    true, false, Set.of(playerObjectId()), Set.of(),
                    "arena-bot-defeated-by-cube-ignition");
            for (ClientSession member : hub.roomMembers(roomId)) {
                member.serverEndBattle(resolution);
            }
            hub.endBattle(roomId);
        }
    }

    void serverCubeIgnitionMonsterDamage(
            long roomId, int mapId, int instanceId,
            BattleCubeIgnitionEffects.Event event) throws IOException {
        if (event == null || event.targetKind()
                != BattleCubeIgnitionEffects.ActorKind.MONSTER) return;
        long targetObjectId = event.targetObjectId();
        long now = System.nanoTime();
        if (mapId < 0) {
            BattleQuestEncounter.Snapshot quest = hub.questMonster(
                    roomId, targetObjectId);
            if (quest != null) {
                if (hub.questMonsterFreezeActive(roomId, targetObjectId, now)
                        || hub.questMonsterEarthBindActive(
                                roomId, targetObjectId, now)) return;
                applyQuestMonsterDamage(targetObjectId,
                        BattleCubeIgnitionEffects.ENEMY_DAMAGE,
                        "cube-ignition-" + BattleSpellCatalog.CUBE_IGNITION);
                return;
            }
            BattleTimeAttackEncounter.Snapshot time = hub.timeAttackActor(
                    roomId, targetObjectId);
            if (time != null) {
                if (hub.timeAttackActorFreezeActive(roomId, targetObjectId, now)
                        || hub.timeAttackActorEarthBindActive(
                                roomId, targetObjectId, now)) return;
                applyTimeAttackActorDamage(targetObjectId,
                        BattleCubeIgnitionEffects.ENEMY_DAMAGE,
                        "cube-ignition-" + BattleSpellCatalog.CUBE_IGNITION);
            }
            return;
        }
        if (!cubeIgnitionContextMatches(roomId, mapId, instanceId)
                || hub.classicWorldMonsterFreezeActive(
                        mapId, instanceId, targetObjectId, now)) return;
        ClassicWorldMonsterPopulation.Hit transition =
                hub.damageClassicWorldMonster(
                        mapId, instanceId, targetObjectId,
                        playerObjectId(), BattleCubeIgnitionEffects.ENEMY_DAMAGE);
        if (transition != null) {
            publishClassicWorldSpellMonsterDamage(
                    BattleSpellCatalog.CUBE_IGNITION, transition);
        }
    }

    private boolean cubeIgnitionContextMatches(
            long roomId, int mapId, int instanceId) {
        return mapId >= 0
                ? phase == Phase.WORLD && classicWorldMapId == mapId
                    && classicWorldInstanceId == instanceId
                : phase == Phase.BATTLE && currentRoomId == roomId;
    }

    private List<ClientSession> cubeIgnitionRecipients(
            long roomId, int mapId, int instanceId) {
        return mapId >= 0 ? hub.classicWorldMembers(mapId, instanceId)
                : hub.roomMembers(roomId);
    }

    private int effectiveCubeIgnitionFireResistance(long nowNanos) {
        if (phase == Phase.BATTLE) {
            return hub.cubeIgnitionFireResistance(
                    currentRoomId, this, nowNanos);
        }
        if (phase == Phase.WORLD) {
            return hub.classicWorldCubeIgnitionFireResistance(
                    classicWorldMapId, classicWorldInstanceId,
                    this, nowNanos);
        }
        return 0;
    }

