    void serverCubeQuakeBind(
            long roomId, int mapId, int instanceId,
            BattleCubeQuakeEffects.Event event) throws IOException {
        if (event == null || event.targetObjectId() != playerObjectId()
                || !cubeIgnitionContextMatches(roomId, mapId, instanceId)) return;
        if (event.kind() == BattleCubeQuakeEffects.EventKind.ENEMY_BIND_STARTED) {
            // Retained S_Paralysis.TYPE_BIND true -> selected LiTo mode 24.
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.BIND_APPLY),
                    "S_PARALYSE mode=24 Cube-Quake MOVE_STOP-start object="
                            + event.cube().objectId());
            return;
        }
        if (event.kind() != BattleCubeQuakeEffects.EventKind.ENEMY_BIND_EXPIRED) {
            return;
        }
        // MOVE_STOP.stop sends TYPE_BIND false first, then restores the current
        // poison palette. Direct L1Cube start deliberately sent no S_POISON.
        sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.BIND_RELEASE),
                "S_PARALYSE mode=25 Cube-Quake MOVE_STOP-expired object="
                        + event.cube().objectId());
        broadcastPoisonState(currentPoisonPalette(System.nanoTime()),
                "cube-quake-move-stop-expired");
    }

    void serverCubeQuakeNonPlayerBind(
            long roomId, int mapId, int instanceId,
            BattleCubeQuakeEffects.Event event) throws IOException {
        if (event == null || event.targetKind()
                == BattleCubeQuakeEffects.ActorKind.PLAYER) return;
        long targetObjectId = event.targetObjectId();
        if (event.kind() == BattleCubeQuakeEffects.EventKind.ENEMY_BIND_STARTED) {
            System.out.println("[LiTo] Cube: Quake NPC MOVE_STOP start target="
                    + targetObjectId + " kind=" + event.targetKind()
                    + " duration-ms=" + BattleCubeQuakeEffects.ENEMY_BIND_MILLIS);
            return;
        }
        if (event.kind() != BattleCubeQuakeEffects.EventKind.ENEMY_BIND_EXPIRED) {
            return;
        }
        int palette = 0;
        if (mapId >= 0) {
            palette = hub.classicWorldMonsterPoisonPalette(
                    mapId, instanceId, targetObjectId, System.nanoTime());
        } else if (event.targetKind() == BattleCubeQuakeEffects.ActorKind.MONSTER) {
            if (hub.questMonster(roomId, targetObjectId) != null) {
                palette = hub.questMonsterPoisonPalette(
                        roomId, targetObjectId, System.nanoTime());
            } else if (hub.timeAttackActor(roomId, targetObjectId) != null) {
                palette = hub.timeAttackActorPoisonPalette(
                        roomId, targetObjectId, System.nanoTime());
            }
        }
        byte[] clear = Protocol.poison(targetObjectId, palette);
        for (ClientSession recipient : cubeIgnitionRecipients(
                roomId, mapId, instanceId)) {
            recipient.sendEncrypted(clear,
                    "S_POISON Cube-Quake MOVE_STOP-expired target="
                            + targetObjectId + " type=" + palette);
        }
    }

    boolean cubeQuakeBindProtected(long nowNanos) {
        return timedStatus.freezeActive(nowNanos)
                || timedStatus.absoluteBarrierActive(nowNanos)
                || timedStatus.earthBindActive(nowNanos);
    }

