    void serverCubeHarmonyMpRecovery(
            long roomId, int mapId, int instanceId,
            BattleCubeHarmonyEffects.Event event) throws IOException {
        if (event == null || event.kind()
                != BattleCubeHarmonyEffects.EventKind.MP_RECOVERY
                || event.targetObjectId() != playerObjectId()
                || playerHp <= 0 || !cubeIgnitionContextMatches(
                        roomId, mapId, instanceId)) return;
        int previous;
        int current;
        synchronized (this) {
            previous = playerMp;
            playerMp = Math.min(playerMaxMp, Math.addExact(
                    playerMp, BattleCubeHarmonyEffects.MP_RECOVERY));
            current = playerMp;
        }
        if (current != previous) {
            sendEncrypted(Protocol.manaPoint(current, playerMaxMp),
                    "S_MANA_POINT Cube-Harmony-recovery=" + current + "/"
                            + playerMaxMp + " amount=" + (current - previous));
        }
        System.out.println("[LiTo] Cube: Harmony MP target=" + playerName()
                + " applied=" + (current - previous) + " mp=" + current
                + "/" + playerMaxMp + " object=" + event.cube().objectId());
    }

    void serverCubeHarmonyDamage(
            long roomId, int mapId, int instanceId, ClientSession caster,
            BattleCubeHarmonyEffects.Event event) throws IOException {
        if (event == null || event.kind()
                != BattleCubeHarmonyEffects.EventKind.HP_DAMAGE
                || event.targetObjectId() != playerObjectId()
                || playerHp <= 0 || !cubeIgnitionContextMatches(
                        roomId, mapId, instanceId)) return;
        int before = playerHp;
        if (mapId >= 0) {
            // The retained source is the effect NPC, not a direct PvP hit.
            takeClassicWorldMonsterDamage(
                    BattleCubeHarmonyEffects.HP_DAMAGE,
                    event.cube().objectId());
        } else {
            takePlayerDamage(BattleCubeHarmonyEffects.HP_DAMAGE,
                    caster, false, true);
        }
        System.out.println("[LiTo] Cube: Harmony HP target=" + playerName()
                + " caster=" + (caster == null ? "detached" : caster.playerName())
                + " source=" + BattleCubeHarmonyEffects.HP_DAMAGE
                + " applied=" + (before - playerHp)
                + " object=" + event.cube().objectId());
    }

    void serverCubeHarmonyNonPlayerMpRecovery(
            long roomId, int mapId, int instanceId,
            BattleCubeHarmonyEffects.Event event) {
        if (event == null || event.kind()
                != BattleCubeHarmonyEffects.EventKind.MP_RECOVERY
                || event.targetKind()
                    == BattleCubeHarmonyEffects.ActorKind.PLAYER) return;
        long targetObjectId = event.targetObjectId();
        int applied = 0;
        if (event.targetKind() == BattleCubeHarmonyEffects.ActorKind.MONSTER) {
            if (mapId >= 0) {
                applied = hub.recoverClassicWorldMonsterMana(
                        mapId, instanceId, targetObjectId,
                        BattleCubeHarmonyEffects.MP_RECOVERY);
            } else if (hub.questMonster(roomId, targetObjectId) != null) {
                applied = hub.recoverQuestMonsterMana(
                        roomId, this, targetObjectId,
                        BattleCubeHarmonyEffects.MP_RECOVERY);
            } else if (hub.timeAttackActor(roomId, targetObjectId) != null) {
                applied = hub.recoverTimeAttackActorMana(
                        roomId, this, targetObjectId,
                        BattleCubeHarmonyEffects.MP_RECOVERY);
            }
        }
        System.out.println("[LiTo] Cube: Harmony NPC-MP target=" + targetObjectId
                + " kind=" + event.targetKind() + " applied=" + applied
                + " object=" + event.cube().objectId());
    }

    void serverCubeHarmonyNonPlayerDamage(
            long roomId, int mapId, int instanceId,
            BattleCubeHarmonyEffects.Event event) throws IOException {
        if (event == null || event.kind()
                != BattleCubeHarmonyEffects.EventKind.HP_DAMAGE
                || event.targetKind()
                    == BattleCubeHarmonyEffects.ActorKind.PLAYER) return;
        long targetObjectId = event.targetObjectId();
        if (event.targetKind() == BattleCubeHarmonyEffects.ActorKind.BOT) {
            if (phase != Phase.BATTLE || currentRoomId != roomId
                    || hub.botHp(roomId) <= 0) return;
            int remaining = hub.damageBot(
                    roomId, BattleCubeHarmonyEffects.HP_DAMAGE);
            broadcastHitRatio(2, remaining, GameHub.ARENA_BOT_MAX_HP,
                    remaining == 0 ? "cube-harmony-bot-death"
                            : "cube-harmony-bot-damage");
            if (remaining == 0) {
                byte[] death = Protocol.objectAction(2, BattleActionCodes.DIE);
                for (ClientSession member : hub.roomMembers(roomId)) {
                    member.sendEncrypted(death, "S_ACTION Cube-Harmony bot death");
                }
                BattleRules.Resolution resolution = new BattleRules.Resolution(
                        true, false, Set.of(playerObjectId()), Set.of(),
                        "arena-bot-defeated-by-cube-harmony");
                for (ClientSession member : hub.roomMembers(roomId)) {
                    member.serverEndBattle(resolution);
                }
                hub.endBattle(roomId);
            }
            return;
        }
        if (mapId < 0) {
            if (hub.questMonster(roomId, targetObjectId) != null) {
                applyQuestMonsterDamage(targetObjectId,
                        BattleCubeHarmonyEffects.HP_DAMAGE,
                        "cube-harmony-" + BattleSpellCatalog.CUBE_HARMONY);
            } else if (hub.timeAttackActor(roomId, targetObjectId) != null) {
                applyTimeAttackActorDamage(targetObjectId,
                        BattleCubeHarmonyEffects.HP_DAMAGE,
                        "cube-harmony-" + BattleSpellCatalog.CUBE_HARMONY);
            }
            return;
        }
        if (!cubeIgnitionContextMatches(roomId, mapId, instanceId)) return;
        ClassicWorldMonsterPopulation.Hit transition =
                hub.damageClassicWorldMonster(
                        mapId, instanceId, targetObjectId,
                        playerObjectId(), BattleCubeHarmonyEffects.HP_DAMAGE);
        if (transition != null) {
            publishClassicWorldSpellMonsterDamage(
                    BattleSpellCatalog.CUBE_HARMONY, transition);
        }
    }

