    private synchronized boolean activateClassicWorldArmorBreak(
            long nowNanos, int durationSeconds) {
        if (phase != Phase.WORLD || observer || playerHp <= 0
                || nowNanos < 0 || durationSeconds <= 0) return false;
        classicWorldArmorBreakExpiresAtNanos = Math.addExact(
                nowNanos, TimeUnit.SECONDS.toNanos(durationSeconds));
        return true;
    }

    private synchronized boolean classicWorldArmorBreakActive(long nowNanos) {
        if (phase != Phase.WORLD || observer || playerHp <= 0 || nowNanos < 0) {
            classicWorldArmorBreakExpiresAtNanos = 0;
            return false;
        }
        if (classicWorldArmorBreakExpiresAtNanos != 0
                && nowNanos >= classicWorldArmorBreakExpiresAtNanos) {
            classicWorldArmorBreakExpiresAtNanos = 0;
        }
        return nowNanos < classicWorldArmorBreakExpiresAtNanos;
    }

    private synchronized boolean cancelClassicWorldArmorBreak() {
        boolean active = classicWorldArmorBreakExpiresAtNanos != 0;
        classicWorldArmorBreakExpiresAtNanos = 0;
        return active;
    }

    private int combatDamageAfterCooking(
            int damage, String source, boolean playerPhysicalAttacker,
            int attackerWeaponType, boolean applyReductionArmor,
            boolean physicalDamage) {
        long now = System.nanoTime();
        BattleCookingStatus.Snapshot cooking = cookingStatus.active(now);
        int reduction = cooking.damageReduction();
        int applied = damage;
        if (reduction != 0) {
            applied = BattleCookingCatalog.damageAfterReduction(damage, reduction);
            System.out.println("[LiTo] cooking damage reduction player=" + playerName()
                    + " statuses=" + cooking.recipes().stream()
                        .map(recipe -> Integer.toString(recipe.statusId())).toList()
                    + " source=" + source
                    + " raw=" + damage + " reduction=" + reduction
                    + " applied=" + applied);
        }
        BattleAbilityStatus.ReductionArmor reductionArmor =
                abilityStatus.reductionArmor(now);
        if (applyReductionArmor && reductionArmor.remainingSeconds() != 0) {
            BattleSpellCatalog.ReductionArmorSpell spell =
                    BattleSpellCatalog.reductionArmorSpell(
                            BattleSpellCatalog.REDUCTION_ARMOR);
            int reducedDamage = spell.applyTo(
                    applied, battleLevel(), playerPhysicalAttacker);
            System.out.println("[LiTo] Reduction Armor damage reduction player="
                    + playerName() + " source=" + source
                    + " before=" + applied
                    + " target-level=" + battleLevel()
                    + " player-physical-attacker=" + playerPhysicalAttacker
                    + " reduction=" + (applied - reducedDamage)
                    + " applied=" + reducedDamage);
            applied = reducedDamage;
        }
        boolean armorBreakActive = playerPhysicalAttacker
                && (phase == Phase.WORLD
                    ? classicWorldArmorBreakActive(now)
                    : currentRoomId != 0 && hub.armorBreakActive(
                            currentRoomId, playerObjectId(), now));
        int brokenDamage = BattleArmorBreak.damageAfterBreak(
                applied, armorBreakActive, attackerWeaponType);
        if (brokenDamage != applied) {
            System.out.println("[LiTo] Armor Break melee amplification player="
                    + playerName() + " source=" + source
                    + " before=" + applied
                    + " weapon-type=" + attackerWeaponType
                    + " percent=" + BattleArmorBreak.DAMAGE_PERCENT
                    + " applied=" + brokenDamage);
            applied = brokenDamage;
        }
        BattleDragonSkinStatus.Snapshot dragonSkin =
                dragonSkinStatus.snapshot(now);
        if (physicalDamage && dragonSkin.active()) {
            int reducedDamage = dragonSkin.applyTo(applied);
            System.out.println("[LiTo] Dragon Skin physical reduction player="
                    + playerName() + " source=" + source
                    + " before=" + applied
                    + " reduction=" + dragonSkin.damageReduction()
                    + " applied=" + reducedDamage);
            applied = reducedDamage;
        }
        int patienceReduction = physicalDamage
                ? effectivePatiencePhysicalReduction(now) : 0;
        if (patienceReduction != 0) {
            int reducedDamage = Math.max(0, applied - patienceReduction);
            System.out.println("[LiTo] Patience physical reduction player="
                    + playerName() + " source=" + source
                    + " before=" + applied
                    + " original-reduction=" + patienceReduction
                    + " applied=" + reducedDamage);
            applied = reducedDamage;
        }
        BattleAbilityStatus.Protection protection =
                abilityStatus.immuneToHarm(now);
        if (protection.divisor() != 0) {
            int protectedDamage = protection.applyTo(applied);
            System.out.println("[LiTo] Immune to Harm damage reduction player="
                    + playerName() + " source=" + source
                    + " before=" + applied + " divisor=" + protection.divisor()
                    + " applied=" + protectedDamage);
            applied = protectedDamage;
        }
        return applied;
    }

    /** NPC/Pet physical order: AC is upstream, then armor reduction, then cooking. */
    private int combatPhysicalDamageAfterArmorAndCooking(int damage, String source) {
        int reductionBase = effectiveArmorMagicReductionBase();
        int reductionRoll = reductionBase <= 10 ? 0
                : ThreadLocalRandom.current().nextInt(reductionBase - 10);
        int reduction = BattlePhysicalDefense.armorReduction(
                reductionBase, reductionRoll);
        int afterArmor = Math.max(0, damage - reduction);
        if (reduction != 0) {
            System.out.println("[LiTo] physical armor reduction player=" + playerName()
                    + " source=" + source + " raw=" + damage
                    + " reduction-base=" + reductionBase
                    + " reduction-roll=" + reductionRoll
                    + " reduction=" + reduction + " applied=" + afterArmor);
        }
        return combatDamageAfterCooking(
                afterArmor, source, false, 0, true, true);
    }

    private void broadcastPoisonState(int type, String reason) throws IOException {
        byte[] poison = Protocol.poison(playerObjectId(), type);
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (phase == Phase.WORLD && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) continue;
            member.sendEncrypted(poison, "S_POISON object=" + playerObjectId()
                    + " type=" + type + " reason=" + reason);
        }
    }

    private int fireWallDamage() {
        CharacterSummary character = selectedCharacterSummary();
        int intelligence = character == null ? 8 : Math.max(1, character.intelligence());
        return 19 + ThreadLocalRandom.current().nextInt(Math.max(intelligence / 2, 1));
    }

    private int effectiveFireResistance() {
        return effectiveFireResistance(System.nanoTime());
    }

    private int effectiveFireResistance(long nowNanos) {
        int total = requiredEquipmentMagicStats().totalFireResistance()
                + activeMagicDollPowers().value("PASSIVE_DEF_FIRE")
                + inventory.activeFireResistance()
                + cookingStatus.active(nowNanos).allElementResistance()
                + awakenStatus.snapshot().allElementalResistance()
                + resistElementalStatus.modifier(nowNanos)
                + elementalProtectionStatus.modifier(
                        BattleSpellCatalog.ATTRIBUTE_FIRE, nowNanos)
                + elementalFallDownStatus.modifier(
                        BattleSpellCatalog.ATTRIBUTE_FIRE, nowNanos)
                + effectiveCubeIgnitionFireResistance(nowNanos);
        return NumericBreakthrough.clampElementalResistance(total);
    }

    private int effectiveSpellElementalResistance(int attributeKind) {
        return effectiveSpellElementalResistance(attributeKind, System.nanoTime());
    }

    private int effectiveSpellElementalResistance(
            int attributeKind, long nowNanos) {
        if (attributeKind == BattleSpellCatalog.ATTRIBUTE_FIRE) {
            return effectiveFireResistance(nowNanos);
        }
        if (attributeKind != 1 && attributeKind != 4 && attributeKind != 8) return 0;
        int equipment = requiredEquipmentMagicStats().physical()
                .elemental().resistance(attributeKind);
        int total = equipment
                + activeMagicDollPowers().value(switch (attributeKind) {
                    case 1 -> "PASSIVE_DEF_EARTH";
                    case 4 -> "PASSIVE_DEF_WATER";
                    case 8 -> "PASSIVE_DEF_WIND";
                    default -> "";
                })
                + cookingStatus.active(nowNanos).allElementResistance()
                + awakenStatus.snapshot().allElementalResistance()
                + resistElementalStatus.modifier(nowNanos)
                + elementalProtectionStatus.modifier(attributeKind, nowNanos)
                + elementalFallDownStatus.modifier(attributeKind, nowNanos);
        if (attributeKind == BattleSpellCatalog.ATTRIBUTE_WATER) {
            total += waterDragonBlessingWaterResistance(nowNanos);
        }
        if (attributeKind == BattleSpellCatalog.ATTRIBUTE_EARTH) {
            total += effectiveCubeQuakeEarthResistance(nowNanos);
        }
        if (attributeKind == BattleSpellCatalog.ATTRIBUTE_WIND) {
            total += effectiveCubeShockWindResistance(nowNanos);
        }
        return NumericBreakthrough.clampElementalResistance(total);
    }

    private int effectiveWeaponAttributeResistance(int attributeKind) {
        if (attributeKind == 0) return 0;
        if (attributeKind == 2) return effectiveFireResistance();
        // The selected retained attribute-resource path maps its four extended
        // kinds to MR; classic earth/fire/water/wind remain elemental defense.
        if (attributeKind == 16 || attributeKind == 32
                || attributeKind == 64 || attributeKind == 128) {
            return effectiveBaseMagicResistance();
        }
        int equipment = requiredEquipmentMagicStats().physical()
                .elemental().resistance(attributeKind);
        long now = System.nanoTime();
        int total = equipment
                + activeMagicDollPowers().value(switch (attributeKind) {
                    case 1 -> "PASSIVE_DEF_EARTH";
                    case 4 -> "PASSIVE_DEF_WATER";
                    case 8 -> "PASSIVE_DEF_WIND";
                    default -> "";
                })
                + cookingStatus.active(now).allElementResistance()
                + awakenStatus.snapshot().allElementalResistance()
                + resistElementalStatus.modifier(now)
                + elementalProtectionStatus.modifier(attributeKind, now)
                + elementalFallDownStatus.modifier(attributeKind, now);
        if (attributeKind == BattleSpellCatalog.ATTRIBUTE_WATER) {
            total += waterDragonBlessingWaterResistance(now);
        }
        if (attributeKind == BattleSpellCatalog.ATTRIBUTE_EARTH) {
            total += effectiveCubeQuakeEarthResistance(now);
        }
        if (attributeKind == BattleSpellCatalog.ATTRIBUTE_WIND) {
            total += effectiveCubeShockWindResistance(now);
        }
        return NumericBreakthrough.clampElementalResistance(total);
    }

    private int effectiveWisdom(long nowNanos) {
        CharacterSummary character = selectedCharacterSummary();
        int baseWisdom = character == null ? 1 : character.wisdom();
        int equipmentWisdom = requiredEquipmentMagicStats()
                .effectiveMprWisdom(baseWisdom);
        int clearMind = clearMindStatus.snapshot(nowNanos).wisdomModifier();
        return NumericBreakthrough.clampAbility((long) equipmentWisdom + clearMind
                + activeMagicDollPowers().value("PASSIVE_WIS")
                + awakenStatus.snapshot().allAbilityScoreBonus()
                + abilityStatus.insight(nowNanos).abilityScoreModifier()
                + abilityStatus.panic(nowNanos).abilityScoreModifier());
    }

    private int effectiveBaseMagicResistance() {
        return effectiveBaseMagicResistance(System.nanoTime());
    }

    private int effectiveBaseMagicResistance(long nowNanos) {
        if (sourceBaseMagicResistance == null) {
            throw new IllegalStateException(
                    "selected character has no qualified source base-MR snapshot");
        }
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveWisdom = effectiveWisdom(nowNanos);
        int base = sourceBaseMagicResistance.classBase()
                + sourceBaseMagicResistance.levelBonus()
                + sourceBaseMagicResistance.originalBonus()
                + BattleMagicResistance.wisdomMagicResistance(effectiveWisdom);
        int normal = Math.max(0, base + equipment.totalDirectMagicResistance()
                + activeMagicDollPowers().value("PASSIVE_MR")
                + magicResistanceModifier(nowNanos));
        return eraseMagicStatus.effectiveMagicResistance(normal, nowNanos);
    }

    private int effectiveArmorMagicReductionBase() {
        return Math.addExact(requiredEquipmentMagicStats().armorReductionBase(),
                Math.addExact(
                        dragonEyeStatus.snapshot(System.nanoTime()).damageReduction(),
                        activeMagicDollPowers().value("PASSIVE_DMG_REDUX")));
    }

    private NativeMagicDollPowers activeMagicDollPowers() {
        synchronized (activeMagicDollObjectIds) {
            return activeMagicDoll == null
                    ? NativeMagicDollPowers.empty()
                    : NativeMagicDollPowers.from(activeMagicDoll.type());
        }
    }

    private boolean activeMagicDollUnderwaterBreath() {
        return activeMagicDollPowers().value("STATUS_UNDERWATER") > 0;
    }

    private int nativeMagicDollDamageAfterActiveReduction(
            int incomingDamage, boolean publishEffect, String source)
            throws IOException {
        if (incomingDamage <= 0) return 0;
        NativeMagicDollEffects.DefenseProc proc = NativeMagicDollEffects.defense(
                activeMagicDollPowers(),
                () -> ThreadLocalRandom.current().nextInt(1000));
        if (proc.damageReduction() <= 0) return incomingDamage;
        if (publishEffect) {
            for (SourceMagicDollPower trigger : proc.triggers()) {
                publishNativeMagicDollProcVisual(
                        trigger, playerObjectId(), true, source + "-defense");
            }
        }
        int applied = Math.max(0, incomingDamage - proc.damageReduction());
        System.out.println("[LiTo] magic-doll defense proc player=" + playerName()
                + " source=" + source + " incoming=" + incomingDamage
                + " reduction=" + proc.damageReduction() + " applied=" + applied
                + " powers=" + proc.triggers().stream()
                        .map(SourceMagicDollPower::id).toList());
        return applied;
    }

    private void applyNativeMagicDollAttackProcs(
            NativeMagicDollEffects.AttackProc proc, long targetObjectId,
            ClientSession playerTarget,
            BattleQuestEncounter.Snapshot questTarget,
            BattleTimeAttackEncounter.Snapshot timeTarget,
            SourceNpcPhysicalStats npcPhysical) throws IOException {
        if (proc == null || !proc.triggered()) return;
        for (SourceMagicDollPower trigger : proc.damageTriggers()) {
            publishNativeMagicDollProcVisual(
                    trigger, targetObjectId, false, "attack-damage");
        }
        if (proc.additionalDamage() > 0) {
            commitNativeMagicDollProcDamage(proc.additionalDamage(), targetObjectId,
                    playerTarget, questTarget, timeTarget, "active-damage");
        }
        for (SourceMagicDollPower trigger : proc.skillTriggers()) {
            int skillDamage = nativeMagicDollTriggeredSkillDamage(
                    trigger, playerTarget, npcPhysical);
            publishNativeMagicDollProcVisual(
                    trigger, targetObjectId, false, "attack-skill");
            BattleSpellCatalog.AreaAttackSpell spell =
                    BattleSpellCatalog.areaAttackSpell(trigger.triggerSkillId());
            if (spell != null) {
                byte[] effect = Protocol.effectObject(targetObjectId, spell.effectGfx());
                NativeMagicDoll doll;
                synchronized (activeMagicDollObjectIds) {
                    doll = activeMagicDoll;
                }
                if (doll != null) {
                    for (ClientSession viewer : nativeMagicDollRecipients(doll)) {
                        viewer.sendEncrypted(effect,
                                "S_EFFECT magic-doll-skill=" + trigger.id()
                                        + " skill=" + trigger.triggerSkillId()
                                        + " target=" + targetObjectId
                                        + " gfx=" + spell.effectGfx());
                    }
                }
            }
            if (skillDamage > 0) {
                commitNativeMagicDollProcDamage(skillDamage, targetObjectId,
                        playerTarget, questTarget, timeTarget,
                        "active-skill-" + trigger.triggerSkillId());
            }
        }
        System.out.println("[LiTo] magic-doll attack proc player=" + playerName()
                + " target=" + targetObjectId + " direct="
                + proc.additionalDamage() + " damage-powers="
                + proc.damageTriggers().stream().map(SourceMagicDollPower::id).toList()
                + " skill-powers=" + proc.skillTriggers().stream()
                        .map(SourceMagicDollPower::id).toList());
    }

    /**
     * Retained DollActiveProc applies its mode-1 damage/skill follow-up only
     * after the ordinary physical hit has been committed.  WORLD monsters use
     * a different canonical population ledger from Tournament actors, so this
     * adapter preserves that ordering while retaining the normal hate, HP,
     * death, reward and corpse lifecycle path.
     */
    private void applyNativeMagicDollClassicWorldAttackProcs(
            NativeMagicDollEffects.AttackProc proc,
            ClassicWorldMonsterPopulation.Snapshot target,
            SourceNpcPhysicalStats npcPhysical) throws IOException {
        if (proc == null || !proc.triggered() || target == null) return;
        for (SourceMagicDollPower trigger : proc.damageTriggers()) {
            publishNativeMagicDollProcVisual(
                    trigger, target.objectId(), false,
                    "classic-world-attack-damage");
        }
        if (proc.additionalDamage() > 0) {
            commitNativeMagicDollClassicWorldProcDamage(
                    target.objectId(), proc.additionalDamage(),
                    "active-damage");
        }
        for (SourceMagicDollPower trigger : proc.skillTriggers()) {
            int skillDamage = nativeMagicDollTriggeredSkillDamage(
                    trigger, null, npcPhysical);
            publishNativeMagicDollProcVisual(
                    trigger, target.objectId(), false,
                    "classic-world-attack-skill");
            BattleSpellCatalog.AreaAttackSpell spell =
                    BattleSpellCatalog.areaAttackSpell(trigger.triggerSkillId());
            if (spell != null) {
                byte[] effect = Protocol.effectObject(
                        target.objectId(), spell.effectGfx());
                NativeMagicDoll doll;
                synchronized (activeMagicDollObjectIds) {
                    doll = activeMagicDoll;
                }
                if (doll != null) {
                    for (ClientSession viewer : nativeMagicDollRecipients(doll)) {
                        viewer.sendEncrypted(effect,
                                "S_EFFECT classic-world magic-doll-skill="
                                        + trigger.id() + " skill="
                                        + trigger.triggerSkillId() + " target="
                                        + target.objectId() + " gfx="
                                        + spell.effectGfx());
                    }
                }
            }
            if (skillDamage > 0) {
                commitNativeMagicDollClassicWorldProcDamage(
                        target.objectId(), skillDamage,
                        "active-skill-" + trigger.triggerSkillId());
            }
        }
        System.out.println("[LiTo] classic-world magic-doll attack proc player="
                + playerName() + " target=" + target.objectId() + " direct="
                + proc.additionalDamage() + " damage-powers="
                + proc.damageTriggers().stream()
                        .map(SourceMagicDollPower::id).toList()
                + " skill-powers=" + proc.skillTriggers().stream()
                        .map(SourceMagicDollPower::id).toList());
    }

    private void commitNativeMagicDollClassicWorldProcDamage(
            long targetObjectId, int damage, String source) throws IOException {
        if (damage <= 0 || phase != Phase.WORLD) return;
        ClassicWorldMonsterPopulation.Snapshot current =
                hub.classicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        targetObjectId);
        if (current == null || !current.present() || !current.alive()) return;
        ClassicWorldMonsterPopulation.Hit transition =
                hub.damageClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        targetObjectId, playerObjectId(), damage);
        if (transition == null) return;
        hub.provokeClassicWorldMonster(
                classicWorldMapId, classicWorldInstanceId,
                targetObjectId, playerObjectId());
        ClassicWorldMonsterPopulation.Snapshot after = transition.after();
        byte[] ratio = Protocol.hitRatio(
                after.objectId(), after.currentHp(), after.maximumHp());
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            after.x(), after.y())) continue;
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO classic-world-monster=" + after.objectId()
                            + " hp=" + after.currentHp() + "/"
                            + after.maximumHp() + " source=magic-doll-"
                            + source);
            if (transition.diedNow()) {
                member.sendEncrypted(Protocol.objectAction(
                                after.objectId(), BattleActionCodes.DIE),
                        "S_ACTION classic-world-monster=" + after.objectId()
                                + " action=" + BattleActionCodes.DIE
                                + " source=magic-doll-" + source);
            }
        }
        System.out.println("[LiTo] classic-world magic-doll damaged monster player="
                + playerName() + " source=" + source + " object="
                + after.objectId() + " npc=" + after.npcId() + " damage="
                + transition.appliedDamage() + " hp=" + after.currentHp() + "/"
                + after.maximumHp() + " died=" + transition.diedNow());
        if (transition.diedNow()) {
            handleClassicWorldWaterDragonDeath(
                    after, transition.contributions());
            distributeClassicWorldMonsterRewards(
                    after, transition.contributions());
            hub.scheduleClassicWorldMonsterLifecycle(
                    classicWorldInstanceId, after);
        }
    }

    private int nativeMagicDollTriggeredSkillDamage(
            SourceMagicDollPower trigger, ClientSession playerTarget,
            SourceNpcPhysicalStats npcPhysical) {
        BattleSpellCatalog.AreaAttackSpell spell =
                BattleSpellCatalog.areaAttackSpell(trigger.triggerSkillId());
        if (spell == null) {
            System.out.println("[LiTo] magic-doll ACTIVE_SKILL rejected unsupported skill="
                    + trigger.triggerSkillId() + " power=" + trigger.id());
            return 0;
        }
        int sourceDamage = rollAreaSpellSourceDamage(spell);
        int elementalResistance = playerTarget == null ? 0
                : playerTarget.effectiveSpellElementalResistance(spell.attribute());
        int magicResistance = playerTarget != null
                ? playerTarget.effectiveBaseMagicResistance()
                : npcPhysical == null ? 0 : npcPhysical.magicResistance();
        int armorReduction = playerTarget != null
                ? playerTarget.effectiveArmorMagicReductionBase()
                : npcPhysical == null ? 0 : npcPhysical.damageReduction();
        return ordinaryMagicDamage(spell.skillId(), spell.attribute(), sourceDamage,
                elementalResistance, magicResistance, armorReduction,
                "magic-doll-proc");
    }

    private void commitNativeMagicDollProcDamage(
            int damage, long targetObjectId, ClientSession playerTarget,
            BattleQuestEncounter.Snapshot questTarget,
            BattleTimeAttackEncounter.Snapshot timeTarget, String source)
            throws IOException {
        if (damage <= 0) return;
        if (playerTarget != null) {
            if (playerTarget.phase == Phase.WORLD) {
                playerTarget.takeClassicWorldPlayerDamage(
                        damage, this, false, true);
            } else {
                playerTarget.takePlayerDamage(damage, this, false, true);
            }
        } else if (questTarget != null) {
            applyQuestMonsterDamage(targetObjectId, damage,
                    "magic-doll-" + source);
        } else if (timeTarget != null) {
            applyTimeAttackActorDamage(targetObjectId, damage,
                    "magic-doll-" + source);
        }
    }

    private void publishNativeMagicDollProcVisual(
            SourceMagicDollPower power, long targetObjectId,
            boolean defense, String reason) throws IOException {
        NativeMagicDoll doll;
        synchronized (activeMagicDollObjectIds) {
            doll = activeMagicDoll;
        }
        if (doll == null) return;
        byte[] packet;
        String wire;
        if (power.gfxId() > 0) {
            packet = Protocol.effectObject(targetObjectId, power.gfxId());
            wire = "S_EFFECT magic-doll-proc=" + power.id()
                    + " target=" + targetObjectId + " gfx=" + power.gfxId();
        } else {
            packet = Protocol.objectAction(doll.objectId(), 67);
            wire = "S_ACTION magic-doll-proc=" + power.id()
                    + " doll=" + doll.objectId() + " action=67";
        }
        for (ClientSession viewer : nativeMagicDollRecipients(doll)) {
            viewer.sendEncrypted(packet, wire + " defense=" + defense
                    + " reason=" + reason);
        }
    }

