    void completeAuthenticatedEndpointTransfer() {
        boolean rentalTransfer = rentalTownTransferPending
                && pendingRentalTeleportEndpoint != null;
        boolean channelTransfer = channelPortTransferPending;
        transferStoneProbeHandoffPending = false;
        rentalTownTransferPending = false;
        channelPortTransferPending = false;
        pendingRentalTeleportEndpoint = null;
        System.out.println("[LiTo] "
                + (rentalTransfer ? "rental-town"
                        : channelTransfer ? "channel-port" : "transfer-stone")
                + " new endpoint claimed account=" + mask(account));
        forceDisconnect(rentalTransfer ? "rental-town-new-endpoint-claimed"
                : channelTransfer ? "channel-port-new-endpoint-claimed"
                : "transfer-stone-probe-new-endpoint-claimed");
    }

