    int battleGfx() {
        long now = System.nanoTime();
        if (petRaceBaseGfx != 0) {
            if (petRaceTemporaryGfx != 0
                    && now < petRaceTemporaryDeadlineNanos) {
                return petRaceTemporaryGfx;
            }
            // Leave an expired temporary lease present until the scheduled
            // status tick broadcasts the authoritative return-to-base packet.
            // A concurrent world rebuild may render the base immediately,
            // but must not consume that pending broadcast for other clients.
            return petRaceBaseGfx;
        }
        if (desireQuestPolymorphGfx != 0) {
            if (now < desireQuestPolymorphDeadlineNanos) {
                return desireQuestPolymorphGfx;
            }
            desireQuestPolymorphGfx = 0;
            desireQuestPolymorphDeadlineNanos = 0;
        }
        BattlePolymorphCatalog.Form polymorph = polymorphStatus.active(now);
        if (polymorph != null) return polymorph.gfx();
        BattleAwakenStatus.Snapshot awakening = awakenStatus.snapshot();
        if (awakening.active()) return awakening.dragonGfx();
        return baseBattleGfx();
    }

    private int baseBattleGfx() {
        CharacterSummary character = characters.stream()
                .filter(candidate -> candidate.name().equalsIgnoreCase(playerName()))
                .findFirst()
                .orElse(characters.isEmpty() ? null : characters.get(0));
        if (character == null) return 61;
        // The persisted Type/Sex pair selects the original base sprite.  In
        // particular, claw and edoryu actions do not exist on knight gfx 61;
        // dark elves must retain native gfx 2786/2796.
        return BattleClassGfx.forCharacter(character.type(), character.sex());
    }

